          std::uint16_t* const destination) noexcept -> cudaError_t {
    return static_cast<cudaError_t>(
        q3x::kernels::launch_sm87_nvfp4_w4a16_m18_gemm_bf16_cuda(
            packed, scales, scale_2, activations, rows, columns,
            destination));
