using NvFp4Launcher = int (*)(const std::uint8_t*, const std::uint8_t*, float,
                              const std::uint16_t*, std::size_t, std::size_t,
                              std::uint16_t*, void*) noexcept;
using Fp8Launcher = int (*)(const std::uint8_t*, float,
                            const std::uint16_t*, std::size_t, std::size_t,
                            std::uint16_t*, void*) noexcept;

[[nodiscard]] float measure_fp8_launcher(
    TestContext& test, cudaStream_t stream, Fp8Launcher launcher,
    const std::uint8_t* weights, const float weight_scale,
    const std::uint16_t* activation, const std::size_t rows,
    const std::size_t columns, std::uint16_t* output, const int iterations,
    const std::string& label) {
  EventPair events;
  bool ready = events.create(test);
  ready = ready && test.cuda_ok(cudaEventRecord(events.start(), stream),
                                label + " record start");
  for (int iteration = 0; iteration < iterations && ready; ++iteration) {
    ready = test.cuda_ok(
        static_cast<cudaError_t>(launcher(
            weights, weight_scale, activation, rows, columns, output,
            static_cast<void*>(stream))),
        label + " launch");
  }
  ready = ready && test.cuda_ok(cudaEventRecord(events.stop(), stream),
                                label + " record stop");
  ready = ready && test.cuda_ok(cudaEventSynchronize(events.stop()),
                                label + " event synchronize");
  float total_milliseconds = std::numeric_limits<float>::quiet_NaN();
  ready = ready && test.cuda_ok(
                       cudaEventElapsedTime(&total_milliseconds,
                                            events.start(), events.stop()),
                       label + " elapsed time");
  if (!ready) {
    return std::numeric_limits<float>::quiet_NaN();
  }
  return total_milliseconds / static_cast<float>(iterations);
}

[[nodiscard]] float measure_nvfp4_launcher(
    TestContext& test, cudaStream_t stream, NvFp4Launcher launcher,
    const std::uint8_t* packed, const std::uint8_t* scales,
    const float weight_scale_2, const std::uint16_t* activation,
    const std::size_t rows, const std::size_t columns,
    std::uint16_t* output, const int iterations, const std::string& label) {
  EventPair events;
  bool ready = events.create(test);
  ready = ready && test.cuda_ok(cudaEventRecord(events.start(), stream),
                                label + " record start");
  for (int iteration = 0; iteration < iterations && ready; ++iteration) {
    ready = test.cuda_ok(
        static_cast<cudaError_t>(launcher(
            packed, scales, weight_scale_2, activation, rows, columns, output,
            static_cast<void*>(stream))),
        label + " launch");
  }
  ready = ready && test.cuda_ok(cudaEventRecord(events.stop(), stream),
                                label + " record stop");
  ready = ready && test.cuda_ok(cudaEventSynchronize(events.stop()),
                                label + " event synchronize");
  float total_milliseconds = std::numeric_limits<float>::quiet_NaN();
  ready = ready && test.cuda_ok(
                       cudaEventElapsedTime(&total_milliseconds,
                                            events.start(), events.stop()),
                       label + " elapsed time");
  if (!ready) {
    return std::numeric_limits<float>::quiet_NaN();
  }
  return total_milliseconds / static_cast<float>(iterations);
}

template <typename LaunchTile>
[[nodiscard]] float measure_small_m_tile(
    TestContext& test, cudaStream_t stream, LaunchTile&& launch_tile,
    const int iterations, const std::string& label) {
  EventPair events;
  bool ready = events.create(test);
  ready = ready && test.cuda_ok(cudaEventRecord(events.start(), stream),
                                label + " record start");
  for (int iteration = 0; iteration < iterations && ready; ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_tile()),
                         label + " launch tile");
  }
  ready = ready && test.cuda_ok(cudaEventRecord(events.stop(), stream),
                                label + " record stop");
  ready = ready && test.cuda_ok(cudaEventSynchronize(events.stop()),
                                label + " event synchronize");
  float total_milliseconds = std::numeric_limits<float>::quiet_NaN();
  ready = ready && test.cuda_ok(
                       cudaEventElapsedTime(&total_milliseconds,
                                            events.start(), events.stop()),
                       label + " elapsed time");
  if (!ready) {
    return std::numeric_limits<float>::quiet_NaN();
  }
  return total_milliseconds / static_cast<float>(iterations);
}

struct SmallMMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float batched_milliseconds = std::numeric_limits<float>::quiet_NaN();
};

[[nodiscard]] SmallMMeasurement report_small_m_performance(
    TestContext& test, const std::string& label,
    const std::size_t token_count, const float required_speedup,
    const float baseline_first, const float batched_first,
    const float batched_second, const float baseline_second) {
  if (!(std::isfinite(baseline_first) && std::isfinite(baseline_second) &&
        std::isfinite(batched_first) && std::isfinite(batched_second))) {
    return {};
  }
  const float baseline_average =
      (baseline_first + baseline_second) * 0.5F;
  const float batched_average = (batched_first + batched_second) * 0.5F;
  const float speedup = baseline_average / batched_average;
  const bool gate_passed = speedup >= required_speedup;
  std::cout << "PERF_SMALL_M: " << label << " M=" << token_count
            << " baseline_mx_m1_ms=" << baseline_average
            << " batched_ms=" << batched_average
            << " speedup=" << speedup
            << " required_speedup=" << required_speedup
            << " gate=" << (gate_passed ? "PASS" : "FAIL") << '\n';
  test.expect(gate_passed, label + " small-M per-shape gate must pass");
  return {baseline_average, batched_average};
}

constexpr std::array<std::size_t, 6U> kFp8M1GridCaps{{
    96U, 192U, 384U, 768U, 1'024U, 2'048U,
}};

struct Fp8M1GridCapMeasurements {
  std::array<float, kFp8M1GridCaps.size()> baseline_milliseconds{};
  std::array<float, kFp8M1GridCaps.size()> candidate_milliseconds{};
  std::array<bool, kFp8M1GridCaps.size()> bitwise_equal{};
};

[[nodiscard]] Fp8M1GridCapMeasurements benchmark_fp8_m1_grid_cap_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 40;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};
  Fp8M1GridCapMeasurements measurements;
  measurements.baseline_milliseconds.fill(
      std::numeric_limits<float>::quiet_NaN());
  measurements.candidate_milliseconds.fill(
      std::numeric_limits<float>::quiet_NaN());

  std::vector<std::uint8_t> host_weights(rows * columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] =
        kFiniteCodes[(index * 7U + index / columns * 5U + 1U) %
                     kFiniteCodes.size()];
  }
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered = static_cast<int>((column * 13U + 3U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed finite weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed activation");
  if (!ready) {
    return measurements;
  }

  const auto launch_baseline = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_gemv_bf16_vector_uncapped_test_cuda(
            weights.get(), kWeightScale, activation.get(), rows, columns,
            baseline_output.get(), static_cast<void*>(stream));
  };
  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " correctness baseline launch");
  std::vector<std::uint16_t> baseline(rows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy correctness baseline");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " baseline synchronize");
  if (!ready) {
    return measurements;
  }

  for (std::size_t cap_index = 0U; cap_index < kFp8M1GridCaps.size();
       ++cap_index) {
    const std::size_t grid_cap = kFp8M1GridCaps[cap_index];
    const auto launch_candidate = [&]() noexcept -> int {
      return q3x::kernels::launch_sm87_fp8_w8a16_gemv_bf16_grid_cap_test_cuda(
          weights.get(), kWeightScale, activation.get(), rows, columns,
          candidate_output.get(), grid_cap, static_cast<void*>(stream));
    };
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_candidate()),
                         label + " correctness candidate launch cap=" +
                             std::to_string(grid_cap));
    std::vector<std::uint16_t> candidate(rows);
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy correctness candidate cap=" +
                             std::to_string(grid_cap));
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         label + " correctness synchronize cap=" +
                             std::to_string(grid_cap));
    if (!ready) {
      return measurements;
    }
    std::size_t mismatches = 0U;
    for (std::size_t index = 0U; index < baseline.size(); ++index) {
      mismatches += baseline[index] != candidate[index] ? 1U : 0U;
    }
    measurements.bitwise_equal[cap_index] = mismatches == 0U;
    std::cout << "FP8_M1_GRID_CAP_DIFF: " << label
              << " grid_cap=" << grid_cap
              << " candidate_vs_uncapped_bf16=" << mismatches << '/'
              << baseline.size() << '\n';
    test.expect(mismatches == 0U,
                label + " cap=" + std::to_string(grid_cap) +
                    " matches every uncapped BF16 bit");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           label + " candidate warmup cap=" +
                               std::to_string(grid_cap));
    }
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         label + " warmup synchronize cap=" +
                             std::to_string(grid_cap));
    if (!ready) {
      return measurements;
    }

    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 1 cap=" + std::to_string(grid_cap));
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 1 cap=" + std::to_string(grid_cap));
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 2 cap=" + std::to_string(grid_cap));
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 2 cap=" + std::to_string(grid_cap));
    if (!(std::isfinite(baseline_first) &&
          std::isfinite(baseline_second) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second))) {
      return measurements;
    }
    const float baseline_average =
        (baseline_first + baseline_second) * 0.5F;
    const float candidate_average =
        (candidate_first + candidate_second) * 0.5F;
    measurements.baseline_milliseconds[cap_index] = baseline_average;
    measurements.candidate_milliseconds[cap_index] = candidate_average;
    const float speedup = baseline_average / candidate_average;
    std::cout << "PERF_FP8_M1_GRID_CAP: " << label
              << " grid_cap=" << grid_cap
              << " baseline_pass1_ms=" << baseline_first
              << " candidate_pass1_ms=" << candidate_first
              << " candidate_pass2_ms=" << candidate_second
              << " baseline_pass2_ms=" << baseline_second
              << " baseline_average_ms=" << baseline_average
              << " candidate_average_ms=" << candidate_average
              << " speedup=" << speedup
              << " uplift_percent=" << (speedup - 1.0F) * 100.0F << '\n';
  }
  return measurements;
}

void run_fp8_m1_large_row_grid_stride_coverage(
    TestContext& test, cudaStream_t stream, const std::size_t grid_cap) {
  constexpr std::size_t kRows = 65'537U;
  constexpr std::size_t kColumns = 1'024U;
  constexpr float kWeightScale = 1.0F / 64.0F;
  const std::string label = "FP8 M1 grid-cap >65535-row coverage";
  std::vector<std::uint16_t> host_activation(
      kColumns, encode_bf16(1.0F / 256.0F));
  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(kRows * kColumns),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activation.allocate(kColumns),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(kRows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kRows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(weights.get(), 0x38, kRows * kColumns,
                                       stream),
                       label + " initialize weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  if (!ready) {
    return;
  }
  ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          launch_sm87_fp8_w8a16_gemv_bf16_vector_uncapped_test_cuda(
              weights.get(), kWeightScale, activation.get(), kRows, kColumns,
              baseline_output.get(), static_cast<void*>(stream))),
      label + " launch uncapped baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           launch_sm87_fp8_w8a16_gemv_bf16_grid_cap_test_cuda(
                               weights.get(), kWeightScale, activation.get(),
                               kRows, kColumns, candidate_output.get(), grid_cap,
                               static_cast<void*>(stream))),
                       label + " launch capped candidate");
  std::vector<std::uint16_t> baseline(kRows);
  std::vector<std::uint16_t> candidate(kRows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize");
  if (!ready) {
    return;
  }
  std::size_t mismatches = 0U;
  for (std::size_t index = 0U; index < baseline.size(); ++index) {
    mismatches += baseline[index] != candidate[index] ? 1U : 0U;
  }
  std::cout << "FP8_M1_GRID_CAP_LARGE_ROWS_DIFF: grid_cap=" << grid_cap
            << " candidate_vs_uncapped_bf16=" << mismatches << '/'
            << baseline.size() << '\n';
  test.expect(mismatches == 0U,
              label + " covers every row with identical BF16 output");
}

void run_optional_fp8_m1_grid_cap_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!fp8_m1_grid_cap_performance_enabled()) {
    std::cout << "SKIP: FP8 M1 persistent-row grid-cap segment; set "
                 "Q3X_RUN_SM87_FP8_M1_GRID_CAP_PERF=1 to enable\n";
    return;
  }
  constexpr float kMinimumWeightedSpeedup = 1.03F;
  constexpr float kMinimumPerShapeSpeedup = 0.98F;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t calls_per_prompt;
    const char* label;
  };
  constexpr std::array<Shape, 6U> kShapes{{
      {10'240U, 5'120U, 48U, "FP8 M1 linear QKV 10240x5120"},
      {5'120U, 6'144U, 64U, "FP8 M1 projection 5120x6144"},
      {6'144U, 5'120U, 48U, "FP8 M1 projection 6144x5120"},
      {12'288U, 5'120U, 16U, "FP8 M1 linear QKV 12288x5120"},
      {1'024U, 5'120U, 32U, "FP8 M1 small projection 1024x5120"},
      {5'120U, 5'120U, 0U, "FP8 M1 square validation 5120x5120"},
  }};
  std::array<Fp8M1GridCapMeasurements, kShapes.size()> measurements{};
  measurements[0] = benchmark_fp8_m1_grid_cap_shape(
      test, stream, kShapes[0].rows, kShapes[0].columns, kShapes[0].label);
  measurements[1] = benchmark_fp8_m1_grid_cap_shape(
      test, stream, kShapes[1].rows, kShapes[1].columns, kShapes[1].label);

  std::size_t selected_cap_index = kFp8M1GridCaps.size();
  double selected_core_speedup = 0.0;
  for (std::size_t cap_index = 0U; cap_index < kFp8M1GridCaps.size();
       ++cap_index) {
    const float baseline0 =
        measurements[0].baseline_milliseconds[cap_index];
    const float baseline1 =
        measurements[1].baseline_milliseconds[cap_index];
    const float candidate0 =
        measurements[0].candidate_milliseconds[cap_index];
    const float candidate1 =
        measurements[1].candidate_milliseconds[cap_index];
    const bool finite = std::isfinite(baseline0) &&
                        std::isfinite(baseline1) &&
                        std::isfinite(candidate0) &&
                        std::isfinite(candidate1);
    const bool bitwise = measurements[0].bitwise_equal[cap_index] &&
                         measurements[1].bitwise_equal[cap_index];
    const double weighted_baseline = 48.0 * baseline0 + 64.0 * baseline1;
    const double weighted_candidate = 48.0 * candidate0 + 64.0 * candidate1;
    const double speedup = weighted_baseline / weighted_candidate;
    const bool no_regression = finite && candidate0 <= baseline0 / 0.98F &&
                               candidate1 <= baseline1 / 0.98F;
    std::cout << "PERF_FP8_M1_GRID_CAP_CORE: grid_cap="
              << kFp8M1GridCaps[cap_index]
              << " weighted_baseline_ms=" << weighted_baseline
              << " weighted_candidate_ms=" << weighted_candidate
              << " speedup=" << speedup
              << " bitwise=" << (bitwise ? "true" : "false")
              << " no_regression=" << (no_regression ? "true" : "false")
              << '\n';
    if (finite && bitwise && no_regression &&
        speedup > selected_core_speedup) {
      selected_core_speedup = speedup;
      selected_cap_index = cap_index;
    }
  }
  const bool selected = selected_cap_index < kFp8M1GridCaps.size();
  test.expect(selected, "FP8 M1 grid-cap sweep selects a valid core cap");
  if (!selected) {
    return;
  }
  const std::size_t sweep_cap = kFp8M1GridCaps[selected_cap_index];
  std::cout << "PERF_FP8_M1_GRID_CAP_SWEEP_BEST: grid_cap=" << sweep_cap
            << " core_speedup=" << selected_core_speedup << '\n';

  // The production cap was frozen after the first complete sweep. Retain the
  // sweep as a diagnostic, but gate the exact value compiled into dispatch so
  // run-to-run clock noise cannot silently validate a different cap.
  constexpr std::size_t kProductionCapIndex = kFp8M1GridCaps.size() - 1U;
  selected_cap_index = kProductionCapIndex;
  const std::size_t selected_cap = kFp8M1GridCaps[selected_cap_index];
  const double production_core_baseline =
      48.0 * measurements[0].baseline_milliseconds[selected_cap_index] +
      64.0 * measurements[1].baseline_milliseconds[selected_cap_index];
  const double production_core_candidate =
      48.0 * measurements[0].candidate_milliseconds[selected_cap_index] +
      64.0 * measurements[1].candidate_milliseconds[selected_cap_index];
  const double production_core_speedup =
      production_core_baseline / production_core_candidate;
  const bool production_core_gate =
      measurements[0].bitwise_equal[selected_cap_index] &&
      measurements[1].bitwise_equal[selected_cap_index] &&
      std::isfinite(production_core_speedup) &&
      production_core_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_FP8_M1_GRID_CAP_SELECTED: grid_cap=" << selected_cap
            << " production_core_speedup=" << production_core_speedup
            << " gate=" << (production_core_gate ? "PASS" : "FAIL") << '\n';
  test.expect(production_core_gate,
              "FP8 M1 production cap clears the frozen core gate");
  if (!production_core_gate) {
    return;
  }

  for (std::size_t shape_index = 2U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_fp8_m1_grid_cap_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }
  double weighted_baseline = 0.0;
  double weighted_candidate = 0.0;
  bool all_bitwise = true;
  bool all_finite = true;
  bool no_shape_regression = true;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    const float baseline =
        measurements[shape_index].baseline_milliseconds[selected_cap_index];
    const float candidate =
        measurements[shape_index].candidate_milliseconds[selected_cap_index];
    const bool finite = std::isfinite(baseline) && std::isfinite(candidate);
    const float speedup = baseline / candidate;
    all_finite = all_finite && finite;
    all_bitwise = all_bitwise &&
                  measurements[shape_index].bitwise_equal[selected_cap_index];
    no_shape_regression = no_shape_regression && finite &&
                          speedup >= kMinimumPerShapeSpeedup;
    weighted_baseline +=
        static_cast<double>(kShapes[shape_index].calls_per_prompt) * baseline;
    weighted_candidate +=
        static_cast<double>(kShapes[shape_index].calls_per_prompt) * candidate;
    std::cout << "PERF_FP8_M1_GRID_CAP_VALIDATION: "
              << kShapes[shape_index].label
              << " grid_cap=" << selected_cap
              << " baseline_ms=" << baseline
              << " candidate_ms=" << candidate
              << " speedup=" << speedup
              << " minimum_speedup=" << kMinimumPerShapeSpeedup
              << " gate="
              << (finite && speedup >= kMinimumPerShapeSpeedup ? "PASS"
                                                               : "FAIL")
              << '\n';
  }
  const double weighted_speedup = weighted_baseline / weighted_candidate;
  const bool aggregate_gate =
      all_finite && all_bitwise && no_shape_regression &&
      std::isfinite(weighted_speedup) &&
      weighted_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_FP8_M1_GRID_CAP_AGGREGATE: selected_cap="
            << selected_cap << " weighted_baseline_ms=" << weighted_baseline
            << " weighted_candidate_ms=" << weighted_candidate
            << " speedup=" << weighted_speedup
            << " required_speedup=" << kMinimumWeightedSpeedup
            << " all_bitwise=" << (all_bitwise ? "true" : "false")
            << " no_shape_regression="
            << (no_shape_regression ? "true" : "false")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "FP8 M1 selected grid cap clears every production gate");
  if (aggregate_gate) {
    run_fp8_m1_large_row_grid_stride_coverage(test, stream, selected_cap);
  }
}

constexpr std::array<std::size_t, 6U> kFp8M2GridCaps{{
    96U, 192U, 384U, 768U, 1'024U, 2'048U,
}};

struct Fp8M2GridCapMeasurements {
  std::array<float, kFp8M2GridCaps.size()> baseline_milliseconds{};
  std::array<float, kFp8M2GridCaps.size()> candidate_milliseconds{};
  std::array<bool, kFp8M2GridCaps.size()> bitwise_equal{};
};

[[nodiscard]] Fp8M2GridCapMeasurements benchmark_fp8_m2_grid_cap_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokenCount = 2U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};
  Fp8M2GridCapMeasurements measurements;
  measurements.baseline_milliseconds.fill(
      std::numeric_limits<float>::quiet_NaN());
  measurements.candidate_milliseconds.fill(
      std::numeric_limits<float>::quiet_NaN());

  std::vector<std::uint8_t> host_weights(rows * columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] =
        kFiniteCodes[(index * 7U + index / columns * 5U + 1U) %
                     kFiniteCodes.size()];
  }
  std::vector<std::uint16_t> host_activations(kTokenCount * columns);
  for (std::size_t token = 0U; token < kTokenCount; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered = static_cast<int>(
                               (column * 13U + token * 29U + 3U) % 127U) -
                           63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready &&
          test.cuda_ok(activations.allocate(host_activations.size()),
                       label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokenCount * rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokenCount * rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed finite weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed activations");
  if (!ready) {
    return measurements;
  }

  const auto launch_baseline = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m2_uncapped_test_cuda(
            weights.get(), kWeightScale, activations.get(), rows, columns,
            baseline_output.get(), static_cast<void*>(stream));
  };
  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " correctness baseline launch");
  std::vector<std::uint16_t> baseline(kTokenCount * rows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy correctness baseline");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " baseline synchronize");
  if (!ready) {
    return measurements;
  }

  for (std::size_t cap_index = 0U; cap_index < kFp8M2GridCaps.size();
       ++cap_index) {
    const std::size_t grid_cap = kFp8M2GridCaps[cap_index];
    const auto launch_candidate = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_small_m2_grid_cap_test_cuda(
              weights.get(), kWeightScale, activations.get(), rows, columns,
              candidate_output.get(), grid_cap, static_cast<void*>(stream));
    };
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_candidate()),
                         label + " correctness candidate launch cap=" +
                             std::to_string(grid_cap));
    std::vector<std::uint16_t> candidate(kTokenCount * rows);
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy correctness candidate cap=" +
                             std::to_string(grid_cap));
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         label + " correctness synchronize cap=" +
                             std::to_string(grid_cap));
    if (!ready) {
      return measurements;
    }
    std::size_t mismatches = 0U;
    for (std::size_t index = 0U; index < baseline.size(); ++index) {
      mismatches += baseline[index] != candidate[index] ? 1U : 0U;
    }
    measurements.bitwise_equal[cap_index] = mismatches == 0U;
    std::cout << "FP8_M2_GRID_CAP_DIFF: " << label
              << " grid_cap=" << grid_cap
              << " candidate_vs_uncapped_bf16=" << mismatches << '/'
              << baseline.size() << '\n';
    test.expect(mismatches == 0U,
                label + " cap=" + std::to_string(grid_cap) +
                    " matches every uncapped M2 BF16 bit");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           label + " candidate warmup cap=" +
                               std::to_string(grid_cap));
    }
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         label + " warmup synchronize cap=" +
                             std::to_string(grid_cap));
    if (!ready) {
      return measurements;
    }

    double baseline_total = 0.0;
    double candidate_total = 0.0;
    bool finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_suffix =
          " cap=" + std::to_string(grid_cap) +
          " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          label + " baseline pass 1" + round_suffix);
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          label + " candidate pass 1" + round_suffix);
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          label + " candidate pass 2" + round_suffix);
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          label + " baseline pass 2" + round_suffix);
      const bool round_finite =
          std::isfinite(baseline_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(baseline_second);
      finite = finite && round_finite;
      if (round_finite) {
        baseline_total += baseline_first + baseline_second;
        candidate_total += candidate_first + candidate_second;
      }
      std::cout << "PERF_FP8_M2_GRID_CAP_ROUND: " << label
                << " grid_cap=" << grid_cap << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }
    if (!finite) {
      return measurements;
    }
    constexpr double kPassesPerCandidate =
        2.0 * static_cast<double>(kMeasurementRounds);
    const float baseline_average =
        static_cast<float>(baseline_total / kPassesPerCandidate);
    const float candidate_average =
        static_cast<float>(candidate_total / kPassesPerCandidate);
    measurements.baseline_milliseconds[cap_index] = baseline_average;
    measurements.candidate_milliseconds[cap_index] = candidate_average;
    const float speedup = baseline_average / candidate_average;
    std::cout << "PERF_FP8_M2_GRID_CAP: " << label
              << " grid_cap=" << grid_cap
              << " baseline_average_ms=" << baseline_average
              << " candidate_average_ms=" << candidate_average
              << " speedup=" << speedup
              << " uplift_percent=" << (speedup - 1.0F) * 100.0F << '\n';
  }
  return measurements;
}

void run_fp8_m2_large_row_grid_stride_coverage(
    TestContext& test, cudaStream_t stream, const std::size_t grid_cap) {
  constexpr std::size_t kTokenCount = 2U;
  constexpr std::size_t kRows = 65'537U;
  constexpr std::size_t kColumns = 1'024U;
  constexpr float kWeightScale = 1.0F / 64.0F;
  const std::string label = "FP8 M2 grid-cap >65535-row coverage";
  std::vector<std::uint16_t> host_activations(
      kTokenCount * kColumns, encode_bf16(1.0F / 256.0F));
  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(kRows * kColumns),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready &&
          test.cuda_ok(baseline_output.allocate(kTokenCount * kRows),
                       label + " allocate baseline output");
  ready = ready &&
          test.cuda_ok(candidate_output.allocate(kTokenCount * kRows),
                       label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(weights.get(), 0x38, kRows * kColumns,
                                       stream),
                       label + " initialize weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  if (!ready) {
    return;
  }
  ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          launch_sm87_fp8_w8a16_small_m2_uncapped_test_cuda(
              weights.get(), kWeightScale, activations.get(), kRows, kColumns,
              baseline_output.get(), static_cast<void*>(stream))),
      label + " launch uncapped baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           launch_sm87_fp8_w8a16_small_m_gemm_bf16_cuda(
                               weights.get(), kWeightScale, activations.get(),
                               kTokenCount, kRows, kColumns,
                               candidate_output.get(),
                               static_cast<void*>(stream))),
                       label + " launch production candidate");
  std::vector<std::uint16_t> baseline(kTokenCount * kRows);
  std::vector<std::uint16_t> candidate(kTokenCount * kRows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize");
  if (!ready) {
    return;
  }
  std::size_t mismatches = 0U;
  for (std::size_t index = 0U; index < baseline.size(); ++index) {
    mismatches += baseline[index] != candidate[index] ? 1U : 0U;
  }
  std::cout << "FP8_M2_GRID_CAP_LARGE_ROWS_DIFF: grid_cap=" << grid_cap
            << " production_vs_uncapped_bf16=" << mismatches << '/'
            << baseline.size() << '\n';
  test.expect(mismatches == 0U,
              label + " covers every token row with identical BF16 output");
}

void run_optional_fp8_m2_grid_cap_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!fp8_m2_grid_cap_performance_enabled()) {
    std::cout << "SKIP: FP8 M2 persistent-row grid-cap segment; set "
                 "Q3X_RUN_SM87_FP8_M2_GRID_CAP_PERF=1 to enable\n";
    return;
  }
  constexpr float kMinimumWeightedSpeedup = 1.03F;
  constexpr float kMinimumPerShapeSpeedup = 0.98F;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t calls_per_prompt;
    const char* label;
  };
  constexpr std::array<Shape, 6U> kShapes{{
      {10'240U, 5'120U, 48U, "FP8 M2 linear QKV 10240x5120"},
      {5'120U, 6'144U, 64U, "FP8 M2 projection 5120x6144"},
      {6'144U, 5'120U, 48U, "FP8 M2 projection 6144x5120"},
      {12'288U, 5'120U, 16U, "FP8 M2 linear QKV 12288x5120"},
      {1'024U, 5'120U, 32U, "FP8 M2 small projection 1024x5120"},
      {5'120U, 5'120U, 0U, "FP8 M2 square validation 5120x5120"},
  }};
  std::array<Fp8M2GridCapMeasurements, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_fp8_m2_grid_cap_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }

  std::size_t selected_cap_index = kFp8M2GridCaps.size();
  double selected_weighted_speedup = 0.0;
  std::array<double, kFp8M2GridCaps.size()> weighted_speedups{};
  std::array<bool, kFp8M2GridCaps.size()> aggregate_gates{};
  for (std::size_t cap_index = 0U; cap_index < kFp8M2GridCaps.size();
       ++cap_index) {
    double weighted_baseline = 0.0;
    double weighted_candidate = 0.0;
    bool all_bitwise = true;
    bool all_finite = true;
    bool no_shape_regression = true;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      const float baseline =
          measurements[shape_index].baseline_milliseconds[cap_index];
      const float candidate =
          measurements[shape_index].candidate_milliseconds[cap_index];
      const bool finite = std::isfinite(baseline) && std::isfinite(candidate);
      const float speedup = baseline / candidate;
      all_finite = all_finite && finite;
      all_bitwise = all_bitwise &&
                    measurements[shape_index].bitwise_equal[cap_index];
      no_shape_regression = no_shape_regression && finite &&
                            speedup >= kMinimumPerShapeSpeedup;
      weighted_baseline +=
          static_cast<double>(kShapes[shape_index].calls_per_prompt) *
          baseline;
      weighted_candidate +=
          static_cast<double>(kShapes[shape_index].calls_per_prompt) *
          candidate;
      std::cout << "PERF_FP8_M2_GRID_CAP_VALIDATION: "
                << kShapes[shape_index].label
                << " grid_cap=" << kFp8M2GridCaps[cap_index]
                << " baseline_ms=" << baseline
                << " candidate_ms=" << candidate
                << " speedup=" << speedup
                << " minimum_speedup=" << kMinimumPerShapeSpeedup
                << " gate="
                << (finite && speedup >= kMinimumPerShapeSpeedup ? "PASS"
                                                                 : "FAIL")
                << '\n';
    }
    const double weighted_speedup = weighted_baseline / weighted_candidate;
    const bool aggregate_gate =
        all_finite && all_bitwise && no_shape_regression &&
        std::isfinite(weighted_speedup) &&
        weighted_speedup >= kMinimumWeightedSpeedup;
    weighted_speedups[cap_index] = weighted_speedup;
    aggregate_gates[cap_index] = aggregate_gate;
    std::cout << "PERF_FP8_M2_GRID_CAP_AGGREGATE: grid_cap="
              << kFp8M2GridCaps[cap_index]
              << " weighted_baseline_ms=" << weighted_baseline
              << " weighted_candidate_ms=" << weighted_candidate
              << " speedup=" << weighted_speedup
              << " required_speedup=" << kMinimumWeightedSpeedup
              << " all_bitwise=" << (all_bitwise ? "true" : "false")
              << " no_shape_regression="
              << (no_shape_regression ? "true" : "false")
              << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
    if (aggregate_gate && weighted_speedup > selected_weighted_speedup) {
      selected_cap_index = cap_index;
      selected_weighted_speedup = weighted_speedup;
    }
  }
  const bool sweep_selected = selected_cap_index < kFp8M2GridCaps.size();
  test.expect(sweep_selected,
              "FP8 M2 sweep selects a cap clearing every production gate");
  if (!sweep_selected) {
    std::cout << "PERF_FP8_M2_GRID_CAP_SWEEP_BEST: gate=FAIL\n";
    return;
  }
  std::cout << "PERF_FP8_M2_GRID_CAP_SWEEP_BEST: grid_cap="
            << kFp8M2GridCaps[selected_cap_index]
            << " weighted_speedup=" << selected_weighted_speedup << '\n';

  // Freeze and gate the exact cap compiled into production. The diagnostic
  // sweep remains useful, but clock noise must not validate another cap.
  constexpr std::size_t kProductionCapIndex = kFp8M2GridCaps.size() - 1U;
  selected_cap_index = kProductionCapIndex;
  const std::size_t selected_cap = kFp8M2GridCaps[selected_cap_index];
  const bool production_gate = aggregate_gates[selected_cap_index];
  std::cout << "PERF_FP8_M2_GRID_CAP_SELECTED: grid_cap=" << selected_cap
            << " weighted_speedup=" << weighted_speedups[selected_cap_index]
            << " gate=" << (production_gate ? "PASS" : "FAIL") << '\n';
  test.expect(production_gate,
              "FP8 M2 frozen production cap clears every production gate");
  if (!production_gate) {
    return;
  }
  run_fp8_m2_large_row_grid_stride_coverage(test, stream, selected_cap);
}

enum class Fp8M2CodeDistribution {
  kCheckpointLike,
  kSameBankStress,
};

[[nodiscard]] const char* fp8_m2_code_distribution_name(
    const Fp8M2CodeDistribution distribution) noexcept {
  return distribution == Fp8M2CodeDistribution::kCheckpointLike
             ? "checkpoint_like"
             : "same_bank_stress";
}

void fill_fp8_m2_code_distribution(
    std::vector<std::uint8_t>& weights, const std::size_t rows,
    const std::size_t columns, const Fp8M2CodeDistribution distribution) {
  constexpr std::array<std::uint8_t, 32U> kCheckpointLikeCodes{{
      0x00U, 0x00U, 0x80U, 0x00U, 0x10U, 0x90U, 0x18U, 0x98U,
      0x20U, 0xa0U, 0x28U, 0xa8U, 0x30U, 0xb0U, 0x34U, 0xb4U,
      0x38U, 0xb8U, 0x38U, 0xb8U, 0x39U, 0xb9U, 0x3aU, 0xbaU,
      0x3cU, 0xbcU, 0x40U, 0xc0U, 0x30U, 0x34U, 0xb0U, 0xb4U,
  }};
  constexpr std::array<std::uint8_t, 8U> kSameBankCodes{{
      0x18U, 0x38U, 0x58U, 0x78U,
      0x98U, 0xb8U, 0xd8U, 0xf8U,
  }};
  for (std::size_t row = 0U; row < rows; ++row) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const std::size_t index = row * columns + column;
      if (distribution == Fp8M2CodeDistribution::kCheckpointLike) {
        weights[index] = kCheckpointLikeCodes[
            (column * 5U + row * 11U + (column >> 4U)) %
            kCheckpointLikeCodes.size()];
      } else {
        // Every code has identical low five bits, so simultaneous lookup
        // lanes contend for one shared-memory bank while decoding different
        // finite E4M3FN values and signs.
        weights[index] = kSameBankCodes[
            (column + row * 3U + (column >> 5U)) % kSameBankCodes.size()];
      }
    }
  }
}

struct Fp8KvPairKernelResources {
  int registers_per_thread = 0;
  std::size_t static_shared_bytes = 0U;
  std::size_t local_bytes = 0U;
  int maximum_threads_per_block = 0;
  int active_blocks_per_sm = 0;
};

struct Fp8KvPairTiming {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
};

template <std::size_t Count>
[[nodiscard]] float median_fp8_kv_pair_timing(
    std::array<float, Count> values) {
  static_assert(Count != 0U);
  std::sort(values.begin(), values.end());
  if constexpr ((Count % 2U) == 0U) {
    return (values[Count / 2U - 1U] + values[Count / 2U]) * 0.5F;
  }
  return values[Count / 2U];
}

void run_fp8_m1_kv_pair_correctness_and_optional_performance(
    TestContext& test, cudaStream_t stream) {
  constexpr std::size_t kRows = 1'024U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kGuardElements = 16U;
  constexpr float kKeyWeightScale = 1.0F / 64.0F;
  constexpr float kValueWeightScale = 1.0F / 96.0F;
  constexpr int kWarmupIterations = 8;
  constexpr int kMeasuredIterations = 80;
  constexpr int kMeasurementRounds = 3;
  constexpr std::uint16_t kKeyGuard = 0xa5a5U;
  constexpr std::uint16_t kValueGuard = 0x5a5aU;
  constexpr std::size_t kComparisonGridCap = 64U;
  constexpr std::size_t kSelectedGridCap = 128U;
  constexpr std::array<Fp8M2CodeDistribution, 2U> kDistributions{{
      Fp8M2CodeDistribution::kCheckpointLike,
      Fp8M2CodeDistribution::kSameBankStress,
  }};
  const std::string label = "FP8 M1 exact K/V pair 1024x5120";

  Fp8KvPairKernelResources row_quad_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_kv_pair_row_quad_resources_test_cuda(
              &row_quad_resources.registers_per_thread,
              &row_quad_resources.static_shared_bytes,
              &row_quad_resources.local_bytes,
              &row_quad_resources.maximum_threads_per_block,
              &row_quad_resources.active_blocks_per_sm)),
      label + " query production cross-matrix row-quad resources");
  if (!ready) {
    return;
  }
  const auto report_resources = [&](const char* const candidate,
                                    const Fp8KvPairKernelResources& resources,
                                    const std::size_t outputs_per_cta) {
    std::cout << "PERF_FP8_M1_KV_PAIR_RESOURCES: candidate=" << candidate
              << " outputs_per_cta=" << outputs_per_cta
              << " registers_per_thread=" << resources.registers_per_thread
              << " static_shared_bytes=" << resources.static_shared_bytes
              << " local_bytes=" << resources.local_bytes
              << " maximum_threads_per_block="
              << resources.maximum_threads_per_block
              << " active_blocks_per_sm=" << resources.active_blocks_per_sm
              << '\n';
    test.expect(resources.registers_per_thread > 0 &&
                    resources.static_shared_bytes > 0U &&
                    resources.maximum_threads_per_block >= 256 &&
                    resources.active_blocks_per_sm > 0,
                label + " " + candidate + " reports usable resources");
  };
  report_resources("production_cross_matrix_row_quad_2K2V",
                   row_quad_resources, 4U);
  const bool selected_resource_gate =
      row_quad_resources.registers_per_thread <= 64 &&
      row_quad_resources.local_bytes == 0U &&
      row_quad_resources.active_blocks_per_sm >= 4;
  std::cout << "PERF_FP8_M1_KV_PAIR_RESOURCE_GATE: candidate="
               "production_cross_matrix_row_quad_2K2V"
            << " maximum_registers_per_thread=64 minimum_active_blocks_per_sm=4"
            << " require_zero_local_bytes=true gate="
            << (selected_resource_gate ? "PASS" : "FAIL") << '\n';
  test.expect(selected_resource_gate,
              label + " selected production kernel clears resource gate");
  test.expect(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_kv_pair_row_quad_resources_test_cuda(
              nullptr, &row_quad_resources.static_shared_bytes,
              &row_quad_resources.local_bytes,
              &row_quad_resources.maximum_threads_per_block,
              &row_quad_resources.active_blocks_per_sm)) ==
          cudaErrorInvalidValue,
      label + " resource query rejects a null destination");

  std::vector<std::uint8_t> host_key_weights(kRows * kColumns);
  std::vector<std::uint8_t> host_value_weights(kRows * kColumns);
  std::vector<std::uint16_t> host_activation(kColumns);
  const auto fill_mixed_activation = [&]() {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + (column >> 3U) * 5U + 7U) %
                           127U) -
          63;
      host_activation[column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  };
  fill_mixed_activation();

  DeviceBuffer<std::uint8_t> key_weights;
  DeviceBuffer<std::uint8_t> value_weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_key_output;
  DeviceBuffer<std::uint16_t> baseline_value_output;
  DeviceBuffer<std::uint16_t> candidate_key_storage;
  DeviceBuffer<std::uint16_t> candidate_value_storage;
  ready = test.cuda_ok(key_weights.allocate(host_key_weights.size()),
                       label + " allocate key weights");
  ready = ready && test.cuda_ok(value_weights.allocate(host_value_weights.size()),
                                label + " allocate value weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_key_output.allocate(kRows),
                                label + " allocate baseline key output");
  ready = ready && test.cuda_ok(baseline_value_output.allocate(kRows),
                                label + " allocate baseline value output");
  ready = ready && test.cuda_ok(
                       candidate_key_storage.allocate(
                           kRows + 2U * kGuardElements),
                       label + " allocate guarded candidate key output");
  ready = ready && test.cuda_ok(
                       candidate_value_storage.allocate(
                           kRows + 2U * kGuardElements),
                       label + " allocate guarded candidate value output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  if (!ready) {
    return;
  }
  std::uint16_t* const candidate_key_output =
      candidate_key_storage.get() + kGuardElements;
  std::uint16_t* const candidate_value_output =
      candidate_value_storage.get() + kGuardElements;

  const auto row_quad_status =
      [&](const std::size_t rows, const std::size_t columns,
          const std::size_t cap, std::uint16_t* const key_output,
          std::uint16_t* const value_output) noexcept {
        return static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_fp8_w8a16_m1_kv_pair_row_quad_grid_cap_test_cuda(
                key_weights.get(), kKeyWeightScale, value_weights.get(),
                kValueWeightScale, activation.get(), rows, columns,
                key_output, value_output, cap, static_cast<void*>(stream)));
      };
  const auto production_status =
      [&](const std::uint8_t* const first_weights,
          const float first_scale, const std::uint8_t* const second_weights,
          const float second_scale, const std::size_t rows,
          const std::size_t columns, std::uint16_t* const first_output,
          std::uint16_t* const second_output) noexcept {
        return static_cast<cudaError_t>(
            q3x::kernels::launch_sm87_fp8_w8a16_gemv_pair_bf16_cuda(
                first_weights, first_scale, second_weights, second_scale,
                activation.get(), rows, columns, first_output, second_output,
                static_cast<void*>(stream)));
      };
  test.expect(production_status(
                  key_weights.get(), kKeyWeightScale, value_weights.get(),
                  kValueWeightScale, kRows - 1U, kColumns,
                  candidate_key_output, candidate_value_output) ==
                  cudaErrorInvalidValue,
              label + " production pair rejects near-miss rows");
  test.expect(production_status(
                  key_weights.get(), kKeyWeightScale, value_weights.get(),
                  kValueWeightScale, kRows, kColumns - 1U,
                  candidate_key_output, candidate_value_output) ==
                  cudaErrorInvalidValue,
              label + " production pair rejects near-miss columns");
  test.expect(row_quad_status(kRows, kColumns, 0U, candidate_key_output,
                              candidate_value_output) ==
                  cudaErrorInvalidValue,
              label + " row-quad rejects zero grid cap");
  test.expect(row_quad_status(kRows, kColumns, kRows / 2U + 1U,
                              candidate_key_output,
                              candidate_value_output) ==
                  cudaErrorInvalidValue,
              label + " row-quad rejects more than 512 CTAs");
  test.expect(production_status(
                  key_weights.get(), kKeyWeightScale, value_weights.get(),
                  kValueWeightScale, kRows, kColumns, candidate_key_output,
                  candidate_key_output) ==
                  cudaErrorInvalidValue,
              label + " production pair rejects overlapping outputs");
  test.expect(
      production_status(key_weights.get(), -1.0F, value_weights.get(),
                        kValueWeightScale, kRows, kColumns,
                        candidate_key_output, candidate_value_output) ==
          cudaErrorInvalidValue,
      label + " production pair rejects a negative first scale");
  test.expect(
      production_status(
          key_weights.get(), kKeyWeightScale, value_weights.get(),
          kValueWeightScale, kRows, kColumns,
          reinterpret_cast<std::uint16_t*>(value_weights.get()),
          candidate_value_output) == cudaErrorInvalidValue,
      label + " production pair rejects first output overlapping second "
              "weights");
  test.expect(
      production_status(key_weights.get() + 1U, kKeyWeightScale,
                        value_weights.get(), kValueWeightScale, kRows,
                        kColumns, candidate_key_output,
                        candidate_value_output) == cudaErrorInvalidValue,
      label + " production pair rejects unaligned first weights");
  test.expect(
      production_status(nullptr, kKeyWeightScale, value_weights.get(),
                        kValueWeightScale, kRows, kColumns,
                        candidate_key_output, candidate_value_output) ==
          cudaErrorInvalidValue,
      label + " production pair rejects null first weights");

  const auto launch_baseline = [&]() noexcept -> int {
    const int key_status =
        q3x::kernels::launch_sm87_fp8_w8a16_gemv_bf16_cuda(
            key_weights.get(), kKeyWeightScale, activation.get(), kRows,
            kColumns, baseline_key_output.get(), static_cast<void*>(stream));
    if (key_status != static_cast<int>(cudaSuccess)) {
      return key_status;
    }
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_bf16_cuda(
        value_weights.get(), kValueWeightScale, activation.get(), kRows,
        kColumns, baseline_value_output.get(), static_cast<void*>(stream));
  };
  const auto launch_row_quad = [&](const std::size_t cap) noexcept -> int {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_kv_pair_row_quad_grid_cap_test_cuda(
            key_weights.get(), kKeyWeightScale, value_weights.get(),
            kValueWeightScale, activation.get(), kRows, kColumns,
            candidate_key_output, candidate_value_output, cap,
            static_cast<void*>(stream));
  };
  const auto launch_production_pair =
      [&](const std::size_t) noexcept -> int {
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_pair_bf16_cuda(
        key_weights.get(), kKeyWeightScale, value_weights.get(),
        kValueWeightScale, activation.get(), kRows, kColumns,
        candidate_key_output, candidate_value_output,
        static_cast<void*>(stream));
  };

  std::vector<std::uint16_t> baseline_key(kRows);
  std::vector<std::uint16_t> baseline_value(kRows);
  std::vector<std::uint16_t> candidate_key(kRows + 2U * kGuardElements);
  std::vector<std::uint16_t> candidate_value(kRows + 2U * kGuardElements);
  std::array<Fp8KvPairTiming, kDistributions.size()> row_quad_cap64{};
  std::array<Fp8KvPairTiming, kDistributions.size()> row_quad_cap128{};
  std::array<bool, kDistributions.size()> row_quad_cap128_correct{};
  bool full_code_production_correct = false;

  const auto check_candidate =
      [&](const auto& launch_candidate, const std::size_t cap,
          const std::string& candidate_label,
          const bool require_finite = true) {
        bool candidate_ready = test.cuda_ok(
            cudaMemsetAsync(candidate_key_storage.get(), 0xa5,
                            candidate_key.size() * sizeof(std::uint16_t),
                            stream),
            candidate_label + " poison guarded key output");
        candidate_ready = candidate_ready && test.cuda_ok(
            cudaMemsetAsync(candidate_value_storage.get(), 0x5a,
                            candidate_value.size() * sizeof(std::uint16_t),
                            stream),
            candidate_label + " poison guarded value output");
        candidate_ready = candidate_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_candidate(cap)),
            candidate_label + " correctness launch");
        candidate_ready = candidate_ready && test.cuda_ok(
            cudaMemcpyAsync(candidate_key.data(), candidate_key_storage.get(),
                            candidate_key.size() * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            candidate_label + " copy guarded key output");
        candidate_ready = candidate_ready && test.cuda_ok(
            cudaMemcpyAsync(candidate_value.data(),
                            candidate_value_storage.get(),
                            candidate_value.size() * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            candidate_label + " copy guarded value output");
        candidate_ready = candidate_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            candidate_label + " correctness synchronize");
        if (!candidate_ready) {
          return false;
        }
        std::size_t key_mismatches = 0U;
        std::size_t value_mismatches = 0U;
        std::size_t nonfinite_outputs = 0U;
        for (std::size_t row = 0U; row < kRows; ++row) {
          key_mismatches +=
              baseline_key[row] != candidate_key[kGuardElements + row] ? 1U
                                                                        : 0U;
          value_mismatches +=
              baseline_value[row] !=
                      candidate_value[kGuardElements + row]
                  ? 1U
                  : 0U;
          nonfinite_outputs += !is_bf16_finite(baseline_key[row]) ? 1U : 0U;
          nonfinite_outputs += !is_bf16_finite(baseline_value[row]) ? 1U : 0U;
          nonfinite_outputs +=
              !is_bf16_finite(candidate_key[kGuardElements + row]) ? 1U : 0U;
          nonfinite_outputs +=
              !is_bf16_finite(candidate_value[kGuardElements + row]) ? 1U
                                                                      : 0U;
        }
        bool guards_intact = true;
        for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
          guards_intact =
              guards_intact && candidate_key[guard] == kKeyGuard &&
              candidate_key[kGuardElements + kRows + guard] == kKeyGuard &&
              candidate_value[guard] == kValueGuard &&
              candidate_value[kGuardElements + kRows + guard] == kValueGuard;
        }
        const bool bitwise =
            key_mismatches == 0U && value_mismatches == 0U;
        std::cout << "FP8_M1_KV_PAIR_DIFF: " << candidate_label
                  << " key_bf16_mismatches=" << key_mismatches << '/'
                  << kRows << " value_bf16_mismatches=" << value_mismatches
                  << '/' << kRows
                  << " output_guards=" << (guards_intact ? "intact" : "BAD")
                  << " nonfinite_outputs=" << nonfinite_outputs
                  << '\n';
        test.expect(bitwise,
                    candidate_label +
                        " matches both production row-pair BF16 outputs");
        test.expect(guards_intact,
                    candidate_label + " preserves both output guards");
        if (require_finite) {
          test.expect(nonfinite_outputs == 0U,
                      candidate_label + " keeps all four output views finite");
        }
        return bitwise && guards_intact &&
               (!require_finite || nonfinite_outputs == 0U);
      };

  const auto benchmark_candidate =
      [&](const auto& launch_candidate, const std::size_t cap,
          const std::string& candidate_label) {
        Fp8KvPairTiming timing{};
        bool timing_ready = true;
        for (int iteration = 0;
             iteration < kWarmupIterations && timing_ready; ++iteration) {
          timing_ready = test.cuda_ok(
              static_cast<cudaError_t>(launch_baseline()),
              candidate_label + " baseline warmup");
          timing_ready = timing_ready && test.cuda_ok(
              static_cast<cudaError_t>(launch_candidate(cap)),
              candidate_label + " candidate warmup");
        }
        timing_ready = timing_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            candidate_label + " warmup synchronize");
        if (!timing_ready) {
          return timing;
        }
        constexpr std::size_t kTimedPasses =
            2U * static_cast<std::size_t>(kMeasurementRounds);
        std::array<float, kTimedPasses> baseline_passes{};
        std::array<float, kTimedPasses> candidate_passes{};
        bool all_finite = true;
        for (int round = 0; round < kMeasurementRounds; ++round) {
          const std::string round_label =
              candidate_label + " round=" + std::to_string(round + 1);
          const float baseline_first = measure_small_m_tile(
              test, stream, launch_baseline, kMeasuredIterations,
              round_label + " baseline pass 1");
          const float candidate_first = measure_small_m_tile(
              test, stream, [&]() noexcept { return launch_candidate(cap); },
              kMeasuredIterations, round_label + " candidate pass 1");
          const float candidate_second = measure_small_m_tile(
              test, stream, [&]() noexcept { return launch_candidate(cap); },
              kMeasuredIterations, round_label + " candidate pass 2");
          const float baseline_second = measure_small_m_tile(
              test, stream, launch_baseline, kMeasuredIterations,
              round_label + " baseline pass 2");
          baseline_passes[2U * static_cast<std::size_t>(round)] =
              baseline_first;
          baseline_passes[2U * static_cast<std::size_t>(round) + 1U] =
              baseline_second;
          candidate_passes[2U * static_cast<std::size_t>(round)] =
              candidate_first;
          candidate_passes[2U * static_cast<std::size_t>(round) + 1U] =
              candidate_second;
          const bool round_finite =
              std::isfinite(baseline_first) &&
              std::isfinite(candidate_first) &&
              std::isfinite(candidate_second) &&
              std::isfinite(baseline_second);
          all_finite = all_finite && round_finite;
          std::cout << "PERF_FP8_M1_KV_PAIR_ROUND: " << candidate_label
                    << " round=" << round + 1
                    << " baseline_pass1_ms=" << baseline_first
                    << " candidate_pass1_ms=" << candidate_first
                    << " candidate_pass2_ms=" << candidate_second
                    << " baseline_pass2_ms=" << baseline_second << '\n';
        }
        if (!all_finite) {
          return timing;
        }
        timing.baseline_milliseconds =
            median_fp8_kv_pair_timing(baseline_passes);
        timing.candidate_milliseconds =
            median_fp8_kv_pair_timing(candidate_passes);
        const float speedup = timing.baseline_milliseconds /
                              timing.candidate_milliseconds;
        constexpr double kEncodedWeightBytes =
            2.0 * static_cast<double>(kRows) *
            static_cast<double>(kColumns);
        const double encoded_weight_gigabytes_per_second =
            kEncodedWeightBytes /
            (static_cast<double>(timing.candidate_milliseconds) * 1.0e6);
        std::cout << "PERF_FP8_M1_KV_PAIR: " << candidate_label
                  << " baseline_two_production_row_pair_median_ms="
                  << timing.baseline_milliseconds
                  << " candidate_median_ms=" << timing.candidate_milliseconds
                  << " speedup=" << speedup
                  << " uplift_percent=" << (speedup - 1.0F) * 100.0F
                  << " candidate_encoded_weight_GBps="
                  << encoded_weight_gigabytes_per_second << '\n';
        test.expect(std::isfinite(speedup) &&
                        timing.baseline_milliseconds > 0.0F &&
                        timing.candidate_milliseconds > 0.0F,
                    candidate_label + " reports finite positive timing");
        return timing;
      };

  // One bounded target-shape fixture puts all 254 finite raw E4M3FN codes in
  // every byte position of the packed-x4 loads. The two NaN codes have a
  // separate classification/sign case below so they cannot make every dot
  // product NaN and erase the finite fixture's bitwise discrimination.
  std::array<std::array<bool, 256U>, 4U> full_key_code_coverage{};
  std::array<std::array<bool, 256U>, 4U> full_value_code_coverage{};
  const auto finite_code = [](const std::size_t index) noexcept {
    const std::size_t finite_index = index % 254U;
    return static_cast<std::uint8_t>(
        finite_index < 127U ? finite_index : finite_index + 1U);
  };
  for (std::size_t row = 0U; row < kRows; ++row) {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const std::size_t byte_position = column & 3U;
      const std::uint8_t key_code =
          finite_code((column >> 2U) + row * 13U);
      host_key_weights[row * kColumns + column] = key_code;
      const std::uint8_t value_code =
          finite_code((column >> 2U) * 7U + row * 11U + 3U);
      host_value_weights[row * kColumns + column] = value_code;
      full_key_code_coverage[byte_position][key_code] = true;
      full_value_code_coverage[byte_position][value_code] = true;
    }
  }
  for (std::size_t byte_position = 0U; byte_position < 4U;
       ++byte_position) {
    const std::size_t key_codes = static_cast<std::size_t>(std::count(
        full_key_code_coverage[byte_position].begin(),
        full_key_code_coverage[byte_position].end(), true));
    const std::size_t value_codes = static_cast<std::size_t>(std::count(
        full_value_code_coverage[byte_position].begin(),
        full_value_code_coverage[byte_position].end(), true));
    test.expect(key_codes == 254U &&
                    !full_key_code_coverage[byte_position][0x7fU] &&
                    !full_key_code_coverage[byte_position][0xffU],
                label + " full-code key fixture covers byte position " +
                    std::to_string(byte_position));
    test.expect(value_codes == 254U &&
                    !full_value_code_coverage[byte_position][0x7fU] &&
                    !full_value_code_coverage[byte_position][0xffU],
                label + " full-code value fixture covers byte position " +
                    std::to_string(byte_position));
  }
  ready = test.cuda_ok(
      cudaMemcpyAsync(key_weights.get(), host_key_weights.data(),
                      host_key_weights.size(), cudaMemcpyHostToDevice, stream),
      label + " initialize full-code key weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           value_weights.get(), host_value_weights.data(),
                           host_value_weights.size(), cudaMemcpyHostToDevice,
                           stream),
                       label + " initialize full-code value weights");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_baseline()),
                       label + " launch full-code production baselines");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline_key.data(), baseline_key_output.get(),
                           baseline_key.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy full-code baseline key output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline_value.data(), baseline_value_output.get(),
                           baseline_value.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy full-code baseline value output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " full-code baseline synchronize");
  if (!ready) {
    return;
  }
  full_code_production_correct = check_candidate(
      launch_production_pair, kSelectedGridCap,
      label + " distribution=full_codebook_all_byte_positions "
              "candidate=production_cross_matrix_row_quad_2K2V cap=128");

  std::fill(host_key_weights.begin(), host_key_weights.end(), 0U);
  std::fill(host_value_weights.begin(), host_value_weights.end(), 0U);
  std::fill(host_activation.begin(), host_activation.end(),
            encode_bf16(0.0F));
  host_activation[0U] = encode_bf16(1.0F);
  host_key_weights[0U] = 0x7fU;
  host_key_weights[kColumns] = 0xffU;
  host_value_weights[0U] = 0xffU;
  host_value_weights[kColumns] = 0x7fU;
  ready = test.cuda_ok(
      cudaMemcpyAsync(key_weights.get(), host_key_weights.data(),
                      host_key_weights.size(), cudaMemcpyHostToDevice, stream),
      label + " initialize isolated NaN key weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           value_weights.get(), host_value_weights.data(),
                           host_value_weights.size(), cudaMemcpyHostToDevice,
                           stream),
                       label + " initialize isolated NaN value weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize isolated NaN activation");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_baseline()),
                       label + " launch isolated NaN production baselines");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline_key.data(), baseline_key_output.get(),
                           baseline_key.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy isolated NaN baseline key output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline_value.data(), baseline_value_output.get(),
                           baseline_value.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy isolated NaN baseline value output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " isolated NaN baseline synchronize");
  if (!ready) {
    return;
  }
  const bool nan_pair_bitwise_and_guards = check_candidate(
      launch_production_pair, kSelectedGridCap,
      label + " distribution=isolated_nan_classification "
              "candidate=production_cross_matrix_row_quad_2K2V cap=128",
      false);
  const auto expect_nan_class_and_sign =
      [&](const std::uint16_t candidate_bits,
          const std::uint16_t baseline_bits,
          const std::string& output_label) {
        test.expect(is_bf16_nan(candidate_bits) && is_bf16_nan(baseline_bits),
                    output_label + " remains in the BF16 NaN class");
        test.expect((candidate_bits & 0x8000U) ==
                        (baseline_bits & 0x8000U),
                    output_label +
                        " matches single-projection NaN output sign");
  };
  expect_nan_class_and_sign(candidate_key[kGuardElements], baseline_key[0U],
                            label + " key row0 raw-code-0x7f NaN");
  expect_nan_class_and_sign(candidate_key[kGuardElements + 1U],
                            baseline_key[1U],
                            label + " key row1 raw-code-0xff NaN");
  expect_nan_class_and_sign(candidate_value[kGuardElements],
                            baseline_value[0U],
                            label + " value row0 raw-code-0xff NaN");
  expect_nan_class_and_sign(candidate_value[kGuardElements + 1U],
                            baseline_value[1U],
                            label + " value row1 raw-code-0x7f NaN");
  std::size_t unexpected_nonfinite = 0U;
  for (std::size_t row = 2U; row < kRows; ++row) {
    unexpected_nonfinite +=
        !is_bf16_finite(candidate_key[kGuardElements + row]) ? 1U : 0U;
    unexpected_nonfinite +=
        !is_bf16_finite(candidate_value[kGuardElements + row]) ? 1U : 0U;
  }
  test.expect(nan_pair_bitwise_and_guards && unexpected_nonfinite == 0U,
              label + " isolates signed NaNs to the four classified rows");
  std::cout << "FP8_M1_KV_PAIR_NAN_CLASSIFICATION: classified_outputs=4"
            << " unexpected_nonfinite=" << unexpected_nonfinite
            << " bitwise_and_guards="
            << (nan_pair_bitwise_and_guards ? "true" : "false") << '\n';

  if (!fp8_m1_kv_pair_performance_enabled()) {
    std::cout << "SKIP: FP8 M1 K/V pair timing segment; set "
                 "Q3X_RUN_SM87_FP8_M1_KV_PAIR_PERF=1 to enable\n";
    return;
  }
  fill_mixed_activation();
  ready = test.cuda_ok(
      cudaMemcpyAsync(activation.get(), host_activation.data(),
                      host_activation.size() * sizeof(std::uint16_t),
                      cudaMemcpyHostToDevice, stream),
      label + " restore mixed activation for timing");
  if (!ready) {
    return;
  }

  for (std::size_t distribution_index = 0U;
       distribution_index < kDistributions.size(); ++distribution_index) {
    const Fp8M2CodeDistribution distribution =
        kDistributions[distribution_index];
    const std::string distribution_name =
        fp8_m2_code_distribution_name(distribution);
    fill_fp8_m2_code_distribution(host_key_weights, kRows, kColumns,
                                  distribution);
    for (std::size_t index = 0U; index < host_value_weights.size(); ++index) {
      host_value_weights[index] =
          host_key_weights[host_value_weights.size() - 1U - index];
    }
    ready = test.cuda_ok(
        cudaMemcpyAsync(key_weights.get(), host_key_weights.data(),
                        host_key_weights.size(), cudaMemcpyHostToDevice,
                        stream),
        label + " " + distribution_name + " initialize key weights");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             value_weights.get(), host_value_weights.data(),
                             host_value_weights.size(), cudaMemcpyHostToDevice,
                             stream),
                         label + " " + distribution_name +
                             " initialize value weights");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         label + " " + distribution_name +
                             " launch two production row-pair baselines");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline_key.data(), baseline_key_output.get(),
                             baseline_key.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " " + distribution_name +
                             " copy baseline key output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline_value.data(),
                             baseline_value_output.get(),
                             baseline_value.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " " + distribution_name +
                             " copy baseline value output");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         label + " " + distribution_name +
                             " baseline synchronize");
    if (!ready) {
      return;
    }

    const std::string comparison_label =
        label + " distribution=" + distribution_name +
        " candidate=cross_matrix_row_quad_2K2V cap=64";
    (void)check_candidate(launch_row_quad, kComparisonGridCap,
                          comparison_label);
    row_quad_cap64[distribution_index] = benchmark_candidate(
        launch_row_quad, kComparisonGridCap, comparison_label);
    const std::string production_label =
        label + " distribution=" + distribution_name +
        " candidate=production_cross_matrix_row_quad_2K2V cap=128";
    row_quad_cap128_correct[distribution_index] =
        check_candidate(launch_production_pair, kSelectedGridCap,
                        production_label);
    row_quad_cap128[distribution_index] = benchmark_candidate(
        launch_production_pair, kSelectedGridCap, production_label);
  }

  const auto report_cap =
      [&](const char* const candidate, const std::size_t cap,
          const std::array<Fp8KvPairTiming, 2U>& timings) {
        double baseline_total = 0.0;
        double candidate_total = 0.0;
        bool finite = true;
        for (const Fp8KvPairTiming& timing : timings) {
          finite = finite && std::isfinite(timing.baseline_milliseconds) &&
                   std::isfinite(timing.candidate_milliseconds);
          baseline_total += timing.baseline_milliseconds;
          candidate_total += timing.candidate_milliseconds;
        }
        const double speedup = baseline_total / candidate_total;
        std::cout << "PERF_FP8_M1_KV_PAIR_CAP_AGGREGATE: candidate="
                  << candidate << " cap=" << cap
                  << " distributions=checkpoint_like:"
                                   "same_bank_stress"
                  << " baseline_two_production_row_pair_ms=" << baseline_total
                  << " candidate_ms=" << candidate_total
                  << " speedup=" << speedup
                  << " uplift_percent=" << (speedup - 1.0) * 100.0
                  << " timing=" << (finite ? "finite" : "BAD") << '\n';
        test.expect(finite && std::isfinite(speedup),
                    label + " " + candidate + " cap" +
                        std::to_string(cap) +
                        " aggregate timing is finite");
      };
  report_cap("cross_matrix_row_quad_2K2V_comparison", kComparisonGridCap,
             row_quad_cap64);
  report_cap("cross_matrix_row_quad_2K2V_selected", kSelectedGridCap,
             row_quad_cap128);

  constexpr double kMinimumSelectedSpeedup = 1.10;
  bool selected_production_gate =
      selected_resource_gate && full_code_production_correct;
  for (std::size_t distribution_index = 0U;
       distribution_index < kDistributions.size(); ++distribution_index) {
    const Fp8KvPairTiming& timing = row_quad_cap128[distribution_index];
    const double speedup =
        static_cast<double>(timing.baseline_milliseconds) /
        static_cast<double>(timing.candidate_milliseconds);
    const bool cell_gate = row_quad_cap128_correct[distribution_index] &&
                           std::isfinite(speedup) &&
                           speedup >= kMinimumSelectedSpeedup;
    selected_production_gate = selected_production_gate && cell_gate;
    std::cout << "PERF_FP8_M1_KV_PAIR_SELECTED_VALIDATION: distribution="
              << fp8_m2_code_distribution_name(
                     kDistributions[distribution_index])
              << " candidate=production_cross_matrix_row_quad_2K2V cap=128"
              << " speedup=" << speedup
              << " required_speedup=" << kMinimumSelectedSpeedup
              << " bitwise_and_guards="
              << (row_quad_cap128_correct[distribution_index] ? "true"
                                                               : "false")
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  std::cout << "PERF_FP8_M1_KV_PAIR_SELECTED: candidate="
               "production_cross_matrix_row_quad_2K2V cap=128"
            << " full_code_bitwise_and_guards="
            << (full_code_production_correct ? "true" : "false")
            << " resource_gate="
            << (selected_resource_gate ? "PASS" : "FAIL")
            << " distribution_gates="
            << (selected_production_gate ? "PASS" : "FAIL")
            << " gate=" << (selected_production_gate ? "PASS" : "FAIL")
            << '\n';
  test.expect(selected_production_gate,
              label + " selected production pair clears exact/resource/"
                      "per-distribution 1.10x gates");
}

void run_fp8_m1_q_kv_production_contract(TestContext& test,
                                          cudaStream_t stream) {
  constexpr std::size_t kQRows = 12'288U;
  constexpr std::size_t kKvRows = 1'024U;
  constexpr std::size_t kColumns = 5'120U;
  const auto* const q_weights =
      reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
  const auto* const key_weights =
      reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
  const auto* const value_weights =
      reinterpret_cast<const std::uint8_t*>(0x3'0000'0000ULL);
  const auto* const activation =
      reinterpret_cast<const std::uint16_t*>(0x4'0000'0000ULL);
  auto* const q_output =
      reinterpret_cast<std::uint16_t*>(0x5'0000'0000ULL);
  auto* const key_output =
      reinterpret_cast<std::uint16_t*>(0x6'0000'0000ULL);
  auto* const value_output =
      reinterpret_cast<std::uint16_t*>(0x7'0000'0000ULL);

  const auto capture = [&](const auto& launch, const std::string& label,
                           std::size_t* const node_count,
                           cudaKernelNodeParams* const params) {
    cudaGraph_t graph = nullptr;
    bool ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        label + " begin capture");
    int launch_status = static_cast<int>(cudaErrorUnknown);
    if (ready) {
      launch_status = launch();
      ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           label + " end capture") &&
              ready;
    }
    *node_count = 0U;
    if (ready) {
      ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, node_count),
                           label + " query nodes") &&
              ready;
    }
    if (ready && params != nullptr && *node_count == 1U) {
      cudaGraphNode_t node = nullptr;
      std::size_t capacity = 1U;
      ready = test.cuda_ok(cudaGraphGetNodes(graph, &node, &capacity),
                           label + " get node") &&
              capacity == 1U &&
              test.cuda_ok(cudaGraphKernelNodeGetParams(node, params),
                           label + " get params") &&
              ready;
    }
    if (graph != nullptr) {
      ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy graph") &&
              ready;
    }
    return std::pair<bool, int>{ready, launch_status};
  };

  const auto exact_launch = [&]() noexcept {
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
        q_weights, 1.0F / 64.0F, key_weights, 1.0F / 96.0F,
        value_weights, 1.0F / 128.0F, activation, kQRows, kKvRows,
        kColumns, q_output, key_output, value_output,
        static_cast<void*>(stream));
  };
  cudaKernelNodeParams exact_params{};
  std::size_t exact_nodes = 0U;
  const auto exact = capture(exact_launch, "FP8 Q+K/V public exact",
                             &exact_nodes, &exact_params);
  const bool exact_contract =
      exact.first && exact.second == static_cast<int>(cudaSuccess) &&
      exact_nodes == 1U && exact_params.gridDim.x == 2'048U &&
      exact_params.gridDim.y == 1U && exact_params.gridDim.z == 1U &&
      exact_params.blockDim.x == 256U && exact_params.blockDim.y == 1U &&
      exact_params.blockDim.z == 1U && exact_params.sharedMemBytes == 0U;
  test.expect(exact_contract,
              "FP8 Q+K/V public exact ABI captures one production kernel");

  std::size_t invalid_shape_nodes = 0U;
  const auto invalid_shape = capture(
      [&]() noexcept {
        return q3x::kernels::launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
            q_weights, 1.0F / 64.0F, key_weights, 1.0F / 96.0F,
            value_weights, 1.0F / 128.0F, activation, kQRows - 1U,
            kKvRows, kColumns, q_output, key_output, value_output,
            static_cast<void*>(stream));
      },
      "FP8 Q+K/V invalid shape", &invalid_shape_nodes, nullptr);
  std::size_t invalid_alias_nodes = 0U;
  const auto invalid_alias = capture(
      [&]() noexcept {
        return q3x::kernels::launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
            q_weights, 1.0F / 64.0F, key_weights, 1.0F / 96.0F,
            value_weights, 1.0F / 128.0F, activation, kQRows, kKvRows,
            kColumns, q_output, q_output, value_output,
            static_cast<void*>(stream));
      },
      "FP8 Q+K/V invalid alias", &invalid_alias_nodes, nullptr);
  const bool invalid_contract =
      invalid_shape.first && invalid_alias.first &&
      invalid_shape.second == static_cast<int>(cudaErrorInvalidValue) &&
      invalid_alias.second == static_cast<int>(cudaErrorInvalidValue) &&
      invalid_shape_nodes == 0U && invalid_alias_nodes == 0U;
  test.expect(invalid_contract,
              "FP8 Q+K/V public ABI rejects invalid calls before enqueue");

  Fp8KvPairKernelResources resources{};
  const bool resource_ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_q_kv_two_phase_fused_resources_test_cuda(
              &resources.registers_per_thread,
              &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)),
      "FP8 Q+K/V public resource query");
  const bool resource_contract =
      resource_ready && resources.registers_per_thread == 64 &&
      resources.static_shared_bytes == 1'280U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block == 256 &&
      resources.active_blocks_per_sm == 4;
  test.expect(resource_contract,
              "FP8 Q+K/V public kernel preserves its resource contract");
  std::cout << "FP8_M1_Q_KV_PRODUCTION_CONTRACT: nodes=" << exact_nodes
            << " grid=" << exact_params.gridDim.x
            << " block=" << exact_params.blockDim.x
            << " registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " invalid_zero_node_gate="
            << (invalid_contract ? "PASS" : "FAIL")
            << " gate="
            << (exact_contract && resource_contract && invalid_contract
                    ? "PASS"
                    : "FAIL")
            << '\n';
}

void run_optional_fp8_m1_q_kv_fusion_performance(TestContext& test,
                                                  cudaStream_t stream) {
  if (!fp8_m1_q_kv_fusion_performance_enabled()) {
    std::cout << "SKIP: FP8 M1 Q+K/V fusion gate; set "
                 "Q3X_RUN_SM87_FP8_M1_Q_KV_FUSION_PERF=1 to enable\n";
    return;
  }

  constexpr std::size_t kQRows = 12'288U;
  constexpr std::size_t kKvRows = 1'024U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr float kQWeightScale = 1.0F / 64.0F;
  constexpr float kKeyWeightScale = 1.0F / 96.0F;
  constexpr float kValueWeightScale = 1.0F / 128.0F;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 80;
  constexpr int kMeasurementRounds = 5;
  constexpr double kRequiredSpeedup = 1.005;
  const std::string label =
      "FP8 M1 full-attention Q12288+K/V1024 K5120 fusion";

  Fp8KvPairKernelResources resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_q_kv_two_phase_fused_resources_test_cuda(
              &resources.registers_per_thread,
              &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)),
      label + " query resources");
  if (!ready) {
    return;
  }
  const bool resource_gate =
      resources.registers_per_thread == 64 &&
      resources.static_shared_bytes == 1'280U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block == 256 &&
      resources.active_blocks_per_sm == 4;
  test.expect(resource_gate, label + " preserves four-block SM87 residency");
  std::cout << "PERF_FP8_M1_Q_KV_FUSION_RESOURCES: grid=2048"
            << " block=256 kv_first_block=1024 kv_blocks=512"
            << " registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " maximum_threads_per_block="
            << resources.maximum_threads_per_block
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';

  std::vector<std::uint8_t> host_q_weights(kQRows * kColumns);
  std::vector<std::uint8_t> host_key_weights(kKvRows * kColumns);
  std::vector<std::uint8_t> host_value_weights(kKvRows * kColumns);
  std::vector<std::uint16_t> host_activation(kColumns);
  fill_fp8_m2_code_distribution(host_q_weights, kQRows, kColumns,
                                Fp8M2CodeDistribution::kCheckpointLike);
  fill_fp8_m2_code_distribution(host_key_weights, kKvRows, kColumns,
                                Fp8M2CodeDistribution::kCheckpointLike);
  for (std::size_t index = 0U; index < host_value_weights.size(); ++index) {
    host_value_weights[index] =
        host_key_weights[host_value_weights.size() - 1U - index];
  }
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 17U + (column >> 3U) * 5U + 7U) %
                         127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> q_weights;
  DeviceBuffer<std::uint8_t> key_weights;
  DeviceBuffer<std::uint8_t> value_weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_q_output;
  DeviceBuffer<std::uint16_t> baseline_key_output;
  DeviceBuffer<std::uint16_t> baseline_value_output;
  DeviceBuffer<std::uint16_t> candidate_q_output;
  DeviceBuffer<std::uint16_t> candidate_key_output;
  DeviceBuffer<std::uint16_t> candidate_value_output;
  ready = test.cuda_ok(q_weights.allocate(host_q_weights.size()),
                       label + " allocate Q weights");
  ready = ready && test.cuda_ok(key_weights.allocate(host_key_weights.size()),
                                label + " allocate K weights");
  ready = ready &&
          test.cuda_ok(value_weights.allocate(host_value_weights.size()),
                       label + " allocate V weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_q_output.allocate(kQRows),
                                label + " allocate baseline Q output");
  ready = ready && test.cuda_ok(baseline_key_output.allocate(kKvRows),
                                label + " allocate baseline K output");
  ready = ready && test.cuda_ok(baseline_value_output.allocate(kKvRows),
                                label + " allocate baseline V output");
  ready = ready && test.cuda_ok(candidate_q_output.allocate(kQRows),
                                label + " allocate candidate Q output");
  ready = ready && test.cuda_ok(candidate_key_output.allocate(kKvRows),
                                label + " allocate candidate K output");
  ready = ready && test.cuda_ok(candidate_value_output.allocate(kKvRows),
                                label + " allocate candidate V output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(q_weights.get(), host_q_weights.data(),
                                       host_q_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload Q weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(key_weights.get(),
                                       host_key_weights.data(),
                                       host_key_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload K weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(value_weights.get(),
                                       host_value_weights.data(),
                                       host_value_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload V weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " upload activation");
  if (!ready) {
    return;
  }

  const auto launch_baseline = [&]() noexcept {
    const int q_status =
        q3x::kernels::launch_sm87_fp8_w8a16_gemv_bf16_cuda(
            q_weights.get(), kQWeightScale, activation.get(), kQRows,
            kColumns, baseline_q_output.get(), static_cast<void*>(stream));
    if (q_status != static_cast<int>(cudaSuccess)) {
      return q_status;
    }
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_pair_bf16_cuda(
        key_weights.get(), kKeyWeightScale, value_weights.get(),
        kValueWeightScale, activation.get(), kKvRows, kColumns,
        baseline_key_output.get(), baseline_value_output.get(),
        static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
            q_weights.get(), kQWeightScale, key_weights.get(),
            kKeyWeightScale, value_weights.get(), kValueWeightScale,
            activation.get(), kQRows, kKvRows, kColumns,
            candidate_q_output.get(),
            candidate_key_output.get(), candidate_value_output.get(),
            static_cast<void*>(stream));
  };

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " launch two-kernel baseline");
  ready = ready &&
          test.cuda_ok(static_cast<cudaError_t>(launch_candidate()),
                       label + " launch one-kernel candidate");
  std::vector<std::uint16_t> baseline_q(kQRows);
  std::vector<std::uint16_t> baseline_key(kKvRows);
  std::vector<std::uint16_t> baseline_value(kKvRows);
  std::vector<std::uint16_t> candidate_q(kQRows);
  std::vector<std::uint16_t> candidate_key(kKvRows);
  std::vector<std::uint16_t> candidate_value(kKvRows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline_q.data(), baseline_q_output.get(),
                           baseline_q.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline Q output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline_key.data(), baseline_key_output.get(),
                           baseline_key.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline K output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline_value.data(), baseline_value_output.get(),
                           baseline_value.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline V output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate_q.data(), candidate_q_output.get(),
                           candidate_q.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate Q output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate_key.data(), candidate_key_output.get(),
                           candidate_key.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate K output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate_value.data(), candidate_value_output.get(),
                           candidate_value.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate V output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " correctness synchronize");
  if (!ready) {
    return;
  }

  std::size_t key_mismatches = 0U;
  std::size_t value_mismatches = 0U;
  for (std::size_t row = 0U; row < kKvRows; ++row) {
    key_mismatches += candidate_key[row] != baseline_key[row] ? 1U : 0U;
    value_mismatches +=
        candidate_value[row] != baseline_value[row] ? 1U : 0U;
  }
  std::size_t direct_q_mismatches = 0U;
  for (std::size_t row = 0U; row < kQRows; ++row) {
    direct_q_mismatches += candidate_q[row] != baseline_q[row] ? 1U : 0U;
  }
  const bool bitwise_gate = direct_q_mismatches == 0U &&
                            key_mismatches == 0U &&
                            value_mismatches == 0U;
  test.expect(bitwise_gate, label + " is bitwise identical to Q + K/V");
  std::cout << "PERF_FP8_M1_Q_KV_FUSION_BITWISE: q_mismatches="
            << direct_q_mismatches << "/" << kQRows
            << " key_mismatches=" << key_mismatches << "/" << kKvRows
            << " value_mismatches=" << value_mismatches << "/" << kKvRows
            << " gate=" << (bitwise_gate ? "PASS" : "FAIL") << '\n';

  for (int iteration = 0; iteration < kWarmupIterations && ready;
       ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " baseline warmup");
    ready = ready &&
            test.cuda_ok(static_cast<cudaError_t>(launch_candidate()),
                         label + " candidate warmup");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return;
  }

  constexpr std::size_t kTimedPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  std::array<float, kTimedPasses> baseline_passes{};
  std::array<float, kTimedPasses> candidate_passes{};
  bool finite = true;
  for (int round = 0; round < kMeasurementRounds; ++round) {
    const std::string round_label =
        label + " round=" + std::to_string(round + 1);
    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        round_label + " B1");
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        round_label + " C1");
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        round_label + " C2");
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        round_label + " B2");
    const std::size_t pass = 2U * static_cast<std::size_t>(round);
    baseline_passes[pass] = baseline_first;
    baseline_passes[pass + 1U] = baseline_second;
    candidate_passes[pass] = candidate_first;
    candidate_passes[pass + 1U] = candidate_second;
    finite = finite && std::isfinite(baseline_first) &&
             std::isfinite(candidate_first) &&
             std::isfinite(candidate_second) &&
             std::isfinite(baseline_second);
    std::cout << "PERF_FP8_M1_Q_KV_FUSION_ROUND: round="
              << round + 1 << " order=B-C-C-B"
              << " baseline_pass1_ms=" << baseline_first
              << " candidate_pass1_ms=" << candidate_first
              << " candidate_pass2_ms=" << candidate_second
              << " baseline_pass2_ms=" << baseline_second << '\n';
  }
  const float baseline_median =
      median_fp8_kv_pair_timing(baseline_passes);
  const float candidate_median =
      median_fp8_kv_pair_timing(candidate_passes);
  const double speedup = static_cast<double>(baseline_median) /
                         static_cast<double>(candidate_median);
  const bool performance_gate = finite && std::isfinite(speedup) &&
                                baseline_median > 0.0F &&
                                candidate_median > 0.0F &&
                                speedup >= kRequiredSpeedup;
  test.expect(finite && std::isfinite(speedup) && baseline_median > 0.0F &&
                  candidate_median > 0.0F,
              label + " reports finite positive timing");
  test.expect(performance_gate,
              label + " clears the required 1.005x performance gate");
  std::cout << "PERF_FP8_M1_Q_KV_FUSION: baseline_q_plus_kv_ms="
            << baseline_median
            << " candidate_one_kernel_ms=" << candidate_median
            << " speedup=" << speedup
            << " uplift_percent=" << (speedup - 1.0) * 100.0
            << " required_speedup=" << kRequiredSpeedup
            << " bitwise=" << (bitwise_gate ? "PASS" : "FAIL")
            << " resources=" << (resource_gate ? "PASS" : "FAIL")
            << " recommendation="
            << (performance_gate ? "KEEP" : "ABANDON")
            << " gate=" << (performance_gate ? "PASS" : "FAIL") << '\n';
}

void run_optional_fp8_m1_q_kv_reduction_scratch_ping_pong_performance(
    TestContext& test, cudaStream_t stream) {
  if (!fp8_m1_q_kv_reduction_scratch_ping_pong_performance_enabled()) {
    std::cout
        << "SKIP: FP8 M1 Q+K/V reduction-scratch ping-pong gate; set "
           "Q3X_RUN_SM87_FP8_M1_Q_KV_REDUCTION_SCRATCH_PING_PONG_PERF=1 "
           "together with Q3X_FP8_M1_Q_KV_ACTUAL_CHECKPOINT_FILE to "
           "enable\n";
    return;
  }

  constexpr std::size_t kQRows = 12'288U;
  constexpr std::size_t kKvRows = 1'024U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::uint64_t kQOffset = 5'862'443'552ULL;
  constexpr std::uint64_t kKeyOffset = 5'825'743'392ULL;
  constexpr std::uint64_t kValueOffset = 5'925'358'112ULL;
  constexpr std::string_view kQSha256 =
      "6a688dbc61bfb33c1224c70b6c7b31e0429ad40d7d16d2107f5fa06dd1636d74";
  constexpr std::string_view kKeySha256 =
      "5f2b231009ca89447ac875a0f31bf9a22ef5d9e1ad900ad45bdbd3659bffa2e6";
  constexpr std::string_view kValueSha256 =
      "9c7a05577136027a738019bee827f2c8d48c6a04f53eac27657c3bacb5d7d607";
  constexpr std::size_t kGuardElements = 16U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 80;
  constexpr int kMeasurementRounds = 5;
  constexpr double kRequiredActualSpeedup = 1.01;
  constexpr double kRequiredStressSpeedup = 1.00;
  const char* const candidate_name =
      "q_kv_two_phase_reduction_scratch_ping_pong_production";
  const std::string label =
      "FP8 M1 Q12288+K/V1024 K5120 reduction-scratch ping-pong";

  const q3x::core::Sha256FileResult binary_identity =
      q3x::core::sha256_file("/proc/self/exe");
  test.expect(binary_identity.ok(), label + " hashes the running test binary");
  if (!binary_identity.ok()) {
    return;
  }
  std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_BINARY_IDENTITY: candidate="
            << candidate_name << " sha256="
            << binary_identity.digest->hex() << " gate=PASS\n";

  const auto* const fake_q_weights =
      reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
  const auto* const fake_key_weights =
      reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
  const auto* const fake_value_weights =
      reinterpret_cast<const std::uint8_t*>(0x3'0000'0000ULL);
  const auto* const fake_activation =
      reinterpret_cast<const std::uint16_t*>(0x4'0000'0000ULL);
  auto* const fake_q_output =
      reinterpret_cast<std::uint16_t*>(0x5'0000'0000ULL);
  auto* const fake_key_output =
      reinterpret_cast<std::uint16_t*>(0x6'0000'0000ULL);
  auto* const fake_value_output =
      reinterpret_cast<std::uint16_t*>(0x7'0000'0000ULL);
  const auto capture_one =
      [&](const auto& launch, const std::string& capture_label,
          cudaKernelNodeParams* const params, std::size_t* const nodes) {
        cudaGraph_t graph = nullptr;
        bool ready = test.cuda_ok(
            cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
            capture_label + " begin capture");
        cudaError_t launch_status = cudaErrorUnknown;
        if (ready) {
          launch_status = static_cast<cudaError_t>(launch());
          ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                               capture_label + " end capture") &&
                  ready;
        }
        *nodes = 0U;
        if (ready) {
          ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, nodes),
                               capture_label + " query nodes") &&
                  ready;
        }
        if (ready && *nodes == 1U && params != nullptr) {
          cudaGraphNode_t node = nullptr;
          std::size_t capacity = 1U;
          ready = test.cuda_ok(cudaGraphGetNodes(graph, &node, &capacity),
                               capture_label + " get node") &&
                  capacity == 1U &&
                  test.cuda_ok(cudaGraphKernelNodeGetParams(node, params),
                               capture_label + " get params") &&
                  ready;
        }
        if (graph != nullptr) {
          ready = test.cuda_ok(cudaGraphDestroy(graph),
                               capture_label + " destroy graph") &&
                  ready;
        }
        return std::make_pair(ready, launch_status);
      };
  const auto public_fake_launch = [&]() noexcept {
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
        fake_q_weights, 1.0F / 64.0F, fake_key_weights, 1.0F / 96.0F,
        fake_value_weights, 1.0F / 128.0F, fake_activation, kQRows, kKvRows,
        kColumns, fake_q_output, fake_key_output, fake_value_output,
        static_cast<void*>(stream));
  };
  const auto candidate_fake_launch = [&]() noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_q_kv_reduction_scratch_ping_pong_test_cuda(
            fake_q_weights, 1.0F / 64.0F, fake_key_weights, 1.0F / 96.0F,
            fake_value_weights, 1.0F / 128.0F, fake_activation, kQRows,
            kKvRows, kColumns, fake_q_output, fake_key_output,
            fake_value_output, static_cast<void*>(stream));
  };
  const auto tail_barrier_fake_launch = [&]() noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_q_kv_tail_barrier_test_cuda(
            fake_q_weights, 1.0F / 64.0F, fake_key_weights,
            1.0F / 96.0F, fake_value_weights, 1.0F / 128.0F,
            fake_activation, kQRows, kKvRows, kColumns, fake_q_output,
            fake_key_output, fake_value_output, static_cast<void*>(stream));
  };
  cudaKernelNodeParams public_params{};
  cudaKernelNodeParams candidate_params{};
  cudaKernelNodeParams tail_barrier_params{};
  std::size_t public_nodes = 0U;
  std::size_t candidate_nodes = 0U;
  std::size_t tail_barrier_nodes = 0U;
  const auto public_capture = capture_one(
      public_fake_launch, label + " public baseline", &public_params,
      &public_nodes);
  const auto candidate_capture = capture_one(
      candidate_fake_launch, label + " candidate", &candidate_params,
      &candidate_nodes);
  const auto tail_barrier_capture = capture_one(
      tail_barrier_fake_launch, label + " tail-barrier predecessor",
      &tail_barrier_params, &tail_barrier_nodes);
  const bool graph_gate =
      public_capture.first && candidate_capture.first &&
      tail_barrier_capture.first &&
      public_capture.second == cudaSuccess &&
      candidate_capture.second == cudaSuccess &&
      tail_barrier_capture.second == cudaSuccess && public_nodes == 1U &&
      candidate_nodes == 1U && tail_barrier_nodes == 1U &&
      public_params.func == candidate_params.func &&
      public_params.func != tail_barrier_params.func &&
      public_params.gridDim.x == 2'048U &&
      candidate_params.gridDim.x == public_params.gridDim.x &&
      tail_barrier_params.gridDim.x == public_params.gridDim.x &&
      public_params.gridDim.y == candidate_params.gridDim.y &&
      public_params.gridDim.y == tail_barrier_params.gridDim.y &&
      public_params.gridDim.z == candidate_params.gridDim.z &&
      public_params.gridDim.z == tail_barrier_params.gridDim.z &&
      public_params.blockDim.x == 256U &&
      candidate_params.blockDim.x == public_params.blockDim.x &&
      tail_barrier_params.blockDim.x == public_params.blockDim.x &&
      public_params.blockDim.y == candidate_params.blockDim.y &&
      public_params.blockDim.y == tail_barrier_params.blockDim.y &&
      public_params.blockDim.z == candidate_params.blockDim.z &&
      public_params.blockDim.z == tail_barrier_params.blockDim.z &&
      public_params.sharedMemBytes == 0U &&
      candidate_params.sharedMemBytes == public_params.sharedMemBytes &&
      tail_barrier_params.sharedMemBytes == public_params.sharedMemBytes;
  test.expect(graph_gate,
              label + " public/direct production hooks match and the "
                      "predecessor is distinct with identical topology");

  struct InvalidLaunchArguments {
    const std::uint8_t* q_weights;
    float q_scale;
    const std::uint8_t* key_weights;
    float key_scale;
    const std::uint8_t* value_weights;
    float value_scale;
    const std::uint16_t* activation;
    std::size_t q_rows;
    std::size_t kv_rows;
    std::size_t columns;
    std::uint16_t* q_output;
    std::uint16_t* key_output;
    std::uint16_t* value_output;
  };
  struct InvalidLaunchCase {
    std::string name;
    InvalidLaunchArguments arguments;
  };
  const InvalidLaunchArguments valid_arguments{
      fake_q_weights,     1.0F / 64.0F, fake_key_weights,
      1.0F / 96.0F,      fake_value_weights,
      1.0F / 128.0F,     fake_activation,
      kQRows,             kKvRows,
      kColumns,           fake_q_output,
      fake_key_output,    fake_value_output,
  };
  std::vector<InvalidLaunchCase> invalid_cases;
  invalid_cases.reserve(41U);
  const auto add_invalid = [&](std::string name, const auto& mutate) {
    InvalidLaunchArguments arguments = valid_arguments;
    mutate(arguments);
    invalid_cases.push_back(
        InvalidLaunchCase{std::move(name), arguments});
  };

  add_invalid("bad_q_rows", [](auto& args) { --args.q_rows; });
  add_invalid("bad_kv_rows", [](auto& args) { --args.kv_rows; });
  add_invalid("bad_columns", [](auto& args) { --args.columns; });
  add_invalid("null_q_weights",
              [](auto& args) { args.q_weights = nullptr; });
  add_invalid("null_key_weights",
              [](auto& args) { args.key_weights = nullptr; });
  add_invalid("null_value_weights",
              [](auto& args) { args.value_weights = nullptr; });
  add_invalid("null_activation",
              [](auto& args) { args.activation = nullptr; });
  add_invalid("null_q_output", [](auto& args) { args.q_output = nullptr; });
  add_invalid("null_key_output",
              [](auto& args) { args.key_output = nullptr; });
  add_invalid("null_value_output",
              [](auto& args) { args.value_output = nullptr; });

  constexpr std::array<std::pair<std::string_view, float>, 3U>
      kInvalidScales{{
          {"nan", std::numeric_limits<float>::quiet_NaN()},
          {"inf", std::numeric_limits<float>::infinity()},
          {"negative", -1.0F},
      }};
  for (const auto& invalid_scale : kInvalidScales) {
    add_invalid("q_scale_" + std::string(invalid_scale.first),
                [value = invalid_scale.second](auto& args) {
                  args.q_scale = value;
                });
    add_invalid("key_scale_" + std::string(invalid_scale.first),
                [value = invalid_scale.second](auto& args) {
                  args.key_scale = value;
                });
    add_invalid("value_scale_" + std::string(invalid_scale.first),
                [value = invalid_scale.second](auto& args) {
                  args.value_scale = value;
                });
  }

  add_invalid("misaligned_q_weights", [&](auto& args) {
    args.q_weights = reinterpret_cast<const std::uint8_t*>(
        reinterpret_cast<std::uintptr_t>(fake_q_weights) + 1U);
  });
  add_invalid("misaligned_key_weights", [&](auto& args) {
    args.key_weights = reinterpret_cast<const std::uint8_t*>(
        reinterpret_cast<std::uintptr_t>(fake_key_weights) + 1U);
  });
  add_invalid("misaligned_value_weights", [&](auto& args) {
    args.value_weights = reinterpret_cast<const std::uint8_t*>(
        reinterpret_cast<std::uintptr_t>(fake_value_weights) + 1U);
  });
  add_invalid("misaligned_activation", [&](auto& args) {
    args.activation = reinterpret_cast<const std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(fake_activation) + 2U);
  });
  add_invalid("misaligned_q_output", [&](auto& args) {
    args.q_output = reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(fake_q_output) + 1U);
  });
  add_invalid("misaligned_key_output", [&](auto& args) {
    args.key_output = reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(fake_key_output) + 1U);
  });
  add_invalid("misaligned_value_output", [&](auto& args) {
    args.value_output = reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(fake_value_output) + 1U);
  });

  add_invalid("q_key_output_alias",
              [](auto& args) { args.key_output = args.q_output; });
  add_invalid("q_value_output_alias",
              [](auto& args) { args.value_output = args.q_output; });
  add_invalid("key_value_output_alias",
              [](auto& args) { args.value_output = args.key_output; });

  const auto output_at = [](const void* const pointer) noexcept {
    return reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(pointer));
  };
  add_invalid("q_output_alias_q_weights", [&](auto& args) {
    args.q_output = output_at(fake_q_weights);
  });
  add_invalid("q_output_alias_key_weights", [&](auto& args) {
    args.q_output = output_at(fake_key_weights);
  });
  add_invalid("q_output_alias_value_weights", [&](auto& args) {
    args.q_output = output_at(fake_value_weights);
  });
  add_invalid("key_output_alias_q_weights", [&](auto& args) {
    args.key_output = output_at(fake_q_weights);
  });
  add_invalid("key_output_alias_key_weights", [&](auto& args) {
    args.key_output = output_at(fake_key_weights);
  });
  add_invalid("key_output_alias_value_weights", [&](auto& args) {
    args.key_output = output_at(fake_value_weights);
  });
  add_invalid("value_output_alias_q_weights", [&](auto& args) {
    args.value_output = output_at(fake_q_weights);
  });
  add_invalid("value_output_alias_key_weights", [&](auto& args) {
    args.value_output = output_at(fake_key_weights);
  });
  add_invalid("value_output_alias_value_weights", [&](auto& args) {
    args.value_output = output_at(fake_value_weights);
  });
  add_invalid("q_output_alias_activation", [&](auto& args) {
    args.q_output = output_at(fake_activation);
  });
  add_invalid("key_output_alias_activation", [&](auto& args) {
    args.key_output = output_at(fake_activation);
  });
  add_invalid("value_output_alias_activation", [&](auto& args) {
    args.value_output = output_at(fake_activation);
  });

  const auto launch_invalid = [&](const bool direct,
                                  const InvalidLaunchArguments& args) noexcept {
    if (direct) {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_m1_q_kv_reduction_scratch_ping_pong_test_cuda(
              args.q_weights, args.q_scale, args.key_weights, args.key_scale,
              args.value_weights, args.value_scale, args.activation,
              args.q_rows, args.kv_rows, args.columns, args.q_output,
              args.key_output, args.value_output, static_cast<void*>(stream));
    }
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
        args.q_weights, args.q_scale, args.key_weights, args.key_scale,
        args.value_weights, args.value_scale, args.activation, args.q_rows,
        args.kv_rows, args.columns, args.q_output, args.key_output,
        args.value_output, static_cast<void*>(stream));
  };
  bool invalid_zero_node_gate = true;
  std::size_t invalid_capture_count = 0U;
  std::size_t invalid_failure_count = 0U;
  for (const InvalidLaunchCase& invalid_case : invalid_cases) {
    for (unsigned int route = 0U; route < 2U; ++route) {
      const bool direct = route == 1U;
      const std::string route_name = direct ? "direct" : "public";
      std::size_t nodes = 0U;
      const auto capture = capture_one(
          [&]() noexcept {
            return launch_invalid(direct, invalid_case.arguments);
          },
          label + " invalid " + route_name + " " + invalid_case.name,
          nullptr, &nodes);
      const bool case_gate =
          capture.first && capture.second == cudaErrorInvalidValue &&
          nodes == 0U;
      invalid_zero_node_gate = invalid_zero_node_gate && case_gate;
      invalid_failure_count += case_gate ? 0U : 1U;
      ++invalid_capture_count;
      test.expect(case_gate,
                  label + " " + route_name + " rejects " +
                      invalid_case.name + " before enqueue");
    }
  }
  invalid_zero_node_gate =
      invalid_zero_node_gate && invalid_cases.size() == 41U &&
      invalid_capture_count == 82U && invalid_failure_count == 0U;
  test.expect(invalid_zero_node_gate,
              label + " freezes the full public/direct invalid table");

  Fp8KvPairKernelResources resources{};
  const bool candidate_resource_ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_q_kv_reduction_scratch_ping_pong_resources_test_cuda(
              &resources.registers_per_thread,
              &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)),
      label + " query candidate resources");
  const bool resource_gate =
      candidate_resource_ready && resources.registers_per_thread == 64 &&
      resources.static_shared_bytes == 1'280U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block == 256 &&
      resources.active_blocks_per_sm == 4;
  test.expect(resource_gate, label + " clears frozen candidate resources");
  Fp8KvPairKernelResources tail_resources{};
  const bool tail_resource_ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_q_kv_tail_barrier_resources_test_cuda(
              &tail_resources.registers_per_thread,
              &tail_resources.static_shared_bytes, &tail_resources.local_bytes,
              &tail_resources.maximum_threads_per_block,
              &tail_resources.active_blocks_per_sm)),
      label + " query tail-barrier predecessor resources");
  const bool tail_resource_gate =
      tail_resource_ready && tail_resources.registers_per_thread == 64 &&
      tail_resources.static_shared_bytes == 1'152U &&
      tail_resources.local_bytes == 0U &&
      tail_resources.maximum_threads_per_block == 256 &&
      tail_resources.active_blocks_per_sm >= 4;
  test.expect(tail_resource_gate,
              label + " freezes tail-barrier predecessor resources");
  bool ready = candidate_resource_ready && tail_resource_ready;
  const bool null_resource_gate =
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_q_kv_reduction_scratch_ping_pong_resources_test_cuda(
              nullptr, &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)) == cudaErrorInvalidValue;
  test.expect(null_resource_gate,
              label + " resource query rejects a null destination");
  std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_CONTRACT: candidate="
            << candidate_name << " public_nodes=" << public_nodes
            << " candidate_nodes=" << candidate_nodes
            << " tail_predecessor_nodes=" << tail_barrier_nodes
            << " public_direct_same_func_tail_distinct_2048x256="
            << (graph_gate ? "true" : "false")
            << " registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " maximum_threads_per_block="
            << resources.maximum_threads_per_block
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " tail_registers_per_thread="
            << tail_resources.registers_per_thread
            << " tail_static_shared_bytes="
            << tail_resources.static_shared_bytes
            << " tail_local_bytes=" << tail_resources.local_bytes
            << " tail_maximum_threads_per_block="
            << tail_resources.maximum_threads_per_block
            << " tail_active_blocks_per_sm="
            << tail_resources.active_blocks_per_sm
            << " expected_barrier_instructions=3"
            << " expected_tail_barrier_instructions=5"
            << " invalid_cases=" << invalid_cases.size()
            << " invalid_captures=" << invalid_capture_count
            << " invalid_failures=" << invalid_failure_count
            << " invalid_zero_node_gate="
            << (invalid_zero_node_gate ? "PASS" : "FAIL")
            << " tail_resource_gate="
            << (tail_resource_gate ? "PASS" : "FAIL")
            << " null_resource_gate="
            << (null_resource_gate ? "PASS" : "FAIL")
            << " gate="
            << (graph_gate && resource_gate && tail_resource_gate &&
                        invalid_zero_node_gate && null_resource_gate
                    ? "PASS"
                    : "FAIL")
            << '\n';
  if (!ready) {
    return;
  }

  const char* const checkpoint_file_value =
      std::getenv("Q3X_FP8_M1_Q_KV_ACTUAL_CHECKPOINT_FILE");
  const bool checkpoint_source_gate =
      checkpoint_file_value != nullptr && checkpoint_file_value[0] != '\0';
  test.expect(checkpoint_source_gate,
              label + " requires the pinned actual checkpoint shard");
  if (!checkpoint_source_gate) {
    return;
  }
  const std::string checkpoint_file = checkpoint_file_value;

  std::vector<std::uint8_t> host_q_weights(kQRows * kColumns);
  std::vector<std::uint8_t> host_key_weights(kKvRows * kColumns);
  std::vector<std::uint8_t> host_value_weights(kKvRows * kColumns);
  std::vector<std::uint16_t> host_activation(kColumns);
  const auto fill_activation = [&]() {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + (column >> 3U) * 5U + 7U) %
                           127U) -
          63;
      host_activation[column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  };
  fill_activation();

  DeviceBuffer<std::uint8_t> q_weights;
  DeviceBuffer<std::uint8_t> key_weights;
  DeviceBuffer<std::uint8_t> value_weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_q_output;
  DeviceBuffer<std::uint16_t> baseline_key_output;
  DeviceBuffer<std::uint16_t> baseline_value_output;
  DeviceBuffer<std::uint16_t> candidate_q_storage;
  DeviceBuffer<std::uint16_t> candidate_key_storage;
  DeviceBuffer<std::uint16_t> candidate_value_storage;
  ready = test.cuda_ok(q_weights.allocate(host_q_weights.size()),
                       label + " allocate Q weights");
  ready = ready && test.cuda_ok(key_weights.allocate(host_key_weights.size()),
                                label + " allocate K weights");
  ready = ready &&
          test.cuda_ok(value_weights.allocate(host_value_weights.size()),
                       label + " allocate V weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_q_output.allocate(kQRows),
                                label + " allocate baseline Q output");
  ready = ready && test.cuda_ok(baseline_key_output.allocate(kKvRows),
                                label + " allocate baseline K output");
  ready = ready && test.cuda_ok(baseline_value_output.allocate(kKvRows),
                                label + " allocate baseline V output");
  ready = ready && test.cuda_ok(
                       candidate_q_storage.allocate(kQRows +
                                                    2U * kGuardElements),
                       label + " allocate guarded candidate Q output");
  ready = ready && test.cuda_ok(
                       candidate_key_storage.allocate(kKvRows +
                                                      2U * kGuardElements),
                       label + " allocate guarded candidate K output");
  ready = ready && test.cuda_ok(
                       candidate_value_storage.allocate(kKvRows +
                                                        2U * kGuardElements),
                       label + " allocate guarded candidate V output");
  if (!ready) {
    return;
  }
  std::uint16_t* const candidate_q_output =
      candidate_q_storage.get() + kGuardElements;
  std::uint16_t* const candidate_key_output =
      candidate_key_storage.get() + kGuardElements;
  std::uint16_t* const candidate_value_output =
      candidate_value_storage.get() + kGuardElements;
  float q_scale = 1.0F / 64.0F;
  float key_scale = 1.0F / 96.0F;
  float value_scale = 1.0F / 128.0F;
  const auto launch_baseline = [&]() noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_q_kv_tail_barrier_test_cuda(
            q_weights.get(), q_scale, key_weights.get(), key_scale,
            value_weights.get(), value_scale, activation.get(), kQRows,
            kKvRows, kColumns, baseline_q_output.get(),
            baseline_key_output.get(), baseline_value_output.get(),
            static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept {
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
        q_weights.get(), q_scale, key_weights.get(), key_scale,
        value_weights.get(), value_scale, activation.get(), kQRows, kKvRows,
        kColumns, candidate_q_output, candidate_key_output,
        candidate_value_output, static_cast<void*>(stream));
  };

  std::vector<std::uint16_t> baseline_q(kQRows);
  std::vector<std::uint16_t> baseline_key(kKvRows);
  std::vector<std::uint16_t> baseline_value(kKvRows);
  std::vector<std::uint16_t> first_q(kQRows + 2U * kGuardElements);
  std::vector<std::uint16_t> first_key(kKvRows + 2U * kGuardElements);
  std::vector<std::uint16_t> first_value(kKvRows + 2U * kGuardElements);
  std::vector<std::uint16_t> replay_q(first_q.size());
  std::vector<std::uint16_t> replay_key(first_key.size());
  std::vector<std::uint16_t> replay_value(first_value.size());

  const auto capture_baseline = [&](const std::string& fixture_label) {
    bool fixture_ready = test.cuda_ok(
        static_cast<cudaError_t>(launch_baseline()),
        fixture_label + " launch tail-barrier predecessor");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(baseline_q.data(), baseline_q_output.get(),
                        baseline_q.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy baseline Q");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(baseline_key.data(), baseline_key_output.get(),
                        baseline_key.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy baseline K");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(baseline_value.data(), baseline_value_output.get(),
                        baseline_value.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy baseline V");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), fixture_label + " baseline sync");
    return fixture_ready;
  };

  const auto check_candidate = [&](const std::string& fixture_label,
                                   const bool preserve_inputs,
                                   const bool require_finite) {
    bool fixture_ready = test.cuda_ok(
        cudaMemsetAsync(candidate_q_storage.get(), 0xa5,
                        first_q.size() * sizeof(std::uint16_t), stream),
        fixture_label + " poison first Q");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_key_storage.get(), 0x5a,
                        first_key.size() * sizeof(std::uint16_t), stream),
        fixture_label + " poison first K");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_value_storage.get(), 0x3c,
                        first_value.size() * sizeof(std::uint16_t), stream),
        fixture_label + " poison first V");
    fixture_ready = fixture_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_candidate()),
        fixture_label + " candidate first launch");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(first_q.data(), candidate_q_storage.get(),
                        first_q.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy first Q");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(first_key.data(), candidate_key_storage.get(),
                        first_key.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy first K");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(first_value.data(), candidate_value_storage.get(),
                        first_value.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy first V");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_q_storage.get(), 0x1b,
                        replay_q.size() * sizeof(std::uint16_t), stream),
        fixture_label + " poison replay Q");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_key_storage.get(), 0xe4,
                        replay_key.size() * sizeof(std::uint16_t), stream),
        fixture_label + " poison replay K");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_value_storage.get(), 0x96,
                        replay_value.size() * sizeof(std::uint16_t), stream),
        fixture_label + " poison replay V");
    fixture_ready = fixture_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_candidate()),
        fixture_label + " candidate replay launch");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(replay_q.data(), candidate_q_storage.get(),
                        replay_q.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy replay Q");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(replay_key.data(), candidate_key_storage.get(),
                        replay_key.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy replay K");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(replay_value.data(), candidate_value_storage.get(),
                        replay_value.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy replay V");
    std::vector<std::uint8_t> observed_q;
    std::vector<std::uint8_t> observed_key;
    std::vector<std::uint8_t> observed_value;
    std::vector<std::uint16_t> observed_activation;
    if (preserve_inputs) {
      observed_q.resize(host_q_weights.size());
      observed_key.resize(host_key_weights.size());
      observed_value.resize(host_value_weights.size());
      observed_activation.resize(host_activation.size());
      fixture_ready = fixture_ready && test.cuda_ok(
          cudaMemcpyAsync(observed_q.data(), q_weights.get(),
                          observed_q.size(), cudaMemcpyDeviceToHost, stream),
          fixture_label + " copy preserved Q weights");
      fixture_ready = fixture_ready && test.cuda_ok(
          cudaMemcpyAsync(observed_key.data(), key_weights.get(),
                          observed_key.size(), cudaMemcpyDeviceToHost, stream),
          fixture_label + " copy preserved K weights");
      fixture_ready = fixture_ready && test.cuda_ok(
          cudaMemcpyAsync(observed_value.data(), value_weights.get(),
                          observed_value.size(), cudaMemcpyDeviceToHost,
                          stream),
          fixture_label + " copy preserved V weights");
      fixture_ready = fixture_ready && test.cuda_ok(
          cudaMemcpyAsync(observed_activation.data(), activation.get(),
                          observed_activation.size() * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
          fixture_label + " copy preserved activation");
    }
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), fixture_label + " candidate sync");
    if (!fixture_ready) {
      return false;
    }
    std::size_t q_mismatches = 0U;
    std::size_t key_mismatches = 0U;
    std::size_t value_mismatches = 0U;
    std::size_t replay_mismatches = 0U;
    std::size_t nonfinite = 0U;
    for (std::size_t row = 0U; row < kQRows; ++row) {
      const std::uint16_t first = first_q[kGuardElements + row];
      const std::uint16_t replay = replay_q[kGuardElements + row];
      q_mismatches += baseline_q[row] != first ? 1U : 0U;
      replay_mismatches += first != replay ? 1U : 0U;
      nonfinite += !is_bf16_finite(first) ? 1U : 0U;
    }
    for (std::size_t row = 0U; row < kKvRows; ++row) {
      const std::uint16_t first_k = first_key[kGuardElements + row];
      const std::uint16_t replay_k = replay_key[kGuardElements + row];
      const std::uint16_t first_v = first_value[kGuardElements + row];
      const std::uint16_t replay_v = replay_value[kGuardElements + row];
      key_mismatches += baseline_key[row] != first_k ? 1U : 0U;
      value_mismatches += baseline_value[row] != first_v ? 1U : 0U;
      replay_mismatches += first_k != replay_k ? 1U : 0U;
      replay_mismatches += first_v != replay_v ? 1U : 0U;
      nonfinite += !is_bf16_finite(first_k) ? 1U : 0U;
      nonfinite += !is_bf16_finite(first_v) ? 1U : 0U;
    }
    bool guards_intact = true;
    for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
      guards_intact =
          guards_intact && first_q[guard] == 0xa5a5U &&
          first_q[kGuardElements + kQRows + guard] == 0xa5a5U &&
          first_key[guard] == 0x5a5aU &&
          first_key[kGuardElements + kKvRows + guard] == 0x5a5aU &&
          first_value[guard] == 0x3c3cU &&
          first_value[kGuardElements + kKvRows + guard] == 0x3c3cU &&
          replay_q[guard] == 0x1b1bU &&
          replay_q[kGuardElements + kQRows + guard] == 0x1b1bU &&
          replay_key[guard] == 0xe4e4U &&
          replay_key[kGuardElements + kKvRows + guard] == 0xe4e4U &&
          replay_value[guard] == 0x9696U &&
          replay_value[kGuardElements + kKvRows + guard] == 0x9696U;
    }
    const bool inputs_preserved =
        !preserve_inputs ||
        (observed_q == host_q_weights &&
         observed_key == host_key_weights &&
         observed_value == host_value_weights &&
         observed_activation == host_activation);
    const bool bitwise = q_mismatches == 0U && key_mismatches == 0U &&
                         value_mismatches == 0U;
    const bool replay_gate = replay_mismatches == 0U;
    const bool finite_gate = !require_finite || nonfinite == 0U;
    test.expect(bitwise, fixture_label + " is bitwise Q/K/V identical");
    test.expect(replay_gate,
                fixture_label + " is stable after output poison replay");
    test.expect(guards_intact, fixture_label + " preserves all canaries");
    test.expect(inputs_preserved, fixture_label + " preserves all inputs");
    if (require_finite) {
      test.expect(finite_gate, fixture_label + " keeps outputs finite");
    }
    std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_DIFF: candidate="
              << candidate_name << " fixture=" << fixture_label
              << " q_mismatches=" << q_mismatches << '/' << kQRows
              << " key_mismatches=" << key_mismatches << '/' << kKvRows
              << " value_mismatches=" << value_mismatches << '/' << kKvRows
              << " replay_mismatches=" << replay_mismatches << '/'
              << (kQRows + 2U * kKvRows)
              << " guards=" << (guards_intact ? "intact" : "BAD")
              << " inputs_preserved="
              << (inputs_preserved ? "true" : "false")
              << " nonfinite_outputs=" << nonfinite << " gate="
              << (bitwise && replay_gate && guards_intact &&
                          inputs_preserved && finite_gate
                      ? "PASS"
                      : "FAIL")
              << '\n';
    return bitwise && replay_gate && guards_intact && inputs_preserved &&
           finite_gate;
  };

  const auto read_checkpoint_slice =
      [&](const std::uint64_t offset,
          std::vector<std::uint8_t>& destination,
          const std::string& tensor_label) {
        std::ifstream input(checkpoint_file, std::ios::binary);
        if (!input.is_open()) {
          test.expect(false, label + " opens checkpoint for " + tensor_label);
          return false;
        }
        input.seekg(0, std::ios::end);
        const std::streamoff file_size = input.tellg();
        const bool range_valid =
            file_size >= 0 && offset <= static_cast<std::uint64_t>(file_size) &&
            destination.size() <=
                static_cast<std::uint64_t>(file_size) - offset;
        test.expect(range_valid,
                    label + " checkpoint contains " + tensor_label);
        if (!range_valid) {
          return false;
        }
        input.seekg(static_cast<std::streamoff>(offset), std::ios::beg);
        input.read(reinterpret_cast<char*>(destination.data()),
                   static_cast<std::streamsize>(destination.size()));
        const bool complete = input.gcount() ==
                              static_cast<std::streamsize>(destination.size());
        test.expect(complete, label + " reads complete " + tensor_label);
        return complete;
      };

  struct DistributionResult {
    float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
    float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
    bool correct = false;
  };
  const auto benchmark = [&](const std::string& fixture_label) {
    DistributionResult result{};
    bool timing_ready = true;
    for (int iteration = 0;
         iteration < kWarmupIterations && timing_ready; ++iteration) {
      timing_ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_baseline()),
          fixture_label + " baseline warmup");
      timing_ready = timing_ready && test.cuda_ok(
          static_cast<cudaError_t>(launch_candidate()),
          fixture_label + " candidate warmup");
    }
    timing_ready = timing_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), fixture_label + " warmup sync");
    if (!timing_ready) {
      return result;
    }
    constexpr std::size_t kPasses =
        2U * static_cast<std::size_t>(kMeasurementRounds);
    std::array<float, kPasses> baseline_passes{};
    std::array<float, kPasses> candidate_passes{};
    bool finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          fixture_label + " round=" + std::to_string(round + 1);
      const float b1 = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " B1");
      const float c1 = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " C1");
      const float c2 = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " C2");
      const float b2 = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " B2");
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      baseline_passes[pass] = b1;
      baseline_passes[pass + 1U] = b2;
      candidate_passes[pass] = c1;
      candidate_passes[pass + 1U] = c2;
      finite = finite && std::isfinite(b1) && std::isfinite(c1) &&
               std::isfinite(c2) && std::isfinite(b2);
      std::cout << "PERF_FP8_M1_Q_KV_REDUCTION_SCRATCH_ROUND: candidate="
                << candidate_name << " fixture=" << fixture_label
                << " round=" << round + 1 << " order=B-C-C-B"
                << " logical_launches_per_pass=" << kMeasuredIterations
                << " baseline_pass1_ms=" << b1
                << " candidate_pass1_ms=" << c1
                << " candidate_pass2_ms=" << c2
                << " baseline_pass2_ms=" << b2 << '\n';
    }
    if (finite) {
      result.baseline_milliseconds =
          median_fp8_kv_pair_timing(baseline_passes);
      result.candidate_milliseconds =
          median_fp8_kv_pair_timing(candidate_passes);
    }
    return result;
  };

  const auto upload_current_fixture = [&](const std::string& fixture_label) {
    bool fixture_ready = test.cuda_ok(
        cudaMemcpyAsync(q_weights.get(), host_q_weights.data(),
                        host_q_weights.size(), cudaMemcpyHostToDevice, stream),
        fixture_label + " upload Q weights");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(key_weights.get(), host_key_weights.data(),
                        host_key_weights.size(), cudaMemcpyHostToDevice,
                        stream),
        fixture_label + " upload K weights");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(value_weights.get(), host_value_weights.data(),
                        host_value_weights.size(), cudaMemcpyHostToDevice,
                        stream),
        fixture_label + " upload V weights");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(activation.get(), host_activation.data(),
                        host_activation.size() * sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        fixture_label + " upload activation");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), fixture_label + " upload sync");
    return fixture_ready;
  };

  // Exercise every finite E4M3FN byte in all four positions of the packed-x4
  // loads independently for Q, K, and V. The isolated signed-NaN fixture
  // below completes the raw 256-code coverage without making every row NaN.
  std::array<std::array<bool, 256U>, 4U> q_code_coverage{};
  std::array<std::array<bool, 256U>, 4U> key_code_coverage{};
  std::array<std::array<bool, 256U>, 4U> value_code_coverage{};
  const auto finite_code = [](const std::size_t index) noexcept {
    const std::size_t finite_index = index % 254U;
    return static_cast<std::uint8_t>(
        finite_index < 127U ? finite_index : finite_index + 1U);
  };
  for (std::size_t row = 0U; row < kQRows; ++row) {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const std::size_t byte_position = column & 3U;
      const std::uint8_t code =
          finite_code((column >> 2U) * 5U + row * 13U);
      host_q_weights[row * kColumns + column] = code;
      q_code_coverage[byte_position][code] = true;
    }
  }
  for (std::size_t row = 0U; row < kKvRows; ++row) {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const std::size_t byte_position = column & 3U;
      const std::uint8_t key_code =
          finite_code((column >> 2U) * 7U + row * 11U + 3U);
      const std::uint8_t value_code =
          finite_code((column >> 2U) * 9U + row * 17U + 5U);
      host_key_weights[row * kColumns + column] = key_code;
      host_value_weights[row * kColumns + column] = value_code;
      key_code_coverage[byte_position][key_code] = true;
      value_code_coverage[byte_position][value_code] = true;
    }
  }
  bool finite_coverage_gate = true;
  for (std::size_t byte_position = 0U; byte_position < 4U;
       ++byte_position) {
    const std::size_t q_codes = static_cast<std::size_t>(std::count(
        q_code_coverage[byte_position].begin(),
        q_code_coverage[byte_position].end(), true));
    const std::size_t key_codes = static_cast<std::size_t>(std::count(
        key_code_coverage[byte_position].begin(),
        key_code_coverage[byte_position].end(), true));
    const std::size_t value_codes = static_cast<std::size_t>(std::count(
        value_code_coverage[byte_position].begin(),
        value_code_coverage[byte_position].end(), true));
    const bool position_gate =
        q_codes == 254U && key_codes == 254U && value_codes == 254U &&
        !q_code_coverage[byte_position][0x7fU] &&
        !q_code_coverage[byte_position][0xffU] &&
        !key_code_coverage[byte_position][0x7fU] &&
        !key_code_coverage[byte_position][0xffU] &&
        !value_code_coverage[byte_position][0x7fU] &&
        !value_code_coverage[byte_position][0xffU];
    finite_coverage_gate = finite_coverage_gate && position_gate;
    test.expect(position_gate,
                label + " covers all 254 finite codes in packed byte " +
                    std::to_string(byte_position));
    std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_CODE_COVERAGE: candidate="
              << candidate_name << " phase=finite"
              << " byte_position=" << byte_position
              << " q_codes=" << q_codes << " key_codes=" << key_codes
              << " value_codes=" << value_codes
              << " gate=" << (position_gate ? "PASS" : "FAIL") << '\n';
  }
  q_scale = 1.0F / 64.0F;
  key_scale = 1.0F / 96.0F;
  value_scale = 1.0F / 128.0F;
  const std::string exhaustive_label = label + " exhaustive finite 254x4x3";
  if (!upload_current_fixture(exhaustive_label) ||
      !capture_baseline(exhaustive_label)) {
    return;
  }
  const bool exhaustive_finite_gate =
      finite_coverage_gate &&
      check_candidate(exhaustive_label, true, true);

  // Neighboring Q row quads and the Q-to-K/V phase handoff receive distinct
  // signs/magnitudes. The poison replay is intended to expose an incorrect
  // scratch-slot reset or reuse even when one execution happens to serialize.
  constexpr std::array<std::uint8_t, 4U> kQRaceCodes{{
      0x30U, 0x38U, 0x40U, 0x48U,
  }};
  constexpr std::array<std::uint8_t, 4U> kKeyRaceCodes{{
      0xb8U, 0xc8U, 0xb0U, 0xc0U,
  }};
  constexpr std::array<std::uint8_t, 4U> kValueRaceCodes{{
      0x34U, 0x44U, 0xb4U, 0xc4U,
  }};
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered = static_cast<int>((column * 13U + 5U) % 31U) - 15;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 32.0F);
  }
  for (std::size_t row = 0U; row < kQRows; ++row) {
    const std::uint8_t code =
        kQRaceCodes[((row / 4U) + (row & 3U)) & 3U];
    std::fill_n(host_q_weights.data() + row * kColumns, kColumns, code);
  }
  for (std::size_t row = 0U; row < kKvRows; ++row) {
    const std::uint8_t key_code =
        kKeyRaceCodes[((row / 2U) + (row & 1U)) & 3U];
    const std::uint8_t value_code =
        kValueRaceCodes[(3U * (row / 2U) + (row & 1U)) & 3U];
    std::fill_n(host_key_weights.data() + row * kColumns, kColumns,
                key_code);
    std::fill_n(host_value_weights.data() + row * kColumns, kColumns,
                value_code);
  }
  const std::string race_label = label + " scratch race signature";
  if (!upload_current_fixture(race_label) ||
      !capture_baseline(race_label)) {
    return;
  }
  const bool race_signature_gate = check_candidate(race_label, true, true);
  std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_RACE_SIGNATURE: candidate="
            << candidate_name
            << " q_row_quad_handoff=true q_to_kv_handoff=true"
            << " executions=2 replay_after_poison=true gate="
            << (race_signature_gate ? "PASS" : "FAIL") << '\n';

  std::fill(host_q_weights.begin(), host_q_weights.end(), 0U);
  std::fill(host_key_weights.begin(), host_key_weights.end(), 0U);
  std::fill(host_value_weights.begin(), host_value_weights.end(), 0U);
  std::fill(host_activation.begin(), host_activation.end(),
            encode_bf16(0.0F));
  for (std::size_t byte_position = 0U; byte_position < 4U;
       ++byte_position) {
    host_activation[byte_position] = encode_bf16(1.0F);
    for (std::size_t nan_index = 0U; nan_index < 2U; ++nan_index) {
      const std::uint8_t code = nan_index == 0U ? 0x7fU : 0xffU;
      const std::size_t row = 2U * byte_position + nan_index;
      host_q_weights[row * kColumns + byte_position] = code;
      host_key_weights[row * kColumns + byte_position] = code;
      host_value_weights[row * kColumns + byte_position] = code;
      q_code_coverage[byte_position][code] = true;
      key_code_coverage[byte_position][code] = true;
      value_code_coverage[byte_position][code] = true;
    }
  }
  bool full_code_coverage_gate = true;
  for (std::size_t byte_position = 0U; byte_position < 4U;
       ++byte_position) {
    const std::size_t q_codes = static_cast<std::size_t>(std::count(
        q_code_coverage[byte_position].begin(),
        q_code_coverage[byte_position].end(), true));
    const std::size_t key_codes = static_cast<std::size_t>(std::count(
        key_code_coverage[byte_position].begin(),
        key_code_coverage[byte_position].end(), true));
    const std::size_t value_codes = static_cast<std::size_t>(std::count(
        value_code_coverage[byte_position].begin(),
        value_code_coverage[byte_position].end(), true));
    const bool position_gate =
        q_codes == 256U && key_codes == 256U && value_codes == 256U;
    full_code_coverage_gate = full_code_coverage_gate && position_gate;
    test.expect(position_gate,
                label + " completes raw-code coverage in packed byte " +
                    std::to_string(byte_position));
    std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_CODE_COVERAGE: candidate="
              << candidate_name << " phase=complete_with_signed_nan"
              << " byte_position=" << byte_position
              << " q_codes=" << q_codes << " key_codes=" << key_codes
              << " value_codes=" << value_codes
              << " gate=" << (position_gate ? "PASS" : "FAIL") << '\n';
  }
  const std::string nan_label = label + " isolated signed NaN x4 bytes x3";
  if (!upload_current_fixture(nan_label) ||
      !capture_baseline(nan_label)) {
    return;
  }
  const bool nan_bitwise_gate = check_candidate(nan_label, true, false);
  bool nan_class_sign_gate = true;
  for (std::size_t byte_position = 0U; byte_position < 4U;
       ++byte_position) {
    for (std::size_t nan_index = 0U; nan_index < 2U; ++nan_index) {
      const std::size_t row = 2U * byte_position + nan_index;
      const auto classified = [](const std::uint16_t candidate_bits,
                                 const std::uint16_t baseline_bits) {
        return is_bf16_nan(candidate_bits) &&
               is_bf16_nan(baseline_bits) &&
               (candidate_bits & 0x8000U) ==
                   (baseline_bits & 0x8000U);
      };
      const bool row_gate =
          classified(first_q[kGuardElements + row], baseline_q[row]) &&
          classified(first_key[kGuardElements + row], baseline_key[row]) &&
          classified(first_value[kGuardElements + row], baseline_value[row]);
      nan_class_sign_gate = nan_class_sign_gate && row_gate;
      test.expect(row_gate,
                  nan_label + " preserves NaN class/sign byte=" +
                      std::to_string(byte_position) + " code=" +
                      (nan_index == 0U ? "0x7f" : "0xff"));
    }
  }
  std::size_t unexpected_nonfinite = 0U;
  for (std::size_t row = 8U; row < kQRows; ++row) {
    unexpected_nonfinite +=
        !is_bf16_finite(first_q[kGuardElements + row]) ? 1U : 0U;
  }
  for (std::size_t row = 8U; row < kKvRows; ++row) {
    unexpected_nonfinite +=
        !is_bf16_finite(first_key[kGuardElements + row]) ? 1U : 0U;
    unexpected_nonfinite +=
        !is_bf16_finite(first_value[kGuardElements + row]) ? 1U : 0U;
  }
  const bool nan_gate = nan_bitwise_gate && nan_class_sign_gate &&
                        full_code_coverage_gate &&
                        unexpected_nonfinite == 0U;
  test.expect(nan_gate,
              nan_label + " isolates all 24 signed-NaN outputs");
  std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_NAN_CLASSIFICATION: candidate="
            << candidate_name << " classified_outputs=24"
            << " unexpected_nonfinite=" << unexpected_nonfinite
            << " bitwise_replay_guards_inputs="
            << (nan_bitwise_gate ? "PASS" : "FAIL")
            << " class_sign=" << (nan_class_sign_gate ? "PASS" : "FAIL")
            << " gate=" << (nan_gate ? "PASS" : "FAIL") << '\n';
  const bool correctness_gate = exhaustive_finite_gate &&
                                race_signature_gate && nan_gate;
  fill_activation();

  constexpr std::array<Fp8M2CodeDistribution, 2U> kDistributions{{
      Fp8M2CodeDistribution::kCheckpointLike,
      Fp8M2CodeDistribution::kSameBankStress,
  }};
  std::array<DistributionResult, kDistributions.size()> results{};
  bool distribution_gate = true;
  for (std::size_t distribution_index = 0U;
       distribution_index < kDistributions.size(); ++distribution_index) {
    const Fp8M2CodeDistribution distribution =
        kDistributions[distribution_index];
    const bool actual =
        distribution == Fp8M2CodeDistribution::kCheckpointLike;
    const std::string distribution_name =
        actual ? "actual_checkpoint" : "same_bank_stress";
    bool fixture_ready = true;
    if (actual) {
      fixture_ready =
          read_checkpoint_slice(kQOffset, host_q_weights, "layer-3 Q weights");
      fixture_ready = fixture_ready && read_checkpoint_slice(
                                           kKeyOffset, host_key_weights,
                                           "layer-3 K weights");
      fixture_ready = fixture_ready && read_checkpoint_slice(
                                           kValueOffset, host_value_weights,
                                           "layer-3 V weights");
      q_scale = 0.000706264F;
      key_scale = 0.00044686455F;
      value_scale = 0.0004752023F;
    } else {
      fill_fp8_m2_code_distribution(host_q_weights, kQRows, kColumns,
                                    distribution);
      fill_fp8_m2_code_distribution(host_key_weights, kKvRows, kColumns,
                                    distribution);
      fill_fp8_m2_code_distribution(host_value_weights, kKvRows, kColumns,
                                    distribution);
      std::reverse(host_value_weights.begin(), host_value_weights.end());
      q_scale = 1.0F / 64.0F;
      key_scale = 1.0F / 96.0F;
      value_scale = 1.0F / 128.0F;
    }
    const std::string q_hash = q3x::core::sha256(std::string_view(
        reinterpret_cast<const char*>(host_q_weights.data()),
        host_q_weights.size())).hex();
    const std::string key_hash = q3x::core::sha256(std::string_view(
        reinterpret_cast<const char*>(host_key_weights.data()),
        host_key_weights.size())).hex();
    const std::string value_hash = q3x::core::sha256(std::string_view(
        reinterpret_cast<const char*>(host_value_weights.data()),
        host_value_weights.size())).hex();
    const bool identity_gate =
        !actual || (q_hash == kQSha256 && key_hash == kKeySha256 &&
                    value_hash == kValueSha256);
    test.expect(identity_gate,
                label + " matches pinned layer-3 Q/K/V payload hashes");
    fixture_ready = fixture_ready && identity_gate;
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(q_weights.get(), host_q_weights.data(),
                        host_q_weights.size(), cudaMemcpyHostToDevice, stream),
        label + " upload " + distribution_name + " Q weights");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(key_weights.get(), host_key_weights.data(),
                        host_key_weights.size(), cudaMemcpyHostToDevice,
                        stream),
        label + " upload " + distribution_name + " K weights");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(value_weights.get(), host_value_weights.data(),
                        host_value_weights.size(), cudaMemcpyHostToDevice,
                        stream),
        label + " upload " + distribution_name + " V weights");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaMemcpyAsync(activation.get(), host_activation.data(),
                        host_activation.size() * sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        label + " upload " + distribution_name + " activation");
    fixture_ready = fixture_ready && test.cuda_ok(
        cudaStreamSynchronize(stream),
        label + " upload " + distribution_name + " sync");
    std::cout << "FP8_M1_Q_KV_REDUCTION_SCRATCH_FIXTURE: candidate="
              << candidate_name << " fixture=" << distribution_name
              << " source=" << (actual ? "actual_checkpoint" : "synthetic")
              << " checkpoint_path="
              << (actual ? checkpoint_file : "not_applicable")
              << " q_offset=" << (actual ? kQOffset : 0U)
              << " key_offset=" << (actual ? kKeyOffset : 0U)
              << " value_offset=" << (actual ? kValueOffset : 0U)
              << " q_sha256=" << q_hash << " key_sha256=" << key_hash
              << " value_sha256=" << value_hash
              << " q_scale=" << q_scale << " key_scale=" << key_scale
              << " value_scale=" << value_scale
              << " pinned_payload_identity="
              << (identity_gate ? "PASS" : "FAIL") << '\n';
    if (!fixture_ready ||
        !capture_baseline(label + " " + distribution_name)) {
      return;
    }
    results[distribution_index].correct = check_candidate(
        label + " " + distribution_name, true, true);
    const DistributionResult timing =
        benchmark(label + " " + distribution_name);
    results[distribution_index].baseline_milliseconds =
        timing.baseline_milliseconds;
    results[distribution_index].candidate_milliseconds =
        timing.candidate_milliseconds;
    const double speedup =
        static_cast<double>(timing.baseline_milliseconds) /
        static_cast<double>(timing.candidate_milliseconds);
    const double required =
        actual ? kRequiredActualSpeedup : kRequiredStressSpeedup;
    const bool cell_gate = results[distribution_index].correct &&
                           std::isfinite(speedup) && speedup >= required;
    distribution_gate = distribution_gate && cell_gate;
    std::cout << "PERF_FP8_M1_Q_KV_REDUCTION_SCRATCH: candidate="
              << candidate_name << " fixture=" << distribution_name
              << " baseline_tail_barrier_predecessor_median_ms="
              << timing.baseline_milliseconds
              << " candidate_ping_pong_median_ms="
              << timing.candidate_milliseconds << " speedup=" << speedup
              << " uplift_percent=" << (speedup - 1.0) * 100.0
              << " required_speedup=" << required
              << " bitwise_replay_guards_inputs="
              << (results[distribution_index].correct ? "PASS" : "FAIL")
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  const bool selected_gate =
      graph_gate && invalid_zero_node_gate && resource_gate &&
      tail_resource_gate && null_resource_gate && checkpoint_source_gate &&
      correctness_gate && distribution_gate;
  test.expect(selected_gate,
              label + " clears contract, correctness, actual checkpoint, "
                      "stress, and performance gates");
  std::cout << "PERF_FP8_M1_Q_KV_REDUCTION_SCRATCH_SELECTED: candidate="
            << candidate_name
            << " q_shape=12288x5120 key_shape=1024x5120"
            << " value_shape=1024x5120 grid=2048 block=256"
            << " baseline=tail_barrier_predecessor"
            << " checkpoint_path=" << checkpoint_file
            << " required_actual_checkpoint_speedup="
            << kRequiredActualSpeedup
            << " required_same_bank_stress_speedup="
            << kRequiredStressSpeedup
            << " graph_gate=" << (graph_gate ? "PASS" : "FAIL")
            << " resource_gate=" << (resource_gate ? "PASS" : "FAIL")
            << " tail_resource_gate="
            << (tail_resource_gate ? "PASS" : "FAIL")
            << " invalid_zero_node_gate="
            << (invalid_zero_node_gate ? "PASS" : "FAIL")
            << " null_resource_gate="
            << (null_resource_gate ? "PASS" : "FAIL")
            << " exhaustive_256x4x3_gate="
            << (correctness_gate ? "PASS" : "FAIL")
            << " race_signature_gate="
            << (race_signature_gate ? "PASS" : "FAIL")
            << " distribution_gates="
            << (distribution_gate ? "PASS" : "FAIL")
            << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
}

[[nodiscard]] bool build_fp8_m1_aosoa4_preswizzled_sidecar(
    const std::vector<std::uint8_t>& weights, std::size_t rows,
    std::size_t columns, std::size_t guard_bytes,
    std::uint8_t guard_value,
    std::vector<std::uint8_t>& guarded_sidecar);

void run_decode_fp8_q_kv_aosoa4_screen(TestContext& test,
                                       cudaStream_t stream) {
  const bool standalone_mode =
      decode_fp8_q_kv_aosoa4_performance_enabled();
  const bool cta512_mode =
      decode_fp8_q_kv_aosoa4_cta512_performance_enabled();
  if (!standalone_mode && !cta512_mode) {
    std::cout
        << "SKIP: Decode FP8 Q+K/V AoSoA4/preswizzled sidecar screen; "
           "set Q3X_RUN_SM87_DECODE_FP8_Q_KV_AOSOA4_PERF=1 or "
           "Q3X_RUN_SM87_DECODE_FP8_Q_KV_AOSOA4_CTA512_PERF=1 together "
           "with Q3X_FP8_M1_Q_KV_ACTUAL_CHECKPOINT_FILE to enable\n";
    return;
  }

  constexpr std::size_t kQRows = 12'288U;
  constexpr std::size_t kKvRows = 1'024U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kQBytes = kQRows * kColumns;
  constexpr std::size_t kKvBytes = kKvRows * kColumns;
  constexpr std::size_t kKvSidecarBytes = 2U * kKvBytes;
  constexpr std::size_t kGuardElements = 16U;
  constexpr std::uint64_t kQOffset = 5'862'443'552ULL;
  constexpr std::uint64_t kKeyOffset = 5'825'743'392ULL;
  constexpr std::uint64_t kValueOffset = 5'925'358'112ULL;
  constexpr std::string_view kQSha256 =
      "6a688dbc61bfb33c1224c70b6c7b31e0429ad40d7d16d2107f5fa06dd1636d74";
  constexpr std::string_view kKeySha256 =
      "5f2b231009ca89447ac875a0f31bf9a22ef5d9e1ad900ad45bdbd3659bffa2e6";
  constexpr std::string_view kValueSha256 =
      "9c7a05577136027a738019bee827f2c8d48c6a04f53eac27657c3bacb5d7d607";
  constexpr float kQScale = 0.000706264F;
  constexpr float kKeyScale = 0.00044686455F;
  constexpr float kValueScale = 0.0004752023F;
  const std::string candidate_name =
      cta512_mode ? "aosoa4_preswizzled_cta512"
                  : "aosoa4_preswizzled_standalone";
  const std::string label =
      "Decode FP8 Q12288+K/V1024 K5120 " + candidate_name;
  const std::size_t candidate_static_shared_bytes =
      cta512_mode ? 1'536U : 1'280U;
  const int candidate_maximum_threads_per_block =
      cta512_mode ? 512 : 256;
  const int candidate_active_blocks_per_sm = cta512_mode ? 2 : 4;
  const unsigned int candidate_grid_x = cta512_mode ? 1'024U : 2'048U;
  const unsigned int candidate_block_x = cta512_mode ? 512U : 256U;

  const q3x::core::Sha256FileResult binary_identity =
      q3x::core::sha256_file("/proc/self/exe");
  test.expect(binary_identity.ok(), label + " hashes the running binary");
  if (!binary_identity.ok()) {
    return;
  }

  Fp8KvPairKernelResources production_resources{};
  Fp8KvPairKernelResources candidate_resources{};
  const auto query_candidate_resources =
      [&](int* const registers_per_thread,
          std::size_t* const static_shared_bytes,
          std::size_t* const local_bytes,
          int* const maximum_threads_per_block,
          int* const active_blocks_per_sm) {
        if (cta512_mode) {
          return q3x::kernels::
              query_sm87_fp8_w8a16_m1_q_kv_aosoa4_preswizzled_cta512_resources_test_cuda(
                  registers_per_thread, static_shared_bytes, local_bytes,
                  maximum_threads_per_block, active_blocks_per_sm);
        }
        return q3x::kernels::
            query_sm87_fp8_w8a16_m1_q_kv_aosoa4_preswizzled_resources_test_cuda(
                registers_per_thread, static_shared_bytes, local_bytes,
                maximum_threads_per_block, active_blocks_per_sm);
      };
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_q_kv_reduction_scratch_ping_pong_resources_test_cuda(
              &production_resources.registers_per_thread,
              &production_resources.static_shared_bytes,
              &production_resources.local_bytes,
              &production_resources.maximum_threads_per_block,
              &production_resources.active_blocks_per_sm)),
      label + " query production resources");
  ready = test.cuda_ok(
              static_cast<cudaError_t>(query_candidate_resources(
                  &candidate_resources.registers_per_thread,
                  &candidate_resources.static_shared_bytes,
                  &candidate_resources.local_bytes,
                  &candidate_resources.maximum_threads_per_block,
                  &candidate_resources.active_blocks_per_sm)),
              label + " query candidate resources") &&
          ready;
  const bool null_resource_gate =
      static_cast<cudaError_t>(query_candidate_resources(
          nullptr, &candidate_resources.static_shared_bytes,
          &candidate_resources.local_bytes,
          &candidate_resources.maximum_threads_per_block,
          &candidate_resources.active_blocks_per_sm)) ==
      cudaErrorInvalidValue;
  const bool resource_gate =
      ready && production_resources.registers_per_thread == 64 &&
      candidate_resources.registers_per_thread == 64 &&
      production_resources.static_shared_bytes == 1'280U &&
      candidate_resources.static_shared_bytes ==
          candidate_static_shared_bytes &&
      production_resources.local_bytes == 0U &&
      candidate_resources.local_bytes == 0U &&
      production_resources.maximum_threads_per_block == 256 &&
      candidate_resources.maximum_threads_per_block ==
          candidate_maximum_threads_per_block &&
      production_resources.active_blocks_per_sm == 4 &&
      candidate_resources.active_blocks_per_sm ==
          candidate_active_blocks_per_sm &&
      null_resource_gate;
  test.expect(resource_gate,
              label + " preserves the production occupancy/spill contract");
  std::cout << "FP8_M1_Q_KV_AOSOA4_RESOURCES: candidate="
            << candidate_name
            << " production_registers="
            << production_resources.registers_per_thread
            << " candidate_registers="
            << candidate_resources.registers_per_thread
            << " production_static_shared_bytes="
            << production_resources.static_shared_bytes
            << " candidate_static_shared_bytes="
            << candidate_resources.static_shared_bytes
            << " production_local_bytes="
            << production_resources.local_bytes
            << " candidate_local_bytes=" << candidate_resources.local_bytes
            << " production_active_ctas_per_sm="
            << production_resources.active_blocks_per_sm
            << " candidate_active_ctas_per_sm="
            << candidate_resources.active_blocks_per_sm
            << " null_query=" << (null_resource_gate ? "PASS" : "FAIL")
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!ready) {
    return;
  }

  const char* const checkpoint_value =
      std::getenv("Q3X_FP8_M1_Q_KV_ACTUAL_CHECKPOINT_FILE");
  const bool checkpoint_source_gate =
      checkpoint_value != nullptr && checkpoint_value[0] != '\0';
  test.expect(checkpoint_source_gate,
              label + " requires the pinned actual checkpoint shard");
  if (!checkpoint_source_gate) {
    return;
  }
  const std::string checkpoint_file = checkpoint_value;
  std::vector<std::uint8_t> host_q(kQBytes);
  std::vector<std::uint8_t> host_key(kKvBytes);
  std::vector<std::uint8_t> host_value(kKvBytes);
  const auto read_slice = [&](const std::uint64_t offset,
                              std::vector<std::uint8_t>& destination,
                              const std::string& name) {
    std::ifstream input(checkpoint_file, std::ios::binary);
    if (!input.is_open()) {
      test.expect(false, label + " opens checkpoint for " + name);
      return false;
    }
    input.seekg(0, std::ios::end);
    const std::streamoff file_size = input.tellg();
    const bool range_gate =
        file_size >= 0 && offset <= static_cast<std::uint64_t>(file_size) &&
        destination.size() <=
            static_cast<std::uint64_t>(file_size) - offset;
    test.expect(range_gate, label + " checkpoint contains " + name);
    if (!range_gate) {
      return false;
    }
    input.seekg(static_cast<std::streamoff>(offset), std::ios::beg);
    input.read(reinterpret_cast<char*>(destination.data()),
               static_cast<std::streamsize>(destination.size()));
    const bool complete = input.gcount() ==
                          static_cast<std::streamsize>(destination.size());
    test.expect(complete, label + " reads complete " + name);
    return complete;
  };
  ready = read_slice(kQOffset, host_q, "layer-3 Q weights");
  ready = read_slice(kKeyOffset, host_key, "layer-3 K weights") && ready;
  ready = read_slice(kValueOffset, host_value, "layer-3 V weights") && ready;
  const std::string q_hash = q3x::core::sha256(std::string_view(
      reinterpret_cast<const char*>(host_q.data()), host_q.size())).hex();
  const std::string key_hash = q3x::core::sha256(std::string_view(
      reinterpret_cast<const char*>(host_key.data()), host_key.size())).hex();
  const std::string value_hash = q3x::core::sha256(std::string_view(
      reinterpret_cast<const char*>(host_value.data()), host_value.size())).hex();
  const bool payload_identity_gate =
      ready && q_hash == kQSha256 && key_hash == kKeySha256 &&
      value_hash == kValueSha256;
  test.expect(payload_identity_gate,
              label + " matches all pinned Q/K/V payload hashes");
  std::cout << "FP8_M1_Q_KV_AOSOA4_ACTUAL_FIXTURE: checkpoint_path="
            << checkpoint_file << " q_offset=" << kQOffset
            << " key_offset=" << kKeyOffset
            << " value_offset=" << kValueOffset
            << " q_bytes=" << host_q.size()
            << " kv_bytes_each=" << host_key.size()
            << " q_sha256=" << q_hash << " key_sha256=" << key_hash
            << " value_sha256=" << value_hash
            << " gate=" << (payload_identity_gate ? "PASS" : "FAIL")
            << '\n';
  if (!payload_identity_gate) {
    return;
  }

  std::vector<std::uint8_t> expected_q_sidecar;
  const bool q_sidecar_semantics =
      build_fp8_m1_aosoa4_preswizzled_sidecar(
          host_q, kQRows, kColumns, 0U, 0U, expected_q_sidecar) &&
      expected_q_sidecar.size() == kQBytes;
  std::vector<std::uint8_t> expected_kv_sidecar(kKvSidecarBytes);
  bool kv_sidecar_semantics = true;
  constexpr std::size_t kPackedColumns = kColumns / 4U;
  for (std::size_t row_pair = 0U; row_pair < kKvRows / 2U;
       ++row_pair) {
    for (std::size_t packed_column = 0U;
         packed_column < kPackedColumns; ++packed_column) {
      std::array<std::uint32_t, 4U> words{};
      const std::array<const std::uint8_t*, 4U> sources{{
          host_key.data() + (2U * row_pair) * kColumns,
          host_key.data() + (2U * row_pair + 1U) * kColumns,
          host_value.data() + (2U * row_pair) * kColumns,
          host_value.data() + (2U * row_pair + 1U) * kColumns,
      }};
      for (std::size_t component = 0U; component < 4U; ++component) {
        std::uint32_t canonical = 0U;
        std::memcpy(&canonical, sources[component] + 4U * packed_column,
                    sizeof(canonical));
        words[component] =
            canonical ^ ((canonical >> 5U) & 0x0707'0707U);
        for (std::size_t byte = 0U; byte < 4U; ++byte) {
          const std::uint8_t code =
              sources[component][4U * packed_column + byte];
          const std::uint8_t slot =
              static_cast<std::uint8_t>(code ^ (code >> 5U));
          kv_sidecar_semantics =
              kv_sidecar_semantics &&
              slot == static_cast<std::uint8_t>(
                          (words[component] >> (8U * byte)) & 0xffU);
        }
      }
      const uint4 packed{words[0U], words[1U], words[2U], words[3U]};
      std::memcpy(expected_kv_sidecar.data() +
                      (row_pair * kPackedColumns + packed_column) *
                          sizeof(uint4),
                  &packed, sizeof(packed));
    }
  }
  test.expect(q_sidecar_semantics && kv_sidecar_semantics,
              label + " freezes all preswizzled byte semantics");
  if (!q_sidecar_semantics || !kv_sidecar_semantics) {
    return;
  }

  std::vector<std::uint16_t> host_activation(kColumns);
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 17U + (column >> 3U) * 5U + 7U) %
                         127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> q_weights;
  DeviceBuffer<std::uint8_t> key_weights;
  DeviceBuffer<std::uint8_t> value_weights;
  DeviceBuffer<std::uint8_t> q_sidecar;
  DeviceBuffer<std::uint8_t> kv_sidecar;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> production_q_storage;
  DeviceBuffer<std::uint16_t> production_key_storage;
  DeviceBuffer<std::uint16_t> production_value_storage;
  DeviceBuffer<std::uint16_t> candidate_q_storage;
  DeviceBuffer<std::uint16_t> candidate_key_storage;
  DeviceBuffer<std::uint16_t> candidate_value_storage;
  DeviceBuffer<std::uint16_t> timing_q;
  DeviceBuffer<std::uint16_t> timing_key;
  DeviceBuffer<std::uint16_t> timing_value;
  ready = test.cuda_ok(q_weights.allocate(kQBytes), label + " allocate Q");
  ready = test.cuda_ok(key_weights.allocate(kKvBytes), label + " allocate K") &&
          ready;
  ready = test.cuda_ok(value_weights.allocate(kKvBytes), label + " allocate V") &&
          ready;
  ready = test.cuda_ok(q_sidecar.allocate(kQBytes),
                       label + " allocate Q sidecar") &&
          ready;
  ready = test.cuda_ok(kv_sidecar.allocate(kKvSidecarBytes),
                       label + " allocate KV sidecar") &&
          ready;
  ready = test.cuda_ok(activation.allocate(kColumns),
                       label + " allocate activation") &&
          ready;
  for (auto* const storage : {&production_q_storage, &candidate_q_storage}) {
    ready = test.cuda_ok(storage->allocate(kQRows + 2U * kGuardElements),
                         label + " allocate guarded Q output") &&
            ready;
  }
  for (auto* const storage : {&production_key_storage,
                              &production_value_storage,
                              &candidate_key_storage,
                              &candidate_value_storage}) {
    ready = test.cuda_ok(storage->allocate(kKvRows + 2U * kGuardElements),
                         label + " allocate guarded KV output") &&
            ready;
  }
  ready = test.cuda_ok(timing_q.allocate(kQRows), label + " allocate timing Q") &&
          ready;
  ready = test.cuda_ok(timing_key.allocate(kKvRows),
                       label + " allocate timing K") &&
          ready;
  ready = test.cuda_ok(timing_value.allocate(kKvRows),
                       label + " allocate timing V") &&
          ready;
  if (!ready) {
    return;
  }

  ready = test.cuda_ok(
      cudaMemcpyAsync(q_weights.get(), host_q.data(), host_q.size(),
                      cudaMemcpyHostToDevice, stream),
      label + " upload Q");
  ready = test.cuda_ok(
              cudaMemcpyAsync(key_weights.get(), host_key.data(),
                              host_key.size(), cudaMemcpyHostToDevice, stream),
              label + " upload K") &&
          ready;
  ready = test.cuda_ok(
              cudaMemcpyAsync(value_weights.get(), host_value.data(),
                              host_value.size(), cudaMemcpyHostToDevice,
                              stream),
              label + " upload V") &&
          ready;
  ready = test.cuda_ok(
              cudaMemcpyAsync(activation.get(), host_activation.data(),
                              host_activation.size() * sizeof(std::uint16_t),
                              cudaMemcpyHostToDevice, stream),
              label + " upload activation") &&
          ready;
  ready = test.cuda_ok(
              static_cast<cudaError_t>(q3x::kernels::
                  launch_sm87_fp8_w8a16_m1_q_kv_aosoa4_preswizzled_pack_test_cuda(
                      q_weights.get(), key_weights.get(), value_weights.get(),
                      kQRows, kKvRows, kColumns, q_sidecar.get(),
                      kv_sidecar.get(), static_cast<void*>(stream))),
              label + " build sidecars") &&
          ready;
  std::vector<std::uint8_t> observed_q_sidecar(kQBytes);
  std::vector<std::uint8_t> observed_kv_sidecar(kKvSidecarBytes);
  ready = test.cuda_ok(
              cudaMemcpyAsync(observed_q_sidecar.data(), q_sidecar.get(),
                              observed_q_sidecar.size(), cudaMemcpyDeviceToHost,
                              stream),
              label + " copy Q sidecar") &&
          ready;
  ready = test.cuda_ok(
              cudaMemcpyAsync(observed_kv_sidecar.data(), kv_sidecar.get(),
                              observed_kv_sidecar.size(),
                              cudaMemcpyDeviceToHost, stream),
              label + " copy KV sidecar") &&
          ready;
  ready = test.cuda_ok(cudaStreamSynchronize(stream),
                       label + " sidecar build synchronize") &&
          ready;
  const bool pack_gate =
      ready && observed_q_sidecar == expected_q_sidecar &&
      observed_kv_sidecar == expected_kv_sidecar;
  test.expect(pack_gate,
              label + " GPU pack is byte-exact against the CPU contract");
  std::cout << "FP8_M1_Q_KV_AOSOA4_PACK: q_sidecar_bytes=" << kQBytes
            << " kv_sidecar_bytes=" << kKvSidecarBytes
            << " q_sidecar_sha256="
            << q3x::core::sha256(std::string_view(
                   reinterpret_cast<const char*>(observed_q_sidecar.data()),
                   observed_q_sidecar.size())).hex()
            << " kv_sidecar_sha256="
            << q3x::core::sha256(std::string_view(
                   reinterpret_cast<const char*>(observed_kv_sidecar.data()),
                   observed_kv_sidecar.size())).hex()
            << " cpu_gpu_byte_exact=" << (pack_gate ? "true" : "false")
            << " gate=" << (pack_gate ? "PASS" : "FAIL") << '\n';
  if (!pack_gate) {
    return;
  }

  std::uint16_t* const production_q =
      production_q_storage.get() + kGuardElements;
  std::uint16_t* const production_key =
      production_key_storage.get() + kGuardElements;
  std::uint16_t* const production_value =
      production_value_storage.get() + kGuardElements;
  std::uint16_t* const candidate_q =
      candidate_q_storage.get() + kGuardElements;
  std::uint16_t* const candidate_key =
      candidate_key_storage.get() + kGuardElements;
  std::uint16_t* const candidate_value =
      candidate_value_storage.get() + kGuardElements;
  float q_scale = kQScale;
  float key_scale = kKeyScale;
  float value_scale = kValueScale;

  const auto launch_production = [&](std::uint16_t* const q_output,
                                     std::uint16_t* const key_output,
                                     std::uint16_t* const value_output) {
    return q3x::kernels::launch_sm87_fp8_w8a16_gemv_q_kv_bf16_cuda(
        q_weights.get(), q_scale, key_weights.get(), key_scale,
        value_weights.get(), value_scale, activation.get(), kQRows, kKvRows,
        kColumns, q_output, key_output, value_output,
        static_cast<void*>(stream));
  };
  const auto launch_candidate_raw =
      [&](const std::uint8_t* const q_sidecar_weights,
          const float launch_q_scale,
          const std::uint8_t* const kv_sidecar_weights,
          const float launch_key_scale, const float launch_value_scale,
          const std::uint16_t* const launch_activation,
          const std::size_t launch_q_rows,
          const std::size_t launch_kv_rows,
          const std::size_t launch_columns,
          std::uint16_t* const q_output,
          std::uint16_t* const key_output,
          std::uint16_t* const value_output) {
        if (cta512_mode) {
          return q3x::kernels::
              launch_sm87_fp8_w8a16_m1_q_kv_aosoa4_preswizzled_cta512_test_cuda(
                  q_sidecar_weights, launch_q_scale, kv_sidecar_weights,
                  launch_key_scale, launch_value_scale, launch_activation,
                  launch_q_rows, launch_kv_rows, launch_columns, q_output,
                  key_output, value_output, static_cast<void*>(stream));
        }
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_q_kv_aosoa4_preswizzled_test_cuda(
                q_sidecar_weights, launch_q_scale, kv_sidecar_weights,
                launch_key_scale, launch_value_scale, launch_activation,
                launch_q_rows, launch_kv_rows, launch_columns, q_output,
                key_output, value_output, static_cast<void*>(stream));
      };
  const auto launch_candidate = [&](std::uint16_t* const q_output,
                                    std::uint16_t* const key_output,
                                    std::uint16_t* const value_output) {
    return launch_candidate_raw(
        q_sidecar.get(), q_scale, kv_sidecar.get(), key_scale, value_scale,
        activation.get(), kQRows, kKvRows, kColumns, q_output, key_output,
        value_output);
  };
  const auto initialize_guarded_outputs = [&](const std::string& fixture) {
    bool initialized = test.cuda_ok(
        cudaMemsetAsync(production_q_storage.get(), 0xa5,
                        (kQRows + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        fixture + " poison production Q");
    initialized = test.cuda_ok(
                      cudaMemsetAsync(production_key_storage.get(), 0x5a,
                                      (kKvRows + 2U * kGuardElements) *
                                          sizeof(std::uint16_t),
                                      stream),
                      fixture + " poison production K") &&
                  initialized;
    initialized = test.cuda_ok(
                      cudaMemsetAsync(production_value_storage.get(), 0x3c,
                                      (kKvRows + 2U * kGuardElements) *
                                          sizeof(std::uint16_t),
                                      stream),
                      fixture + " poison production V") &&
                  initialized;
    initialized = test.cuda_ok(
                      cudaMemsetAsync(candidate_q_storage.get(), 0xa5,
                                      (kQRows + 2U * kGuardElements) *
                                          sizeof(std::uint16_t),
                                      stream),
                      fixture + " poison candidate Q") &&
                  initialized;
    initialized = test.cuda_ok(
                      cudaMemsetAsync(candidate_key_storage.get(), 0x5a,
                                      (kKvRows + 2U * kGuardElements) *
                                          sizeof(std::uint16_t),
                                      stream),
                      fixture + " poison candidate K") &&
                  initialized;
    initialized = test.cuda_ok(
                      cudaMemsetAsync(candidate_value_storage.get(), 0x3c,
                                      (kKvRows + 2U * kGuardElements) *
                                          sizeof(std::uint16_t),
                                      stream),
                      fixture + " poison candidate V") &&
                  initialized;
    return initialized;
  };
  const auto guards_match = [](const std::vector<std::uint16_t>& values,
                               const std::size_t rows,
                               const std::uint16_t canary) {
    return std::all_of(values.begin(),
                       values.begin() + kGuardElements,
                       [canary](const std::uint16_t value) {
                         return value == canary;
                       }) &&
           std::all_of(values.begin() + kGuardElements + rows,
                       values.end(),
                       [canary](const std::uint16_t value) {
                         return value == canary;
                       });
  };
  const auto run_direct_diff =
      [&](const std::string& fixture,
          const std::vector<std::uint8_t>& expected_q_sidecar_bytes,
          const std::vector<std::uint8_t>& expected_kv_sidecar_bytes) {
        bool diff_ready = initialize_guarded_outputs(fixture);
        diff_ready = test.cuda_ok(
                         static_cast<cudaError_t>(launch_production(
                             production_q, production_key,
                             production_value)),
                         fixture + " launch production") &&
                     diff_ready;
        diff_ready = test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate(
                             candidate_q, candidate_key, candidate_value)),
                         fixture + " launch candidate") &&
                     diff_ready;
        std::vector<std::uint16_t> observed_production_q(
            kQRows + 2U * kGuardElements);
        std::vector<std::uint16_t> observed_production_key(
            kKvRows + 2U * kGuardElements);
        std::vector<std::uint16_t> observed_production_value(
            kKvRows + 2U * kGuardElements);
        std::vector<std::uint16_t> observed_candidate_q(
            kQRows + 2U * kGuardElements);
        std::vector<std::uint16_t> observed_candidate_key(
            kKvRows + 2U * kGuardElements);
        std::vector<std::uint16_t> observed_candidate_value(
            kKvRows + 2U * kGuardElements);
        const auto copy_output = [&](auto& destination, const auto& source,
                                     const std::string& name) {
          return test.cuda_ok(
              cudaMemcpyAsync(destination.data(), source.get(),
                              destination.size() * sizeof(std::uint16_t),
                              cudaMemcpyDeviceToHost, stream),
              fixture + " copy " + name);
        };
        diff_ready = copy_output(observed_production_q,
                                 production_q_storage,
                                 "production Q") &&
                     diff_ready;
        diff_ready = copy_output(observed_production_key,
                                 production_key_storage,
                                 "production K") &&
                     diff_ready;
        diff_ready = copy_output(observed_production_value,
                                 production_value_storage,
                                 "production V") &&
                     diff_ready;
        diff_ready = copy_output(observed_candidate_q, candidate_q_storage,
                                 "candidate Q") &&
                     diff_ready;
        diff_ready = copy_output(observed_candidate_key,
                                 candidate_key_storage,
                                 "candidate K") &&
                     diff_ready;
        diff_ready = copy_output(observed_candidate_value,
                                 candidate_value_storage,
                                 "candidate V") &&
                     diff_ready;
        std::vector<std::uint8_t> preserved_q(host_q.size());
        std::vector<std::uint8_t> preserved_key(host_key.size());
        std::vector<std::uint8_t> preserved_value(host_value.size());
        std::vector<std::uint8_t> preserved_q_sidecar(
            expected_q_sidecar_bytes.size());
        std::vector<std::uint8_t> preserved_kv_sidecar(
            expected_kv_sidecar_bytes.size());
        std::vector<std::uint16_t> preserved_activation(
            host_activation.size());
        diff_ready = test.cuda_ok(
                         cudaMemcpyAsync(preserved_q.data(), q_weights.get(),
                                         preserved_q.size(),
                                         cudaMemcpyDeviceToHost, stream),
                         fixture + " preserve Q") &&
                     diff_ready;
        diff_ready = test.cuda_ok(
                         cudaMemcpyAsync(preserved_key.data(),
                                         key_weights.get(),
                                         preserved_key.size(),
                                         cudaMemcpyDeviceToHost, stream),
                         fixture + " preserve K") &&
                     diff_ready;
        diff_ready = test.cuda_ok(
                         cudaMemcpyAsync(preserved_value.data(),
                                         value_weights.get(),
                                         preserved_value.size(),
                                         cudaMemcpyDeviceToHost, stream),
                         fixture + " preserve V") &&
                     diff_ready;
        diff_ready = test.cuda_ok(
                         cudaMemcpyAsync(preserved_q_sidecar.data(),
                                         q_sidecar.get(),
                                         preserved_q_sidecar.size(),
                                         cudaMemcpyDeviceToHost, stream),
                         fixture + " preserve Q sidecar") &&
                     diff_ready;
        diff_ready = test.cuda_ok(
                         cudaMemcpyAsync(preserved_kv_sidecar.data(),
                                         kv_sidecar.get(),
                                         preserved_kv_sidecar.size(),
                                         cudaMemcpyDeviceToHost, stream),
                         fixture + " preserve KV sidecar") &&
                     diff_ready;
        diff_ready = test.cuda_ok(
                         cudaMemcpyAsync(
                             preserved_activation.data(), activation.get(),
                             preserved_activation.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture + " preserve activation") &&
                     diff_ready;
        diff_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                  fixture + " synchronize") &&
                     diff_ready;
        if (!diff_ready) {
          return false;
        }
        std::size_t q_mismatches = 0U;
        std::size_t key_mismatches = 0U;
        std::size_t value_mismatches = 0U;
        std::size_t nonfinite = 0U;
        for (std::size_t row = 0U; row < kQRows; ++row) {
          const std::uint16_t production_bits =
              observed_production_q[kGuardElements + row];
          const std::uint16_t candidate_bits =
              observed_candidate_q[kGuardElements + row];
          q_mismatches += production_bits != candidate_bits ? 1U : 0U;
          nonfinite += !is_bf16_finite(candidate_bits) ? 1U : 0U;
        }
        for (std::size_t row = 0U; row < kKvRows; ++row) {
          const std::uint16_t production_key_bits =
              observed_production_key[kGuardElements + row];
          const std::uint16_t candidate_key_bits =
              observed_candidate_key[kGuardElements + row];
          const std::uint16_t production_value_bits =
              observed_production_value[kGuardElements + row];
          const std::uint16_t candidate_value_bits =
              observed_candidate_value[kGuardElements + row];
          key_mismatches +=
              production_key_bits != candidate_key_bits ? 1U : 0U;
          value_mismatches +=
              production_value_bits != candidate_value_bits ? 1U : 0U;
          nonfinite += !is_bf16_finite(candidate_key_bits) ? 1U : 0U;
          nonfinite += !is_bf16_finite(candidate_value_bits) ? 1U : 0U;
        }
        const bool guards_intact =
            guards_match(observed_production_q, kQRows, 0xa5a5U) &&
            guards_match(observed_candidate_q, kQRows, 0xa5a5U) &&
            guards_match(observed_production_key, kKvRows, 0x5a5aU) &&
            guards_match(observed_candidate_key, kKvRows, 0x5a5aU) &&
            guards_match(observed_production_value, kKvRows, 0x3c3cU) &&
            guards_match(observed_candidate_value, kKvRows, 0x3c3cU);
        const bool inputs_preserved =
            preserved_q == host_q && preserved_key == host_key &&
            preserved_value == host_value &&
            preserved_q_sidecar == expected_q_sidecar_bytes &&
            preserved_kv_sidecar == expected_kv_sidecar_bytes &&
            preserved_activation == host_activation;
        const bool diff_gate = q_mismatches == 0U && key_mismatches == 0U &&
                               value_mismatches == 0U && nonfinite == 0U &&
                               guards_intact && inputs_preserved;
        test.expect(diff_gate,
                    fixture + " is bitwise guarded and input-preserving");
        std::cout << "FP8_M1_Q_KV_AOSOA4_DIFF: candidate="
                  << candidate_name << " fixture=" << fixture
                  << " q_mismatches=" << q_mismatches << '/' << kQRows
                  << " key_mismatches=" << key_mismatches << '/'
                  << kKvRows << " value_mismatches=" << value_mismatches
                  << '/' << kKvRows << " nonfinite_outputs=" << nonfinite
                  << " guards=" << (guards_intact ? "intact" : "BAD")
                  << " inputs_preserved="
                  << (inputs_preserved ? "true" : "false")
                  << " gate=" << (diff_gate ? "PASS" : "FAIL") << '\n';
        return diff_gate;
      };

  const bool actual_diff_gate = run_direct_diff(
      "actual_checkpoint", observed_q_sidecar, observed_kv_sidecar);

  cudaGraph_t production_graph = nullptr;
  cudaGraph_t candidate_graph = nullptr;
  cudaGraphExec_t candidate_graph_exec = nullptr;
  cudaKernelNodeParams production_params{};
  cudaKernelNodeParams candidate_params{};
  const auto capture_graph = [&](const auto& launch, cudaGraph_t* const graph,
                                 cudaKernelNodeParams* const params,
                                 const std::string& name) {
    bool capture_ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        label + " " + name + " begin capture");
    if (capture_ready) {
      capture_ready = test.cuda_ok(static_cast<cudaError_t>(launch()),
                                   label + " " + name + " launch") &&
                      capture_ready;
      capture_ready = test.cuda_ok(cudaStreamEndCapture(stream, graph),
                                   label + " " + name + " end capture") &&
                      capture_ready;
    }
    std::size_t nodes = 0U;
    capture_ready =
        capture_ready && *graph != nullptr &&
        test.cuda_ok(cudaGraphGetNodes(*graph, nullptr, &nodes),
                     label + " " + name + " count nodes");
    if (capture_ready && nodes == 1U) {
      cudaGraphNode_t node = nullptr;
      std::size_t capacity = 1U;
      capture_ready =
          test.cuda_ok(cudaGraphGetNodes(*graph, &node, &capacity),
                       label + " " + name + " get node") &&
          capacity == 1U &&
          test.cuda_ok(cudaGraphKernelNodeGetParams(node, params),
                       label + " " + name + " params") &&
          capture_ready;
    }
    return std::make_pair(capture_ready, nodes);
  };
  const auto production_capture = capture_graph(
      [&]() {
        return launch_production(production_q, production_key,
                                 production_value);
      },
      &production_graph, &production_params, "production graph");
  const auto candidate_capture = capture_graph(
      [&]() {
        return launch_candidate(candidate_q, candidate_key, candidate_value);
      },
      &candidate_graph, &candidate_params, "candidate graph");
  bool graph_ready =
      production_capture.first && candidate_capture.first &&
      production_capture.second == 1U && candidate_capture.second == 1U &&
      production_params.func != candidate_params.func &&
      production_params.gridDim.x == 2'048U &&
      candidate_params.gridDim.x == candidate_grid_x &&
      production_params.blockDim.x == 256U &&
      candidate_params.blockDim.x == candidate_block_x &&
      production_params.sharedMemBytes == 0U &&
      candidate_params.sharedMemBytes == 0U;
  if (graph_ready) {
    graph_ready = test.cuda_ok(
        cudaGraphInstantiate(&candidate_graph_exec, candidate_graph, nullptr,
                             nullptr, 0U),
        label + " instantiate candidate graph");
  }
  if (graph_ready) {
    graph_ready = test.cuda_ok(
        cudaMemsetAsync(candidate_q_storage.get(), 0x1b,
                        (kQRows + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        label + " poison graph Q");
    graph_ready = test.cuda_ok(
                      cudaMemsetAsync(candidate_key_storage.get(), 0xe4,
                                      (kKvRows + 2U * kGuardElements) *
                                          sizeof(std::uint16_t),
                                      stream),
                      label + " poison graph K") &&
                  graph_ready;
    graph_ready = test.cuda_ok(
                      cudaMemsetAsync(candidate_value_storage.get(), 0x96,
                                      (kKvRows + 2U * kGuardElements) *
                                          sizeof(std::uint16_t),
                                      stream),
                      label + " poison graph V") &&
                  graph_ready;
    graph_ready = test.cuda_ok(
                      cudaGraphLaunch(candidate_graph_exec, stream),
                      label + " replay candidate graph") &&
                  graph_ready;
  }
  std::vector<std::uint16_t> graph_q(kQRows + 2U * kGuardElements);
  std::vector<std::uint16_t> graph_key(kKvRows + 2U * kGuardElements);
  std::vector<std::uint16_t> graph_value(kKvRows + 2U * kGuardElements);
  std::vector<std::uint16_t> graph_baseline_q(kQRows);
  std::vector<std::uint16_t> graph_baseline_key(kKvRows);
  std::vector<std::uint16_t> graph_baseline_value(kKvRows);
  if (graph_ready) {
    graph_ready = test.cuda_ok(
        static_cast<cudaError_t>(launch_production(
            production_q, production_key, production_value)),
        label + " graph replay baseline launch");
    graph_ready = test.cuda_ok(
                      cudaMemcpyAsync(
                          graph_q.data(), candidate_q_storage.get(),
                          graph_q.size() * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
                      label + " copy graph Q") &&
                  graph_ready;
    graph_ready = test.cuda_ok(
                      cudaMemcpyAsync(
                          graph_key.data(), candidate_key_storage.get(),
                          graph_key.size() * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
                      label + " copy graph K") &&
                  graph_ready;
    graph_ready = test.cuda_ok(
                      cudaMemcpyAsync(
                          graph_value.data(), candidate_value_storage.get(),
                          graph_value.size() * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
                      label + " copy graph V") &&
                  graph_ready;
    graph_ready = test.cuda_ok(
                      cudaMemcpyAsync(
                          graph_baseline_q.data(), production_q,
                          graph_baseline_q.size() * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
                      label + " copy graph baseline Q") &&
                  graph_ready;
    graph_ready = test.cuda_ok(
                      cudaMemcpyAsync(
                          graph_baseline_key.data(), production_key,
                          graph_baseline_key.size() * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
                      label + " copy graph baseline K") &&
                  graph_ready;
    graph_ready = test.cuda_ok(
                      cudaMemcpyAsync(
                          graph_baseline_value.data(), production_value,
                          graph_baseline_value.size() * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
                      label + " copy graph baseline V") &&
                  graph_ready;
    graph_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                               label + " graph synchronize") &&
                  graph_ready;
  }
  std::size_t graph_mismatches = 0U;
  if (graph_ready) {
    for (std::size_t row = 0U; row < kQRows; ++row) {
      graph_mismatches +=
          graph_q[kGuardElements + row] != graph_baseline_q[row] ? 1U : 0U;
    }
    for (std::size_t row = 0U; row < kKvRows; ++row) {
      graph_mismatches +=
          graph_key[kGuardElements + row] != graph_baseline_key[row] ? 1U
                                                                     : 0U;
      graph_mismatches +=
          graph_value[kGuardElements + row] != graph_baseline_value[row] ? 1U
                                                                         : 0U;
    }
  }
  const bool graph_guard_gate =
      graph_ready && guards_match(graph_q, kQRows, 0x1b1bU) &&
      guards_match(graph_key, kKvRows, 0xe4e4U) &&
      guards_match(graph_value, kKvRows, 0x9696U);
  const bool graph_gate =
      graph_ready && graph_mismatches == 0U && graph_guard_gate;
  test.expect(graph_gate,
              label + " Graph replay is distinct, bitwise, and guarded");
  std::cout << "FP8_M1_Q_KV_AOSOA4_GRAPH: production_nodes="
            << production_capture.second
            << " candidate_nodes=" << candidate_capture.second
            << " distinct_function="
            << (production_params.func != candidate_params.func ? "true"
                                                                 : "false")
            << " candidate=" << candidate_name
            << " production_grid=" << production_params.gridDim.x
            << " production_block=" << production_params.blockDim.x
            << " candidate_grid=" << candidate_params.gridDim.x
            << " candidate_block=" << candidate_params.blockDim.x
            << " replay_mismatches="
            << graph_mismatches
            << " guards=" << (graph_guard_gate ? "intact" : "BAD")
            << " gate=" << (graph_gate ? "PASS" : "FAIL") << '\n';
  if (candidate_graph_exec != nullptr) {
    (void)test.cuda_ok(cudaGraphExecDestroy(candidate_graph_exec),
                       label + " destroy candidate graph executable");
  }
  if (candidate_graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(candidate_graph),
                       label + " destroy candidate graph");
  }
  if (production_graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(production_graph),
                       label + " destroy production graph");
  }

  struct InvalidArguments {
    const std::uint8_t* q_sidecar;
    float q_scale;
    const std::uint8_t* kv_sidecar;
    float key_scale;
    float value_scale;
    const std::uint16_t* activation;
    std::size_t q_rows;
    std::size_t kv_rows;
    std::size_t columns;
    std::uint16_t* q_output;
    std::uint16_t* key_output;
    std::uint16_t* value_output;
  };
  struct InvalidCase {
    std::string name;
    InvalidArguments arguments;
  };
  const auto* const fake_q_sidecar =
      reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
  const auto* const fake_kv_sidecar =
      reinterpret_cast<const std::uint8_t*>(0x1'1000'0000ULL);
  const auto* const fake_activation =
      reinterpret_cast<const std::uint16_t*>(0x1'2000'0000ULL);
  auto* const fake_q_output =
      reinterpret_cast<std::uint16_t*>(0x1'3000'0000ULL);
  auto* const fake_key_output =
      reinterpret_cast<std::uint16_t*>(0x1'4000'0000ULL);
  auto* const fake_value_output =
      reinterpret_cast<std::uint16_t*>(0x1'5000'0000ULL);
  const InvalidArguments valid_arguments{
      fake_q_sidecar, 1.0F / 64.0F, fake_kv_sidecar, 1.0F / 96.0F,
      1.0F / 128.0F, fake_activation, kQRows, kKvRows, kColumns,
      fake_q_output, fake_key_output, fake_value_output,
  };
  std::vector<InvalidCase> invalid_cases;
  const auto add_invalid = [&](std::string name, const auto& mutate) {
    InvalidArguments arguments = valid_arguments;
    mutate(arguments);
    invalid_cases.push_back(InvalidCase{std::move(name), arguments});
  };
  add_invalid("bad_q_rows", [](auto& args) { --args.q_rows; });
  add_invalid("bad_kv_rows", [](auto& args) { --args.kv_rows; });
  add_invalid("bad_columns", [](auto& args) { --args.columns; });
  add_invalid("null_q_sidecar", [](auto& args) { args.q_sidecar = nullptr; });
  add_invalid("null_kv_sidecar",
              [](auto& args) { args.kv_sidecar = nullptr; });
  add_invalid("null_activation",
              [](auto& args) { args.activation = nullptr; });
  add_invalid("null_q_output", [](auto& args) { args.q_output = nullptr; });
  add_invalid("null_key_output",
              [](auto& args) { args.key_output = nullptr; });
  add_invalid("null_value_output",
              [](auto& args) { args.value_output = nullptr; });
  add_invalid("q_scale_nan", [](auto& args) {
    args.q_scale = std::numeric_limits<float>::quiet_NaN();
  });
  add_invalid("key_scale_inf", [](auto& args) {
    args.key_scale = std::numeric_limits<float>::infinity();
  });
  add_invalid("value_scale_negative",
              [](auto& args) { args.value_scale = -1.0F; });
  add_invalid("misaligned_q_sidecar", [](auto& args) {
    args.q_sidecar = reinterpret_cast<const std::uint8_t*>(
        reinterpret_cast<std::uintptr_t>(args.q_sidecar) + 1U);
  });
  add_invalid("misaligned_kv_sidecar", [](auto& args) {
    args.kv_sidecar = reinterpret_cast<const std::uint8_t*>(
        reinterpret_cast<std::uintptr_t>(args.kv_sidecar) + 1U);
  });
  add_invalid("misaligned_activation", [](auto& args) {
    args.activation = reinterpret_cast<const std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(args.activation) + 2U);
  });
  add_invalid("misaligned_q_output", [](auto& args) {
    args.q_output = reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(args.q_output) + 1U);
  });
  add_invalid("misaligned_key_output", [](auto& args) {
    args.key_output = reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(args.key_output) + 1U);
  });
  add_invalid("misaligned_value_output", [](auto& args) {
    args.value_output = reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(args.value_output) + 1U);
  });
  add_invalid("q_key_output_alias",
              [](auto& args) { args.key_output = args.q_output; });
  add_invalid("q_value_output_alias",
              [](auto& args) { args.value_output = args.q_output; });
  add_invalid("key_value_output_alias",
              [](auto& args) { args.value_output = args.key_output; });
  add_invalid("q_output_q_sidecar_alias", [](auto& args) {
    args.q_output = reinterpret_cast<std::uint16_t*>(
        const_cast<std::uint8_t*>(args.q_sidecar));
  });
  add_invalid("key_output_kv_sidecar_alias", [](auto& args) {
    args.key_output = reinterpret_cast<std::uint16_t*>(
        const_cast<std::uint8_t*>(args.kv_sidecar));
  });
  add_invalid("value_output_activation_alias", [](auto& args) {
    args.value_output = const_cast<std::uint16_t*>(args.activation);
  });
  add_invalid("sidecar_input_alias",
              [](auto& args) { args.kv_sidecar = args.q_sidecar; });

  bool invalid_gate = true;
  std::size_t invalid_failures = 0U;
  for (const InvalidCase& invalid_case : invalid_cases) {
    const std::string case_label = label + " invalid " + invalid_case.name;
    cudaGraph_t invalid_graph = nullptr;
    bool invalid_ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        case_label + " begin capture");
    int status = static_cast<int>(cudaErrorUnknown);
    if (invalid_ready) {
      const InvalidArguments& args = invalid_case.arguments;
      status = launch_candidate_raw(
          args.q_sidecar, args.q_scale, args.kv_sidecar, args.key_scale,
          args.value_scale, args.activation, args.q_rows, args.kv_rows,
          args.columns, args.q_output, args.key_output, args.value_output);
      invalid_ready = test.cuda_ok(
                          cudaStreamEndCapture(stream, &invalid_graph),
                          case_label + " end capture") &&
                      invalid_ready;
    }
    std::size_t nodes = 0U;
    if (invalid_ready && invalid_graph != nullptr) {
      invalid_ready = test.cuda_ok(
                          cudaGraphGetNodes(invalid_graph, nullptr, &nodes),
                          case_label + " count nodes") &&
                      invalid_ready;
    }
    if (invalid_graph != nullptr) {
      invalid_ready = test.cuda_ok(cudaGraphDestroy(invalid_graph),
                                   case_label + " destroy graph") &&
                      invalid_ready;
    }
    const bool case_gate =
        invalid_ready && status == static_cast<int>(cudaErrorInvalidValue) &&
        nodes == 0U;
    invalid_gate = invalid_gate && case_gate;
    invalid_failures += case_gate ? 0U : 1U;
    test.expect(case_gate, case_label + " rejects before enqueue");
  }
  const bool stream_clean = test.cuda_ok(cudaStreamSynchronize(stream),
                                         label + " invalid stream clean");
  invalid_gate = invalid_gate && stream_clean && invalid_failures == 0U;
  test.expect(invalid_gate,
              label + " freezes invalid-value fail-before-enqueue behavior");
  std::cout << "FP8_M1_Q_KV_AOSOA4_INVALID: candidate="
            << candidate_name << " cases=" << invalid_cases.size()
            << " failures=" << invalid_failures
            << " zero_nodes=true stream_clean="
            << (stream_clean ? "true" : "false")
            << " gate=" << (invalid_gate ? "PASS" : "FAIL") << '\n';

  struct SidecarTiming {
    bool ready = false;
    bool every_round_nonregressing = false;
    float production_median_ms = std::numeric_limits<float>::quiet_NaN();
    float candidate_median_ms = std::numeric_limits<float>::quiet_NaN();
    float paired_median_speedup = std::numeric_limits<float>::quiet_NaN();
    float paired_median_delta_ms = std::numeric_limits<float>::quiet_NaN();
    double projected_16_layer_delta_ms =
        std::numeric_limits<double>::quiet_NaN();
  };
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 80;
  constexpr int kMeasurementRounds = 5;
  constexpr std::size_t kTimedPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  const auto launch_production_timing = [&]() {
    return launch_production(timing_q.get(), timing_key.get(),
                             timing_value.get());
  };
  const auto launch_candidate_timing = [&]() {
    return launch_candidate(timing_q.get(), timing_key.get(),
                            timing_value.get());
  };
  const auto benchmark_fixture = [&](const std::string& fixture) {
    SidecarTiming timing{};
    bool timing_ready = true;
    for (int iteration = 0;
         iteration < kWarmupIterations && timing_ready; ++iteration) {
      if ((iteration & 1) == 0) {
        timing_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_production_timing()),
            fixture + " production warmup");
        timing_ready = test.cuda_ok(
                           static_cast<cudaError_t>(
                               launch_candidate_timing()),
                           fixture + " candidate warmup") &&
                       timing_ready;
      } else {
        timing_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_candidate_timing()),
            fixture + " candidate warmup");
        timing_ready = test.cuda_ok(
                           static_cast<cudaError_t>(
                               launch_production_timing()),
                           fixture + " production warmup") &&
                       timing_ready;
      }
    }
    timing_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                fixture + " warmup synchronize") &&
                   timing_ready;
    std::array<float, kTimedPasses> production_passes{};
    std::array<float, kTimedPasses> candidate_passes{};
    std::array<float, kMeasurementRounds> paired_speedups{};
    std::array<float, kMeasurementRounds> paired_deltas{};
    bool every_round_nonregressing = timing_ready;
    for (int round = 0; round < kMeasurementRounds && timing_ready; ++round) {
      const bool production_first = (round & 1) == 0;
      const std::string round_label =
          fixture + " round=" + std::to_string(round + 1);
      float b1 = std::numeric_limits<float>::quiet_NaN();
      float b2 = std::numeric_limits<float>::quiet_NaN();
      float c1 = std::numeric_limits<float>::quiet_NaN();
      float c2 = std::numeric_limits<float>::quiet_NaN();
      if (production_first) {
        b1 = measure_small_m_tile(test, stream, launch_production_timing,
                                  kMeasuredIterations, round_label + " B1");
        c1 = measure_small_m_tile(test, stream, launch_candidate_timing,
                                  kMeasuredIterations, round_label + " C1");
        c2 = measure_small_m_tile(test, stream, launch_candidate_timing,
                                  kMeasuredIterations, round_label + " C2");
        b2 = measure_small_m_tile(test, stream, launch_production_timing,
                                  kMeasuredIterations, round_label + " B2");
      } else {
        c1 = measure_small_m_tile(test, stream, launch_candidate_timing,
                                  kMeasuredIterations, round_label + " C1");
        b1 = measure_small_m_tile(test, stream, launch_production_timing,
                                  kMeasuredIterations, round_label + " B1");
        b2 = measure_small_m_tile(test, stream, launch_production_timing,
                                  kMeasuredIterations, round_label + " B2");
        c2 = measure_small_m_tile(test, stream, launch_candidate_timing,
                                  kMeasuredIterations, round_label + " C2");
      }
      const bool finite =
          std::isfinite(b1) && std::isfinite(b2) && std::isfinite(c1) &&
          std::isfinite(c2) && b1 > 0.0F && b2 > 0.0F && c1 > 0.0F &&
          c2 > 0.0F;
      const float paired_production = 0.5F * (b1 + b2);
      const float paired_candidate = 0.5F * (c1 + c2);
      const float paired_speedup = paired_production / paired_candidate;
      const float paired_delta = paired_production - paired_candidate;
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      production_passes[pass] = b1;
      production_passes[pass + 1U] = b2;
      candidate_passes[pass] = c1;
      candidate_passes[pass + 1U] = c2;
      paired_speedups[static_cast<std::size_t>(round)] = paired_speedup;
      paired_deltas[static_cast<std::size_t>(round)] = paired_delta;
      const bool round_gate = finite && paired_speedup >= 1.0F;
      every_round_nonregressing = every_round_nonregressing && round_gate;
      timing_ready = timing_ready && finite;
      std::cout << "PERF_FP8_M1_Q_KV_AOSOA4_ROUND: candidate="
                << candidate_name << " fixture=" << fixture
                << " round=" << round + 1 << " order="
                << (production_first ? "B-C-C-B" : "C-B-B-C")
                << " launches_per_pass=" << kMeasuredIterations
                << " shared_output_address=true"
                << " production_pass1_ms=" << b1
                << " candidate_pass1_ms=" << c1
                << " candidate_pass2_ms=" << c2
                << " production_pass2_ms=" << b2
                << " paired_speedup=" << paired_speedup
                << " paired_delta_ms=" << paired_delta
                << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
    }
    timing.ready = timing_ready;
    timing.every_round_nonregressing = every_round_nonregressing;
    if (timing_ready) {
      timing.production_median_ms =
          median_fp8_kv_pair_timing(production_passes);
      timing.candidate_median_ms =
          median_fp8_kv_pair_timing(candidate_passes);
      timing.paired_median_speedup =
          median_fp8_kv_pair_timing(paired_speedups);
      timing.paired_median_delta_ms =
          median_fp8_kv_pair_timing(paired_deltas);
      timing.projected_16_layer_delta_ms =
          static_cast<double>(timing.paired_median_delta_ms) * 16.0;
    }
    return timing;
  };

  const SidecarTiming actual_timing = benchmark_fixture("actual_checkpoint");
  constexpr double kRequiredActualSpeedup = 1.005;
  constexpr double kRequiredPerLayerDeltaMs = 0.0125;
  constexpr double kRequiredProjected16LayerDeltaMs = 0.20;
  const bool actual_timing_gate =
      actual_timing.ready && actual_timing.every_round_nonregressing &&
      std::isfinite(actual_timing.paired_median_speedup) &&
      actual_timing.paired_median_speedup >= kRequiredActualSpeedup &&
      std::isfinite(actual_timing.paired_median_delta_ms) &&
      actual_timing.paired_median_delta_ms >= kRequiredPerLayerDeltaMs &&
      std::isfinite(actual_timing.projected_16_layer_delta_ms) &&
      actual_timing.projected_16_layer_delta_ms >=
          kRequiredProjected16LayerDeltaMs;
  const bool actual_gate =
      resource_gate && payload_identity_gate && pack_gate &&
      actual_diff_gate && graph_gate && invalid_gate && actual_timing_gate;
  test.expect(actual_gate,
              label + " clears the frozen first actual-process hard gate");
  std::cout << "PERF_FP8_M1_Q_KV_AOSOA4_ACTUAL: candidate="
            << candidate_name << " production_median_ms="
            << actual_timing.production_median_ms
            << " candidate_median_ms=" << actual_timing.candidate_median_ms
            << " paired_median_speedup="
            << actual_timing.paired_median_speedup
            << " paired_median_delta_ms="
            << actual_timing.paired_median_delta_ms
            << " projected_16_layer_delta_ms="
            << actual_timing.projected_16_layer_delta_ms
            << " every_round_nonregressing="
            << (actual_timing.every_round_nonregressing ? "true" : "false")
            << " required_speedup=" << kRequiredActualSpeedup
            << " required_per_layer_delta_ms=" << kRequiredPerLayerDeltaMs
            << " required_projected_16_layer_delta_ms="
            << kRequiredProjected16LayerDeltaMs
            << " bitwise_graph_invalid="
            << (actual_diff_gate && graph_gate && invalid_gate ? "PASS"
                                                               : "FAIL")
            << " gate=" << (actual_gate ? "PASS" : "FAIL") << '\n';
  if (!actual_gate) {
    std::cout << "PERF_FP8_M1_Q_KV_AOSOA4_STOP_LOSS: candidate="
              << candidate_name
              << " reason=first_frozen_actual_process_failed"
              << " stress_timing=NOT_RUN production_integration=NOT_RUN"
              << " end_to_end=NOT_RUN gate=FAIL\n";
    return;
  }

  fill_fp8_m2_code_distribution(host_q, kQRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  fill_fp8_m2_code_distribution(host_key, kKvRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  fill_fp8_m2_code_distribution(host_value, kKvRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  std::reverse(host_value.begin(), host_value.end());
  q_scale = 1.0F / 64.0F;
  key_scale = 1.0F / 96.0F;
  value_scale = 1.0F / 128.0F;
  bool stress_ready = test.cuda_ok(
      cudaMemcpyAsync(q_weights.get(), host_q.data(), host_q.size(),
                      cudaMemcpyHostToDevice, stream),
      label + " stress upload Q");
  stress_ready = test.cuda_ok(
                     cudaMemcpyAsync(key_weights.get(), host_key.data(),
                                     host_key.size(), cudaMemcpyHostToDevice,
                                     stream),
                     label + " stress upload K") &&
                 stress_ready;
  stress_ready = test.cuda_ok(
                     cudaMemcpyAsync(value_weights.get(), host_value.data(),
                                     host_value.size(), cudaMemcpyHostToDevice,
                                     stream),
                     label + " stress upload V") &&
                 stress_ready;
  stress_ready = test.cuda_ok(
                     static_cast<cudaError_t>(q3x::kernels::
                         launch_sm87_fp8_w8a16_m1_q_kv_aosoa4_preswizzled_pack_test_cuda(
                             q_weights.get(), key_weights.get(),
                             value_weights.get(), kQRows, kKvRows, kColumns,
                             q_sidecar.get(), kv_sidecar.get(),
                             static_cast<void*>(stream))),
                     label + " stress build sidecars") &&
                 stress_ready;
  std::vector<std::uint8_t> stress_q_sidecar(kQBytes);
  std::vector<std::uint8_t> stress_kv_sidecar(kKvSidecarBytes);
  stress_ready = test.cuda_ok(
                     cudaMemcpyAsync(stress_q_sidecar.data(), q_sidecar.get(),
                                     stress_q_sidecar.size(),
                                     cudaMemcpyDeviceToHost, stream),
                     label + " stress copy Q sidecar") &&
                 stress_ready;
  stress_ready = test.cuda_ok(
                     cudaMemcpyAsync(stress_kv_sidecar.data(),
                                     kv_sidecar.get(),
                                     stress_kv_sidecar.size(),
                                     cudaMemcpyDeviceToHost, stream),
                     label + " stress copy KV sidecar") &&
                 stress_ready;
  stress_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                              label + " stress upload synchronize") &&
                 stress_ready;
  const bool stress_diff_gate =
      stress_ready && run_direct_diff("same_bank_stress", stress_q_sidecar,
                                      stress_kv_sidecar);
  const SidecarTiming stress_timing =
      stress_diff_gate ? benchmark_fixture("same_bank_stress")
                       : SidecarTiming{};
  const bool stress_gate =
      stress_diff_gate && stress_timing.ready &&
      stress_timing.every_round_nonregressing &&
      std::isfinite(stress_timing.paired_median_speedup) &&
      stress_timing.paired_median_speedup >= 1.0F;
  const bool selected_gate = actual_gate && stress_gate;
  test.expect(selected_gate,
              label + " clears actual and same-bank process gates");
  std::cout << "PERF_FP8_M1_Q_KV_AOSOA4_SELECTED:"
            << " baseline=production_canonical_ping_pong"
            << " candidate=test_only_" << candidate_name
            << " topology=" << candidate_grid_x << 'x' << candidate_block_x
            << " actual_production_median_ms="
            << actual_timing.production_median_ms
            << " actual_candidate_median_ms="
            << actual_timing.candidate_median_ms
            << " actual_paired_median_speedup="
            << actual_timing.paired_median_speedup
            << " actual_paired_median_delta_ms="
            << actual_timing.paired_median_delta_ms
            << " actual_projected_16_layer_delta_ms="
            << actual_timing.projected_16_layer_delta_ms
            << " stress_production_median_ms="
            << stress_timing.production_median_ms
            << " stress_candidate_median_ms="
            << stress_timing.candidate_median_ms
            << " stress_paired_median_speedup="
            << stress_timing.paired_median_speedup
            << " stress_every_round_nonregressing="
            << (stress_timing.every_round_nonregressing ? "true" : "false")
            << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
}

struct Fp8QkvZFusionTiming {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
};

[[nodiscard]] bool parse_fp8_qkv_z_checkpoint_offsets(
    const char* const value,
    std::array<std::uint64_t, 2U>& offsets) noexcept {
  if (value == nullptr || value[0] == '\0') {
    return false;
  }
  const char* cursor = value;
  for (std::size_t index = 0U; index < offsets.size(); ++index) {
    if (*cursor < '0' || *cursor > '9') {
      return false;
    }
    errno = 0;
    char* end = nullptr;
    const unsigned long long parsed = std::strtoull(cursor, &end, 10);
    if (errno == ERANGE || end == cursor) {
      return false;
    }
    offsets[index] = static_cast<std::uint64_t>(parsed);
    if (index + 1U == offsets.size()) {
      return *end == '\0';
    }
    if (*end != ':') {
      return false;
    }
    cursor = end + 1;
  }
  return false;
}

void run_fp8_m1_qkv_z_production_dispatch_contract(
    TestContext& test, cudaStream_t stream) {
  constexpr std::size_t kQkvRows = 10'240U;
  constexpr std::size_t kZRows = 6'144U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kProductionBlocks = 1'536U;

  // Capture-only probes lock the public launcher and the performance harness
  // to the same kernel symbol and launch topology without allocating or
  // dereferencing the production-sized matrices.
  const auto* const fake_qkv_weights =
      reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
  const auto* const fake_z_weights =
      reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
  const auto* const fake_activation =
      reinterpret_cast<const std::uint16_t*>(0x3'0000'0000ULL);
  auto* const fake_qkv_output =
      reinterpret_cast<std::uint16_t*>(0x4'0000'0000ULL);
  auto* const fake_z_output =
      reinterpret_cast<std::uint16_t*>(0x5'0000'0000ULL);

  const auto capture_single_kernel =
      [&](const auto& launch, const std::string& label,
          cudaKernelNodeParams* const captured_params) {
        cudaGraph_t graph = nullptr;
        bool ready = test.cuda_ok(
            cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
            label + " begin capture");
        if (ready) {
          ready = test.cuda_ok(static_cast<cudaError_t>(launch()),
                               label + " capture launch") &&
                  ready;
          ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                               label + " end capture") &&
                  ready;
        }
        std::size_t node_count = 0U;
        if (ready) {
          ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                               label + " query node count");
        }
        if (ready && node_count == 1U) {
          cudaGraphNode_t node = nullptr;
          std::size_t node_capacity = 1U;
          ready = test.cuda_ok(
              cudaGraphGetNodes(graph, &node, &node_capacity),
              label + " get kernel node");
          ready = ready && node_capacity == 1U &&
                  test.cuda_ok(
                      cudaGraphKernelNodeGetParams(node, captured_params),
                      label + " get kernel params");
        }
        if (graph != nullptr) {
          ready = test.cuda_ok(cudaGraphDestroy(graph),
                               label + " destroy graph") &&
                  ready;
        }
        return ready && node_count == 1U;
      };
  const auto same_launch_configuration =
      [](const cudaKernelNodeParams& first,
         const cudaKernelNodeParams& second) {
        return first.func == second.func &&
               first.gridDim.x == second.gridDim.x &&
               first.gridDim.y == second.gridDim.y &&
               first.gridDim.z == second.gridDim.z &&
               first.blockDim.x == second.blockDim.x &&
               first.blockDim.y == second.blockDim.y &&
               first.blockDim.z == second.blockDim.z &&
               first.sharedMemBytes == second.sharedMemBytes;
      };
  const auto same_launch_topology =
      [](const cudaKernelNodeParams& first,
         const cudaKernelNodeParams& second) {
        return first.gridDim.x == second.gridDim.x &&
               first.gridDim.y == second.gridDim.y &&
               first.gridDim.z == second.gridDim.z &&
               first.blockDim.x == second.blockDim.x &&
               first.blockDim.y == second.blockDim.y &&
               first.blockDim.z == second.blockDim.z &&
               first.sharedMemBytes == second.sharedMemBytes;
      };

  cudaKernelNodeParams public_params{};
  cudaKernelNodeParams performance_params{};
  cudaKernelNodeParams ping_pong_params{};
  cudaKernelNodeParams tail_barrier_params{};
  const bool public_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_gemv_qkv_z_bf16_cuda(
                fake_qkv_weights, 1.0F / 64.0F, fake_z_weights,
                1.0F / 96.0F, fake_activation, kQkvRows, kZRows, kColumns,
                fake_qkv_output, fake_z_output, static_cast<void*>(stream));
      },
      "FP8 M1 QKV/Z public production launcher", &public_params);
  const bool performance_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_qkv_z_two_phase_fused_grid_cap_test_cuda(
                fake_qkv_weights, 1.0F / 64.0F, fake_z_weights,
                1.0F / 96.0F, fake_activation, kQkvRows, kZRows, kColumns,
                fake_qkv_output, fake_z_output, kProductionBlocks,
                static_cast<void*>(stream));
      },
      "FP8 M1 QKV/Z performance cap1536 launcher", &performance_params);
  const bool ping_pong_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_qkv_z_reduction_scratch_ping_pong_grid_cap_test_cuda(
                fake_qkv_weights, 1.0F / 64.0F, fake_z_weights,
                1.0F / 96.0F, fake_activation, kQkvRows, kZRows, kColumns,
                fake_qkv_output, fake_z_output, kProductionBlocks,
                static_cast<void*>(stream));
      },
      "FP8 M1 QKV/Z reduction-scratch ping-pong cap1536 launcher",
      &ping_pong_params);
  const bool tail_barrier_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_qkv_z_tail_barrier_grid_cap_test_cuda(
                fake_qkv_weights, 1.0F / 64.0F, fake_z_weights,
                1.0F / 96.0F, fake_activation, kQkvRows, kZRows, kColumns,
                fake_qkv_output, fake_z_output, kProductionBlocks,
                static_cast<void*>(stream));
      },
      "FP8 M1 QKV/Z tail-barrier predecessor cap1536 launcher",
      &tail_barrier_params);
  const bool exact_topology =
      public_params.gridDim.x == kProductionBlocks &&
      public_params.gridDim.y == 1U && public_params.gridDim.z == 1U &&
      public_params.blockDim.x == 256U && public_params.blockDim.y == 1U &&
      public_params.blockDim.z == 1U && public_params.sharedMemBytes == 0U;
  const bool launch_identity =
      public_captured && performance_captured && exact_topology &&
      same_launch_configuration(public_params, performance_params);
  test.expect(launch_identity,
              "FP8 M1 QKV/Z public and cap1536 performance launchers use "
              "the same exact production kernel configuration");
  const bool ping_pong_graph_contract =
      ping_pong_captured && exact_topology &&
      same_launch_configuration(public_params, ping_pong_params);
  test.expect(ping_pong_graph_contract,
              "FP8 M1 QKV/Z direct ping-pong test hook reaches the exact "
              "public production kernel configuration");
  const bool tail_barrier_graph_contract =
      tail_barrier_captured && exact_topology &&
      tail_barrier_params.func != public_params.func &&
      same_launch_topology(public_params, tail_barrier_params);
  test.expect(tail_barrier_graph_contract,
              "FP8 M1 QKV/Z tail-barrier predecessor is a distinct kernel "
              "with the exact production launch topology");
  cudaGraph_t invalid_graph = nullptr;
  bool invalid_capture_ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      "FP8 M1 QKV/Z ping-pong invalid begin capture");
  cudaError_t invalid_capture_status = cudaSuccess;
  if (invalid_capture_ready) {
    invalid_capture_status = static_cast<cudaError_t>(
        q3x::kernels::
            launch_sm87_fp8_w8a16_m1_qkv_z_reduction_scratch_ping_pong_grid_cap_test_cuda(
                fake_qkv_weights, 1.0F / 64.0F, fake_z_weights,
                1.0F / 96.0F, fake_activation, kQkvRows, kZRows, kColumns,
                fake_qkv_output, fake_z_output, 0U,
                static_cast<void*>(stream)));
    invalid_capture_ready =
        test.cuda_ok(cudaStreamEndCapture(stream, &invalid_graph),
                     "FP8 M1 QKV/Z ping-pong invalid end capture") &&
        invalid_capture_ready;
  }
  std::size_t invalid_node_count = 0U;
  if (invalid_capture_ready && invalid_graph != nullptr) {
    invalid_capture_ready =
        test.cuda_ok(
            cudaGraphGetNodes(invalid_graph, nullptr, &invalid_node_count),
            "FP8 M1 QKV/Z ping-pong invalid query graph nodes") &&
        invalid_capture_ready;
  }
  if (invalid_graph != nullptr) {
    invalid_capture_ready =
        test.cuda_ok(cudaGraphDestroy(invalid_graph),
                     "FP8 M1 QKV/Z ping-pong invalid destroy graph") &&
        invalid_capture_ready;
  }
  const bool ping_pong_invalid_zero_node =
      invalid_capture_ready && invalid_capture_status == cudaErrorInvalidValue &&
      invalid_node_count == 0U;
  test.expect(ping_pong_invalid_zero_node,
              "FP8 M1 QKV/Z ping-pong invalid cap is rejected and captures "
              "zero graph nodes");

  Fp8KvPairKernelResources resources{};
  const bool resource_query_ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_two_phase_fused_resources_test_cuda(
              &resources.registers_per_thread,
              &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)),
      "FP8 M1 QKV/Z production resource query");
  const bool resource_contract =
      resource_query_ready && resources.registers_per_thread == 64 &&
      resources.static_shared_bytes == 1'280U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block == 256 &&
      resources.active_blocks_per_sm == 4;
  test.expect(resource_contract,
              "FP8 M1 QKV/Z production kernel preserves its frozen resource "
              "contract");
  Fp8KvPairKernelResources ping_pong_resources{};
  const bool ping_pong_resource_query_ready = test.cuda_ok(
      static_cast<cudaError_t>(
          q3x::kernels::
              query_sm87_fp8_w8a16_m1_qkv_z_reduction_scratch_ping_pong_resources_test_cuda(
                  &ping_pong_resources.registers_per_thread,
                  &ping_pong_resources.static_shared_bytes,
                  &ping_pong_resources.local_bytes,
                  &ping_pong_resources.maximum_threads_per_block,
                  &ping_pong_resources.active_blocks_per_sm)),
      "FP8 M1 QKV/Z reduction-scratch ping-pong resource query");
  const bool ping_pong_resource_contract =
      ping_pong_resource_query_ready &&
      ping_pong_resources.registers_per_thread == 64 &&
      ping_pong_resources.static_shared_bytes == 1'280U &&
      ping_pong_resources.local_bytes == 0U &&
      ping_pong_resources.maximum_threads_per_block == 256 &&
      ping_pong_resources.active_blocks_per_sm == 4;
  test.expect(ping_pong_resource_contract,
              "FP8 M1 QKV/Z reduction-scratch ping-pong production hook "
              "clears its frozen resource gate");
  const bool production_resource_identity =
      ping_pong_resource_query_ready && resource_query_ready &&
      ping_pong_resources.registers_per_thread ==
          resources.registers_per_thread &&
      ping_pong_resources.static_shared_bytes ==
          resources.static_shared_bytes &&
      ping_pong_resources.local_bytes == resources.local_bytes &&
      ping_pong_resources.maximum_threads_per_block ==
          resources.maximum_threads_per_block &&
      ping_pong_resources.active_blocks_per_sm ==
          resources.active_blocks_per_sm;
  test.expect(production_resource_identity,
              "FP8 M1 QKV/Z production and direct ping-pong resource hooks "
              "describe the same kernel");
  const bool ping_pong_resource_null_rejected =
      static_cast<cudaError_t>(
          q3x::kernels::
              query_sm87_fp8_w8a16_m1_qkv_z_reduction_scratch_ping_pong_resources_test_cuda(
                  nullptr, &ping_pong_resources.static_shared_bytes,
                  &ping_pong_resources.local_bytes,
                  &ping_pong_resources.maximum_threads_per_block,
                  &ping_pong_resources.active_blocks_per_sm)) ==
      cudaErrorInvalidValue;
  test.expect(ping_pong_resource_null_rejected,
              "FP8 M1 QKV/Z reduction-scratch ping-pong resource query "
              "rejects a null destination");
  std::cout << "FP8_M1_QKV_Z_PRODUCTION_IDENTITY: public_captured="
            << (public_captured ? "true" : "false")
            << " performance_captured="
            << (performance_captured ? "true" : "false")
            << " ping_pong_hook_captured="
            << (ping_pong_captured ? "true" : "false")
            << " public_performance_ping_pong_same_func_grid_block_shared="
            << (launch_identity && ping_pong_graph_contract ? "true"
                                                            : "false")
            << " tail_predecessor_captured="
            << (tail_barrier_captured ? "true" : "false")
            << " tail_predecessor_distinct_same_topology="
            << (tail_barrier_graph_contract ? "true" : "false")
            << " grid=" << public_params.gridDim.x
            << " block=" << public_params.blockDim.x
            << " dynamic_shared_bytes=" << public_params.sharedMemBytes
            << " registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " expected_barrier_instructions=2"
            << " tail_predecessor_expected_barrier_instructions=3"
            << " gate="
            << (launch_identity && ping_pong_graph_contract &&
                        tail_barrier_graph_contract && resource_contract &&
                        production_resource_identity
                    ? "PASS"
                    : "FAIL")
            << '\n';
  std::cout << "FP8_M1_QKV_Z_REDUCTION_SCRATCH_PING_PONG_CONTRACT:"
            << " captured=" << (ping_pong_captured ? "true" : "false")
            << " same_public_production_function="
            << (ping_pong_graph_contract ? "true" : "false")
            << " tail_predecessor_distinct_same_topology="
            << (tail_barrier_graph_contract ? "true" : "false")
            << " grid=" << ping_pong_params.gridDim.x
            << " block=" << ping_pong_params.blockDim.x
            << " dynamic_shared_bytes=" << ping_pong_params.sharedMemBytes
            << " registers_per_thread="
            << ping_pong_resources.registers_per_thread
            << " static_shared_bytes="
            << ping_pong_resources.static_shared_bytes
            << " local_bytes=" << ping_pong_resources.local_bytes
            << " active_blocks_per_sm="
            << ping_pong_resources.active_blocks_per_sm
            << " expected_barrier_instructions=2"
            << " tail_predecessor_expected_barrier_instructions=3"
            << " invalid_zero_node_gate="
            << (ping_pong_invalid_zero_node ? "PASS" : "FAIL")
            << " null_resource_gate="
            << (ping_pong_resource_null_rejected ? "PASS" : "FAIL")
            << " gate="
            << (ping_pong_graph_contract && ping_pong_invalid_zero_node &&
                        ping_pong_resource_contract &&
                        ping_pong_resource_null_rejected &&
                        production_resource_identity &&
                        tail_barrier_graph_contract
                    ? "PASS"
                    : "FAIL")
            << '\n';
}

void run_optional_fp8_m1_qkv_z_fusion_performance(
    TestContext& test, cudaStream_t stream) {
  if (!fp8_m1_qkv_z_fusion_performance_enabled()) {
    std::cout << "SKIP: FP8 M1 QKV/Z fusion gate; set "
                 "Q3X_RUN_SM87_FP8_M1_QKV_Z_FUSION_PERF=1 together with "
                 "Q3X_FP8_M1_QKV_Z_ACTUAL_CHECKPOINT_FILE and "
                 "Q3X_FP8_M1_QKV_Z_ACTUAL_CHECKPOINT_OFFSETS to enable\n";
    return;
  }

  constexpr std::size_t kQkvRows = 10'240U;
  constexpr std::size_t kZRows = 6'144U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::uint64_t kExpectedQkvOffset = 3'485'125'152ULL;
  constexpr std::uint64_t kExpectedZOffset = 3'537'553'952ULL;
  constexpr std::string_view kExpectedQkvSha256 =
      "66eeb8a7cfd3f577a4f7bafdb5b68f4f7ba3cb1aa9717801082791b2de696ed7";
  constexpr std::string_view kExpectedZSha256 =
      "79a60d790f4ca146c05ea2efeff51964f825b1cdd92a83c8ee11b9fe9cfafdae";
  constexpr std::size_t kQkvBaselineCap = 1'536U;
  constexpr std::size_t kZBaselineCap = 768U;
  constexpr std::size_t kCorrectnessCap = 1'280U;
  constexpr std::array<std::size_t, 5U> kCandidateCaps{{
      768U, 1'024U, 1'280U, 1'536U, 2'048U,
  }};
  constexpr std::array<Fp8M2CodeDistribution, 2U> kDistributions{{
      Fp8M2CodeDistribution::kCheckpointLike,
      Fp8M2CodeDistribution::kSameBankStress,
  }};
  constexpr float kQkvWeightScale = 1.0F / 64.0F;
  constexpr float kZWeightScale = 1.0F / 96.0F;
  constexpr std::size_t kGuardElements = 16U;
  constexpr std::uint16_t kQkvGuard = 0xa5a5U;
  constexpr std::uint16_t kZGuard = 0x5a5aU;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 80;
  constexpr int kMeasurementRounds = 5;
  // Freeze the production-evidence policy before collecting independent
  // repeats. The actual checkpoint fixture carries the production value
  // threshold; the synthetic adversarial fixture is a non-regression guard.
  constexpr double kExploratorySymmetricSpeedup = 1.01;
  constexpr double kRequiredActualCheckpointSpeedup = 1.02;
  constexpr double kRequiredStressSpeedup = 1.00;
  const char* const candidate_name = "qkv_z_two_phase_fused";
  using CandidateLauncher = int (*)(
      const std::uint8_t*, float, const std::uint8_t*, float,
      const std::uint16_t*, std::size_t, std::size_t, std::size_t,
      std::uint16_t*, std::uint16_t*, std::size_t, void*) noexcept;
  using CandidateResourceQuery = int (*)(
      int*, std::size_t*, std::size_t*, int*, int*) noexcept;
  const CandidateLauncher candidate_launcher =
      q3x::kernels::
          launch_sm87_fp8_w8a16_m1_qkv_z_two_phase_fused_grid_cap_test_cuda;
  const CandidateResourceQuery candidate_resource_query =
      q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_two_phase_fused_resources_test_cuda;
  const std::string label =
      std::string("FP8 M1 fused QKV10240/Z6144 K5120 candidate=") +
      candidate_name;
  const q3x::core::Sha256FileResult binary_identity =
      q3x::core::sha256_file("/proc/self/exe");
  test.expect(binary_identity.ok(), label + " hashes the running test binary");
  if (!binary_identity.ok()) {
    std::cout << "FP8_M1_QKV_Z_BINARY_IDENTITY: candidate="
              << candidate_name << " sha256=unavailable error="
              << binary_identity.error << " gate=FAIL\n";
    return;
  }
  std::cout << "FP8_M1_QKV_Z_BINARY_IDENTITY: candidate="
            << candidate_name
            << " sha256=" << binary_identity.digest->hex()
            << " gate=PASS\n";
  std::cout << "FP8_M1_QKV_Z_FUSION_MODE: candidate=" << candidate_name
            << " topology=frozen_two_phase_1536_768\n";

  const char* const checkpoint_file_value =
      std::getenv("Q3X_FP8_M1_QKV_Z_ACTUAL_CHECKPOINT_FILE");
  const char* const checkpoint_offsets_value =
      std::getenv("Q3X_FP8_M1_QKV_Z_ACTUAL_CHECKPOINT_OFFSETS");
  const bool checkpoint_file_set =
      checkpoint_file_value != nullptr && checkpoint_file_value[0] != '\0';
  const bool checkpoint_offsets_set =
      checkpoint_offsets_value != nullptr &&
      checkpoint_offsets_value[0] != '\0';
  const bool production_evidence_source_gate =
      checkpoint_file_set && checkpoint_offsets_set;
  test.expect(production_evidence_source_gate,
              label + " production gate requires actual checkpoint file "
                      "and offsets");
  if (!production_evidence_source_gate) {
    std::cout << "FP8_M1_QKV_Z_CHECKPOINT_SOURCE: candidate="
              << candidate_name << " source=missing"
              << " required_env=Q3X_FP8_M1_QKV_Z_ACTUAL_CHECKPOINT_FILE,"
                 "Q3X_FP8_M1_QKV_Z_ACTUAL_CHECKPOINT_OFFSETS gate=FAIL\n";
    return;
  }
  const std::string checkpoint_file = checkpoint_file_value;
  std::array<std::uint64_t, 2U> checkpoint_offsets{};
  const bool parsed = parse_fp8_qkv_z_checkpoint_offsets(
      checkpoint_offsets_value, checkpoint_offsets);
  test.expect(parsed,
              label + " parses exactly two decimal checkpoint offsets");
  if (!parsed) {
    return;
  }
  const bool checkpoint_offsets_match =
      checkpoint_offsets[0U] == kExpectedQkvOffset &&
      checkpoint_offsets[1U] == kExpectedZOffset;
  test.expect(checkpoint_offsets_match,
              label + " uses the pinned layer-0 QKV/Z payload offsets");
  if (!checkpoint_offsets_match) {
    return;
  }
  std::cout << "FP8_M1_QKV_Z_CHECKPOINT_SOURCE: candidate="
            << candidate_name << " source=actual"
            << " path=" << checkpoint_file
            << " qkv_tensor=model.language_model.layers.0.linear_attn."
               "in_proj_qkv.weight"
            << " z_tensor=model.language_model.layers.0.linear_attn."
               "in_proj_z.weight"
            << " qkv_offset=" << checkpoint_offsets[0U]
            << " z_offset=" << checkpoint_offsets[1U] << '\n';
  std::cout << "FP8_M1_QKV_Z_PRODUCTION_POLICY: candidate="
            << candidate_name
            << " required_actual_checkpoint_speedup="
            << kRequiredActualCheckpointSpeedup
            << " required_same_bank_stress_speedup="
            << kRequiredStressSpeedup
            << " exploratory_symmetric_speedup="
            << kExploratorySymmetricSpeedup
            << " actual_checkpoint_required_for_two_phase=true"
            << " source_gate="
            << (production_evidence_source_gate ? "PASS" : "FAIL") << '\n';

  Fp8KvPairKernelResources resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(candidate_resource_query(
          &resources.registers_per_thread, &resources.static_shared_bytes,
          &resources.local_bytes, &resources.maximum_threads_per_block,
          &resources.active_blocks_per_sm)),
      label + " query fused kernel resources");
  if (!ready) {
    return;
  }
  const bool resource_gate =
      resources.registers_per_thread == 64 &&
      resources.static_shared_bytes == 1'280U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block == 256 &&
      resources.active_blocks_per_sm == 4;
  std::cout << "PERF_FP8_M1_QKV_Z_FUSION_RESOURCES:"
            << " candidate=" << candidate_name
            << " registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " maximum_threads_per_block="
            << resources.maximum_threads_per_block
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " required_registers_per_thread=64"
            << " required_static_shared_bytes=1280"
            << " require_zero_local_bytes=true"
            << " required_threads_per_block=256"
            << " required_active_blocks_per_sm=4"
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  test.expect(resource_gate, label + " clears the frozen resource gate");
  const bool resource_query_null_rejected =
      static_cast<cudaError_t>(candidate_resource_query(
          nullptr, &resources.static_shared_bytes, &resources.local_bytes,
          &resources.maximum_threads_per_block,
          &resources.active_blocks_per_sm)) == cudaErrorInvalidValue;
  test.expect(resource_query_null_rejected,
