            << " z_offset=" << kExpectedZOffset
            << " z_bytes=" << host_z_weights.size()
            << " z_sha256=" << z_sha256
            << " a_offset=" << kExpectedAOffset
            << " a_bytes="
            << host_a_weights.size() * sizeof(std::uint16_t)
            << " a_sha256=" << a_sha256
            << " b_offset=" << kExpectedBOffset
            << " b_bytes="
            << host_b_weights.size() * sizeof(std::uint16_t)
            << " b_sha256=" << b_sha256
            << " qkv_scale_offset=" << kExpectedQkvScaleOffset
            << " qkv_scale=" << qkv_weight_scale
            << " z_scale_offset=" << kExpectedZScaleOffset
            << " z_scale=" << z_weight_scale
            << " gate=PASS\n";

  if (!upload_fixture(label + " actual checkpoint")) {
    return;
  }
  const bool actual_bitwise_gate =
      run_direct_diff(label + " actual checkpoint");

  if (cs_performance_enabled) {
    constexpr double kRequiredActualSpeedup = 1.005;
    constexpr double kRequiredStressSpeedup = 1.0;
    constexpr double kRequiredPerProcessProjectedDeltaMs = 0.20;
    constexpr double kRequiredThreeProcessMedianProjectedDeltaMs = 0.25;
    const bool actual_cs_bitwise_gate =
        run_cs_direct_diff(label + " actual checkpoint");
    const LinearQkvCsTiming actual_cs_timing =
        actual_cs_bitwise_gate ? benchmark_cs_fixture("actual_checkpoint")
                               : LinearQkvCsTiming{};
    const bool actual_cs_timing_gate =
        actual_cs_timing.ready &&
        actual_cs_timing.every_round_nonregressing &&
        std::isfinite(actual_cs_timing.paired_median_speedup) &&
        actual_cs_timing.paired_median_speedup >= kRequiredActualSpeedup &&
        std::isfinite(actual_cs_timing.projected_48_layer_delta_ms) &&
        actual_cs_timing.projected_48_layer_delta_ms >=
            kRequiredPerProcessProjectedDeltaMs;
    const bool stress_cs_timing_gate =
        stress_cs_timing.ready &&
        stress_cs_timing.every_round_nonregressing &&
        std::isfinite(stress_cs_timing.paired_median_speedup) &&
        stress_cs_timing.paired_median_speedup >= kRequiredStressSpeedup;
    const bool cs_process_gate =
        default_gate && payload_hash_gate && synthetic_cs_bitwise_gate &&
        actual_cs_bitwise_gate && actual_cs_timing_gate &&
        stress_cs_timing_gate;
    if (joint_mode) {
      joint_result->completed = true;
      joint_result->correctness_gate =
          default_gate && payload_hash_gate && synthetic_cs_bitwise_gate &&
          actual_bitwise_gate && actual_cs_bitwise_gate;
      joint_result->actual_every_round_strictly_improves =
          actual_cs_timing.ready &&
          actual_cs_timing.every_round_strictly_improves;
      joint_result->stress_every_round_strictly_improves =
          stress_cs_timing.ready &&
          stress_cs_timing.every_round_strictly_improves;
      joint_result->actual_speedups = actual_cs_timing.round_speedups;
      joint_result->actual_deltas_ms = actual_cs_timing.round_deltas_ms;
      joint_result->stress_speedups = stress_cs_timing.round_speedups;
      joint_result->stress_deltas_ms = stress_cs_timing.round_deltas_ms;
      joint_result->actual_median_speedup =
          actual_cs_timing.paired_median_speedup;
      joint_result->actual_median_delta_ms =
          actual_cs_timing.paired_median_delta_ms;
      joint_result->stress_median_speedup =
          stress_cs_timing.paired_median_speedup;
      joint_result->stress_median_delta_ms =
          stress_cs_timing.paired_median_delta_ms;
      joint_result->projected_delta_ms =
          actual_cs_timing.projected_48_layer_delta_ms;
      std::cout << "PERF_DECODE_PROJECTION_PALETTE_V2_COMPONENT:"
                << " component=qkv"
                << " baseline=rollback_tail_composite_default_cache_test_abi"
                << " candidate=public_selected_qkv_z_fp8_weight_cs"
                << " actual_median_speedup="
                << joint_result->actual_median_speedup
                << " stress_median_speedup="
                << joint_result->stress_median_speedup
                << " actual_delta_ms_per_layer="
                << joint_result->actual_median_delta_ms
                << " projected_48_layer_delta_ms="
                << joint_result->projected_delta_ms
                << " actual_every_round_strictly_gt_1="
                << (joint_result->actual_every_round_strictly_improves
                        ? "true"
                        : "false")
                << " stress_every_round_strictly_gt_1="
                << (joint_result->stress_every_round_strictly_improves
                        ? "true"
                        : "false")
                << " correctness="
                << (joint_result->correctness_gate ? "PASS" : "FAIL")
                << " isolated_absolute_gate=not_applied"
                << " gate=pending_joint_aggregation\n";
    } else {
      test.expect(
          cs_process_gate,
          label + " rollback-versus-selected process clears frozen gate");
      std::cout << "PERF_FP8_M1_LINEAR_QKV_CS_SELECTED:"
              << " baseline=rollback_tail_composite_default_cache_test_abi"
              << " candidate=public_selected_qkv_z_fp8_weight_cs"
              << " actual_baseline_median_ms="
              << actual_cs_timing.baseline_median_ms
              << " actual_candidate_median_ms="
              << actual_cs_timing.candidate_median_ms
              << " actual_paired_median_speedup="
              << actual_cs_timing.paired_median_speedup
              << " actual_paired_median_delta_ms="
              << actual_cs_timing.paired_median_delta_ms
              << " actual_projected_48_layer_delta_ms="
              << actual_cs_timing.projected_48_layer_delta_ms
              << " actual_every_round_nonregressing="
              << (actual_cs_timing.every_round_nonregressing ? "true"
                                                              : "false")
              << " stress_baseline_median_ms="
              << stress_cs_timing.baseline_median_ms
              << " stress_candidate_median_ms="
              << stress_cs_timing.candidate_median_ms
              << " stress_paired_median_speedup="
              << stress_cs_timing.paired_median_speedup
              << " stress_paired_median_delta_ms="
              << stress_cs_timing.paired_median_delta_ms
              << " stress_every_round_nonregressing="
              << (stress_cs_timing.every_round_nonregressing ? "true"
                                                              : "false")
              << " required_actual_speedup=" << kRequiredActualSpeedup
              << " required_stress_speedup=" << kRequiredStressSpeedup
              << " required_each_round_speedup=1"
              << " required_per_process_projected_48_layer_delta_ms="
              << kRequiredPerProcessProjectedDeltaMs
              << " required_three_process_median_projected_48_layer_delta_ms="
              << kRequiredThreeProcessMedianProjectedDeltaMs
              << " three_process_median_gate=pending_external_aggregation"
              << " claim_scope=isolated_qkv_z_ab_tail_composite"
              << " projection_scope=arithmetic_48_layer_only"
              << " end_to_end_claim=none"
              << " actual_bitwise_guard="
              << (actual_cs_bitwise_gate ? "PASS" : "FAIL")
              << " stress_bitwise_guard="
              << (synthetic_cs_bitwise_gate ? "PASS" : "FAIL")
              << " payload_hashes=" << (payload_hash_gate ? "PASS" : "FAIL")
              << " default_gate=" << (default_gate ? "PASS" : "FAIL")
              << " gate=" << (cs_process_gate ? "PASS" : "FAIL") << '\n';
    }
  }

  if (!predecessor_composite_performance_enabled) {
    return;
  }

  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 80;
  constexpr int kMeasurementRounds = 5;
  constexpr float kRequiredProjectedDeltaMilliseconds =
      0.5F / static_cast<float>(kAbRows);
  constexpr double kRequiredSpeedup = 1.0215;
  bool timing_ready = actual_bitwise_gate;
  for (int iteration = 0;
       iteration < kWarmupIterations && timing_ready; ++iteration) {
    timing_ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                                label + " actual baseline warmup");
    timing_ready = test.cuda_ok(static_cast<cudaError_t>(launch_candidate()),
                                label + " actual candidate warmup") &&
                   timing_ready;
  }
  timing_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                              label + " actual warmup synchronize") &&
                 timing_ready;
  constexpr std::size_t kTimedPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  std::array<float, kTimedPasses> baseline_passes{};
  std::array<float, kTimedPasses> candidate_passes{};
  std::array<float, kMeasurementRounds> paired_deltas{};
  bool all_rounds_improve = timing_ready;
  for (int round = 0; round < kMeasurementRounds && timing_ready; ++round) {
    const std::string round_label =
        label + " actual round=" + std::to_string(round + 1);
    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        round_label + " B1");
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        round_label + " C1");
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        round_label + " C2");
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        round_label + " B2");
    const std::size_t pass = 2U * static_cast<std::size_t>(round);
    baseline_passes[pass] = baseline_first;
    baseline_passes[pass + 1U] = baseline_second;
    candidate_passes[pass] = candidate_first;
    candidate_passes[pass + 1U] = candidate_second;
    const bool finite = std::isfinite(baseline_first) &&
                        std::isfinite(candidate_first) &&
                        std::isfinite(candidate_second) &&
                        std::isfinite(baseline_second) &&
                        baseline_first > 0.0F && candidate_first > 0.0F &&
                        candidate_second > 0.0F && baseline_second > 0.0F;
    timing_ready = timing_ready && finite;
    const float paired_baseline =
        0.5F * (baseline_first + baseline_second);
    const float paired_candidate =
        0.5F * (candidate_first + candidate_second);
    paired_deltas[static_cast<std::size_t>(round)] =
        paired_baseline - paired_candidate;
    const bool round_improves =
        finite && candidate_first < baseline_first &&
        candidate_second < baseline_second &&
        paired_candidate < paired_baseline;
    all_rounds_improve = all_rounds_improve && round_improves;
    std::cout << "PERF_FP8_M1_QKV_Z_BF16_AB_COMPOSITE_ROUND:"
              << " round=" << round + 1 << " order=B-C-C-B"
              << " logical_chains_per_pass=" << kMeasuredIterations
              << " baseline_pass1_ms=" << baseline_first
              << " candidate_pass1_ms=" << candidate_first
              << " candidate_pass2_ms=" << candidate_second
              << " baseline_pass2_ms=" << baseline_second
              << " paired_delta_ms="
              << paired_deltas[static_cast<std::size_t>(round)]
              << " gate=" << (round_improves ? "PASS" : "FAIL") << '\n';
  }
  const float baseline_median =
      timing_ready ? median_fp8_kv_pair_timing(baseline_passes)
                   : std::numeric_limits<float>::quiet_NaN();
  const float candidate_median =
      timing_ready ? median_fp8_kv_pair_timing(candidate_passes)
                   : std::numeric_limits<float>::quiet_NaN();
  const float delta_median =
      timing_ready ? median_fp8_kv_pair_timing(paired_deltas)
                   : std::numeric_limits<float>::quiet_NaN();
  const double speedup =
      static_cast<double>(baseline_median) /
      static_cast<double>(candidate_median);
  const double projected_decode_delta =
      static_cast<double>(delta_median) * static_cast<double>(kAbRows);
  const bool timing_gate =
      timing_ready && all_rounds_improve &&
      delta_median >= kRequiredProjectedDeltaMilliseconds &&
      std::isfinite(speedup) && speedup >= kRequiredSpeedup;
  test.expect(timing_gate,
              label + " clears the actual-checkpoint B-C-C-B value gate");
  std::cout << "PERF_FP8_M1_QKV_Z_BF16_AB_COMPOSITE_SELECTED:"
            << " baseline_two_kernel_median_ms=" << baseline_median
            << " candidate_one_kernel_median_ms=" << candidate_median
            << " median_delta_ms_per_layer=" << delta_median
            << " projected_48_layer_delta_ms=" << projected_decode_delta
            << " speedup=" << speedup
            << " all_rounds_improve="
            << (all_rounds_improve ? "true" : "false")
            << " required_delta_ms_per_layer="
            << kRequiredProjectedDeltaMilliseconds
            << " required_projected_48_layer_delta_ms=0.5"
            << " required_speedup=" << kRequiredSpeedup
            << " actual_bitwise_guard="
            << (actual_bitwise_gate ? "PASS" : "FAIL")
            << " payload_hashes=" << (payload_hash_gate ? "PASS" : "FAIL")
            << " default_gate=" << (default_gate ? "PASS" : "FAIL")
            << " gate="
            << (timing_gate && actual_bitwise_gate && payload_hash_gate &&
                        default_gate
                    ? "PASS"
                    : "FAIL")
            << '\n';
}

struct Fp8M2RowPairDistributionMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
};

struct Fp8M2RowPairMeasurement {
  std::array<Fp8M2RowPairDistributionMeasurement, 2U> distributions{};
};

[[nodiscard]] Fp8M2RowPairMeasurement benchmark_fp8_m2_row_pair_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 2U;
  constexpr std::size_t kProductionGridCap = 2'048U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 40;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<Fp8M2CodeDistribution, 2U> kDistributions{{
      Fp8M2CodeDistribution::kCheckpointLike,
      Fp8M2CodeDistribution::kSameBankStress,
  }};

  std::vector<std::uint8_t> host_weights(rows * columns);
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 29U + 5U) % 127U) - 63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokens * rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokens * rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  if (!ready) {
    return {};
  }

  Fp8M2RowPairMeasurement measurement;
  for (std::size_t distribution_index = 0U;
       distribution_index < kDistributions.size(); ++distribution_index) {
    const Fp8M2CodeDistribution distribution =
        kDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + fp8_m2_code_distribution_name(distribution);
    fill_fp8_m2_code_distribution(host_weights, rows, columns, distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(weights.get(), host_weights.data(),
                        host_weights.size(), cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize weights");
    if (!ready) {
      return measurement;
    }

    const auto launch_baseline = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_small_m2_grid_cap_test_cuda(
              weights.get(), kWeightScale, activations.get(), rows, columns,
              baseline_output.get(), kProductionGridCap,
              static_cast<void*>(stream));
    };
    const auto launch_candidate = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_small_m2_row_pair_test_cuda(
              weights.get(), kWeightScale, activations.get(), rows, columns,
              candidate_output.get(), static_cast<void*>(stream));
    };

    ready = test.cuda_ok(
        static_cast<cudaError_t>(launch_baseline()),
        distribution_label +
            " correctness preserved cap2048 single-row baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         distribution_label + " correctness direct row-pair");
    std::vector<std::uint16_t> baseline(kTokens * rows);
    std::vector<std::uint16_t> candidate(kTokens * rows);
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy baseline output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy direct row-pair output");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " correctness synchronize");
    if (!ready) {
      return measurement;
    }

    std::size_t mismatches = 0U;
    for (std::size_t index = 0U; index < baseline.size(); ++index) {
      mismatches += baseline[index] != candidate[index] ? 1U : 0U;
    }
    Fp8M2RowPairDistributionMeasurement& distribution_measurement =
        measurement.distributions[distribution_index];
    distribution_measurement.bitwise_equal = mismatches == 0U;
    test.expect(distribution_measurement.bitwise_equal,
                distribution_label +
                    " direct row-pair matches every preserved cap2048 BF16 "
                    "bit");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           distribution_label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           distribution_label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " warmup synchronize");
    if (!ready) {
      return measurement;
    }

    double baseline_total = 0.0;
    double candidate_total = 0.0;
    bool all_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          distribution_label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 2");
      const bool round_finite =
          std::isfinite(baseline_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(baseline_second);
      all_finite = all_finite && round_finite;
      if (round_finite) {
        baseline_total += baseline_first + baseline_second;
        candidate_total += candidate_first + candidate_second;
      }
      std::cout << "PERF_FP8_M2_ROW_PAIR_ROUND: " << label
                << " distribution="
                << fp8_m2_code_distribution_name(distribution)
                << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }
    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    distribution_measurement.baseline_milliseconds =
        all_finite ? static_cast<float>(baseline_total / kTimedPasses)
                   : std::numeric_limits<float>::quiet_NaN();
    distribution_measurement.candidate_milliseconds =
        all_finite ? static_cast<float>(candidate_total / kTimedPasses)
                   : std::numeric_limits<float>::quiet_NaN();
    const float speedup = distribution_measurement.baseline_milliseconds /
                          distribution_measurement.candidate_milliseconds;
    std::cout << "PERF_FP8_M2_ROW_PAIR: " << label << " distribution="
              << fp8_m2_code_distribution_name(distribution)
              << " preserved_cap2048_single_row_ms="
              << distribution_measurement.baseline_milliseconds
              << " direct_row_pair_ms="
              << distribution_measurement.candidate_milliseconds
              << " speedup=" << speedup << " bitwise_mismatches="
              << mismatches << '/' << baseline.size() << '\n';
  }
  return measurement;
}

void run_decode_fp8_qkv_z_register_prefetch_screen(TestContext& test,
                                                   cudaStream_t stream) {
  constexpr std::size_t kQkvRows = 10'240U;
  constexpr std::size_t kZRows = 6'144U;
  constexpr std::size_t kAbRows = 48U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kOutputCount = 4U;
  constexpr std::size_t kGuardElements = 16U;
  constexpr std::array<std::size_t, kOutputCount> kOutputElements{{
      kQkvRows,
      kZRows,
      kAbRows,
      kAbRows,
  }};
  constexpr std::uint64_t kExpectedQkvOffset = 3'485'125'152ULL;
  constexpr std::uint64_t kExpectedZOffset = 3'537'553'952ULL;
  constexpr std::uint64_t kExpectedAOffset = 2'543'016'896ULL;
  constexpr std::uint64_t kExpectedBOffset = 2'543'508'416ULL;
  constexpr std::uint64_t kExpectedQkvScaleOffset = 126'516ULL;
  constexpr std::uint64_t kExpectedZScaleOffset = 126'524ULL;
  constexpr std::string_view kExpectedQkvSha256 =
      "66eeb8a7cfd3f577a4f7bafdb5b68f4f7ba3cb1aa9717801082791b2de696ed7";
  constexpr std::string_view kExpectedZSha256 =
      "79a60d790f4ca146c05ea2efeff51964f825b1cdd92a83c8ee11b9fe9cfafdae";
  constexpr std::string_view kExpectedASha256 =
      "73465d67c2d85fc1dbe477df6d67794a979369e2edb032ca0f9af04c0c64568d";
  constexpr std::string_view kExpectedBSha256 =
      "e2c02daf895618828a36fcba4cd6b90ea8313587eca293baceebff549f509c90";
  constexpr std::string_view kExpectedQkvScaleSha256 =
      "d552446f521b6f79296f0473d8e8a66303ca4d1299688f286b90c7c923527021";
  constexpr std::string_view kExpectedZScaleSha256 =
      "861e5d0c508a43c225a124a22f8e12e331ad3abe057c528bdc3a256754b856e9";
  const std::string label =
      "Decode FP8 QKV/Z direct-LDG register-lookahead screen";

  if (!decode_fp8_qkv_z_register_prefetch_performance_enabled()) {
    std::cout
        << "SKIP: Decode FP8 QKV/Z register-lookahead formal screen; set "
           "Q3X_RUN_SM87_DECODE_FP8_QKV_Z_REGISTER_PREFETCH_PERF=1\n";
    return;
  }

  struct KernelResources {
    int registers_per_thread = -1;
    std::size_t static_shared_bytes =
        std::numeric_limits<std::size_t>::max();
    std::size_t local_bytes = std::numeric_limits<std::size_t>::max();
    int maximum_threads_per_block = -1;
    int active_blocks_per_sm = -1;
  };
  KernelResources production_resources{};
  KernelResources candidate_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_resources_test_cuda(
              &production_resources.registers_per_thread,
              &production_resources.static_shared_bytes,
              &production_resources.local_bytes,
              &production_resources.maximum_threads_per_block,
