  ready = test.cuda_ok(
              static_cast<cudaError_t>(q3x::kernels::
                  query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_register_lookahead_resources_test_cuda(
                      &candidate_resources.registers_per_thread,
