          ready;
  ready = copy_outputs(candidate_storage, candidate_outputs,
                       label + " copy candidate") &&
          ready;
  const bool direct_gate =
      ready && check_outputs(production_outputs, candidate_outputs, 0xa5U,
                             0x5aU, "actual_checkpoint_direct");

  struct CapturedKernel {
    cudaGraph_t graph = nullptr;
    cudaGraphExec_t executable = nullptr;
    std::size_t total_nodes = 0U;
    std::size_t root_nodes = 0U;
    cudaKernelNodeParams params{};
    bool ready = false;
  };
  const auto capture = [&](const auto& launch,
                           const std::string& capture_label) {
    CapturedKernel captured{};
    bool capture_ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        capture_label + " begin");
    int launch_status = static_cast<int>(cudaErrorUnknown);
    if (capture_ready) {
      launch_status = launch();
      capture_ready = test.cuda_ok(
                          cudaStreamEndCapture(stream, &captured.graph),
                          capture_label + " end") &&
                      capture_ready;
    }
    std::vector<cudaGraphNode_t> nodes;
    if (capture_ready) {
      capture_ready = test.cuda_ok(
                          cudaGraphGetNodes(captured.graph, nullptr,
                                            &captured.total_nodes),
                          capture_label + " count nodes") &&
                      capture_ready;
      capture_ready = test.cuda_ok(
                          cudaGraphGetRootNodes(captured.graph, nullptr,
                                                &captured.root_nodes),
                          capture_label + " count roots") &&
                      capture_ready;
      nodes.resize(captured.total_nodes);
    }
    if (capture_ready && !nodes.empty()) {
      std::size_t capacity = nodes.size();
      capture_ready = test.cuda_ok(
                          cudaGraphGetNodes(captured.graph, nodes.data(),
                                            &capacity),
                          capture_label + " enumerate nodes") &&
                      capture_ready;
      cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
      capture_ready = test.cuda_ok(cudaGraphNodeGetType(nodes.front(), &type),
                                   capture_label + " node type") &&
                      capture_ready;
      capture_ready =
          test.cuda_ok(cudaGraphKernelNodeGetParams(nodes.front(),
                                                    &captured.params),
                       capture_label + " kernel params") &&
          capture_ready && type == cudaGraphNodeTypeKernel;
    }
    captured.ready = capture_ready &&
                     launch_status == static_cast<int>(cudaSuccess);
    return captured;
  };
  CapturedKernel production_graph =
      capture(launch_production, label + " capture production");
  CapturedKernel candidate_graph =
      capture(launch_candidate, label + " capture candidate");
  const auto exact_topology = [](const cudaKernelNodeParams& params) {
    return params.gridDim.x == 1'536U && params.gridDim.y == 1U &&
           params.gridDim.z == 1U && params.blockDim.x == 256U &&
           params.blockDim.y == 1U && params.blockDim.z == 1U &&
           params.sharedMemBytes == 0U;
  };
  const bool graph_shape_gate =
      production_graph.ready && production_graph.total_nodes == 1U &&
      production_graph.root_nodes == 1U &&
      exact_topology(production_graph.params) && candidate_graph.ready &&
      candidate_graph.total_nodes == 1U &&
      candidate_graph.root_nodes == 1U &&
      exact_topology(candidate_graph.params) &&
      production_graph.params.func != candidate_graph.params.func;
  test.expect(graph_shape_gate,
              label + " captures distinct one-node 1536x256 routes");
  bool graph_replay_gate = graph_shape_gate;
  if (graph_replay_gate) {
    graph_replay_gate = test.cuda_ok(
        cudaGraphInstantiate(&production_graph.executable,
                             production_graph.graph, nullptr, nullptr, 0U),
        label + " instantiate production graph");
    graph_replay_gate = test.cuda_ok(
                            cudaGraphInstantiate(&candidate_graph.executable,
                                                 candidate_graph.graph,
                                                 nullptr, nullptr, 0U),
                            label + " instantiate candidate graph") &&
                        graph_replay_gate;
  }
  if (graph_replay_gate) {
    graph_replay_gate =
        poison(production_storage, 0xc3U, label + " graph production") &&
        poison(candidate_storage, 0x3cU, label + " graph candidate");
    graph_replay_gate = test.cuda_ok(
                            cudaGraphLaunch(production_graph.executable,
                                            stream),
                            label + " replay production graph") &&
                        graph_replay_gate;
    graph_replay_gate = test.cuda_ok(
                            cudaGraphLaunch(candidate_graph.executable,
                                            stream),
                            label + " replay candidate graph") &&
                        graph_replay_gate;
    graph_replay_gate = copy_outputs(production_storage, production_outputs,
                                     label + " graph production output") &&
                        graph_replay_gate;
    graph_replay_gate = copy_outputs(candidate_storage, candidate_outputs,
                                     label + " graph candidate output") &&
                        graph_replay_gate;
  }
  graph_replay_gate =
      graph_replay_gate &&
      check_outputs(production_outputs, candidate_outputs, 0xc3U, 0x3cU,
                    "actual_checkpoint_graph_replay");
  test.expect(graph_replay_gate, label + " graph replay is exact and guarded");
  std::cout << "FP8_M1_QKV_Z_REGISTER_PREFETCH_GRAPH:"
            << " production_nodes=" << production_graph.total_nodes
            << " candidate_nodes=" << candidate_graph.total_nodes
            << " production_roots=" << production_graph.root_nodes
            << " candidate_roots=" << candidate_graph.root_nodes
            << " distinct_function="
            << (graph_shape_gate ? "true" : "false")
            << " grid=1536 block=256 dynamic_shared_bytes=0"
            << " replay=" << (graph_replay_gate ? "bitwise_guarded" : "FAIL")
            << " gate="
            << (graph_shape_gate && graph_replay_gate ? "PASS" : "FAIL")
            << '\n';
  if (production_graph.executable != nullptr) {
    (void)test.cuda_ok(cudaGraphExecDestroy(production_graph.executable),
                       label + " destroy production graph executable");
  }
  if (candidate_graph.executable != nullptr) {
    (void)test.cuda_ok(cudaGraphExecDestroy(candidate_graph.executable),
                       label + " destroy candidate graph executable");
  }
  if (production_graph.graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(production_graph.graph),
                       label + " destroy production graph");
  }
  if (candidate_graph.graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(candidate_graph.graph),
                       label + " destroy candidate graph");
  }

  cudaGraph_t invalid_graph = nullptr;
  bool invalid_ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " invalid begin capture");
  std::array<int, 11U> invalid_statuses{};
  const auto invalid_launch =
      [&](const std::uint8_t* qkv, const float qkv_scale,
          const std::uint8_t* z, const std::uint16_t* a,
          const std::uint16_t* b, const std::uint16_t* x,
          const std::size_t qkv_rows, const std::size_t z_rows,
          const std::size_t ab_rows, const std::size_t columns,
          std::uint16_t* qkv_out, std::uint16_t* z_out,
          std::uint16_t* a_out, std::uint16_t* b_out) {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_register_lookahead_test_cuda(
                qkv, qkv_scale, z, z_weight_scale, a, b, x, qkv_rows,
                z_rows, ab_rows, columns, qkv_out, z_out, a_out, b_out,
                static_cast<void*>(stream));
      };
  if (invalid_ready) {
    auto* const qkv_out = output_pointer(candidate_storage, 0U);
    auto* const z_out = output_pointer(candidate_storage, 1U);
    auto* const a_out = output_pointer(candidate_storage, 2U);
    auto* const b_out = output_pointer(candidate_storage, 3U);
    invalid_statuses[0U] = invalid_launch(
        nullptr, qkv_weight_scale, z_weights.get(), a_weights.get(),
        b_weights.get(), activation.get(), kQkvRows, kZRows, kAbRows,
        kColumns, qkv_out, z_out, a_out, b_out);
    invalid_statuses[1U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, nullptr, a_weights.get(),
        b_weights.get(), activation.get(), kQkvRows, kZRows, kAbRows,
        kColumns, qkv_out, z_out, a_out, b_out);
    invalid_statuses[2U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), nullptr,
        b_weights.get(), activation.get(), kQkvRows, kZRows, kAbRows,
        kColumns, qkv_out, z_out, a_out, b_out);
    invalid_statuses[3U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), a_weights.get(),
        nullptr, activation.get(), kQkvRows, kZRows, kAbRows, kColumns,
        qkv_out, z_out, a_out, b_out);
    invalid_statuses[4U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), a_weights.get(),
        b_weights.get(), nullptr, kQkvRows, kZRows, kAbRows, kColumns,
        qkv_out, z_out, a_out, b_out);
    invalid_statuses[5U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), a_weights.get(),
        b_weights.get(), activation.get(), kQkvRows - 4U, kZRows, kAbRows,
        kColumns, qkv_out, z_out, a_out, b_out);
    invalid_statuses[6U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), a_weights.get(),
        b_weights.get(), activation.get(), kQkvRows, kZRows - 4U, kAbRows,
        kColumns, qkv_out, z_out, a_out, b_out);
    invalid_statuses[7U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), a_weights.get(),
        b_weights.get(), activation.get(), kQkvRows, kZRows, kAbRows - 1U,
        kColumns, qkv_out, z_out, a_out, b_out);
    invalid_statuses[8U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), a_weights.get(),
        b_weights.get(), activation.get(), kQkvRows, kZRows, kAbRows,
        kColumns - 16U, qkv_out, z_out, a_out, b_out);
    invalid_statuses[9U] = invalid_launch(
        qkv_weights.get(), -qkv_weight_scale, z_weights.get(),
        a_weights.get(), b_weights.get(), activation.get(), kQkvRows,
        kZRows, kAbRows, kColumns, qkv_out, z_out, a_out, b_out);
    invalid_statuses[10U] = invalid_launch(
        qkv_weights.get(), qkv_weight_scale, z_weights.get(), a_weights.get(),
        b_weights.get(), activation.get(), kQkvRows, kZRows, kAbRows,
        kColumns, qkv_out, z_out, qkv_out, b_out);
    invalid_ready = test.cuda_ok(
                        cudaStreamEndCapture(stream, &invalid_graph),
                        label + " invalid end capture") &&
                    invalid_ready;
  }
  std::size_t invalid_nodes = 0U;
  if (invalid_ready) {
    invalid_ready = test.cuda_ok(
                        cudaGraphGetNodes(invalid_graph, nullptr,
                                          &invalid_nodes),
                        label + " invalid count nodes") &&
                    invalid_ready;
  }
  if (invalid_graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(invalid_graph),
                       label + " invalid destroy graph");
  }
  const bool invalid_status_gate = std::all_of(
      invalid_statuses.begin(), invalid_statuses.end(), [](const int status) {
        return status == static_cast<int>(cudaErrorInvalidValue);
      });
  const bool invalid_gate =
      invalid_ready && invalid_status_gate && invalid_nodes == 0U;
  test.expect(invalid_gate,
              label + " rejects eleven invalid calls with zero nodes");
  std::cout << "FP8_M1_QKV_Z_REGISTER_PREFETCH_INVALID: cases=11"
            << " statuses="
            << (invalid_status_gate ? "all_invalid_value" : "BAD")
            << " captured_nodes=" << invalid_nodes
            << " gate=" << (invalid_gate ? "PASS" : "FAIL") << '\n';

  std::vector<std::uint8_t> recovered_fp8;
  std::vector<std::uint16_t> recovered_bf16;
  const auto fp8_input_preserved = [&](const DeviceBuffer<std::uint8_t>& input,
                                       const std::vector<std::uint8_t>& host,
                                       const std::string& input_label) {
    recovered_fp8.resize(host.size());
    bool copied = test.cuda_ok(
        cudaMemcpyAsync(recovered_fp8.data(), input.get(), host.size(),
                        cudaMemcpyDeviceToHost, stream),
        label + " recover " + input_label);
    copied = test.cuda_ok(cudaStreamSynchronize(stream),
                          label + " recover synchronize " + input_label) &&
             copied;
    return copied && recovered_fp8 == host;
  };
  const auto bf16_input_preserved =
      [&](const DeviceBuffer<std::uint16_t>& input,
          const std::vector<std::uint16_t>& host,
          const std::string& input_label) {
        recovered_bf16.resize(host.size());
        bool copied = test.cuda_ok(
            cudaMemcpyAsync(recovered_bf16.data(), input.get(),
                            host.size() * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            label + " recover " + input_label);
        copied = test.cuda_ok(cudaStreamSynchronize(stream),
                              label + " recover synchronize " + input_label) &&
                 copied;
        return copied && recovered_bf16 == host;
      };
  const bool input_gate =
      fp8_input_preserved(qkv_weights, host_qkv_weights, "QKV weights") &&
      fp8_input_preserved(z_weights, host_z_weights, "Z weights") &&
      bf16_input_preserved(a_weights, host_a_weights, "A weights") &&
      bf16_input_preserved(b_weights, host_b_weights, "B weights") &&
      bf16_input_preserved(activation, host_activation, "activation");
  test.expect(input_gate, label + " preserves all five input buffers");
  std::cout << "FP8_M1_QKV_Z_REGISTER_PREFETCH_INPUTS: buffers=5"
            << " gate=" << (input_gate ? "PASS" : "FAIL") << '\n';

  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 48;
  constexpr int kMeasurementRounds = 5;
  constexpr double kRequiredSpeedup = 1.022;
  constexpr double kRequiredProjected48LayerDeltaMs = 0.500;
  bool timing_ready = direct_gate && graph_shape_gate && graph_replay_gate &&
                      invalid_gate && input_gate && resource_gate &&
                      resource_null_gate && payload_hash_gate;
  for (int iteration = 0;
       iteration < kWarmupIterations && timing_ready; ++iteration) {
    timing_ready = test.cuda_ok(static_cast<cudaError_t>(launch_production()),
                                label + " production warmup") &&
                   timing_ready;
    timing_ready = test.cuda_ok(static_cast<cudaError_t>(launch_candidate()),
                                label + " candidate warmup") &&
                   timing_ready;
  }
  timing_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                              label + " warmup synchronize") &&
                 timing_ready;
  constexpr std::size_t kTimedPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  std::array<float, kTimedPasses> production_passes{};
  std::array<float, kTimedPasses> candidate_passes{};
  std::array<float, kMeasurementRounds> paired_speedups{};
  std::array<float, kMeasurementRounds> paired_deltas{};
  bool every_round_improves = timing_ready;
  for (int round = 0; round < kMeasurementRounds && timing_ready; ++round) {
    const bool production_first = (round & 1) == 0;
    const std::string round_label =
        label + " round=" + std::to_string(round + 1);
    float production1 = std::numeric_limits<float>::quiet_NaN();
    float production2 = std::numeric_limits<float>::quiet_NaN();
    float candidate1 = std::numeric_limits<float>::quiet_NaN();
    float candidate2 = std::numeric_limits<float>::quiet_NaN();
    if (production_first) {
      production1 = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          round_label + " B1");
      candidate1 = measure_small_m_tile(test, stream, launch_candidate,
                                        kMeasuredIterations,
                                        round_label + " C1");
      candidate2 = measure_small_m_tile(test, stream, launch_candidate,
                                        kMeasuredIterations,
                                        round_label + " C2");
      production2 = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          round_label + " B2");
    } else {
      candidate1 = measure_small_m_tile(test, stream, launch_candidate,
                                        kMeasuredIterations,
                                        round_label + " C1");
      production1 = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          round_label + " B1");
      production2 = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          round_label + " B2");
      candidate2 = measure_small_m_tile(test, stream, launch_candidate,
                                        kMeasuredIterations,
                                        round_label + " C2");
    }
    const std::size_t pass = 2U * static_cast<std::size_t>(round);
    production_passes[pass] = production1;
    production_passes[pass + 1U] = production2;
    candidate_passes[pass] = candidate1;
    candidate_passes[pass + 1U] = candidate2;
    const bool finite =
        std::isfinite(production1) && std::isfinite(production2) &&
        std::isfinite(candidate1) && std::isfinite(candidate2) &&
        production1 > 0.0F && production2 > 0.0F && candidate1 > 0.0F &&
        candidate2 > 0.0F;
    timing_ready = timing_ready && finite;
    const float paired_production = 0.5F * (production1 + production2);
    const float paired_candidate = 0.5F * (candidate1 + candidate2);
    const float paired_speedup = paired_production / paired_candidate;
    const float paired_delta = paired_production - paired_candidate;
    paired_speedups[static_cast<std::size_t>(round)] = paired_speedup;
    paired_deltas[static_cast<std::size_t>(round)] = paired_delta;
    const bool round_improves = finite && paired_speedup > 1.0F;
    every_round_improves = every_round_improves && round_improves;
    std::cout << "PERF_FP8_M1_QKV_Z_REGISTER_PREFETCH_ROUND:"
              << " round=" << round + 1
              << " order=" << (production_first ? "B-C-C-B" : "C-B-B-C")
              << " logical_launches_per_pass=" << kMeasuredIterations
              << " production_pass1_ms=" << production1
              << " candidate_pass1_ms=" << candidate1
              << " candidate_pass2_ms=" << candidate2
              << " production_pass2_ms=" << production2
              << " paired_speedup=" << paired_speedup
              << " paired_delta_ms=" << paired_delta
              << " gate=" << (round_improves ? "PASS" : "FAIL") << '\n';
  }
  const float production_median =
      timing_ready ? median_fp8_kv_pair_timing(production_passes)
                   : std::numeric_limits<float>::quiet_NaN();
  const float candidate_median =
      timing_ready ? median_fp8_kv_pair_timing(candidate_passes)
                   : std::numeric_limits<float>::quiet_NaN();
  const float paired_median_speedup =
      timing_ready ? median_fp8_kv_pair_timing(paired_speedups)
                   : std::numeric_limits<float>::quiet_NaN();
  const float paired_median_delta =
      timing_ready ? median_fp8_kv_pair_timing(paired_deltas)
                   : std::numeric_limits<float>::quiet_NaN();
  const double projected_48_layer_delta_ms =
      static_cast<double>(paired_median_delta) * 48.0;
  const bool timing_gate =
      timing_ready && every_round_improves &&
      std::isfinite(paired_median_speedup) &&
      paired_median_speedup >= kRequiredSpeedup &&
      std::isfinite(projected_48_layer_delta_ms) &&
      projected_48_layer_delta_ms >= kRequiredProjected48LayerDeltaMs;
  const bool process1_gate =
      resource_gate && resource_null_gate && payload_hash_gate && direct_gate &&
      graph_shape_gate && graph_replay_gate && invalid_gate && input_gate &&
      timing_gate;
  test.expect(process1_gate,
              label + " clears frozen process-1 stop-loss gate");
  std::cout << "PERF_FP8_M1_QKV_Z_REGISTER_PREFETCH_SELECTED:"
            << " baseline=production_tail_composite"
            << " candidate=test_only_rolled_direct_ldg_register_lookahead"
            << " production_median_ms=" << production_median
            << " candidate_median_ms=" << candidate_median
            << " paired_median_speedup=" << paired_median_speedup
            << " paired_median_delta_ms=" << paired_median_delta
            << " projected_48_layer_delta_ms="
            << projected_48_layer_delta_ms
            << " every_round_speedup_gt_1="
            << (every_round_improves ? "true" : "false")
            << " required_speedup=" << kRequiredSpeedup
            << " required_projected_48_layer_delta_ms="
            << kRequiredProjected48LayerDeltaMs
            << " source_outer_loop=runtime_rolled"
            << " fp8_load_cache_policy=compiler_default"
            << " source_prefetch_distance=one_stage"
            << " graph="
            << (graph_shape_gate && graph_replay_gate ? "PASS" : "FAIL")
            << " invalid_zero_node=" << (invalid_gate ? "PASS" : "FAIL")
            << " input_preservation=" << (input_gate ? "PASS" : "FAIL")
            << " process=1 stop_loss=true"
            << " gate=" << (process1_gate ? "PASS" : "FAIL") << '\n';
}

void run_decode_qkv_causal_conv_epilogue_screen(TestContext& test,
                                                 cudaStream_t stream) {
  constexpr std::size_t kQkvRows = q3x::runtime::kGdnQkvChannels;
  constexpr std::size_t kZRows = 6'144U;
  constexpr std::size_t kAbRows = 48U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kHistoryElements =
      kQkvRows * q3x::runtime::kGdnConvHistoryWidth;
  constexpr std::size_t kConvWeightElements =
      kQkvRows * q3x::runtime::kGdnConvKernelWidth;
  constexpr std::size_t kGuardElements = 16U;
  constexpr std::size_t kStateCount = 5U;
  constexpr std::size_t kHistoryIndex = 4U;
  constexpr std::array<std::size_t, kStateCount> kStateElements{{
      kQkvRows, kZRows, kAbRows, kAbRows, kHistoryElements,
  }};
  constexpr float kQkvScale = 1.0F / 64.0F;
  constexpr float kZScale = 1.0F / 96.0F;
  const std::string label =
      "Decode FP8 QKV/Z/A/B causal-conv epilogue screen";

  int registers_per_thread = -1;
  std::size_t static_shared_bytes =
      std::numeric_limits<std::size_t>::max();
  std::size_t local_bytes = std::numeric_limits<std::size_t>::max();
  int maximum_threads_per_block = -1;
  int active_blocks_per_sm = -1;
  const bool resource_ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_resources_test_cuda(
              &registers_per_thread, &static_shared_bytes, &local_bytes,
              &maximum_threads_per_block, &active_blocks_per_sm)),
      label + " query candidate resources");
  const bool resource_gate =
      resource_ready && registers_per_thread > 0 &&
      registers_per_thread <= 64 && static_shared_bytes <= 1'280U &&
      local_bytes == 0U && maximum_threads_per_block == 256 &&
      active_blocks_per_sm >= 4;
  test.expect(resource_gate,
              label + " clears the hard SM87 occupancy/spill gate");
  const std::array<int, 5U> null_resource_statuses{{
      q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_resources_test_cuda(
              nullptr, &static_shared_bytes, &local_bytes,
              &maximum_threads_per_block, &active_blocks_per_sm),
      q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_resources_test_cuda(
              &registers_per_thread, nullptr, &local_bytes,
              &maximum_threads_per_block, &active_blocks_per_sm),
      q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_resources_test_cuda(
              &registers_per_thread, &static_shared_bytes, nullptr,
              &maximum_threads_per_block, &active_blocks_per_sm),
      q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_resources_test_cuda(
              &registers_per_thread, &static_shared_bytes, &local_bytes,
              nullptr, &active_blocks_per_sm),
      q3x::kernels::
          query_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_resources_test_cuda(
              &registers_per_thread, &static_shared_bytes, &local_bytes,
              &maximum_threads_per_block, nullptr),
  }};
  const bool resource_null_gate =
      std::all_of(null_resource_statuses.begin(),
                  null_resource_statuses.end(), [](const int status) {
                    return status == static_cast<int>(cudaErrorInvalidValue);
                  });
  test.expect(resource_null_gate,
              label + " resource query rejects every null destination");
  std::cout << "DECODE_QKV_CAUSAL_CONV_RESOURCES:"
            << " registers_per_thread=" << registers_per_thread
            << " static_shared_bytes=" << static_shared_bytes
            << " local_bytes=" << local_bytes
            << " maximum_threads_per_block=" << maximum_threads_per_block
            << " active_blocks_per_sm=" << active_blocks_per_sm
            << " require_registers_le=64"
            << " require_static_shared_le=1280"
            << " require_zero_local=true"
            << " require_active_blocks_ge=4"
            << " null_query_gate="
            << (resource_null_gate ? "PASS" : "FAIL")
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!resource_ready) {
    return;
  }

  std::vector<std::uint8_t> host_qkv_weights(kQkvRows * kColumns);
  std::vector<std::uint8_t> host_z_weights(kZRows * kColumns);
  std::vector<std::uint16_t> host_a_weights(kAbRows * kColumns);
  std::vector<std::uint16_t> host_b_weights(kAbRows * kColumns);
  std::vector<std::uint16_t> host_activation(kColumns);
  std::vector<std::uint16_t> host_conv_weight(kConvWeightElements);
  std::vector<std::uint16_t> host_initial_history(kHistoryElements);
  fill_fp8_m2_code_distribution(host_qkv_weights, kQkvRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  fill_fp8_m2_code_distribution(host_z_weights, kZRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  std::reverse(host_z_weights.begin(), host_z_weights.end());
  for (std::size_t index = 0U; index < host_a_weights.size(); ++index) {
    const int a_centered = static_cast<int>((index * 17U + 5U) % 127U) - 63;
    const int b_centered = static_cast<int>((index * 29U + 11U) % 113U) - 56;
    host_a_weights[index] =
        encode_bf16(static_cast<float>(a_centered) / 128.0F);
    host_b_weights[index] =
        encode_bf16(static_cast<float>(b_centered) / 256.0F);
  }
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 13U + (column >> 3U) * 7U + 3U) %
                         127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }
  for (std::size_t channel = 0U; channel < kQkvRows; ++channel) {
    for (std::size_t tap = 0U;
         tap < q3x::runtime::kGdnConvKernelWidth; ++tap) {
      const int centered =
          static_cast<int>((channel * 19U + tap * 31U + 7U) % 97U) - 48;
      host_conv_weight[channel * q3x::runtime::kGdnConvKernelWidth + tap] =
          encode_bf16(static_cast<float>(centered) / 192.0F);
    }
    for (std::size_t slot = 0U;
         slot < q3x::runtime::kGdnConvHistoryWidth; ++slot) {
      const int centered =
          static_cast<int>((channel * 23U + slot * 37U + 11U) % 101U) - 50;
      host_initial_history
          [channel * q3x::runtime::kGdnConvHistoryWidth + slot] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> qkv_weights;
  DeviceBuffer<std::uint8_t> z_weights;
  DeviceBuffer<std::uint16_t> a_weights;
  DeviceBuffer<std::uint16_t> b_weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> conv_weight;
  std::array<DeviceBuffer<std::uint16_t>, kStateCount> baseline_storage;
  std::array<DeviceBuffer<std::uint16_t>, kStateCount> candidate_storage;
  bool ready = test.cuda_ok(qkv_weights.allocate(host_qkv_weights.size()),
                            label + " allocate QKV weights");
  ready = ready && test.cuda_ok(z_weights.allocate(host_z_weights.size()),
                                label + " allocate Z weights");
  ready = ready && test.cuda_ok(a_weights.allocate(host_a_weights.size()),
                                label + " allocate A weights");
  ready = ready && test.cuda_ok(b_weights.allocate(host_b_weights.size()),
                                label + " allocate B weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(conv_weight.allocate(host_conv_weight.size()),
                                label + " allocate conv weight");
  for (std::size_t state = 0U; state < kStateCount && ready; ++state) {
    ready = test.cuda_ok(
        baseline_storage[state].allocate(kStateElements[state] +
                                         2U * kGuardElements),
        label + " allocate baseline state " + std::to_string(state));
    ready = ready && test.cuda_ok(
                         candidate_storage[state].allocate(
                             kStateElements[state] + 2U * kGuardElements),
                         label + " allocate candidate state " +
                             std::to_string(state));
  }
  if (!ready) {
    return;
  }
  const auto state_pointer =
      [&](std::array<DeviceBuffer<std::uint16_t>, kStateCount>& storage,
          const std::size_t state) {
        return storage[state].get() + kGuardElements;
      };
  const auto upload_inputs = [&]() {
    bool upload_ready = test.cuda_ok(
        cudaMemcpyAsync(qkv_weights.get(), host_qkv_weights.data(),
                        host_qkv_weights.size(), cudaMemcpyHostToDevice,
                        stream),
        label + " upload QKV weights");
    upload_ready = test.cuda_ok(
                       cudaMemcpyAsync(z_weights.get(), host_z_weights.data(),
                                       host_z_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload Z weights") &&
                   upload_ready;
    upload_ready = test.cuda_ok(
                       cudaMemcpyAsync(a_weights.get(), host_a_weights.data(),
                                       host_a_weights.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload A weights") &&
                   upload_ready;
    upload_ready = test.cuda_ok(
                       cudaMemcpyAsync(b_weights.get(), host_b_weights.data(),
                                       host_b_weights.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload B weights") &&
                   upload_ready;
    upload_ready = test.cuda_ok(
                       cudaMemcpyAsync(activation.get(),
                                       host_activation.data(),
                                       host_activation.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload activation") &&
                   upload_ready;
    upload_ready = test.cuda_ok(
                       cudaMemcpyAsync(conv_weight.get(),
                                       host_conv_weight.data(),
                                       host_conv_weight.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload conv weight") &&
                   upload_ready;
    return test.cuda_ok(cudaStreamSynchronize(stream),
                        label + " upload synchronize") &&
           upload_ready;
  };
  const auto initialize_state =
      [&](std::array<DeviceBuffer<std::uint16_t>, kStateCount>& storage,
          const std::uint8_t output_poison,
          const std::uint8_t history_poison,
          const std::string& initialize_label) {
        bool initialize_ready = true;
        for (std::size_t state = 0U; state < kHistoryIndex; ++state) {
          initialize_ready =
              test.cuda_ok(cudaMemsetAsync(
                               storage[state].get(), output_poison,
                               (kStateElements[state] + 2U * kGuardElements) *
                                   sizeof(std::uint16_t),
                               stream),
                           initialize_label + " poison output " +
                               std::to_string(state)) &&
              initialize_ready;
        }
        initialize_ready =
            test.cuda_ok(cudaMemsetAsync(
                             storage[kHistoryIndex].get(), history_poison,
                             (kHistoryElements + 2U * kGuardElements) *
                                 sizeof(std::uint16_t),
                             stream),
                         initialize_label + " poison history guards") &&
            initialize_ready;
        initialize_ready =
            test.cuda_ok(cudaMemcpyAsync(
                             state_pointer(storage, kHistoryIndex),
                             host_initial_history.data(),
                             host_initial_history.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyHostToDevice, stream),
                         initialize_label + " initialize history") &&
            initialize_ready;
        return initialize_ready;
      };
  if (!upload_inputs() ||
      !initialize_state(baseline_storage, 0xa5U, 0xc3U,
                        label + " baseline") ||
      !initialize_state(candidate_storage, 0x5aU, 0x3cU,
                        label + " candidate") ||
      !test.cuda_ok(cudaStreamSynchronize(stream),
                    label + " initialize synchronize")) {
    return;
  }

  const auto launch_baseline =
      [&](std::array<DeviceBuffer<std::uint16_t>, kStateCount>& storage) {
        const int projection_status =
            q3x::kernels::
                launch_sm87_fp8_w8a16_gemv_qkv_z_bf16_ab_pair_cuda(
                    qkv_weights.get(), kQkvScale, z_weights.get(), kZScale,
                    a_weights.get(), b_weights.get(), activation.get(),
                    kQkvRows, kZRows, kAbRows, kColumns,
                    state_pointer(storage, 0U), state_pointer(storage, 1U),
                    state_pointer(storage, 2U), state_pointer(storage, 3U),
                    static_cast<void*>(stream));
        if (projection_status != static_cast<int>(cudaSuccess)) {
          return projection_status;
        }
        return q3x::runtime::launch_causal_conv1d_silu_update_reference_cuda(
            state_pointer(storage, 0U), conv_weight.get(),
            state_pointer(storage, kHistoryIndex),
            state_pointer(storage, 0U), {}, static_cast<void*>(stream));
      };
  const auto launch_candidate =
      [&](std::array<DeviceBuffer<std::uint16_t>, kStateCount>& storage) {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_test_cuda(
                qkv_weights.get(), kQkvScale, z_weights.get(), kZScale,
                a_weights.get(), b_weights.get(), activation.get(),
                kQkvRows, kZRows, kAbRows, kColumns,
                state_pointer(storage, 0U), state_pointer(storage, 1U),
                state_pointer(storage, 2U), state_pointer(storage, 3U),
                conv_weight.get(), state_pointer(storage, kHistoryIndex),
                static_cast<void*>(stream));
      };

  using HostState =
      std::array<std::vector<std::uint16_t>, kStateCount>;
  const auto make_host_state = [&]() {
    HostState state;
    for (std::size_t index = 0U; index < kStateCount; ++index) {
      state[index].resize(kStateElements[index] + 2U * kGuardElements);
    }
    return state;
  };
  const auto copy_state =
      [&](const std::array<DeviceBuffer<std::uint16_t>, kStateCount>& storage,
          HostState& destination, const std::string& copy_label) {
        bool copy_ready = true;
        for (std::size_t state = 0U; state < kStateCount; ++state) {
          copy_ready =
              test.cuda_ok(cudaMemcpyAsync(
                               destination[state].data(), storage[state].get(),
                               destination[state].size() *
                                   sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           copy_label + " copy state " +
                               std::to_string(state)) &&
              copy_ready;
        }
        return test.cuda_ok(cudaStreamSynchronize(stream),
                            copy_label + " synchronize") &&
               copy_ready;
      };
  const auto guards_intact = [&](const HostState& state,
                                 const std::uint8_t output_poison,
                                 const std::uint8_t history_poison) {
    bool intact = true;
    for (std::size_t output = 0U; output < kStateCount; ++output) {
      const std::uint8_t poison =
          output == kHistoryIndex ? history_poison : output_poison;
      const std::uint16_t guard = static_cast<std::uint16_t>(
          poison | (static_cast<std::uint16_t>(poison) << 8U));
      for (std::size_t index = 0U; index < kGuardElements; ++index) {
        intact = intact && state[output][index] == guard &&
                 state[output][kGuardElements + kStateElements[output] +
                               index] == guard;
      }
    }
    return intact;
  };
  const auto count_mismatches = [&](const HostState& candidate,
                                    const HostState& baseline) {
    std::array<std::size_t, kStateCount> mismatches{};
    for (std::size_t state = 0U; state < kStateCount; ++state) {
      for (std::size_t index = 0U; index < kStateElements[state]; ++index) {
        mismatches[state] +=
            candidate[state][kGuardElements + index] !=
                    baseline[state][kGuardElements + index]
                ? 1U
                : 0U;
      }
    }
    return mismatches;
  };
  const auto zero_mismatches =
      [](const std::array<std::size_t, kStateCount>& mismatches) {
        return std::all_of(mismatches.begin(), mismatches.end(),
                           [](const std::size_t count) { return count == 0U; });
      };

  HostState observed_baseline = make_host_state();
  HostState observed_candidate = make_host_state();
  bool sequential_exact_gate = true;
  for (std::size_t step = 0U; step < 4U; ++step) {
    const std::string step_label =
        label + " state step=" + std::to_string(step + 1U);
    bool step_ready = test.cuda_ok(
        static_cast<cudaError_t>(launch_baseline(baseline_storage)),
        step_label + " launch two-node baseline");
    step_ready = test.cuda_ok(
                     static_cast<cudaError_t>(
                         launch_candidate(candidate_storage)),
                     step_label + " launch one-node candidate") &&
                 step_ready;
    step_ready = copy_state(baseline_storage, observed_baseline,
                            step_label + " baseline") &&
                 step_ready;
    step_ready = copy_state(candidate_storage, observed_candidate,
                            step_label + " candidate") &&
                 step_ready;
    const auto mismatches =
        count_mismatches(observed_candidate, observed_baseline);
    const bool baseline_guards =
        guards_intact(observed_baseline, 0xa5U, 0xc3U);
    const bool candidate_guards =
        guards_intact(observed_candidate, 0x5aU, 0x3cU);
    const bool step_gate = step_ready && zero_mismatches(mismatches) &&
                           baseline_guards && candidate_guards;
    sequential_exact_gate = sequential_exact_gate && step_gate;
    test.expect(step_gate,
                step_label + " is five-state bitwise and guarded");
    std::cout << "DECODE_QKV_CAUSAL_CONV_STEP: step=" << step + 1U
              << " conv_qkv_mismatches=" << mismatches[0U] << '/'
              << kQkvRows << " z_mismatches=" << mismatches[1U] << '/'
              << kZRows << " a_mismatches=" << mismatches[2U] << '/'
              << kAbRows << " b_mismatches=" << mismatches[3U] << '/'
              << kAbRows << " history_mismatches="
              << mismatches[kHistoryIndex] << '/' << kHistoryElements
              << " baseline_guards="
              << (baseline_guards ? "intact" : "BAD")
              << " candidate_guards="
              << (candidate_guards ? "intact" : "BAD")
              << " gate=" << (step_gate ? "PASS" : "FAIL") << '\n';
  }

  std::vector<std::uint8_t> preserved_qkv(host_qkv_weights.size());
  std::vector<std::uint8_t> preserved_z(host_z_weights.size());
  std::vector<std::uint16_t> preserved_a(host_a_weights.size());
  std::vector<std::uint16_t> preserved_b(host_b_weights.size());
  std::vector<std::uint16_t> preserved_activation(host_activation.size());
  std::vector<std::uint16_t> preserved_conv(host_conv_weight.size());
  bool preserve_ready = test.cuda_ok(
      cudaMemcpyAsync(preserved_qkv.data(), qkv_weights.get(),
                      preserved_qkv.size(), cudaMemcpyDeviceToHost, stream),
      label + " preserve QKV weights");
  preserve_ready = test.cuda_ok(
                       cudaMemcpyAsync(preserved_z.data(), z_weights.get(),
                                       preserved_z.size(),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " preserve Z weights") &&
                   preserve_ready;
  preserve_ready = test.cuda_ok(
                       cudaMemcpyAsync(preserved_a.data(), a_weights.get(),
                                       preserved_a.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " preserve A weights") &&
                   preserve_ready;
  preserve_ready = test.cuda_ok(
                       cudaMemcpyAsync(preserved_b.data(), b_weights.get(),
                                       preserved_b.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " preserve B weights") &&
                   preserve_ready;
  preserve_ready = test.cuda_ok(
                       cudaMemcpyAsync(preserved_activation.data(),
                                       activation.get(),
                                       preserved_activation.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " preserve activation") &&
                   preserve_ready;
  preserve_ready = test.cuda_ok(
                       cudaMemcpyAsync(preserved_conv.data(),
                                       conv_weight.get(),
                                       preserved_conv.size() *
                                           sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " preserve conv weight") &&
                   preserve_ready;
  preserve_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " preserve synchronize") &&
                   preserve_ready;
  const bool input_preservation_gate =
      preserve_ready && preserved_qkv == host_qkv_weights &&
      preserved_z == host_z_weights && preserved_a == host_a_weights &&
      preserved_b == host_b_weights &&
      preserved_activation == host_activation &&
      preserved_conv == host_conv_weight;
  test.expect(input_preservation_gate,
              label + " leaves activation and all weights bitwise intact");
  std::cout << "DECODE_QKV_CAUSAL_CONV_INPUTS: qkv_weights="
            << (preserved_qkv == host_qkv_weights ? "preserved" : "MUTATED")
            << " z_weights="
            << (preserved_z == host_z_weights ? "preserved" : "MUTATED")
            << " a_weights="
            << (preserved_a == host_a_weights ? "preserved" : "MUTATED")
            << " b_weights="
            << (preserved_b == host_b_weights ? "preserved" : "MUTATED")
            << " activation="
            << (preserved_activation == host_activation ? "preserved"
                                                         : "MUTATED")
            << " conv_weight="
            << (preserved_conv == host_conv_weight ? "preserved"
                                                    : "MUTATED")
            << " gate=" << (input_preservation_gate ? "PASS" : "FAIL")
            << '\n';

  struct CapturedRoute {
    bool ready = false;
    cudaGraph_t graph = nullptr;
    std::size_t total_nodes = 0U;
    std::size_t root_nodes = 0U;
    std::vector<cudaKernelNodeParams> kernel_params;
  };
  const auto capture_route = [&](const auto& launch,
                                 const std::string& capture_label) {
    CapturedRoute captured;
    bool capture_ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        capture_label + " begin capture");
    int launch_status = static_cast<int>(cudaErrorUnknown);
    if (capture_ready) {
      launch_status = launch();
      capture_ready = test.cuda_ok(cudaStreamEndCapture(stream,
                                                        &captured.graph),
                                   capture_label + " end capture") &&
                      capture_ready;
    }
    if (capture_ready && captured.graph != nullptr) {
      capture_ready = test.cuda_ok(
                          cudaGraphGetNodes(captured.graph, nullptr,
                                            &captured.total_nodes),
                          capture_label + " count nodes") &&
                      capture_ready;
      capture_ready = test.cuda_ok(
                          cudaGraphGetRootNodes(captured.graph, nullptr,
                                                &captured.root_nodes),
                          capture_label + " count roots") &&
                      capture_ready;
    }
    if (capture_ready && captured.total_nodes != 0U) {
      std::vector<cudaGraphNode_t> nodes(captured.total_nodes);
      std::size_t capacity = nodes.size();
      capture_ready = test.cuda_ok(
                          cudaGraphGetNodes(captured.graph, nodes.data(),
                                            &capacity),
                          capture_label + " get nodes") &&
                      capture_ready;
      for (std::size_t index = 0U; index < capacity && capture_ready;
           ++index) {
        cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
        capture_ready = test.cuda_ok(cudaGraphNodeGetType(nodes[index], &type),
                                     capture_label + " get node type") &&
                        capture_ready;
        if (type == cudaGraphNodeTypeKernel) {
          cudaKernelNodeParams params{};
          capture_ready = test.cuda_ok(
                              cudaGraphKernelNodeGetParams(nodes[index],
                                                           &params),
                              capture_label + " get kernel params") &&
                          capture_ready;
          captured.kernel_params.push_back(params);
        }
      }
    }
    captured.ready = capture_ready &&
                     launch_status == static_cast<int>(cudaSuccess);
    return captured;
  };
  if (!initialize_state(baseline_storage, 0xa5U, 0xc3U,
                        label + " graph baseline") ||
      !initialize_state(candidate_storage, 0x5aU, 0x3cU,
                        label + " graph candidate") ||
      !test.cuda_ok(cudaStreamSynchronize(stream),
                    label + " graph initialize synchronize")) {
    return;
  }
  CapturedRoute baseline_graph = capture_route(
      [&]() { return launch_baseline(baseline_storage); },
      label + " baseline graph");
  CapturedRoute candidate_graph = capture_route(
      [&]() { return launch_candidate(candidate_storage); },
      label + " candidate graph");
  const auto exact_topology = [](const cudaKernelNodeParams& params,
                                 const unsigned int grid_x) {
    return params.gridDim.x == grid_x && params.gridDim.y == 1U &&
           params.gridDim.z == 1U && params.blockDim.x == 256U &&
           params.blockDim.y == 1U && params.blockDim.z == 1U &&
           params.sharedMemBytes == 0U;
  };
  bool baseline_has_projection = false;
  bool baseline_has_conv = false;
  for (const cudaKernelNodeParams& params : baseline_graph.kernel_params) {
    baseline_has_projection =
        baseline_has_projection || exact_topology(params, 1'536U);
    baseline_has_conv = baseline_has_conv || exact_topology(params, 40U);
  }
  const bool baseline_graph_gate =
      baseline_graph.ready && baseline_graph.total_nodes == 2U &&
      baseline_graph.root_nodes == 1U &&
      baseline_graph.kernel_params.size() == 2U &&
      baseline_has_projection && baseline_has_conv;
  const bool candidate_graph_gate =
      candidate_graph.ready && candidate_graph.total_nodes == 1U &&
      candidate_graph.root_nodes == 1U &&
      candidate_graph.kernel_params.size() == 1U &&
      exact_topology(candidate_graph.kernel_params.front(), 1'536U);
  bool graph_function_distinct =
      baseline_graph_gate && candidate_graph_gate;
  if (graph_function_distinct) {
    for (const cudaKernelNodeParams& params : baseline_graph.kernel_params) {
      graph_function_distinct =
          graph_function_distinct &&
          candidate_graph.kernel_params.front().func != params.func;
    }
  }
  cudaGraphExec_t candidate_graph_exec = nullptr;
  bool graph_replay_ready =
      candidate_graph_gate && graph_function_distinct &&
      test.cuda_ok(cudaGraphInstantiate(&candidate_graph_exec,
                                        candidate_graph.graph, nullptr,
                                        nullptr, 0U),
                   label + " instantiate candidate graph");
  if (graph_replay_ready) {
    graph_replay_ready =
        initialize_state(baseline_storage, 0xa5U, 0xc3U,
                         label + " replay baseline") &&
        initialize_state(candidate_storage, 0x5aU, 0x3cU,
                         label + " replay candidate");
  }
  for (std::size_t replay = 0U; replay < 2U && graph_replay_ready; ++replay) {
    graph_replay_ready = test.cuda_ok(
                             static_cast<cudaError_t>(
                                 launch_baseline(baseline_storage)),
                             label + " replay baseline step") &&
                         graph_replay_ready;
    graph_replay_ready = test.cuda_ok(
                             cudaGraphLaunch(candidate_graph_exec, stream),
                             label + " replay candidate step") &&
                         graph_replay_ready;
  }
  graph_replay_ready =
      copy_state(baseline_storage, observed_baseline,
                 label + " replay baseline") &&
      graph_replay_ready;
  graph_replay_ready =
      copy_state(candidate_storage, observed_candidate,
                 label + " replay candidate") &&
      graph_replay_ready;
  const auto graph_mismatches =
      count_mismatches(observed_candidate, observed_baseline);
  const bool graph_guards =
      guards_intact(observed_baseline, 0xa5U, 0xc3U) &&
      guards_intact(observed_candidate, 0x5aU, 0x3cU);
  const bool graph_replay_gate =
      graph_replay_ready && zero_mismatches(graph_mismatches) &&
      graph_guards;
  const bool graph_gate = baseline_graph_gate && candidate_graph_gate &&
                          graph_function_distinct && graph_replay_gate;
  test.expect(graph_gate,
              label + " captures ordered 2-to-1 Graphs and replays bitwise");
  std::cout << "DECODE_QKV_CAUSAL_CONV_GRAPH: baseline_nodes="
            << baseline_graph.total_nodes
            << " baseline_kernel_nodes="
            << baseline_graph.kernel_params.size()
            << " baseline_root_nodes=" << baseline_graph.root_nodes
            << " candidate_nodes=" << candidate_graph.total_nodes
            << " candidate_kernel_nodes="
            << candidate_graph.kernel_params.size()
            << " candidate_root_nodes=" << candidate_graph.root_nodes
            << " baseline_projection_grid=1536"
            << " baseline_conv_grid=40"
            << " candidate_grid=1536"
            << " distinct_function="
            << (graph_function_distinct ? "true" : "false")
            << " replay_steps=2"
            << " replay_mismatches="
            << std::accumulate(graph_mismatches.begin(),
                               graph_mismatches.end(), std::size_t{0U})
            << " guards=" << (graph_guards ? "intact" : "BAD")
            << " gate=" << (graph_gate ? "PASS" : "FAIL") << '\n';
  if (candidate_graph_exec != nullptr) {
    (void)test.cuda_ok(cudaGraphExecDestroy(candidate_graph_exec),
                       label + " destroy candidate graph executable");
  }
  if (candidate_graph.graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(candidate_graph.graph),
                       label + " destroy candidate graph");
  }
  if (baseline_graph.graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(baseline_graph.graph),
                       label + " destroy baseline graph");
  }

  struct InvalidArguments {
    const std::uint8_t* qkv_weights;
    float qkv_scale;
    const std::uint8_t* z_weights;
    float z_scale;
    const std::uint16_t* a_weights;
    const std::uint16_t* b_weights;
    const std::uint16_t* activation;
    std::size_t qkv_rows;
    std::size_t z_rows;
    std::size_t ab_rows;
    std::size_t columns;
    std::uint16_t* qkv_output;
    std::uint16_t* z_output;
    std::uint16_t* a_output;
    std::uint16_t* b_output;
    const std::uint16_t* conv_weight;
    std::uint16_t* history;
  };
  struct InvalidCase {
    std::string name;
    InvalidArguments arguments;
  };
  const InvalidArguments valid_arguments{
      qkv_weights.get(),
      kQkvScale,
      z_weights.get(),
      kZScale,
      a_weights.get(),
      b_weights.get(),
      activation.get(),
      kQkvRows,
      kZRows,
      kAbRows,
      kColumns,
      state_pointer(candidate_storage, 0U),
      state_pointer(candidate_storage, 1U),
      state_pointer(candidate_storage, 2U),
      state_pointer(candidate_storage, 3U),
      conv_weight.get(),
      state_pointer(candidate_storage, kHistoryIndex),
  };
  std::vector<InvalidCase> invalid_cases;
  const auto add_invalid = [&](std::string name, const auto& mutate) {
    InvalidArguments arguments = valid_arguments;
    mutate(arguments);
    invalid_cases.push_back(InvalidCase{std::move(name), arguments});
  };
  add_invalid("bad_qkv_rows", [](auto& args) { --args.qkv_rows; });
  add_invalid("bad_z_rows", [](auto& args) { --args.z_rows; });
  add_invalid("bad_ab_rows", [](auto& args) { --args.ab_rows; });
  add_invalid("bad_columns", [](auto& args) { --args.columns; });
  add_invalid("null_qkv_weights",
              [](auto& args) { args.qkv_weights = nullptr; });
  add_invalid("null_z_weights", [](auto& args) { args.z_weights = nullptr; });
  add_invalid("null_a_weights", [](auto& args) { args.a_weights = nullptr; });
  add_invalid("null_b_weights", [](auto& args) { args.b_weights = nullptr; });
  add_invalid("null_activation", [](auto& args) { args.activation = nullptr; });
  add_invalid("null_qkv_output", [](auto& args) { args.qkv_output = nullptr; });
  add_invalid("null_z_output", [](auto& args) { args.z_output = nullptr; });
  add_invalid("null_a_output", [](auto& args) { args.a_output = nullptr; });
  add_invalid("null_b_output", [](auto& args) { args.b_output = nullptr; });
  add_invalid("null_conv_weight",
              [](auto& args) { args.conv_weight = nullptr; });
  add_invalid("null_history", [](auto& args) { args.history = nullptr; });
  add_invalid("qkv_scale_negative",
              [](auto& args) { args.qkv_scale = -1.0F; });
  add_invalid("qkv_scale_nan", [](auto& args) {
    args.qkv_scale = std::numeric_limits<float>::quiet_NaN();
  });
  add_invalid("z_scale_negative", [](auto& args) { args.z_scale = -1.0F; });
  add_invalid("z_scale_inf", [](auto& args) {
    args.z_scale = std::numeric_limits<float>::infinity();
  });
  add_invalid("misaligned_qkv_weights", [](auto& args) {
    args.qkv_weights = reinterpret_cast<const std::uint8_t*>(
        reinterpret_cast<std::uintptr_t>(args.qkv_weights) + 1U);
  });
  add_invalid("misaligned_conv_weight", [](auto& args) {
    args.conv_weight = reinterpret_cast<const std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(args.conv_weight) + 1U);
  });
  add_invalid("misaligned_history", [](auto& args) {
    args.history = reinterpret_cast<std::uint16_t*>(
        reinterpret_cast<std::uintptr_t>(args.history) + 1U);
  });
  add_invalid("qkv_z_output_alias",
              [](auto& args) { args.z_output = args.qkv_output; });
  add_invalid("a_b_output_alias",
              [](auto& args) { args.b_output = args.a_output; });
  add_invalid("qkv_output_input_alias", [](auto& args) {
    args.qkv_output = reinterpret_cast<std::uint16_t*>(
        const_cast<std::uint8_t*>(args.qkv_weights));
  });
  add_invalid("history_qkv_output_alias",
              [](auto& args) { args.history = args.qkv_output; });
  add_invalid("history_conv_weight_alias", [](auto& args) {
    args.history = const_cast<std::uint16_t*>(args.conv_weight);
  });
  add_invalid("conv_weight_activation_alias",
              [](auto& args) { args.conv_weight = args.activation; });

  const auto launch_invalid = [&](const InvalidArguments& args) {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_test_cuda(
            args.qkv_weights, args.qkv_scale, args.z_weights, args.z_scale,
            args.a_weights, args.b_weights, args.activation, args.qkv_rows,
            args.z_rows, args.ab_rows, args.columns, args.qkv_output,
            args.z_output, args.a_output, args.b_output, args.conv_weight,
            args.history, static_cast<void*>(stream));
  };
  bool invalid_gate = true;
  std::size_t invalid_failures = 0U;
  for (const InvalidCase& invalid_case : invalid_cases) {
    const std::string invalid_label =
        label + " invalid " + invalid_case.name;
    cudaGraph_t invalid_graph = nullptr;
    bool invalid_ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        invalid_label + " begin capture");
    int status = static_cast<int>(cudaErrorUnknown);
    if (invalid_ready) {
      status = launch_invalid(invalid_case.arguments);
      invalid_ready = test.cuda_ok(cudaStreamEndCapture(stream,
                                                        &invalid_graph),
                                   invalid_label + " end capture") &&
                      invalid_ready;
    }
    std::size_t nodes = std::numeric_limits<std::size_t>::max();
    if (invalid_ready && invalid_graph != nullptr) {
      invalid_ready = test.cuda_ok(
                          cudaGraphGetNodes(invalid_graph, nullptr, &nodes),
                          invalid_label + " count nodes") &&
                      invalid_ready;
    }
    if (invalid_graph != nullptr) {
      (void)test.cuda_ok(cudaGraphDestroy(invalid_graph),
                         invalid_label + " destroy graph");
    }
    const bool case_gate =
        invalid_ready && status == static_cast<int>(cudaErrorInvalidValue) &&
        nodes == 0U;
    invalid_gate = invalid_gate && case_gate;
    invalid_failures += case_gate ? 0U : 1U;
    test.expect(case_gate,
                invalid_label + " returns invalid and captures zero nodes");
  }
  std::cout << "DECODE_QKV_CAUSAL_CONV_INVALID: cases="
            << invalid_cases.size() << " failures=" << invalid_failures
            << " aliases_checked=6"
            << " each_captured_graph_nodes=0"
            << " gate=" << (invalid_gate ? "PASS" : "FAIL") << '\n';

  const bool default_gate =
      resource_gate && resource_null_gate && sequential_exact_gate &&
      input_preservation_gate && graph_gate && invalid_gate;
  test.expect(default_gate,
              label + " clears the strict default selection contract");
  std::cout << "DECODE_QKV_CAUSAL_CONV_DEFAULT: sequential_steps=4"
            << " exact_outputs=qkv_after_conv,z,a,b"
            << " exact_history=true"
            << " inputs_preserved="
            << (input_preservation_gate ? "true" : "false")
            << " canaries="
            << (sequential_exact_gate && graph_guards ? "intact" : "BAD")
            << " graph_2_to_1=" << (graph_gate ? "PASS" : "FAIL")
            << " invalid_zero_node="
            << (invalid_gate ? "PASS" : "FAIL")
            << " resources=" << (resource_gate ? "PASS" : "FAIL")
            << " gate=" << (default_gate ? "PASS" : "FAIL") << '\n';

  if (!decode_qkv_causal_conv_epilogue_performance_enabled()) {
    std::cout
        << "SKIP: Decode QKV causal-conv epilogue formal performance; set "
           "Q3X_RUN_SM87_DECODE_QKV_CAUSAL_CONV_EPILOGUE_PERF=1 to enable\n";
    return;
  }
  if (!default_gate) {
    test.expect(false, label + " refuses performance after a default failure");
    return;
  }

  constexpr std::size_t kLayerCount = 48U;
  constexpr int kWarmupChains = 2;
  constexpr int kMeasuredIterations = 8;
  constexpr int kMeasurementRounds = 5;
  constexpr std::size_t kTimedPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  constexpr float kRequiredProjectedSavingMs = 0.20F;
  DeviceBuffer<std::uint16_t> timing_history;
  DeviceBuffer<std::uint16_t> timing_history_seed;
  std::vector<std::uint16_t> host_layer_history(kLayerCount *
                                                kHistoryElements);
  for (std::size_t layer = 0U; layer < kLayerCount; ++layer) {
    std::copy(host_initial_history.begin(), host_initial_history.end(),
              host_layer_history.begin() + layer * kHistoryElements);
  }
  bool timing_ready = test.cuda_ok(
      timing_history.allocate(host_layer_history.size()),
      label + " allocate timing history");
  timing_ready = test.cuda_ok(
                     timing_history_seed.allocate(host_layer_history.size()),
                     label + " allocate timing history seed") &&
                 timing_ready;
  if (timing_ready) {
    timing_ready = test.cuda_ok(
        cudaMemcpyAsync(timing_history_seed.get(), host_layer_history.data(),
                        host_layer_history.size() * sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        label + " upload timing history seed");
  }
  const auto reset_timing_history = [&](const std::string& reset_label) {
    return test.cuda_ok(
        cudaMemcpyAsync(timing_history.get(), timing_history_seed.get(),
                        host_layer_history.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToDevice, stream),
        reset_label + " reset same-address history");
  };
  const auto launch_baseline_chain = [&]() {
    for (std::size_t layer = 0U; layer < kLayerCount; ++layer) {
      const int projection_status =
          q3x::kernels::
              launch_sm87_fp8_w8a16_gemv_qkv_z_bf16_ab_pair_cuda(
                  qkv_weights.get(), kQkvScale, z_weights.get(), kZScale,
                  a_weights.get(), b_weights.get(), activation.get(),
                  kQkvRows, kZRows, kAbRows, kColumns,
                  state_pointer(candidate_storage, 0U),
                  state_pointer(candidate_storage, 1U),
                  state_pointer(candidate_storage, 2U),
                  state_pointer(candidate_storage, 3U),
                  static_cast<void*>(stream));
      if (projection_status != static_cast<int>(cudaSuccess)) {
        return projection_status;
      }
      const int conv_status =
          q3x::runtime::launch_causal_conv1d_silu_update_reference_cuda(
              state_pointer(candidate_storage, 0U), conv_weight.get(),
              timing_history.get() + layer * kHistoryElements,
              state_pointer(candidate_storage, 0U), {},
              static_cast<void*>(stream));
      if (conv_status != static_cast<int>(cudaSuccess)) {
        return conv_status;
      }
    }
    return static_cast<int>(cudaSuccess);
  };
  const auto launch_candidate_chain = [&]() {
    for (std::size_t layer = 0U; layer < kLayerCount; ++layer) {
      const int status = q3x::kernels::
          launch_sm87_fp8_w8a16_m1_qkv_z_bf16_ab_pair_tail_composite_causal_conv_epilogue_test_cuda(
              qkv_weights.get(), kQkvScale, z_weights.get(), kZScale,
              a_weights.get(), b_weights.get(), activation.get(),
              kQkvRows, kZRows, kAbRows, kColumns,
              state_pointer(candidate_storage, 0U),
              state_pointer(candidate_storage, 1U),
              state_pointer(candidate_storage, 2U),
              state_pointer(candidate_storage, 3U), conv_weight.get(),
              timing_history.get() + layer * kHistoryElements,
              static_cast<void*>(stream));
      if (status != static_cast<int>(cudaSuccess)) {
        return status;
      }
    }
    return static_cast<int>(cudaSuccess);
  };
  const auto measure_chain = [&](const auto& launch_chain,
                                 const std::string& measure_label) {
    EventPair events;
    bool measure_ready = events.create(test);
    measure_ready = reset_timing_history(measure_label) && measure_ready;
    measure_ready = test.cuda_ok(cudaEventRecord(events.start(), stream),
                                 measure_label + " record start") &&
                    measure_ready;
    for (int iteration = 0; iteration < kMeasuredIterations && measure_ready;
         ++iteration) {
      measure_ready =
          test.cuda_ok(static_cast<cudaError_t>(launch_chain()),
                       measure_label + " launch 48-layer chain") &&
          measure_ready;
    }
    measure_ready = test.cuda_ok(cudaEventRecord(events.stop(), stream),
                                 measure_label + " record stop") &&
                    measure_ready;
    measure_ready = test.cuda_ok(cudaEventSynchronize(events.stop()),
                                 measure_label + " synchronize") &&
                    measure_ready;
    float milliseconds = std::numeric_limits<float>::quiet_NaN();
    measure_ready = test.cuda_ok(
                        cudaEventElapsedTime(&milliseconds, events.start(),
                                             events.stop()),
                        measure_label + " elapsed time") &&
                    measure_ready;
    return measure_ready
               ? milliseconds / static_cast<float>(kMeasuredIterations)
               : std::numeric_limits<float>::quiet_NaN();
  };
  for (int warmup = 0; warmup < kWarmupChains && timing_ready; ++warmup) {
    timing_ready = reset_timing_history(label + " baseline warmup") &&
                   timing_ready;
    timing_ready = test.cuda_ok(
                       static_cast<cudaError_t>(launch_baseline_chain()),
                       label + " baseline warmup chain") &&
                   timing_ready;
    timing_ready = reset_timing_history(label + " candidate warmup") &&
                   timing_ready;
    timing_ready = test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate_chain()),
                       label + " candidate warmup chain") &&
                   timing_ready;
  }
  timing_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                              label + " timing warmup synchronize") &&
                 timing_ready;

  std::array<float, kTimedPasses> baseline_passes{};
  std::array<float, kTimedPasses> candidate_passes{};
  std::array<float, kMeasurementRounds> paired_speedups{};
  std::array<float, kMeasurementRounds> paired_deltas{};
  bool every_round_positive = timing_ready;
  for (int round = 0; round < kMeasurementRounds && timing_ready; ++round) {
    const bool baseline_first = (round & 1) == 0;
    const std::string round_label =
        label + " round=" + std::to_string(round + 1);
    float baseline1 = std::numeric_limits<float>::quiet_NaN();
    float baseline2 = std::numeric_limits<float>::quiet_NaN();
    float candidate1 = std::numeric_limits<float>::quiet_NaN();
    float candidate2 = std::numeric_limits<float>::quiet_NaN();
    if (baseline_first) {
      baseline1 = measure_chain(launch_baseline_chain, round_label + " B1");
      candidate1 =
          measure_chain(launch_candidate_chain, round_label + " C1");
      candidate2 =
          measure_chain(launch_candidate_chain, round_label + " C2");
      baseline2 = measure_chain(launch_baseline_chain, round_label + " B2");
    } else {
      candidate1 =
          measure_chain(launch_candidate_chain, round_label + " C1");
      baseline1 = measure_chain(launch_baseline_chain, round_label + " B1");
      baseline2 = measure_chain(launch_baseline_chain, round_label + " B2");
      candidate2 =
          measure_chain(launch_candidate_chain, round_label + " C2");
    }
    const std::size_t pass = 2U * static_cast<std::size_t>(round);
    baseline_passes[pass] = baseline1;
    baseline_passes[pass + 1U] = baseline2;
    candidate_passes[pass] = candidate1;
    candidate_passes[pass + 1U] = candidate2;
    const bool finite =
        std::isfinite(baseline1) && std::isfinite(baseline2) &&
        std::isfinite(candidate1) && std::isfinite(candidate2) &&
        baseline1 > 0.0F && baseline2 > 0.0F && candidate1 > 0.0F &&
        candidate2 > 0.0F;
    const float paired_baseline = 0.5F * (baseline1 + baseline2);
    const float paired_candidate = 0.5F * (candidate1 + candidate2);
    const float paired_speedup = paired_baseline / paired_candidate;
    const float paired_delta = paired_baseline - paired_candidate;
    paired_speedups[static_cast<std::size_t>(round)] = paired_speedup;
    paired_deltas[static_cast<std::size_t>(round)] = paired_delta;
    const bool round_gate = finite && paired_delta > 0.0F;
    every_round_positive = every_round_positive && round_gate;
    timing_ready = timing_ready && finite;
    std::cout << "PERF_DECODE_QKV_CAUSAL_CONV_ROUND: round=" << round + 1
              << " order="
              << (baseline_first ? "B-C-C-B" : "C-B-B-C")
              << " layers_per_chain=" << kLayerCount
              << " logical_chains_per_pass=" << kMeasuredIterations
              << " baseline_pass1_ms=" << baseline1
              << " candidate_pass1_ms=" << candidate1
              << " candidate_pass2_ms=" << candidate2
              << " baseline_pass2_ms=" << baseline2
              << " paired_speedup=" << paired_speedup
              << " paired_delta_ms_per_token=" << paired_delta
              << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
  }
  const float baseline_median =
      timing_ready ? median_fp8_kv_pair_timing(baseline_passes)
                   : std::numeric_limits<float>::quiet_NaN();
  const float candidate_median =
      timing_ready ? median_fp8_kv_pair_timing(candidate_passes)
                   : std::numeric_limits<float>::quiet_NaN();
  const float paired_median_speedup =
      timing_ready ? median_fp8_kv_pair_timing(paired_speedups)
                   : std::numeric_limits<float>::quiet_NaN();
  const float projected_48_layer_delta_ms =
      timing_ready ? median_fp8_kv_pair_timing(paired_deltas)
                   : std::numeric_limits<float>::quiet_NaN();
  const bool performance_gate =
      timing_ready && every_round_positive &&
      projected_48_layer_delta_ms >= kRequiredProjectedSavingMs;
  std::cout << "PERF_DECODE_QKV_CAUSAL_CONV_SELECTED:"
            << " baseline=production_composite_plus_reference_conv"
            << " candidate=test_only_single_node_conv_epilogue"
            << " layers_per_token=" << kLayerCount
            << " same_output_addresses=true"
            << " same_history_address=true"
            << " reset_same_initial_history_each_pass=true"
            << " baseline_median_ms_per_48_layer_chain=" << baseline_median
            << " candidate_median_ms_per_48_layer_chain="
            << candidate_median
            << " paired_median_speedup=" << paired_median_speedup
            << " projected_48_layer_delta_ms_per_token="
            << projected_48_layer_delta_ms
            << " required_each_round_positive=true"
            << " every_round_positive="
            << (every_round_positive ? "true" : "false")
            << " required_projected_delta_ms_per_token="
            << kRequiredProjectedSavingMs
            << " gate=" << (performance_gate ? "PASS" : "FAIL") << '\n';
  test.expect(performance_gate,
              label + " clears the formal 48-layer performance gate");
}

void run_optional_fp8_m2_row_pair_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!fp8_m2_row_pair_performance_enabled()) {
    std::cout << "SKIP: FP8 M2 row-pair performance segment; set "
                 "Q3X_RUN_SM87_FP8_M2_ROW_PAIR_PERF=1 to enable\n";
    return;
  }
  constexpr float kMinimumPerShapeDistributionSpeedup = 1.02F;
  constexpr float kMinimumCheckpointWeightedSpeedup = 1.05F;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t checkpoint_calls;
    const char* label;
  };
  constexpr std::array<Shape, 6U> kShapes{{
      {10'240U, 5'120U, 48U, "FP8 M2 row-pair QKV 10240x5120"},
      {5'120U, 6'144U, 64U, "FP8 M2 row-pair projection 5120x6144"},
      {6'144U, 5'120U, 48U, "FP8 M2 row-pair projection 6144x5120"},
      {12'288U, 5'120U, 16U, "FP8 M2 row-pair QKV 12288x5120"},
      {1'024U, 5'120U, 32U, "FP8 M2 row-pair small 1024x5120"},
      {5'120U, 5'120U, 0U, "FP8 M2 row-pair square 5120x5120"},
  }};
  constexpr std::array<Fp8M2CodeDistribution, 2U> kDistributions{{
      Fp8M2CodeDistribution::kCheckpointLike,
      Fp8M2CodeDistribution::kSameBankStress,
  }};
  std::array<Fp8M2RowPairMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_fp8_m2_row_pair_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }

  bool all_shape_distributions_pass = true;
  double checkpoint_weighted_baseline = 0.0;
  double checkpoint_weighted_candidate = 0.0;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    for (std::size_t distribution_index = 0U;
         distribution_index < kDistributions.size(); ++distribution_index) {
      const Fp8M2RowPairDistributionMeasurement& measurement =
          measurements[shape_index].distributions[distribution_index];
      const float speedup = measurement.baseline_milliseconds /
                            measurement.candidate_milliseconds;
      const bool finite =
          std::isfinite(measurement.baseline_milliseconds) &&
          std::isfinite(measurement.candidate_milliseconds) &&
          std::isfinite(speedup);
      const bool gate = measurement.bitwise_equal && finite &&
                        speedup >= kMinimumPerShapeDistributionSpeedup;
      all_shape_distributions_pass =
          all_shape_distributions_pass && gate;
      test.expect(
          gate,
          std::string(kShapes[shape_index].label) + " " +
              fp8_m2_code_distribution_name(
                  kDistributions[distribution_index]) +
              " clears the M2 row-pair performance gate");
      std::cout << "PERF_FP8_M2_ROW_PAIR_VALIDATION: "
                << kShapes[shape_index].label << " distribution="
                << fp8_m2_code_distribution_name(
                       kDistributions[distribution_index])
                << " preserved_cap2048_single_row_ms="
                << measurement.baseline_milliseconds
                << " direct_row_pair_ms="
                << measurement.candidate_milliseconds
                << " speedup=" << speedup
                << " required_speedup="
                << kMinimumPerShapeDistributionSpeedup << " bitwise="
                << (measurement.bitwise_equal ? "true" : "false")
                << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
    }
    const Fp8M2RowPairDistributionMeasurement& checkpoint =
        measurements[shape_index].distributions[0U];
    checkpoint_weighted_baseline +=
        static_cast<double>(kShapes[shape_index].checkpoint_calls) *
        checkpoint.baseline_milliseconds;
    checkpoint_weighted_candidate +=
        static_cast<double>(kShapes[shape_index].checkpoint_calls) *
        checkpoint.candidate_milliseconds;
  }
  const double checkpoint_weighted_speedup =
      checkpoint_weighted_baseline / checkpoint_weighted_candidate;
  const bool aggregate_gate =
      all_shape_distributions_pass &&
      std::isfinite(checkpoint_weighted_speedup) &&
      checkpoint_weighted_speedup >= kMinimumCheckpointWeightedSpeedup;
  std::cout << "PERF_FP8_M2_ROW_PAIR_AGGREGATE: "
            << "checkpoint_weighted_preserved_cap2048_single_row_ms="
            << checkpoint_weighted_baseline
            << " checkpoint_weighted_direct_row_pair_ms="
            << checkpoint_weighted_candidate
            << " speedup=" << checkpoint_weighted_speedup
            << " required_speedup=" << kMinimumCheckpointWeightedSpeedup
            << " profile_calls=48:64:48:16:32:0 all_shape_distributions="
            << (all_shape_distributions_pass ? "PASS" : "FAIL")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "FP8 M2 row-pair clears every production gate");
}

constexpr std::array<std::size_t, 6U> kFp8M2RowQuadGridCaps{{
    256U,
    512U,
    768U,
    1'024U,
    1'536U,
    2'048U,
}};

constexpr std::array<Fp8M2CodeDistribution, 2U>
    kFp8M2RowQuadDistributions{{
        Fp8M2CodeDistribution::kCheckpointLike,
        Fp8M2CodeDistribution::kSameBankStress,
    }};

struct Fp8M2RowQuadComparison {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
};

struct Fp8M2RowQuadDistributionMeasurement {
  std::array<Fp8M2RowQuadComparison, kFp8M2RowQuadGridCaps.size()>
      caps{};
};

struct Fp8M2RowQuadMeasurement {
  std::array<Fp8M2RowQuadDistributionMeasurement,
             kFp8M2RowQuadDistributions.size()>
      distributions{};
};

struct Fp8M2RowQuadShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  std::size_t selected_quad_cap;
  const char* label;
};

void run_fp8_m2_row_quad_tail_correctness(TestContext& test,
                                           cudaStream_t stream) {
  constexpr std::size_t kTokens = 2U;
  constexpr std::size_t kBytePositions = 4U;
  constexpr std::size_t kColumns = 1'024U;
  constexpr std::array<std::size_t, 3U> kRows{{1'025U, 1'026U, 1'027U}};
  constexpr std::size_t kBaselineGridCap = 2'048U;
  constexpr float kWeightScale = 1.0F / 128.0F;
  const std::size_t max_rows = kRows.back();
  const std::string label =
      "FP8 M2 row-quad tails rows1025/1026/1027 full E4M3FN byte "
      "positions";

  // Each of the 256 raw E4M3FN encodings appears once in each byte of the
  // first packed-x4 load. A zero background isolates that contribution even
  // for the NaN encodings, while finite nonzero tail rows catch dropped work.
  std::vector<std::uint8_t> host_weights(max_rows * kColumns, 0U);
  std::array<std::array<bool, 256U>, kBytePositions> code_coverage{};
  for (std::size_t code = 0U; code < 256U; ++code) {
    for (std::size_t position = 0U; position < kBytePositions; ++position) {
      const std::size_t row = code * kBytePositions + position;
      host_weights[row * kColumns + position] =
          static_cast<std::uint8_t>(code);
      code_coverage[position][code] = true;
    }
  }
  constexpr std::array<std::uint8_t, 3U> kTailCodes{{
      0x38U,
      0xb8U,
      0x40U,
  }};
  for (std::size_t tail = 0U; tail < kTailCodes.size(); ++tail) {
    const std::size_t row = 1'024U + tail;
    for (std::size_t column = 0U; column < kColumns; ++column) {
      host_weights[row * kColumns + column] = kTailCodes[tail];
    }
  }
  for (std::size_t position = 0U; position < kBytePositions; ++position) {
    test.expect(
        std::all_of(code_coverage[position].begin(),
                    code_coverage[position].end(),
                    [](const bool covered) { return covered; }),
        label + " covers all 256 raw codes at byte position " +
            std::to_string(position));
  }

  std::vector<std::uint16_t> host_activations(kTokens * kColumns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const int centered = static_cast<int>(
                               (column * 13U + token * 29U + 5U) % 127U) -
                           63;
      host_activations[token * kColumns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
    for (std::size_t position = 0U; position < kBytePositions; ++position) {
      const float distinct =
          static_cast<float>((token + 1U) * (position + 2U)) / 8.0F;
      host_activations[token * kColumns + position] = encode_bf16(distinct);
    }
  }
  test.expect(host_activations[0U] != host_activations[kColumns],
              label + " uses distinct token activations");

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokens * max_rows),
                                label + " allocate row-pair output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokens * max_rows),
                                label + " allocate row-quad output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize exhaustive weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize two token activations");
  if (!ready) {
    return;
  }

  std::vector<std::uint16_t> baseline(kTokens * max_rows);
  std::vector<std::uint16_t> candidate(kTokens * max_rows);
  for (const std::size_t rows : kRows) {
    const std::string row_label = label + " rows=" + std::to_string(rows);
    ready = test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_fp8_w8a16_small_m2_row_pair_grid_cap_test_cuda(
                weights.get(), kWeightScale, activations.get(), rows,
                kColumns, baseline_output.get(), kBaselineGridCap,
                static_cast<void*>(stream))),
        row_label + " launch production row-pair cap2048 baseline");
    for (const std::size_t cap : kFp8M2RowQuadGridCaps) {
      if (!ready) {
        return;
      }
      const std::string cap_label =
          row_label + " row_quad_cap=" + std::to_string(cap);
      ready = test.cuda_ok(
          cudaMemsetAsync(candidate_output.get(), 0xa5,
                          kTokens * max_rows * sizeof(std::uint16_t), stream),
          cap_label + " poison row-quad output");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(q3x::kernels::
                               launch_sm87_fp8_w8a16_small_m2_row_quad_grid_cap_test_cuda(
                                   weights.get(), kWeightScale,
                                   activations.get(), rows, kColumns,
                                   candidate_output.get(), cap,
                                   static_cast<void*>(stream))),
                           cap_label + " launch tail-safe row-quad");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               baseline.data(), baseline_output.get(),
                               kTokens * rows * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-pair output");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               kTokens * rows * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-quad output");
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " synchronize");
      if (!ready) {
        return;
      }
      std::size_t mismatches = 0U;
      for (std::size_t index = 0U; index < kTokens * rows; ++index) {
        mismatches += baseline[index] != candidate[index] ? 1U : 0U;
      }
      std::cout << "FP8_M2_ROW_QUAD_TAIL_DIFF: rows=" << rows
                << " columns=" << kColumns << " candidate_cap=" << cap
                << " mismatches=" << mismatches << '/' << kTokens * rows
                << '\n';
      test.expect(mismatches == 0U,
                  cap_label + " matches every row-pair BF16 bit");
    }
  }
}

[[nodiscard]] Fp8M2RowQuadMeasurement benchmark_fp8_m2_row_quad_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 2U;
  constexpr std::size_t kBaselineGridCap = 2'048U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;

  std::vector<std::uint8_t> host_weights(rows * columns);
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered = static_cast<int>(
                               (column * 17U + token * 29U + 5U) % 127U) -
                           63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }
  test.expect(host_activations[0U] != host_activations[columns],
              label + " uses distinct token activations");

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokens * rows),
                                label + " allocate row-pair output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokens * rows),
                                label + " allocate row-quad output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize two token activations");
  Fp8M2RowQuadMeasurement measurement;
  if (!ready) {
    return measurement;
  }

  std::vector<std::uint16_t> baseline(kTokens * rows);
  std::vector<std::uint16_t> candidate(kTokens * rows);
  for (std::size_t distribution_index = 0U;
       distribution_index < kFp8M2RowQuadDistributions.size();
       ++distribution_index) {
    const Fp8M2CodeDistribution distribution =
        kFp8M2RowQuadDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + fp8_m2_code_distribution_name(distribution);
    fill_fp8_m2_code_distribution(host_weights, rows, columns, distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(weights.get(), host_weights.data(),
                        host_weights.size(), cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize weights");
    if (!ready) {
      return measurement;
    }

    for (std::size_t cap_index = 0U;
         cap_index < kFp8M2RowQuadGridCaps.size(); ++cap_index) {
      const std::size_t candidate_cap =
          kFp8M2RowQuadGridCaps[cap_index];
      const std::string cap_label =
          distribution_label + " row_quad_cap=" +
          std::to_string(candidate_cap);
      const auto launch_baseline = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_small_m2_row_pair_grid_cap_test_cuda(
                weights.get(), kWeightScale, activations.get(), rows,
                columns, baseline_output.get(), kBaselineGridCap,
                static_cast<void*>(stream));
      };
      const auto launch_candidate = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_small_m2_row_quad_grid_cap_test_cuda(
                weights.get(), kWeightScale, activations.get(), rows,
                columns, candidate_output.get(), candidate_cap,
                static_cast<void*>(stream));
      };

      ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_baseline()),
          cap_label + " correctness production row-pair cap2048 baseline");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           cap_label + " correctness row-quad candidate");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               baseline.data(), baseline_output.get(),
                               baseline.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-pair output");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               candidate.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-quad output");
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " correctness synchronize");
      if (!ready) {
        return measurement;
      }

      std::size_t mismatches = 0U;
      for (std::size_t index = 0U; index < baseline.size(); ++index) {
        mismatches += baseline[index] != candidate[index] ? 1U : 0U;
      }
      Fp8M2RowQuadComparison& comparison =
          measurement.distributions[distribution_index].caps[cap_index];
      comparison.bitwise_equal = mismatches == 0U;
      std::cout << "FP8_M2_ROW_QUAD_DIFF: " << label << " distribution="
                << fp8_m2_code_distribution_name(distribution)
                << " baseline_pair_cap=" << kBaselineGridCap
                << " candidate_quad_cap=" << candidate_cap
                << " mismatches=" << mismatches << '/' << baseline.size()
                << '\n';
      test.expect(comparison.bitwise_equal,
                  cap_label + " matches every row-pair BF16 bit");

      for (int iteration = 0; iteration < kWarmupIterations && ready;
           ++iteration) {
        ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                             cap_label + " row-pair warmup");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_candidate()),
                             cap_label + " row-quad warmup");
      }
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " warmup synchronize");
      if (!ready) {
        return measurement;
      }

      double baseline_total = 0.0;
      double candidate_total = 0.0;
      bool all_finite = true;
      for (int round = 0; round < kMeasurementRounds; ++round) {
        const std::string round_label =
            cap_label + " round=" + std::to_string(round + 1);
        const float baseline_first = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 1");
        const float candidate_first = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 1");
        const float candidate_second = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 2");
        const float baseline_second = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 2");
        const bool round_finite =
            std::isfinite(baseline_first) &&
            std::isfinite(candidate_first) &&
            std::isfinite(candidate_second) &&
            std::isfinite(baseline_second);
        all_finite = all_finite && round_finite;
        if (round_finite) {
          baseline_total += baseline_first + baseline_second;
          candidate_total += candidate_first + candidate_second;
        }
        std::cout << "PERF_FP8_M2_ROW_QUAD_ROUND: " << label
                  << " distribution="
                  << fp8_m2_code_distribution_name(distribution)
                  << " baseline_pair_cap=" << kBaselineGridCap
                  << " candidate_quad_cap=" << candidate_cap
                  << " measured_iterations=" << kMeasuredIterations
                  << " round=" << round + 1
                  << " baseline_pass1_ms=" << baseline_first
                  << " candidate_pass1_ms=" << candidate_first
                  << " candidate_pass2_ms=" << candidate_second
                  << " baseline_pass2_ms=" << baseline_second << '\n';
      }
      constexpr double kTimedPasses =
          2.0 * static_cast<double>(kMeasurementRounds);
      comparison.baseline_milliseconds =
          all_finite
              ? static_cast<float>(baseline_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      comparison.candidate_milliseconds =
          all_finite
              ? static_cast<float>(candidate_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      const float speedup = comparison.baseline_milliseconds /
                            comparison.candidate_milliseconds;
      std::cout << "PERF_FP8_M2_ROW_QUAD_CELL: " << label
                << " distribution="
                << fp8_m2_code_distribution_name(distribution)
                << " baseline_pair_cap=" << kBaselineGridCap
                << " candidate_quad_cap=" << candidate_cap
                << " baseline_ms=" << comparison.baseline_milliseconds
                << " candidate_ms=" << comparison.candidate_milliseconds
                << " speedup=" << speedup << " bitwise="
                << (comparison.bitwise_equal ? "true" : "false") << '\n';
    }
  }
  return measurement;
}

void run_optional_fp8_m2_row_quad_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!fp8_m2_row_quad_performance_enabled()) {
    std::cout << "SKIP: FP8 M2 row-quad cap/correctness performance "
                 "segment; set Q3X_RUN_SM87_FP8_M2_ROW_QUAD_PERF=1 to "
                 "enable\n";
    return;
  }
  constexpr float kMinimumPerCellSpeedup = 1.02F;
  constexpr double kMinimumCheckpointWeightedSpeedup = 1.05;
  constexpr std::array<Fp8M2RowQuadShape, 5U> kShapes{{
      {10'240U, 5'120U, 48U, 1'536U,
       "FP8 M2 row-quad QKV 10240x5120"},
      {5'120U, 6'144U, 64U, 768U,
       "FP8 M2 row-quad projection 5120x6144"},
      {6'144U, 5'120U, 48U, 1'024U,
       "FP8 M2 row-quad projection 6144x5120"},
      {12'288U, 5'120U, 16U, 2'048U,
       "FP8 M2 row-quad QKV 12288x5120"},
      {1'024U, 5'120U, 32U, 0U,
       "FP8 M2 preserved row-pair small 1024x5120"},
  }};

  for (const Fp8M2RowQuadShape& shape : kShapes) {
    test.expect(
        q3x::kernels::sm87_fp8_m2_row_quad_maximum_blocks_test(
            shape.rows, shape.columns) == shape.selected_quad_cap,
        std::string(shape.label) +
            " performance cap matches production dispatch");
  }

  run_fp8_m2_row_quad_tail_correctness(test, stream);
  std::array<Fp8M2RowQuadMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_fp8_m2_row_quad_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }

  bool all_candidate_bits_equal = true;
  for (std::size_t cap_index = 0U;
       cap_index < kFp8M2RowQuadGridCaps.size(); ++cap_index) {
    double weighted_baseline = 0.0;
    double weighted_candidate = 0.0;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      for (std::size_t distribution_index = 0U;
           distribution_index < kFp8M2RowQuadDistributions.size();
           ++distribution_index) {
        all_candidate_bits_equal =
            all_candidate_bits_equal &&
            measurements[shape_index]
                .distributions[distribution_index]
                .caps[cap_index]
                .bitwise_equal;
      }
      const Fp8M2RowQuadComparison& checkpoint =
          measurements[shape_index].distributions[0U].caps[cap_index];
      weighted_baseline +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          checkpoint.baseline_milliseconds;
      weighted_candidate +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          checkpoint.candidate_milliseconds;
    }
    const double weighted_speedup =
        weighted_baseline / weighted_candidate;
    std::cout << "PERF_FP8_M2_ROW_QUAD_CAP: candidate_cap="
              << kFp8M2RowQuadGridCaps[cap_index]
              << " checkpoint_weighted_baseline_ms=" << weighted_baseline
              << " checkpoint_weighted_candidate_ms=" << weighted_candidate
              << " speedup=" << weighted_speedup << '\n';
  }

  bool all_selected_cells_pass = true;
  double selected_weighted_baseline = 0.0;
  double selected_weighted_candidate = 0.0;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    const Fp8M2RowQuadShape& shape = kShapes[shape_index];
    if (shape.selected_quad_cap == 0U) {
      // This small shape is intentionally left on the production row-pair.
      // Use one of its interleaved baseline timings in both totals so it is
      // represented in the real call mix without claiming row-quad uplift.
      const Fp8M2RowQuadComparison& checkpoint =
          measurements[shape_index].distributions[0U].caps[0U];
      const bool finite = std::isfinite(checkpoint.baseline_milliseconds) &&
                          checkpoint.baseline_milliseconds > 0.0F;
      all_selected_cells_pass = all_selected_cells_pass && finite;
      const double weighted =
          static_cast<double>(shape.profile_calls) *
          checkpoint.baseline_milliseconds;
      selected_weighted_baseline += weighted;
      selected_weighted_candidate += weighted;
      std::cout << "PERF_FP8_M2_ROW_QUAD_PRESERVED: " << shape.label
                << " selected=row_pair_cap2048 baseline_ms="
                << checkpoint.baseline_milliseconds
                << " profile_calls=" << shape.profile_calls
                << " gate=" << (finite ? "PASS" : "FAIL") << '\n';
      test.expect(finite,
                  std::string(shape.label) +
                      " has a finite preserved row-pair timing");
      continue;
    }
    const auto selected_cap_iterator =
        std::find(kFp8M2RowQuadGridCaps.begin(),
                  kFp8M2RowQuadGridCaps.end(), shape.selected_quad_cap);
    const bool selected_cap_measured =
        selected_cap_iterator != kFp8M2RowQuadGridCaps.end();
    test.expect(selected_cap_measured,
                std::string(shape.label) +
                    " selected row-quad cap is present in the sweep");
    if (!selected_cap_measured) {
      all_selected_cells_pass = false;
      continue;
    }
    const std::size_t selected_cap_index = static_cast<std::size_t>(
        selected_cap_iterator - kFp8M2RowQuadGridCaps.begin());
    for (std::size_t distribution_index = 0U;
         distribution_index < kFp8M2RowQuadDistributions.size();
         ++distribution_index) {
      const Fp8M2RowQuadComparison& selected =
          measurements[shape_index]
              .distributions[distribution_index]
              .caps[selected_cap_index];
      const float speedup = selected.baseline_milliseconds /
                            selected.candidate_milliseconds;
      const bool finite = std::isfinite(selected.baseline_milliseconds) &&
                          std::isfinite(selected.candidate_milliseconds) &&
                          std::isfinite(speedup) &&
                          selected.baseline_milliseconds > 0.0F &&
                          selected.candidate_milliseconds > 0.0F;
      const bool cell_gate = selected.bitwise_equal && finite &&
                             speedup >= kMinimumPerCellSpeedup;
      all_selected_cells_pass = all_selected_cells_pass && cell_gate;
      std::cout << "PERF_FP8_M2_ROW_QUAD_VALIDATION: "
                << shape.label << " distribution="
                << fp8_m2_code_distribution_name(
                       kFp8M2RowQuadDistributions[distribution_index])
                << " selected_cap=" << shape.selected_quad_cap
                << " baseline_ms=" << selected.baseline_milliseconds
                << " candidate_ms=" << selected.candidate_milliseconds
                << " speedup=" << speedup
                << " required_speedup=" << kMinimumPerCellSpeedup
                << " bitwise="
                << (selected.bitwise_equal ? "true" : "false")
                << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
      test.expect(cell_gate,
                  std::string(shape.label) + " " +
                      fp8_m2_code_distribution_name(
                          kFp8M2RowQuadDistributions[distribution_index]) +
                      " selected row-quad cap clears the cell gate");
    }
    const Fp8M2RowQuadComparison& checkpoint =
        measurements[shape_index]
            .distributions[0U]
            .caps[selected_cap_index];
    selected_weighted_baseline +=
        static_cast<double>(shape.profile_calls) *
        checkpoint.baseline_milliseconds;
    selected_weighted_candidate +=
        static_cast<double>(shape.profile_calls) *
        checkpoint.candidate_milliseconds;
  }

  const double selected_weighted_speedup =
      selected_weighted_baseline / selected_weighted_candidate;
  const bool aggregate_gate =
      all_candidate_bits_equal && all_selected_cells_pass &&
      std::isfinite(selected_weighted_speedup) &&
      selected_weighted_baseline > 0.0 &&
      selected_weighted_candidate > 0.0 &&
      selected_weighted_speedup >= kMinimumCheckpointWeightedSpeedup;
  std::cout << "PERF_FP8_M2_ROW_QUAD_SELECTED: baseline_pair_cap=2048"
            << " selected_caps=1536:768:1024:2048:pair"
            << " checkpoint_weighted_baseline_ms="
            << selected_weighted_baseline
            << " checkpoint_weighted_candidate_ms="
            << selected_weighted_candidate
            << " checkpoint_weighted_speedup=" << selected_weighted_speedup
            << " required_weighted_speedup="
            << kMinimumCheckpointWeightedSpeedup
            << " profile_calls=48:64:48:16:32 all_candidate_bitwise="
            << (all_candidate_bits_equal ? "true" : "false")
            << " all_selected_cells="
            << (all_selected_cells_pass ? "PASS" : "FAIL")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "FP8 M2 shape-selected row-quad mapping clears every gate");
}

constexpr std::array<std::size_t, 15U> kFp8M1RowQuadGridCaps{{
    48U,
    64U,
    80U,
    96U,
    128U,
    192U,
    256U,
    512U,
    768U,
    1'024U,
    1'280U,
    1'536U,
    2'048U,
    2'560U,
    3'072U,
}};

constexpr std::array<Fp8M2CodeDistribution, 2U>
    kFp8M1RowQuadDistributions{{
        Fp8M2CodeDistribution::kCheckpointLike,
        Fp8M2CodeDistribution::kSameBankStress,
    }};

struct Fp8M1RowQuadComparison {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
};

struct Fp8M1RowQuadDistributionMeasurement {
  std::array<Fp8M1RowQuadComparison, kFp8M1RowQuadGridCaps.size()> caps{};
};

struct Fp8M1RowQuadMeasurement {
  std::array<Fp8M1RowQuadDistributionMeasurement,
             kFp8M1RowQuadDistributions.size()>
      distributions{};
};

struct Fp8M1RowQuadShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  std::size_t selected_quad_cap;
  const char* label;
};

void run_fp8_m1_row_quad_tail_correctness(TestContext& test,
                                           cudaStream_t stream) {
  constexpr std::size_t kBytePositions = 4U;
  constexpr std::size_t kColumns = 1'024U;
  constexpr std::array<std::size_t, 3U> kRows{{
      4'097U,
      4'098U,
      4'099U,
  }};
  constexpr std::size_t kBaselineGridCap = 2'048U;
  constexpr float kWeightScale = 1.0F / 128.0F;
  const std::size_t max_rows = kRows.back();
  const std::string label =
      "FP8 M1 row-quad tails rows4097/4098/4099 full E4M3FN byte "
      "positions";

  // Put every raw E4M3FN code in each byte of a packed-x4 load. The zero
  // background isolates that code, including both NaN encodings, while the
  // finite nonzero rows after 4096 make dropped tail work observable.
  std::vector<std::uint8_t> host_weights(max_rows * kColumns, 0U);
  std::array<std::array<bool, 256U>, kBytePositions> code_coverage{};
  for (std::size_t code = 0U; code < 256U; ++code) {
    for (std::size_t position = 0U; position < kBytePositions; ++position) {
      const std::size_t row = code * kBytePositions + position;
      host_weights[row * kColumns + position] =
          static_cast<std::uint8_t>(code);
      code_coverage[position][code] = true;
    }
  }
  constexpr std::array<std::uint8_t, 3U> kTailCodes{{
      0x38U,
      0xb8U,
      0x40U,
  }};
  for (std::size_t tail = 0U; tail < kTailCodes.size(); ++tail) {
    const std::size_t row = 4'096U + tail;
    for (std::size_t column = 0U; column < kColumns; ++column) {
      host_weights[row * kColumns + column] = kTailCodes[tail];
    }
  }
  for (std::size_t position = 0U; position < kBytePositions; ++position) {
    test.expect(
        std::all_of(code_coverage[position].begin(),
                    code_coverage[position].end(),
                    [](const bool covered) { return covered; }),
        label + " covers all 256 raw codes at byte position " +
            std::to_string(position));
  }

  std::vector<std::uint16_t> host_activation(kColumns);
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 13U + (column >> 3U) * 7U + 5U) % 127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }
  for (std::size_t position = 0U; position < kBytePositions; ++position) {
    host_activation[position] =
        encode_bf16(static_cast<float>(position + 2U) / 8.0F);
  }
  test.expect(host_activation[0U] != host_activation[1U] &&
                  host_activation[1U] != host_activation[2U] &&
                  host_activation[2U] != host_activation[3U],
              label + " uses distinct activation values by byte position");

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(max_rows),
                                label + " allocate row-pair output");
  ready = ready && test.cuda_ok(candidate_output.allocate(max_rows),
                                label + " allocate row-quad output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize exhaustive weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  if (!ready) {
    return;
  }

  std::vector<std::uint16_t> baseline(max_rows);
  std::vector<std::uint16_t> candidate(max_rows);
  for (const std::size_t rows : kRows) {
    const std::string row_label = label + " rows=" + std::to_string(rows);
    ready = test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_fp8_w8a16_m1_row_pair_grid_cap_test_cuda(
                weights.get(), kWeightScale, activation.get(), rows,
                kColumns, baseline_output.get(), kBaselineGridCap,
                static_cast<void*>(stream))),
        row_label + " launch row-pair cap2048 baseline");
    for (const std::size_t cap : kFp8M1RowQuadGridCaps) {
      if (!ready) {
        return;
      }
      const std::string cap_label =
          row_label + " row_quad_cap=" + std::to_string(cap);
      ready = test.cuda_ok(
          cudaMemsetAsync(candidate_output.get(), 0xa5,
                          max_rows * sizeof(std::uint16_t), stream),
          cap_label + " poison row-quad output");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(q3x::kernels::
                               launch_sm87_fp8_w8a16_m1_row_quad_grid_cap_test_cuda(
                                   weights.get(), kWeightScale,
                                   activation.get(), rows, kColumns,
                                   candidate_output.get(), cap,
                                   static_cast<void*>(stream))),
                           cap_label + " launch tail-safe row-quad");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               baseline.data(), baseline_output.get(),
                               rows * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-pair output");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               rows * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-quad output");
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " synchronize");
      if (!ready) {
        return;
      }
      std::size_t mismatches = 0U;
      for (std::size_t row = 0U; row < rows; ++row) {
        mismatches += baseline[row] != candidate[row] ? 1U : 0U;
      }
      std::cout << "FP8_M1_ROW_QUAD_TAIL_DIFF: rows=" << rows
                << " columns=" << kColumns << " baseline_pair_cap="
                << kBaselineGridCap << " candidate_quad_cap=" << cap
                << " mismatches=" << mismatches << '/' << rows << '\n';
      test.expect(mismatches == 0U,
                  cap_label + " matches every row-pair BF16 bit");
    }
  }
}

[[nodiscard]] Fp8M1RowQuadMeasurement benchmark_fp8_m1_row_quad_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kBaselineGridCap = 2'048U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;

  std::vector<std::uint8_t> host_weights(rows * columns);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered = static_cast<int>((column * 17U + 5U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(rows),
                                label + " allocate row-pair output");
  ready = ready && test.cuda_ok(candidate_output.allocate(rows),
                                label + " allocate row-quad output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  Fp8M1RowQuadMeasurement measurement;
  if (!ready) {
    return measurement;
  }

  std::vector<std::uint16_t> baseline(rows);
  std::vector<std::uint16_t> candidate(rows);
  for (std::size_t distribution_index = 0U;
       distribution_index < kFp8M1RowQuadDistributions.size();
       ++distribution_index) {
    const Fp8M2CodeDistribution distribution =
        kFp8M1RowQuadDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + fp8_m2_code_distribution_name(distribution);
    fill_fp8_m2_code_distribution(host_weights, rows, columns, distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(weights.get(), host_weights.data(),
                        host_weights.size(), cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize weights");
    if (!ready) {
      return measurement;
    }

    for (std::size_t cap_index = 0U;
         cap_index < kFp8M1RowQuadGridCaps.size(); ++cap_index) {
      const std::size_t candidate_cap = kFp8M1RowQuadGridCaps[cap_index];
      const std::string cap_label =
          distribution_label + " row_quad_cap=" +
          std::to_string(candidate_cap);
      const auto launch_baseline = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_row_pair_grid_cap_test_cuda(
                weights.get(), kWeightScale, activation.get(), rows,
                columns, baseline_output.get(), kBaselineGridCap,
                static_cast<void*>(stream));
      };
      const auto launch_candidate = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_m1_row_quad_grid_cap_test_cuda(
                weights.get(), kWeightScale, activation.get(), rows,
                columns, candidate_output.get(), candidate_cap,
                static_cast<void*>(stream));
      };

      ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_baseline()),
          cap_label + " correctness row-pair cap2048 baseline");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           cap_label + " correctness row-quad candidate");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               baseline.data(), baseline_output.get(),
                               baseline.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-pair output");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               candidate.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-quad output");
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " correctness synchronize");
      if (!ready) {
        return measurement;
      }

      std::size_t mismatches = 0U;
      for (std::size_t row = 0U; row < rows; ++row) {
        mismatches += baseline[row] != candidate[row] ? 1U : 0U;
      }
      Fp8M1RowQuadComparison& comparison =
          measurement.distributions[distribution_index].caps[cap_index];
      comparison.bitwise_equal = mismatches == 0U;
      std::cout << "FP8_M1_ROW_QUAD_DIFF: " << label << " distribution="
                << fp8_m2_code_distribution_name(distribution)
                << " baseline_pair_cap=" << kBaselineGridCap
                << " candidate_quad_cap=" << candidate_cap
                << " mismatches=" << mismatches << '/' << rows << '\n';
      test.expect(comparison.bitwise_equal,
                  cap_label + " matches every row-pair BF16 bit");

      for (int iteration = 0; iteration < kWarmupIterations && ready;
           ++iteration) {
        ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                             cap_label + " row-pair warmup");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_candidate()),
                             cap_label + " row-quad warmup");
      }
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " warmup synchronize");
      if (!ready) {
        return measurement;
      }

      double baseline_total = 0.0;
      double candidate_total = 0.0;
      bool all_finite = true;
      for (int round = 0; round < kMeasurementRounds; ++round) {
        const std::string round_label =
            cap_label + " round=" + std::to_string(round + 1);
        // A/B/B/A keeps both launchers equally exposed to clock drift and
        // thermal movement within every measurement round.
        const float baseline_first = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 1");
        const float candidate_first = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 1");
        const float candidate_second = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 2");
        const float baseline_second = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 2");
        const bool round_finite =
            std::isfinite(baseline_first) &&
            std::isfinite(candidate_first) &&
            std::isfinite(candidate_second) &&
            std::isfinite(baseline_second);
        all_finite = all_finite && round_finite;
        if (round_finite) {
          baseline_total += baseline_first + baseline_second;
          candidate_total += candidate_first + candidate_second;
        }
        std::cout << "PERF_FP8_M1_ROW_QUAD_ROUND: " << label
                  << " distribution="
                  << fp8_m2_code_distribution_name(distribution)
                  << " baseline_pair_cap=" << kBaselineGridCap
                  << " candidate_quad_cap=" << candidate_cap
                  << " measured_iterations=" << kMeasuredIterations
                  << " round=" << round + 1
                  << " baseline_pass1_ms=" << baseline_first
                  << " candidate_pass1_ms=" << candidate_first
                  << " candidate_pass2_ms=" << candidate_second
                  << " baseline_pass2_ms=" << baseline_second << '\n';
      }
      constexpr double kTimedPasses =
          2.0 * static_cast<double>(kMeasurementRounds);
      comparison.baseline_milliseconds =
          all_finite
              ? static_cast<float>(baseline_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      comparison.candidate_milliseconds =
          all_finite
              ? static_cast<float>(candidate_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      const float speedup = comparison.baseline_milliseconds /
                            comparison.candidate_milliseconds;
      std::cout << "PERF_FP8_M1_ROW_QUAD_CELL: " << label
                << " distribution="
                << fp8_m2_code_distribution_name(distribution)
                << " baseline_pair_cap=" << kBaselineGridCap
                << " candidate_quad_cap=" << candidate_cap
                << " baseline_ms=" << comparison.baseline_milliseconds
                << " candidate_ms=" << comparison.candidate_milliseconds
                << " speedup=" << speedup << " bitwise="
                << (comparison.bitwise_equal ? "true" : "false") << '\n';
    }
  }
  return measurement;
}

void run_optional_fp8_m1_row_quad_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!fp8_m1_row_quad_performance_enabled()) {
    std::cout << "SKIP: FP8 M1 row-quad cap/correctness performance "
                 "segment; set Q3X_RUN_SM87_FP8_M1_ROW_QUAD_PERF=1 to "
                 "enable\n";
    return;
  }
  constexpr float kMinimumCheckpointShapeSpeedup = 1.005F;
  constexpr float kMinimumStressShapeSpeedup = 0.995F;
  constexpr double kMinimumCheckpointWeightedSpeedup = 1.018;
  constexpr double kMinimumStressWeightedSpeedup = 0.998;
  constexpr std::array<Fp8M1RowQuadShape, 5U> kShapes{{
      {10'240U, 5'120U, 48U, 1'536U,
       "FP8 M1 row-quad QKV 10240x5120"},
      {5'120U, 6'144U, 64U, 1'280U,
       "FP8 M1 row-quad projection 5120x6144"},
      {6'144U, 5'120U, 48U, 768U,
       "FP8 M1 row-quad projection 6144x5120"},
      {12'288U, 5'120U, 16U, 2'048U,
       "FP8 M1 row-quad QKV 12288x5120"},
      {1'024U, 5'120U, 32U, 0U,
       "FP8 M1 row-quad small projection 1024x5120"},
  }};

  for (const Fp8M1RowQuadShape& shape : kShapes) {
    test.expect(
        q3x::kernels::sm87_fp8_m1_row_quad_maximum_blocks_test(
            shape.rows, shape.columns) == shape.selected_quad_cap,
        std::string(shape.label) +
            " selected cap matches production dispatch");
  }

  run_fp8_m1_row_quad_tail_correctness(test, stream);
  std::array<Fp8M1RowQuadMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_fp8_m1_row_quad_shape(
        test, stream, kShapes[shape_index].rows,
        kShapes[shape_index].columns, kShapes[shape_index].label);
  }

  bool all_candidate_bits_equal = true;
  for (std::size_t cap_index = 0U;
       cap_index < kFp8M1RowQuadGridCaps.size(); ++cap_index) {
    for (std::size_t distribution_index = 0U;
         distribution_index < kFp8M1RowQuadDistributions.size();
         ++distribution_index) {
      double weighted_baseline = 0.0;
      double weighted_candidate = 0.0;
      bool cap_distribution_bits_equal = true;
      for (std::size_t shape_index = 0U; shape_index < kShapes.size();
           ++shape_index) {
        const Fp8M1RowQuadComparison& comparison =
            measurements[shape_index]
                .distributions[distribution_index]
                .caps[cap_index];
        cap_distribution_bits_equal =
            cap_distribution_bits_equal && comparison.bitwise_equal;
        weighted_baseline +=
            static_cast<double>(kShapes[shape_index].profile_calls) *
            comparison.baseline_milliseconds;
        weighted_candidate +=
            static_cast<double>(kShapes[shape_index].profile_calls) *
            comparison.candidate_milliseconds;
      }
      all_candidate_bits_equal =
          all_candidate_bits_equal && cap_distribution_bits_equal;
      const double weighted_speedup =
          weighted_baseline / weighted_candidate;
      std::cout << "PERF_FP8_M1_ROW_QUAD_WEIGHTED: distribution="
                << fp8_m2_code_distribution_name(
                       kFp8M1RowQuadDistributions[distribution_index])
                << " baseline_pair_cap=2048 candidate_quad_cap="
                << kFp8M1RowQuadGridCaps[cap_index]
                << " weighted_baseline_ms=" << weighted_baseline
                << " weighted_candidate_ms=" << weighted_candidate
                << " speedup=" << weighted_speedup
                << " profile_calls=48:64:48:16:32 bitwise="
                << (cap_distribution_bits_equal ? "true" : "false")
                << '\n';
    }
  }

  // Retain the complete sweep as a diagnostic around the frozen mapping.
  std::cout << "PERF_FP8_M1_ROW_QUAD_SWEEP: baseline_pair_cap=2048"
            << " candidate_caps=48:64:80:96:128:192:256:512:768:1024:"
               "1280:1536:2048:2560:3072"
            << " distributions=checkpoint_like:same_bank_stress"
            << " profile_calls=48:64:48:16:32 all_candidate_bitwise="
            << (all_candidate_bits_equal ? "true" : "false")
            << " gate=" << (all_candidate_bits_equal ? "PASS" : "FAIL")
            << '\n';
  test.expect(all_candidate_bits_equal,
              "FP8 M1 row-quad sweep matches every row-pair BF16 bit");

  std::array<double, kFp8M1RowQuadDistributions.size()>
      selected_weighted_baseline{};
  std::array<double, kFp8M1RowQuadDistributions.size()>
      selected_weighted_candidate{};
  bool all_selected_bitwise_finite = true;
  bool all_selected_cells_pass = true;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    const Fp8M1RowQuadShape& shape = kShapes[shape_index];
    if (shape.selected_quad_cap == 0U) {
      // This small shape remains on the production row-pair path. Include its
      // measured baseline in both sides of every weighted total.
      for (std::size_t distribution_index = 0U;
           distribution_index < kFp8M1RowQuadDistributions.size();
           ++distribution_index) {
        const Fp8M1RowQuadComparison& preserved =
            measurements[shape_index]
                .distributions[distribution_index]
                .caps[0U];
        const bool finite =
            std::isfinite(preserved.baseline_milliseconds) &&
            preserved.baseline_milliseconds > 0.0F;
        all_selected_bitwise_finite =
            all_selected_bitwise_finite && finite;
        all_selected_cells_pass = all_selected_cells_pass && finite;
        const double weighted =
            static_cast<double>(shape.profile_calls) *
            preserved.baseline_milliseconds;
        selected_weighted_baseline[distribution_index] += weighted;
        selected_weighted_candidate[distribution_index] += weighted;
        std::cout << "PERF_FP8_M1_ROW_QUAD_SELECTED_CELL: "
                  << shape.label << " distribution="
                  << fp8_m2_code_distribution_name(
                         kFp8M1RowQuadDistributions[distribution_index])
                  << " selected=row_pair_cap2048 baseline_ms="
                  << preserved.baseline_milliseconds
                  << " candidate_ms=" << preserved.baseline_milliseconds
                  << " speedup=1 bitwise=true finite="
                  << (finite ? "true" : "false")
                  << " profile_calls=" << shape.profile_calls
                  << " gate=" << (finite ? "PASS" : "FAIL") << '\n';
        test.expect(finite,
                    std::string(shape.label) + " " +
                        fp8_m2_code_distribution_name(
                            kFp8M1RowQuadDistributions[distribution_index]) +
                        " has a finite preserved row-pair timing");
      }
      continue;
    }

    const auto selected_cap_iterator =
        std::find(kFp8M1RowQuadGridCaps.begin(),
                  kFp8M1RowQuadGridCaps.end(), shape.selected_quad_cap);
    const bool selected_cap_measured =
        selected_cap_iterator != kFp8M1RowQuadGridCaps.end();
    test.expect(selected_cap_measured,
                std::string(shape.label) +
                    " selected row-quad cap is present in the sweep");
    if (!selected_cap_measured) {
      all_selected_bitwise_finite = false;
      all_selected_cells_pass = false;
      continue;
    }
    const std::size_t selected_cap_index = static_cast<std::size_t>(
        selected_cap_iterator - kFp8M1RowQuadGridCaps.begin());
    for (std::size_t distribution_index = 0U;
         distribution_index < kFp8M1RowQuadDistributions.size();
         ++distribution_index) {
      const Fp8M1RowQuadComparison& selected =
          measurements[shape_index]
              .distributions[distribution_index]
              .caps[selected_cap_index];
      const float speedup = selected.baseline_milliseconds /
                            selected.candidate_milliseconds;
      const bool finite =
          std::isfinite(selected.baseline_milliseconds) &&
          std::isfinite(selected.candidate_milliseconds) &&
          std::isfinite(speedup) &&
          selected.baseline_milliseconds > 0.0F &&
          selected.candidate_milliseconds > 0.0F;
      const float required_speedup =
          distribution_index == 0U ? kMinimumCheckpointShapeSpeedup
                                   : kMinimumStressShapeSpeedup;
      const bool bitwise_finite = selected.bitwise_equal && finite;
      const bool cell_gate = bitwise_finite && speedup >= required_speedup;
      all_selected_bitwise_finite =
          all_selected_bitwise_finite && bitwise_finite;
      all_selected_cells_pass = all_selected_cells_pass && cell_gate;
      selected_weighted_baseline[distribution_index] +=
          static_cast<double>(shape.profile_calls) *
          selected.baseline_milliseconds;
      selected_weighted_candidate[distribution_index] +=
          static_cast<double>(shape.profile_calls) *
          selected.candidate_milliseconds;
      std::cout << "PERF_FP8_M1_ROW_QUAD_SELECTED_CELL: " << shape.label
                << " distribution="
                << fp8_m2_code_distribution_name(
                       kFp8M1RowQuadDistributions[distribution_index])
                << " selected_quad_cap=" << shape.selected_quad_cap
                << " baseline_ms=" << selected.baseline_milliseconds
                << " candidate_ms=" << selected.candidate_milliseconds
                << " speedup=" << speedup
                << " required_speedup=" << required_speedup
                << " bitwise="
                << (selected.bitwise_equal ? "true" : "false")
                << " finite=" << (finite ? "true" : "false")
                << " profile_calls=" << shape.profile_calls
                << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
      test.expect(cell_gate,
                  std::string(shape.label) + " " +
                      fp8_m2_code_distribution_name(
                          kFp8M1RowQuadDistributions[distribution_index]) +
                      " selected row-quad cap clears its cell gate");
    }
  }

  bool all_weighted_gates_pass = true;
  std::array<double, kFp8M1RowQuadDistributions.size()>
      selected_weighted_speedups{};
  for (std::size_t distribution_index = 0U;
       distribution_index < kFp8M1RowQuadDistributions.size();
       ++distribution_index) {
    const double speedup =
        selected_weighted_baseline[distribution_index] /
        selected_weighted_candidate[distribution_index];
    selected_weighted_speedups[distribution_index] = speedup;
    const double required_speedup =
        distribution_index == 0U ? kMinimumCheckpointWeightedSpeedup
                                 : kMinimumStressWeightedSpeedup;
    const bool weighted_gate =
        std::isfinite(speedup) &&
        selected_weighted_baseline[distribution_index] > 0.0 &&
        selected_weighted_candidate[distribution_index] > 0.0 &&
        speedup >= required_speedup;
    all_weighted_gates_pass =
        all_weighted_gates_pass && weighted_gate;
    std::cout << "PERF_FP8_M1_ROW_QUAD_SELECTED_WEIGHTED: distribution="
              << fp8_m2_code_distribution_name(
                     kFp8M1RowQuadDistributions[distribution_index])
              << " selected_caps=1536:1280:768:2048:pair"
              << " weighted_baseline_ms="
              << selected_weighted_baseline[distribution_index]
              << " weighted_candidate_ms="
              << selected_weighted_candidate[distribution_index]
              << " speedup=" << speedup
              << " required_speedup=" << required_speedup
              << " profile_calls=48:64:48:16:32"
              << " gate=" << (weighted_gate ? "PASS" : "FAIL") << '\n';
    test.expect(weighted_gate,
                std::string("FP8 M1 selected row-quad ") +
                    fp8_m2_code_distribution_name(
                        kFp8M1RowQuadDistributions[distribution_index]) +
                    " weighted gate passes");
  }

  const bool selected_mapping_gate =
      all_selected_bitwise_finite && all_selected_cells_pass &&
      all_weighted_gates_pass;
  std::cout << "PERF_FP8_M1_ROW_QUAD_SELECTED: baseline_pair_cap=2048"
            << " selected_caps=1536:1280:768:2048:pair"
            << " checkpoint_weighted_speedup="
            << selected_weighted_speedups[0U]
            << " stress_weighted_speedup="
            << selected_weighted_speedups[1U]
            << " profile_calls=48:64:48:16:32"
            << " all_selected_bitwise_finite="
            << (all_selected_bitwise_finite ? "PASS" : "FAIL")
            << " all_selected_cells="
            << (all_selected_cells_pass ? "PASS" : "FAIL")
            << " all_weighted_gates="
            << (all_weighted_gates_pass ? "PASS" : "FAIL")
            << " gate=" << (selected_mapping_gate ? "PASS" : "FAIL")
            << '\n';
  test.expect(selected_mapping_gate,
              "FP8 M1 shape-selected row-quad mapping clears every gate");
}

struct Fp8M1SwizzledCodebookDistributionMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
  bool output_finite = false;
  bool timing_finite = false;
};

struct Fp8M1SwizzledCodebookMeasurement {
  std::array<Fp8M1SwizzledCodebookDistributionMeasurement,
             kFp8M1RowQuadDistributions.size()>
      distributions{};
};

[[nodiscard]] Fp8M1SwizzledCodebookMeasurement
benchmark_fp8_m1_swizzled_codebook_shape(
    TestContext& test, cudaStream_t stream, const Fp8M1RowQuadShape& shape) {
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<float, 2U> kMinimumCellSpeedups{{
      1.50F,
      2.00F,
  }};

  std::vector<std::uint8_t> host_weights(shape.rows * shape.columns);
  std::vector<std::uint16_t> host_activation(shape.columns);
  for (std::size_t column = 0U; column < shape.columns; ++column) {
    const int centered = static_cast<int>((column * 17U + 5U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            std::string(shape.label) + " allocate weights");
  ready = ready && test.cuda_ok(
                       activation.allocate(host_activation.size()),
                       std::string(shape.label) + " allocate activation");
  ready = ready && test.cuda_ok(
                       baseline_output.allocate(shape.rows),
                       std::string(shape.label) + " allocate baseline output");
  ready = ready && test.cuda_ok(
                       candidate_output.allocate(shape.rows),
                       std::string(shape.label) + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       std::string(shape.label) + " initialize activation");

  Fp8M1SwizzledCodebookMeasurement measurement;
  if (!ready) {
    return measurement;
  }

  std::vector<std::uint16_t> baseline(shape.rows);
  std::vector<std::uint16_t> candidate(shape.rows);
  for (std::size_t distribution_index = 0U;
       distribution_index < kFp8M1RowQuadDistributions.size();
       ++distribution_index) {
    const Fp8M2CodeDistribution distribution =
        kFp8M1RowQuadDistributions[distribution_index];
    const std::string label =
        std::string(shape.label) + " " +
        fp8_m2_code_distribution_name(distribution) + " cap=" +
        std::to_string(shape.selected_quad_cap);
    fill_fp8_m2_code_distribution(host_weights, shape.rows, shape.columns,
                                  distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(weights.get(), host_weights.data(),
                        host_weights.size(), cudaMemcpyHostToDevice, stream),
        label + " initialize weights");
    if (!ready) {
      return measurement;
    }

    const auto launch_baseline = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_m1_row_quad_grid_cap_test_cuda(
              weights.get(), kWeightScale, activation.get(), shape.rows,
              shape.columns, baseline_output.get(), shape.selected_quad_cap,
              static_cast<void*>(stream));
    };
    const auto launch_candidate = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_m1_row_quad_swizzled_codebook_grid_cap_test_cuda(
              weights.get(), kWeightScale, activation.get(), shape.rows,
              shape.columns, candidate_output.get(), shape.selected_quad_cap,
              static_cast<void*>(stream));
    };

    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " launch current row-quad baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " launch swizzled-codebook candidate");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy baseline output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy candidate output");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " correctness synchronize");
    if (!ready) {
      return measurement;
    }

    std::size_t mismatches = 0U;
    bool output_finite = true;
    for (std::size_t row = 0U; row < shape.rows; ++row) {
      mismatches += baseline[row] != candidate[row] ? 1U : 0U;
      output_finite = output_finite &&
                      std::isfinite(decode_bf16(baseline[row])) &&
                      std::isfinite(decode_bf16(candidate[row]));
    }
    auto& distribution_measurement =
        measurement.distributions[distribution_index];
    distribution_measurement.bitwise_equal = mismatches == 0U;
    distribution_measurement.output_finite = output_finite;
    std::cout << "FP8_M1_SWIZZLED_CODEBOOK_DIFF: " << shape.label
              << " distribution="
              << fp8_m2_code_distribution_name(distribution)
              << " baseline_quad_cap=" << shape.selected_quad_cap
              << " candidate_swizzled_cap=" << shape.selected_quad_cap
              << " mismatches=" << mismatches << '/' << shape.rows
              << " output_finite=" << (output_finite ? "true" : "false")
              << '\n';
    test.expect(distribution_measurement.bitwise_equal,
                label + " swizzled codebook matches every baseline BF16 bit");
    test.expect(output_finite, label + " outputs remain finite");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " warmup synchronize");
    if (!ready) {
      return measurement;
    }

    double baseline_total = 0.0;
    double candidate_total = 0.0;
    bool timing_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 2");
      const bool round_finite =
          std::isfinite(baseline_first) && baseline_first > 0.0F &&
          std::isfinite(candidate_first) && candidate_first > 0.0F &&
          std::isfinite(candidate_second) && candidate_second > 0.0F &&
          std::isfinite(baseline_second) && baseline_second > 0.0F;
      timing_finite = timing_finite && round_finite;
      if (round_finite) {
        baseline_total += baseline_first + baseline_second;
        candidate_total += candidate_first + candidate_second;
      }
      std::cout << "PERF_FP8_M1_SWIZZLED_CODEBOOK_ROUND: " << shape.label
                << " distribution="
                << fp8_m2_code_distribution_name(distribution)
                << " cap=" << shape.selected_quad_cap
                << " measured_iterations=" << kMeasuredIterations
                << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }

    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    distribution_measurement.baseline_milliseconds =
        timing_finite
            ? static_cast<float>(baseline_total / kTimedPasses)
            : std::numeric_limits<float>::quiet_NaN();
    distribution_measurement.candidate_milliseconds =
        timing_finite
            ? static_cast<float>(candidate_total / kTimedPasses)
            : std::numeric_limits<float>::quiet_NaN();
    distribution_measurement.timing_finite = timing_finite;
    const float speedup = distribution_measurement.baseline_milliseconds /
                          distribution_measurement.candidate_milliseconds;
    const float required_speedup =
        kMinimumCellSpeedups[distribution_index];
    const bool cell_gate = distribution_measurement.bitwise_equal &&
                           distribution_measurement.output_finite &&
                           distribution_measurement.timing_finite &&
                           std::isfinite(speedup) &&
                           speedup >= required_speedup;
    std::cout << "PERF_FP8_M1_SWIZZLED_CODEBOOK_CELL: " << shape.label
              << " distribution="
              << fp8_m2_code_distribution_name(distribution)
              << " baseline_quad_cap=" << shape.selected_quad_cap
              << " candidate_swizzled_cap=" << shape.selected_quad_cap
              << " baseline_ms="
              << distribution_measurement.baseline_milliseconds
              << " candidate_ms="
              << distribution_measurement.candidate_milliseconds
              << " speedup=" << speedup
              << " required_speedup=" << required_speedup
              << " bitwise="
              << (distribution_measurement.bitwise_equal ? "true" : "false")
              << " output_finite="
              << (distribution_measurement.output_finite ? "true" : "false")
              << " timing_finite="
              << (distribution_measurement.timing_finite ? "true" : "false")
              << " hard_gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
    test.expect(cell_gate,
                label + " clears bitwise/finite and speedup hard gate");
  }
  return measurement;
}

void run_optional_fp8_m1_swizzled_codebook_performance(
    TestContext& test, cudaStream_t stream) {
  if (!fp8_m1_swizzled_codebook_performance_enabled()) {
    std::cout
        << "SKIP: FP8 M1 swizzled-codebook performance segment; set "
           "Q3X_RUN_SM87_FP8_M1_SWIZZLED_CODEBOOK_PERF=1 to enable\n";
    return;
  }

  constexpr std::array<Fp8M1RowQuadShape, 4U> kShapes{{
      {10'240U, 5'120U, 48U, 1'536U,
       "FP8 M1 swizzled QKV 10240x5120"},
      {5'120U, 6'144U, 64U, 1'280U,
       "FP8 M1 swizzled projection 5120x6144"},
      {6'144U, 5'120U, 48U, 768U,
       "FP8 M1 swizzled projection 6144x5120"},
      {12'288U, 5'120U, 16U, 2'048U,
       "FP8 M1 swizzled QKV 12288x5120"},
  }};
  constexpr std::array<double, 2U> kMinimumWeightedSpeedups{{
      1.60,
      2.20,
  }};

  std::array<Fp8M1SwizzledCodebookMeasurement, kShapes.size()>
      measurements{};
  std::array<double, kFp8M1RowQuadDistributions.size()>
      weighted_speedups{};
  bool all_cells_pass = true;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    const Fp8M1RowQuadShape& shape = kShapes[shape_index];
    const bool frozen_cap =
        q3x::kernels::sm87_fp8_m1_row_quad_maximum_blocks_test(
            shape.rows, shape.columns) == shape.selected_quad_cap;
    test.expect(frozen_cap,
                std::string(shape.label) +
                    " uses the frozen production row-quad cap");
    all_cells_pass = all_cells_pass && frozen_cap;
    measurements[shape_index] =
        benchmark_fp8_m1_swizzled_codebook_shape(test, stream, shape);
  }

  for (std::size_t distribution_index = 0U;
       distribution_index < kFp8M1RowQuadDistributions.size();
       ++distribution_index) {
    double weighted_baseline = 0.0;
    double weighted_candidate = 0.0;
    bool distribution_gate = true;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      const auto& cell =
          measurements[shape_index].distributions[distribution_index];
      const double cell_speedup =
          static_cast<double>(cell.baseline_milliseconds) /
          static_cast<double>(cell.candidate_milliseconds);
      const double required_cell_speedup =
          distribution_index == 0U ? 1.50 : 2.00;
      const bool cell_gate = cell.bitwise_equal && cell.output_finite &&
                             cell.timing_finite &&
                             std::isfinite(cell_speedup) &&
                             cell_speedup >= required_cell_speedup;
      distribution_gate = distribution_gate && cell_gate;
      weighted_baseline +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          cell.baseline_milliseconds;
      weighted_candidate +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          cell.candidate_milliseconds;
    }
    const double weighted_speedup = weighted_baseline / weighted_candidate;
    weighted_speedups[distribution_index] = weighted_speedup;
    const double required_speedup =
        kMinimumWeightedSpeedups[distribution_index];
    const bool weighted_finite = std::isfinite(weighted_speedup) &&
                                 weighted_baseline > 0.0 &&
                                 weighted_candidate > 0.0;
    distribution_gate = distribution_gate && weighted_finite &&
                        weighted_speedup >= required_speedup;
    all_cells_pass = all_cells_pass && distribution_gate;
    std::cout << "PERF_FP8_M1_SWIZZLED_CODEBOOK_WEIGHTED: distribution="
              << fp8_m2_code_distribution_name(
                     kFp8M1RowQuadDistributions[distribution_index])
              << " frozen_caps=1536:1280:768:2048"
              << " weighted_baseline_ms=" << weighted_baseline
              << " weighted_candidate_ms=" << weighted_candidate
              << " speedup=" << weighted_speedup
              << " required_speedup=" << required_speedup
              << " profile_calls=48:64:48:16"
              << " hard_gate="
              << (distribution_gate ? "PASS" : "FAIL") << '\n';
    test.expect(distribution_gate,
                std::string("FP8 M1 swizzled ") +
                    fp8_m2_code_distribution_name(
                        kFp8M1RowQuadDistributions[distribution_index]) +
                    " weighted bitwise/finite and speedup gate passes");
  }

  std::cout << "PERF_FP8_M1_SWIZZLED_CODEBOOK_SELECTED:"
            << " baseline=current_row_quad candidate=swizzled_codebook"
            << " frozen_caps=1536:1280:768:2048"
            << " distributions=checkpoint_like:same_bank_stress"
            << " profile_calls=48:64:48:16"
            << " checkpoint_weighted_speedup=" << weighted_speedups[0U]
            << " stress_weighted_speedup=" << weighted_speedups[1U]
            << " hard_gate=" << (all_cells_pass ? "PASS" : "FAIL")
            << '\n';
  test.expect(all_cells_pass,
              "FP8 M1 swizzled codebook clears every correctness and "
              "performance gate");
}

struct Fp8M1Aosoa4PreswizzledResources {
  int registers_per_thread = 0;
  std::size_t static_shared_bytes = 0U;
  std::size_t local_bytes = 0U;
  int maximum_threads_per_block = 0;
  int active_blocks_per_sm = 0;
};

template <std::size_t Count>
[[nodiscard]] float median_fp8_m1_aosoa4_timing(
    std::array<float, Count> values) {
  static_assert(Count != 0U);
  std::sort(values.begin(), values.end());
  if constexpr ((Count & 1U) != 0U) {
    return values[Count / 2U];
  }
  return 0.5F * (values[Count / 2U - 1U] + values[Count / 2U]);
}

[[nodiscard]] bool build_fp8_m1_aosoa4_preswizzled_sidecar(
    const std::vector<std::uint8_t>& weights, const std::size_t rows,
    const std::size_t columns, const std::size_t guard_bytes,
    const std::uint8_t guard_value,
    std::vector<std::uint8_t>& guarded_sidecar) {
  if ((rows & 3U) != 0U || (columns & 3U) != 0U ||
      weights.size() != rows * columns) {
    return false;
  }
  const std::size_t row_quads = rows / 4U;
  const std::size_t packed_columns = columns / 4U;
  guarded_sidecar.assign(guard_bytes + rows * columns + guard_bytes,
                         guard_value);
  bool byte_semantics_match = true;
  for (std::size_t row_quad = 0U; row_quad < row_quads; ++row_quad) {
    for (std::size_t packed_column = 0U;
         packed_column < packed_columns; ++packed_column) {
      std::array<std::uint32_t, 4U> components{};
      for (std::size_t row_in_quad = 0U; row_in_quad < 4U;
           ++row_in_quad) {
        const std::size_t source_offset =
            (4U * row_quad + row_in_quad) * columns + 4U * packed_column;
        std::uint32_t word = 0U;
        std::memcpy(&word, weights.data() + source_offset, sizeof(word));
        const std::uint32_t preswizzled =
            word ^ ((word >> 5U) & 0x0707'0707U);
        components[row_in_quad] = preswizzled;
        for (std::size_t byte = 0U; byte < 4U; ++byte) {
          const std::uint8_t code = weights[source_offset + byte];
          const std::uint8_t slot =
              static_cast<std::uint8_t>(code ^ (code >> 5U));
          const std::uint8_t packed_slot = static_cast<std::uint8_t>(
              (preswizzled >> (8U * byte)) & 0xffU);
          byte_semantics_match =
          byte_semantics_match && packed_slot == slot;
        }
      }
      const uint4 packed_rows{components[0U], components[1U],
                              components[2U], components[3U]};
      const std::size_t destination_offset =
          guard_bytes +
          (row_quad * packed_columns + packed_column) * sizeof(uint4);
      std::memcpy(guarded_sidecar.data() + destination_offset, &packed_rows,
                  sizeof(packed_rows));
    }
  }
  return byte_semantics_match;
}

enum class Fp8M1OProjAosoa4ScreenMode {
  kCacheStreaming,
  kResidentGrid64,
};

void run_fp8_m1_output_projection_aosoa4_screen(
    TestContext& test, cudaStream_t stream,
    const Fp8M1OProjAosoa4ScreenMode mode) {
  const bool resident_grid64 =
      mode == Fp8M1OProjAosoa4ScreenMode::kResidentGrid64;
  const bool enabled = resident_grid64
                           ? decode_fp8_o_proj_resident_grid64_performance_enabled()
                           : decode_fp8_o_proj_cs_performance_enabled();
  if (!enabled) {
    if (resident_grid64) {
      std::cout
          << "SKIP: Decode FP8 O-proj AoSoA4 resident-grid64 screen; set "
             "Q3X_RUN_SM87_DECODE_FP8_O_PROJ_RESIDENT_GRID64_PERF=1 to "
             "enable\n";
    } else {
      std::cout
          << "SKIP: Decode FP8 O-proj AoSoA4 sidecar cache-policy screen; "
             "set Q3X_RUN_SM87_DECODE_FP8_O_PROJ_CS_PERF=1 to enable\n";
    }
    return;
  }
  constexpr std::size_t kRows = 5'120U;
  constexpr std::size_t kColumns = 6'144U;
  constexpr std::size_t kWeightElements = kRows * kColumns;
  constexpr std::size_t kInputGuardBytes = 64U;
  constexpr std::size_t kActivationGuardElements = 16U;
  constexpr std::size_t kOutputGuardElements = 32U;
  constexpr std::uint8_t kSidecarGuard = 0xd3U;
  constexpr std::uint16_t kActivationGuard = 0x7fc1U;
  constexpr std::uint16_t kOutputCanary = 0x5aa5U;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::uint64_t kActualPayloadOffset = 3'569'011'232ULL;
  constexpr std::string_view kActualPayloadSha256 =
      "e49a9f770a84cfcf7c2eb60f041aa7f1af8b84f5ab6323d3b8a9151588ff2bb9";
  constexpr std::string_view kActualSidecarSha256 =
      "20f6875f163aefa869d7c96c436fdc63f90171793a88a0f1b3fefca55531782b";
  const std::string label = resident_grid64
                                ? "FP8 M1 output projection AoSoA4 resident-grid64 screen"
                                : "FP8 M1 output projection AoSoA4 sidecar cache-policy screen";
  const char* const log_prefix = resident_grid64
                                     ? "FP8_M1_O_PROJ_RESIDENT_GRID64"
                                     : "FP8_M1_O_PROJ_CS";
  const char* const perf_prefix = resident_grid64
                                      ? "PERF_FP8_M1_O_PROJ_RESIDENT_GRID64"
                                      : "PERF_FP8_M1_O_PROJ_CS";
  const auto query_candidate_resources =
      [&](int* const registers_per_thread,
          std::size_t* const static_shared_bytes,
          std::size_t* const local_bytes,
          int* const maximum_threads_per_block,
          int* const active_blocks_per_sm) noexcept {
        return resident_grid64
                   ? q3x::kernels::
                         query_sm87_fp8_w8a16_m1_output_projection_aosoa4_resident_grid64_resources_test_cuda(
                             registers_per_thread, static_shared_bytes,
                             local_bytes, maximum_threads_per_block,
                             active_blocks_per_sm)
                   : q3x::kernels::
                         query_sm87_fp8_w8a16_m1_output_projection_aosoa4_cs_resources_test_cuda(
                             registers_per_thread, static_shared_bytes,
                             local_bytes, maximum_threads_per_block,
                             active_blocks_per_sm);
      };
  const auto launch_candidate_route =
      [&](const std::uint8_t* const sidecar_weights,
          const float weight_scale,
          const std::uint16_t* const activation_values,
          const std::size_t rows, const std::size_t columns,
          std::uint16_t* const output,
          void* const cuda_stream) noexcept {
        return resident_grid64
                   ? q3x::kernels::
                         launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_resident_grid64_test_cuda(
                             sidecar_weights, weight_scale, activation_values,
                             rows, columns, output, cuda_stream)
                   : q3x::kernels::
                         launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_cs_test_cuda(
                             sidecar_weights, weight_scale, activation_values,
                             rows, columns, output, cuda_stream);
      };

  Fp8M1Aosoa4PreswizzledResources public_resources{};
  Fp8M1Aosoa4PreswizzledResources candidate_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_row_quad_aosoa4_preswizzled_resources_test_cuda(
              &public_resources.registers_per_thread,
              &public_resources.static_shared_bytes,
              &public_resources.local_bytes,
              &public_resources.maximum_threads_per_block,
              &public_resources.active_blocks_per_sm)),
      label + " query current public resources");
  ready = ready && test.cuda_ok(
      static_cast<cudaError_t>(query_candidate_resources(
              &candidate_resources.registers_per_thread,
              &candidate_resources.static_shared_bytes,
              &candidate_resources.local_bytes,
              &candidate_resources.maximum_threads_per_block,
              &candidate_resources.active_blocks_per_sm)),
      label + " query test-only candidate resources");
  const auto resources_clear_gate = [](const auto& resources) {
    return resources.registers_per_thread > 0 &&
           resources.registers_per_thread <= 64 &&
           resources.static_shared_bytes == 1'152U &&
           resources.local_bytes == 0U &&
           resources.maximum_threads_per_block == 256 &&
           resources.active_blocks_per_sm >= 4;
  };
  int device = -1;
  int multiprocessor_count = 0;
  if (resident_grid64) {
    ready = ready &&
            test.cuda_ok(cudaGetDevice(&device),
                         label + " query current CUDA device");
    ready = ready && test.cuda_ok(
                         cudaDeviceGetAttribute(&multiprocessor_count,
                                                cudaDevAttrMultiProcessorCount,
                                                device),
                         label + " query SM count");
  }
  const auto resources_match_resident_grid64 = [](const auto& resources) {
    return resources.registers_per_thread == 64 &&
           resources.static_shared_bytes == 1'152U &&
           resources.local_bytes == 0U &&
           resources.maximum_threads_per_block == 256 &&
           resources.active_blocks_per_sm == 4;
  };
  const bool public_resource_gate =
      ready && (resident_grid64
                    ? resources_match_resident_grid64(public_resources)
                    : resources_clear_gate(public_resources));
  const bool candidate_resource_gate =
      ready && (resident_grid64
                    ? resources_match_resident_grid64(candidate_resources)
                    : resources_clear_gate(candidate_resources));
  const bool public_resource_null_gate =
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_row_quad_aosoa4_preswizzled_resources_test_cuda(
              nullptr, &public_resources.static_shared_bytes,
              &public_resources.local_bytes,
              &public_resources.maximum_threads_per_block,
              &public_resources.active_blocks_per_sm)) ==
      cudaErrorInvalidValue;
  const bool candidate_resource_null_gate =
      static_cast<cudaError_t>(query_candidate_resources(
              nullptr, &candidate_resources.static_shared_bytes,
              &candidate_resources.local_bytes,
              &candidate_resources.maximum_threads_per_block,
              &candidate_resources.active_blocks_per_sm)) ==
      cudaErrorInvalidValue;
  const int resident_capacity =
      multiprocessor_count * candidate_resources.active_blocks_per_sm;
  const bool resident_capacity_gate =
      !resident_grid64 ||
      (multiprocessor_count == 16 && resident_capacity == 64);
  const bool resource_gate =
      public_resource_gate && candidate_resource_gate &&
      public_resource_null_gate && candidate_resource_null_gate &&
      resident_capacity_gate;
  test.expect(resource_gate,
              label + " preserves the public occupancy/spill contract");
  std::cout << log_prefix << "_RESOURCES:"
            << " public_registers="
            << public_resources.registers_per_thread
            << " candidate_registers="
            << candidate_resources.registers_per_thread
            << " public_static_shared_bytes="
            << public_resources.static_shared_bytes
            << " candidate_static_shared_bytes="
            << candidate_resources.static_shared_bytes
            << " public_local_bytes=" << public_resources.local_bytes
            << " candidate_local_bytes=" << candidate_resources.local_bytes
            << " public_active_blocks_per_sm="
            << public_resources.active_blocks_per_sm
            << " candidate_active_blocks_per_sm="
            << candidate_resources.active_blocks_per_sm
            << (resident_grid64 ? " require_registers_eq=64"
                                : " require_registers_le=64")
            << " require_static_shared_eq=1152"
            << " require_zero_local=true"
            << " require_threads_eq=256"
            << (resident_grid64 ? " require_active_blocks_eq=4"
                                : " require_active_blocks_ge=4");
  if (resident_grid64) {
    std::cout << " device_sms=" << multiprocessor_count
              << " resident_capacity_blocks=" << resident_capacity
              << " require_device_sms_eq=16"
              << " require_resident_capacity_eq=64";
  }
  std::cout
            << " null_queries="
            << (public_resource_null_gate && candidate_resource_null_gate
                    ? "PASS"
                    : "FAIL")
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!ready) {
    return;
  }

  std::vector<std::uint8_t> host_weights(kWeightElements);
  fill_fp8_m2_code_distribution(host_weights, kRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  std::vector<std::uint8_t> host_sidecar_storage;
  std::vector<std::uint16_t> host_activation_storage(
      kActivationGuardElements + kColumns + kActivationGuardElements,
      kActivationGuard);
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 29U + (column >> 3U) * 7U + 11U) %
                         127U) -
        63;
    host_activation_storage[kActivationGuardElements + column] =
        encode_bf16(static_cast<float>(centered) / 512.0F);
  }
  const std::vector<std::uint16_t> finite_host_activation_storage =
      host_activation_storage;
  const std::vector<std::uint16_t> host_output_initial(
      kOutputGuardElements + kRows + kOutputGuardElements, kOutputCanary);

  DeviceBuffer<std::uint8_t> sidecar_storage;
  DeviceBuffer<std::uint16_t> activation_storage;
  DeviceBuffer<std::uint16_t> public_output_storage;
  DeviceBuffer<std::uint16_t> candidate_output_storage;
  DeviceBuffer<std::uint16_t> replay_output_storage;
  DeviceBuffer<std::uint16_t> timing_output_storage;
  ready = test.cuda_ok(
      sidecar_storage.allocate(kInputGuardBytes + kWeightElements +
                               kInputGuardBytes),
      label + " allocate guarded AoSoA4 sidecar");
  ready = ready && test.cuda_ok(
                       activation_storage.allocate(
                           host_activation_storage.size()),
                       label + " allocate guarded activation");
  for (auto* const output_storage :
       {&public_output_storage, &candidate_output_storage,
        &replay_output_storage, &timing_output_storage}) {
    ready = ready && test.cuda_ok(
                         output_storage->allocate(host_output_initial.size()),
                         label + " allocate guarded output");
  }
  if (!ready) {
    return;
  }

  const std::uint8_t* const sidecar =
      sidecar_storage.get() + kInputGuardBytes;
  const std::uint16_t* const activation =
      activation_storage.get() + kActivationGuardElements;
  std::uint16_t* const public_output =
      public_output_storage.get() + kOutputGuardElements;
  std::uint16_t* const candidate_output =
      candidate_output_storage.get() + kOutputGuardElements;
  std::uint16_t* const replay_output =
      replay_output_storage.get() + kOutputGuardElements;
  std::uint16_t* const timing_output =
      timing_output_storage.get() + kOutputGuardElements;

  bool actual_sidecar_identity_gate = !resident_grid64;
  std::string current_sidecar_sha256;
  const auto upload_fixture = [&](const std::string& fixture_name) {
    const bool sidecar_semantics =
        build_fp8_m1_aosoa4_preswizzled_sidecar(
            host_weights, kRows, kColumns, kInputGuardBytes, kSidecarGuard,
            host_sidecar_storage);
    test.expect(sidecar_semantics,
                fixture_name + " preserves code^(code>>5) byte semantics");
    bool fixture_ready = sidecar_semantics;
    fixture_ready = test.cuda_ok(
                        cudaMemcpyAsync(
                            sidecar_storage.get(),
                            host_sidecar_storage.data(),
                            host_sidecar_storage.size(),
                            cudaMemcpyHostToDevice, stream),
                        fixture_name + " upload guarded sidecar") &&
                    fixture_ready;
    fixture_ready = test.cuda_ok(
                        cudaMemcpyAsync(
                            activation_storage.get(),
                            host_activation_storage.data(),
                            host_activation_storage.size() *
                                sizeof(std::uint16_t),
                            cudaMemcpyHostToDevice, stream),
                        fixture_name + " upload guarded activation") &&
                    fixture_ready;
    for (auto* const output_storage :
         {&public_output_storage, &candidate_output_storage,
          &replay_output_storage, &timing_output_storage}) {
      fixture_ready = test.cuda_ok(
                          cudaMemcpyAsync(
                              output_storage->get(),
                              host_output_initial.data(),
                              host_output_initial.size() *
                                  sizeof(std::uint16_t),
                              cudaMemcpyHostToDevice, stream),
                          fixture_name + " initialize guarded output") &&
                      fixture_ready;
    }
    fixture_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                 fixture_name + " upload synchronize") &&
                    fixture_ready;
    const std::string canonical_sha256 =
        q3x::core::sha256(std::string_view(
            reinterpret_cast<const char*>(host_weights.data()),
            host_weights.size()))
            .hex();
    current_sidecar_sha256 =
        q3x::core::sha256(std::string_view(
            reinterpret_cast<const char*>(host_sidecar_storage.data() +
                                          kInputGuardBytes),
            kWeightElements))
            .hex();
    const bool is_actual_payload =
        canonical_sha256 == kActualPayloadSha256;
    if (resident_grid64 && is_actual_payload) {
      actual_sidecar_identity_gate =
          current_sidecar_sha256 == kActualSidecarSha256;
      test.expect(actual_sidecar_identity_gate,
                  fixture_name + " matches pinned actual sidecar SHA256");
      fixture_ready = fixture_ready && actual_sidecar_identity_gate;
    }
    std::cout << log_prefix << "_FIXTURE: fixture=" << fixture_name
              << " canonical_bytes=" << host_weights.size()
              << " canonical_sha256=" << canonical_sha256
              << " sidecar_bytes=" << kWeightElements
              << " sidecar_layout=aosoa4_preswizzled"
              << " sidecar_runtime_pack=none";
    if (resident_grid64) {
      std::cout << " sidecar_sha256=" << current_sidecar_sha256;
      if (is_actual_payload) {
        std::cout << " expected_sidecar_sha256=" << kActualSidecarSha256
                  << " sidecar_identity="
                  << (actual_sidecar_identity_gate ? "PASS" : "FAIL");
      }
    }
    std::cout << " gate=" << (fixture_ready ? "PASS" : "FAIL") << '\n';
    return fixture_ready;
  };

  std::vector<std::uint16_t> observed_public(host_output_initial.size());
  std::vector<std::uint16_t> observed_candidate(host_output_initial.size());
  std::vector<std::uint8_t> observed_sidecar;
  std::vector<std::uint16_t> observed_activation(
      host_activation_storage.size());
  const auto output_guards_intact = [&](const auto& observed,
                                        const std::uint16_t canary) {
    return std::all_of(
               observed.begin(),
               observed.begin() + kOutputGuardElements,
               [canary](const std::uint16_t value) {
                 return value == canary;
               }) &&
           std::all_of(
               observed.end() - kOutputGuardElements, observed.end(),
               [canary](const std::uint16_t value) {
                 return value == canary;
               });
  };
  const auto run_direct_diff = [&](const std::string& fixture_name) {
    bool diff_ready = test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_bf16_cuda(
                sidecar, kWeightScale, activation, kRows, kColumns,
                public_output, static_cast<void*>(stream))),
        fixture_name + " launch current public O-proj");
    diff_ready = test.cuda_ok(
                     static_cast<cudaError_t>(launch_candidate_route(
                         sidecar, kWeightScale, activation, kRows, kColumns,
                         candidate_output, static_cast<void*>(stream))),
                     fixture_name + " launch test-only candidate O-proj") &&
                 diff_ready;
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(
                         observed_public.data(), public_output_storage.get(),
                         observed_public.size() * sizeof(std::uint16_t),
                         cudaMemcpyDeviceToHost, stream),
                     fixture_name + " copy public guarded output") &&
                 diff_ready;
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(
                         observed_candidate.data(),
                         candidate_output_storage.get(),
                         observed_candidate.size() * sizeof(std::uint16_t),
                         cudaMemcpyDeviceToHost, stream),
                     fixture_name + " copy candidate guarded output") &&
                 diff_ready;
    observed_sidecar.resize(host_sidecar_storage.size());
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(observed_sidecar.data(),
                                     sidecar_storage.get(),
                                     observed_sidecar.size(),
                                     cudaMemcpyDeviceToHost, stream),
                     fixture_name + " copy sidecar and guards") &&
                 diff_ready;
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(
                         observed_activation.data(), activation_storage.get(),
                         observed_activation.size() * sizeof(std::uint16_t),
                         cudaMemcpyDeviceToHost, stream),
                     fixture_name + " copy activation and guards") &&
                 diff_ready;
    diff_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                              fixture_name + " diff synchronize") &&
                 diff_ready;
    std::size_t mismatches = 0U;
    for (std::size_t row = 0U; row < kRows; ++row) {
      mismatches +=
          observed_public[kOutputGuardElements + row] !=
                  observed_candidate[kOutputGuardElements + row]
              ? 1U
              : 0U;
    }
    const bool public_guards =
        output_guards_intact(observed_public, kOutputCanary);
    const bool candidate_guards =
        output_guards_intact(observed_candidate, kOutputCanary);
    const bool sidecar_preserved =
        observed_sidecar == host_sidecar_storage;
    const bool activation_preserved =
        observed_activation == host_activation_storage;
    const bool direct_gate =
        diff_ready && mismatches == 0U && public_guards && candidate_guards &&
        sidecar_preserved && activation_preserved;
    test.expect(direct_gate,
                fixture_name + " is bitwise and preserves all guards");
    std::cout << log_prefix << "_DIFF: fixture=" << fixture_name
              << " mismatches=" << mismatches << '/' << kRows
              << " public_output_guards="
              << (public_guards ? "PASS" : "FAIL")
              << " candidate_output_guards="
              << (candidate_guards ? "PASS" : "FAIL")
              << " sidecar_payload_and_guards="
              << (sidecar_preserved ? "PASS" : "FAIL")
              << " activation_payload_and_guards="
              << (activation_preserved ? "PASS" : "FAIL")
              << " gate=" << (direct_gate ? "PASS" : "FAIL") << '\n';
    return direct_gate;
  };

  const std::string stress_label = label + " same_bank_stress";
  if (!upload_fixture(stress_label)) {
    return;
  }
  const bool stress_direct_gate = run_direct_diff(stress_label);
  if (!stress_direct_gate) {
    return;
  }

  struct CapturedOProjRoute {
    bool ready = false;
    cudaGraph_t graph = nullptr;
    std::size_t total_nodes = 0U;
    std::size_t root_nodes = 0U;
    cudaKernelNodeParams kernel_params{};
  };
  const auto capture_route = [&](const auto& launch,
                                 const std::string& capture_label) {
    CapturedOProjRoute captured;
    bool capture_ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        capture_label + " begin capture");
    int launch_status = static_cast<int>(cudaErrorUnknown);
    if (capture_ready) {
      launch_status = launch();
      capture_ready = test.cuda_ok(
                          cudaStreamEndCapture(stream, &captured.graph),
                          capture_label + " end capture") &&
                      capture_ready;
    }
    if (capture_ready && captured.graph != nullptr) {
      capture_ready = test.cuda_ok(
                          cudaGraphGetNodes(captured.graph, nullptr,
                                            &captured.total_nodes),
                          capture_label + " count nodes") &&
                      capture_ready;
      capture_ready = test.cuda_ok(
                          cudaGraphGetRootNodes(captured.graph, nullptr,
                                                &captured.root_nodes),
                          capture_label + " count roots") &&
                      capture_ready;
    } else if (capture_ready) {
      test.expect(false, capture_label + " produced a null graph");
      capture_ready = false;
    }
    if (capture_ready && captured.total_nodes == 1U) {
      cudaGraphNode_t node = nullptr;
      std::size_t node_capacity = 1U;
      capture_ready = test.cuda_ok(
                          cudaGraphGetNodes(captured.graph, &node,
                                            &node_capacity),
                          capture_label + " get sole node") &&
                      capture_ready;
      cudaGraphNodeType node_type = cudaGraphNodeTypeEmpty;
      capture_ready = test.cuda_ok(cudaGraphNodeGetType(node, &node_type),
                                   capture_label + " get node type") &&
                      capture_ready;
      if (capture_ready && node_type == cudaGraphNodeTypeKernel) {
        capture_ready = test.cuda_ok(
                            cudaGraphKernelNodeGetParams(
                                node, &captured.kernel_params),
                            capture_label + " get kernel params") &&
                        capture_ready;
      } else {
        test.expect(false, capture_label + " sole node is not a kernel");
        capture_ready = false;
      }
    }
    captured.ready =
        capture_ready && launch_status == static_cast<int>(cudaSuccess);
    return captured;
  };
  const auto launch_public_graph = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_bf16_cuda(
            sidecar, kWeightScale, activation, kRows, kColumns,
            public_output, static_cast<void*>(stream));
  };
  const auto launch_candidate_graph = [&]() noexcept -> int {
    return launch_candidate_route(sidecar, kWeightScale, activation, kRows,
                                  kColumns, replay_output,
                                  static_cast<void*>(stream));
  };
  CapturedOProjRoute public_graph =
      capture_route(launch_public_graph, label + " public graph");
  CapturedOProjRoute candidate_graph =
      capture_route(launch_candidate_graph, label + " candidate graph");
  const auto exact_topology = [](const cudaKernelNodeParams& params,
                                 const unsigned int grid_x) {
    return params.gridDim.x == grid_x && params.gridDim.y == 1U &&
           params.gridDim.z == 1U && params.blockDim.x == 256U &&
           params.blockDim.y == 1U && params.blockDim.z == 1U &&
           params.sharedMemBytes == 0U;
  };
  const bool public_graph_gate =
      public_graph.ready && public_graph.total_nodes == 1U &&
      public_graph.root_nodes == 1U &&
      exact_topology(public_graph.kernel_params, 1'024U);
  const bool candidate_graph_gate =
      candidate_graph.ready && candidate_graph.total_nodes == 1U &&
      candidate_graph.root_nodes == 1U &&
      exact_topology(candidate_graph.kernel_params,
                     resident_grid64 ? 64U : 1'024U);
  const bool graph_function_gate =
      public_graph_gate && candidate_graph_gate &&
      (resident_grid64
           ? public_graph.kernel_params.func == candidate_graph.kernel_params.func
           : public_graph.kernel_params.func != candidate_graph.kernel_params.func);

  constexpr std::uint8_t kReplayPoisonByte = 0x69U;
  constexpr std::uint16_t kReplayPoison = 0x6969U;
  std::vector<std::uint16_t> observed_graph_public(
      host_output_initial.size());
  std::vector<std::uint16_t> observed_replay(host_output_initial.size());
  cudaGraphExec_t public_graph_exec = nullptr;
  cudaGraphExec_t candidate_graph_exec = nullptr;
  bool replay_ready = candidate_graph_gate && graph_function_gate;
  if (replay_ready && resident_grid64) {
    replay_ready = test.cuda_ok(
        cudaGraphInstantiate(&public_graph_exec, public_graph.graph, nullptr,
                             nullptr, 0U),
        label + " instantiate public graph");
  }
  if (replay_ready) {
    replay_ready = test.cuda_ok(
        cudaGraphInstantiate(&candidate_graph_exec, candidate_graph.graph,
                             nullptr, nullptr, 0U),
        label + " instantiate candidate graph");
  }
  if (replay_ready) {
    if (resident_grid64) {
      replay_ready = test.cuda_ok(
                         cudaMemsetAsync(
                             public_output_storage.get(), kReplayPoisonByte,
                             host_output_initial.size() *
                                 sizeof(std::uint16_t),
                             stream),
                         label + " poison public graph replay output") &&
                     replay_ready;
    }
    replay_ready = test.cuda_ok(
                       cudaMemsetAsync(
                           replay_output_storage.get(), kReplayPoisonByte,
                           host_output_initial.size() *
                               sizeof(std::uint16_t),
                           stream),
                       label + " poison graph replay output") &&
                   replay_ready;
    if (resident_grid64) {
      replay_ready = test.cuda_ok(
                         cudaGraphLaunch(public_graph_exec, stream),
                         label + " launch public graph replay") &&
                     replay_ready;
    }
    replay_ready = test.cuda_ok(
                       cudaGraphLaunch(candidate_graph_exec, stream),
                       label + " launch candidate graph replay") &&
                   replay_ready;
    if (resident_grid64) {
      replay_ready = test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_graph_public.data(),
                             public_output_storage.get(),
                             observed_graph_public.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy public graph replay output") &&
                     replay_ready;
    }
    replay_ready = test.cuda_ok(
                       cudaMemcpyAsync(
                           observed_replay.data(), replay_output_storage.get(),
                           observed_replay.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy graph replay output") &&
                   replay_ready;
    replay_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " graph replay synchronize") &&
                   replay_ready;
  }
  std::size_t replay_mismatches = 0U;
  if (replay_ready) {
    const auto& replay_reference =
        resident_grid64 ? observed_graph_public : observed_public;
    for (std::size_t row = 0U; row < kRows; ++row) {
      replay_mismatches +=
          observed_replay[kOutputGuardElements + row] !=
                  replay_reference[kOutputGuardElements + row]
              ? 1U
              : 0U;
    }
  }
  const bool public_replay_guards =
      !resident_grid64 ||
      (replay_ready &&
       output_guards_intact(observed_graph_public, kReplayPoison));
  const bool replay_guards =
      replay_ready && output_guards_intact(observed_replay, kReplayPoison);
  const bool replay_gate =
      replay_ready && replay_mismatches == 0U && public_replay_guards &&
      replay_guards;
  if (public_graph_exec != nullptr) {
    (void)test.cuda_ok(cudaGraphExecDestroy(public_graph_exec),
                       label + " destroy public graph executable");
  }
  if (candidate_graph_exec != nullptr) {
    (void)test.cuda_ok(cudaGraphExecDestroy(candidate_graph_exec),
                       label + " destroy candidate graph executable");
  }
  if (public_graph.graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(public_graph.graph),
                       label + " destroy public graph");
  }
  if (candidate_graph.graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(candidate_graph.graph),
                       label + " destroy candidate graph");
  }
  const bool graph_gate = public_graph_gate && candidate_graph_gate &&
                          graph_function_gate && replay_gate;
  test.expect(
      graph_gate,
      label + (resident_grid64
                   ? " captures same-function 1024/64-grid routes and replays"
                   : " captures distinct one-node routes and replays"));
  if (resident_grid64) {
    std::cout << log_prefix << "_GRAPH:"
              << " public_nodes=" << public_graph.total_nodes
              << " public_roots=" << public_graph.root_nodes
              << " candidate_nodes=" << candidate_graph.total_nodes
              << " candidate_roots=" << candidate_graph.root_nodes
              << " public_grid=" << public_graph.kernel_params.gridDim.x
              << " candidate_grid=" << candidate_graph.kernel_params.gridDim.x
              << " block=256 dynamic_shared=0"
              << " functions_same="
              << (graph_function_gate ? "true" : "false")
              << " replay_mismatches=" << replay_mismatches << '/' << kRows
              << " public_replay_guards="
              << (public_replay_guards ? "PASS" : "FAIL")
              << " candidate_replay_guards="
              << (replay_guards ? "PASS" : "FAIL")
              << " gate=" << (graph_gate ? "PASS" : "FAIL") << '\n';
  } else {
    std::cout << "FP8_M1_O_PROJ_CS_GRAPH:"
              << " public_nodes=" << public_graph.total_nodes
              << " public_roots=" << public_graph.root_nodes
              << " candidate_nodes=" << candidate_graph.total_nodes
              << " candidate_roots=" << candidate_graph.root_nodes
              << " grid=1024 block=256 dynamic_shared=0"
              << " functions_distinct="
              << (graph_function_gate ? "true" : "false")
              << " replay_mismatches=" << replay_mismatches << '/' << kRows
              << " replay_guards=" << (replay_guards ? "PASS" : "FAIL")
              << " gate=" << (graph_gate ? "PASS" : "FAIL") << '\n';
  }

  struct InvalidOProjCase {
    const char* name;
    const std::uint8_t* sidecar_weights;
    const std::uint16_t* activation_values;
    std::size_t rows;
    std::size_t columns;
    std::uint16_t* output;
  };
  const std::array<InvalidOProjCase, 11U> invalid_cases{{
      {"null_sidecar", nullptr, activation, kRows, kColumns,
       candidate_output},
      {"null_activation", sidecar, nullptr, kRows, kColumns,
       candidate_output},
      {"null_output", sidecar, activation, kRows, kColumns, nullptr},
      {"wrong_rows", sidecar, activation, kRows - 1U, kColumns,
       candidate_output},
      {"wrong_columns", sidecar, activation, kRows, kColumns - 1U,
       candidate_output},
      {"sidecar_not_16_byte_aligned", sidecar + 1U, activation, kRows,
       kColumns, candidate_output},
      {"activation_not_8_byte_aligned", sidecar, activation + 1U, kRows,
       kColumns, candidate_output},
      {"output_not_2_byte_aligned", sidecar, activation, kRows, kColumns,
       reinterpret_cast<std::uint16_t*>(
           reinterpret_cast<std::uint8_t*>(candidate_output) + 1U)},
      {"sidecar_activation_complete_span_overlap", sidecar,
       reinterpret_cast<const std::uint16_t*>(sidecar), kRows, kColumns,
       candidate_output},
      {"sidecar_output_complete_span_overlap", sidecar, activation, kRows,
       kColumns, reinterpret_cast<std::uint16_t*>(
                     const_cast<std::uint8_t*>(sidecar))},
      {"activation_output_complete_span_overlap", sidecar, activation,
       kRows, kColumns, const_cast<std::uint16_t*>(activation)},
  }};
  const auto invalid_does_not_enqueue =
      [&](const InvalidOProjCase& invalid_case) {
        const std::string case_label =
            label + " invalid " + invalid_case.name;
        cudaGraph_t invalid_graph = nullptr;
        bool invalid_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream,
                                   cudaStreamCaptureModeThreadLocal),
            case_label + " begin capture");
        int launch_status = static_cast<int>(cudaErrorUnknown);
        if (invalid_ready) {
          launch_status = launch_candidate_route(
              invalid_case.sidecar_weights, kWeightScale,
              invalid_case.activation_values, invalid_case.rows,
              invalid_case.columns, invalid_case.output,
              static_cast<void*>(stream));
          invalid_ready = test.cuda_ok(
                              cudaStreamEndCapture(stream, &invalid_graph),
                              case_label + " end capture") &&
                          invalid_ready;
        }
        std::size_t node_count = 0U;
        if (invalid_ready && invalid_graph != nullptr) {
          invalid_ready = test.cuda_ok(
                              cudaGraphGetNodes(invalid_graph, nullptr,
                                                &node_count),
                              case_label + " count nodes") &&
                          invalid_ready;
        } else if (invalid_ready) {
          test.expect(false, case_label + " produced a null graph");
          invalid_ready = false;
        }
        if (invalid_graph != nullptr) {
          invalid_ready = test.cuda_ok(cudaGraphDestroy(invalid_graph),
                                       case_label + " destroy graph") &&
                          invalid_ready;
        }
        const bool case_gate =
            invalid_ready &&
            launch_status == static_cast<int>(cudaErrorInvalidValue) &&
            node_count == 0U;
        test.expect(case_gate,
                    case_label + " returns invalid before enqueue");
        return case_gate;
      };
  bool invalid_gate = true;
  for (const InvalidOProjCase& invalid_case : invalid_cases) {
    invalid_gate = invalid_does_not_enqueue(invalid_case) && invalid_gate;
  }
  std::cout << log_prefix << "_INVALID: cases=" << invalid_cases.size()
            << " all_invalid_value_zero_nodes="
            << (invalid_gate ? "PASS" : "FAIL") << '\n';

  bool signed_nonfinite_gate = true;
  if (resident_grid64) {
    struct SignedNonfiniteFixture {
      const char* name;
      std::uint16_t activation_bits;
      bool expect_nan;
      bool expect_negative;
    };
    constexpr std::array<SignedNonfiniteFixture, 4U> kSignedNonfiniteFixtures{{
        {"positive_infinity", 0x7f80U, false, false},
        {"negative_infinity", 0xff80U, false, true},
        {"positive_nan", 0x7fc1U, true, false},
        {"negative_nan", 0xffc1U, true, true},
    }};
    std::fill(host_weights.begin(), host_weights.end(),
              static_cast<std::uint8_t>(0x38U));
    for (const SignedNonfiniteFixture& fixture : kSignedNonfiniteFixtures) {
      host_activation_storage = finite_host_activation_storage;
      std::fill(host_activation_storage.begin() + kActivationGuardElements,
                host_activation_storage.end() - kActivationGuardElements,
                encode_bf16(0.0F));
      host_activation_storage[kActivationGuardElements + 17U] =
          fixture.activation_bits;
      const std::string fixture_label =
          label + " signed_nonfinite " + fixture.name;
      const bool uploaded = upload_fixture(fixture_label);
      const bool bitwise_guarded = uploaded && run_direct_diff(fixture_label);
      std::size_t classification_matches = 0U;
      if (bitwise_guarded) {
        for (std::size_t row = 0U; row < kRows; ++row) {
          const float value = decode_bf16(
              observed_public[kOutputGuardElements + row]);
          const bool matches = fixture.expect_nan
                                   ? std::isnan(value)
                                   : std::isinf(value) &&
                                         std::signbit(value) ==
                                             fixture.expect_negative;
          classification_matches += matches ? 1U : 0U;
        }
      }
      const bool fixture_gate =
          bitwise_guarded && classification_matches == kRows;
      test.expect(fixture_gate,
                  fixture_label + " is bitwise with exact classification");
      signed_nonfinite_gate = signed_nonfinite_gate && fixture_gate;
      std::cout << log_prefix << "_NONFINITE: fixture=" << fixture.name
                << " input_bits=0x" << std::hex << fixture.activation_bits
                << std::dec << " public_candidate_bitwise="
                << (bitwise_guarded ? "PASS" : "FAIL")
                << " classification_matches=" << classification_matches
                << '/' << kRows
                << " expected="
                << (fixture.expect_nan
                        ? (fixture.expect_negative ? "negative_nan"
                                                   : "positive_nan")
                        : (fixture.expect_negative ? "negative_infinity"
                                                   : "positive_infinity"))
                << " gate=" << (fixture_gate ? "PASS" : "FAIL") << '\n';
    }
    host_activation_storage = finite_host_activation_storage;
  }

  const bool focused_gate =
      resource_gate && stress_direct_gate && graph_gate && invalid_gate &&
      signed_nonfinite_gate;
  test.expect(focused_gate,
              label + " clears focused correctness/Graph/invalid gates");
  std::cout << log_prefix << "_FOCUSED:"
            << " resources=" << (resource_gate ? "PASS" : "FAIL")
            << " stress_bitwise_guards="
            << (stress_direct_gate ? "PASS" : "FAIL");
  if (resident_grid64) {
    std::cout << " signed_nonfinite="
              << (signed_nonfinite_gate ? "PASS" : "FAIL")
              << " graph_same_function_replay="
              << (graph_gate ? "PASS" : "FAIL")
              << " invalid_zero_node="
              << (invalid_gate ? "PASS" : "FAIL")
              << " sidecar_load_policy=production_default"
              << " activation_load_policy=production_default"
              << " topology=64x256";
  } else {
    std::cout << " graph_distinct_replay="
              << (graph_gate ? "PASS" : "FAIL")
              << " invalid_zero_node="
              << (invalid_gate ? "PASS" : "FAIL")
              << " sidecar_load_policy=streaming"
              << " activation_load_policy=production_default"
              << " topology=1024x256";
  }
  std::cout << " gate=" << (focused_gate ? "PASS" : "FAIL") << '\n';
  if (!focused_gate) {
    return;
  }

  struct OProjCsTiming {
    bool ready = false;
    bool every_round_nonregressing = false;
    float public_median_ms = std::numeric_limits<float>::quiet_NaN();
    float candidate_median_ms = std::numeric_limits<float>::quiet_NaN();
    float paired_median_speedup =
        std::numeric_limits<float>::quiet_NaN();
    float paired_median_delta_ms =
        std::numeric_limits<float>::quiet_NaN();
    double projected_64_layer_delta_ms =
        std::numeric_limits<double>::quiet_NaN();
  };
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 64;
  constexpr int kMeasurementRounds = 5;
  constexpr std::size_t kTimedPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  const auto launch_public_timing = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_bf16_cuda(
            sidecar, kWeightScale, activation, kRows, kColumns,
            timing_output, static_cast<void*>(stream));
  };
  const auto launch_candidate_timing = [&]() noexcept -> int {
    return launch_candidate_route(sidecar, kWeightScale, activation, kRows,
                                  kColumns, timing_output,
                                  static_cast<void*>(stream));
  };
  const auto measure_timing_pass = [&](const auto& launch,
                                       const std::string& pass_label) {
    if (resident_grid64) {
      const bool reset_ready = test.cuda_ok(
          cudaMemcpyAsync(timing_output_storage.get(),
                          host_output_initial.data(),
                          host_output_initial.size() * sizeof(std::uint16_t),
                          cudaMemcpyHostToDevice, stream),
          pass_label + " reset guarded timing output");
      if (!reset_ready) {
        return std::numeric_limits<float>::quiet_NaN();
      }
    }
    return measure_small_m_tile(test, stream, launch, kMeasuredIterations,
                                pass_label);
  };
  const auto benchmark_fixture = [&](const std::string& fixture_name,
                                     const bool require_round_improvement) {
    OProjCsTiming timing{};
    bool timing_ready = true;
    for (int iteration = 0;
         iteration < kWarmupIterations && timing_ready; ++iteration) {
      const bool public_first = (iteration & 1) == 0;
      if (public_first) {
        timing_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_public_timing()),
            fixture_name + " alternating public warmup");
        timing_ready = test.cuda_ok(
                           static_cast<cudaError_t>(
                               launch_candidate_timing()),
                           fixture_name + " alternating candidate warmup") &&
                       timing_ready;
      } else {
        timing_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_candidate_timing()),
            fixture_name + " alternating candidate warmup");
        timing_ready = test.cuda_ok(
                           static_cast<cudaError_t>(launch_public_timing()),
                           fixture_name + " alternating public warmup") &&
                       timing_ready;
      }
    }
    if (timing_ready) {
      timing_ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_public_timing()),
          fixture_name + " prime B1");
      timing_ready = test.cuda_ok(
                         static_cast<cudaError_t>(
                             launch_candidate_timing()),
                         fixture_name + " prime C1") &&
                     timing_ready;
      timing_ready = test.cuda_ok(
                         static_cast<cudaError_t>(
                             launch_candidate_timing()),
                         fixture_name + " prime C2") &&
                     timing_ready;
      timing_ready = test.cuda_ok(
                         static_cast<cudaError_t>(launch_public_timing()),
                         fixture_name + " prime B2") &&
                     timing_ready;
    }
    timing_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                fixture_name + " warmup/prime synchronize") &&
                   timing_ready;

    std::array<float, kTimedPasses> public_passes{};
    std::array<float, kTimedPasses> candidate_passes{};
    std::array<float, kMeasurementRounds> paired_speedups{};
    std::array<float, kMeasurementRounds> paired_deltas{};
    bool every_round_nonregressing = timing_ready;
    for (int round = 0; round < kMeasurementRounds && timing_ready; ++round) {
      const bool public_first = (round & 1) == 0;
      const std::string round_label =
          fixture_name + " round=" + std::to_string(round + 1);
      float public1 = std::numeric_limits<float>::quiet_NaN();
      float public2 = std::numeric_limits<float>::quiet_NaN();
      float candidate1 = std::numeric_limits<float>::quiet_NaN();
      float candidate2 = std::numeric_limits<float>::quiet_NaN();
      if (public_first) {
        public1 =
            measure_timing_pass(launch_public_timing, round_label + " B1");
        candidate1 = measure_timing_pass(launch_candidate_timing,
                                         round_label + " C1");
        candidate2 = measure_timing_pass(launch_candidate_timing,
                                         round_label + " C2");
        public2 =
            measure_timing_pass(launch_public_timing, round_label + " B2");
      } else {
        candidate1 = measure_timing_pass(launch_candidate_timing,
                                         round_label + " C1");
        public1 =
            measure_timing_pass(launch_public_timing, round_label + " B1");
        public2 =
            measure_timing_pass(launch_public_timing, round_label + " B2");
        candidate2 = measure_timing_pass(launch_candidate_timing,
                                         round_label + " C2");
      }
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      public_passes[pass] = public1;
      public_passes[pass + 1U] = public2;
      candidate_passes[pass] = candidate1;
      candidate_passes[pass + 1U] = candidate2;
      const bool finite =
          std::isfinite(public1) && std::isfinite(public2) &&
          std::isfinite(candidate1) && std::isfinite(candidate2) &&
          public1 > 0.0F && public2 > 0.0F && candidate1 > 0.0F &&
          candidate2 > 0.0F;
      const float paired_public = 0.5F * (public1 + public2);
      const float paired_candidate = 0.5F * (candidate1 + candidate2);
      const float paired_speedup = paired_public / paired_candidate;
      const float paired_delta = paired_public - paired_candidate;
      paired_speedups[static_cast<std::size_t>(round)] = paired_speedup;
      paired_deltas[static_cast<std::size_t>(round)] = paired_delta;
      const bool round_nonregressing =
          finite && (require_round_improvement ? paired_speedup > 1.0F
                                               : paired_speedup >= 1.0F);
      every_round_nonregressing =
          every_round_nonregressing && round_nonregressing;
      timing_ready = timing_ready && finite;
      std::cout << perf_prefix << "_ROUND: fixture="
                << fixture_name << " round=" << round + 1
                << " order="
                << (public_first ? "B-C-C-B" : "C-B-B-C")
                << " launches_per_pass=" << kMeasuredIterations
                << " shared_output_address=true"
                << (resident_grid64 ? " output_reset_each_pass=true" : "")
                << " public_pass1_ms=" << public1
                << " candidate_pass1_ms=" << candidate1
                << " candidate_pass2_ms=" << candidate2
                << " public_pass2_ms=" << public2
                << " paired_speedup=" << paired_speedup
                << " paired_delta_ms=" << paired_delta
                << " gate="
                << (round_nonregressing ? "PASS" : "FAIL") << '\n';
    }
    timing.ready = timing_ready;
    timing.every_round_nonregressing = every_round_nonregressing;
    if (timing_ready) {
      timing.public_median_ms =
          median_fp8_kv_pair_timing(public_passes);
      timing.candidate_median_ms =
          median_fp8_kv_pair_timing(candidate_passes);
      timing.paired_median_speedup =
          median_fp8_kv_pair_timing(paired_speedups);
      timing.paired_median_delta_ms =
          median_fp8_kv_pair_timing(paired_deltas);
      timing.projected_64_layer_delta_ms =
          static_cast<double>(timing.paired_median_delta_ms) * 64.0;
    }
    return timing;
  };

  const char* const actual_checkpoint =
      std::getenv("Q3X_FP8_M1_O_PROJ_ACTUAL_CHECKPOINT_FILE");
  const bool actual_source_set =
      actual_checkpoint != nullptr && actual_checkpoint[0] != '\0';
  test.expect(actual_source_set,
              label + " requires the pinned actual-checkpoint shard");
  if (!actual_source_set) {
    return;
  }
  std::ifstream input(actual_checkpoint, std::ios::binary);
  const bool opened = input.is_open();
  test.expect(opened, label + " opens actual-checkpoint shard");
  if (!opened) {
    return;
  }
  input.seekg(0, std::ios::end);
  const std::streamoff file_size = input.tellg();
  const bool range_valid =
      file_size >= 0 &&
      kActualPayloadOffset <= static_cast<std::uint64_t>(file_size) &&
      host_weights.size() <=
          static_cast<std::uint64_t>(file_size) - kActualPayloadOffset &&
      kActualPayloadOffset <= static_cast<std::uint64_t>(
                                  std::numeric_limits<std::streamoff>::max()) &&
      host_weights.size() <= static_cast<std::size_t>(
                                 std::numeric_limits<std::streamsize>::max());
  test.expect(range_valid, label + " actual payload range is present");
  if (!range_valid) {
    return;
  }
  input.seekg(static_cast<std::streamoff>(kActualPayloadOffset),
              std::ios::beg);
  input.read(reinterpret_cast<char*>(host_weights.data()),
             static_cast<std::streamsize>(host_weights.size()));
  const bool read_complete =
      input.gcount() == static_cast<std::streamsize>(host_weights.size());
  test.expect(read_complete,
              label + " reads all actual O-proj payload bytes");
  if (!read_complete) {
    return;
  }
  const std::string actual_sha256 =
      q3x::core::sha256(std::string_view(
          reinterpret_cast<const char*>(host_weights.data()),
          host_weights.size()))
          .hex();
  const bool actual_identity_gate =
      actual_sha256 == kActualPayloadSha256;
  test.expect(actual_identity_gate,
              label + " matches pinned actual O-proj payload SHA256");
  std::cout << log_prefix << "_ACTUAL_FIXTURE:"
            << " checkpoint_path=" << actual_checkpoint
            << " absolute_payload_offset=" << kActualPayloadOffset
            << " payload_bytes=" << host_weights.size()
            << " sha256=" << actual_sha256
            << " expected_sha256=" << kActualPayloadSha256
            << " gate=" << (actual_identity_gate ? "PASS" : "FAIL")
            << '\n';
  if (!actual_identity_gate) {
    return;
  }

  const std::string actual_label = label + " actual_checkpoint";
  if (!upload_fixture(actual_label)) {
    return;
  }
  const bool actual_direct_gate = run_direct_diff(actual_label);
  const OProjCsTiming actual_timing =
      actual_direct_gate
          ? benchmark_fixture("actual_checkpoint", resident_grid64)
                         : OProjCsTiming{};
  const double kRequiredActualSpeedup = resident_grid64 ? 1.02 : 1.005;
  constexpr double kRequiredStressSpeedup = 1.0;
  const double kRequiredProjected64LayerDeltaMs =
      resident_grid64 ? 0.30 : 0.10;
  const double kRequiredThreeProcessMedianProjected64LayerDeltaMs =
      resident_grid64 ? 0.40 : 0.125;
  const bool actual_timing_gate =
      actual_timing.ready && actual_timing.every_round_nonregressing &&
      std::isfinite(actual_timing.paired_median_speedup) &&
      actual_timing.paired_median_speedup >= kRequiredActualSpeedup &&
      std::isfinite(actual_timing.projected_64_layer_delta_ms) &&
      actual_timing.projected_64_layer_delta_ms >=
          kRequiredProjected64LayerDeltaMs;
  const bool actual_gate =
      actual_identity_gate && actual_sidecar_identity_gate &&
      actual_direct_gate && actual_timing_gate;
  test.expect(actual_gate,
              label + " clears the first frozen actual-process gate");
  std::cout << perf_prefix << "_ACTUAL:"
            << " public_median_ms=" << actual_timing.public_median_ms
            << " candidate_median_ms="
            << actual_timing.candidate_median_ms
            << " paired_median_speedup="
            << actual_timing.paired_median_speedup
            << " paired_median_delta_ms="
            << actual_timing.paired_median_delta_ms
            << " projected_64_layer_delta_ms="
            << actual_timing.projected_64_layer_delta_ms
            << " every_round_nonregressing="
            << (actual_timing.every_round_nonregressing ? "true" : "false")
            << (resident_grid64
                    ? " required_each_actual_round=improving"
                    : "")
            << " required_speedup=" << kRequiredActualSpeedup
            << " required_projected_64_layer_delta_ms="
            << kRequiredProjected64LayerDeltaMs
            << " bitwise_guards="
            << (actual_direct_gate ? "PASS" : "FAIL")
            << " gate=" << (actual_gate ? "PASS" : "FAIL") << '\n';
  if (!actual_gate) {
    std::cout << perf_prefix << "_STOP_LOSS:"
              << " reason=first_frozen_actual_process_failed"
              << " stress_timing=NOT_RUN gate=FAIL\n";
    return;
  }

  fill_fp8_m2_code_distribution(host_weights, kRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  if (!upload_fixture(stress_label)) {
    return;
  }
  const bool stress_retest_direct_gate = run_direct_diff(stress_label);
  const OProjCsTiming stress_timing =
      stress_retest_direct_gate
          ? benchmark_fixture("same_bank_stress", false)
                                : OProjCsTiming{};
  const bool stress_timing_gate =
      stress_timing.ready && stress_timing.every_round_nonregressing &&
      std::isfinite(stress_timing.paired_median_speedup) &&
      stress_timing.paired_median_speedup >= kRequiredStressSpeedup;
  const bool process_gate = focused_gate && actual_gate &&
                            stress_retest_direct_gate && stress_timing_gate;
  test.expect(process_gate,
              label + " clears the frozen single-process selection gate");
  std::cout << perf_prefix << "_SELECTED:"
            << " baseline=current_public_aosoa4_default_cache"
            << (resident_grid64
                    ? " candidate=test_only_same_production_kernel_resident_grid64"
                    : " candidate=test_only_aosoa4_sidecar_cs")
            << (resident_grid64
                    ? " topology=public1024x256_candidate64x256"
                    : " topology=1024x256")
            << " warmup_pairs=" << kWarmupIterations
            << " prime=B-C-C-B"
            << " rounds=" << kMeasurementRounds
            << " launches_per_pass=" << kMeasuredIterations
            << " round_orders=alternating_B-C-C-B_C-B-B-C"
            << " shared_timing_output_address=true"
            << " actual_public_median_ms="
            << actual_timing.public_median_ms
            << " actual_candidate_median_ms="
            << actual_timing.candidate_median_ms
            << " actual_paired_median_speedup="
            << actual_timing.paired_median_speedup
            << " actual_paired_median_delta_ms="
            << actual_timing.paired_median_delta_ms
            << " actual_projected_64_layer_delta_ms="
            << actual_timing.projected_64_layer_delta_ms
            << " actual_every_round_nonregressing="
            << (actual_timing.every_round_nonregressing ? "true" : "false")
            << " stress_public_median_ms="
            << stress_timing.public_median_ms
            << " stress_candidate_median_ms="
            << stress_timing.candidate_median_ms
            << " stress_paired_median_speedup="
            << stress_timing.paired_median_speedup
            << " stress_paired_median_delta_ms="
            << stress_timing.paired_median_delta_ms
            << " stress_every_round_nonregressing="
            << (stress_timing.every_round_nonregressing ? "true" : "false")
            << " required_actual_speedup=" << kRequiredActualSpeedup
            << " required_stress_speedup=" << kRequiredStressSpeedup
            << (resident_grid64
                    ? " required_each_actual_round_speedup_gt=1 required_each_stress_round_speedup_ge=1"
                    : " required_each_round_speedup=1")
            << " required_actual_projected_64_layer_delta_ms="
            << kRequiredProjected64LayerDeltaMs
            << " required_three_process_median_projected_64_layer_delta_ms="
            << kRequiredThreeProcessMedianProjected64LayerDeltaMs
            << " three_process_median_gate=pending_external_aggregation"
            << " actual_payload_hash="
            << (actual_identity_gate ? "PASS" : "FAIL")
            << (resident_grid64 ? " actual_sidecar_hash=" : "")
            << (resident_grid64
                    ? (actual_sidecar_identity_gate ? "PASS" : "FAIL")
                    : "")
            << " focused_gate=" << (focused_gate ? "PASS" : "FAIL")
            << " gate=" << (process_gate ? "PASS" : "FAIL") << '\n';
}

void run_fp8_m1_output_projection_aosoa4_cs_screen(
    TestContext& test, cudaStream_t stream) {
  run_fp8_m1_output_projection_aosoa4_screen(
      test, stream, Fp8M1OProjAosoa4ScreenMode::kCacheStreaming);
}

void run_fp8_m1_output_projection_aosoa4_resident_grid64_screen(
    TestContext& test, cudaStream_t stream) {
  run_fp8_m1_output_projection_aosoa4_screen(
      test, stream, Fp8M1OProjAosoa4ScreenMode::kResidentGrid64);
}

void run_fp8_m1_output_projection_aosoa4_cta512_shared_activation_screen(
    TestContext& test, cudaStream_t stream) {
  if (!decode_fp8_o_proj_cta512_shared_activation_performance_enabled()) {
    std::cout
        << "SKIP: Decode FP8 O-proj CTA512 shared-activation screen; set "
           "Q3X_RUN_SM87_DECODE_FP8_O_PROJ_CTA512_SHARED_ACTIVATION_PERF=1 "
           "to enable\n";
    return;
  }

  constexpr std::size_t kRows = 5'120U;
  constexpr std::size_t kColumns = 6'144U;
  constexpr std::size_t kWeightBytes = kRows * kColumns;
  constexpr std::size_t kInputGuardBytes = 64U;
  constexpr std::size_t kActivationGuardElements = 16U;
  constexpr std::size_t kOutputGuardElements = 32U;
  constexpr std::uint8_t kSidecarGuard = 0xd3U;
  constexpr std::uint16_t kActivationGuard = 0x7fc1U;
  constexpr std::uint16_t kOutputCanary = 0x5aa5U;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::uint64_t kActualPayloadOffset = 3'569'011'232ULL;
  constexpr std::string_view kActualPayloadSha256 =
      "e49a9f770a84cfcf7c2eb60f041aa7f1af8b84f5ab6323d3b8a9151588ff2bb9";
  constexpr std::string_view kActualSidecarSha256 =
      "20f6875f163aefa869d7c96c436fdc63f90171793a88a0f1b3fefca55531782b";
  constexpr std::string_view kLabel =
      "FP8 M1 output projection AoSoA4 CTA512 shared activation";

  Fp8M1Aosoa4PreswizzledResources public_resources{};
  Fp8M1Aosoa4PreswizzledResources candidate_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_row_quad_aosoa4_preswizzled_resources_test_cuda(
              &public_resources.registers_per_thread,
              &public_resources.static_shared_bytes,
              &public_resources.local_bytes,
              &public_resources.maximum_threads_per_block,
              &public_resources.active_blocks_per_sm)),
      std::string(kLabel) + " query public resources");
  ready = test.cuda_ok(
              static_cast<cudaError_t>(q3x::kernels::
                  query_sm87_fp8_w8a16_m1_output_projection_aosoa4_cta512_shared_activation_resources_test_cuda(
                      &candidate_resources.registers_per_thread,
                      &candidate_resources.static_shared_bytes,
                      &candidate_resources.local_bytes,
                      &candidate_resources.maximum_threads_per_block,
                      &candidate_resources.active_blocks_per_sm)),
              std::string(kLabel) + " query candidate resources") &&
          ready;
  const bool public_resource_gate =
      ready && public_resources.registers_per_thread == 64 &&
      public_resources.static_shared_bytes == 1'152U &&
      public_resources.local_bytes == 0U &&
      public_resources.maximum_threads_per_block == 256 &&
      public_resources.active_blocks_per_sm == 4;
  const bool candidate_resource_gate =
      ready && candidate_resources.registers_per_thread <= 64 &&
      candidate_resources.static_shared_bytes == 13'568U &&
      candidate_resources.local_bytes == 0U &&
      candidate_resources.maximum_threads_per_block == 512 &&
      candidate_resources.active_blocks_per_sm >= 2;
  const bool resource_gate = public_resource_gate && candidate_resource_gate;
  test.expect(resource_gate,
              std::string(kLabel) + " clears resource/occupancy gate");
  std::cout << "FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_RESOURCES:"
            << " public_registers=" << public_resources.registers_per_thread
            << " candidate_registers="
            << candidate_resources.registers_per_thread
            << " public_static_shared_bytes="
            << public_resources.static_shared_bytes
            << " candidate_static_shared_bytes="
            << candidate_resources.static_shared_bytes
            << " public_local_bytes=" << public_resources.local_bytes
            << " candidate_local_bytes=" << candidate_resources.local_bytes
            << " public_max_threads="
            << public_resources.maximum_threads_per_block
            << " candidate_max_threads="
            << candidate_resources.maximum_threads_per_block
            << " public_active_blocks_per_sm="
            << public_resources.active_blocks_per_sm
            << " candidate_active_blocks_per_sm="
            << candidate_resources.active_blocks_per_sm
            << " require_candidate_registers_le=64"
            << " require_candidate_shared_eq=13568"
            << " require_candidate_active_blocks_ge=2"
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!ready || !resource_gate) {
    return;
  }

  std::vector<std::uint8_t> host_weights(kWeightBytes);
  std::vector<std::uint8_t> host_sidecar_storage;
  std::vector<std::uint16_t> host_activation_storage(
      kActivationGuardElements + kColumns + kActivationGuardElements,
      kActivationGuard);
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 29U + (column >> 3U) * 7U + 11U) %
                         127U) -
        63;
    host_activation_storage[kActivationGuardElements + column] =
        encode_bf16(static_cast<float>(centered) / 512.0F);
  }
  const std::vector<std::uint16_t> host_output_initial(
      kOutputGuardElements + kRows + kOutputGuardElements, kOutputCanary);

  DeviceBuffer<std::uint8_t> sidecar_storage;
  DeviceBuffer<std::uint16_t> activation_storage;
  DeviceBuffer<std::uint16_t> public_output_storage;
  DeviceBuffer<std::uint16_t> candidate_output_storage;
  DeviceBuffer<std::uint16_t> timing_output_storage;
  ready = test.cuda_ok(
      sidecar_storage.allocate(kInputGuardBytes + kWeightBytes +
                               kInputGuardBytes),
      std::string(kLabel) + " allocate guarded sidecar");
  ready = test.cuda_ok(
              activation_storage.allocate(host_activation_storage.size()),
              std::string(kLabel) + " allocate guarded activation") &&
          ready;
  for (auto* const storage : {&public_output_storage,
                              &candidate_output_storage,
                              &timing_output_storage}) {
    ready = test.cuda_ok(storage->allocate(host_output_initial.size()),
                         std::string(kLabel) + " allocate guarded output") &&
            ready;
  }
  if (!ready) {
    return;
  }

  const std::uint8_t* const sidecar =
      sidecar_storage.get() + kInputGuardBytes;
  const std::uint16_t* const activation =
      activation_storage.get() + kActivationGuardElements;
  std::uint16_t* const public_output =
      public_output_storage.get() + kOutputGuardElements;
  std::uint16_t* const candidate_output =
      candidate_output_storage.get() + kOutputGuardElements;
  std::uint16_t* const timing_output =
      timing_output_storage.get() + kOutputGuardElements;

  const auto launch_public = [&](std::uint16_t* const output) noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_bf16_cuda(
            sidecar, kWeightScale, activation, kRows, kColumns, output,
            static_cast<void*>(stream));
  };
  const auto launch_candidate = [&](std::uint16_t* const output) noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_cta512_shared_activation_test_cuda(
            sidecar, kWeightScale, activation, kRows, kColumns, output,
            static_cast<void*>(stream));
  };

  bool actual_sidecar_identity_gate = false;
  const auto upload_fixture = [&](const std::string& fixture_name,
                                  const bool require_actual_identity) {
    const bool sidecar_semantics =
        build_fp8_m1_aosoa4_preswizzled_sidecar(
            host_weights, kRows, kColumns, kInputGuardBytes, kSidecarGuard,
            host_sidecar_storage);
    bool fixture_ready = sidecar_semantics;
    test.expect(sidecar_semantics,
                fixture_name + " preserves sidecar byte semantics");
    fixture_ready = test.cuda_ok(
                        cudaMemcpyAsync(sidecar_storage.get(),
                                        host_sidecar_storage.data(),
                                        host_sidecar_storage.size(),
                                        cudaMemcpyHostToDevice, stream),
                        fixture_name + " upload sidecar") &&
                    fixture_ready;
    fixture_ready = test.cuda_ok(
                        cudaMemcpyAsync(
                            activation_storage.get(),
                            host_activation_storage.data(),
                            host_activation_storage.size() *
                                sizeof(std::uint16_t),
                            cudaMemcpyHostToDevice, stream),
                        fixture_name + " upload activation") &&
                    fixture_ready;
    for (auto* const storage : {&public_output_storage,
                                &candidate_output_storage,
                                &timing_output_storage}) {
      fixture_ready = test.cuda_ok(
                          cudaMemcpyAsync(
                              storage->get(), host_output_initial.data(),
                              host_output_initial.size() *
                                  sizeof(std::uint16_t),
                              cudaMemcpyHostToDevice, stream),
                          fixture_name + " initialize output") &&
                      fixture_ready;
    }
    fixture_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                 fixture_name + " upload synchronize") &&
                    fixture_ready;
    const std::string sidecar_sha256 =
        q3x::core::sha256(std::string_view(
            reinterpret_cast<const char*>(host_sidecar_storage.data() +
                                          kInputGuardBytes),
            kWeightBytes))
            .hex();
    if (require_actual_identity) {
      actual_sidecar_identity_gate =
          sidecar_sha256 == kActualSidecarSha256;
      test.expect(actual_sidecar_identity_gate,
                  fixture_name + " matches pinned sidecar hash");
      fixture_ready = fixture_ready && actual_sidecar_identity_gate;
    }
    std::cout << "FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_FIXTURE:"
              << " fixture=" << fixture_name
              << " canonical_bytes=" << host_weights.size()
              << " sidecar_bytes=" << kWeightBytes
              << " sidecar_sha256=" << sidecar_sha256
              << " sidecar_layout=aosoa4_preswizzled"
              << " require_actual_identity="
              << (require_actual_identity ? "true" : "false")
              << " gate=" << (fixture_ready ? "PASS" : "FAIL") << '\n';
    return fixture_ready;
  };

  std::vector<std::uint16_t> observed_public(host_output_initial.size());
  std::vector<std::uint16_t> observed_candidate(host_output_initial.size());
  std::vector<std::uint8_t> observed_sidecar;
  std::vector<std::uint16_t> observed_activation(
      host_activation_storage.size());
  const auto guards_intact = [&](const auto& observed) {
    return std::all_of(
               observed.begin(),
               observed.begin() + kOutputGuardElements,
               [](const std::uint16_t value) {
                 return value == kOutputCanary;
               }) &&
           std::all_of(
               observed.end() - kOutputGuardElements, observed.end(),
               [](const std::uint16_t value) {
                 return value == kOutputCanary;
               });
  };
  const auto run_bitwise = [&](const std::string& fixture_name) {
    bool diff_ready = test.cuda_ok(
        static_cast<cudaError_t>(launch_public(public_output)),
        fixture_name + " launch public");
    diff_ready = test.cuda_ok(
                     static_cast<cudaError_t>(
                         launch_candidate(candidate_output)),
                     fixture_name + " launch candidate") &&
                 diff_ready;
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(
                         observed_public.data(), public_output_storage.get(),
                         observed_public.size() * sizeof(std::uint16_t),
                         cudaMemcpyDeviceToHost, stream),
                     fixture_name + " copy public output") &&
                 diff_ready;
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(
                         observed_candidate.data(),
                         candidate_output_storage.get(),
                         observed_candidate.size() * sizeof(std::uint16_t),
                         cudaMemcpyDeviceToHost, stream),
                     fixture_name + " copy candidate output") &&
                 diff_ready;
    observed_sidecar.resize(host_sidecar_storage.size());
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(
                         observed_sidecar.data(), sidecar_storage.get(),
                         observed_sidecar.size(), cudaMemcpyDeviceToHost,
                         stream),
                     fixture_name + " copy sidecar") &&
                 diff_ready;
    diff_ready = test.cuda_ok(
                     cudaMemcpyAsync(
                         observed_activation.data(), activation_storage.get(),
                         observed_activation.size() * sizeof(std::uint16_t),
                         cudaMemcpyDeviceToHost, stream),
                     fixture_name + " copy activation") &&
                 diff_ready;
    diff_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                              fixture_name + " diff synchronize") &&
                 diff_ready;
    std::size_t mismatches = 0U;
    for (std::size_t row = 0U; row < kRows; ++row) {
      mismatches +=
          observed_public[kOutputGuardElements + row] !=
                  observed_candidate[kOutputGuardElements + row]
              ? 1U
              : 0U;
    }
    const bool public_guards = guards_intact(observed_public);
    const bool candidate_guards = guards_intact(observed_candidate);
    const bool sidecar_preserved =
        observed_sidecar == host_sidecar_storage;
    const bool activation_preserved =
        observed_activation == host_activation_storage;
    const bool gate = diff_ready && mismatches == 0U && public_guards &&
                      candidate_guards && sidecar_preserved &&
                      activation_preserved;
    test.expect(gate, fixture_name + " is bitwise with intact guards");
    std::cout << "FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_DIFF:"
              << " fixture=" << fixture_name
              << " mismatches=" << mismatches << '/' << kRows
              << " public_guards="
              << (public_guards ? "PASS" : "FAIL")
              << " candidate_guards="
              << (candidate_guards ? "PASS" : "FAIL")
              << " sidecar_immutable="
              << (sidecar_preserved ? "PASS" : "FAIL")
              << " activation_immutable="
              << (activation_preserved ? "PASS" : "FAIL")
              << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
    return gate;
  };

  struct Timing {
    bool ready = false;
    bool every_round_passed = false;
    float public_median_ms = std::numeric_limits<float>::quiet_NaN();
    float candidate_median_ms = std::numeric_limits<float>::quiet_NaN();
    float paired_median_speedup =
        std::numeric_limits<float>::quiet_NaN();
    float paired_median_delta_ms =
        std::numeric_limits<float>::quiet_NaN();
    double projected_64_layer_delta_ms =
        std::numeric_limits<double>::quiet_NaN();
  };
  constexpr int kWarmupPairs = 10;
  constexpr int kMeasuredLaunches = 64;
  constexpr int kRounds = 5;
  const auto launch_public_timing = [&]() noexcept {
    return launch_public(timing_output);
  };
  const auto launch_candidate_timing = [&]() noexcept {
    return launch_candidate(timing_output);
  };
  const auto benchmark_fixture = [&](const std::string& fixture_name,
                                     const bool require_strict_rounds) {
    Timing timing;
    bool timing_ready = true;
    for (int pair = 0; pair < kWarmupPairs && timing_ready; ++pair) {
      timing_ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_public_timing()),
          fixture_name + " public warmup");
      timing_ready = test.cuda_ok(
                         static_cast<cudaError_t>(
                             launch_candidate_timing()),
                         fixture_name + " candidate warmup") &&
                     timing_ready;
    }
    timing_ready = test.cuda_ok(cudaStreamSynchronize(stream),
                                fixture_name + " warmup synchronize") &&
                   timing_ready;
    std::array<float, 2U * kRounds> public_passes{};
    std::array<float, 2U * kRounds> candidate_passes{};
    std::array<float, kRounds> speedups{};
    std::array<float, kRounds> deltas{};
    bool every_round_passed = timing_ready;
    for (int round = 0; round < kRounds && timing_ready; ++round) {
      const bool public_first = (round & 1) == 0;
      const std::string round_label =
          fixture_name + " round=" + std::to_string(round + 1);
      const auto measure = [&](const auto& launch,
                               const std::string& pass) {
        return measure_small_m_tile(test, stream, launch,
                                    kMeasuredLaunches,
                                    round_label + " " + pass);
      };
      float public1 = 0.0F;
      float public2 = 0.0F;
      float candidate1 = 0.0F;
      float candidate2 = 0.0F;
      if (public_first) {
        public1 = measure(launch_public_timing, "B1");
        candidate1 = measure(launch_candidate_timing, "C1");
        candidate2 = measure(launch_candidate_timing, "C2");
        public2 = measure(launch_public_timing, "B2");
      } else {
        candidate1 = measure(launch_candidate_timing, "C1");
        public1 = measure(launch_public_timing, "B1");
        public2 = measure(launch_public_timing, "B2");
        candidate2 = measure(launch_candidate_timing, "C2");
      }
      const float paired_public = 0.5F * (public1 + public2);
      const float paired_candidate = 0.5F * (candidate1 + candidate2);
      const float speedup = paired_public / paired_candidate;
      const float delta = paired_public - paired_candidate;
      const bool finite =
          std::isfinite(public1) && std::isfinite(public2) &&
          std::isfinite(candidate1) && std::isfinite(candidate2) &&
          public1 > 0.0F && public2 > 0.0F && candidate1 > 0.0F &&
          candidate2 > 0.0F;
      const bool round_gate =
          finite && (require_strict_rounds ? speedup > 1.0F
                                           : speedup >= 1.0F);
      every_round_passed = every_round_passed && round_gate;
      timing_ready = timing_ready && finite;
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      public_passes[pass] = public1;
      public_passes[pass + 1U] = public2;
      candidate_passes[pass] = candidate1;
      candidate_passes[pass + 1U] = candidate2;
      speedups[static_cast<std::size_t>(round)] = speedup;
      deltas[static_cast<std::size_t>(round)] = delta;
      std::cout << "PERF_FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_ROUND:"
                << " fixture=" << fixture_name
                << " round=" << round + 1
                << " order="
                << (public_first ? "B-C-C-B" : "C-B-B-C")
                << " launches_per_pass=" << kMeasuredLaunches
                << " public1_ms=" << public1
                << " candidate1_ms=" << candidate1
                << " candidate2_ms=" << candidate2
                << " public2_ms=" << public2
                << " paired_speedup=" << speedup
                << " paired_delta_ms=" << delta
                << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
    }
    timing.ready = timing_ready;
    timing.every_round_passed = every_round_passed;
    if (timing_ready) {
      timing.public_median_ms =
          median_fp8_kv_pair_timing(public_passes);
      timing.candidate_median_ms =
          median_fp8_kv_pair_timing(candidate_passes);
      timing.paired_median_speedup =
          median_fp8_kv_pair_timing(speedups);
      timing.paired_median_delta_ms =
          median_fp8_kv_pair_timing(deltas);
      timing.projected_64_layer_delta_ms =
          static_cast<double>(timing.paired_median_delta_ms) * 64.0;
    }
    return timing;
  };

  const char* const actual_checkpoint =
      std::getenv("Q3X_FP8_M1_O_PROJ_ACTUAL_CHECKPOINT_FILE");
  const bool actual_source_set =
      actual_checkpoint != nullptr && actual_checkpoint[0] != '\0';
  test.expect(actual_source_set,
              std::string(kLabel) + " requires actual checkpoint shard");
  if (!actual_source_set) {
    return;
  }
  std::ifstream input(actual_checkpoint, std::ios::binary);
  input.seekg(0, std::ios::end);
  const std::streamoff file_size = input.tellg();
  const bool actual_range = input.is_open() && file_size >= 0 &&
      kActualPayloadOffset <= static_cast<std::uint64_t>(file_size) &&
      kWeightBytes <=
          static_cast<std::uint64_t>(file_size) - kActualPayloadOffset;
  test.expect(actual_range,
              std::string(kLabel) + " actual payload range is valid");
  if (!actual_range) {
    return;
  }
  input.seekg(static_cast<std::streamoff>(kActualPayloadOffset),
              std::ios::beg);
  input.read(reinterpret_cast<char*>(host_weights.data()),
             static_cast<std::streamsize>(host_weights.size()));
  const bool read_complete =
      input.gcount() == static_cast<std::streamsize>(host_weights.size());
  const std::string actual_sha256 =
      q3x::core::sha256(std::string_view(
          reinterpret_cast<const char*>(host_weights.data()),
          host_weights.size()))
          .hex();
  const bool actual_identity_gate =
      read_complete && actual_sha256 == kActualPayloadSha256;
  test.expect(actual_identity_gate,
              std::string(kLabel) + " matches actual payload hash");
  std::cout << "FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_ACTUAL_FIXTURE:"
            << " checkpoint_path=" << actual_checkpoint
            << " payload_offset=" << kActualPayloadOffset
            << " payload_bytes=" << host_weights.size()
            << " sha256=" << actual_sha256
            << " expected_sha256=" << kActualPayloadSha256
            << " gate=" << (actual_identity_gate ? "PASS" : "FAIL")
            << '\n';
  if (!actual_identity_gate ||
      !upload_fixture("actual_checkpoint", true)) {
    return;
  }
  const bool actual_bitwise_gate = run_bitwise("actual_checkpoint");
  const Timing actual_timing =
      actual_bitwise_gate ? benchmark_fixture("actual_checkpoint", true)
                          : Timing{};
  constexpr double kRequiredActualSpeedup = 1.02;
  constexpr double kRequiredProjectedDeltaMs = 0.30;
  constexpr double kRequiredThreeProcessMedianDeltaMs = 0.40;
  const bool actual_gate =
      actual_sidecar_identity_gate && actual_bitwise_gate &&
      actual_timing.ready && actual_timing.every_round_passed &&
      actual_timing.paired_median_speedup >= kRequiredActualSpeedup &&
      actual_timing.projected_64_layer_delta_ms >=
          kRequiredProjectedDeltaMs;
  test.expect(actual_gate,
              std::string(kLabel) + " clears actual performance gate");
  std::cout << "PERF_FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_ACTUAL:"
            << " public_median_ms=" << actual_timing.public_median_ms
            << " candidate_median_ms="
            << actual_timing.candidate_median_ms
            << " paired_median_speedup="
            << actual_timing.paired_median_speedup
            << " paired_median_delta_ms="
            << actual_timing.paired_median_delta_ms
            << " projected_64_layer_delta_ms="
            << actual_timing.projected_64_layer_delta_ms
            << " required_speedup=" << kRequiredActualSpeedup
            << " required_projected_delta_ms="
            << kRequiredProjectedDeltaMs
            << " required_three_process_median_delta_ms="
            << kRequiredThreeProcessMedianDeltaMs
            << " gate=" << (actual_gate ? "PASS" : "FAIL") << '\n';
  if (!actual_gate) {
    std::cout
        << "PERF_FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_STOP_LOSS:"
        << " reason=actual_first_process_failed"
        << " stress=NOT_RUN gate=FAIL\n";
    return;
  }

  fill_fp8_m2_code_distribution(host_weights, kRows, kColumns,
                                Fp8M2CodeDistribution::kSameBankStress);
  if (!upload_fixture("same_bank_stress", false)) {
    return;
  }
  const bool stress_bitwise_gate = run_bitwise("same_bank_stress");
  const Timing stress_timing =
      stress_bitwise_gate
          ? benchmark_fixture("same_bank_stress", false)
          : Timing{};
  const bool stress_gate =
      stress_bitwise_gate && stress_timing.ready &&
      stress_timing.every_round_passed &&
      stress_timing.paired_median_speedup >= 1.0F;
  const bool selected = resource_gate && actual_gate && stress_gate;
  test.expect(selected,
              std::string(kLabel) + " clears single-process selection gate");
  std::cout << "PERF_FP8_M1_O_PROJ_CTA512_SHARED_ACTIVATION_SELECTED:"
            << " baseline=public_aosoa4_1024x256"
            << " candidate=test_only_cta512_shared_activation_640x512"
            << " worker_topology=two_independent_256_thread_workers"
            << " actual_projected_64_layer_delta_ms="
            << actual_timing.projected_64_layer_delta_ms
            << " stress_paired_median_speedup="
            << stress_timing.paired_median_speedup
            << " three_process_gate=pending_external_aggregation"
            << " gate=" << (selected ? "PASS" : "FAIL") << '\n';
}

void run_optional_fp8_m1_row_quad_aosoa4_preswizzled_performance(
    TestContext& test, cudaStream_t stream) {
  if (!fp8_m1_row_quad_aosoa4_preswizzled_performance_enabled()) {
    std::cout
        << "SKIP: FP8 M1 exact output-projection AoSoA4/preswizzled "
           "performance segment; set "
           "Q3X_RUN_SM87_FP8_M1_ROW_QUAD_AOSOA4_PRESWIZZLED_PERF=1 to "
           "enable\n";
    return;
  }

  constexpr std::size_t kRows = 5'120U;
  constexpr std::size_t kColumns = 6'144U;
  constexpr std::size_t kWeightElements = kRows * kColumns;
  constexpr std::size_t kInputGuardBytes = 64U;
  constexpr std::size_t kActivationGuardElements = 16U;
  constexpr std::size_t kOutputGuardElements = 32U;
  constexpr std::size_t kProductionGridCap = 1'280U;
  constexpr std::size_t kCandidateGridCap = 1'024U;
  constexpr std::uint8_t kWeightGuard = 0xa5U;
  constexpr std::uint8_t kSidecarGuard = 0xd3U;
  constexpr std::uint16_t kActivationGuard = 0x7fc1U;
  constexpr std::uint16_t kOutputCanary = 0x5aa5U;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 64;
  constexpr int kMeasurementRounds = 5;
  constexpr std::size_t kTimedPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  constexpr std::uint64_t kActualPayloadOffset = 3'569'011'232ULL;
  constexpr const char* kActualPayloadSha256 =
      "e49a9f770a84cfcf7c2eb60f041aa7f1af8b84f5ab6323d3b8a9151588ff2bb9";
  const std::string label =
      "FP8 M1 output projection exact 5120x6144 AoSoA4 preswizzled";

  Fp8M1Aosoa4PreswizzledResources resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_row_quad_aosoa4_preswizzled_resources_test_cuda(
              &resources.registers_per_thread,
              &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)),
      label + " query candidate resources");
  if (!ready) {
    return;
  }
  const bool resource_gate =
      resources.registers_per_thread > 0 &&
      resources.registers_per_thread <= 64 &&
      resources.static_shared_bytes <= 1'152U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block == 256 &&
      resources.active_blocks_per_sm >= 4;
  std::cout << "FP8_M1_AOSOA4_PRESWIZZLED_RESOURCES:"
            << " registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " maximum_threads_per_block="
            << resources.maximum_threads_per_block
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " maximum_registers_per_thread=64"
            << " maximum_static_shared_bytes=1152"
            << " require_zero_local_bytes=true"
            << " minimum_active_blocks_per_sm=4"
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  test.expect(resource_gate, label + " clears the frozen resource gate");
  test.expect(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_fp8_w8a16_m1_row_quad_aosoa4_preswizzled_resources_test_cuda(
              nullptr, &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)) == cudaErrorInvalidValue,
      label + " resource query rejects a null destination");

  std::vector<std::uint16_t> host_activation(kColumns);
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 29U + (column >> 3U) * 7U + 11U) % 127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 512.0F);
  }
  std::vector<std::uint16_t> host_activation_storage(
      kActivationGuardElements + kColumns + kActivationGuardElements,
      kActivationGuard);
  std::copy(host_activation.begin(), host_activation.end(),
            host_activation_storage.begin() + kActivationGuardElements);
  const std::vector<std::uint16_t> host_output_initial(
      kOutputGuardElements + kRows + kOutputGuardElements, kOutputCanary);

  DeviceBuffer<std::uint8_t> weight_storage;
  DeviceBuffer<std::uint8_t> sidecar_storage;
  DeviceBuffer<std::uint8_t> production_pack_sidecar_storage;
  DeviceBuffer<std::uint16_t> activation_storage;
  DeviceBuffer<std::uint16_t> baseline_output_storage;
  DeviceBuffer<std::uint16_t> candidate_output_storage;
  DeviceBuffer<std::uint16_t> replay_output_storage;
  ready = test.cuda_ok(
      weight_storage.allocate(kInputGuardBytes + kWeightElements +
                              kInputGuardBytes),
      label + " allocate guarded natural-order weights");
  ready = ready && test.cuda_ok(
                       sidecar_storage.allocate(
                           kInputGuardBytes + kWeightElements +
                           kInputGuardBytes),
                       label + " allocate guarded AoSoA4 sidecar");
  ready = ready && test.cuda_ok(
                       production_pack_sidecar_storage.allocate(
                           kInputGuardBytes + kWeightElements +
                           kInputGuardBytes),
                       label + " allocate guarded production-pack sidecar");
  ready = ready && test.cuda_ok(
                       activation_storage.allocate(
                           host_activation_storage.size()),
                       label + " allocate guarded activation");
  ready = ready && test.cuda_ok(
                       baseline_output_storage.allocate(
                           host_output_initial.size()),
                       label + " allocate guarded baseline output");
  ready = ready && test.cuda_ok(
                       candidate_output_storage.allocate(
                           host_output_initial.size()),
                       label + " allocate guarded candidate output");
  ready = ready && test.cuda_ok(
                       replay_output_storage.allocate(
                           host_output_initial.size()),
                       label + " allocate guarded replay output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation_storage.get(),
                           host_activation_storage.data(),
                           host_activation_storage.size() *
                               sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize guarded activation");
  if (!ready) {
    return;
  }

  const std::uint8_t* const weights =
      weight_storage.get() + kInputGuardBytes;
  const std::uint8_t* const sidecar =
      sidecar_storage.get() + kInputGuardBytes;
  std::uint8_t* const production_pack_sidecar =
      production_pack_sidecar_storage.get() + kInputGuardBytes;
  const std::uint16_t* const activation =
      activation_storage.get() + kActivationGuardElements;
  std::uint16_t* const baseline_output =
      baseline_output_storage.get() + kOutputGuardElements;
  std::uint16_t* const candidate_output =
      candidate_output_storage.get() + kOutputGuardElements;
  std::uint16_t* const replay_output =
      replay_output_storage.get() + kOutputGuardElements;

  const char* const actual_checkpoint_value =
      std::getenv("Q3X_FP8_M1_O_PROJ_ACTUAL_CHECKPOINT_FILE");
  const bool actual_checkpoint_set =
      actual_checkpoint_value != nullptr && actual_checkpoint_value[0] != '\0';
  if (!actual_checkpoint_set) {
    std::cout
        << "SKIP: FP8 M1 AoSoA4 authoritative actual-checkpoint cell; set "
           "Q3X_FP8_M1_O_PROJ_ACTUAL_CHECKPOINT_FILE to the safetensors "
           "shard. The deterministic stress cell will still run.\n";
  }

  struct Fixture {
    const char* name;
    bool actual_checkpoint;
    float minimum_median_speedup;
    bool require_every_round_nonregression;
  };
  constexpr std::array<Fixture, 2U> kFixtures{{
      {"actual_checkpoint", true, 1.03F, true},
      {"same_bank_stress", false, 1.00F, false},
  }};
  bool every_executed_fixture_passed = resource_gate;
  bool actual_fixture_executed = false;
  std::vector<std::uint8_t> host_weights(kWeightElements);
  std::vector<std::uint8_t> host_weight_storage;
  std::vector<std::uint8_t> host_sidecar_storage;
  std::vector<std::uint16_t> baseline(kRows);
  std::vector<std::uint16_t> candidate(kRows);
  std::vector<std::uint16_t> replay(kRows);

  for (const Fixture& fixture : kFixtures) {
    if (fixture.actual_checkpoint && !actual_checkpoint_set) {
      continue;
    }
    actual_fixture_executed =
        actual_fixture_executed || fixture.actual_checkpoint;
    const std::string fixture_label = label + " " + fixture.name;

    if (fixture.actual_checkpoint) {
      std::ifstream input(actual_checkpoint_value, std::ios::binary);
      const bool opened = input.is_open();
      test.expect(opened, fixture_label + " opens the safetensors shard");
      if (!opened) {
        every_executed_fixture_passed = false;
        continue;
      }
      input.seekg(static_cast<std::streamoff>(kActualPayloadOffset),
                  std::ios::beg);
      const bool seeked = input.good();
      test.expect(seeked, fixture_label + " seeks to the pinned payload");
      if (seeked) {
        input.read(reinterpret_cast<char*>(host_weights.data()),
                   static_cast<std::streamsize>(host_weights.size()));
      }
      const bool read_complete =
          seeked && input.gcount() ==
                        static_cast<std::streamsize>(host_weights.size());
      test.expect(read_complete,
                  fixture_label + " reads all 31,457,280 payload bytes");
      if (!read_complete) {
        every_executed_fixture_passed = false;
        continue;
      }
    } else {
      fill_fp8_m2_code_distribution(
          host_weights, kRows, kColumns,
          Fp8M2CodeDistribution::kSameBankStress);
    }

    const std::string payload_sha256 =
        q3x::core::sha256(std::string_view(
            reinterpret_cast<const char*>(host_weights.data()),
            host_weights.size()))
            .hex();
    const bool identity_gate =
        !fixture.actual_checkpoint || payload_sha256 == kActualPayloadSha256;
    std::cout << "FP8_M1_AOSOA4_PRESWIZZLED_FIXTURE: distribution="
              << fixture.name
              << " source="
              << (fixture.actual_checkpoint ? actual_checkpoint_value
                                            : "deterministic_generator")
              << " absolute_payload_offset="
              << (fixture.actual_checkpoint ? kActualPayloadOffset : 0U)
              << " payload_bytes=" << host_weights.size()
              << " sha256=" << payload_sha256
              << " expected_sha256="
              << (fixture.actual_checkpoint ? kActualPayloadSha256
                                            : "not_applicable")
              << " identity_gate=" << (identity_gate ? "PASS" : "FAIL")
              << '\n';
    test.expect(identity_gate, fixture_label + " matches the pinned SHA256");
    if (!identity_gate) {
      every_executed_fixture_passed = false;
      continue;
    }

    host_weight_storage.assign(
        kInputGuardBytes + kWeightElements + kInputGuardBytes,
        kWeightGuard);
    std::copy(host_weights.begin(), host_weights.end(),
              host_weight_storage.begin() + kInputGuardBytes);
    const bool sidecar_semantics =
        build_fp8_m1_aosoa4_preswizzled_sidecar(
            host_weights, kRows, kColumns, kInputGuardBytes, kSidecarGuard,
            host_sidecar_storage);
    test.expect(sidecar_semantics,
                fixture_label +
                    " encodes each byte as slot=code^(code>>5)");

    ready = test.cuda_ok(
        cudaMemcpyAsync(weight_storage.get(), host_weight_storage.data(),
                        host_weight_storage.size(), cudaMemcpyHostToDevice,
                        stream),
        fixture_label + " upload guarded natural-order weights");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             sidecar_storage.get(),
                             host_sidecar_storage.data(),
                             host_sidecar_storage.size(),
                             cudaMemcpyHostToDevice, stream),
                         fixture_label + " upload guarded AoSoA4 sidecar");
    for (auto* const output_storage :
         {&baseline_output_storage, &candidate_output_storage,
          &replay_output_storage}) {
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               output_storage->get(),
                               host_output_initial.data(),
                               host_output_initial.size() *
                                   sizeof(std::uint16_t),
                               cudaMemcpyHostToDevice, stream),
                           fixture_label + " initialize guarded output");
    }
    if (!ready) {
      return;
    }

    const auto launch_baseline = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_m1_row_quad_swizzled_codebook_grid_cap_test_cuda(
              weights, kWeightScale, activation, kRows, kColumns,
              baseline_output, kProductionGridCap,
              static_cast<void*>(stream));
    };
    const auto launch_candidate = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_m1_row_quad_aosoa4_preswizzled_test_cuda(
              sidecar, kWeightScale, activation, kRows, kColumns,
              candidate_output, static_cast<void*>(stream));
    };
    const auto launch_replay = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_m1_row_quad_aosoa4_preswizzled_test_cuda(
              sidecar, kWeightScale, activation, kRows, kColumns,
              replay_output, static_cast<void*>(stream));
    };

    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         fixture_label + " launch production cap1280");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         fixture_label + " launch candidate cap1024");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_replay()),
                         fixture_label + " deterministic replay cap1024");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output,
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " copy baseline output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output,
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " copy candidate output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             replay.data(), replay_output,
                             replay.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " copy replay output");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         fixture_label + " correctness synchronize");
    if (!ready) {
      return;
    }

    std::size_t candidate_mismatches = 0U;
    std::size_t replay_mismatches = 0U;
    bool output_finite = true;
    for (std::size_t row = 0U; row < kRows; ++row) {
      candidate_mismatches += baseline[row] != candidate[row] ? 1U : 0U;
      replay_mismatches += candidate[row] != replay[row] ? 1U : 0U;
      output_finite = output_finite &&
                      std::isfinite(decode_bf16(baseline[row])) &&
                      std::isfinite(decode_bf16(candidate[row])) &&
                      std::isfinite(decode_bf16(replay[row]));
    }
    const bool bitwise_gate =
        candidate_mismatches == 0U && replay_mismatches == 0U &&
        output_finite;
    std::cout << "FP8_M1_AOSOA4_PRESWIZZLED_DIFF: distribution="
              << fixture.name
              << " baseline=production_swizzled_row_quad_cap1280"
              << " candidate=aosoa4_preswizzled_cap1024"
              << " candidate_mismatches=" << candidate_mismatches << '/'
              << kRows << " replay_mismatches=" << replay_mismatches << '/'
              << kRows
              << " output_finite=" << (output_finite ? "true" : "false")
              << " gate=" << (bitwise_gate ? "PASS" : "FAIL") << '\n';
    test.expect(bitwise_gate,
                fixture_label +
                    " is bit-exact, finite, and deterministic on replay");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           fixture_label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           fixture_label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         fixture_label + " warmup synchronize");
    if (!ready) {
      return;
    }

    std::array<float, kTimedPasses> baseline_passes{};
    std::array<float, kTimedPasses> candidate_passes{};
    std::array<float, static_cast<std::size_t>(kMeasurementRounds)>
        paired_round_speedups{};
    bool timings_finite = true;
    bool every_round_nonregression = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          fixture_label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 2");
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      baseline_passes[pass] = baseline_first;
      baseline_passes[pass + 1U] = baseline_second;
      candidate_passes[pass] = candidate_first;
      candidate_passes[pass + 1U] = candidate_second;
      const bool round_finite =
          std::isfinite(baseline_first) && baseline_first > 0.0F &&
          std::isfinite(candidate_first) && candidate_first > 0.0F &&
          std::isfinite(candidate_second) && candidate_second > 0.0F &&
          std::isfinite(baseline_second) && baseline_second > 0.0F;
      timings_finite = timings_finite && round_finite;
      const float round_speedup =
          round_finite
              ? (baseline_first + baseline_second) /
                    (candidate_first + candidate_second)
              : std::numeric_limits<float>::quiet_NaN();
      paired_round_speedups[static_cast<std::size_t>(round)] =
          round_speedup;
      const bool round_nonregression =
          round_finite && round_speedup >= 1.00F;
      every_round_nonregression =
          every_round_nonregression && round_nonregression;
      std::cout << "PERF_FP8_M1_AOSOA4_PRESWIZZLED_ROUND: distribution="
                << fixture.name << " round=" << round + 1
                << " order=B-C-C-B"
                << " warmup_launches_per_route=" << kWarmupIterations
                << " measured_launches_per_pass=" << kMeasuredIterations
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second
                << " paired_speedup=" << round_speedup
                << " nonregression="
                << (round_nonregression ? "PASS" : "FAIL") << '\n';
    }

    const float baseline_median =
        timings_finite
            ? median_fp8_m1_aosoa4_timing(baseline_passes)
            : std::numeric_limits<float>::quiet_NaN();
    const float candidate_median =
        timings_finite
            ? median_fp8_m1_aosoa4_timing(candidate_passes)
            : std::numeric_limits<float>::quiet_NaN();
    const float pass_median_ratio = baseline_median / candidate_median;
    const float paired_median_speedup =
        timings_finite
            ? median_fp8_m1_aosoa4_timing(paired_round_speedups)
            : std::numeric_limits<float>::quiet_NaN();
    const bool timing_gate =
        timings_finite && std::isfinite(baseline_median) &&
        std::isfinite(candidate_median) &&
        std::isfinite(pass_median_ratio) &&
        std::isfinite(paired_median_speedup) &&
        baseline_median > 0.0F && candidate_median > 0.0F &&
        paired_median_speedup >= fixture.minimum_median_speedup &&
        (!fixture.require_every_round_nonregression ||
         every_round_nonregression);

    std::vector<std::uint8_t> observed_weight_storage(
        host_weight_storage.size());
    std::vector<std::uint8_t> observed_sidecar_storage(
        host_sidecar_storage.size());
    std::vector<std::uint16_t> observed_activation_storage(
        host_activation_storage.size());
    std::vector<std::uint16_t> observed_baseline_storage(
        host_output_initial.size());
    std::vector<std::uint16_t> observed_candidate_storage(
        host_output_initial.size());
    std::vector<std::uint16_t> observed_replay_storage(
        host_output_initial.size());
    ready = test.cuda_ok(
        cudaMemcpyAsync(observed_weight_storage.data(), weight_storage.get(),
                        observed_weight_storage.size(),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " verify natural-order input");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_sidecar_storage.data(),
                             sidecar_storage.get(),
                             observed_sidecar_storage.size(),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " verify AoSoA4 sidecar");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_activation_storage.data(),
                             activation_storage.get(),
                             observed_activation_storage.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " verify activation input");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_baseline_storage.data(),
                             baseline_output_storage.get(),
                             observed_baseline_storage.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " verify baseline canaries");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_candidate_storage.data(),
                             candidate_output_storage.get(),
                             observed_candidate_storage.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " verify candidate canaries");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_replay_storage.data(),
                             replay_output_storage.get(),
                             observed_replay_storage.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label + " verify replay canaries");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         fixture_label + " guard verification synchronize");
    if (!ready) {
      return;
    }

    const auto output_guards_intact = [&](const auto& observed) {
      return std::all_of(
                 observed.begin(),
                 observed.begin() + kOutputGuardElements,
                 [](const std::uint16_t value) {
                   return value == kOutputCanary;
                 }) &&
             std::all_of(
                 observed.end() - kOutputGuardElements, observed.end(),
                 [](const std::uint16_t value) {
                   return value == kOutputCanary;
                 });
    };
    const bool weight_input_preserved =
        observed_weight_storage == host_weight_storage;
    const bool sidecar_preserved =
        observed_sidecar_storage == host_sidecar_storage;
    const bool activation_preserved =
        observed_activation_storage == host_activation_storage;
    const bool baseline_guards =
        output_guards_intact(observed_baseline_storage);
    const bool candidate_guards =
        output_guards_intact(observed_candidate_storage);
    const bool replay_guards = output_guards_intact(observed_replay_storage);
    const bool preservation_gate =
        weight_input_preserved && sidecar_preserved && activation_preserved &&
        baseline_guards && candidate_guards && replay_guards;
    std::cout << "FP8_M1_AOSOA4_PRESWIZZLED_GUARDS: distribution="
              << fixture.name
              << " natural_weight_input_preserved="
              << (weight_input_preserved ? "true" : "false")
              << " activation_input_preserved="
              << (activation_preserved ? "true" : "false")
              << " sidecar_payload_and_guards_preserved="
              << (sidecar_preserved ? "true" : "false")
              << " baseline_output_guards="
              << (baseline_guards ? "PASS" : "FAIL")
              << " candidate_output_guards="
              << (candidate_guards ? "PASS" : "FAIL")
              << " replay_output_guards="
              << (replay_guards ? "PASS" : "FAIL")
              << " gate=" << (preservation_gate ? "PASS" : "FAIL")
              << '\n';
    test.expect(preservation_gate,
                fixture_label + " preserves every input and canary guard");

    // Keep production pack validation outside the correctness/performance
    // launch sequence above. Seed every payload byte with the complement of
    // its CPU-oracle value so a missed GPU write cannot compare equal by
    // accident; the guards retain their oracle values to detect overrun.
    observed_sidecar_storage = host_sidecar_storage;
    std::transform(
        observed_sidecar_storage.begin() + kInputGuardBytes,
        observed_sidecar_storage.end() - kInputGuardBytes,
        observed_sidecar_storage.begin() + kInputGuardBytes,
        [](const std::uint8_t value) {
          return static_cast<std::uint8_t>(value ^ 0xffU);
        });
    ready = test.cuda_ok(
        cudaMemcpyAsync(production_pack_sidecar_storage.get(),
                        observed_sidecar_storage.data(),
                        observed_sidecar_storage.size(),
                        cudaMemcpyHostToDevice, stream),
        fixture_label + " seed guarded production-pack sidecar");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(q3x::kernels::
                             launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_pack_cuda(
                                 weights, production_pack_sidecar, kRows,
                                 kColumns, static_cast<void*>(stream))),
                         fixture_label + " launch production GPU pack");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_sidecar_storage.data(),
                             production_pack_sidecar_storage.get(),
                             observed_sidecar_storage.size(),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label +
                             " copy complete production-pack sidecar");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             observed_weight_storage.data(),
                             weight_storage.get(),
                             observed_weight_storage.size(),
                             cudaMemcpyDeviceToHost, stream),
                         fixture_label +
                             " copy canonical weights after production pack");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         fixture_label +
                             " production GPU pack verification synchronize");
    if (!ready) {
      return;
    }
    const bool production_pack_matches_cpu_oracle =
        observed_sidecar_storage == host_sidecar_storage;
    const bool production_pack_preserves_canonical =
        observed_weight_storage == host_weight_storage;
    const bool production_pack_gate =
        production_pack_matches_cpu_oracle &&
        production_pack_preserves_canonical;
    std::cout << "FP8_M1_AOSOA4_PRODUCTION_PACK: distribution="
              << fixture.name << " compared_payload_bytes="
              << kWeightElements
              << " cpu_oracle_payload_and_guards="
              << (production_pack_matches_cpu_oracle ? "PASS" : "FAIL")
              << " canonical_input_preserved="
              << (production_pack_preserves_canonical ? "true" : "false")
              << " gate=" << (production_pack_gate ? "PASS" : "FAIL")
              << '\n';
    test.expect(production_pack_gate,
                fixture_label +
                    " production GPU pack matches the complete 30 MiB CPU "
                    "oracle and preserves canonical weights");

    const bool fixture_gate = sidecar_semantics && bitwise_gate &&
                              preservation_gate && production_pack_gate &&
                              timing_gate;
    every_executed_fixture_passed =
        every_executed_fixture_passed && fixture_gate;
    std::cout << "PERF_FP8_M1_AOSOA4_PRESWIZZLED_MEDIAN: distribution="
              << fixture.name
              << " baseline=production_swizzled_row_quad_cap1280"
              << " candidate=aosoa4_preswizzled_cap1024"
              << " rounds=" << kMeasurementRounds
              << " order=B-C-C-B"
              << " measured_launches_per_pass=" << kMeasuredIterations
              << " baseline_median_ms=" << baseline_median
              << " candidate_median_ms=" << candidate_median
              << " pass_median_ratio=" << pass_median_ratio
              << " paired_median_speedup=" << paired_median_speedup
              << " required_median_speedup="
              << fixture.minimum_median_speedup
              << " require_every_round_nonregression="
              << (fixture.require_every_round_nonregression ? "true"
                                                            : "false")
              << " every_round_nonregression="
              << (every_round_nonregression ? "PASS" : "FAIL")
              << " bitwise=" << (bitwise_gate ? "PASS" : "FAIL")
              << " guards_inputs="
              << (preservation_gate ? "PASS" : "FAIL")
              << " timing_finite=" << (timings_finite ? "true" : "false")
              << " hard_gate=" << (fixture_gate ? "PASS" : "FAIL")
              << '\n';
    test.expect(fixture_gate,
                fixture_label + " clears the frozen formal gate");
  }

  struct InvalidPackCase {
    const char* name;
    const std::uint8_t* canonical_weights;
    std::uint8_t* sidecar_weights;
    std::size_t rows;
    std::size_t columns;
  };
  const std::array<InvalidPackCase, 7U> invalid_pack_cases{{
      {"null_canonical", nullptr, production_pack_sidecar, kRows,
       kColumns},
      {"null_sidecar", weights, nullptr, kRows, kColumns},
      {"wrong_rows", weights, production_pack_sidecar, kRows - 1U,
       kColumns},
      {"wrong_columns", weights, production_pack_sidecar, kRows,
       kColumns - 1U},
      {"canonical_not_4_byte_aligned", weights + 1U,
       production_pack_sidecar, kRows, kColumns},
      {"sidecar_not_16_byte_aligned", weights,
       production_pack_sidecar + 1U, kRows, kColumns},
      {"complete_span_overlap", weights,
       const_cast<std::uint8_t*>(weights), kRows, kColumns},
  }};
  const auto invalid_pack_does_not_enqueue =
      [&](const InvalidPackCase& invalid_case) {
        const std::string case_label =
            label + " production pack invalid " + invalid_case.name;
        cudaGraph_t graph = nullptr;
        bool capture_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream,
                                   cudaStreamCaptureModeThreadLocal),
            case_label + " begin capture");
        cudaError_t launch_status = cudaErrorUnknown;
        if (capture_ready) {
          launch_status = static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_pack_cuda(
                  invalid_case.canonical_weights,
                  invalid_case.sidecar_weights, invalid_case.rows,
                  invalid_case.columns, static_cast<void*>(stream)));
          capture_ready =
              test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           case_label + " end capture") &&
              capture_ready;
        }
        std::size_t node_count = 0U;
        if (capture_ready && graph != nullptr) {
          capture_ready =
              test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                           case_label + " query nodes") &&
              capture_ready;
        } else if (capture_ready) {
          test.expect(false, case_label + " produced a null graph");
          capture_ready = false;
        }
        if (graph != nullptr) {
          capture_ready =
              test.cuda_ok(cudaGraphDestroy(graph),
                           case_label + " destroy graph") &&
              capture_ready;
        }
        const bool case_gate =
            capture_ready && launch_status == cudaErrorInvalidValue &&
            node_count == 0U;
        test.expect(case_gate,
                    case_label +
                        " returns cudaErrorInvalidValue before enqueue");
        return case_gate;
      };
  bool invalid_pack_gate = true;
  for (const InvalidPackCase& invalid_case : invalid_pack_cases) {
    invalid_pack_gate =
        invalid_pack_does_not_enqueue(invalid_case) && invalid_pack_gate;
  }
  every_executed_fixture_passed =
      every_executed_fixture_passed && invalid_pack_gate;
  std::cout << "FP8_M1_AOSOA4_PRODUCTION_PACK_INVALID: cases="
            << invalid_pack_cases.size()
            << " all_cuda_error_invalid_value_and_zero_nodes="
            << (invalid_pack_gate ? "PASS" : "FAIL") << '\n';

  struct InvalidGemvCase {
    const char* name;
    const std::uint8_t* sidecar_weights;
    const std::uint16_t* activation;
    std::size_t rows;
    std::size_t columns;
    std::uint16_t* output;
  };
  const std::array<InvalidGemvCase, 11U> invalid_gemv_cases{{
      {"null_sidecar", nullptr, activation, kRows, kColumns,
       candidate_output},
      {"null_activation", sidecar, nullptr, kRows, kColumns,
       candidate_output},
      {"null_output", sidecar, activation, kRows, kColumns, nullptr},
      {"wrong_rows", sidecar, activation, kRows - 1U, kColumns,
       candidate_output},
      {"wrong_columns", sidecar, activation, kRows, kColumns - 1U,
       candidate_output},
      {"sidecar_not_16_byte_aligned", sidecar + 1U, activation, kRows,
       kColumns, candidate_output},
      {"activation_not_8_byte_aligned", sidecar, activation + 1U, kRows,
       kColumns, candidate_output},
      {"output_not_2_byte_aligned", sidecar, activation, kRows, kColumns,
       reinterpret_cast<std::uint16_t*>(
           reinterpret_cast<std::uint8_t*>(candidate_output) + 1U)},
      {"sidecar_activation_complete_span_overlap", sidecar,
       reinterpret_cast<const std::uint16_t*>(sidecar), kRows, kColumns,
       candidate_output},
      {"sidecar_output_complete_span_overlap", sidecar, activation, kRows,
       kColumns, reinterpret_cast<std::uint16_t*>(
                     const_cast<std::uint8_t*>(sidecar))},
      {"activation_output_complete_span_overlap", sidecar, activation, kRows,
       kColumns, const_cast<std::uint16_t*>(activation)},
  }};
  const auto invalid_gemv_does_not_enqueue =
      [&](const InvalidGemvCase& invalid_case) {
        const std::string case_label =
            label + " production GEMV invalid " + invalid_case.name;
        cudaGraph_t graph = nullptr;
        bool capture_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream,
                                   cudaStreamCaptureModeThreadLocal),
            case_label + " begin capture");
        cudaError_t launch_status = cudaErrorUnknown;
        if (capture_ready) {
          launch_status = static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_bf16_cuda(
                  invalid_case.sidecar_weights, kWeightScale,
                  invalid_case.activation, invalid_case.rows,
                  invalid_case.columns, invalid_case.output,
                  static_cast<void*>(stream)));
          capture_ready =
              test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           case_label + " end capture") &&
              capture_ready;
        }
        std::size_t node_count = 0U;
        if (capture_ready && graph != nullptr) {
          capture_ready =
              test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                           case_label + " query nodes") &&
              capture_ready;
        } else if (capture_ready) {
          test.expect(false, case_label + " produced a null graph");
          capture_ready = false;
        }
        if (graph != nullptr) {
          capture_ready =
              test.cuda_ok(cudaGraphDestroy(graph),
                           case_label + " destroy graph") &&
              capture_ready;
        }
        const bool case_gate =
            capture_ready && launch_status == cudaErrorInvalidValue &&
            node_count == 0U;
        test.expect(case_gate,
                    case_label +
                        " returns cudaErrorInvalidValue before enqueue");
        return case_gate;
      };
  bool invalid_gemv_gate = true;
  for (const InvalidGemvCase& invalid_case : invalid_gemv_cases) {
    invalid_gemv_gate =
        invalid_gemv_does_not_enqueue(invalid_case) && invalid_gemv_gate;
  }
  every_executed_fixture_passed =
      every_executed_fixture_passed && invalid_gemv_gate;
  std::cout << "FP8_M1_AOSOA4_PRODUCTION_GEMV_INVALID: cases="
            << invalid_gemv_cases.size()
            << " all_cuda_error_invalid_value_and_zero_nodes="
            << (invalid_gemv_gate ? "PASS" : "FAIL") << '\n';

  std::cout << "PERF_FP8_M1_AOSOA4_PRESWIZZLED_SELECTED:"
            << " shape=5120x6144"
            << " baseline_cap=1280 candidate_cap=" << kCandidateGridCap
            << " actual_checkpoint="
            << (actual_fixture_executed ? "EXECUTED" : "SKIPPED")
            << " stress=EXECUTED"
            << " resource_gate=" << (resource_gate ? "PASS" : "FAIL")
            << " production_pack_invalid_gate="
            << (invalid_pack_gate ? "PASS" : "FAIL")
            << " production_gemv_invalid_gate="
            << (invalid_gemv_gate ? "PASS" : "FAIL")
            << " all_executed_fixtures="
            << (every_executed_fixture_passed ? "PASS" : "FAIL") << '\n';
  test.expect(every_executed_fixture_passed,
              label + " clears every executed formal cell");
}

struct Fp8M1RowPairDistributionMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
};

struct Fp8M1RowPairMeasurement {
  std::array<Fp8M1RowPairDistributionMeasurement, 2U> distributions{};
};

[[nodiscard]] Fp8M1RowPairMeasurement benchmark_fp8_m1_row_pair_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kProductionGridCap = 2'048U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 40;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<Fp8M2CodeDistribution, 2U> kDistributions{{
      Fp8M2CodeDistribution::kCheckpointLike,
      Fp8M2CodeDistribution::kSameBankStress,
  }};

  std::vector<std::uint8_t> host_weights(rows * columns);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered = static_cast<int>((column * 17U + 5U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  if (!ready) {
    return {};
  }

  Fp8M1RowPairMeasurement measurement;
  for (std::size_t distribution_index = 0U;
       distribution_index < kDistributions.size(); ++distribution_index) {
    const Fp8M2CodeDistribution distribution =
        kDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + fp8_m2_code_distribution_name(distribution);
    fill_fp8_m2_code_distribution(host_weights, rows, columns, distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(weights.get(), host_weights.data(),
                        host_weights.size(), cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize weights");
    if (!ready) {
      return measurement;
    }

    const auto launch_baseline = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_gemv_bf16_grid_cap_test_cuda(
              weights.get(), kWeightScale, activation.get(), rows, columns,
              baseline_output.get(), kProductionGridCap,
              static_cast<void*>(stream));
    };
    const auto launch_candidate = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_gemv_bf16_row_pair_test_cuda(
              weights.get(), kWeightScale, activation.get(), rows, columns,
              candidate_output.get(), static_cast<void*>(stream));
    };

    ready = test.cuda_ok(
        static_cast<cudaError_t>(launch_baseline()),
        distribution_label +
            " correctness preserved production cap2048 baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         distribution_label +
                             " correctness direct row-pair");
    std::vector<std::uint16_t> baseline(rows);
    std::vector<std::uint16_t> candidate(rows);
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy baseline output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy direct row-pair output");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " correctness synchronize");
    if (!ready) {
      return measurement;
    }

    std::size_t mismatches = 0U;
    for (std::size_t index = 0U; index < baseline.size(); ++index) {
      mismatches += baseline[index] != candidate[index] ? 1U : 0U;
    }
    Fp8M1RowPairDistributionMeasurement& distribution_measurement =
        measurement.distributions[distribution_index];
    distribution_measurement.bitwise_equal = mismatches == 0U;
    test.expect(distribution_measurement.bitwise_equal,
                distribution_label +
                    " direct row-pair matches every preserved production "
                    "BF16 bit");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           distribution_label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           distribution_label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " warmup synchronize");
    if (!ready) {
      return measurement;
    }

    double baseline_total = 0.0;
    double candidate_total = 0.0;
    bool all_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          distribution_label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 2");
      const bool round_finite =
          std::isfinite(baseline_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(baseline_second);
      all_finite = all_finite && round_finite;
      if (round_finite) {
        baseline_total += baseline_first + baseline_second;
        candidate_total += candidate_first + candidate_second;
      }
      std::cout << "PERF_FP8_M1_ROW_PAIR_ROUND: " << label
                << " distribution="
                << fp8_m2_code_distribution_name(distribution)
                << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }
    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    distribution_measurement.baseline_milliseconds =
        all_finite ? static_cast<float>(baseline_total / kTimedPasses)
                   : std::numeric_limits<float>::quiet_NaN();
    distribution_measurement.candidate_milliseconds =
        all_finite ? static_cast<float>(candidate_total / kTimedPasses)
                   : std::numeric_limits<float>::quiet_NaN();
    const float speedup = distribution_measurement.baseline_milliseconds /
                          distribution_measurement.candidate_milliseconds;
    std::cout << "PERF_FP8_M1_ROW_PAIR: " << label << " distribution="
              << fp8_m2_code_distribution_name(distribution)
              << " preserved_production_cap2048_ms="
              << distribution_measurement.baseline_milliseconds
              << " direct_row_pair_ms="
              << distribution_measurement.candidate_milliseconds
              << " speedup=" << speedup << " bitwise_mismatches="
              << mismatches << '/' << baseline.size() << '\n';
  }
  return measurement;
}

void run_optional_fp8_m1_row_pair_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!fp8_m1_row_pair_performance_enabled()) {
    std::cout << "SKIP: FP8 M1 row-pair performance segment; set "
                 "Q3X_RUN_SM87_FP8_M1_ROW_PAIR_PERF=1 to enable\n";
    return;
  }
  constexpr float kMinimumCheckpointShapeSpeedup = 1.02F;
  constexpr float kMinimumStressShapeSpeedup = 0.99F;
  constexpr float kMinimumCheckpointWeightedSpeedup = 1.03F;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t checkpoint_calls;
    const char* label;
  };
  constexpr std::array<Shape, 6U> kShapes{{
      {10'240U, 5'120U, 48U, "FP8 M1 row-pair QKV 10240x5120"},
      {5'120U, 6'144U, 64U, "FP8 M1 row-pair projection 5120x6144"},
      {6'144U, 5'120U, 48U, "FP8 M1 row-pair projection 6144x5120"},
      {12'288U, 5'120U, 16U, "FP8 M1 row-pair QKV 12288x5120"},
      {1'024U, 5'120U, 32U, "FP8 M1 row-pair small 1024x5120"},
      {5'120U, 5'120U, 0U, "FP8 M1 row-pair square 5120x5120"},
  }};
  constexpr std::array<Fp8M2CodeDistribution, 2U> kDistributions{{
      Fp8M2CodeDistribution::kCheckpointLike,
      Fp8M2CodeDistribution::kSameBankStress,
  }};
  std::array<Fp8M1RowPairMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_fp8_m1_row_pair_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }

  bool all_shape_distributions_pass = true;
  double checkpoint_weighted_baseline = 0.0;
  double checkpoint_weighted_candidate = 0.0;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    for (std::size_t distribution_index = 0U;
         distribution_index < kDistributions.size(); ++distribution_index) {
      const Fp8M1RowPairDistributionMeasurement& measurement =
          measurements[shape_index].distributions[distribution_index];
      const float speedup = measurement.baseline_milliseconds /
                            measurement.candidate_milliseconds;
      const bool finite =
          std::isfinite(measurement.baseline_milliseconds) &&
          std::isfinite(measurement.candidate_milliseconds) &&
          std::isfinite(speedup);
      const float required_speedup =
          kDistributions[distribution_index] ==
                  Fp8M2CodeDistribution::kCheckpointLike
              ? kMinimumCheckpointShapeSpeedup
              : kMinimumStressShapeSpeedup;
      const bool gate = measurement.bitwise_equal && finite &&
                        speedup >= required_speedup;
      all_shape_distributions_pass =
          all_shape_distributions_pass && gate;
      test.expect(
          gate,
          std::string(kShapes[shape_index].label) + " " +
              fp8_m2_code_distribution_name(
                  kDistributions[distribution_index]) +
              " clears the M1 row-pair performance gate");
      std::cout << "PERF_FP8_M1_ROW_PAIR_VALIDATION: "
                << kShapes[shape_index].label << " distribution="
                << fp8_m2_code_distribution_name(
                       kDistributions[distribution_index])
                << " preserved_production_cap2048_ms="
                << measurement.baseline_milliseconds
                << " direct_row_pair_ms="
                << measurement.candidate_milliseconds
                << " speedup=" << speedup
                << " required_speedup=" << required_speedup << " bitwise="
                << (measurement.bitwise_equal ? "true" : "false")
                << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
    }
    const Fp8M1RowPairDistributionMeasurement& checkpoint =
        measurements[shape_index].distributions[0U];
    checkpoint_weighted_baseline +=
        static_cast<double>(kShapes[shape_index].checkpoint_calls) *
        checkpoint.baseline_milliseconds;
    checkpoint_weighted_candidate +=
        static_cast<double>(kShapes[shape_index].checkpoint_calls) *
        checkpoint.candidate_milliseconds;
  }
  const double checkpoint_weighted_speedup =
      checkpoint_weighted_baseline / checkpoint_weighted_candidate;
  const bool aggregate_gate =
      all_shape_distributions_pass &&
      std::isfinite(checkpoint_weighted_speedup) &&
      checkpoint_weighted_speedup >= kMinimumCheckpointWeightedSpeedup;
  std::cout << "PERF_FP8_M1_ROW_PAIR_AGGREGATE: "
            << "checkpoint_weighted_preserved_production_cap2048_ms="
            << checkpoint_weighted_baseline
            << " checkpoint_weighted_direct_row_pair_ms="
            << checkpoint_weighted_candidate
            << " speedup=" << checkpoint_weighted_speedup
            << " required_speedup=" << kMinimumCheckpointWeightedSpeedup
            << " profile_calls=48:64:48:16:32:0 all_shape_distributions="
            << (all_shape_distributions_pass ? "PASS" : "FAIL")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "FP8 M1 row-pair clears every production gate");
}

struct Fp8M8FixedShapeMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
};

[[nodiscard]] Fp8M8FixedShapeMeasurement
benchmark_fp8_m8_fixed_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 8U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};
  std::vector<std::uint8_t> host_weights(rows * columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] =
        kFiniteCodes[(index * 7U + index / columns * 5U + 1U) %
                     kFiniteCodes.size()];
  }
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 13U + token * 17U + 3U) % 127U) - 63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokens * rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokens * rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed finite weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize token-distinct activations");
  if (!ready) {
    return {};
  }

  const auto launch_baseline = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_fp8_w8a16_small_m8_row_pair_test_cuda(
        weights.get(), kWeightScale, activations.get(), rows, columns,
        baseline_output.get(), static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_fp8_w8a16_small_m_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), kTokens, rows, columns,
        candidate_output.get(), static_cast<void*>(stream));
  };

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " correctness generic row-pair baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " correctness fixed-shape candidate");
  std::vector<std::uint16_t> baseline(kTokens * rows);
  std::vector<std::uint16_t> candidate(kTokens * rows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy generic row-pair output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy fixed-shape output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " correctness synchronize");
  if (!ready) {
    return {};
  }
  std::size_t mismatches = 0U;
  for (std::size_t index = 0U; index < baseline.size(); ++index) {
    mismatches += baseline[index] != candidate[index] ? 1U : 0U;
  }
  const bool bitwise_equal = mismatches == 0U;
  std::cout << "FP8_M8_FIXED_SHAPE_DIFF: " << label
            << " candidate_vs_generic_row_pair_bf16=" << mismatches << '/'
            << baseline.size() << '\n';
  test.expect(bitwise_equal,
              label + " fixed shape matches every generic row-pair BF16 bit");

  for (int iteration = 0; iteration < kWarmupIterations && ready;
       ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " baseline warmup");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " candidate warmup");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return {};
  }

  double baseline_total = 0.0;
  double candidate_total = 0.0;
  bool finite = true;
  for (int round = 0; round < kMeasurementRounds; ++round) {
    const std::string round_suffix =
        " round=" + std::to_string(round + 1);
    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 1" + round_suffix);
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 1" + round_suffix);
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 2" + round_suffix);
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 2" + round_suffix);
    const bool round_finite =
        std::isfinite(baseline_first) && std::isfinite(candidate_first) &&
        std::isfinite(candidate_second) && std::isfinite(baseline_second);
    finite = finite && round_finite;
    if (round_finite) {
      baseline_total += baseline_first + baseline_second;
      candidate_total += candidate_first + candidate_second;
    }
    std::cout << "PERF_FP8_M8_FIXED_SHAPE_ROUND: " << label
              << " round=" << round + 1
              << " baseline_pass1_ms=" << baseline_first
              << " candidate_pass1_ms=" << candidate_first
              << " candidate_pass2_ms=" << candidate_second
              << " baseline_pass2_ms=" << baseline_second << '\n';
  }
  if (!finite) {
    return {};
  }
  constexpr double kTimedPasses =
      2.0 * static_cast<double>(kMeasurementRounds);
  const float baseline_average =
      static_cast<float>(baseline_total / kTimedPasses);
  const float candidate_average =
      static_cast<float>(candidate_total / kTimedPasses);
  const float speedup = baseline_average / candidate_average;
  std::cout << "PERF_FP8_M8_FIXED_SHAPE: " << label
            << " baseline_average_ms=" << baseline_average
            << " candidate_average_ms=" << candidate_average
            << " speedup=" << speedup
            << " uplift_percent=" << (speedup - 1.0F) * 100.0F
            << " bitwise_mismatches=" << mismatches << '/' << baseline.size()
            << '\n';
  return {baseline_average, candidate_average, bitwise_equal};
}

void run_optional_fp8_m8_fixed_shape_performance(TestContext& test,
                                                  cudaStream_t stream) {
  if (!fp8_m8_fixed_shape_performance_enabled()) {
    std::cout << "SKIP: FP8 M8 fixed-shape performance segment; set "
                 "Q3X_RUN_SM87_FP8_M8_FIXED_SHAPE_PERF=1 to enable\n";
    return;
  }
  constexpr float kMinimumWeightedSpeedup = 1.03F;
  constexpr float kMinimumPerShapeSpeedup = 0.98F;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t calls_per_prompt;
    const char* label;
  };
  constexpr std::array<Shape, 5U> kShapes{{
      {10'240U, 5'120U, 48U, "FP8 M8 fixed 10240x5120"},
      {5'120U, 6'144U, 64U, "FP8 M8 fixed 5120x6144"},
      {6'144U, 5'120U, 48U, "FP8 M8 fixed 6144x5120"},
      {12'288U, 5'120U, 16U, "FP8 M8 fixed 12288x5120"},
      {1'024U, 5'120U, 32U, "FP8 M8 fixed 1024x5120"},
  }};
  std::array<Fp8M8FixedShapeMeasurement, kShapes.size()> measurements{};
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    measurements[index] = benchmark_fp8_m8_fixed_shape(
        test, stream, kShapes[index].rows, kShapes[index].columns,
        kShapes[index].label);
  }

  double weighted_baseline = 0.0;
  double weighted_candidate = 0.0;
  bool all_bitwise = true;
  bool all_finite = true;
  bool no_shape_regression = true;
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    const Fp8M8FixedShapeMeasurement& measurement = measurements[index];
    const bool finite =
        std::isfinite(measurement.baseline_milliseconds) &&
        std::isfinite(measurement.candidate_milliseconds);
    const float speedup =
        measurement.baseline_milliseconds / measurement.candidate_milliseconds;
    all_bitwise = all_bitwise && measurement.bitwise_equal;
    all_finite = all_finite && finite;
    no_shape_regression = no_shape_regression && finite &&
                          speedup >= kMinimumPerShapeSpeedup;
    weighted_baseline +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        measurement.baseline_milliseconds;
    weighted_candidate +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        measurement.candidate_milliseconds;
    std::cout << "PERF_FP8_M8_FIXED_SHAPE_VALIDATION: "
              << kShapes[index].label << " baseline_ms="
              << measurement.baseline_milliseconds << " candidate_ms="
              << measurement.candidate_milliseconds << " speedup=" << speedup
              << " minimum_speedup=" << kMinimumPerShapeSpeedup
              << " gate="
              << (finite && speedup >= kMinimumPerShapeSpeedup ? "PASS"
                                                               : "FAIL")
              << '\n';
  }
  const double weighted_speedup = weighted_baseline / weighted_candidate;
  const bool aggregate_gate =
      all_bitwise && all_finite && no_shape_regression &&
      std::isfinite(weighted_speedup) &&
      weighted_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_FP8_M8_FIXED_SHAPE_AGGREGATE: weighted_baseline_ms="
            << weighted_baseline
            << " weighted_candidate_ms=" << weighted_candidate
            << " speedup=" << weighted_speedup
            << " required_speedup=" << kMinimumWeightedSpeedup
            << " all_bitwise=" << (all_bitwise ? "true" : "false")
            << " no_shape_regression="
            << (no_shape_regression ? "true" : "false")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "FP8 M8 fixed shapes clear every production gate");
}

struct NvFp4M16WmmaMeasurement {
  double baseline_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
  bool deterministic = false;
  bool within_tolerance = false;
};

struct NvFp4M16OutputCheck {
  bool deterministic = false;
  bool within_tolerance = false;
  std::size_t reference_nan_count = 0U;
};

[[nodiscard]] NvFp4M16OutputCheck check_nvfp4_m16_outputs(
    TestContext& test, const std::vector<std::uint16_t>& candidate,
    const std::vector<std::uint16_t>& baseline,
    const std::vector<std::uint16_t>& replay, const std::size_t columns,
    const std::size_t expected_reference_nan_count,
    const std::string& label) {
  test.expect(candidate.size() == baseline.size(),
              label + " candidate/baseline output size");
  test.expect(candidate.size() == replay.size(),
              label + " candidate/replay output size");
  const std::size_t count =
      std::min(candidate.size(), std::min(baseline.size(), replay.size()));
  std::size_t bf16_mismatches = 0U;
  std::size_t deterministic_mismatches = 0U;
  std::size_t reference_nan_count = 0U;
  std::size_t nan_class_mismatches = 0U;
  float maximum_absolute_error = 0.0F;
  float maximum_relative_error = 0.0F;
  bool within_tolerance = true;
  for (std::size_t index = 0U; index < count; ++index) {
    bf16_mismatches += candidate[index] != baseline[index] ? 1U : 0U;
    deterministic_mismatches += candidate[index] != replay[index] ? 1U : 0U;
    if (is_bf16_nan(baseline[index])) {
      ++reference_nan_count;
      const bool candidate_is_nan = is_bf16_nan(candidate[index]);
      nan_class_mismatches += candidate_is_nan ? 0U : 1U;
      within_tolerance = within_tolerance && candidate_is_nan;
      continue;
    }
    const float baseline_value = decode_bf16(baseline[index]);
    const float candidate_value = decode_bf16(candidate[index]);
    const float absolute_error =
        std::fabs(candidate_value - baseline_value);
    const float relative_error =
        absolute_error / std::max(1.0e-6F, std::fabs(baseline_value));
    maximum_absolute_error =
        std::max(maximum_absolute_error, absolute_error);
    maximum_relative_error =
        std::max(maximum_relative_error, relative_error);
    const float tolerance =
        2.0e-4F * std::sqrt(static_cast<float>(columns)) +
        1.0e-2F * std::max(1.0F, std::fabs(baseline_value));
    within_tolerance = within_tolerance &&
                       std::isfinite(candidate_value) &&
                       std::isfinite(baseline_value) &&
                       absolute_error <= tolerance;
  }
  const bool deterministic = deterministic_mismatches == 0U;
  const bool nan_coverage =
      reference_nan_count == expected_reference_nan_count &&
      nan_class_mismatches == 0U;
  std::cout << "NVFP4_M16_WMMA_DIFF: " << label
            << " candidate_vs_two_m8_bf16=" << bf16_mismatches << '/'
            << count << " deterministic_mismatches="
            << deterministic_mismatches << '/' << count
            << " reference_nan_count=" << reference_nan_count
            << " nan_class_mismatches=" << nan_class_mismatches
            << " max_abs=" << maximum_absolute_error
            << " max_rel=" << maximum_relative_error
            << " tolerance_gate=" << (within_tolerance ? "PASS" : "FAIL")
            << '\n';
  test.expect(deterministic, label + " candidate replay is bitwise stable");
  test.expect(nan_coverage, label + " has the required NaN-class coverage");
  test.expect(within_tolerance,
              label + " clears the existing numerical tolerance");
  return {deterministic, within_tolerance && nan_coverage,
          reference_nan_count};
}

[[nodiscard]] NvFp4M16WmmaMeasurement benchmark_nvfp4_m16_wmma_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 16U;
  constexpr std::size_t kHalfTokens = 8U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  // Deliberately not a power-of-two scale. Together with the odd activation
  // denominators below this prevents an accidentally exact-only fixture.
  constexpr float kWeightScale2 = 1.0F / 37.0F;
  constexpr std::array<std::uint8_t, 16U> kFiniteScaleCodes{{
      0x00U, 0x80U, 0x08U, 0x88U, 0x18U, 0x98U, 0x20U, 0xa0U,
      0x28U, 0xa8U, 0x30U, 0xb0U, 0x38U, 0xb8U, 0x40U, 0xc0U,
  }};
  const std::size_t packed_columns = columns / 2U;
  const std::size_t scale_columns = columns / 16U;

  std::vector<std::uint8_t> host_packed(rows * packed_columns);
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t row = 0U; row < rows; ++row) {
    for (std::size_t packed_column = 0U; packed_column < packed_columns;
         ++packed_column) {
      const std::uint8_t low = static_cast<std::uint8_t>(
          (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
      const std::uint8_t high = static_cast<std::uint8_t>(
          (packed_column * 5U + row * 7U + (packed_column >> 3U) * 3U + 1U) &
          0x0fU);
      host_packed[row * packed_columns + packed_column] =
          static_cast<std::uint8_t>(low | (high << 4U));
      low_nibble_covered[low] = true;
      high_nibble_covered[high] = true;
    }
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers all E2M1 low-nibble codes");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers all E2M1 high-nibble codes");

  std::vector<std::uint8_t> host_scales(rows * scale_columns);
  std::array<bool, kFiniteScaleCodes.size()> scale_codes_covered{};
  for (std::size_t row = 0U; row < rows; ++row) {
    for (std::size_t group = 0U; group < scale_columns; ++group) {
      const std::size_t code_index =
          (row * 5U + group * 7U + (group >> 3U)) & 0x0fU;
      host_scales[row * scale_columns + group] =
          kFiniteScaleCodes[code_index];
      scale_codes_covered[code_index] = true;
    }
  }
  test.expect(std::all_of(scale_codes_covered.begin(),
                          scale_codes_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every finite scale fixture code");

  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 31U) - 15;
      const int odd_denominator =
          3 + 2 * static_cast<int>((column * 7U + token * 3U) % 11U);
      const int exponent =
          static_cast<int>((column * 5U + token * 7U) % 5U) - 3;
      host_activations[token * columns + column] = encode_bf16(std::ldexp(
          static_cast<float>(centered) /
              static_cast<float>(odd_denominator),
          exponent));
    }
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  DeviceBuffer<std::uint16_t> replay_output;
  bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokens * rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokens * rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(replay_output.allocate(kTokens * rows),
                                label + " allocate replay output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), host_packed.data(),
                                       host_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize packed E2M1 weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(scales.get(), host_scales.data(),
                                       host_scales.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize grouped scale codes");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize nonpower activations");
  if (!ready) {
    return {};
  }

  const auto launch_baseline = [&]() noexcept -> int {
    int status =
        q3x::kernels::launch_sm87_nvfp4_w4a16_small_m_gemm_bf16_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            kHalfTokens, rows, columns, baseline_output.get(),
            static_cast<void*>(stream));
    if (status != static_cast<int>(cudaSuccess)) {
      return status;
    }
    return q3x::kernels::launch_sm87_nvfp4_w4a16_small_m_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2,
        activations.get() + kHalfTokens * columns, kHalfTokens, rows, columns,
        baseline_output.get() + kHalfTokens * rows,
        static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2, activations.get(), rows,
        columns, candidate_output.get(), static_cast<void*>(stream));
  };
  const auto launch_replay = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2, activations.get(), rows,
        columns, replay_output.get(), static_cast<void*>(stream));
  };

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " correctness two-M8 baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " correctness M16 WMMA candidate");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_replay()),
                                label + " deterministic replay");
  std::vector<std::uint16_t> baseline(kTokens * rows);
  std::vector<std::uint16_t> candidate(kTokens * rows);
  std::vector<std::uint16_t> replay(kTokens * rows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy two-M8 baseline");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy M16 candidate");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           replay.data(), replay_output.get(),
                           replay.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy M16 replay");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " correctness synchronize");
  if (!ready) {
    return {};
  }
  const NvFp4M16OutputCheck finite_check = check_nvfp4_m16_outputs(
      test, candidate, baseline, replay, columns, 0U,
      label + " full E2M1/group-scale fixture");

  for (int iteration = 0; iteration < kWarmupIterations && ready;
       ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " baseline warmup");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " candidate warmup");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return {};
  }

  double baseline_total = 0.0;
  double candidate_total = 0.0;
  bool finite_timing = true;
  for (int round = 0; round < kMeasurementRounds; ++round) {
    const std::string suffix = " round=" + std::to_string(round + 1);
    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 1" + suffix);
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 1" + suffix);
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 2" + suffix);
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 2" + suffix);
    const bool round_finite =
        std::isfinite(baseline_first) && std::isfinite(candidate_first) &&
        std::isfinite(candidate_second) && std::isfinite(baseline_second);
    finite_timing = finite_timing && round_finite;
    if (round_finite) {
      baseline_total += baseline_first + baseline_second;
      candidate_total += candidate_first + candidate_second;
    }
    std::cout << "PERF_NVFP4_M16_WMMA_ROUND: " << label
              << " round=" << round + 1
              << " baseline_pass1_ms=" << baseline_first
              << " candidate_pass1_ms=" << candidate_first
              << " candidate_pass2_ms=" << candidate_second
              << " baseline_pass2_ms=" << baseline_second << '\n';
  }
  constexpr double kTimedPasses =
      2.0 * static_cast<double>(kMeasurementRounds);
  const double baseline_average = baseline_total / kTimedPasses;
  const double candidate_average = candidate_total / kTimedPasses;
  std::cout << "PERF_NVFP4_M16_WMMA: " << label
            << " baseline_two_m8_ms=" << baseline_average
            << " candidate_m16_ms=" << candidate_average
            << " speedup=" << baseline_average / candidate_average << '\n';

  // Reuse the timed buffers for an exhaustive 256 scale-code x 16 E2M1
  // matrix. Each of the first 4096 rows has exactly one selected nibble and
  // one selected 16-value scale group. Critical K positions cross nibble,
  // scale-group, vector-load, and K64 staging boundaries. All other values
  // are zero, which also checks the required 0 * NaN propagation inside the
  // two reserved E4M3FN scale groups.
  constexpr std::size_t kScaleCodes = 256U;
  constexpr std::size_t kNibbles = 16U;
  constexpr std::size_t kExhaustiveRows = kScaleCodes * kNibbles;
  constexpr std::size_t kNanCombinations = 2U * kNibbles;
  constexpr std::array<std::size_t, 12U> kTargetColumns{{
      0U, 1U, 15U, 16U, 31U, 32U, 47U, 48U, 62U, 63U, 64U, 65U,
  }};
  std::fill(host_packed.begin(), host_packed.end(), 0U);
  std::fill(host_scales.begin(), host_scales.end(), 0U);
  std::array<bool, kTargetColumns.size()> target_columns_covered{};
  for (std::size_t scale_code = 0U; scale_code < kScaleCodes;
       ++scale_code) {
    for (std::size_t nibble = 0U; nibble < kNibbles; ++nibble) {
      const std::size_t row = scale_code * kNibbles + nibble;
      const std::size_t target_index = row % kTargetColumns.size();
      const std::size_t column = kTargetColumns[target_index];
      std::uint8_t& packed_byte =
          host_packed[row * packed_columns + column / 2U];
      if ((column & 1U) == 0U) {
        packed_byte = static_cast<std::uint8_t>(nibble);
      } else {
        packed_byte = static_cast<std::uint8_t>(nibble << 4U);
      }
      host_scales[row * scale_columns + column / 16U] =
          static_cast<std::uint8_t>(scale_code);
      target_columns_covered[target_index] = true;
    }
  }
  test.expect(rows >= kExhaustiveRows,
              label + " has room for all scale x nibble rows");
  test.expect(std::all_of(target_columns_covered.begin(),
                          target_columns_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every K boundary fixture");
  ready = test.cuda_ok(
      cudaMemcpyAsync(packed.get(), host_packed.data(), host_packed.size(),
                      cudaMemcpyHostToDevice, stream),
      label + " initialize exhaustive scale/nibble weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(scales.get(), host_scales.data(),
                                       host_scales.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize exhaustive scale codes");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                                label + " exhaustive two-M8 baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " exhaustive M16 candidate");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_replay()),
                                label + " exhaustive deterministic replay");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy exhaustive baseline");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy exhaustive candidate");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           replay.data(), replay_output.get(),
                           replay.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy exhaustive replay");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " exhaustive synchronize");
  if (!ready) {
    return {};
  }
  constexpr std::size_t kExpectedNanOutputs = kNanCombinations * kTokens;
  const NvFp4M16OutputCheck nan_check = check_nvfp4_m16_outputs(
      test, candidate, baseline, replay, columns, kExpectedNanOutputs,
      label + " exhaustive scale x E2M1 fixture");
  std::size_t positive_nan_row_count = 0U;
  std::size_t negative_nan_row_count = 0U;
  bool token_boundary_covered = true;
  constexpr std::size_t kPositiveNanFirstRow = 0x7fU * kNibbles;
  constexpr std::size_t kNegativeNanFirstRow = 0xffU * kNibbles;
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t nibble = 0U; nibble < kNibbles; ++nibble) {
      positive_nan_row_count +=
          is_bf16_nan(
              baseline[token * rows + kPositiveNanFirstRow + nibble])
              ? 1U
              : 0U;
      negative_nan_row_count +=
          is_bf16_nan(
              baseline[token * rows + kNegativeNanFirstRow + nibble])
              ? 1U
              : 0U;
    }
  }
  for (const std::size_t token : {7U, 8U}) {
    for (const std::size_t first_row : {kPositiveNanFirstRow,
                                        kNegativeNanFirstRow}) {
      for (std::size_t nibble = 0U; nibble < kNibbles; ++nibble) {
        const std::size_t row = first_row + nibble;
        token_boundary_covered =
            token_boundary_covered &&
            is_bf16_nan(baseline[token * rows + row]) &&
            is_bf16_nan(candidate[token * rows + row]);
      }
    }
  }
  test.expect(positive_nan_row_count == kNibbles * kTokens,
              label + " propagates all 0x7f x E2M1 combinations");
  test.expect(negative_nan_row_count == kNibbles * kTokens,
              label + " propagates all 0xff x E2M1 combinations");
  test.expect(token_boundary_covered,
              label + " preserves NaN class across token 7/8");

  const bool deterministic =
      finite_check.deterministic && nan_check.deterministic;
  const bool within_tolerance =
      finite_check.within_tolerance && nan_check.within_tolerance;
  return {finite_timing ? baseline_average
                        : std::numeric_limits<double>::quiet_NaN(),
          finite_timing ? candidate_average
                        : std::numeric_limits<double>::quiet_NaN(),
          deterministic, within_tolerance};
}

void run_optional_nvfp4_m16_wmma_performance(TestContext& test,
                                              cudaStream_t stream) {
  if (!nvfp4_m16_wmma_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M16 WMMA performance segment; set "
                 "Q3X_RUN_SM87_NVFP4_M16_WMMA_PERF=1 to enable\n";
    return;
  }

  constexpr double kMinimumPerShapeSpeedup = 1.10;
  constexpr double kMinimumWeightedSpeedup = 1.15;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t calls_per_prompt;
    const char* label;
  };
  constexpr std::array<Shape, 2U> kShapes{{
      {17'408U, 5'120U, 256U, "NVFP4 M16 WMMA 17408x5120"},
      {5'120U, 17'408U, 128U, "NVFP4 M16 WMMA 5120x17408"},
  }};
  std::array<NvFp4M16WmmaMeasurement, kShapes.size()> measurements{};
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    measurements[index] = benchmark_nvfp4_m16_wmma_shape(
        test, stream, kShapes[index].rows, kShapes[index].columns,
        kShapes[index].label);
  }

  double weighted_baseline = 0.0;
  double weighted_candidate = 0.0;
  bool all_shapes_pass = true;
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    const NvFp4M16WmmaMeasurement& measurement = measurements[index];
    const double speedup = measurement.baseline_milliseconds /
                           measurement.candidate_milliseconds;
    const bool finite =
        std::isfinite(measurement.baseline_milliseconds) &&
        std::isfinite(measurement.candidate_milliseconds) &&
        std::isfinite(speedup);
    const bool shape_gate =
        finite && measurement.deterministic && measurement.within_tolerance &&
        speedup >= kMinimumPerShapeSpeedup;
    all_shapes_pass = all_shapes_pass && shape_gate;
    test.expect(shape_gate,
                std::string(kShapes[index].label) +
                    " clears correctness and per-shape performance gates");
    weighted_baseline +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        measurement.baseline_milliseconds;
    weighted_candidate +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        measurement.candidate_milliseconds;
    std::cout << "PERF_NVFP4_M16_WMMA_VALIDATION: "
              << kShapes[index].label << " baseline_two_m8_ms="
              << measurement.baseline_milliseconds
              << " candidate_m16_ms=" << measurement.candidate_milliseconds
              << " speedup=" << speedup
              << " minimum_speedup=" << kMinimumPerShapeSpeedup
              << " gate=" << (shape_gate ? "PASS" : "FAIL") << '\n';
  }
  const double weighted_speedup = weighted_baseline / weighted_candidate;
  const bool aggregate_gate =
      all_shapes_pass && std::isfinite(weighted_speedup) &&
      weighted_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_NVFP4_M16_WMMA_AGGREGATE: "
            << "weighted_baseline_two_m8_ms=" << weighted_baseline
            << " weighted_candidate_m16_ms=" << weighted_candidate
            << " speedup=" << weighted_speedup
            << " required_speedup=" << kMinimumWeightedSpeedup
            << " profile_calls=256:128"
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "NVFP4 M16 WMMA clears the weighted production gate");
}

void run_fp8_m32_wmma_exact_shape_smoke_case(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 32U;
  constexpr std::size_t kPanelTokens = 16U;
  constexpr std::size_t kGuardElements = 64U;
  constexpr std::uint16_t kCandidateGuard = 0xa5a5U;
  constexpr std::uint16_t kReplayGuard = 0x5a5aU;
  constexpr std::uint16_t kPublicGuard = 0x3c3cU;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};
  std::vector<std::uint8_t> host_weights(rows * columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] =
        kFiniteCodes[(index * 7U + index / columns * 5U + 1U) %
                     kFiniteCodes.size()];
  }
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 13U + token * 17U + 3U) % 127U) - 63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_guarded;
  DeviceBuffer<std::uint16_t> replay_guarded;
  DeviceBuffer<std::uint16_t> public_guarded;
  const std::size_t output_elements = kTokens * rows;
  const std::size_t guarded_elements = output_elements + 2U * kGuardElements;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(output_elements),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_guarded.allocate(guarded_elements),
                                label + " allocate guarded candidate output");
  ready = ready && test.cuda_ok(replay_guarded.allocate(guarded_elements),
                                label + " allocate guarded replay output");
  ready = ready && test.cuda_ok(public_guarded.allocate(guarded_elements),
                                label + " allocate guarded public output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(candidate_guarded.get(), 0xa5,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison candidate guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(replay_guarded.get(), 0x5a,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison replay guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(public_guarded.get(), 0x3c,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison public guards");
  if (!ready) {
    return;
  }

  std::uint16_t* const candidate_output =
      candidate_guarded.get() + kGuardElements;
  std::uint16_t* const replay_output =
      replay_guarded.get() + kGuardElements;
  std::uint16_t* const public_output =
      public_guarded.get() + kGuardElements;
  const auto launch_baseline = [&]() noexcept -> int {
    int status = q3x::kernels::launch_sm87_fp8_w8a16_m16_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), rows, columns,
        baseline_output.get(), static_cast<void*>(stream));
    if (status != static_cast<int>(cudaSuccess)) {
      return status;
    }
    return q3x::kernels::launch_sm87_fp8_w8a16_m16_gemm_bf16_cuda(
        weights.get(), kWeightScale,
        activations.get() + kPanelTokens * columns, rows, columns,
        baseline_output.get() + kPanelTokens * rows,
        static_cast<void*>(stream));
  };
  const auto launch_candidate = [&](std::uint16_t* const destination) noexcept
      -> int {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_fixed_shape_test_cuda(
            weights.get(), kWeightScale, activations.get(), rows, columns,
            destination, static_cast<void*>(stream));
  };
  const auto launch_public = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_fp8_w8a16_m32_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), rows, columns,
        public_output, static_cast<void*>(stream));
  };

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " launch two-public-M16 baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(
                           launch_candidate(candidate_output)),
                       label + " launch single-M32 candidate");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(
                           launch_candidate(replay_output)),
                       label + " launch deterministic replay");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_public()),
                                label + " launch public M32");

  std::vector<std::uint16_t> baseline(output_elements);
  std::vector<std::uint16_t> candidate(guarded_elements);
  std::vector<std::uint16_t> replay(guarded_elements);
  std::vector<std::uint16_t> production(guarded_elements);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_guarded.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded candidate");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(replay.data(), replay_guarded.get(),
                                       replay.size() * sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded replay");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           production.data(), public_guarded.get(),
                           production.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded public output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize outputs");
  if (!ready) {
    return;
  }

  std::size_t baseline_mismatches = 0U;
  std::size_t replay_mismatches = 0U;
  std::size_t public_mismatches = 0U;
  for (std::size_t index = 0U; index < output_elements; ++index) {
    const std::uint16_t candidate_value =
        candidate[kGuardElements + index];
    baseline_mismatches += candidate_value != baseline[index] ? 1U : 0U;
    replay_mismatches +=
        candidate_value != replay[kGuardElements + index] ? 1U : 0U;
    public_mismatches +=
        candidate_value != production[kGuardElements + index] ? 1U : 0U;
  }
  bool guards_intact = true;
  for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
    guards_intact =
        guards_intact && candidate[guard] == kCandidateGuard &&
        candidate[kGuardElements + output_elements + guard] ==
            kCandidateGuard &&
        replay[guard] == kReplayGuard &&
        replay[kGuardElements + output_elements + guard] == kReplayGuard &&
        production[guard] == kPublicGuard &&
        production[kGuardElements + output_elements + guard] == kPublicGuard;
  }
  std::cout << "FP8_M32_WMMA_SMOKE_DIFF: " << label
            << " candidate_vs_two_public_m16_bf16=" << baseline_mismatches
            << '/' << output_elements
            << " replay_mismatches=" << replay_mismatches << '/'
            << output_elements
            << " public_mismatches=" << public_mismatches << '/'
            << output_elements
            << " output_guards=" << (guards_intact ? "intact" : "BAD")
            << '\n';
  test.expect(baseline_mismatches == 0U,
              label + " is bit-exact to two public M16 launches");
  test.expect(replay_mismatches == 0U,
              label + " deterministic replay is bit-exact");
  test.expect(public_mismatches == 0U,
              label + " public M32 is bit-exact to the direct candidate");
  test.expect(guards_intact, label + " preserves head and tail guards");

  cudaGraph_t graph = nullptr;
  bool graph_ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin graph capture");
  int graph_launch_status = static_cast<int>(cudaErrorUnknown);
  if (graph_ready) {
    graph_launch_status = launch_public();
    graph_ready =
        test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                     label + " end graph capture") &&
        graph_ready;
  }
  std::size_t node_count = 0U;
  std::size_t kernel_node_count = 0U;
  if (graph_ready) {
    graph_ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                               label + " query graph nodes") &&
                  graph_ready;
  }
  if (graph_ready && node_count != 0U) {
    std::vector<cudaGraphNode_t> nodes(node_count);
    std::size_t capacity = nodes.size();
    graph_ready = test.cuda_ok(cudaGraphGetNodes(graph, nodes.data(),
                                                 &capacity),
                               label + " get graph nodes") &&
                  graph_ready;
    for (std::size_t index = 0U; index < capacity && graph_ready; ++index) {
      cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
      graph_ready = test.cuda_ok(cudaGraphNodeGetType(nodes[index], &type),
                                 label + " get graph node type") &&
                    graph_ready;
      kernel_node_count += type == cudaGraphNodeTypeKernel ? 1U : 0U;
    }
  }
  if (graph != nullptr) {
    graph_ready = test.cuda_ok(cudaGraphDestroy(graph),
                               label + " destroy graph") &&
                  graph_ready;
  }
  const bool single_kernel_graph =
      graph_ready && graph_launch_status == static_cast<int>(cudaSuccess) &&
      node_count == 1U && kernel_node_count == 1U;
  std::cout << "FP8_M32_WMMA_GRAPH: " << label
            << " total_nodes=" << node_count
            << " kernel_nodes=" << kernel_node_count
            << " gate=" << (single_kernel_graph ? "PASS" : "FAIL")
            << '\n';
  test.expect(single_kernel_graph,
              label + " captures exactly one CUDA kernel node");
}

void run_fp8_m32_wmma_exact_shape_smoke(TestContext& test,
                                         cudaStream_t stream) {
  struct Shape {
