using Fp8M32TestLaunch = int (*)(
    const std::uint8_t*, float, const std::uint16_t*, std::size_t,
    std::size_t, std::uint16_t*, void*) noexcept;

using Fp8M32ResourceQuery = int (*)(
    std::size_t, std::size_t, int*, std::size_t*, std::size_t*, int*,
    int*) noexcept;

struct Fp8M32ProductionShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t calls_per_p33;
  const char* label;
};

constexpr std::array<Fp8M32ProductionShape, 4U>
    kFp8M32ProductionShapes{{
        {10'240U, 5'120U, 48U, "FP8 M32 dual-A 10240x5120"},
        {5'120U, 6'144U, 64U, "FP8 M32 dual-A 5120x6144"},
        {6'144U, 5'120U, 48U, "FP8 M32 dual-A 6144x5120"},
        {12'288U, 5'120U, 16U, "FP8 M32 dual-A 12288x5120"},
    }};

struct Fp8M32CapturedKernel {
  bool valid = false;
  void* function = nullptr;
  dim3 grid{0U, 0U, 0U};
  dim3 block{0U, 0U, 0U};
  unsigned int dynamic_shared_bytes = 0U;
  std::size_t total_nodes = 0U;
  std::size_t kernel_nodes = 0U;
};

[[nodiscard]] Fp8M32CapturedKernel capture_fp8_m32_kernel(
    TestContext& test, cudaStream_t stream, const Fp8M32TestLaunch launch,
    const std::uint8_t* const weights, const float weight_scale,
    const std::uint16_t* const activations, const std::size_t rows,
    const std::size_t columns, std::uint16_t* const output,
    const std::string& label) {
  Fp8M32CapturedKernel result{};
  cudaGraph_t graph = nullptr;
  bool ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin capture");
  int launch_status = static_cast<int>(cudaErrorUnknown);
  if (ready) {
    launch_status = launch(weights, weight_scale, activations, rows, columns,
                           output, static_cast<void*>(stream));
    ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                         label + " end capture") &&
            ready;
  }
  if (ready) {
    ready = test.cuda_ok(
                cudaGraphGetNodes(graph, nullptr, &result.total_nodes),
                label + " query nodes") &&
            ready;
  }
  if (ready && result.total_nodes != 0U) {
    std::vector<cudaGraphNode_t> nodes(result.total_nodes);
    std::size_t capacity = nodes.size();
    ready = test.cuda_ok(cudaGraphGetNodes(graph, nodes.data(), &capacity),
                         label + " get nodes") &&
            ready;
    for (std::size_t index = 0U; index < capacity && ready; ++index) {
      cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
      ready = test.cuda_ok(cudaGraphNodeGetType(nodes[index], &type),
                           label + " get node type") &&
              ready;
      if (type == cudaGraphNodeTypeKernel) {
        ++result.kernel_nodes;
        cudaKernelNodeParams params{};
        ready = test.cuda_ok(cudaGraphKernelNodeGetParams(nodes[index],
                                                           &params),
                             label + " get kernel params") &&
                ready;
        result.function = params.func;
        result.grid = params.gridDim;
        result.block = params.blockDim;
        result.dynamic_shared_bytes = params.sharedMemBytes;
      }
    }
  }
  if (graph != nullptr) {
    ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy graph") &&
            ready;
  }
  result.valid = ready && launch_status == static_cast<int>(cudaSuccess) &&
                 result.total_nodes == 1U && result.kernel_nodes == 1U;
  return result;
}

void run_fp8_m32_dual_resident_a_resource_gates(TestContext& test) {
  constexpr int kPredecessorRegisters = 46;
  constexpr std::size_t kPredecessorStaticSharedBytes = 21'248U;
  constexpr int kPredecessorActiveBlocks = 5;
  constexpr int kProductionMaximumRegisters = 51;
  constexpr std::size_t kProductionStaticSharedBytes = 23'552U;
  constexpr int kProductionMinimumActiveBlocks = 5;
  constexpr int kMaximumThreads = 256;

  const auto query_and_check =
      [&](const Fp8M32ProductionShape& shape,
          const char* const implementation_name,
          const Fp8M32ResourceQuery query, const bool predecessor) {
        int registers_per_thread = -1;
        std::size_t static_shared_bytes =
            std::numeric_limits<std::size_t>::max();
        std::size_t local_bytes = std::numeric_limits<std::size_t>::max();
        int maximum_threads_per_block = -1;
        int active_blocks_per_sm = -1;
        const int status = query(
            shape.rows, shape.columns, &registers_per_thread,
            &static_shared_bytes, &local_bytes, &maximum_threads_per_block,
            &active_blocks_per_sm);
        const bool registers_gate =
            predecessor
                ? registers_per_thread == kPredecessorRegisters
                : registers_per_thread <= kProductionMaximumRegisters;
        const bool shared_gate =
            static_shared_bytes ==
            (predecessor ? kPredecessorStaticSharedBytes
                         : kProductionStaticSharedBytes);
        const bool occupancy_gate =
            predecessor
                ? active_blocks_per_sm == kPredecessorActiveBlocks
                : active_blocks_per_sm >= kProductionMinimumActiveBlocks;
        const bool gate =
            status == static_cast<int>(cudaSuccess) && registers_gate &&
            shared_gate && local_bytes == 0U &&
            maximum_threads_per_block == kMaximumThreads && occupancy_gate;
        std::cout << "FP8_M32_DUAL_RESIDENT_A_RESOURCES: implementation="
                  << implementation_name << " shape=" << shape.rows << 'x'
                  << shape.columns << " status=" << status
                  << " registers_per_thread=" << registers_per_thread
                  << " static_shared_bytes=" << static_shared_bytes
                  << " local_bytes=" << local_bytes
                  << " maximum_threads_per_block="
                  << maximum_threads_per_block
                  << " active_blocks_per_sm=" << active_blocks_per_sm
                  << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
        test.expect(gate,
                    std::string(shape.label) + " " + implementation_name +
                        " clears the frozen resource gate");
      };

  for (const Fp8M32ProductionShape& shape : kFp8M32ProductionShapes) {
    query_and_check(
        shape, "fixed_predecessor_single_resident_a",
        q3x::kernels::
            query_sm87_fp8_w8a16_small_m32_wmma_fixed_shape_resources_test_cuda,
        true);
    query_and_check(
        shape, "production_dual_resident_a",
        q3x::kernels::
            query_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_resources_test_cuda,
        false);
  }

  int registers_per_thread = 123;
  std::size_t static_shared_bytes = 456U;
  std::size_t local_bytes = 789U;
  int maximum_threads_per_block = 321;
  int active_blocks_per_sm = 654;
  const int null_status = q3x::kernels::
      query_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_resources_test_cuda(
          10'240U, 5'120U, nullptr, &static_shared_bytes, &local_bytes,
          &maximum_threads_per_block, &active_blocks_per_sm);
  const int shape_status = q3x::kernels::
      query_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_resources_test_cuda(
          10'239U, 5'120U, &registers_per_thread, &static_shared_bytes,
          &local_bytes, &maximum_threads_per_block, &active_blocks_per_sm);
  const bool invalid_gate =
      null_status == static_cast<int>(cudaErrorInvalidValue) &&
      shape_status == static_cast<int>(cudaErrorInvalidValue) &&
      registers_per_thread == 123 && static_shared_bytes == 456U &&
      local_bytes == 789U && maximum_threads_per_block == 321 &&
      active_blocks_per_sm == 654;
  std::cout << "FP8_M32_DUAL_RESIDENT_A_RESOURCE_INVALID: null_status="
            << null_status << " shape_status=" << shape_status
            << " outputs_unchanged=" << (invalid_gate ? "true" : "false")
            << " gate=" << (invalid_gate ? "PASS" : "FAIL") << '\n';
  test.expect(invalid_gate,
              "FP8 M32 production dual-A resource query rejects before "
              "output writes");
}

void run_fp8_m32_dual_resident_a_invalid_capture_contract(
    TestContext& test, cudaStream_t stream) {
  constexpr std::size_t kRows = 10'240U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::uintptr_t kWeightAddress = 0x1'0000'0000ULL;
  constexpr std::uintptr_t kActivationAddress = 0x2'0000'0000ULL;
  constexpr std::uintptr_t kOutputAddress = 0x3'0000'0000ULL;
  auto* const weights =
      reinterpret_cast<const std::uint8_t*>(kWeightAddress);
  auto* const activations =
      reinterpret_cast<const std::uint16_t*>(kActivationAddress);
  auto* const output = reinterpret_cast<std::uint16_t*>(kOutputAddress);
  auto* const overlapping_output = reinterpret_cast<std::uint16_t*>(
      kActivationAddress + 16U * kColumns * sizeof(std::uint16_t));
  auto* const misaligned_activations =
      reinterpret_cast<const std::uint16_t*>(kActivationAddress + 1U);
  const std::string label = "FP8 M32 production dual-A invalid capture";

  cudaGraph_t graph = nullptr;
  bool ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin");
  std::array<int, 4U> statuses{};
  statuses.fill(static_cast<int>(cudaErrorUnknown));
  if (ready) {
    statuses[0] = q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda(
            weights, 1.0F, activations, kRows - 1U, kColumns, output,
            static_cast<void*>(stream));
    statuses[1] = q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda(
            weights, 1.0F, activations, kRows, kColumns,
            overlapping_output, static_cast<void*>(stream));
    statuses[2] = q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda(
            weights + 1U, 1.0F, activations, kRows, kColumns, output,
            static_cast<void*>(stream));
    statuses[3] = q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda(
            weights, 1.0F, misaligned_activations, kRows, kColumns, output,
            static_cast<void*>(stream));
    ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph), label + " end") &&
            ready;
  }
  std::size_t node_count = 0U;
  if (ready) {
    ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                         label + " query nodes") &&
            ready;
  }
  if (graph != nullptr) {
    ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy") &&
            ready;
  }
  const bool statuses_valid = std::all_of(
      statuses.begin(), statuses.end(), [](const int status) {
        return status == static_cast<int>(cudaErrorInvalidValue);
      });
  const bool gate = ready && statuses_valid && node_count == 0U;
  std::cout << "FP8_M32_DUAL_RESIDENT_A_INVALID_GRAPH: shape_status="
            << statuses[0] << " alias_status=" << statuses[1]
            << " weight_alignment_status=" << statuses[2]
            << " activation_alignment_status=" << statuses[3]
            << " total_nodes=" << node_count
            << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
  test.expect(gate,
              label + " rejects shape/alias/alignment before enqueue");
}

void run_fp8_m32_dual_resident_a_correctness_case(
    TestContext& test, cudaStream_t stream,
    const Fp8M32ProductionShape& shape,
    const bool exhaustive_codebook) {
  constexpr std::size_t kTokens = 32U;
  constexpr std::size_t kGuardElements = 64U;
  constexpr std::uint16_t kPredecessorGuard = 0x3c3cU;
  constexpr std::uint16_t kPublicGuard = 0xa5a5U;
  constexpr std::uint16_t kReplayGuard = 0x5a5aU;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};
  const std::string label =
      std::string(shape.label) +
      (exhaustive_codebook
           ? " exhaustive E4M3FN x4 packed-byte fixture"
           : " production-shape finite fixture");
  const std::size_t weight_elements = shape.rows * shape.columns;
  const std::size_t activation_elements = kTokens * shape.columns;
  const std::size_t output_elements = kTokens * shape.rows;
  const std::size_t guarded_elements = output_elements + 2U * kGuardElements;
  std::vector<std::uint8_t> host_weights(weight_elements, 0U);
  std::vector<std::uint16_t> host_activations(
      activation_elements, encode_bf16(0.0F));
  bool code_coverage_gate = true;

  if (exhaustive_codebook) {
    constexpr std::size_t kBytePositions = 4U;
    std::array<std::array<bool, 256U>, kBytePositions> code_coverage{};
    for (std::size_t code = 0U; code < 256U; ++code) {
      for (std::size_t position = 0U; position < kBytePositions; ++position) {
        const std::size_t row = code * kBytePositions + position;
        host_weights[row * shape.columns + position] =
            static_cast<std::uint8_t>(code);
        code_coverage[position][code] = true;
      }
    }
    for (std::size_t position = 0U; position < kBytePositions; ++position) {
      const std::size_t codes = static_cast<std::size_t>(std::count(
          code_coverage[position].begin(), code_coverage[position].end(),
          true));
      const bool position_gate = codes == 256U;
      code_coverage_gate = code_coverage_gate && position_gate;
      test.expect(position_gate,
                  label + " covers all raw codes in byte position " +
                      std::to_string(position));
      std::cout << "FP8_M32_DUAL_RESIDENT_A_CODE_COVERAGE: shape="
                << shape.rows << 'x' << shape.columns
                << " byte_position=" << position << " codes=" << codes
                << " gate=" << (position_gate ? "PASS" : "FAIL") << '\n';
    }
    for (std::size_t token = 0U; token < kTokens; ++token) {
      const float token_factor =
          static_cast<float>((token & 3U) + 1U) / 8.0F;
      for (std::size_t position = 0U; position < kBytePositions; ++position) {
        host_activations[token * shape.columns + position] = encode_bf16(
            token_factor * static_cast<float>(position + 1U));
      }
    }
  } else {
    for (std::size_t index = 0U; index < host_weights.size(); ++index) {
      host_weights[index] =
          kFiniteCodes[(index * 7U + index / shape.columns * 5U + 1U) %
                       kFiniteCodes.size()];
    }
    for (std::size_t token = 0U; token < kTokens; ++token) {
      for (std::size_t column = 0U; column < shape.columns; ++column) {
        const int centered = static_cast<int>(
                                 (column * 13U + token * 17U + 3U) % 127U) -
                             63;
        host_activations[token * shape.columns + column] =
            encode_bf16(static_cast<float>(centered) / 256.0F);
      }
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> predecessor_guarded;
  DeviceBuffer<std::uint16_t> public_guarded;
  DeviceBuffer<std::uint16_t> replay_guarded;
  bool ready = test.cuda_ok(weights.allocate(weight_elements),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(activation_elements),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(
                       predecessor_guarded.allocate(guarded_elements),
                       label + " allocate fixed predecessor output");
  ready = ready && test.cuda_ok(public_guarded.allocate(guarded_elements),
                                label + " allocate public production output");
  ready = ready && test.cuda_ok(replay_guarded.allocate(guarded_elements),
                                label + " allocate replay output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(predecessor_guarded.get(), 0x3c,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison fixed predecessor output and guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(public_guarded.get(), 0xa5,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison public production output and guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(replay_guarded.get(), 0x5a,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison direct dual-A replay differently");
  if (!ready) {
    return;
  }

  std::uint16_t* const predecessor_output =
      predecessor_guarded.get() + kGuardElements;
  std::uint16_t* const public_output =
      public_guarded.get() + kGuardElements;
  std::uint16_t* const replay_output =
      replay_guarded.get() + kGuardElements;
  const auto launch_fixed_predecessor =
      [&](std::uint16_t* const output) noexcept {
        return q3x::kernels::
            launch_sm87_fp8_w8a16_small_m32_wmma_fixed_shape_test_cuda(
                weights.get(), kWeightScale, activations.get(), shape.rows,
                shape.columns, output, static_cast<void*>(stream));
      };
  const auto launch_public = [&](std::uint16_t* const output) noexcept {
    return q3x::kernels::launch_sm87_fp8_w8a16_m32_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), shape.rows,
        shape.columns, output, static_cast<void*>(stream));
  };
  const auto launch_dual_a = [&](std::uint16_t* const output) noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda(
            weights.get(), kWeightScale, activations.get(), shape.rows,
            shape.columns, output, static_cast<void*>(stream));
  };
  ready = test.cuda_ok(
      static_cast<cudaError_t>(launch_fixed_predecessor(predecessor_output)),
      label + " launch fixed direct predecessor");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_public(public_output)),
                       label + " launch public production dual-A");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_dual_a(replay_output)),
                       label + " launch differently poisoned direct dual-A "
                               "replay");

  std::vector<std::uint16_t> predecessor_result(guarded_elements);
  std::vector<std::uint16_t> public_result(guarded_elements);
  std::vector<std::uint16_t> replay_result(guarded_elements);
  std::vector<std::uint8_t> weights_after(weight_elements);
  std::vector<std::uint16_t> activations_after(activation_elements);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           predecessor_result.data(), predecessor_guarded.get(),
                           predecessor_result.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded fixed predecessor output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           public_result.data(), public_guarded.get(),
                           public_result.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded public production output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           replay_result.data(), replay_guarded.get(),
                           replay_result.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded replay output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights_after.data(), weights.get(),
                                       weights_after.size(),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " copy weights after launches");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations_after.data(), activations.get(),
                           activations_after.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy activations after launches");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize correctness");
  if (!ready) {
    return;
  }

  std::size_t public_predecessor_mismatches = 0U;
  std::size_t replay_mismatches = 0U;
  std::size_t token_boundary_mismatches = 0U;
  std::size_t unexpected_nonfinite = 0U;
  for (std::size_t index = 0U; index < output_elements; ++index) {
    const std::uint16_t predecessor_bits =
        predecessor_result[kGuardElements + index];
    const std::uint16_t public_bits = public_result[kGuardElements + index];
    const bool mismatch = public_bits != predecessor_bits;
    public_predecessor_mismatches += mismatch ? 1U : 0U;
    replay_mismatches +=
        public_bits != replay_result[kGuardElements + index] ? 1U : 0U;
    const std::size_t token = index / shape.rows;
    token_boundary_mismatches +=
        mismatch && (token == 15U || token == 16U) ? 1U : 0U;
    if (!exhaustive_codebook) {
      unexpected_nonfinite += !is_bf16_finite(public_bits) ? 1U : 0U;
    }
  }
  bool guards_intact = true;
  for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
    guards_intact =
        guards_intact &&
        predecessor_result[guard] == kPredecessorGuard &&
        predecessor_result[kGuardElements + output_elements + guard] ==
            kPredecessorGuard &&
        public_result[guard] == kPublicGuard &&
        public_result[kGuardElements + output_elements + guard] ==
            kPublicGuard &&
        replay_result[guard] == kReplayGuard &&
        replay_result[kGuardElements + output_elements + guard] ==
            kReplayGuard;
  }
  const bool inputs_preserved =
      weights_after == host_weights && activations_after == host_activations;
  bool nan_class_sign_gate = true;
  std::size_t classified_nan_outputs = 0U;
  if (exhaustive_codebook) {
    constexpr std::array<std::uint8_t, 2U> kNanCodes{{0x7fU, 0xffU}};
    for (std::size_t token = 0U; token < kTokens; ++token) {
      for (std::size_t position = 0U; position < 4U; ++position) {
        for (const std::uint8_t code : kNanCodes) {
          const std::size_t row =
              static_cast<std::size_t>(code) * 4U + position;
          const std::size_t index = token * shape.rows + row;
          const std::uint16_t predecessor_bits =
              predecessor_result[kGuardElements + index];
          const std::uint16_t public_bits =
              public_result[kGuardElements + index];
          const std::uint16_t replay_bits =
              replay_result[kGuardElements + index];
          const bool classified =
              is_bf16_nan(predecessor_bits) && is_bf16_nan(public_bits) &&
              is_bf16_nan(replay_bits) &&
              (public_bits & 0x8000U) ==
                  (predecessor_bits & 0x8000U) &&
              public_bits == replay_bits;
          nan_class_sign_gate = nan_class_sign_gate && classified;
          classified_nan_outputs += classified ? 1U : 0U;
        }
      }
    }
    for (std::size_t token = 0U; token < kTokens; ++token) {
      for (std::size_t code = 0U; code < 256U; ++code) {
        if (code == 0x7fU || code == 0xffU) {
          continue;
        }
        for (std::size_t position = 0U; position < 4U; ++position) {
          const std::size_t row = code * 4U + position;
          unexpected_nonfinite +=
              !is_bf16_finite(public_result[
                  kGuardElements + token * shape.rows + row])
                  ? 1U
                  : 0U;
        }
      }
    }
  }
  const std::size_t expected_nan_outputs =
      exhaustive_codebook ? kTokens * 4U * 2U : 0U;
  const bool correctness_gate =
      code_coverage_gate && public_predecessor_mismatches == 0U &&
      replay_mismatches == 0U && token_boundary_mismatches == 0U &&
      guards_intact && inputs_preserved && unexpected_nonfinite == 0U &&
      (!exhaustive_codebook ||
       (nan_class_sign_gate &&
        classified_nan_outputs == expected_nan_outputs));
  std::cout << "FP8_M32_DUAL_RESIDENT_A_DIFF: shape=" << shape.rows << 'x'
            << shape.columns
            << " fixture="
            << (exhaustive_codebook ? "exhaustive_256x4"
                                    : "production_finite")
            << " public_vs_fixed_predecessor_mismatches="
            << public_predecessor_mismatches << '/' << output_elements
            << " dual_direct_replay_mismatches=" << replay_mismatches << '/'
            << output_elements
            << " token15_16_mismatches=" << token_boundary_mismatches
            << " classified_nan_outputs=" << classified_nan_outputs << '/'
            << expected_nan_outputs
            << " unexpected_nonfinite=" << unexpected_nonfinite
            << " guards=" << (guards_intact ? "intact" : "BAD")
            << " inputs_preserved="
            << (inputs_preserved ? "true" : "false")
            << " gate=" << (correctness_gate ? "PASS" : "FAIL") << '\n';
  test.expect(correctness_gate,
              label + " clears predecessor/public/direct-replay/guard/input/"
                      "code gates");

  const Fp8M32CapturedKernel fixed_predecessor_capture =
      capture_fp8_m32_kernel(
          test, stream,
          q3x::kernels::
              launch_sm87_fp8_w8a16_small_m32_wmma_fixed_shape_test_cuda,
          weights.get(), kWeightScale, activations.get(), shape.rows,
          shape.columns, predecessor_output,
          label + " fixed direct predecessor graph");
  const Fp8M32CapturedKernel public_capture = capture_fp8_m32_kernel(
      test, stream,
      q3x::kernels::launch_sm87_fp8_w8a16_m32_gemm_bf16_cuda,
      weights.get(), kWeightScale, activations.get(), shape.rows,
      shape.columns, public_output, label + " public graph");
  const Fp8M32CapturedKernel dual_a_capture = capture_fp8_m32_kernel(
      test, stream,
      q3x::kernels::
          launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda,
      weights.get(), kWeightScale, activations.get(), shape.rows,
      shape.columns, replay_output,
      label + " direct production dual-A graph");
  const auto topology_matches = [&](const Fp8M32CapturedKernel& capture) {
    return capture.valid && capture.grid.x == shape.rows / 128U &&
           capture.grid.y == 1U && capture.grid.z == 1U &&
           capture.block.x == 256U && capture.block.y == 1U &&
           capture.block.z == 1U && capture.dynamic_shared_bytes == 0U;
  };
  const bool graph_gate =
      topology_matches(fixed_predecessor_capture) &&
      topology_matches(public_capture) &&
      topology_matches(dual_a_capture) &&
      public_capture.function == dual_a_capture.function &&
      public_capture.function != fixed_predecessor_capture.function;
  std::cout << "FP8_M32_DUAL_RESIDENT_A_GRAPH: shape=" << shape.rows << 'x'
            << shape.columns
            << " fixed_predecessor_nodes="
            << fixed_predecessor_capture.kernel_nodes
            << " public_nodes=" << public_capture.kernel_nodes
            << " dual_a_nodes=" << dual_a_capture.kernel_nodes
            << " public_dual_same_func="
            << (public_capture.function == dual_a_capture.function ? "true"
                                                                    : "false")
            << " public_fixed_distinct="
            << (public_capture.function != fixed_predecessor_capture.function
                    ? "true"
                    : "false")
            << " grid=" << dual_a_capture.grid.x
            << " block=" << dual_a_capture.block.x
            << " gate=" << (graph_gate ? "PASS" : "FAIL") << '\n';
  test.expect(graph_gate,
              label + " freezes fixed-predecessor/public-dual Graph "
                      "identities");
}

void run_fp8_m32_dual_resident_a_default_screen(TestContext& test,
                                                 cudaStream_t stream) {
  run_fp8_m32_dual_resident_a_resource_gates(test);
  run_fp8_m32_dual_resident_a_invalid_capture_contract(test, stream);
  for (std::size_t index = 0U; index < kFp8M32ProductionShapes.size();
       ++index) {
    run_fp8_m32_dual_resident_a_correctness_case(
        test, stream, kFp8M32ProductionShapes[index], index == 0U);
  }
}

struct Fp8M16WmmaMeasurement {
  double baseline_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
  bool deterministic = false;
  bool within_tolerance = false;
};

[[nodiscard]] Fp8M16WmmaMeasurement benchmark_fp8_m16_wmma_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 16U;
  constexpr std::size_t kHalfTokens = 8U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};

  std::vector<std::uint8_t> host_weights(rows * columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] =
        kFiniteCodes[(index * 7U + index / columns * 5U + 1U) %
                     kFiniteCodes.size()];
  }
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 13U + token * 17U + 3U) % 127U) - 63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  DeviceBuffer<std::uint16_t> replay_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokens * rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokens * rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(replay_output.allocate(kTokens * rows),
                                label + " allocate replay output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed finite weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize token-distinct activations");
  if (!ready) {
    return {};
  }

  const auto launch_baseline = [&]() noexcept -> int {
    int status = q3x::kernels::launch_sm87_fp8_w8a16_small_m_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), kHalfTokens, rows,
        columns, baseline_output.get(), static_cast<void*>(stream));
    if (status != static_cast<int>(cudaSuccess)) {
      return status;
    }
    status = q3x::kernels::launch_sm87_fp8_w8a16_small_m_gemm_bf16_cuda(
        weights.get(), kWeightScale,
        activations.get() + kHalfTokens * columns, kHalfTokens, rows,
        columns, baseline_output.get() + kHalfTokens * rows,
        static_cast<void*>(stream));
    return status;
  };
  const auto launch_candidate = [&]() noexcept -> int {
    if (q3x::kernels::use_sm87_fp8_m16_wmma_fixed_shape_test(rows,
                                                              columns)) {
      return q3x::kernels::launch_sm87_fp8_w8a16_m16_gemm_bf16_cuda(
          weights.get(), kWeightScale, activations.get(), rows, columns,
          candidate_output.get(), static_cast<void*>(stream));
    }
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m16_wmma_fixed_shape_test_cuda(
            weights.get(), kWeightScale, activations.get(), rows, columns,
            candidate_output.get(), static_cast<void*>(stream));
  };
  const auto launch_replay = [&]() noexcept -> int {
    if (q3x::kernels::use_sm87_fp8_m16_wmma_fixed_shape_test(rows,
                                                              columns)) {
      return q3x::kernels::launch_sm87_fp8_w8a16_m16_gemm_bf16_cuda(
          weights.get(), kWeightScale, activations.get(), rows, columns,
          replay_output.get(), static_cast<void*>(stream));
    }
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m16_wmma_fixed_shape_test_cuda(
            weights.get(), kWeightScale, activations.get(), rows, columns,
            replay_output.get(), static_cast<void*>(stream));
  };

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " correctness two-M8 baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " correctness WMMA candidate");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_replay()),
                                label + " deterministic replay");
  std::vector<std::uint16_t> baseline(kTokens * rows);
  std::vector<std::uint16_t> candidate(kTokens * rows);
  std::vector<std::uint16_t> replay(kTokens * rows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           replay.data(), replay_output.get(),
                           replay.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy replay output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " correctness synchronize");
  if (!ready) {
    return {};
  }

  std::size_t bf16_mismatches = 0U;
  std::size_t deterministic_mismatches = 0U;
  float maximum_absolute_error = 0.0F;
  float maximum_relative_error = 0.0F;
  bool within_tolerance = true;
  for (std::size_t index = 0U; index < candidate.size(); ++index) {
    bf16_mismatches += candidate[index] != baseline[index] ? 1U : 0U;
    deterministic_mismatches += candidate[index] != replay[index] ? 1U : 0U;
    if (is_bf16_nan(baseline[index])) {
      within_tolerance =
          within_tolerance && is_bf16_nan(candidate[index]);
      continue;
    }
    const float baseline_value = decode_bf16(baseline[index]);
    const float candidate_value = decode_bf16(candidate[index]);
    const float absolute_error =
        std::fabs(candidate_value - baseline_value);
    const float relative_error =
        absolute_error / std::max(1.0e-6F, std::fabs(baseline_value));
    maximum_absolute_error =
        std::max(maximum_absolute_error, absolute_error);
    maximum_relative_error =
        std::max(maximum_relative_error, relative_error);
    const float tolerance =
        2.0e-4F * std::sqrt(static_cast<float>(columns)) +
        1.0e-2F * std::max(1.0F, std::fabs(baseline_value));
    within_tolerance = within_tolerance &&
                       std::isfinite(candidate_value) &&
                       std::isfinite(baseline_value) &&
                       absolute_error <= tolerance;
  }
  bool deterministic = deterministic_mismatches == 0U;
  std::cout << "FP8_M16_WMMA_DIFF: " << label
            << " candidate_vs_two_m8_bf16="
            << bf16_mismatches << '/' << candidate.size()
            << " deterministic_mismatches=" << deterministic_mismatches
            << '/' << candidate.size()
            << " max_abs=" << maximum_absolute_error
            << " max_rel=" << maximum_relative_error
            << " tolerance_gate=" << (within_tolerance ? "PASS" : "FAIL")
            << '\n';
  test.expect(deterministic,
              label + " reproduces every M16 BF16 output bitwise");
  test.expect(within_tolerance,
              label + " clears the existing FP8 numerical tolerance");
  compare_cuda_reference_outputs(test, candidate, baseline, columns,
                                 label + " candidate vs two M8");

  ready = test.cuda_ok(
      static_cast<cudaError_t>(
          q3x::kernels::launch_sm87_fp8_w8a16_m16_gemm_bf16_cuda(
              weights.get(), kWeightScale, activations.get(), rows, columns,
              replay_output.get(), static_cast<void*>(stream))),
      label + " public M16 selection launch");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           replay.data(), replay_output.get(),
                           replay.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy public M16 selection output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " public M16 selection synchronize");
  if (!ready) {
    return {};
  }
  const bool public_uses_wmma =
      q3x::kernels::use_sm87_fp8_m16_wmma_fixed_shape_test(rows, columns);
  const std::vector<std::uint16_t>& public_expected =
      public_uses_wmma ? candidate : baseline;
  std::size_t public_selection_mismatches = 0U;
  for (std::size_t index = 0U; index < replay.size(); ++index) {
    public_selection_mismatches +=
        replay[index] != public_expected[index] ? 1U : 0U;
  }
  const bool public_selection_matches = public_selection_mismatches == 0U;
  std::cout << "FP8_M16_PUBLIC_SELECTION_DIFF: " << label
            << " selected=" << (public_uses_wmma ? "wmma_m16" : "two_m8")
            << " mismatches=" << public_selection_mismatches << '/'
            << replay.size() << '\n';
  test.expect(public_selection_matches,
              label + " public M16 selects the required production path");
  deterministic = deterministic && public_selection_matches;
  within_tolerance = within_tolerance && public_selection_matches;

  // The /256 timing fixture often makes distinct FP32 reduction trees land
  // on identical BF16 values. Exercise the primary shape once more with
  // odd, non-power-of-two divisors and values spanning twelve exponents.
  if (rows == 10'240U && columns == 5'120U) {
    std::vector<std::uint16_t> nonpower_activations(kTokens * columns);
    for (std::size_t token = 0U; token < kTokens; ++token) {
      for (std::size_t column = 0U; column < columns; ++column) {
        const int centered =
            static_cast<int>((column * 37U + token * 19U + 11U) % 61U) - 30;
        const int odd_denominator =
            3 + 2 * static_cast<int>((column * 7U + token * 5U) % 15U);
        const int exponent =
            static_cast<int>((column * 11U + token * 3U) % 12U) - 6;
        const float value = std::ldexp(
            static_cast<float>(centered) /
                static_cast<float>(odd_denominator),
            exponent);
        nonpower_activations[token * columns + column] = encode_bf16(value);
      }
    }
    ready = test.cuda_ok(
        cudaMemcpyAsync(
            activations.get(), nonpower_activations.data(),
            nonpower_activations.size() * sizeof(std::uint16_t),
            cudaMemcpyHostToDevice, stream),
        label + " initialize nonpower cross-exponent activations");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         label + " nonpower two-M8 baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " nonpower WMMA candidate");
    ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_replay()),
                                  label + " nonpower deterministic replay");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy nonpower baseline output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy nonpower candidate output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             replay.data(), replay_output.get(),
                             replay.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy nonpower replay output");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " nonpower synchronize");
    if (!ready) {
      return {};
    }

    std::size_t nonpower_bf16_mismatches = 0U;
    std::size_t nonpower_deterministic_mismatches = 0U;
    float nonpower_maximum_absolute_error = 0.0F;
    float nonpower_maximum_relative_error = 0.0F;
    bool nonpower_within_tolerance = true;
    for (std::size_t index = 0U; index < candidate.size(); ++index) {
      nonpower_bf16_mismatches +=
          candidate[index] != baseline[index] ? 1U : 0U;
      nonpower_deterministic_mismatches +=
          candidate[index] != replay[index] ? 1U : 0U;
      if (is_bf16_nan(baseline[index])) {
        nonpower_within_tolerance =
            nonpower_within_tolerance && is_bf16_nan(candidate[index]);
        continue;
      }
      const float baseline_value = decode_bf16(baseline[index]);
      const float candidate_value = decode_bf16(candidate[index]);
      const float absolute_error =
          std::fabs(candidate_value - baseline_value);
      const float relative_error =
          absolute_error / std::max(1.0e-6F, std::fabs(baseline_value));
      nonpower_maximum_absolute_error =
          std::max(nonpower_maximum_absolute_error, absolute_error);
      nonpower_maximum_relative_error =
          std::max(nonpower_maximum_relative_error, relative_error);
      const float tolerance =
          2.0e-4F * std::sqrt(static_cast<float>(columns)) +
          1.0e-2F * std::max(1.0F, std::fabs(baseline_value));
      nonpower_within_tolerance =
          nonpower_within_tolerance && std::isfinite(candidate_value) &&
          std::isfinite(baseline_value) && absolute_error <= tolerance;
    }
    const bool nonpower_deterministic =
        nonpower_deterministic_mismatches == 0U;
    std::cout << "FP8_M16_WMMA_NONPOWER_DIFF: " << label
              << " candidate_vs_two_m8_bf16=" << nonpower_bf16_mismatches
              << '/' << candidate.size()
              << " deterministic_mismatches="
              << nonpower_deterministic_mismatches << '/' << candidate.size()
              << " max_abs=" << nonpower_maximum_absolute_error
              << " max_rel=" << nonpower_maximum_relative_error
              << " tolerance_gate="
              << (nonpower_within_tolerance ? "PASS" : "FAIL") << '\n';
    test.expect(nonpower_deterministic,
                label + " nonpower activation replay is deterministic");
    test.expect(nonpower_within_tolerance,
                label + " nonpower activations clear numerical tolerance");
    compare_cuda_reference_outputs(
        test, candidate, baseline, columns,
        label + " nonpower candidate vs two M8");
    deterministic = deterministic && nonpower_deterministic;
    within_tolerance = within_tolerance && nonpower_within_tolerance;

    ready = test.cuda_ok(
        cudaMemcpyAsync(
            activations.get(), host_activations.data(),
            host_activations.size() * sizeof(std::uint16_t),
            cudaMemcpyHostToDevice, stream),
        label + " restore timing activations");
  }

  for (int iteration = 0; iteration < kWarmupIterations && ready;
       ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " baseline warmup");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " candidate warmup");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return {};
  }

  double baseline_total = 0.0;
  double candidate_total = 0.0;
  bool finite = true;
  for (int round = 0; round < kMeasurementRounds; ++round) {
    const std::string suffix = " round=" + std::to_string(round + 1);
    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 1" + suffix);
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 1" + suffix);
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 2" + suffix);
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 2" + suffix);
    const bool round_finite =
        std::isfinite(baseline_first) && std::isfinite(candidate_first) &&
        std::isfinite(candidate_second) && std::isfinite(baseline_second);
    finite = finite && round_finite;
    if (round_finite) {
      baseline_total += baseline_first + baseline_second;
      candidate_total += candidate_first + candidate_second;
    }
    std::cout << "PERF_FP8_M16_WMMA_ROUND: " << label
              << " round=" << round + 1
              << " baseline_pass1_ms=" << baseline_first
              << " candidate_pass1_ms=" << candidate_first
              << " candidate_pass2_ms=" << candidate_second
              << " baseline_pass2_ms=" << baseline_second << '\n';
  }
  constexpr double kTimedPasses =
      2.0 * static_cast<double>(kMeasurementRounds);
  const double baseline_average = baseline_total / kTimedPasses;
  const double candidate_average = candidate_total / kTimedPasses;
  const double speedup = baseline_average / candidate_average;
  std::cout << "PERF_FP8_M16_WMMA: " << label
            << " baseline_two_m8_ms="
            << baseline_average << " candidate_m16_ms=" << candidate_average
            << " speedup=" << speedup << '\n';

  if (columns == 5'120U && rows != 1'024U) {
    const auto launch_ldm64 = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_small_m16_wmma_shared_ldm_test_cuda(
              weights.get(), kWeightScale, activations.get(), rows, columns,
              candidate_output.get(), 64U, static_cast<void*>(stream));
    };
    const auto launch_ldm72 = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_fp8_w8a16_small_m16_wmma_shared_ldm_test_cuda(
              weights.get(), kWeightScale, activations.get(), rows, columns,
              replay_output.get(), 72U, static_cast<void*>(stream));
    };

    ready = test.cuda_ok(static_cast<cudaError_t>(launch_ldm64()),
                         label + " ldm64 correctness launch");
    ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_ldm72()),
                                  label + " ldm72 correctness launch");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy ldm64 output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             replay.data(), replay_output.get(),
                             replay.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy ldm72 output");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " ldm correctness synchronize");
    if (!ready) {
      return {};
    }
    std::size_t ldm_mismatches = 0U;
    for (std::size_t index = 0U; index < candidate.size(); ++index) {
      ldm_mismatches += candidate[index] != replay[index] ? 1U : 0U;
    }
    const bool ldm_bitwise_equal = ldm_mismatches == 0U;
    std::cout << "FP8_M16_WMMA_LDM_DIFF: " << label
              << " ldm64_vs_ldm72_bf16=" << ldm_mismatches << '/'
              << candidate.size() << '\n';
    test.expect(ldm_bitwise_equal,
                label + " ldm64 and ldm72 are bitwise identical");
    deterministic = deterministic && ldm_bitwise_equal;
    within_tolerance = within_tolerance && ldm_bitwise_equal;

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_ldm64()),
                           label + " ldm64 warmup");
      ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_ldm72()),
                                    label + " ldm72 warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " ldm warmup synchronize");
    if (!ready) {
      return {};
    }

    double ldm64_total = 0.0;
    double ldm72_total = 0.0;
    bool ldm_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string suffix = " round=" + std::to_string(round + 1);
      const float ldm64_first = measure_small_m_tile(
          test, stream, launch_ldm64, kMeasuredIterations,
          label + " ldm64 pass 1" + suffix);
      const float ldm72_first = measure_small_m_tile(
          test, stream, launch_ldm72, kMeasuredIterations,
          label + " ldm72 pass 1" + suffix);
      const float ldm72_second = measure_small_m_tile(
          test, stream, launch_ldm72, kMeasuredIterations,
          label + " ldm72 pass 2" + suffix);
      const float ldm64_second = measure_small_m_tile(
          test, stream, launch_ldm64, kMeasuredIterations,
          label + " ldm64 pass 2" + suffix);
      const bool round_finite =
          std::isfinite(ldm64_first) && std::isfinite(ldm72_first) &&
          std::isfinite(ldm72_second) && std::isfinite(ldm64_second);
      ldm_finite = ldm_finite && round_finite;
      if (round_finite) {
        ldm64_total += ldm64_first + ldm64_second;
        ldm72_total += ldm72_first + ldm72_second;
      }
      std::cout << "PERF_FP8_M16_WMMA_LDM_ROUND: " << label
                << " round=" << round + 1
                << " ldm64_pass1_ms=" << ldm64_first
                << " ldm72_pass1_ms=" << ldm72_first
                << " ldm72_pass2_ms=" << ldm72_second
                << " ldm64_pass2_ms=" << ldm64_second << '\n';
    }
    const double ldm64_average = ldm64_total / kTimedPasses;
    const double ldm72_average = ldm72_total / kTimedPasses;
    const double ldm72_speedup = ldm64_average / ldm72_average;
    finite = finite && ldm_finite && std::isfinite(ldm72_speedup);
    std::cout << "PERF_FP8_M16_WMMA_LDM: " << label
              << " ldm64_ms=" << ldm64_average
              << " ldm72_ms=" << ldm72_average
              << " ldm72_speedup=" << ldm72_speedup << '\n';
    test.expect(ldm_finite && std::isfinite(ldm72_speedup),
                label + " ldm64/ldm72 mirrored timing is finite");
  }

  // Performance is already frozen above. Reuse the primary-shape buffers to
  // cover every E4M3FN code in every byte position, including both reserved
  // NaN encodings, without contaminating the timing fixture.
  if (rows == 10'240U && columns == 5'120U) {
    std::fill(host_weights.begin(), host_weights.end(), 0U);
    constexpr std::size_t kCodes = 256U;
    constexpr std::size_t kBytePositions = 4U;
    for (std::size_t code = 0U; code < kCodes; ++code) {
      for (std::size_t byte_position = 0U;
           byte_position < kBytePositions; ++byte_position) {
        const std::size_t row = code * kBytePositions + byte_position;
        const std::size_t packed_word =
            (code * 29U + byte_position * 31U) % (columns / 4U);
        const std::size_t column = packed_word * 4U + byte_position;
        host_weights[row * columns + column] =
            static_cast<std::uint8_t>(code);
      }
    }
    std::vector<std::uint16_t> exhaustive_activations(kTokens * columns);
    for (std::size_t token = 0U; token < kTokens; ++token) {
      for (std::size_t column = 0U; column < columns; ++column) {
        const int magnitude =
            1 + static_cast<int>((column * 13U + token * 7U) % 29U);
        const int numerator =
            ((column + token) & 1U) == 0U ? magnitude : -magnitude;
        const int odd_denominator =
            3 + 2 * static_cast<int>((column * 5U + token * 3U) % 11U);
        const int exponent =
            static_cast<int>((column * 3U + token * 5U) % 8U) - 4;
        exhaustive_activations[token * columns + column] = encode_bf16(
            std::ldexp(static_cast<float>(numerator) /
                           static_cast<float>(odd_denominator),
                       exponent));
      }
    }
    ready = test.cuda_ok(
        cudaMemcpyAsync(weights.get(), host_weights.data(),
                        host_weights.size(), cudaMemcpyHostToDevice, stream),
        label + " initialize exhaustive FP8 byte-position weights");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             activations.get(), exhaustive_activations.data(),
                             exhaustive_activations.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyHostToDevice, stream),
                         label + " initialize exhaustive activations");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         label + " exhaustive two-M8 baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " exhaustive WMMA candidate");
    ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_replay()),
                                  label + " exhaustive deterministic replay");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy exhaustive baseline output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy exhaustive candidate output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             replay.data(), replay_output.get(),
                             replay.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy exhaustive replay output");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " exhaustive synchronize");
    if (!ready) {
      return {};
    }

    std::size_t exhaustive_bf16_mismatches = 0U;
    std::size_t exhaustive_deterministic_mismatches = 0U;
    std::size_t reference_nan_count = 0U;
    std::size_t nan_class_mismatches = 0U;
    float exhaustive_maximum_absolute_error = 0.0F;
    float exhaustive_maximum_relative_error = 0.0F;
    bool exhaustive_within_tolerance = true;
    for (std::size_t index = 0U; index < candidate.size(); ++index) {
      exhaustive_bf16_mismatches +=
          candidate[index] != baseline[index] ? 1U : 0U;
      exhaustive_deterministic_mismatches +=
          candidate[index] != replay[index] ? 1U : 0U;
      if (is_bf16_nan(baseline[index])) {
        ++reference_nan_count;
        const bool candidate_is_nan = is_bf16_nan(candidate[index]);
        nan_class_mismatches += candidate_is_nan ? 0U : 1U;
        exhaustive_within_tolerance =
            exhaustive_within_tolerance && candidate_is_nan;
        continue;
      }
      const float baseline_value = decode_bf16(baseline[index]);
      const float candidate_value = decode_bf16(candidate[index]);
      const float absolute_error =
          std::fabs(candidate_value - baseline_value);
      const float relative_error =
          absolute_error / std::max(1.0e-6F, std::fabs(baseline_value));
      exhaustive_maximum_absolute_error =
          std::max(exhaustive_maximum_absolute_error, absolute_error);
      exhaustive_maximum_relative_error =
          std::max(exhaustive_maximum_relative_error, relative_error);
      const float tolerance =
          2.0e-4F * std::sqrt(static_cast<float>(columns)) +
          1.0e-2F * std::max(1.0F, std::fabs(baseline_value));
      exhaustive_within_tolerance =
          exhaustive_within_tolerance && std::isfinite(candidate_value) &&
          std::isfinite(baseline_value) && absolute_error <= tolerance;
    }
    constexpr std::size_t kExpectedNanOutputs =
        2U * kBytePositions * kTokens;
    const bool exhaustive_deterministic =
        exhaustive_deterministic_mismatches == 0U;
    const bool nan_coverage = reference_nan_count == kExpectedNanOutputs &&
                              nan_class_mismatches == 0U;
    std::cout << "FP8_M16_WMMA_EXHAUSTIVE_DIFF: " << label
              << " candidate_vs_two_m8_bf16="
              << exhaustive_bf16_mismatches << '/' << candidate.size()
              << " deterministic_mismatches="
              << exhaustive_deterministic_mismatches << '/'
              << candidate.size() << " reference_nan_count="
              << reference_nan_count
              << " nan_class_mismatches=" << nan_class_mismatches
              << " max_abs=" << exhaustive_maximum_absolute_error
              << " max_rel=" << exhaustive_maximum_relative_error
              << " tolerance_gate="
              << (exhaustive_within_tolerance ? "PASS" : "FAIL") << '\n';
    test.expect(exhaustive_deterministic,
                label + " exhaustive replay is deterministic");
    test.expect(nan_coverage,
                label + " covers both NaN codes in all byte positions");
    test.expect(exhaustive_within_tolerance,
                label + " exhaustive codes clear numerical tolerance");
    compare_cuda_reference_outputs(
        test, candidate, baseline, columns,
        label + " exhaustive candidate vs two M8");
    deterministic = deterministic && exhaustive_deterministic;
    within_tolerance = within_tolerance && exhaustive_within_tolerance &&
                       nan_coverage;
  }

  return {finite ? baseline_average
                 : std::numeric_limits<double>::quiet_NaN(),
          finite ? candidate_average
                 : std::numeric_limits<double>::quiet_NaN(),
          deterministic, within_tolerance};
}

void run_optional_fp8_m16_wmma_performance(TestContext& test,
                                            cudaStream_t stream) {
  if (!fp8_m16_wmma_performance_enabled()) {
    std::cout << "SKIP: FP8 M16 WMMA performance segment; set "
                 "Q3X_RUN_SM87_FP8_M16_WMMA_PERF=1 to enable\n";
    return;
  }

  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t calls_per_prompt;
    double minimum_speedup;
    bool allow_fallback;
    const char* label;
  };
  constexpr std::array<Shape, 5U> kShapes{{
      {10'240U, 5'120U, 96U, 1.15, false,
       "FP8 M16 WMMA 10240x5120"},
      {5'120U, 6'144U, 128U, 1.05, false,
       "FP8 M16 WMMA 5120x6144"},
      {6'144U, 5'120U, 96U, 1.05, false,
       "FP8 M16 WMMA 6144x5120"},
      {12'288U, 5'120U, 32U, 1.05, false,
       "FP8 M16 WMMA 12288x5120"},
      {1'024U, 5'120U, 64U, 1.05, true,
       "FP8 M16 WMMA 1024x5120"},
  }};
  std::array<Fp8M16WmmaMeasurement, kShapes.size()> measurements{};
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    measurements[index] = benchmark_fp8_m16_wmma_shape(
        test, stream, kShapes[index].rows, kShapes[index].columns,
        kShapes[index].label);
  }

  double weighted_baseline = 0.0;
  double weighted_raw_candidate = 0.0;
  double weighted_selected_candidate = 0.0;
  bool required_shapes_pass = true;
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    const Fp8M16WmmaMeasurement& measurement = measurements[index];
    const double speedup = measurement.baseline_milliseconds /
                           measurement.candidate_milliseconds;
    const bool finite =
        std::isfinite(measurement.baseline_milliseconds) &&
        std::isfinite(measurement.candidate_milliseconds) &&
        std::isfinite(speedup);
    const bool raw_performance_gate =
        finite && speedup >= kShapes[index].minimum_speedup;
    const bool selected_fallback =
        kShapes[index].allow_fallback && finite && !raw_performance_gate;
    const bool shape_gate =
        measurement.deterministic && measurement.within_tolerance &&
        (raw_performance_gate || selected_fallback);
    required_shapes_pass = required_shapes_pass && shape_gate;
    test.expect(shape_gate,
                std::string(kShapes[index].label) +
                    " clears correctness and selected performance policy");

    weighted_baseline +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        measurement.baseline_milliseconds;
    weighted_raw_candidate +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        measurement.candidate_milliseconds;
    weighted_selected_candidate +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        (selected_fallback ? measurement.baseline_milliseconds
                           : measurement.candidate_milliseconds);
    std::cout << "PERF_FP8_M16_WMMA_VALIDATION: " << kShapes[index].label
              << " baseline_two_m8_ms="
              << measurement.baseline_milliseconds
              << " candidate_m16_ms=" << measurement.candidate_milliseconds
              << " speedup=" << speedup
              << " minimum_speedup=" << kShapes[index].minimum_speedup
              << " selected="
              << (selected_fallback ? "two_m8_fallback" : "wmma_m16")
              << " gate=" << (shape_gate ? "PASS" : "FAIL") << '\n';
  }
  const double raw_weighted_speedup =
      weighted_baseline / weighted_raw_candidate;
  const double selected_weighted_speedup =
      weighted_baseline / weighted_selected_candidate;
  constexpr double kMinimumSelectedWeightedSpeedup = 1.05;
  const bool aggregate_gate =
      required_shapes_pass && std::isfinite(selected_weighted_speedup) &&
      selected_weighted_speedup >= kMinimumSelectedWeightedSpeedup;
  std::cout << "PERF_FP8_M16_WMMA_AGGREGATE: weighted_baseline_two_m8_ms="
            << weighted_baseline
            << " weighted_raw_candidate_ms=" << weighted_raw_candidate
            << " raw_speedup=" << raw_weighted_speedup
            << " weighted_selected_candidate_ms="
            << weighted_selected_candidate
            << " selected_speedup=" << selected_weighted_speedup
            << " required_selected_speedup="
            << kMinimumSelectedWeightedSpeedup
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL")
            << '\n';
  test.expect(aggregate_gate,
              "FP8 M16 WMMA selected shapes clear weighted speedup gate");
}

struct Fp8M32WmmaMeasurement {
  double baseline_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
  bool bitwise_equal = false;
  bool deterministic = false;
  bool guards_intact = false;
};

[[nodiscard]] Fp8M32WmmaMeasurement benchmark_fp8_m32_wmma_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 32U;
  constexpr std::size_t kPanelTokens = 16U;
  constexpr std::size_t kGuardElements = 64U;
  constexpr std::uint16_t kCandidateGuard = 0xa5a5U;
  constexpr std::uint16_t kReplayGuard = 0x5a5aU;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};

  std::vector<std::uint8_t> host_weights(rows * columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] =
        kFiniteCodes[(index * 7U + index / columns * 5U + 1U) %
                     kFiniteCodes.size()];
  }
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 13U + token * 17U + 3U) % 127U) - 63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  const std::size_t output_elements = kTokens * rows;
  const std::size_t guarded_elements = output_elements + 2U * kGuardElements;
  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_guarded;
  DeviceBuffer<std::uint16_t> replay_guarded;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(output_elements),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_guarded.allocate(guarded_elements),
                                label + " allocate guarded candidate output");
  ready = ready && test.cuda_ok(replay_guarded.allocate(guarded_elements),
                                label + " allocate guarded replay output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(candidate_guarded.get(), 0xa5,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison candidate guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(replay_guarded.get(), 0x5a,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison replay guards");
  if (!ready) {
    return {};
  }

  std::uint16_t* const candidate_output =
      candidate_guarded.get() + kGuardElements;
  std::uint16_t* const replay_output =
      replay_guarded.get() + kGuardElements;
  const auto launch_baseline = [&]() noexcept -> int {
    int status = q3x::kernels::launch_sm87_fp8_w8a16_m16_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), rows, columns,
        baseline_output.get(), static_cast<void*>(stream));
    if (status != static_cast<int>(cudaSuccess)) {
      return status;
    }
    return q3x::kernels::launch_sm87_fp8_w8a16_m16_gemm_bf16_cuda(
        weights.get(), kWeightScale,
        activations.get() + kPanelTokens * columns, rows, columns,
        baseline_output.get() + kPanelTokens * rows,
        static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_fp8_w8a16_m32_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), rows, columns,
        candidate_output, static_cast<void*>(stream));
  };
  const auto launch_replay = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_fp8_w8a16_m32_gemm_bf16_cuda(
        weights.get(), kWeightScale, activations.get(), rows, columns,
        replay_output, static_cast<void*>(stream));
  };

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " launch two-public-M16 baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " launch M32 candidate");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_replay()),
                                label + " launch M32 replay");
  std::vector<std::uint16_t> baseline(output_elements);
  std::vector<std::uint16_t> candidate(guarded_elements);
  std::vector<std::uint16_t> replay(guarded_elements);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_guarded.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded candidate");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(replay.data(), replay_guarded.get(),
                                       replay.size() * sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded replay");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " correctness synchronize");
  if (!ready) {
    return {};
  }

  std::size_t bf16_mismatches = 0U;
  std::size_t replay_mismatches = 0U;
  std::size_t token_boundary_mismatches = 0U;
  for (std::size_t index = 0U; index < output_elements; ++index) {
    const std::uint16_t candidate_value =
        candidate[kGuardElements + index];
    const bool differs = candidate_value != baseline[index];
    bf16_mismatches += differs ? 1U : 0U;
    replay_mismatches +=
        candidate_value != replay[kGuardElements + index] ? 1U : 0U;
    const std::size_t token = index / rows;
    token_boundary_mismatches +=
        differs && (token == 15U || token == 16U) ? 1U : 0U;
  }
  bool guards_intact = true;
  for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
    guards_intact =
        guards_intact && candidate[guard] == kCandidateGuard &&
        candidate[kGuardElements + output_elements + guard] ==
            kCandidateGuard &&
        replay[guard] == kReplayGuard &&
        replay[kGuardElements + output_elements + guard] == kReplayGuard;
  }
  const bool bitwise_equal = bf16_mismatches == 0U;
  const bool deterministic = replay_mismatches == 0U;
  std::cout << "FP8_M32_WMMA_DIFF: " << label
            << " candidate_vs_two_public_m16_bf16=" << bf16_mismatches
            << '/' << output_elements
            << " replay_mismatches=" << replay_mismatches << '/'
            << output_elements
            << " token15_16_mismatches=" << token_boundary_mismatches
            << " output_guards=" << (guards_intact ? "intact" : "BAD")
            << '\n';
  test.expect(bitwise_equal,
              label + " is bit-exact to two public M16 launches");
  test.expect(deterministic, label + " replay is bit-exact");
  test.expect(guards_intact, label + " preserves head and tail guards");

  for (int iteration = 0; iteration < kWarmupIterations && ready;
       ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " baseline warmup");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " candidate warmup");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return {};
  }

  double baseline_total = 0.0;
  double candidate_total = 0.0;
  bool finite = true;
  for (int round = 0; round < kMeasurementRounds; ++round) {
    const std::string suffix = " round=" + std::to_string(round + 1);
    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 1" + suffix);
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 1" + suffix);
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " candidate pass 2" + suffix);
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " baseline pass 2" + suffix);
    const bool round_finite =
        std::isfinite(baseline_first) && std::isfinite(candidate_first) &&
        std::isfinite(candidate_second) && std::isfinite(baseline_second);
    finite = finite && round_finite;
    if (round_finite) {
      baseline_total += baseline_first + baseline_second;
      candidate_total += candidate_first + candidate_second;
    }
    std::cout << "PERF_FP8_M32_WMMA_ROUND: " << label
              << " round=" << round + 1
              << " baseline_pass1_ms=" << baseline_first
              << " candidate_pass1_ms=" << candidate_first
              << " candidate_pass2_ms=" << candidate_second
              << " baseline_pass2_ms=" << baseline_second << '\n';
  }
  constexpr double kTimedPasses =
      2.0 * static_cast<double>(kMeasurementRounds);
  const double baseline_average = baseline_total / kTimedPasses;
  const double candidate_average = candidate_total / kTimedPasses;
  std::cout << "PERF_FP8_M32_WMMA: " << label
            << " baseline_two_public_m16_ms=" << baseline_average
            << " candidate_single_m32_ms=" << candidate_average
            << " speedup=" << baseline_average / candidate_average << '\n';
  return {finite ? baseline_average
                 : std::numeric_limits<double>::quiet_NaN(),
          finite ? candidate_average
                 : std::numeric_limits<double>::quiet_NaN(),
          bitwise_equal, deterministic, guards_intact};
}

void run_optional_fp8_m32_wmma_performance(TestContext& test,
                                            cudaStream_t stream) {
  if (!fp8_m32_wmma_performance_enabled()) {
    std::cout << "SKIP: FP8 M32 WMMA performance segment; set "
                 "Q3X_RUN_SM87_FP8_M32_WMMA_PERF=1 to enable\n";
    return;
  }

  constexpr double kMinimumPerShapeSpeedup = 1.05;
  constexpr double kMinimumWeightedSpeedup = 1.10;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t m32_calls_per_prompt;
    const char* label;
  };
  constexpr std::array<Shape, 4U> kShapes{{
      {10'240U, 5'120U, 48U, "FP8 M32 WMMA 10240x5120"},
      {5'120U, 6'144U, 64U, "FP8 M32 WMMA 5120x6144"},
      {6'144U, 5'120U, 48U, "FP8 M32 WMMA 6144x5120"},
      {12'288U, 5'120U, 16U, "FP8 M32 WMMA 12288x5120"},
  }};
  std::array<Fp8M32WmmaMeasurement, kShapes.size()> measurements{};
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    measurements[index] = benchmark_fp8_m32_wmma_shape(
        test, stream, kShapes[index].rows, kShapes[index].columns,
        kShapes[index].label);
  }

  double weighted_baseline = 0.0;
  double weighted_candidate = 0.0;
  bool all_shapes_pass = true;
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    const Fp8M32WmmaMeasurement& measurement = measurements[index];
    const double speedup = measurement.baseline_milliseconds /
                           measurement.candidate_milliseconds;
    const bool finite =
        std::isfinite(measurement.baseline_milliseconds) &&
        std::isfinite(measurement.candidate_milliseconds) &&
        std::isfinite(speedup);
    const bool shape_gate =
        finite && measurement.bitwise_equal && measurement.deterministic &&
        measurement.guards_intact && speedup >= kMinimumPerShapeSpeedup;
    all_shapes_pass = all_shapes_pass && shape_gate;
    weighted_baseline +=
        static_cast<double>(kShapes[index].m32_calls_per_prompt) *
        measurement.baseline_milliseconds;
    weighted_candidate +=
        static_cast<double>(kShapes[index].m32_calls_per_prompt) *
        measurement.candidate_milliseconds;
    std::cout << "PERF_FP8_M32_WMMA_VALIDATION: " << kShapes[index].label
              << " baseline_two_public_m16_ms="
              << measurement.baseline_milliseconds
              << " candidate_single_m32_ms="
              << measurement.candidate_milliseconds
              << " speedup=" << speedup
              << " minimum_speedup=" << kMinimumPerShapeSpeedup
              << " gate=" << (shape_gate ? "PASS" : "FAIL") << '\n';
    test.expect(shape_gate,
                std::string(kShapes[index].label) +
                    " clears bit-exact/guard/per-shape performance gates");
  }
  const double weighted_speedup = weighted_baseline / weighted_candidate;
  const bool aggregate_gate =
      all_shapes_pass && std::isfinite(weighted_speedup) &&
      weighted_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_FP8_M32_WMMA_AGGREGATE: "
            << "weighted_baseline_two_public_m16_ms=" << weighted_baseline
            << " weighted_candidate_single_m32_ms=" << weighted_candidate
            << " speedup=" << weighted_speedup
            << " required_speedup=" << kMinimumWeightedSpeedup
            << " m32_projection_calls=48:64:48:16"
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "FP8 M32 WMMA clears the weighted production-shape gate");
}

struct Fp8M32DualResidentAMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool every_round_bitwise = false;
  bool guards_intact = false;
};

[[nodiscard]] Fp8M32DualResidentAMeasurement
benchmark_fp8_m32_dual_resident_a_shape(
    TestContext& test, cudaStream_t stream,
    const Fp8M32ProductionShape& shape) {
  constexpr std::size_t kTokens = 32U;
  constexpr std::size_t kGuardElements = 64U;
  constexpr std::uint16_t kPredecessorGuard = 0x3c3cU;
  constexpr std::uint16_t kCandidateFirstGuard = 0xa5a5U;
  constexpr std::uint16_t kCandidateSecondGuard = 0x5a5aU;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 80;
  constexpr int kMeasurementRounds = 5;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 16U> kCheckpointLikeCodes{{
      0x00U, 0x80U, 0x18U, 0x20U, 0x28U, 0x30U, 0x38U, 0x3cU,
      0xb8U, 0x40U, 0xc0U, 0x48U, 0x50U, 0xd0U, 0x70U, 0xf0U,
  }};
  const std::string label =
      std::string(shape.label) +
      " frozen fixed-predecessor-vs-production-dual-A perf";
  const std::size_t output_elements = kTokens * shape.rows;
  const std::size_t guarded_elements = output_elements + 2U * kGuardElements;
  std::vector<std::uint8_t> host_weights(shape.rows * shape.columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] = kCheckpointLikeCodes[
        (index * 5U + (index / shape.columns) * 11U +
         (index % shape.columns >> 4U)) %
        kCheckpointLikeCodes.size()];
  }
  std::vector<std::uint16_t> host_activations(kTokens * shape.columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < shape.columns; ++column) {
      const int centered = static_cast<int>(
                               (column * 13U + token * 17U + 3U) % 127U) -
                           63;
      host_activations[token * shape.columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_guarded;
  DeviceBuffer<std::uint16_t> candidate_first_guarded;
  DeviceBuffer<std::uint16_t> candidate_second_guarded;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_guarded.allocate(guarded_elements),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(
                       candidate_first_guarded.allocate(guarded_elements),
                       label + " allocate candidate first output");
  ready = ready && test.cuda_ok(
                       candidate_second_guarded.allocate(guarded_elements),
                       label + " allocate candidate second output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize checkpoint-like weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(baseline_guarded.get(), 0x3c,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison baseline guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(candidate_first_guarded.get(), 0xa5,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison candidate first guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(candidate_second_guarded.get(), 0x5a,
                                       guarded_elements *
                                           sizeof(std::uint16_t),
                                       stream),
                       label + " poison candidate second guards");
  if (!ready) {
    return {};
  }

  std::uint16_t* const baseline_output =
      baseline_guarded.get() + kGuardElements;
  std::uint16_t* const candidate_first_output =
      candidate_first_guarded.get() + kGuardElements;
  std::uint16_t* const candidate_second_output =
      candidate_second_guarded.get() + kGuardElements;
  const auto launch_baseline = [&]() noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_fixed_shape_test_cuda(
            weights.get(), kWeightScale, activations.get(), shape.rows,
            shape.columns, baseline_output, static_cast<void*>(stream));
  };
  const auto launch_candidate_first = [&]() noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda(
            weights.get(), kWeightScale, activations.get(), shape.rows,
            shape.columns, candidate_first_output,
            static_cast<void*>(stream));
  };
  const auto launch_candidate_second = [&]() noexcept {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m32_wmma_dual_resident_a_test_cuda(
            weights.get(), kWeightScale, activations.get(), shape.rows,
            shape.columns, candidate_second_output,
            static_cast<void*>(stream));
  };

  for (int iteration = 0; iteration < kWarmupIterations && ready;
       ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " fixed predecessor warmup");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate_first()),
                         label + " candidate warmup");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return {};
  }

  constexpr std::size_t kPasses =
      2U * static_cast<std::size_t>(kMeasurementRounds);
  std::array<float, kPasses> baseline_passes{};
  std::array<float, kPasses> candidate_passes{};
  std::vector<std::uint16_t> baseline_result(guarded_elements);
  std::vector<std::uint16_t> candidate_first_result(guarded_elements);
  std::vector<std::uint16_t> candidate_second_result(guarded_elements);
  bool every_round_bitwise = true;
  bool guards_intact = true;
  bool finite_timing = true;
  for (int round = 0; round < kMeasurementRounds; ++round) {
    const std::string round_label =
        label + " round=" + std::to_string(round + 1);
    const float b1 = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        round_label + " B1");
    const float c1 = measure_small_m_tile(
        test, stream, launch_candidate_first, kMeasuredIterations,
        round_label + " C1");
    const float c2 = measure_small_m_tile(
        test, stream, launch_candidate_second, kMeasuredIterations,
        round_label + " C2");
    const float b2 = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        round_label + " B2");
    const std::size_t pass = 2U * static_cast<std::size_t>(round);
    baseline_passes[pass] = b1;
    baseline_passes[pass + 1U] = b2;
    candidate_passes[pass] = c1;
    candidate_passes[pass + 1U] = c2;
    const bool round_finite =
        std::isfinite(b1) && std::isfinite(c1) && std::isfinite(c2) &&
        std::isfinite(b2);
    finite_timing = finite_timing && round_finite;

    bool round_ready = test.cuda_ok(
        cudaMemcpyAsync(baseline_result.data(), baseline_guarded.get(),
                        baseline_result.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        round_label + " copy baseline output");
    round_ready = round_ready && test.cuda_ok(
                                     cudaMemcpyAsync(
                                         candidate_first_result.data(),
                                         candidate_first_guarded.get(),
                                         candidate_first_result.size() *
                                             sizeof(std::uint16_t),
                                         cudaMemcpyDeviceToHost, stream),
                                     round_label +
                                         " copy candidate first output");
    round_ready = round_ready && test.cuda_ok(
                                     cudaMemcpyAsync(
                                         candidate_second_result.data(),
                                         candidate_second_guarded.get(),
                                         candidate_second_result.size() *
                                             sizeof(std::uint16_t),
                                         cudaMemcpyDeviceToHost, stream),
                                     round_label +
                                         " copy candidate second output");
    round_ready = round_ready && test.cuda_ok(
                                     cudaStreamSynchronize(stream),
                                     round_label + " output synchronize");
    std::size_t candidate_first_mismatches = 0U;
    std::size_t candidate_second_mismatches = 0U;
    std::size_t unexpected_nonfinite = 0U;
    if (round_ready) {
      for (std::size_t index = 0U; index < output_elements; ++index) {
        const std::uint16_t baseline_bits =
            baseline_result[kGuardElements + index];
        candidate_first_mismatches +=
            candidate_first_result[kGuardElements + index] != baseline_bits
                ? 1U
                : 0U;
        candidate_second_mismatches +=
            candidate_second_result[kGuardElements + index] != baseline_bits
                ? 1U
                : 0U;
        unexpected_nonfinite += !is_bf16_finite(baseline_bits) ? 1U : 0U;
      }
      for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
        guards_intact =
            guards_intact &&
            baseline_result[guard] == kPredecessorGuard &&
            baseline_result[kGuardElements + output_elements + guard] ==
                kPredecessorGuard &&
            candidate_first_result[guard] == kCandidateFirstGuard &&
            candidate_first_result[kGuardElements + output_elements + guard] ==
                kCandidateFirstGuard &&
            candidate_second_result[guard] == kCandidateSecondGuard &&
            candidate_second_result[kGuardElements + output_elements +
                                    guard] == kCandidateSecondGuard;
      }
    }
    const bool round_gate =
        round_ready && round_finite && candidate_first_mismatches == 0U &&
        candidate_second_mismatches == 0U && unexpected_nonfinite == 0U &&
        guards_intact;
    every_round_bitwise = every_round_bitwise && round_gate;
    std::cout << "PERF_FP8_M32_DUAL_RESIDENT_A_ROUND: shape="
              << shape.rows << 'x' << shape.columns
              << " round=" << round + 1 << " order=B-C-C-B"
              << " logical_launches_per_pass=" << kMeasuredIterations
              << " baseline_predecessor_pass1_ms=" << b1
              << " candidate_pass1_ms=" << c1
              << " candidate_pass2_ms=" << c2
              << " baseline_predecessor_pass2_ms=" << b2
              << " candidate_first_mismatches="
              << candidate_first_mismatches << '/' << output_elements
              << " candidate_second_mismatches="
              << candidate_second_mismatches << '/' << output_elements
              << " guards=" << (guards_intact ? "intact" : "BAD")
              << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
    test.expect(round_gate,
                round_label + " preserves exact output and guards");
  }
  const float baseline_median =
      finite_timing ? median_fp8_kv_pair_timing(baseline_passes)
                    : std::numeric_limits<float>::quiet_NaN();
  const float candidate_median =
      finite_timing ? median_fp8_kv_pair_timing(candidate_passes)
                    : std::numeric_limits<float>::quiet_NaN();
  return {baseline_median, candidate_median, every_round_bitwise,
          guards_intact};
}

void run_optional_fp8_m32_dual_resident_a_performance(
    TestContext& test, cudaStream_t stream, const bool default_screen_gate) {
  if (!fp8_m32_dual_resident_a_performance_enabled()) {
    std::cout << "SKIP: FP8 M32 dual-resident-A performance screen; set "
                 "Q3X_RUN_SM87_FP8_M32_DUAL_RESIDENT_A_PERF=1 to enable\n";
    return;
  }

  constexpr double kMinimumPerShapeSpeedup = 1.00;
  constexpr double kMinimumWeightedSpeedup = 1.03;
  std::array<Fp8M32DualResidentAMeasurement,
             kFp8M32ProductionShapes.size()>
      measurements{};
  double weighted_baseline = 0.0;
  double weighted_candidate = 0.0;
  bool all_shapes_pass = true;
  for (std::size_t index = 0U; index < kFp8M32ProductionShapes.size();
       ++index) {
    const Fp8M32ProductionShape& shape = kFp8M32ProductionShapes[index];
    measurements[index] =
        benchmark_fp8_m32_dual_resident_a_shape(test, stream, shape);
    const Fp8M32DualResidentAMeasurement& measurement = measurements[index];
    const double speedup = measurement.baseline_milliseconds /
                           measurement.candidate_milliseconds;
    const bool finite =
        std::isfinite(measurement.baseline_milliseconds) &&
        std::isfinite(measurement.candidate_milliseconds) &&
        measurement.baseline_milliseconds > 0.0F &&
        measurement.candidate_milliseconds > 0.0F &&
        std::isfinite(speedup);
    const bool shape_gate =
        finite && measurement.every_round_bitwise &&
        measurement.guards_intact && speedup >= kMinimumPerShapeSpeedup;
    all_shapes_pass = all_shapes_pass && shape_gate;
    weighted_baseline += static_cast<double>(shape.calls_per_p33) *
                         measurement.baseline_milliseconds;
    weighted_candidate += static_cast<double>(shape.calls_per_p33) *
                          measurement.candidate_milliseconds;
    std::cout << "PERF_FP8_M32_DUAL_RESIDENT_A: shape=" << shape.rows << 'x'
              << shape.columns
              << " baseline_predecessor_median_ms="
              << measurement.baseline_milliseconds
              << " candidate_dual_a_median_ms="
              << measurement.candidate_milliseconds
              << " speedup=" << speedup
              << " required_speedup=" << kMinimumPerShapeSpeedup
              << " calls_per_p33=" << shape.calls_per_p33
              << " output_every_round="
              << (measurement.every_round_bitwise ? "PASS" : "FAIL")
              << " gate=" << (shape_gate ? "PASS" : "FAIL") << '\n';
    test.expect(shape_gate,
                std::string(shape.label) +
                    " clears the frozen per-shape dual-A gate");
  }
  const double weighted_speedup = weighted_baseline / weighted_candidate;
  const bool selected_gate =
      default_screen_gate && all_shapes_pass &&
      std::isfinite(weighted_speedup) &&
      weighted_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_FP8_M32_DUAL_RESIDENT_A_SELECTED: candidate="
            << (selected_gate ? "dual_resident_a"
                              : "fixed_predecessor_single_resident_a")
            << " weighted_baseline_predecessor_ms=" << weighted_baseline
            << " weighted_candidate_dual_a_ms=" << weighted_candidate
            << " weighted_speedup=" << weighted_speedup
            << " required_per_shape_speedup=" << kMinimumPerShapeSpeedup
            << " required_weighted_speedup=" << kMinimumWeightedSpeedup
            << " profile_calls=48:64:48:16"
            << " default_correctness_resource_graph_invalid_gate="
            << (default_screen_gate ? "PASS" : "FAIL")
            << " all_shape_gates=" << (all_shapes_pass ? "PASS" : "FAIL")
            << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
  test.expect(selected_gate,
              "FP8 M32 dual-A clears the frozen P33-weighted selection gate");
}

struct Fp8RowPairMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
};

[[nodiscard]] Fp8RowPairMeasurement benchmark_fp8_row_pair_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kTokens = 8U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 40;
  constexpr float kWeightScale = 1.0F / 64.0F;
  constexpr std::array<std::uint8_t, 12U> kFiniteCodes{{
      0x00U, 0x80U, 0x01U, 0x07U, 0x30U, 0x38U,
      0x3cU, 0x40U, 0xb8U, 0x70U, 0x78U, 0xfeU,
  }};
  std::vector<std::uint8_t> host_weights(rows * columns);
  for (std::size_t index = 0U; index < host_weights.size(); ++index) {
    host_weights[index] =
        kFiniteCodes[(index * 7U + index / columns * 5U + 1U) %
                     kFiniteCodes.size()];
  }
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 13U + token * 17U + 3U) % 127U) - 63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> weights;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(weights.allocate(host_weights.size()),
                            label + " allocate weights");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(kTokens * rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(kTokens * rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(weights.get(), host_weights.data(),
                                       host_weights.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed finite weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed activations");
  if (!ready) {
    return {};
  }

  const auto launch_baseline = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_fp8_w8a16_small_m8_single_row_test_cuda(
            weights.get(), kWeightScale, activations.get(), rows, columns,
            baseline_output.get(), static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_fp8_w8a16_small_m8_row_pair_test_cuda(
        weights.get(), kWeightScale, activations.get(), rows, columns,
        candidate_output.get(), static_cast<void*>(stream));
  };

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " correctness baseline launch");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " correctness candidate launch");
  std::vector<std::uint16_t> baseline(kTokens * rows);
  std::vector<std::uint16_t> candidate(kTokens * rows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " correctness synchronize");
  if (!ready) {
    return {};
  }
  std::size_t mismatches = 0U;
  for (std::size_t index = 0U; index < baseline.size(); ++index) {
    mismatches += baseline[index] != candidate[index] ? 1U : 0U;
  }
  const bool bitwise_equal = mismatches == 0U;
  std::cout << "FP8_ROW_PAIR_SHAPE_DIFF: " << label
            << " candidate_vs_single_row_m8_bf16=" << mismatches << '/'
            << baseline.size() << '\n';
  test.expect(bitwise_equal,
              label + " row-pair candidate matches every baseline BF16 bit");

  for (int iteration = 0; iteration < kWarmupIterations && ready;
       ++iteration) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         label + " baseline warmup");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         label + " candidate warmup");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return {};
  }

  const float baseline_first = measure_small_m_tile(
      test, stream, launch_baseline, kMeasuredIterations,
      label + " baseline pass 1");
  const float candidate_first = measure_small_m_tile(
      test, stream, launch_candidate, kMeasuredIterations,
      label + " candidate pass 1");
  const float candidate_second = measure_small_m_tile(
      test, stream, launch_candidate, kMeasuredIterations,
      label + " candidate pass 2");
  const float baseline_second = measure_small_m_tile(
      test, stream, launch_baseline, kMeasuredIterations,
      label + " baseline pass 2");
  if (!(std::isfinite(baseline_first) &&
        std::isfinite(baseline_second) &&
        std::isfinite(candidate_first) &&
        std::isfinite(candidate_second))) {
    return {};
  }
  const float baseline_average =
      (baseline_first + baseline_second) * 0.5F;
  const float candidate_average =
      (candidate_first + candidate_second) * 0.5F;
  const float speedup = baseline_average / candidate_average;
  std::cout << "PERF_FP8_ROW_PAIR: " << label << " M=" << kTokens
            << " baseline_pass1_ms=" << baseline_first
            << " candidate_pass1_ms=" << candidate_first
            << " candidate_pass2_ms=" << candidate_second
            << " baseline_pass2_ms=" << baseline_second
            << " baseline_average_ms=" << baseline_average
            << " candidate_average_ms=" << candidate_average
            << " speedup=" << speedup
            << " uplift_percent=" << (speedup - 1.0F) * 100.0F << '\n';
  return {baseline_average, candidate_average, bitwise_equal};
}

void run_optional_fp8_row_pair_performance(TestContext& test,
                                            cudaStream_t stream) {
  if (!fp8_row_pair_performance_enabled()) {
    std::cout << "SKIP: FP8 M8 row-pair performance segment; set "
                 "Q3X_RUN_SM87_FP8_ROW_PAIR_PERF=1 to enable\n";
    return;
  }
  constexpr float kMinimumRequiredSpeedup = 1.03F;
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t calls_per_prompt;
    const char* label;
  };
  constexpr std::array<Shape, 5U> kShapes{{
      {10'240U, 5'120U, 48U, "FP8 linear QKV 10240x5120"},
      {5'120U, 6'144U, 64U, "FP8 projection 5120x6144"},
      {6'144U, 5'120U, 48U, "FP8 projection 6144x5120"},
      {12'288U, 5'120U, 16U, "FP8 linear QKV 12288x5120"},
      {1'024U, 5'120U, 32U, "FP8 small projection 1024x5120"},
  }};
  std::array<Fp8RowPairMeasurement, kShapes.size()> measurements{};
  measurements[0] = benchmark_fp8_row_pair_shape(
      test, stream, kShapes[0].rows, kShapes[0].columns, kShapes[0].label);
  measurements[1] = benchmark_fp8_row_pair_shape(
      test, stream, kShapes[1].rows, kShapes[1].columns, kShapes[1].label);
  const auto passes_core_gate = [&](const std::size_t index) noexcept {
    const Fp8RowPairMeasurement& measurement = measurements[index];
    return measurement.bitwise_equal &&
           std::isfinite(measurement.baseline_milliseconds) &&
           std::isfinite(measurement.candidate_milliseconds) &&
           measurement.baseline_milliseconds /
                   measurement.candidate_milliseconds >=
               kMinimumRequiredSpeedup;
  };
  const bool core_gate = passes_core_gate(0U) && passes_core_gate(1U);
  test.expect(core_gate,
              "FP8 M8 row-pair both core shapes improve by at least 3%");
  if (!core_gate) {
    std::cout << "PERF_FP8_ROW_PAIR_CORE_GATE: gate=FAIL\n";
    return;
  }
  std::cout << "PERF_FP8_ROW_PAIR_CORE_GATE: gate=PASS\n";

  for (std::size_t index = 2U; index < kShapes.size(); ++index) {
    measurements[index] = benchmark_fp8_row_pair_shape(
        test, stream, kShapes[index].rows, kShapes[index].columns,
        kShapes[index].label);
  }
  double weighted_baseline = 0.0;
  double weighted_candidate = 0.0;
  bool all_correct = true;
  bool all_finite = true;
  for (std::size_t index = 0U; index < kShapes.size(); ++index) {
    const Fp8RowPairMeasurement& measurement = measurements[index];
    all_correct = all_correct && measurement.bitwise_equal;
    all_finite = all_finite &&
                 std::isfinite(measurement.baseline_milliseconds) &&
                 std::isfinite(measurement.candidate_milliseconds);
    weighted_baseline += static_cast<double>(kShapes[index].calls_per_prompt) *
                         measurement.baseline_milliseconds;
    weighted_candidate +=
        static_cast<double>(kShapes[index].calls_per_prompt) *
        measurement.candidate_milliseconds;
  }
  const double weighted_speedup = weighted_baseline / weighted_candidate;
  const bool aggregate_gate =
      all_correct && all_finite && std::isfinite(weighted_speedup) &&
      weighted_speedup >= kMinimumRequiredSpeedup;
  std::cout << "PERF_FP8_ROW_PAIR_AGGREGATE: weighted_baseline_ms="
            << weighted_baseline
            << " weighted_candidate_ms=" << weighted_candidate
            << " speedup=" << weighted_speedup
            << " required_speedup=" << kMinimumRequiredSpeedup
            << " all_bitwise_equal=" << (all_correct ? "true" : "false")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "FP8 M8 row-pair five-shape weighted gate must pass");
}

enum class NvFp4M1ScaleDistribution {
  kCheckpointLike,
  kSameBankStress,
};

constexpr std::array<std::uint8_t, 32U> kNvFp4M1CheckpointLikeScaleCodes{{
    0x4eU, 0x50U, 0x52U, 0x54U, 0x55U, 0x56U, 0x57U, 0x58U,
    0x58U, 0x58U, 0x59U, 0x59U, 0x59U, 0x5aU, 0x5aU, 0x5bU,
    0x5bU, 0x5cU, 0x5cU, 0x5dU, 0x5dU, 0x5eU, 0x5fU, 0x60U,
    0x60U, 0x61U, 0x62U, 0x63U, 0x64U, 0x65U, 0x66U, 0x67U,
}};

constexpr std::array<std::uint8_t, 3U> kNvFp4M1SameBankScaleCodes{{
    0x20U,
    0x40U,
    0x60U,
}};

// The exact-shape kernel advances one warp's row quad by 64 blocks * 8 warps
// * 4 rows = 2048 rows. A prime fixture period prevents an omitted or stale
// rolling-offset update from aliasing the same packed/scaled input rows.
constexpr std::size_t kNvFp4M1ExactShapeFixturePeriod = 251U;
constexpr std::size_t kNvFp4M1ExactShapeRowStride = 2'048U;
constexpr std::size_t kNvFp4M1DownDualFixturePeriod = 257U;

[[nodiscard]] const char* nvfp4_m1_scale_distribution_name(
    const NvFp4M1ScaleDistribution distribution) noexcept {
  return distribution == NvFp4M1ScaleDistribution::kCheckpointLike
             ? "checkpoint_like"
             : "same_bank_stress";
}

void fill_nvfp4_m1_scale_distribution(
    std::vector<std::uint8_t>& scales, const std::size_t scale_columns,
    const NvFp4M1ScaleDistribution distribution) {
  for (std::size_t index = 0U; index < scales.size(); ++index) {
    const std::size_t row = index / scale_columns;
    const std::size_t scale_column = index - row * scale_columns;
    if (distribution == NvFp4M1ScaleDistribution::kCheckpointLike) {
      scales[index] = kNvFp4M1CheckpointLikeScaleCodes[
          (scale_column * 5U + row * 11U + (scale_column >> 3U)) %
          kNvFp4M1CheckpointLikeScaleCodes.size()];
    } else {
      // All three codes share their low five bits and therefore map to the
      // same shared-memory bank while retaining different decoded values.
      scales[index] =
          kNvFp4M1SameBankScaleCodes[
              (scale_column + row * 3U) %
              kNvFp4M1SameBankScaleCodes.size()];
    }
  }
}

void fill_nvfp4_m1_exact_shape_scale_distribution(
    std::vector<std::uint8_t>& scales, const std::size_t scale_columns,
    const NvFp4M1ScaleDistribution distribution) {
  for (std::size_t index = 0U; index < scales.size(); ++index) {
    const std::size_t row = index / scale_columns;
    const std::size_t scale_column = index - row * scale_columns;
    const std::size_t row_phase =
        row % kNvFp4M1ExactShapeFixturePeriod;
    if (distribution == NvFp4M1ScaleDistribution::kCheckpointLike) {
      scales[index] = kNvFp4M1CheckpointLikeScaleCodes[
          (scale_column * 5U + row_phase * 11U + (scale_column >> 3U)) %
          kNvFp4M1CheckpointLikeScaleCodes.size()];
    } else {
      // Preserve the same-bank stress while varying the decoded value across
      // rows, including rows separated by the production 2048-row stride.
      scales[index] = kNvFp4M1SameBankScaleCodes[
          (scale_column + row_phase) % kNvFp4M1SameBankScaleCodes.size()];
    }
  }
}

void fill_nvfp4_m1_down_dual_scale_distribution(
    std::vector<std::uint8_t>& scales, const std::size_t scale_columns,
    const NvFp4M1ScaleDistribution distribution) {
  for (std::size_t index = 0U; index < scales.size(); ++index) {
    const std::size_t row = index / scale_columns;
    const std::size_t scale_column = index - row * scale_columns;
    const std::size_t row_phase =
        row % kNvFp4M1DownDualFixturePeriod;
    if (distribution == NvFp4M1ScaleDistribution::kCheckpointLike) {
      scales[index] = kNvFp4M1CheckpointLikeScaleCodes[
          (scale_column * 5U + row_phase * 11U +
           (scale_column >> 3U)) %
          kNvFp4M1CheckpointLikeScaleCodes.size()];
    } else {
      scales[index] = kNvFp4M1SameBankScaleCodes[
          (scale_column + row_phase) %
          kNvFp4M1SameBankScaleCodes.size()];
    }
  }
}

using NvFp4M32TestLaunch = int (*)(
    const std::uint8_t*, const std::uint8_t*, float,
    const std::uint16_t*, std::size_t, std::size_t, std::uint16_t*,
    void*) noexcept;

using NvFp4M32ResourceQuery = int (*)(
    std::size_t, std::size_t, int*, std::size_t*, std::size_t*, int*,
    int*) noexcept;

struct NvFp4M32CapturedKernel {
  bool valid = false;
  void* function = nullptr;
  dim3 grid{0U, 0U, 0U};
  dim3 block{0U, 0U, 0U};
  unsigned int dynamic_shared_bytes = 0U;
  std::size_t total_nodes = 0U;
  std::size_t kernel_nodes = 0U;
};

[[nodiscard]] NvFp4M32CapturedKernel capture_nvfp4_m32_kernel(
    TestContext& test, cudaStream_t stream, const NvFp4M32TestLaunch launch,
    const std::uint8_t* const packed, const std::uint8_t* const scales,
    const float weight_scale_2, const std::uint16_t* const activations,
    const std::size_t rows, const std::size_t columns,
    std::uint16_t* const output, const std::string& label) {
  NvFp4M32CapturedKernel result{};
  cudaGraph_t graph = nullptr;
  bool ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin capture");
  int launch_status = static_cast<int>(cudaErrorUnknown);
  if (ready) {
    launch_status = launch(packed, scales, weight_scale_2, activations, rows,
                           columns, output, static_cast<void*>(stream));
    ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                         label + " end capture") &&
            ready;
  }
  if (ready) {
    ready = test.cuda_ok(
                cudaGraphGetNodes(graph, nullptr, &result.total_nodes),
                label + " query nodes") &&
            ready;
  }
  if (ready && result.total_nodes != 0U) {
    std::vector<cudaGraphNode_t> nodes(result.total_nodes);
    std::size_t capacity = nodes.size();
    ready = test.cuda_ok(cudaGraphGetNodes(graph, nodes.data(), &capacity),
                         label + " get nodes") &&
            ready;
    for (std::size_t index = 0U; index < capacity && ready; ++index) {
      cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
      ready = test.cuda_ok(cudaGraphNodeGetType(nodes[index], &type),
                           label + " get node type") &&
              ready;
      if (type == cudaGraphNodeTypeKernel) {
        ++result.kernel_nodes;
        cudaKernelNodeParams params{};
        ready = test.cuda_ok(
                    cudaGraphKernelNodeGetParams(nodes[index], &params),
                    label + " get kernel params") &&
                ready;
        result.function = params.func;
        result.grid = params.gridDim;
        result.block = params.blockDim;
        result.dynamic_shared_bytes = params.sharedMemBytes;
      }
    }
  }
  if (graph != nullptr) {
    ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy graph") &&
            ready;
  }
  result.valid = ready && launch_status == static_cast<int>(cudaSuccess) &&
                 result.total_nodes == 1U && result.kernel_nodes == 1U;
  return result;
}

void run_nvfp4_factorized_product_lookup_exhaustive(TestContext& test,
                                                     cudaStream_t stream) {
  constexpr std::size_t kScaleCodes = 256U;
  constexpr std::size_t kPackedBytes = 256U;
  constexpr std::size_t kCombinations = kScaleCodes * kPackedBytes;
  DeviceBuffer<std::uint32_t> factorized_device;
  DeviceBuffer<std::uint32_t> reference_device;
  const std::string label =
      "NVFP4 factorized BF16x2 product lookup exhaustive";
  bool ready = test.cuda_ok(factorized_device.allocate(kCombinations),
                            label + " allocate factorized output");
  ready = ready && test.cuda_ok(reference_device.allocate(kCombinations),
                                label + " allocate reference output");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           launch_sm87_nvfp4_factorized_product_lookup_exhaustive_test_cuda(
                               factorized_device.get(), reference_device.get(),
                               static_cast<void*>(stream))),
                       label + " launch");
  std::vector<std::uint32_t> factorized(kCombinations);
  std::vector<std::uint32_t> reference(kCombinations);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           factorized.data(), factorized_device.get(),
                           factorized.size() * sizeof(std::uint32_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy factorized output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           reference.data(), reference_device.get(),
                           reference.size() * sizeof(std::uint32_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy reference output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize");
  if (!ready) {
    return;
  }

  std::size_t word_mismatches = 0U;
  std::size_t half_mismatches = 0U;
  std::size_t reference_nan_halves = 0U;
  std::size_t factorized_nan_halves = 0U;
  std::size_t first_mismatch = kCombinations;
  for (std::size_t index = 0U; index < kCombinations; ++index) {
    if (factorized[index] != reference[index]) {
      ++word_mismatches;
      first_mismatch = std::min(first_mismatch, index);
    }
    for (unsigned int half = 0U; half < 2U; ++half) {
      const std::uint16_t factorized_half = static_cast<std::uint16_t>(
          factorized[index] >> (half * 16U));
      const std::uint16_t reference_half = static_cast<std::uint16_t>(
          reference[index] >> (half * 16U));
      half_mismatches += factorized_half != reference_half ? 1U : 0U;
      reference_nan_halves += is_bf16_nan(reference_half) ? 1U : 0U;
      factorized_nan_halves += is_bf16_nan(factorized_half) ? 1U : 0U;
    }
  }
  std::cout << "NVFP4_FACTORIZED_PRODUCT_LOOKUP_DIFF: combinations="
            << kCombinations << " word_mismatches=" << word_mismatches
            << " half_mismatches=" << half_mismatches
            << " reference_nan_halves=" << reference_nan_halves
            << " factorized_nan_halves=" << factorized_nan_halves;
  if (first_mismatch != kCombinations) {
    std::cout << " first_scale_code=" << first_mismatch / kPackedBytes
              << " first_packed_byte=" << first_mismatch % kPackedBytes
              << " first_reference=0x" << std::hex
              << reference[first_mismatch] << " first_factorized=0x"
              << factorized[first_mismatch] << std::dec;
  }
  std::cout << " gate=" << (word_mismatches == 0U ? "PASS" : "FAIL")
            << '\n';
  test.expect(word_mismatches == 0U,
              label + " matches every product-table BF16 bit");
}

void run_nvfp4_table_free_e2m1_exhaustive(TestContext& test,
                                           cudaStream_t stream) {
  constexpr std::size_t kScaleCodes = 256U;
  constexpr std::size_t kPackedBytes = 256U;
  constexpr std::size_t kPackedBytePositions = 4U;
  constexpr std::size_t kCombinations =
      kScaleCodes * kPackedBytes * kPackedBytePositions;
  DeviceBuffer<std::uint32_t> candidate_device;
  DeviceBuffer<std::uint32_t> reference_device;
  const std::string label = "NVFP4 table-free E2M1 exhaustive";
  bool ready = test.cuda_ok(candidate_device.allocate(kCombinations),
                            label + " allocate candidate output");
  ready = ready && test.cuda_ok(reference_device.allocate(kCombinations),
                                label + " allocate reference output");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           launch_sm87_nvfp4_table_free_e2m1_exhaustive_test_cuda(
                               candidate_device.get(), reference_device.get(),
                               static_cast<void*>(stream))),
                       label + " launch");
  std::vector<std::uint32_t> candidate(kCombinations);
  std::vector<std::uint32_t> reference(kCombinations);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_device.get(),
                           candidate.size() * sizeof(std::uint32_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           reference.data(), reference_device.get(),
                           reference.size() * sizeof(std::uint32_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy reference output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize");
  if (!ready) {
    return;
  }

  std::size_t word_mismatches = 0U;
  std::size_t half_mismatches = 0U;
  std::size_t first_mismatch = kCombinations;
  for (std::size_t index = 0U; index < kCombinations; ++index) {
    if (candidate[index] != reference[index]) {
      ++word_mismatches;
      first_mismatch = std::min(first_mismatch, index);
    }
    half_mismatches +=
        static_cast<std::uint16_t>(candidate[index]) !=
                static_cast<std::uint16_t>(reference[index])
            ? 1U
            : 0U;
    half_mismatches +=
        static_cast<std::uint16_t>(candidate[index] >> 16U) !=
                static_cast<std::uint16_t>(reference[index] >> 16U)
            ? 1U
            : 0U;
  }
  constexpr std::size_t kOneScaleCode = 0x38U;
  constexpr std::size_t kNegativeZeroPair = 0x88U;
  bool signed_zero_preserved = true;
  for (std::size_t position = 0U; position < kPackedBytePositions;
       ++position) {
    const std::size_t index =
        (kOneScaleCode * kPackedBytes + kNegativeZeroPair) *
            kPackedBytePositions +
        position;
    signed_zero_preserved =
        signed_zero_preserved && candidate[index] == 0x8000'8000U &&
        reference[index] == 0x8000'8000U;
  }
  std::cout << "NVFP4_TABLE_FREE_E2M1_DIFF: combinations="
            << kCombinations << " word_mismatches=" << word_mismatches
            << " half_mismatches=" << half_mismatches
            << " signed_zero_all_positions="
            << (signed_zero_preserved ? "true" : "false");
  if (first_mismatch != kCombinations) {
    const std::size_t pair_index =
        first_mismatch / kPackedBytePositions;
    std::cout << " first_scale_code=" << pair_index / kPackedBytes
              << " first_packed_byte=" << pair_index % kPackedBytes
              << " first_byte_position="
              << first_mismatch % kPackedBytePositions << " first_reference=0x"
              << std::hex << reference[first_mismatch]
              << " first_candidate=0x" << candidate[first_mismatch]
              << std::dec;
  }
  const bool gate = word_mismatches == 0U && signed_zero_preserved;
  std::cout << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
  test.expect(gate, label + " matches all four PRMT output positions");
}

void run_nvfp4_m32_candidate_smoke(
    TestContext& test, cudaStream_t stream,
    const DeviceBuffer<std::uint8_t>& packed,
    const std::uint8_t* const scales,
    const DeviceBuffer<std::uint16_t>& activations,
    const std::vector<std::uint16_t>& baseline, const std::size_t rows,
    const std::size_t columns, const float weight_scale_2,
    NvFp4M32TestLaunch launch, const std::uint8_t candidate_sentinel,
    const std::uint8_t replay_sentinel, const std::string& label) {
  constexpr std::size_t kGuardElements = 64U;
  const std::size_t output_elements = 32U * rows;
  const std::size_t guarded_elements =
      output_elements + 2U * kGuardElements;
  DeviceBuffer<std::uint16_t> candidate_guarded;
  DeviceBuffer<std::uint16_t> replay_guarded;
  bool ready = test.cuda_ok(candidate_guarded.allocate(guarded_elements),
                            label + " allocate guarded candidate output");
  ready = ready && test.cuda_ok(
                       replay_guarded.allocate(guarded_elements),
                       label + " allocate guarded replay output");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           candidate_guarded.get(), candidate_sentinel,
                           guarded_elements * sizeof(std::uint16_t), stream),
                       label + " poison candidate output and guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           replay_guarded.get(), replay_sentinel,
                           guarded_elements * sizeof(std::uint16_t), stream),
                       label + " poison replay output and guards");
  if (!ready) {
    return;
  }

  std::uint16_t* const candidate_output =
      candidate_guarded.get() + kGuardElements;
  std::uint16_t* const replay_output =
      replay_guarded.get() + kGuardElements;
  ready = test.cuda_ok(
      static_cast<cudaError_t>(
          launch(packed.get(), scales, weight_scale_2,
                 activations.get(), rows, columns, candidate_output,
                 static_cast<void*>(stream))),
      label + " launch candidate");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(
                           launch(packed.get(), scales, weight_scale_2,
                                  activations.get(), rows, columns,
                                  replay_output, static_cast<void*>(stream))),
                       label + " launch deterministic replay");

  std::vector<std::uint16_t> candidate(guarded_elements);
  std::vector<std::uint16_t> replay(guarded_elements);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_guarded.get(),
                           guarded_elements * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           replay.data(), replay_guarded.get(),
                           guarded_elements * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy guarded replay output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize smoke outputs");
  if (!ready) {
    return;
  }

  std::size_t baseline_mismatches = 0U;
  std::size_t replay_mismatches = 0U;
  bool output_finite = true;
  for (std::size_t index = 0U; index < output_elements; ++index) {
    const std::uint16_t candidate_value =
        candidate[kGuardElements + index];
    baseline_mismatches += candidate_value != baseline[index] ? 1U : 0U;
    replay_mismatches +=
        candidate_value != replay[kGuardElements + index] ? 1U : 0U;
    output_finite =
        output_finite && std::isfinite(decode_bf16(candidate_value));
  }
  const std::uint16_t candidate_guard = static_cast<std::uint16_t>(
      candidate_sentinel | (static_cast<std::uint16_t>(candidate_sentinel)
                            << 8U));
  const std::uint16_t replay_guard = static_cast<std::uint16_t>(
      replay_sentinel |
      (static_cast<std::uint16_t>(replay_sentinel) << 8U));
  bool guards_intact = true;
  for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
    guards_intact =
        guards_intact && candidate[guard] == candidate_guard &&
        candidate[kGuardElements + output_elements + guard] ==
            candidate_guard &&
        replay[guard] == replay_guard &&
        replay[kGuardElements + output_elements + guard] == replay_guard;
  }
  const std::size_t token_boundary = 16U * rows;
  const bool panel_boundary_exact =
      candidate[kGuardElements + token_boundary - 1U] ==
          baseline[token_boundary - 1U] &&
      candidate[kGuardElements + token_boundary] == baseline[token_boundary];
  std::cout << "NVFP4_M32_WMMA_SMOKE_DIFF: " << label
            << " candidate_vs_two_public_m16_bf16=" << baseline_mismatches
            << '/' << output_elements
            << " replay_mismatches=" << replay_mismatches << '/'
            << output_elements
            << " token15_16_boundary="
            << (panel_boundary_exact ? "exact" : "BAD")
            << " output_finite=" << (output_finite ? "true" : "false")
            << " guards=" << (guards_intact ? "intact" : "BAD") << '\n';
  test.expect(baseline_mismatches == 0U,
              label + " is bit-exact to two public production M16 calls");
  test.expect(replay_mismatches == 0U,
              label + " deterministic replay is bit-exact");
  test.expect(panel_boundary_exact,
              label + " preserves the token15/token16 panel boundary");
  test.expect(output_finite, label + " output remains finite");
  test.expect(guards_intact, label + " preserves head and tail guards");

  cudaGraph_t graph = nullptr;
  bool graph_ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin direct-candidate graph capture");
  int graph_launch_status = static_cast<int>(cudaErrorUnknown);
  if (graph_ready) {
    graph_launch_status =
        launch(packed.get(), scales, weight_scale_2,
               activations.get(), rows, columns, candidate_output,
               static_cast<void*>(stream));
    graph_ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                               label + " end direct-candidate graph capture") &&
                  graph_ready;
  }
  std::size_t node_count = 0U;
  std::size_t kernel_node_count = 0U;
  if (graph_ready) {
    graph_ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                               label + " query captured graph nodes") &&
                  graph_ready;
  }
  if (graph_ready && node_count != 0U) {
    std::vector<cudaGraphNode_t> nodes(node_count);
    std::size_t capacity = nodes.size();
    graph_ready = test.cuda_ok(
                      cudaGraphGetNodes(graph, nodes.data(), &capacity),
                      label + " get captured graph nodes") &&
                  graph_ready;
    for (std::size_t index = 0U; index < capacity && graph_ready; ++index) {
      cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
      graph_ready = test.cuda_ok(cudaGraphNodeGetType(nodes[index], &type),
                                 label + " inspect graph node type") &&
                    graph_ready;
      kernel_node_count += type == cudaGraphNodeTypeKernel ? 1U : 0U;
    }
  }
  if (graph != nullptr) {
    graph_ready = test.cuda_ok(cudaGraphDestroy(graph),
                               label + " destroy captured graph") &&
                  graph_ready;
  }
  const bool single_kernel_graph =
      graph_ready && graph_launch_status == static_cast<int>(cudaSuccess) &&
      node_count == 1U && kernel_node_count == 1U;
  std::cout << "NVFP4_M32_WMMA_GRAPH: " << label
            << " total_nodes=" << node_count
            << " kernel_nodes=" << kernel_node_count
            << " gate=" << (single_kernel_graph ? "PASS" : "FAIL")
            << '\n';
  test.expect(single_kernel_graph,
              label + " captures exactly one direct CUDA kernel node");
}

void run_nvfp4_m17_m31_runtime_masked_m32_default_matrix(
    TestContext& test, cudaStream_t stream,
    const DeviceBuffer<std::uint8_t>& packed,
    const std::uint8_t* const scales,
    const DeviceBuffer<std::uint16_t>& m32_activations,
    const std::vector<std::uint16_t>& m32_baseline, const std::size_t rows,
    const std::size_t columns, const float weight_scale_2,
    const std::string& label) {
  constexpr std::size_t kPaddedTokens = 32U;
  constexpr std::uint8_t kTailSentinelByte = 0x6dU;
  constexpr std::uint16_t kTailSentinel = 0x6d6dU;
  const std::size_t padded_output_elements = kPaddedTokens * rows;
  DeviceBuffer<std::uint16_t> replay_output;
  bool ready = test.cuda_ok(
      replay_output.allocate(padded_output_elements),
      label + " allocate runtime-mask padded replay output");
  if (!ready) {
    return;
  }

  for (std::size_t valid_tokens = 17U; valid_tokens <= 31U;
       ++valid_tokens) {
    const std::string cell_label =
        label + " runtime-valid M" + std::to_string(valid_tokens);
    const std::size_t activation_elements = valid_tokens * columns;
    const std::size_t output_elements = valid_tokens * rows;
    DeviceBuffer<std::uint16_t> exact_activations;
    DeviceBuffer<std::uint16_t> exact_output;
    ready = test.cuda_ok(exact_activations.allocate(activation_elements),
                         cell_label + " allocate exact-C_M activations");
    ready = ready && test.cuda_ok(
                         exact_output.allocate(output_elements),
                         cell_label + " allocate exact-C_M output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             exact_activations.get(), m32_activations.get(),
                             activation_elements * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToDevice, stream),
                         cell_label + " initialize exact-C_M activations");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             replay_output.get(), kTailSentinelByte,
                             padded_output_elements * sizeof(std::uint16_t),
                             stream),
                         cell_label + " poison padded replay tail");
    if (!ready) {
      return;
    }

    const auto launch = [&](std::uint16_t* const output) noexcept {
      if (valid_tokens == 18U) {
        return q3x::kernels::launch_sm87_nvfp4_w4a16_m18_gemm_bf16_cuda(
            packed.get(), scales, weight_scale_2, exact_activations.get(),
            rows, columns, output, static_cast<void*>(stream));
      }
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_m17_m31_gemm_bf16_cuda(
              packed.get(), scales, weight_scale_2, exact_activations.get(),
              valid_tokens, rows, columns, output,
              static_cast<void*>(stream));
    };
    ready = test.cuda_ok(static_cast<cudaError_t>(launch(exact_output.get())),
                         cell_label + " launch exact-C_M candidate");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch(replay_output.get())),
                         cell_label + " launch padded replay");

    std::vector<std::uint16_t> exact(output_elements);
    std::vector<std::uint16_t> replay(padded_output_elements);
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             exact.data(), exact_output.get(),
                             output_elements * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         cell_label + " copy exact-C_M output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             replay.data(), replay_output.get(),
                             padded_output_elements * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         cell_label + " copy padded replay and tail");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  cell_label + " synchronize outputs");
    if (!ready) {
      return;
    }

    std::size_t baseline_mismatches = 0U;
    std::size_t replay_mismatches = 0U;
    bool output_finite = true;
    for (std::size_t index = 0U; index < output_elements; ++index) {
      baseline_mismatches +=
          exact[index] != m32_baseline[index] ? 1U : 0U;
      replay_mismatches += exact[index] != replay[index] ? 1U : 0U;
      output_finite =
          output_finite && std::isfinite(decode_bf16(exact[index]));
    }
    const bool replay_tail_intact = std::all_of(
        replay.begin() + static_cast<std::ptrdiff_t>(output_elements),
        replay.end(), [](const std::uint16_t value) noexcept {
          return value == kTailSentinel;
        });
    const bool gate = baseline_mismatches == 0U && replay_mismatches == 0U &&
                      output_finite && replay_tail_intact;
    std::cout << "NVFP4_M17_M31_PUBLIC_MASKED_M32_DEFAULT: "
              << cell_label
              << " candidate_vs_two_m16_mismatches=" << baseline_mismatches
              << '/' << output_elements
              << " replay_mismatches=" << replay_mismatches << '/'
              << output_elements
              << " candidate_capacity=exact_m" << valid_tokens
              << " output_finite=" << (output_finite ? "true" : "false")
              << " replay_tail="
              << (replay_tail_intact ? "intact" : "BAD")
              << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
    test.expect(gate, cell_label +
                          " is bit-exact, deterministic, finite, and preserves "
                          "the complete masked output tail");

    if (valid_tokens == 17U || valid_tokens == 31U) {
      cudaGraph_t graph = nullptr;
      bool graph_ready = test.cuda_ok(
          cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
          cell_label + " begin single-kernel graph capture");
      int graph_launch_status = static_cast<int>(cudaErrorUnknown);
      if (graph_ready) {
        graph_launch_status = launch(exact_output.get());
        graph_ready =
            test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                         cell_label + " end single-kernel graph capture") &&
            graph_ready;
      }
      std::size_t node_count = 0U;
      std::size_t kernel_node_count = 0U;
      if (graph_ready) {
        graph_ready =
            test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                         cell_label + " query graph nodes") &&
            graph_ready;
      }
      if (graph_ready && node_count != 0U) {
        std::vector<cudaGraphNode_t> nodes(node_count);
        std::size_t capacity = nodes.size();
        graph_ready =
            test.cuda_ok(cudaGraphGetNodes(graph, nodes.data(), &capacity),
                         cell_label + " get graph nodes") &&
            graph_ready;
        for (std::size_t index = 0U; index < capacity && graph_ready;
             ++index) {
          cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
          graph_ready =
              test.cuda_ok(cudaGraphNodeGetType(nodes[index], &type),
                           cell_label + " inspect graph node") &&
              graph_ready;
          kernel_node_count +=
              type == cudaGraphNodeTypeKernel ? 1U : 0U;
        }
      }
      if (graph != nullptr) {
        graph_ready =
            test.cuda_ok(cudaGraphDestroy(graph),
                         cell_label + " destroy captured graph") &&
            graph_ready;
      }
      const bool single_kernel =
          graph_ready &&
          graph_launch_status == static_cast<int>(cudaSuccess) &&
          node_count == 1U && kernel_node_count == 1U;
      std::cout << "NVFP4_M17_M31_RUNTIME_MASKED_M32_GRAPH: " << cell_label
                << " total_nodes=" << node_count
                << " kernel_nodes=" << kernel_node_count
                << " gate=" << (single_kernel ? "PASS" : "FAIL") << '\n';
      test.expect(single_kernel,
                  cell_label + " captures exactly one direct kernel node");
    }
  }
}

void run_nvfp4_m32_wmma_smoke_case(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns,
    const NvFp4M1ScaleDistribution scale_distribution,
    const std::string& label) {
  constexpr std::size_t kTokens = 32U;
  constexpr std::size_t kPanelTokens = 16U;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  const std::size_t packed_columns = columns / 2U;
  const std::size_t scale_columns = columns / 16U;
  std::vector<std::uint8_t> host_packed(rows * packed_columns);
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t row = 0U; row < rows; ++row) {
    for (std::size_t packed_column = 0U; packed_column < packed_columns;
         ++packed_column) {
      const std::uint8_t low = static_cast<std::uint8_t>(
          (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
      const std::uint8_t high = static_cast<std::uint8_t>(
          (packed_column * 5U + row * 7U +
           (packed_column >> 3U) * 3U + 1U) &
          0x0fU);
      host_packed[row * packed_columns + packed_column] =
          static_cast<std::uint8_t>(low | (high << 4U));
      low_nibble_covered[low] = true;
      high_nibble_covered[high] = true;
    }
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers all 16 low-nibble E2M1 codes");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers all 16 high-nibble E2M1 codes");

  std::vector<std::uint8_t> host_scales(rows * scale_columns);
  fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                   scale_distribution);
  std::vector<std::uint16_t> host_activations(kTokens * columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < columns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scale_storage;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  const std::size_t output_elements = kTokens * rows;
  bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(
                       scale_storage.allocate(host_scales.size() + 2U),
                       label + " allocate +2B block-scale storage");
  ready = ready && test.cuda_ok(
                       activations.allocate(host_activations.size()),
                       label + " allocate M32 activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(output_elements),
                                label + " allocate M32 baseline output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), host_packed.data(),
                                       host_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize all-nibble packed weights");
  std::uint8_t* const scales = scale_storage.get() == nullptr
                                   ? nullptr
                                   : scale_storage.get() + 2U;
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(scales, host_scales.data(),
                                       host_scales.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize block scales");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize M32 activations");
  if (!ready) {
    return;
  }

  int baseline_status =
      q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
          packed.get(), scales, kWeightScale2, activations.get(), rows,
          columns, baseline_output.get(), static_cast<void*>(stream));
  if (baseline_status == static_cast<int>(cudaSuccess)) {
    baseline_status =
        q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
            packed.get(), scales, kWeightScale2,
            activations.get() + kPanelTokens * columns, rows, columns,
            baseline_output.get() + kPanelTokens * rows,
            static_cast<void*>(stream));
  }
  ready = test.cuda_ok(static_cast<cudaError_t>(baseline_status),
                       label + " launch exactly two public production M16s");
  std::vector<std::uint16_t> baseline(output_elements);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           output_elements * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy two-M16 baseline");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize baseline");
  if (!ready) {
    return;
  }

  const std::string distribution_label =
      label + " " + nvfp4_m1_scale_distribution_name(scale_distribution);
  constexpr std::size_t kM18Tokens = 18U;
  constexpr std::uint8_t kM18TailSentinelByte = 0xcdU;
  constexpr std::uint16_t kM18TailSentinel = 0xcdcdU;
  DeviceBuffer<std::uint16_t> m18_output;
  ready = test.cuda_ok(m18_output.allocate(output_elements),
                       distribution_label + " allocate production M18 smoke");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           m18_output.get(), kM18TailSentinelByte,
                           output_elements * sizeof(std::uint16_t), stream),
                       distribution_label + " poison production M18 tail");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(
                           q3x::kernels::
                               launch_sm87_nvfp4_w4a16_m18_gemm_bf16_cuda(
                                   packed.get(), scales, kWeightScale2,
                                   activations.get(), rows, columns,
                                   m18_output.get(),
                                   static_cast<void*>(stream))),
                       distribution_label + " launch production M18 smoke");
  std::vector<std::uint16_t> m18_result(output_elements);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           m18_result.data(), m18_output.get(),
                           output_elements * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       distribution_label + " copy production M18 smoke");
  ready = ready && test.cuda_ok(
                       cudaStreamSynchronize(stream),
                       distribution_label + " synchronize production M18");
  if (!ready) {
    return;
  }
  const std::size_t m18_output_elements = kM18Tokens * rows;
  std::size_t m18_mismatches = 0U;
  bool m18_output_finite = true;
  for (std::size_t index = 0U; index < m18_output_elements; ++index) {
    m18_mismatches += m18_result[index] != baseline[index] ? 1U : 0U;
    m18_output_finite =
        m18_output_finite && std::isfinite(decode_bf16(m18_result[index]));
  }
  const bool m18_tail_intact = std::all_of(
      m18_result.begin() + static_cast<std::ptrdiff_t>(m18_output_elements),
      m18_result.end(), [](const std::uint16_t value) noexcept {
        return value == kM18TailSentinel;
      });
  const bool m18_smoke =
      m18_mismatches == 0U && m18_output_finite && m18_tail_intact;
  std::cout << "NVFP4_M18_MASKED_M32_SMOKE: " << distribution_label
            << " candidate_vs_two_public_m16_mismatches=" << m18_mismatches
            << '/' << m18_output_elements
            << " output_finite=" << (m18_output_finite ? "true" : "false")
            << " output_tail=" << (m18_tail_intact ? "intact" : "BAD")
            << " gate=" << (m18_smoke ? "PASS" : "FAIL") << '\n';
  test.expect(m18_smoke,
              distribution_label +
                  " production M18 is bit-exact and preserves rows 18..31");

  run_nvfp4_m17_m31_runtime_masked_m32_default_matrix(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2, distribution_label);

  run_nvfp4_m32_candidate_smoke(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_test_cuda,
      0xa5U, 0x5aU, distribution_label + " K64/LD72 dual-A");
  run_nvfp4_m32_candidate_smoke(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_scale_window_test_cuda,
      0x87U, 0x78U,
      distribution_label + " K64/LD72 dual-A scale-window");
  run_nvfp4_m32_candidate_smoke(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_lookup_test_cuda,
      0xd2U, 0x2dU,
      distribution_label + " K64/LD72 factorized lookup");
  run_nvfp4_m32_candidate_smoke(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_vector_store_test_cuda,
      0xb4U, 0x4bU,
      distribution_label + " K64/LD72 factorized vector store");
  run_nvfp4_m32_candidate_smoke(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_test_cuda,
      0x6dU, 0xd6U,
      distribution_label + " K64/LD72 table-free E2M1");
  if (rows == 17'408U && columns == 5'120U) {
    run_nvfp4_m32_candidate_smoke(
        test, stream, packed, scales, activations, baseline, rows, columns,
        kWeightScale2,
        q3x::kernels::
            launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_test_cuda,
        0x39U, 0x93U,
        distribution_label +
            " K64/LD72 table-free single-slot raw-weight cp.async");
  }
  run_nvfp4_m32_candidate_smoke(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k128_single_a_test_cuda,
      0x3cU, 0xc3U, distribution_label + " K128/LD136 single-A");
  run_nvfp4_m32_candidate_smoke(
      test, stream, packed, scales, activations, baseline, rows, columns,
      kWeightScale2,
      q3x::kernels::launch_sm87_nvfp4_w4a16_m32_gemm_bf16_cuda,
      0x69U, 0x96U, distribution_label + " public production M32");
}

void run_nvfp4_m32_wmma_exact_shape_smoke(TestContext& test,
                                            cudaStream_t stream) {
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    NvFp4M1ScaleDistribution scale_distribution;
    const char* label;
  };
  // Each case owns and releases its production-size matrix before the next
  // case starts, keeping the default smoke peak to one exact MLP shape.
  constexpr std::array<Shape, 2U> kShapes{{
      {17'408U, 5'120U, NvFp4M1ScaleDistribution::kCheckpointLike,
       "NVFP4 fixed-M32 gate/up 17408x5120 smoke"},
      {5'120U, 17'408U, NvFp4M1ScaleDistribution::kSameBankStress,
       "NVFP4 fixed-M32 down 5120x17408 smoke"},
  }};
  for (const Shape& shape : kShapes) {
    run_nvfp4_m32_wmma_smoke_case(
        test, stream, shape.rows, shape.columns, shape.scale_distribution,
        shape.label);
  }
}

void run_nvfp4_m32_wmma_resource_gates(TestContext& test) {
  struct Candidate {
    const char* label;
    NvFp4M32ResourceQuery query;
    int maximum_registers;
    std::size_t expected_static_shared_bytes;
    int minimum_active_blocks;
    bool gate_up_only = false;
  };
  constexpr std::array<Candidate, 10U> kCandidates{{
      {"K64/LD72 dual-A",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_resources_test_cuda,
       51, 31'232U, 5},
      {"K64/LD72 dual-A scale-window",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_scale_window_resources_test_cuda,
       51, 31'232U, 5},
      {"K64/LD72 factorized lookup",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_lookup_resources_test_cuda,
       51, 24'576U, 5},
      {"K64/LD72 factorized vector store",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_vector_store_resources_test_cuda,
       51, 24'576U, 5},
      {"K64/LD72 table-free E2M1",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_resources_test_cuda,
       51, 23'552U, 5},
      {"K64/LD72 table-free single-slot raw-weight cp.async",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_resources_test_cuda,
       51, 27'648U, 5, true},
      {"M18 masked-M32 factorized vector store",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m18_masked_m32_wmma_resources_test_cuda,
       46, 24'576U, 5},
      {"M17-M31 runtime-valid masked-M32 factorized vector store",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m17_m31_runtime_masked_m32_resources_test_cuda,
       51, 24'576U, 5},
      {"M17-M31 runtime-valid single-slot raw-weight cp.async",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m17_m31_runtime_masked_m32_raw_weight_cp_async_resources_test_cuda,
       51, 28'672U, 5},
      {"K128/LD136 single-A",
       q3x::kernels::
           query_sm87_nvfp4_w4a16_small_m32_wmma_k128_single_a_resources_test_cuda,
       64, 47'360U, 3},
  }};
  struct Shape {
    std::size_t rows;
    std::size_t columns;
    const char* label;
  };
  constexpr std::array<Shape, 2U> kShapes{{
      {17'408U, 5'120U, "gate/up"},
      {5'120U, 17'408U, "down"},
  }};
  for (const Candidate& candidate : kCandidates) {
    for (const Shape& shape : kShapes) {
      if (candidate.gate_up_only && shape.rows != 17'408U) {
        continue;
      }
      int registers_per_thread = -1;
      std::size_t static_shared_bytes =
          std::numeric_limits<std::size_t>::max();
      std::size_t local_bytes = std::numeric_limits<std::size_t>::max();
      int maximum_threads_per_block = -1;
      int active_blocks_per_sm = -1;
      const cudaError_t status = static_cast<cudaError_t>(candidate.query(
          shape.rows, shape.columns, &registers_per_thread,
          &static_shared_bytes, &local_bytes, &maximum_threads_per_block,
          &active_blocks_per_sm));
      const bool gate =
          status == cudaSuccess &&
          registers_per_thread <= candidate.maximum_registers &&
          static_shared_bytes == candidate.expected_static_shared_bytes &&
          local_bytes == 0U && maximum_threads_per_block == 256 &&
          active_blocks_per_sm >= candidate.minimum_active_blocks;
      std::cout << "NVFP4_M32_WMMA_RESOURCES: candidate="
                << candidate.label << " shape=" << shape.label
                << " status=" << static_cast<int>(status)
                << " registers=" << registers_per_thread
                << " maximum_registers=" << candidate.maximum_registers
                << " static_shared_bytes=" << static_shared_bytes
                << " expected_static_shared_bytes="
                << candidate.expected_static_shared_bytes
                << " local_bytes=" << local_bytes
                << " maximum_threads_per_block="
                << maximum_threads_per_block
                << " active_blocks_per_sm=" << active_blocks_per_sm
                << " minimum_active_blocks="
                << candidate.minimum_active_blocks
                << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
      test.expect(gate, std::string("NVFP4 M32 ") + candidate.label + " " +
                            shape.label + " clears its resource gate");
    }
  }
}

void run_nvfp4_m32_wmma_invalid_capture_contract(TestContext& test,
                                                   cudaStream_t stream) {
  constexpr std::size_t kRows = 17'408U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::uintptr_t kPackedAddress = 0x5'0000'0000ULL;
  constexpr std::uintptr_t kScaleAddress = 0x6'0000'0000ULL;
  constexpr std::uintptr_t kActivationAddress = 0x7'0000'0000ULL;
  auto* const packed =
      reinterpret_cast<const std::uint8_t*>(kPackedAddress);
  auto* const scales =
      reinterpret_cast<const std::uint8_t*>(kScaleAddress);
  auto* const activations =
      reinterpret_cast<const std::uint16_t*>(kActivationAddress);
  auto* const overlapping_output = reinterpret_cast<std::uint16_t*>(
      kActivationAddress + 16U * kColumns * sizeof(std::uint16_t));
  auto* const separate_output =
      reinterpret_cast<std::uint16_t*>(0x8'0000'0000ULL);
  struct Candidate {
    const char* label;
    NvFp4M32TestLaunch launch;
  };
  constexpr std::array<Candidate, 7U> kCandidates{{
      {"K64/LD72 dual-A",
       q3x::kernels::
           launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_test_cuda},
      {"K64/LD72 dual-A scale-window",
       q3x::kernels::
           launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_scale_window_test_cuda},
      {"K64/LD72 factorized lookup",
       q3x::kernels::
           launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_lookup_test_cuda},
      {"K64/LD72 factorized vector store",
       q3x::kernels::
           launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_vector_store_test_cuda},
      {"K64/LD72 table-free E2M1",
       q3x::kernels::
           launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_test_cuda},
      {"K64/LD72 table-free single-slot raw-weight cp.async",
       q3x::kernels::
           launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_test_cuda},
      {"K128/LD136 single-A",
       q3x::kernels::
           launch_sm87_nvfp4_w4a16_small_m32_wmma_k128_single_a_test_cuda},
  }};
  for (const Candidate& candidate : kCandidates) {
    const std::string label =
        std::string("NVFP4 test-only M32 invalid capture ") +
        candidate.label;
    cudaGraph_t graph = nullptr;
    bool ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        label + " begin");
    int alias_status = static_cast<int>(cudaErrorUnknown);
    int near_miss_status = static_cast<int>(cudaErrorUnknown);
    if (ready) {
      alias_status = candidate.launch(
          packed, scales, 1.0F, activations, kRows, kColumns,
          overlapping_output, static_cast<void*>(stream));
      near_miss_status = candidate.launch(
          packed, scales, 1.0F, activations, kRows - 1U, kColumns,
          separate_output, static_cast<void*>(stream));
      ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           label + " end") &&
              ready;
    }
    std::size_t node_count = 0U;
    if (ready) {
      ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                           label + " query nodes") &&
              ready;
    }
    if (graph != nullptr) {
      ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy") &&
              ready;
    }
    const bool contract =
        ready && alias_status == static_cast<int>(cudaErrorInvalidValue) &&
        near_miss_status == static_cast<int>(cudaErrorInvalidValue) &&
        node_count == 0U;
    std::cout << "NVFP4_M32_WMMA_INVALID_GRAPH: candidate="
              << candidate.label << " alias_status=" << alias_status
              << " near_miss_status=" << near_miss_status
              << " total_nodes=" << node_count
              << " gate=" << (contract ? "PASS" : "FAIL") << '\n';
    test.expect(contract,
                label + " rejects both launches without capturing a node");
  }

  const std::string public_label =
      "NVFP4 public M32 invalid alias capture";
  cudaGraph_t public_graph = nullptr;
  bool public_ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      public_label + " begin");
  int public_status = static_cast<int>(cudaErrorUnknown);
  if (public_ready) {
    public_status =
        q3x::kernels::launch_sm87_nvfp4_w4a16_m32_gemm_bf16_cuda(
            packed, scales, 1.0F, activations, kRows, kColumns,
            overlapping_output, static_cast<void*>(stream));
    public_ready =
        test.cuda_ok(cudaStreamEndCapture(stream, &public_graph),
                     public_label + " end") &&
        public_ready;
  }
  std::size_t public_node_count = 0U;
  if (public_ready) {
    public_ready =
        test.cuda_ok(
            cudaGraphGetNodes(public_graph, nullptr, &public_node_count),
            public_label + " query nodes") &&
        public_ready;
  }
  if (public_graph != nullptr) {
    public_ready =
        test.cuda_ok(cudaGraphDestroy(public_graph), public_label +
                                                       " destroy") &&
        public_ready;
  }
  const bool public_contract =
      public_ready &&
      public_status == static_cast<int>(cudaErrorInvalidValue) &&
      public_node_count == 0U;
  std::cout << "NVFP4_M32_PUBLIC_INVALID_GRAPH: alias_status="
            << public_status << " total_nodes=" << public_node_count
            << " gate=" << (public_contract ? "PASS" : "FAIL") << '\n';
  test.expect(public_contract,
              public_label + " rejects before capturing a node");
}

void run_nvfp4_m17_m31_runtime_masked_m32_invalid_capture_contract(
    TestContext& test, cudaStream_t stream) {
  constexpr std::size_t kRows = 17'408U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kValidTokens = 31U;
  constexpr std::size_t kMaximum =
      std::numeric_limits<std::size_t>::max();
  constexpr std::size_t kFirstAlignedPastM31 =
      ((kMaximum / kValidTokens) / 16U + 1U) * 16U;
  constexpr std::size_t kLargestAlignedM31 =
      (kMaximum / kValidTokens) & ~std::size_t{15U};
  constexpr std::size_t kFirstM31OutputElementOverflowRows =
      kMaximum / kValidTokens + 1U;
  constexpr std::size_t kFirstM31OutputByteOverflowRows =
      kMaximum / (kValidTokens * sizeof(std::uint16_t)) + 1U;
  auto* const packed =
      reinterpret_cast<const std::uint8_t*>(0x5'0000'0000ULL);
  auto* const scales =
      reinterpret_cast<const std::uint8_t*>(0x6'0000'0000ULL);
  auto* const activations =
      reinterpret_cast<const std::uint16_t*>(0x7'0000'0000ULL);
  auto* const output =
      reinterpret_cast<std::uint16_t*>(0x8'0000'0000ULL);
  const auto launch = [&](const std::uint8_t* const candidate_packed,
                          const std::uint8_t* const candidate_scales,
                          const float scale_2,
                          const std::uint16_t* const candidate_activations,
                          const std::size_t valid_tokens,
                          const std::size_t rows, const std::size_t columns,
                          std::uint16_t* const candidate_output) noexcept {
    return std::array<int, 2U>{
        q3x::kernels::
            launch_sm87_nvfp4_w4a16_small_m17_m31_runtime_masked_m32_test_cuda(
                candidate_packed, candidate_scales, scale_2,
                candidate_activations, valid_tokens, rows, columns,
                candidate_output, static_cast<void*>(stream)),
        q3x::kernels::
            launch_sm87_nvfp4_w4a16_small_m17_m31_runtime_masked_m32_raw_weight_cp_async_test_cuda(
                candidate_packed, candidate_scales, scale_2,
                candidate_activations, valid_tokens, rows, columns,
                candidate_output, static_cast<void*>(stream))};
  };

  const std::string label =
      "NVFP4 test-only M17-M31 runtime-mask invalid capture";
  cudaGraph_t graph = nullptr;
  bool ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin");
  bool runtime_all_invalid = ready;
  bool cp_async_all_invalid = ready;
  const auto expect_invalid = [&](const std::array<int, 2U>& statuses) {
    runtime_all_invalid =
        runtime_all_invalid &&
        static_cast<cudaError_t>(statuses[0]) == cudaErrorInvalidValue;
    cp_async_all_invalid =
        cp_async_all_invalid &&
        static_cast<cudaError_t>(statuses[1]) == cudaErrorInvalidValue;
  };
  if (ready) {
    expect_invalid(launch(packed, scales, 1.0F, activations, 16U, kRows,
                          kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, 32U, kRows,
                          kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens, 0U,
                          kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows, 0U, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows - 1U, kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows + 1U, kColumns, output));
    expect_invalid(launch(nullptr, scales, 1.0F, activations, kValidTokens,
                          kRows, kColumns, output));
    expect_invalid(launch(packed, nullptr, 1.0F, activations, kValidTokens,
                          kRows, kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, nullptr, kValidTokens,
                          kRows, kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows, kColumns, nullptr));
    expect_invalid(launch(packed, scales,
                          std::numeric_limits<float>::quiet_NaN(),
                          activations, kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(packed, scales, -1.0F, activations, kValidTokens,
                          kRows, kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows, kColumns - 1U, output));
    expect_invalid(launch(
        reinterpret_cast<const std::uint8_t*>(
            reinterpret_cast<std::uintptr_t>(packed) + 1U),
        scales, 1.0F, activations, kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed,
        reinterpret_cast<const std::uint8_t*>(
            reinterpret_cast<std::uintptr_t>(scales) + 1U),
        1.0F, activations, kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed, scales, 1.0F,
        reinterpret_cast<const std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(activations) + 2U),
        kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(output) + 1U)));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        const_cast<std::uint16_t*>(activations)));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(packed) + 16U)));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(scales))));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(activations) +
            (kValidTokens - 1U) * kColumns * sizeof(std::uint16_t))));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kMaximum, 16U, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens, 1U,
                          kFirstAlignedPastM31, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kFirstM31OutputElementOverflowRows, 16U, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens, 1U,
                          kLargestAlignedM31, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kFirstM31OutputByteOverflowRows, 16U, output));
    expect_invalid(launch(
        reinterpret_cast<const std::uint8_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 15U),
        scales, 1.0F, activations, kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed,
        reinterpret_cast<const std::uint8_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 1U),
        1.0F, activations, kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed, scales, 1.0F,
        reinterpret_cast<const std::uint16_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 7U),
        kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 1U)));
    ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph), label + " end") &&
            ready;
  }
  std::size_t node_count = 0U;
  if (ready) {
    ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                         label + " query nodes") &&
            ready;
  }
  if (graph != nullptr) {
    ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy") && ready;
  }
  const bool gate = ready && runtime_all_invalid && cp_async_all_invalid &&
                    node_count == 0U;
  std::cout << "NVFP4_M17_M31_RUNTIME_MASKED_M32_INVALID_CAPTURE: "
            << "runtime_all_invalid="
            << (runtime_all_invalid ? "true" : "false")
            << " cp_async_all_invalid="
            << (cp_async_all_invalid ? "true" : "false")
            << " graph_nodes=" << node_count
            << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
  test.expect(gate, label +
                        " rejects boundaries, pointers, aliases, alignment, "
                        "and overflow before enqueue");
}

void run_nvfp4_m17_m31_public_invalid_capture_contract(
    TestContext& test, cudaStream_t stream) {
  constexpr std::size_t kRows = 17'408U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kValidTokens = 31U;
  constexpr std::size_t kMaximum =
      std::numeric_limits<std::size_t>::max();
  constexpr std::size_t kFirstAlignedInputOverflowColumns =
      ((kMaximum / kValidTokens) / 16U + 1U) * 16U;
  constexpr std::size_t kFirstOutputElementOverflowRows =
      kMaximum / kValidTokens + 1U;
  constexpr std::size_t kFirstOutputByteOverflowRows =
      kMaximum / (kValidTokens * sizeof(std::uint16_t)) + 1U;
  auto* const packed =
      reinterpret_cast<const std::uint8_t*>(0x15'0000'0000ULL);
  auto* const scales =
      reinterpret_cast<const std::uint8_t*>(0x25'0000'0000ULL);
  auto* const activations =
      reinterpret_cast<const std::uint16_t*>(0x35'0000'0000ULL);
  auto* const output =
      reinterpret_cast<std::uint16_t*>(0x45'0000'0000ULL);
  const auto launch = [&](const std::uint8_t* const candidate_packed,
                          const std::uint8_t* const candidate_scales,
                          const float scale_2,
                          const std::uint16_t* const candidate_activations,
                          const std::size_t valid_tokens,
                          const std::size_t rows, const std::size_t columns,
                          std::uint16_t* const candidate_output) noexcept {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_m17_m31_gemm_bf16_cuda(
            candidate_packed, candidate_scales, scale_2,
            candidate_activations, valid_tokens, rows, columns,
            candidate_output, static_cast<void*>(stream));
  };

  const std::string label =
      "NVFP4 public M17/M19-M31 invalid capture";
  cudaGraph_t graph = nullptr;
  bool ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin");
  bool all_expected = ready;
  const auto expect_invalid = [&](const int status) {
    all_expected = all_expected &&
                   static_cast<cudaError_t>(status) == cudaErrorInvalidValue;
  };
  const auto expect_success = [&](const int status) {
    all_expected = all_expected &&
                   static_cast<cudaError_t>(status) == cudaSuccess;
  };
  if (ready) {
    expect_invalid(launch(packed, scales, 1.0F, activations, 16U, kRows,
                          kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, 18U, kRows,
                          kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, 32U, kRows,
                          kColumns, output));
    expect_success(launch(nullptr, nullptr, 1.0F, nullptr, 17U, 0U,
                          kColumns, nullptr));
    expect_success(launch(nullptr, nullptr, 1.0F, nullptr, 31U, kRows, 0U,
                          nullptr));
    expect_invalid(launch(nullptr, scales, 1.0F, activations, kValidTokens,
                          kRows, kColumns, output));
    expect_invalid(launch(packed, nullptr, 1.0F, activations, kValidTokens,
                          kRows, kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, nullptr, kValidTokens, kRows,
                          kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows, kColumns, nullptr));
    expect_invalid(launch(packed, scales,
                          std::numeric_limits<float>::quiet_NaN(),
                          activations, kValidTokens, kRows, kColumns,
                          output));
    expect_invalid(launch(packed, scales, -1.0F, activations, kValidTokens,
                          kRows, kColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows, kColumns - 1U, output));
    expect_invalid(launch(
        packed, scales, 1.0F,
        reinterpret_cast<const std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(activations) + 1U),
        kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(output) + 1U)));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kRows, kColumns,
                          const_cast<std::uint16_t*>(activations)));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(activations) +
            (kValidTokens - 1U) * kColumns * sizeof(std::uint16_t))));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kMaximum, 16U, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens, 1U,
                          kFirstAlignedInputOverflowColumns, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kFirstOutputElementOverflowRows, 16U, output));
    expect_invalid(launch(packed, scales, 1.0F, activations, kValidTokens,
                          kFirstOutputByteOverflowRows, 16U, output));
    expect_invalid(launch(
        reinterpret_cast<const std::uint8_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 15U),
        scales, 1.0F, activations, kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed,
        reinterpret_cast<const std::uint8_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 1U),
        1.0F, activations, kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed, scales, 1.0F,
        reinterpret_cast<const std::uint16_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 7U),
        kValidTokens, kRows, kColumns, output));
    expect_invalid(launch(
        packed, scales, 1.0F, activations, kValidTokens, kRows, kColumns,
        reinterpret_cast<std::uint16_t*>(
            std::numeric_limits<std::uintptr_t>::max() - 1U)));
    expect_invalid(
        q3x::kernels::launch_sm87_nvfp4_w4a16_m18_gemm_bf16_cuda(
            packed, scales, 1.0F, activations, kRows, kColumns,
            reinterpret_cast<std::uint16_t*>(
                reinterpret_cast<std::uintptr_t>(output) + 1U),
            static_cast<void*>(stream)));
    ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph), label + " end") &&
            ready;
  }
  std::size_t node_count = 0U;
  if (ready) {
    ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                         label + " query nodes") &&
            ready;
  }
  if (graph != nullptr) {
    ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy") && ready;
  }
  const bool gate = ready && all_expected && node_count == 0U;
  std::cout << "NVFP4_M17_M31_PUBLIC_INVALID_CAPTURE: all_expected="
            << (all_expected ? "true" : "false")
            << " graph_nodes=" << node_count
            << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
  test.expect(gate,
              label + " rejects invalid exact spans before any enqueue");
}

void run_nvfp4_m32_raw_weight_cp_async_production_identity(
    TestContext& test, cudaStream_t stream) {
  constexpr std::uintptr_t kPackedAddress = 0x10'0000'0000ULL;
  constexpr std::uintptr_t kScaleAddress = 0x20'0000'0000ULL;
  constexpr std::uintptr_t kActivationAddress = 0x30'0000'0000ULL;
  constexpr std::uintptr_t kOutputAddress = 0x40'0000'0000ULL;
  constexpr std::size_t kGateRows = 17'408U;
  constexpr std::size_t kGateColumns = 5'120U;
  constexpr std::size_t kDownRows = 5'120U;
  constexpr std::size_t kDownColumns = 17'408U;
  const auto* const packed =
      reinterpret_cast<const std::uint8_t*>(kPackedAddress);
  const auto* const scales =
      reinterpret_cast<const std::uint8_t*>(kScaleAddress);
  const auto* const activations =
      reinterpret_cast<const std::uint16_t*>(kActivationAddress);
  auto* const output = reinterpret_cast<std::uint16_t*>(kOutputAddress);

  const NvFp4M32CapturedKernel gate_baseline = capture_nvfp4_m32_kernel(
      test, stream,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_test_cuda,
      packed, scales, 1.0F, activations, kGateRows, kGateColumns, output,
      "NVFP4 M32 gate table-free baseline graph");
  const NvFp4M32CapturedKernel gate_candidate = capture_nvfp4_m32_kernel(
      test, stream,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_test_cuda,
      packed, scales, 1.0F, activations, kGateRows, kGateColumns, output,
      "NVFP4 M32 gate raw-weight cp.async graph");
  const NvFp4M32CapturedKernel gate_public = capture_nvfp4_m32_kernel(
      test, stream,
      q3x::kernels::launch_sm87_nvfp4_w4a16_m32_gemm_bf16_cuda, packed,
      scales, 1.0F, activations, kGateRows, kGateColumns, output,
      "NVFP4 M32 gate public production graph");
  const NvFp4M32CapturedKernel down_baseline = capture_nvfp4_m32_kernel(
      test, stream,
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_test_cuda,
      packed, scales, 1.0F, activations, kDownRows, kDownColumns, output,
      "NVFP4 M32 down table-free baseline graph");
  const NvFp4M32CapturedKernel down_public = capture_nvfp4_m32_kernel(
      test, stream,
      q3x::kernels::launch_sm87_nvfp4_w4a16_m32_gemm_bf16_cuda, packed,
      scales, 1.0F, activations, kDownRows, kDownColumns, output,
      "NVFP4 M32 down public production graph");

  const auto topology_matches = [](const NvFp4M32CapturedKernel& capture,
                                   const std::size_t rows) noexcept {
    return capture.valid && capture.grid.x == rows / 128U &&
           capture.grid.y == 1U && capture.grid.z == 1U &&
           capture.block.x == 256U && capture.block.y == 1U &&
           capture.block.z == 1U && capture.dynamic_shared_bytes == 0U;
  };
  int registers_per_thread = -1;
  std::size_t static_shared_bytes = std::numeric_limits<std::size_t>::max();
  std::size_t local_bytes = std::numeric_limits<std::size_t>::max();
  int maximum_threads_per_block = -1;
  int active_blocks_per_sm = -1;
  const int resource_status =
      q3x::kernels::
          query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_resources_test_cuda(
              kGateRows, kGateColumns, &registers_per_thread,
              &static_shared_bytes, &local_bytes, &maximum_threads_per_block,
              &active_blocks_per_sm);
  const bool resource_gate =
      resource_status == static_cast<int>(cudaSuccess) &&
      registers_per_thread <= 51 && static_shared_bytes == 27'648U &&
      local_bytes == 0U && maximum_threads_per_block == 256 &&
      active_blocks_per_sm >= 5;
  const bool identity_gate =
      topology_matches(gate_baseline, kGateRows) &&
      topology_matches(gate_candidate, kGateRows) &&
      topology_matches(gate_public, kGateRows) &&
      topology_matches(down_baseline, kDownRows) &&
      topology_matches(down_public, kDownRows) &&
      gate_public.function == gate_candidate.function &&
      gate_public.function != gate_baseline.function &&
      down_public.function == down_baseline.function &&
      down_public.function != gate_candidate.function && resource_gate;
  std::cout << "NVFP4_M32_RAW_WEIGHT_CP_ASYNC_PRODUCTION_IDENTITY: "
            << "gate_baseline_nodes=" << gate_baseline.kernel_nodes
            << " gate_candidate_nodes=" << gate_candidate.kernel_nodes
            << " gate_public_nodes=" << gate_public.kernel_nodes
            << " gate_public_candidate_same_func="
            << (gate_public.function == gate_candidate.function ? "true"
                                                                 : "false")
            << " gate_public_baseline_distinct="
            << (gate_public.function != gate_baseline.function ? "true"
                                                                : "false")
            << " down_public_nodes=" << down_public.kernel_nodes
            << " down_public_baseline_same_func="
            << (down_public.function == down_baseline.function ? "true"
                                                                : "false")
            << " registers=" << registers_per_thread
            << " static_shared_bytes=" << static_shared_bytes
            << " local_bytes=" << local_bytes
            << " active_blocks_per_sm=" << active_blocks_per_sm
            << " gate=" << (identity_gate ? "PASS" : "FAIL") << '\n';
  test.expect(identity_gate,
              "NVFP4 exact-M32 gate/up selects raw-weight cp.async while "
              "down retains table-free baseline identity and resources");
}

void run_nvfp4_m32_public_fallback_graph_contract(TestContext& test,
                                                   cudaStream_t stream) {
  constexpr std::uintptr_t kPackedAddress = 0x10'0000'0000ULL;
  constexpr std::uintptr_t kScaleAddress = 0x20'0000'0000ULL;
  constexpr std::uintptr_t kActivationAddress = 0x30'0000'0000ULL;
  constexpr std::uintptr_t kOutputAddress = 0x40'0000'0000ULL;
  struct Case {
    const char* label;
    std::uintptr_t packed_address;
    std::uintptr_t scale_address;
    std::uintptr_t activation_address;
    std::size_t rows;
    std::size_t columns;
    std::size_t expected_kernel_nodes;
  };
  constexpr std::array<Case, 6U> kCases{{
      {"generic 13x48", kPackedAddress, kScaleAddress, kActivationAddress,
       13U, 48U, 32U},
      {"near-miss rows 17407x5120", kPackedAddress, kScaleAddress,
       kActivationAddress, 17'407U, 5'120U, 4U},
      {"4-byte-only packed-weight alignment 17408x5120",
       kPackedAddress + 4U, kScaleAddress, kActivationAddress, 17'408U,
       5'120U, 4U},
      {"misaligned packed weights 17408x5120", kPackedAddress + 1U,
       kScaleAddress, kActivationAddress, 17'408U, 5'120U, 32U},
      {"misaligned block scales 17408x5120", kPackedAddress,
       kScaleAddress + 1U, kActivationAddress, 17'408U, 5'120U, 4U},
      {"BF16-only activation alignment 17408x5120", kPackedAddress,
       kScaleAddress, kActivationAddress + sizeof(std::uint16_t), 17'408U,
       5'120U, 32U},
  }};

  for (const Case& test_case : kCases) {
    const std::string label =
        std::string("NVFP4 public M32 fallback graph ") + test_case.label;
    const auto* const packed =
        reinterpret_cast<const std::uint8_t*>(test_case.packed_address);
    const auto* const scales =
        reinterpret_cast<const std::uint8_t*>(test_case.scale_address);
    const auto* const activations =
        reinterpret_cast<const std::uint16_t*>(
            test_case.activation_address);
    auto* const output =
        reinterpret_cast<std::uint16_t*>(kOutputAddress);
    cudaGraph_t graph = nullptr;
    bool ready = test.cuda_ok(
        cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
        label + " begin");
    int launch_status = static_cast<int>(cudaErrorUnknown);
    if (ready) {
      launch_status =
          q3x::kernels::launch_sm87_nvfp4_w4a16_m32_gemm_bf16_cuda(
              packed, scales, 1.0F, activations, test_case.rows,
              test_case.columns, output, static_cast<void*>(stream));
      ready = test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           label + " end") &&
              ready;
    }
    std::size_t node_count = 0U;
    std::size_t kernel_node_count = 0U;
    if (ready) {
      ready = test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &node_count),
                           label + " query nodes") &&
              ready;
    }
    if (ready && node_count != 0U) {
      std::vector<cudaGraphNode_t> nodes(node_count);
      std::size_t capacity = nodes.size();
      ready = test.cuda_ok(
                  cudaGraphGetNodes(graph, nodes.data(), &capacity),
                  label + " get nodes") &&
              ready;
      for (std::size_t index = 0U; index < capacity && ready; ++index) {
        cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
        ready = test.cuda_ok(cudaGraphNodeGetType(nodes[index], &type),
                             label + " inspect node") &&
                ready;
        kernel_node_count += type == cudaGraphNodeTypeKernel ? 1U : 0U;
      }
    }
    if (graph != nullptr) {
      ready = test.cuda_ok(cudaGraphDestroy(graph), label + " destroy") &&
              ready;
    }
    const bool contract =
        ready && launch_status == static_cast<int>(cudaSuccess) &&
        node_count == test_case.expected_kernel_nodes &&
        kernel_node_count == test_case.expected_kernel_nodes;
    std::cout << "NVFP4_M32_PUBLIC_FALLBACK_GRAPH: " << test_case.label
              << " launch_status=" << launch_status
              << " total_nodes=" << node_count
              << " kernel_nodes=" << kernel_node_count
              << " expected=" << test_case.expected_kernel_nodes
              << " gate=" << (contract ? "PASS" : "FAIL") << '\n';
    test.expect(contract,
                label + " preserves the expected ordered fallback");
  }
}

constexpr std::array<NvFp4M1ScaleDistribution, 2U>
    kNvFp4M16K128ScaleDistributions{{
        NvFp4M1ScaleDistribution::kCheckpointLike,
        NvFp4M1ScaleDistribution::kSameBankStress,
    }};

struct NvFp4M16K128DistributionMeasurement {
  float current_k64_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_k128_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
  bool output_finite = false;
  bool production_bitwise_equal = false;
  bool production_output_finite = false;
};

struct NvFp4M16K128ShapeMeasurement {
  std::array<NvFp4M16K128DistributionMeasurement,
             kNvFp4M16K128ScaleDistributions.size()>
      distributions{};
};

struct NvFp4M16K128Shape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  const char* label;
};

[[nodiscard]] NvFp4M16K128ShapeMeasurement
benchmark_nvfp4_m16_k128_shape(TestContext& test, cudaStream_t stream,
                                const NvFp4M16K128Shape& shape) {
  constexpr std::size_t kTokens = 16U;
  const std::size_t kRows = shape.rows;
  const std::size_t kColumns = shape.columns;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr float kMinimumCellSpeedup = 1.02F;
  constexpr std::uint8_t kCurrentOutputSentinel = 0xa5U;
  constexpr std::uint8_t kCandidateOutputSentinel = 0x5aU;
  constexpr std::uint8_t kProductionOutputSentinel = 0x3cU;
  const std::string label = shape.label;
  const std::size_t packed_columns = kColumns / 2U;
  const std::size_t scale_columns = kColumns / 16U;

  std::vector<std::uint8_t> host_packed(kRows * packed_columns);
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t row = 0U; row < kRows; ++row) {
    for (std::size_t packed_column = 0U; packed_column < packed_columns;
         ++packed_column) {
      const std::uint8_t low = static_cast<std::uint8_t>(
          (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
      const std::uint8_t high = static_cast<std::uint8_t>(
          (packed_column * 5U + row * 7U +
           (packed_column >> 3U) * 3U + 1U) &
          0x0fU);
      host_packed[row * packed_columns + packed_column] =
          static_cast<std::uint8_t>(low | (high << 4U));
      low_nibble_covered[low] = true;
      high_nibble_covered[high] = true;
    }
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 low-nibble code");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 high-nibble code");

  std::vector<std::uint8_t> host_scales(kRows * scale_columns);
  std::vector<std::uint16_t> host_activations(kTokens * kColumns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * kColumns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> current_k64_output;
  DeviceBuffer<std::uint16_t> candidate_k128_output;
  bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready &&
          test.cuda_ok(current_k64_output.allocate(kTokens * kRows),
                       label + " allocate current K64 output");
  ready = ready &&
          test.cuda_ok(candidate_k128_output.allocate(kTokens * kRows),
                       label + " allocate candidate K128 output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), host_packed.data(),
                                       host_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed all-nibble weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  if (!ready) {
    return {};
  }

  std::vector<std::uint16_t> current_k64(kTokens * kRows);
  std::vector<std::uint16_t> candidate_k128(kTokens * kRows);
  NvFp4M16K128ShapeMeasurement shape_measurement{};
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M16K128ScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                     distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize scales");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             current_k64_output.get(), kCurrentOutputSentinel,
                             kTokens * kRows * sizeof(std::uint16_t), stream),
                         distribution_label +
                             " initialize current K64 output sentinel");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             candidate_k128_output.get(),
                             kCandidateOutputSentinel,
                             kTokens * kRows * sizeof(std::uint16_t), stream),
                         distribution_label +
                             " initialize candidate K128 output sentinel");
    if (!ready) {
      return shape_measurement;
    }

    const auto launch_current_k64 = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m16_wmma_fixed_shape_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activations.get(),
              kRows, kColumns, current_k64_output.get(),
              static_cast<void*>(stream));
    };
    const auto launch_candidate_k128 = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m16_wmma_k128_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activations.get(),
              kRows, kColumns, candidate_k128_output.get(),
              static_cast<void*>(stream));
    };
    const auto launch_production = [&]() noexcept -> int {
      return q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
          packed.get(), scales.get(), kWeightScale2, activations.get(), kRows,
          kColumns, candidate_k128_output.get(), static_cast<void*>(stream));
    };

    ready = test.cuda_ok(static_cast<cudaError_t>(launch_current_k64()),
                         distribution_label + " correctness current K64");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate_k128()),
                         distribution_label + " correctness K128/LD136");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             current_k64.data(), current_k64_output.get(),
                             current_k64.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy current K64");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_k128.data(),
                             candidate_k128_output.get(),
                             candidate_k128.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy candidate K128");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " correctness synchronize");
    if (!ready) {
      return shape_measurement;
    }

    std::size_t mismatches = 0U;
    bool output_finite = true;
    for (std::size_t index = 0U; index < current_k64.size(); ++index) {
      mismatches += current_k64[index] != candidate_k128[index] ? 1U : 0U;
      output_finite = output_finite &&
                      std::isfinite(decode_bf16(current_k64[index])) &&
                      std::isfinite(decode_bf16(candidate_k128[index]));
    }
    NvFp4M16K128DistributionMeasurement& measurement =
        shape_measurement.distributions[distribution_index];
    measurement.bitwise_equal = mismatches == 0U;
    measurement.output_finite = output_finite;
    std::cout << "NVFP4_M16_K128_DIFF: " << label << " distribution="
              << nvfp4_m1_scale_distribution_name(distribution)
              << " current_k64_vs_k128_ld136_mismatches=" << mismatches << '/'
              << current_k64.size()
              << " output_finite=" << (output_finite ? "true" : "false")
              << '\n';
    test.expect(measurement.bitwise_equal,
                distribution_label +
                    " K128/LD136 is bitwise equal to current K64");
    test.expect(output_finite,
                distribution_label + " K64 and K128 outputs remain finite");

    ready = test.cuda_ok(
        cudaMemsetAsync(candidate_k128_output.get(),
                        kProductionOutputSentinel,
                        kTokens * kRows * sizeof(std::uint16_t), stream),
        distribution_label + " poison production output");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_production()),
                         distribution_label + " launch production M16");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_k128.data(),
                             candidate_k128_output.get(),
                             candidate_k128.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy production M16 output");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label +
                             " production correctness synchronize");
    if (!ready) {
      return shape_measurement;
    }

    std::size_t production_mismatches = 0U;
    bool production_output_finite = true;
    for (std::size_t index = 0U; index < current_k64.size(); ++index) {
      production_mismatches +=
          current_k64[index] != candidate_k128[index] ? 1U : 0U;
      production_output_finite =
          production_output_finite &&
          std::isfinite(decode_bf16(current_k64[index])) &&
          std::isfinite(decode_bf16(candidate_k128[index]));
    }
    measurement.production_bitwise_equal = production_mismatches == 0U;
    measurement.production_output_finite = production_output_finite;
    std::cout << "NVFP4_M16_K128_PRODUCTION_DIFF: " << label
              << " distribution="
              << nvfp4_m1_scale_distribution_name(distribution)
              << " current_k64_vs_public_m16_mismatches="
              << production_mismatches << '/' << current_k64.size()
              << " output_finite="
              << (production_output_finite ? "true" : "false") << '\n';
    test.expect(measurement.production_bitwise_equal,
                distribution_label +
                    " public production M16 is bitwise equal to current K64");
    test.expect(production_output_finite,
                distribution_label +
                    " public production M16 output remains finite");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_current_k64()),
                           distribution_label + " current K64 warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate_k128()),
                           distribution_label + " K128/LD136 warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " warmup synchronize");
    if (!ready) {
      return shape_measurement;
    }

    double current_k64_total = 0.0;
    double candidate_k128_total = 0.0;
    bool finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string suffix =
          distribution_label + " round=" + std::to_string(round + 1);
      const float current_first = measure_small_m_tile(
          test, stream, launch_current_k64, kMeasuredIterations,
          suffix + " current K64 pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate_k128, kMeasuredIterations,
          suffix + " candidate K128 pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate_k128, kMeasuredIterations,
          suffix + " candidate K128 pass 2");
      const float current_second = measure_small_m_tile(
          test, stream, launch_current_k64, kMeasuredIterations,
          suffix + " current K64 pass 2");
      const bool round_finite =
          std::isfinite(current_first) && std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) && std::isfinite(current_second);
      finite = finite && round_finite;
      if (round_finite) {
        current_k64_total += current_first + current_second;
        candidate_k128_total += candidate_first + candidate_second;
      }
      std::cout << "PERF_NVFP4_M16_K128_ROUND: " << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " round=" << round + 1
                << " current_k64_pass1_ms=" << current_first
                << " candidate_k128_pass1_ms=" << candidate_first
                << " candidate_k128_pass2_ms=" << candidate_second
                << " current_k64_pass2_ms=" << current_second << '\n';
    }
    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    measurement.current_k64_milliseconds =
        finite ? static_cast<float>(current_k64_total / kTimedPasses)
               : std::numeric_limits<float>::quiet_NaN();
    measurement.candidate_k128_milliseconds =
        finite ? static_cast<float>(candidate_k128_total / kTimedPasses)
               : std::numeric_limits<float>::quiet_NaN();
    const float speedup = measurement.current_k64_milliseconds /
                          measurement.candidate_k128_milliseconds;
    const bool valid =
        finite && std::isfinite(measurement.current_k64_milliseconds) &&
        std::isfinite(measurement.candidate_k128_milliseconds) &&
        std::isfinite(speedup) &&
        measurement.current_k64_milliseconds > 0.0F &&
        measurement.candidate_k128_milliseconds > 0.0F;
    const bool gate = measurement.bitwise_equal && measurement.output_finite &&
                      measurement.production_bitwise_equal &&
                      measurement.production_output_finite && valid &&
                      speedup >= kMinimumCellSpeedup;
    test.expect(gate, distribution_label + " clears K128/LD136 gate");
    std::cout << "PERF_NVFP4_M16_K128_VALIDATION: " << label
              << " distribution="
              << nvfp4_m1_scale_distribution_name(distribution)
              << " current_k64_ms=" << measurement.current_k64_milliseconds
              << " candidate_k128_ms="
              << measurement.candidate_k128_milliseconds
              << " speedup=" << speedup
              << " required_speedup=" << kMinimumCellSpeedup
              << " bitwise="
              << (measurement.bitwise_equal ? "true" : "false")
              << " output_finite="
              << (measurement.output_finite ? "true" : "false")
              << " production_bitwise="
              << (measurement.production_bitwise_equal ? "true" : "false")
              << " production_output_finite="
              << (measurement.production_output_finite ? "true" : "false")
              << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
  }
  return shape_measurement;
}

void run_optional_nvfp4_m16_k128_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!nvfp4_m16_k128_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M16 K128/LD136 performance segment; set "
                 "Q3X_RUN_SM87_NVFP4_M16_K128_PERF=1 to enable\n";
    return;
  }

  constexpr float kMinimumCellSpeedup = 1.02F;
  constexpr double kMinimumWeightedSpeedup = 1.05;
  constexpr std::array<NvFp4M16K128Shape, 2U> kShapes{{
      {17'408U, 5'120U, 128U,
       "NVFP4 M16 gate/up 17408x5120 K128/LD136"},
      {5'120U, 17'408U, 64U,
       "NVFP4 M16 down 5120x17408 K128/LD136"},
  }};

  std::array<NvFp4M16K128ShapeMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] =
        benchmark_nvfp4_m16_k128_shape(test, stream, kShapes[shape_index]);
  }

  double weighted_current_k64 = 0.0;
  double weighted_candidate_k128 = 0.0;
  bool all_cells_pass = true;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    double shape_current_k64 = 0.0;
    double shape_candidate_k128 = 0.0;
    bool shape_cells_pass = true;
    for (std::size_t distribution_index = 0U;
         distribution_index < kNvFp4M16K128ScaleDistributions.size();
         ++distribution_index) {
      const NvFp4M16K128DistributionMeasurement& cell =
          measurements[shape_index].distributions[distribution_index];
      const double speedup =
          static_cast<double>(cell.current_k64_milliseconds) /
          static_cast<double>(cell.candidate_k128_milliseconds);
      const bool finite =
          std::isfinite(cell.current_k64_milliseconds) &&
          std::isfinite(cell.candidate_k128_milliseconds) &&
          cell.current_k64_milliseconds > 0.0F &&
          cell.candidate_k128_milliseconds > 0.0F &&
          std::isfinite(speedup);
      const bool cell_gate =
          cell.bitwise_equal && cell.output_finite &&
          cell.production_bitwise_equal && cell.production_output_finite &&
          finite && speedup >= kMinimumCellSpeedup;
      shape_cells_pass = shape_cells_pass && cell_gate;
      all_cells_pass = all_cells_pass && cell_gate;
      shape_current_k64 += cell.current_k64_milliseconds;
      shape_candidate_k128 += cell.candidate_k128_milliseconds;
      weighted_current_k64 +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          cell.current_k64_milliseconds;
      weighted_candidate_k128 +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          cell.candidate_k128_milliseconds;
    }
    const double shape_speedup = shape_current_k64 / shape_candidate_k128;
    std::cout << "PERF_NVFP4_M16_K128_SHAPE_AGGREGATE: "
              << kShapes[shape_index].label
              << " current_k64_ms=" << shape_current_k64
              << " candidate_k128_ms=" << shape_candidate_k128
              << " speedup=" << shape_speedup
              << " profile_calls=" << kShapes[shape_index].profile_calls
              << " all_cells=" << (shape_cells_pass ? "PASS" : "FAIL")
              << '\n';
  }

  const double weighted_speedup =
      weighted_current_k64 / weighted_candidate_k128;
  const bool aggregate_gate =
      all_cells_pass && std::isfinite(weighted_speedup) &&
      weighted_current_k64 > 0.0 && weighted_candidate_k128 > 0.0 &&
      weighted_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_NVFP4_M16_K128_AGGREGATE: weighted_current_k64_ms="
            << weighted_current_k64
            << " weighted_candidate_k128_ms=" << weighted_candidate_k128
            << " speedup=" << weighted_speedup
            << " required_speedup=" << kMinimumWeightedSpeedup
            << " profile_calls=128:64"
            << " distributions=checkpoint_like:same_bank_stress"
            << " all_cells=" << (all_cells_pass ? "PASS" : "FAIL")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "NVFP4 M16 gate/up and down K128/LD136 clear the weighted "
              "production gate");
}

struct NvFp4M32WmmaCellMeasurement {
  double k64_baseline_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double k128_baseline_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double k64_dual_a_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double k128_single_a_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double scale_window_reference_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double scale_window_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double factorized_reference_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double factorized_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double vector_store_reference_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  double vector_store_milliseconds =
      std::numeric_limits<double>::quiet_NaN();
  bool k64_bitwise_equal = false;
  bool k128_bitwise_equal = false;
  bool scale_window_bitwise_equal = false;
  bool factorized_bitwise_equal = false;
  bool vector_store_bitwise_equal = false;
  bool output_finite = false;
};

struct NvFp4M32WmmaShapeMeasurement {
  std::array<NvFp4M32WmmaCellMeasurement,
             kNvFp4M16K128ScaleDistributions.size()>
      distributions{};
};

struct NvFp4M32WmmaShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  const char* label;
};

[[nodiscard]] NvFp4M32WmmaShapeMeasurement
benchmark_nvfp4_m32_wmma_shape(TestContext& test, cudaStream_t stream,
                                const NvFp4M32WmmaShape& shape) {
  constexpr std::size_t kTokens = 32U;
  constexpr std::size_t kPanelTokens = 16U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  // An even round count balances which candidate is measured first while
  // every individual comparison still uses the mirrored B-C-C-B order.
  constexpr int kMeasurementRounds = 4;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  const std::size_t packed_columns = shape.columns / 2U;
  const std::size_t scale_columns = shape.columns / 16U;
  const std::size_t output_elements = kTokens * shape.rows;
  const std::string label = shape.label;

  std::vector<std::uint8_t> host_packed(shape.rows * packed_columns);
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t row = 0U; row < shape.rows; ++row) {
    for (std::size_t packed_column = 0U; packed_column < packed_columns;
         ++packed_column) {
      const std::uint8_t low = static_cast<std::uint8_t>(
          (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
      const std::uint8_t high = static_cast<std::uint8_t>(
          (packed_column * 5U + row * 7U +
           (packed_column >> 3U) * 3U + 1U) &
          0x0fU);
      host_packed[row * packed_columns + packed_column] =
          static_cast<std::uint8_t>(low | (high << 4U));
      low_nibble_covered[low] = true;
      high_nibble_covered[high] = true;
    }
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 low-nibble code");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 high-nibble code");

  std::vector<std::uint8_t> host_scales(shape.rows * scale_columns);
  std::vector<std::uint16_t> host_activations(kTokens * shape.columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < shape.columns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * shape.columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> k64_output;
  DeviceBuffer<std::uint16_t> k128_output;
  DeviceBuffer<std::uint16_t> scale_window_output;
  DeviceBuffer<std::uint16_t> factorized_output;
  DeviceBuffer<std::uint16_t> vector_store_output;
  bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activations.allocate(host_activations.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(baseline_output.allocate(output_elements),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(k64_output.allocate(output_elements),
                                label + " allocate K64 dual-A output");
  ready = ready && test.cuda_ok(k128_output.allocate(output_elements),
                                label + " allocate K128 single-A output");
  ready = ready && test.cuda_ok(
                       scale_window_output.allocate(output_elements),
                       label + " allocate K64 scale-window output");
  ready = ready && test.cuda_ok(
                       factorized_output.allocate(output_elements),
                       label + " allocate K64 factorized-lookup output");
  ready = ready && test.cuda_ok(
                       vector_store_output.allocate(output_elements),
                       label + " allocate K64 factorized-vector output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), host_packed.data(),
                                       host_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed all-nibble weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  if (!ready) {
    return {};
  }

  const auto launch_baseline = [&]() noexcept -> int {
    int status = q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2, activations.get(),
        shape.rows, shape.columns, baseline_output.get(),
        static_cast<void*>(stream));
    if (status != static_cast<int>(cudaSuccess)) {
      return status;
    }
    return q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2,
        activations.get() + kPanelTokens * shape.columns, shape.rows,
        shape.columns, baseline_output.get() + kPanelTokens * shape.rows,
        static_cast<void*>(stream));
  };
  const auto launch_k64 = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, k64_output.get(),
            static_cast<void*>(stream));
  };
  const auto launch_k128 = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k128_single_a_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, k128_output.get(),
            static_cast<void*>(stream));
  };
  const auto launch_scale_window = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_scale_window_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, scale_window_output.get(),
            static_cast<void*>(stream));
  };
  const auto launch_factorized = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_lookup_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, factorized_output.get(),
            static_cast<void*>(stream));
  };
  const auto launch_vector_store = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_vector_store_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, vector_store_output.get(),
            static_cast<void*>(stream));
  };

  std::vector<std::uint16_t> baseline(output_elements);
  std::vector<std::uint16_t> candidate_k64(output_elements);
  std::vector<std::uint16_t> candidate_k128(output_elements);
  std::vector<std::uint16_t> candidate_scale_window(output_elements);
  std::vector<std::uint16_t> candidate_factorized(output_elements);
  std::vector<std::uint16_t> candidate_vector_store(output_elements);
  NvFp4M32WmmaShapeMeasurement shape_measurement{};
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M16K128ScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                     distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize scales");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         distribution_label + " correctness two-M16 baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_k64()),
                         distribution_label + " correctness K64 dual-A");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_k128()),
                         distribution_label + " correctness K128 single-A");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_scale_window()),
                         distribution_label +
                             " correctness K64 scale-window");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_factorized()),
                         distribution_label +
                             " correctness K64 factorized lookup");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_vector_store()),
                         distribution_label +
                             " correctness K64 factorized vector store");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy baseline");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_k64.data(), k64_output.get(),
                             candidate_k64.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy K64 dual-A");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_k128.data(), k128_output.get(),
                             candidate_k128.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy K128 single-A");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_scale_window.data(),
                             scale_window_output.get(),
                             candidate_scale_window.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy K64 scale-window");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_factorized.data(),
                             factorized_output.get(),
                             candidate_factorized.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label +
                             " copy K64 factorized lookup");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_vector_store.data(),
                             vector_store_output.get(),
                             candidate_vector_store.size() *
                                 sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label +
                             " copy K64 factorized vector store");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " correctness synchronize");
    if (!ready) {
      return shape_measurement;
    }

    std::size_t k64_mismatches = 0U;
    std::size_t k128_mismatches = 0U;
    std::size_t scale_window_mismatches = 0U;
    std::size_t factorized_mismatches = 0U;
    std::size_t vector_store_mismatches = 0U;
    bool output_finite = true;
    for (std::size_t index = 0U; index < output_elements; ++index) {
      k64_mismatches += baseline[index] != candidate_k64[index] ? 1U : 0U;
      k128_mismatches +=
          baseline[index] != candidate_k128[index] ? 1U : 0U;
      scale_window_mismatches +=
          candidate_k64[index] != candidate_scale_window[index] ? 1U : 0U;
      factorized_mismatches +=
          candidate_scale_window[index] != candidate_factorized[index]
              ? 1U
              : 0U;
      vector_store_mismatches +=
          candidate_factorized[index] != candidate_vector_store[index]
              ? 1U
              : 0U;
      output_finite = output_finite &&
                      std::isfinite(decode_bf16(baseline[index])) &&
                      std::isfinite(decode_bf16(candidate_k64[index])) &&
                      std::isfinite(decode_bf16(candidate_k128[index])) &&
                      std::isfinite(
                          decode_bf16(candidate_scale_window[index])) &&
                      std::isfinite(
                          decode_bf16(candidate_factorized[index])) &&
                      std::isfinite(
                          decode_bf16(candidate_vector_store[index]));
    }
    NvFp4M32WmmaCellMeasurement& measurement =
        shape_measurement.distributions[distribution_index];
    measurement.k64_bitwise_equal = k64_mismatches == 0U;
    measurement.k128_bitwise_equal = k128_mismatches == 0U;
    measurement.scale_window_bitwise_equal =
        scale_window_mismatches == 0U;
    measurement.factorized_bitwise_equal = factorized_mismatches == 0U;
    measurement.vector_store_bitwise_equal =
        vector_store_mismatches == 0U;
    measurement.output_finite = output_finite;
    std::cout << "NVFP4_M32_WMMA_DIFF: " << label << " distribution="
              << nvfp4_m1_scale_distribution_name(distribution)
              << " k64_vs_two_public_m16_bf16=" << k64_mismatches << '/'
              << output_elements
              << " k128_vs_two_public_m16_bf16=" << k128_mismatches << '/'
              << output_elements
              << " scale_window_vs_previous_production_k64="
              << scale_window_mismatches << '/' << output_elements
              << " factorized_vs_scale_window=" << factorized_mismatches
              << '/' << output_elements
              << " vector_store_vs_factorized=" << vector_store_mismatches
              << '/' << output_elements
              << " output_finite=" << (output_finite ? "true" : "false")
              << '\n';
    test.expect(measurement.k64_bitwise_equal,
                distribution_label + " K64 dual-A is bit-exact");
    test.expect(measurement.k128_bitwise_equal,
                distribution_label + " K128 single-A is bit-exact");
    test.expect(measurement.scale_window_bitwise_equal,
                distribution_label +
                    " K64 scale-window is bit-exact to previous production K64");
    test.expect(measurement.factorized_bitwise_equal,
                distribution_label +
                    " K64 factorized lookup is bit-exact to scale-window");
    test.expect(measurement.vector_store_bitwise_equal,
                distribution_label +
                    " K64 factorized vector store is bit-exact");
    test.expect(output_finite, distribution_label + " outputs remain finite");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           distribution_label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_k64()),
                           distribution_label + " K64 warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_k128()),
                           distribution_label + " K128 warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_scale_window()),
                           distribution_label + " scale-window warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_factorized()),
                           distribution_label + " factorized warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_vector_store()),
                           distribution_label + " vector-store warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " warmup synchronize");
    if (!ready) {
      return shape_measurement;
    }

    double k64_baseline_total = 0.0;
    double k128_baseline_total = 0.0;
    double k64_total = 0.0;
    double k128_total = 0.0;
    double scale_window_reference_total = 0.0;
    double scale_window_total = 0.0;
    double factorized_reference_total = 0.0;
    double factorized_total = 0.0;
    double vector_store_reference_total = 0.0;
    double vector_store_total = 0.0;
    bool k64_timings_finite = true;
    bool k128_timings_finite = true;
    bool scale_window_timings_finite = true;
    bool factorized_timings_finite = true;
    bool vector_store_timings_finite = true;
    const auto measure_mirrored_pair =
        [&](const auto& launch_reference, const auto& launch_candidate,
            const char* const reference_name,
            const char* const candidate_name, double& baseline_total,
            double& candidate_total,
            bool& candidate_timings_finite, const int round) {
          const std::string suffix =
              distribution_label + " round=" + std::to_string(round + 1) +
              " " + candidate_name;
          const float baseline_first = measure_small_m_tile(
              test, stream, launch_reference, kMeasuredIterations,
              suffix + " baseline pass 1");
          const float candidate_first = measure_small_m_tile(
              test, stream, launch_candidate, kMeasuredIterations,
              suffix + " candidate pass 1");
          const float candidate_second = measure_small_m_tile(
              test, stream, launch_candidate, kMeasuredIterations,
              suffix + " candidate pass 2");
          const float baseline_second = measure_small_m_tile(
              test, stream, launch_reference, kMeasuredIterations,
              suffix + " baseline pass 2");
          const bool pair_finite =
              std::isfinite(baseline_first) &&
              std::isfinite(candidate_first) &&
              std::isfinite(candidate_second) &&
              std::isfinite(baseline_second);
          candidate_timings_finite =
              candidate_timings_finite && pair_finite;
          if (pair_finite) {
            baseline_total += baseline_first + baseline_second;
            candidate_total += candidate_first + candidate_second;
          }
          std::cout << "PERF_NVFP4_M32_WMMA_ROUND: " << label
                    << " distribution="
                    << nvfp4_m1_scale_distribution_name(distribution)
                    << " round=" << round + 1
                    << " reference=" << reference_name
                    << " candidate=" << candidate_name
                    << " baseline_pass1_ms=" << baseline_first
                    << " candidate_pass1_ms=" << candidate_first
                    << " candidate_pass2_ms=" << candidate_second
                    << " baseline_pass2_ms=" << baseline_second << '\n';
        };
    for (int round = 0; round < kMeasurementRounds; ++round) {
      if ((round & 1) == 0) {
        measure_mirrored_pair(launch_baseline, launch_k64,
                              "two_public_m16", "k64_dual_a",
                              k64_baseline_total, k64_total,
                              k64_timings_finite, round);
        measure_mirrored_pair(launch_baseline, launch_k128,
                              "two_public_m16", "k128_single_a",
                              k128_baseline_total, k128_total,
                              k128_timings_finite, round);
        measure_mirrored_pair(
            launch_k64, launch_scale_window, "previous_production_k64_dual_a",
            "k64_scale_window", scale_window_reference_total,
            scale_window_total, scale_window_timings_finite, round);
        measure_mirrored_pair(
            launch_scale_window, launch_factorized,
            "previous_production_k64_scale_window",
            "production_k64_factorized_lookup",
            factorized_reference_total, factorized_total,
            factorized_timings_finite, round);
        measure_mirrored_pair(
            launch_factorized, launch_vector_store,
            "production_k64_factorized_lookup",
            "factorized_vector_store", vector_store_reference_total,
            vector_store_total, vector_store_timings_finite, round);
      } else {
        measure_mirrored_pair(
            launch_factorized, launch_vector_store,
            "production_k64_factorized_lookup",
            "factorized_vector_store", vector_store_reference_total,
            vector_store_total, vector_store_timings_finite, round);
        measure_mirrored_pair(
            launch_scale_window, launch_factorized,
            "previous_production_k64_scale_window",
            "production_k64_factorized_lookup",
            factorized_reference_total, factorized_total,
            factorized_timings_finite, round);
        measure_mirrored_pair(
            launch_k64, launch_scale_window, "previous_production_k64_dual_a",
            "k64_scale_window", scale_window_reference_total,
            scale_window_total, scale_window_timings_finite, round);
        measure_mirrored_pair(launch_baseline, launch_k128,
                              "two_public_m16", "k128_single_a",
                              k128_baseline_total, k128_total,
                              k128_timings_finite, round);
        measure_mirrored_pair(launch_baseline, launch_k64,
                              "two_public_m16", "k64_dual_a",
                              k64_baseline_total, k64_total,
                              k64_timings_finite, round);
      }
    }
    constexpr double kBaselineTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    constexpr double kCandidateTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    if (k64_timings_finite) {
      measurement.k64_baseline_milliseconds =
          k64_baseline_total / kBaselineTimedPasses;
      measurement.k64_dual_a_milliseconds =
          k64_total / kCandidateTimedPasses;
    }
    if (k128_timings_finite) {
      measurement.k128_baseline_milliseconds =
          k128_baseline_total / kBaselineTimedPasses;
      measurement.k128_single_a_milliseconds =
          k128_total / kCandidateTimedPasses;
    }
    if (scale_window_timings_finite) {
      measurement.scale_window_reference_milliseconds =
          scale_window_reference_total / kBaselineTimedPasses;
      measurement.scale_window_milliseconds =
          scale_window_total / kCandidateTimedPasses;
    }
    if (factorized_timings_finite) {
      measurement.factorized_reference_milliseconds =
          factorized_reference_total / kBaselineTimedPasses;
      measurement.factorized_milliseconds =
          factorized_total / kCandidateTimedPasses;
    }
    if (vector_store_timings_finite) {
      measurement.vector_store_reference_milliseconds =
          vector_store_reference_total / kBaselineTimedPasses;
      measurement.vector_store_milliseconds =
          vector_store_total / kCandidateTimedPasses;
    }
  }
  return shape_measurement;
}

void run_optional_nvfp4_m32_wmma_performance(TestContext& test,
                                               cudaStream_t stream) {
  if (!nvfp4_m32_wmma_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M32 WMMA multi-candidate performance segment; "
                 "set Q3X_RUN_SM87_NVFP4_M32_WMMA_PERF=1 to enable\n";
    return;
  }

  constexpr double kMinimumCellSpeedup = 1.05;
  constexpr double kMinimumWeightedSpeedup = 1.15;
  constexpr double kMinimumScaleWindowCellSpeedup = 1.02;
  constexpr double kMinimumScaleWindowWeightedSpeedup = 1.05;
  constexpr double kMinimumFactorizedCellSpeedup = 1.00;
  constexpr double kMinimumFactorizedWeightedSpeedup = 1.02;
  constexpr double kMinimumVectorStoreCellSpeedup = 1.00;
  constexpr double kMinimumVectorStoreWeightedSpeedup = 1.02;
  constexpr std::array<NvFp4M32WmmaShape, 2U> kShapes{{
      {17'408U, 5'120U, 128U, "NVFP4 M32 gate/up 17408x5120"},
      {5'120U, 17'408U, 64U, "NVFP4 M32 down 5120x17408"},
  }};

  std::array<NvFp4M32WmmaShapeMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] =
        benchmark_nvfp4_m32_wmma_shape(test, stream, kShapes[shape_index]);
  }

  double weighted_k64_baseline = 0.0;
  double weighted_k128_baseline = 0.0;
  double weighted_k64 = 0.0;
  double weighted_k128 = 0.0;
  double weighted_scale_window_reference = 0.0;
  double weighted_scale_window = 0.0;
  double weighted_factorized_reference = 0.0;
  double weighted_factorized = 0.0;
  double weighted_vector_store_reference = 0.0;
  double weighted_vector_store = 0.0;
  bool all_k64_cells_pass = true;
  bool all_k128_cells_pass = true;
  bool all_scale_window_cells_pass = true;
  bool all_factorized_cells_pass = true;
  bool all_vector_store_cells_pass = true;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    for (std::size_t distribution_index = 0U;
         distribution_index < kNvFp4M16K128ScaleDistributions.size();
         ++distribution_index) {
      const NvFp4M32WmmaCellMeasurement& cell =
          measurements[shape_index].distributions[distribution_index];
      const double k64_speedup =
          cell.k64_baseline_milliseconds / cell.k64_dual_a_milliseconds;
      const double k128_speedup =
          cell.k128_baseline_milliseconds /
          cell.k128_single_a_milliseconds;
      const double scale_window_speedup =
          cell.scale_window_reference_milliseconds /
          cell.scale_window_milliseconds;
      const double factorized_speedup =
          cell.factorized_reference_milliseconds /
          cell.factorized_milliseconds;
      const double vector_store_speedup =
          cell.vector_store_reference_milliseconds /
          cell.vector_store_milliseconds;
      const bool k64_finite =
          std::isfinite(cell.k64_baseline_milliseconds) &&
          std::isfinite(cell.k64_dual_a_milliseconds) &&
          std::isfinite(k64_speedup) &&
          cell.k64_baseline_milliseconds > 0.0 &&
          cell.k64_dual_a_milliseconds > 0.0;
      const bool k128_finite =
          std::isfinite(cell.k128_baseline_milliseconds) &&
          std::isfinite(cell.k128_single_a_milliseconds) &&
          std::isfinite(k128_speedup) &&
          cell.k128_baseline_milliseconds > 0.0 &&
          cell.k128_single_a_milliseconds > 0.0;
      const bool scale_window_finite =
          std::isfinite(cell.scale_window_reference_milliseconds) &&
          std::isfinite(cell.scale_window_milliseconds) &&
          std::isfinite(scale_window_speedup) &&
          cell.scale_window_reference_milliseconds > 0.0 &&
          cell.scale_window_milliseconds > 0.0;
      const bool factorized_finite =
          std::isfinite(cell.factorized_reference_milliseconds) &&
          std::isfinite(cell.factorized_milliseconds) &&
          std::isfinite(factorized_speedup) &&
          cell.factorized_reference_milliseconds > 0.0 &&
          cell.factorized_milliseconds > 0.0;
      const bool vector_store_finite =
          std::isfinite(cell.vector_store_reference_milliseconds) &&
          std::isfinite(cell.vector_store_milliseconds) &&
          std::isfinite(vector_store_speedup) &&
          cell.vector_store_reference_milliseconds > 0.0 &&
          cell.vector_store_milliseconds > 0.0;
      const bool k64_gate = cell.k64_bitwise_equal && cell.output_finite &&
                            k64_finite &&
                            k64_speedup >= kMinimumCellSpeedup;
      const bool k128_gate = cell.k128_bitwise_equal && cell.output_finite &&
                             k128_finite &&
                             k128_speedup >= kMinimumCellSpeedup;
      const bool scale_window_gate =
          cell.scale_window_bitwise_equal && cell.output_finite &&
          scale_window_finite &&
          scale_window_speedup >= kMinimumScaleWindowCellSpeedup;
      const bool factorized_gate =
          cell.factorized_bitwise_equal && cell.output_finite &&
          factorized_finite &&
          factorized_speedup >= kMinimumFactorizedCellSpeedup;
      const bool vector_store_gate =
          cell.vector_store_bitwise_equal && cell.output_finite &&
          vector_store_finite &&
          vector_store_speedup >= kMinimumVectorStoreCellSpeedup;
      all_k64_cells_pass = all_k64_cells_pass && k64_gate;
      all_k128_cells_pass = all_k128_cells_pass && k128_gate;
      all_scale_window_cells_pass =
          all_scale_window_cells_pass && scale_window_gate;
      all_factorized_cells_pass =
          all_factorized_cells_pass && factorized_gate;
      all_vector_store_cells_pass =
          all_vector_store_cells_pass && vector_store_gate;
      const double profile_calls =
          static_cast<double>(kShapes[shape_index].profile_calls);
      weighted_k64_baseline +=
          profile_calls * cell.k64_baseline_milliseconds;
      weighted_k128_baseline +=
          profile_calls * cell.k128_baseline_milliseconds;
      weighted_k64 += profile_calls * cell.k64_dual_a_milliseconds;
      weighted_k128 += profile_calls * cell.k128_single_a_milliseconds;
      weighted_scale_window_reference +=
          profile_calls * cell.scale_window_reference_milliseconds;
      weighted_scale_window +=
          profile_calls * cell.scale_window_milliseconds;
      weighted_factorized_reference +=
          profile_calls * cell.factorized_reference_milliseconds;
      weighted_factorized +=
          profile_calls * cell.factorized_milliseconds;
      weighted_vector_store_reference +=
          profile_calls * cell.vector_store_reference_milliseconds;
      weighted_vector_store +=
          profile_calls * cell.vector_store_milliseconds;
      std::cout << "PERF_NVFP4_M32_WMMA_CELL: "
                << kShapes[shape_index].label << " distribution="
                << nvfp4_m1_scale_distribution_name(
                       kNvFp4M16K128ScaleDistributions[distribution_index])
                << " k64_baseline_two_public_m16_ms="
                << cell.k64_baseline_milliseconds
                << " k64_dual_a_ms=" << cell.k64_dual_a_milliseconds
                << " k64_speedup=" << k64_speedup
                << " k64_gate=" << (k64_gate ? "PASS" : "FAIL")
                << " k128_baseline_two_public_m16_ms="
                << cell.k128_baseline_milliseconds
                << " k128_single_a_ms="
                << cell.k128_single_a_milliseconds
                << " k128_speedup=" << k128_speedup
                << " k128_gate=" << (k128_gate ? "PASS" : "FAIL")
                << " scale_window_reference_previous_production_k64_ms="
                << cell.scale_window_reference_milliseconds
                << " scale_window_ms=" << cell.scale_window_milliseconds
                << " scale_window_speedup=" << scale_window_speedup
                << " scale_window_gate="
                << (scale_window_gate ? "PASS" : "FAIL")
                << " minimum_speedup=" << kMinimumCellSpeedup
                << " scale_window_minimum_speedup="
                << kMinimumScaleWindowCellSpeedup
                << " factorized_reference_scale_window_ms="
                << cell.factorized_reference_milliseconds
                << " factorized_ms=" << cell.factorized_milliseconds
                << " factorized_speedup=" << factorized_speedup
                << " factorized_gate="
                << (factorized_gate ? "PASS" : "FAIL")
                << " factorized_minimum_speedup="
                << kMinimumFactorizedCellSpeedup
                << " vector_store_reference_factorized_ms="
                << cell.vector_store_reference_milliseconds
                << " vector_store_ms=" << cell.vector_store_milliseconds
                << " vector_store_speedup=" << vector_store_speedup
                << " vector_store_gate="
                << (vector_store_gate ? "PASS" : "FAIL")
                << " vector_store_minimum_speedup="
                << kMinimumVectorStoreCellSpeedup << '\n';
    }
  }

  const double weighted_k64_speedup =
      weighted_k64_baseline / weighted_k64;
  const double weighted_k128_speedup =
      weighted_k128_baseline / weighted_k128;
  const double weighted_scale_window_speedup =
      weighted_scale_window_reference / weighted_scale_window;
  const double weighted_factorized_speedup =
      weighted_factorized_reference / weighted_factorized;
  const double weighted_vector_store_speedup =
      weighted_vector_store_reference / weighted_vector_store;
  const bool k64_aggregate_gate =
      all_k64_cells_pass && std::isfinite(weighted_k64_speedup) &&
      weighted_k64_speedup >= kMinimumWeightedSpeedup;
  const bool k128_aggregate_gate =
      all_k128_cells_pass && std::isfinite(weighted_k128_speedup) &&
      weighted_k128_speedup >= kMinimumWeightedSpeedup;
  const bool scale_window_aggregate_gate =
      all_scale_window_cells_pass &&
      std::isfinite(weighted_scale_window_speedup) &&
      weighted_scale_window_speedup >= kMinimumScaleWindowWeightedSpeedup;
  const bool factorized_aggregate_gate =
      all_factorized_cells_pass &&
      std::isfinite(weighted_factorized_speedup) &&
      weighted_factorized_speedup >= kMinimumFactorizedWeightedSpeedup;
  const bool vector_store_aggregate_gate =
      all_vector_store_cells_pass &&
      std::isfinite(weighted_vector_store_speedup) &&
      weighted_vector_store_speedup >= kMinimumVectorStoreWeightedSpeedup;
  const bool any_candidate_eligible =
      k64_aggregate_gate || k128_aggregate_gate ||
      scale_window_aggregate_gate || factorized_aggregate_gate ||
      vector_store_aggregate_gate;
  const bool select_k64 =
      k64_aggregate_gate &&
      (!k128_aggregate_gate || weighted_k64_speedup >= weighted_k128_speedup);
  const char* selected_candidate = "none";
  if (vector_store_aggregate_gate) {
    selected_candidate = "k64_factorized_vector_store";
  } else if (factorized_aggregate_gate) {
    selected_candidate = "k64_factorized_lookup";
  } else if (scale_window_aggregate_gate) {
    selected_candidate = "k64_scale_window";
  } else if (any_candidate_eligible) {
    selected_candidate = select_k64 ? "k64_dual_a" : "k128_single_a";
  }
  std::cout << "PERF_NVFP4_M32_WMMA_AGGREGATE: "
            << "weighted_k64_baseline_two_public_m16_ms="
            << weighted_k64_baseline
            << " weighted_k64_dual_a_ms=" << weighted_k64
            << " k64_speedup=" << weighted_k64_speedup
            << " k64_required_speedup=" << kMinimumWeightedSpeedup
            << " k64_gate=" << (k64_aggregate_gate ? "PASS" : "FAIL")
            << " weighted_k128_baseline_two_public_m16_ms="
            << weighted_k128_baseline
            << " weighted_k128_single_a_ms=" << weighted_k128
            << " k128_speedup=" << weighted_k128_speedup
            << " k128_required_speedup=" << kMinimumWeightedSpeedup
            << " k128_gate=" << (k128_aggregate_gate ? "PASS" : "FAIL")
            << " weighted_scale_window_reference_previous_production_k64_ms="
            << weighted_scale_window_reference
            << " weighted_scale_window_ms=" << weighted_scale_window
            << " scale_window_speedup=" << weighted_scale_window_speedup
            << " scale_window_required_speedup="
            << kMinimumScaleWindowWeightedSpeedup
            << " scale_window_gate="
            << (scale_window_aggregate_gate ? "PASS" : "FAIL")
            << " weighted_factorized_reference_scale_window_ms="
            << weighted_factorized_reference
            << " weighted_factorized_ms=" << weighted_factorized
            << " factorized_speedup=" << weighted_factorized_speedup
            << " factorized_required_speedup="
            << kMinimumFactorizedWeightedSpeedup
            << " factorized_gate="
            << (factorized_aggregate_gate ? "PASS" : "FAIL")
            << " weighted_vector_store_reference_factorized_ms="
            << weighted_vector_store_reference
            << " weighted_vector_store_ms=" << weighted_vector_store
            << " vector_store_speedup=" << weighted_vector_store_speedup
            << " vector_store_required_speedup="
            << kMinimumVectorStoreWeightedSpeedup
            << " vector_store_gate="
            << (vector_store_aggregate_gate ? "PASS" : "FAIL")
            << " selected=" << selected_candidate
            << " profile_calls=128:64"
            << " distributions=checkpoint_like:same_bank_stress\n";
  test.expect(any_candidate_eligible,
              "at least one NVFP4 M32 candidate clears every cell and the "
              "weighted prototype gate");
  test.expect(scale_window_aggregate_gate,
              "NVFP4 M32 K64 scale-window clears every cell and the "
              "weighted production-relative gate");
  test.expect(factorized_aggregate_gate,
              "NVFP4 M32 K64 factorized lookup clears every cell and the "
              "weighted scale-window-relative gate");
  test.expect(vector_store_aggregate_gate,
              "NVFP4 M32 K64 factorized vector store clears every cell and "
              "the weighted factorized-relative gate");
}

struct NvFp4M32TableFreeCellMeasurement {
  double production_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double minimum_round_speedup =
      std::numeric_limits<double>::quiet_NaN();
  bool bitwise_equal = false;
  bool output_finite = false;
};

struct NvFp4M32TableFreeShapeMeasurement {
  std::array<NvFp4M32TableFreeCellMeasurement,
             kNvFp4M16K128ScaleDistributions.size()>
      distributions{};
};

[[nodiscard]] NvFp4M32TableFreeShapeMeasurement
benchmark_nvfp4_m32_table_free_shape(
    TestContext& test, cudaStream_t stream,
    const NvFp4M32WmmaShape& shape,
    const bool raw_weight_cp_async_probe = false) {
  constexpr std::size_t kTokens = 32U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 4;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  const std::size_t packed_columns = shape.columns / 2U;
  const std::size_t scale_columns = shape.columns / 16U;
  const std::size_t output_elements = kTokens * shape.rows;
  const std::string label = shape.label;

  std::vector<std::uint8_t> host_packed(shape.rows * packed_columns);
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t row = 0U; row < shape.rows; ++row) {
    for (std::size_t packed_column = 0U; packed_column < packed_columns;
         ++packed_column) {
      const std::uint8_t low = static_cast<std::uint8_t>(
          (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
      const std::uint8_t high = static_cast<std::uint8_t>(
          (packed_column * 5U + row * 7U +
           (packed_column >> 3U) * 3U + 1U) &
          0x0fU);
      host_packed[row * packed_columns + packed_column] =
          static_cast<std::uint8_t>(low | (high << 4U));
      low_nibble_covered[low] = true;
      high_nibble_covered[high] = true;
    }
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " table-free covers every low-nibble code");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " table-free covers every high-nibble code");

  std::vector<std::uint8_t> host_scales(shape.rows * scale_columns);
  std::vector<std::uint16_t> host_activations(kTokens * shape.columns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < shape.columns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * shape.columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> production_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                            label + " allocate table-free packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate table-free scales");
  ready = ready && test.cuda_ok(
                       activations.allocate(host_activations.size()),
                       label + " allocate table-free activations");
  ready = ready && test.cuda_ok(
                       production_output.allocate(output_elements),
                       label + " allocate table-free production output");
  ready = ready && test.cuda_ok(
                       candidate_output.allocate(output_elements),
                       label + " allocate table-free candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), host_packed.data(),
                                       host_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize table-free packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize table-free activations");
  if (!ready) {
    return {};
  }

  const auto launch_production = [&]() noexcept -> int {
    if (raw_weight_cp_async_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activations.get(),
              shape.rows, shape.columns, production_output.get(),
              static_cast<void*>(stream));
    }
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_vector_store_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, production_output.get(),
            static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    if (raw_weight_cp_async_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activations.get(),
              shape.rows, shape.columns, candidate_output.get(),
              static_cast<void*>(stream));
    }
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, candidate_output.get(),
            static_cast<void*>(stream));
  };

  std::vector<std::uint16_t> production(output_elements);
  std::vector<std::uint16_t> candidate(output_elements);
  NvFp4M32TableFreeShapeMeasurement shape_measurement{};
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M16K128ScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                     distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize table-free scales");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_production()),
                         distribution_label + " correctness production");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         distribution_label + " correctness candidate");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             production.data(), production_output.get(),
                             production.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy production");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy candidate");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label +
                                      " correctness synchronize");
    if (!ready) {
      return shape_measurement;
    }

    std::size_t mismatches = 0U;
    bool output_finite = true;
    for (std::size_t index = 0U; index < output_elements; ++index) {
      mismatches += production[index] != candidate[index] ? 1U : 0U;
      output_finite = output_finite &&
                      std::isfinite(decode_bf16(production[index])) &&
                      std::isfinite(decode_bf16(candidate[index]));
    }
    NvFp4M32TableFreeCellMeasurement& measurement =
        shape_measurement.distributions[distribution_index];
    measurement.bitwise_equal = mismatches == 0U;
    measurement.output_finite = output_finite;
    std::cout << "NVFP4_M32_TABLE_FREE_DIFF: " << label
              << " distribution="
              << nvfp4_m1_scale_distribution_name(distribution)
              << " mismatches=" << mismatches << '/' << output_elements
              << " output_finite=" << (output_finite ? "true" : "false")
              << '\n';
    test.expect(measurement.bitwise_equal,
                distribution_label + " table-free output is bit-exact");
    test.expect(output_finite,
                distribution_label + " table-free output remains finite");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_production()),
                           distribution_label + " production warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           distribution_label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " warmup synchronize");
    if (!ready) {
      return shape_measurement;
    }

    double production_total = 0.0;
    double candidate_total = 0.0;
    double minimum_round_speedup =
        std::numeric_limits<double>::infinity();
    bool finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string suffix =
          distribution_label + " round=" + std::to_string(round + 1);
      const float production_first = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          suffix + " production pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          suffix + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          suffix + " candidate pass 2");
      const float production_second = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          suffix + " production pass 2");
      const bool round_finite =
          std::isfinite(production_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(production_second) && production_first > 0.0F &&
          candidate_first > 0.0F && candidate_second > 0.0F &&
          production_second > 0.0F;
      finite = finite && round_finite;
      double round_speedup = std::numeric_limits<double>::quiet_NaN();
      if (round_finite) {
        const double production_round =
            static_cast<double>(production_first) + production_second;
        const double candidate_round =
            static_cast<double>(candidate_first) + candidate_second;
        round_speedup = production_round / candidate_round;
        production_total += production_round;
        candidate_total += candidate_round;
        minimum_round_speedup =
            std::min(minimum_round_speedup, round_speedup);
      }
      std::cout
          << (raw_weight_cp_async_probe
                  ? "PERF_NVFP4_M32_RAW_WEIGHT_CP_ASYNC_ROUND: "
                  : "PERF_NVFP4_M32_TABLE_FREE_ROUND: ")
          << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " round=" << round + 1
                << " production_pass1_ms=" << production_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " production_pass2_ms=" << production_second
                << " round_speedup=" << round_speedup << '\n';
    }
    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    if (finite) {
      measurement.production_milliseconds = production_total / kTimedPasses;
      measurement.candidate_milliseconds = candidate_total / kTimedPasses;
      measurement.minimum_round_speedup = minimum_round_speedup;
    }
  }
  return shape_measurement;
}

struct NvFp4M32TableFreePairMeasurement {
  double production_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double minimum_round_speedup =
      std::numeric_limits<double>::quiet_NaN();
  bool bitwise_equal = false;
  bool output_finite = false;
};

void run_nvfp4_m32_table_free_pair_performance(TestContext& test,
                                                cudaStream_t stream,
                                                const bool raw_weight_probe =
                                                    false) {
  constexpr std::size_t kRows = 17'408U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kTokens = 32U;
  constexpr std::size_t kPackedColumns = kColumns / 2U;
  constexpr std::size_t kScaleColumns = kColumns / 16U;
  constexpr std::size_t kOutputElements = kTokens * kRows;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 4;
  const double kMinimumCellSpeedup = raw_weight_probe ? 1.02 : 1.0;
  constexpr double kMinimumRoundSpeedup = 1.0;
  constexpr double kMinimumAggregateSpeedup = 1.02;

  std::vector<std::uint8_t> host_gate_packed(kRows * kPackedColumns);
  std::vector<std::uint8_t> host_up_packed(host_gate_packed.size());
  for (std::size_t index = 0U; index < host_gate_packed.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 3U + (index >> 5U) + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 5U + (index >> 7U) * 3U + 7U) & 0x0fU);
    host_gate_packed[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
    host_up_packed[index] = static_cast<std::uint8_t>(
        (low ^ 0x09U) | ((high ^ 0x05U) << 4U));
  }
  std::vector<std::uint8_t> host_gate_scales(kRows * kScaleColumns);
  std::vector<std::uint8_t> host_up_scales(host_gate_scales.size());
  std::vector<std::uint16_t> host_activations(kTokens * kColumns);
  for (std::size_t token = 0U; token < kTokens; ++token) {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * kColumns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> gate_packed;
  DeviceBuffer<std::uint8_t> up_packed;
  DeviceBuffer<std::uint8_t> gate_scales;
  DeviceBuffer<std::uint8_t> up_scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> production_gate_output;
  DeviceBuffer<std::uint16_t> production_up_output;
  DeviceBuffer<std::uint16_t> candidate_gate_output;
  DeviceBuffer<std::uint16_t> candidate_up_output;
  bool ready = test.cuda_ok(
      gate_packed.allocate(host_gate_packed.size()),
      "table-free pair allocate gate packed weights");
  ready = ready && test.cuda_ok(
                       up_packed.allocate(host_up_packed.size()),
                       "table-free pair allocate up packed weights");
  ready = ready && test.cuda_ok(
                       gate_scales.allocate(host_gate_scales.size()),
                       "table-free pair allocate gate block scales");
  ready = ready && test.cuda_ok(
                       up_scales.allocate(host_up_scales.size()),
                       "table-free pair allocate up block scales");
  ready = ready && test.cuda_ok(
                       activations.allocate(host_activations.size()),
                       "table-free pair allocate activations");
  ready = ready && test.cuda_ok(
                       production_gate_output.allocate(kOutputElements),
                       "table-free pair allocate production gate output");
  ready = ready && test.cuda_ok(
                       production_up_output.allocate(kOutputElements),
                       "table-free pair allocate production up output");
  ready = ready && test.cuda_ok(
                       candidate_gate_output.allocate(kOutputElements),
                       "table-free pair allocate candidate gate output");
  ready = ready && test.cuda_ok(
                       candidate_up_output.allocate(kOutputElements),
                       "table-free pair allocate candidate up output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(gate_packed.get(),
                                       host_gate_packed.data(),
                                       host_gate_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       "table-free pair initialize gate packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(up_packed.get(), host_up_packed.data(),
                                       host_up_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       "table-free pair initialize up packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       "table-free pair initialize activations");
  if (!ready) {
    return;
  }

  cudaStream_t auxiliary_stream = nullptr;
  cudaEvent_t inputs_ready = nullptr;
  cudaEvent_t auxiliary_done = nullptr;
  ready = test.cuda_ok(
      cudaStreamCreateWithFlags(&auxiliary_stream, cudaStreamNonBlocking),
      "table-free pair create auxiliary stream");
  ready = ready && test.cuda_ok(
                       cudaEventCreateWithFlags(&inputs_ready,
                                                cudaEventDisableTiming),
                       "table-free pair create input-ready event");
  ready = ready && test.cuda_ok(
                       cudaEventCreateWithFlags(&auxiliary_done,
                                                cudaEventDisableTiming),
                       "table-free pair create auxiliary-done event");
  const auto cleanup = [&]() {
    if (stream != nullptr) {
      (void)test.cuda_ok(cudaStreamSynchronize(stream),
                         "table-free pair final primary synchronize");
    }
    if (auxiliary_stream != nullptr) {
      (void)test.cuda_ok(
          cudaStreamSynchronize(auxiliary_stream),
          "table-free pair final auxiliary synchronize");
    }
    if (inputs_ready != nullptr) {
      (void)test.cuda_ok(cudaEventDestroy(inputs_ready),
                         "table-free pair destroy input-ready event");
    }
    if (auxiliary_done != nullptr) {
      (void)test.cuda_ok(cudaEventDestroy(auxiliary_done),
                         "table-free pair destroy auxiliary-done event");
    }
    if (auxiliary_stream != nullptr) {
      (void)test.cuda_ok(cudaStreamDestroy(auxiliary_stream),
                         "table-free pair destroy auxiliary stream");
    }
  };
  if (!ready) {
    cleanup();
    return;
  }

  const auto launch_one = [&](const bool candidate_path,
                              const std::uint8_t* const packed,
                              const std::uint8_t* const scales,
                              std::uint16_t* const output,
                              cudaStream_t const launch_stream) noexcept {
    if (raw_weight_probe && candidate_path) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_test_cuda(
              packed, scales, kWeightScale2, activations.get(), kRows,
              kColumns, output, static_cast<void*>(launch_stream));
    }
    if (raw_weight_probe || candidate_path) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_test_cuda(
              packed, scales, kWeightScale2, activations.get(), kRows,
              kColumns, output, static_cast<void*>(launch_stream));
    }
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_vector_store_test_cuda(
            packed, scales, kWeightScale2, activations.get(), kRows,
            kColumns, output, static_cast<void*>(launch_stream));
  };
  const auto launch_pair = [&](const bool candidate_path) noexcept -> int {
    std::uint16_t* const gate_output =
        candidate_path ? candidate_gate_output.get()
                       : production_gate_output.get();
    std::uint16_t* const up_output =
        candidate_path ? candidate_up_output.get()
                       : production_up_output.get();
    cudaError_t status = cudaEventRecord(inputs_ready, stream);
    if (status != cudaSuccess) {
      return static_cast<int>(status);
    }
    status = cudaStreamWaitEvent(auxiliary_stream, inputs_ready, 0U);
    if (status != cudaSuccess) {
      return static_cast<int>(status);
    }
    int launch_status = launch_one(candidate_path, gate_packed.get(),
                                   gate_scales.get(), gate_output, stream);
    if (launch_status != static_cast<int>(cudaSuccess)) {
      return launch_status;
    }
    launch_status = launch_one(candidate_path, up_packed.get(),
                               up_scales.get(), up_output, auxiliary_stream);
    if (launch_status != static_cast<int>(cudaSuccess)) {
      return launch_status;
    }
    status = cudaEventRecord(auxiliary_done, auxiliary_stream);
    if (status != cudaSuccess) {
      return static_cast<int>(status);
    }
    return static_cast<int>(
        cudaStreamWaitEvent(stream, auxiliary_done, 0U));
  };
  const auto launch_production_pair = [&]() noexcept -> int {
    return launch_pair(false);
  };
  const auto launch_candidate_pair = [&]() noexcept -> int {
    return launch_pair(true);
  };

  std::vector<std::uint16_t> production_gate(kOutputElements);
  std::vector<std::uint16_t> production_up(kOutputElements);
  std::vector<std::uint16_t> candidate_gate(kOutputElements);
  std::vector<std::uint16_t> candidate_up(kOutputElements);
  std::array<NvFp4M32TableFreePairMeasurement,
             kNvFp4M16K128ScaleDistributions.size()>
      measurements{};
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M16K128ScaleDistributions[distribution_index];
    const std::string distribution_name =
        nvfp4_m1_scale_distribution_name(distribution);
    const std::string cell_label =
        std::string(raw_weight_probe
                        ? "NVFP4 M32 raw-weight cp.async gate/up pair "
                        : "NVFP4 M32 table-free gate/up pair ") +
        distribution_name;
    fill_nvfp4_m1_scale_distribution(host_gate_scales, kScaleColumns,
                                     distribution);
    host_up_scales = host_gate_scales;
    ready = test.cuda_ok(
        cudaMemcpyAsync(gate_scales.get(), host_gate_scales.data(),
                        host_gate_scales.size(), cudaMemcpyHostToDevice,
                        stream),
        cell_label + " initialize gate scales");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             up_scales.get(), host_up_scales.data(),
                             host_up_scales.size(), cudaMemcpyHostToDevice,
                             stream),
                         cell_label + " initialize up scales");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_production_pair()),
                         cell_label + " correctness production pair");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate_pair()),
                         cell_label + " correctness candidate pair");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             production_gate.data(),
                             production_gate_output.get(),
                             production_gate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         cell_label + " copy production gate");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             production_up.data(), production_up_output.get(),
                             production_up.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         cell_label + " copy production up");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_gate.data(),
                             candidate_gate_output.get(),
                             candidate_gate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         cell_label + " copy candidate gate");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate_up.data(), candidate_up_output.get(),
                             candidate_up.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         cell_label + " copy candidate up");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         cell_label + " correctness synchronize");
    if (!ready) {
      cleanup();
      return;
    }

    NvFp4M32TableFreePairMeasurement& measurement =
        measurements[distribution_index];
    std::size_t gate_mismatches = 0U;
    std::size_t up_mismatches = 0U;
    bool output_finite = true;
    for (std::size_t index = 0U; index < kOutputElements; ++index) {
      gate_mismatches +=
          production_gate[index] != candidate_gate[index] ? 1U : 0U;
      up_mismatches +=
          production_up[index] != candidate_up[index] ? 1U : 0U;
      output_finite =
          output_finite &&
          std::isfinite(decode_bf16(production_gate[index])) &&
          std::isfinite(decode_bf16(production_up[index])) &&
          std::isfinite(decode_bf16(candidate_gate[index])) &&
          std::isfinite(decode_bf16(candidate_up[index]));
    }
    measurement.bitwise_equal =
        gate_mismatches == 0U && up_mismatches == 0U;
    measurement.output_finite = output_finite;
    std::cout
        << (raw_weight_probe
                ? "NVFP4_M32_RAW_WEIGHT_CP_ASYNC_PAIR_DIFF: distribution="
                : "NVFP4_M32_TABLE_FREE_PAIR_DIFF: distribution=")
              << distribution_name << " gate_mismatches=" << gate_mismatches
              << '/' << kOutputElements
              << " up_mismatches=" << up_mismatches << '/'
              << kOutputElements
              << " output_finite=" << (output_finite ? "true" : "false")
              << '\n';
    test.expect(measurement.bitwise_equal,
                cell_label + " is bit-exact for both projections");
    test.expect(output_finite,
                cell_label + " keeps both projection outputs finite");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_production_pair()),
          cell_label + " production pair warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate_pair()),
                           cell_label + " candidate pair warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  cell_label + " warmup synchronize");
    if (!ready) {
      cleanup();
      return;
    }

    double production_total = 0.0;
    double candidate_total = 0.0;
    double minimum_round_speedup =
        std::numeric_limits<double>::infinity();
    bool timings_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          cell_label + " round=" + std::to_string(round + 1);
      const float production_first = measure_small_m_tile(
          test, stream, launch_production_pair, kMeasuredIterations,
          round_label + " production pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate_pair, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate_pair, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float production_second = measure_small_m_tile(
          test, stream, launch_production_pair, kMeasuredIterations,
          round_label + " production pass 2");
      const bool round_finite =
          std::isfinite(production_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(production_second) && production_first > 0.0F &&
          candidate_first > 0.0F && candidate_second > 0.0F &&
          production_second > 0.0F;
      double round_speedup = std::numeric_limits<double>::quiet_NaN();
      timings_finite = timings_finite && round_finite;
      if (round_finite) {
        const double production_round =
            static_cast<double>(production_first) + production_second;
        const double candidate_round =
            static_cast<double>(candidate_first) + candidate_second;
        round_speedup = production_round / candidate_round;
        production_total += production_round;
        candidate_total += candidate_round;
        minimum_round_speedup =
            std::min(minimum_round_speedup, round_speedup);
      }
      std::cout
          << (raw_weight_probe
                  ? "PERF_NVFP4_M32_RAW_WEIGHT_CP_ASYNC_PAIR_ROUND: distribution="
                  : "PERF_NVFP4_M32_TABLE_FREE_PAIR_ROUND: distribution=")
                << distribution_name << " round=" << round + 1
                << " order=B-C-C-B"
                << " production_pass1_ms=" << production_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " production_pass2_ms=" << production_second
                << " round_speedup=" << round_speedup << '\n';
    }
    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    if (timings_finite) {
      measurement.production_milliseconds =
          production_total / kTimedPasses;
      measurement.candidate_milliseconds = candidate_total / kTimedPasses;
      measurement.minimum_round_speedup = minimum_round_speedup;
    }
  }

  bool all_cells_pass = ready;
  double aggregate_production = 0.0;
  double aggregate_candidate = 0.0;
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M32TableFreePairMeasurement& measurement =
        measurements[distribution_index];
    const double speedup = measurement.production_milliseconds /
                           measurement.candidate_milliseconds;
    const bool finite =
        std::isfinite(measurement.production_milliseconds) &&
        std::isfinite(measurement.candidate_milliseconds) &&
        std::isfinite(measurement.minimum_round_speedup) &&
        std::isfinite(speedup) && measurement.production_milliseconds > 0.0 &&
        measurement.candidate_milliseconds > 0.0;
    const bool cell_gate = measurement.bitwise_equal &&
                           measurement.output_finite && finite &&
                           speedup >= kMinimumCellSpeedup &&
                           measurement.minimum_round_speedup >=
                               kMinimumRoundSpeedup;
    all_cells_pass = all_cells_pass && cell_gate;
    aggregate_production += measurement.production_milliseconds;
    aggregate_candidate += measurement.candidate_milliseconds;
    std::cout
        << (raw_weight_probe
                ? "PERF_NVFP4_M32_RAW_WEIGHT_CP_ASYNC_PAIR_CELL: distribution="
                : "PERF_NVFP4_M32_TABLE_FREE_PAIR_CELL: distribution=")
              << nvfp4_m1_scale_distribution_name(
                     kNvFp4M16K128ScaleDistributions[distribution_index])
              << " production_pair_ms="
              << measurement.production_milliseconds
              << " candidate_pair_ms="
              << measurement.candidate_milliseconds
              << " speedup=" << speedup
              << " minimum_round_speedup="
              << measurement.minimum_round_speedup
              << " required_minimum_round_speedup="
              << kMinimumRoundSpeedup
              << " required_speedup=" << kMinimumCellSpeedup
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
    test.expect(cell_gate,
                std::string(raw_weight_probe
                                ? "NVFP4 M32 raw-weight cp.async gate/up pair "
                                : "NVFP4 M32 table-free gate/up pair ") +
                               std::string(nvfp4_m1_scale_distribution_name(
                                   kNvFp4M16K128ScaleDistributions[
                                       distribution_index])) +
                               " clears its absolute-envelope gate");
  }

  const double aggregate_speedup =
      aggregate_production / aggregate_candidate;
  const bool promotion_gate =
      all_cells_pass && std::isfinite(aggregate_speedup) &&
      aggregate_production > 0.0 && aggregate_candidate > 0.0 &&
      aggregate_speedup >= kMinimumAggregateSpeedup;
  std::cout
      << (raw_weight_probe
              ? "PERF_NVFP4_M32_RAW_WEIGHT_CP_ASYNC_PAIR_AGGREGATE: "
              : "PERF_NVFP4_M32_TABLE_FREE_PAIR_AGGREGATE: ")
            << "production_pair_ms=" << aggregate_production
            << " candidate_pair_ms=" << aggregate_candidate
            << " speedup=" << aggregate_speedup
            << " required_speedup=" << kMinimumAggregateSpeedup
            << " all_cells=" << (all_cells_pass ? "PASS" : "FAIL")
            << " distributions=checkpoint_like:same_bank_stress"
            << " promotion_gate="
            << (promotion_gate ? "PASS" : "FAIL") << '\n';
  test.expect(
      promotion_gate,
      std::string(raw_weight_probe
                      ? "NVFP4 M32 raw-weight cp.async gate/up pair"
                      : "NVFP4 M32 table-free gate/up pair") +
          " clears the same-binary absolute-envelope promotion gate");
  cleanup();
}

void run_optional_nvfp4_m32_table_free_performance(TestContext& test,
                                                     cudaStream_t stream) {
  if (!nvfp4_m32_table_free_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M32 table-free E2M1 performance segment; set "
                 "Q3X_RUN_SM87_NVFP4_M32_TABLE_FREE_PERF=1 to enable\n";
    return;
  }

  constexpr double kMinimumCellSpeedup = 1.0;
  constexpr double kMinimumScreenWeightedSpeedup = 1.005;
  constexpr double kPromotionWeightedSpeedup = 1.02;
  constexpr std::size_t kExpectedProductionSharedBytes = 24'576U;
  constexpr std::size_t kExpectedCandidateSharedBytes = 23'552U;
  constexpr std::array<NvFp4M32WmmaShape, 2U> kShapes{{
      {17'408U, 5'120U, 128U,
       "NVFP4 M32 table-free gate/up 17408x5120"},
      {5'120U, 17'408U, 64U,
       "NVFP4 M32 table-free down 5120x17408"},
  }};

  bool resource_gate = true;
  for (const NvFp4M32WmmaShape& shape : kShapes) {
    int production_registers = -1;
    std::size_t production_shared = std::numeric_limits<std::size_t>::max();
    std::size_t production_local = std::numeric_limits<std::size_t>::max();
    int production_maximum_threads = -1;
    int production_active_blocks = -1;
    int candidate_registers = -1;
    std::size_t candidate_shared = std::numeric_limits<std::size_t>::max();
    std::size_t candidate_local = std::numeric_limits<std::size_t>::max();
    int candidate_maximum_threads = -1;
    int candidate_active_blocks = -1;
    const cudaError_t production_status = static_cast<cudaError_t>(
        q3x::kernels::
            query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_factorized_vector_store_resources_test_cuda(
                shape.rows, shape.columns, &production_registers,
                &production_shared, &production_local,
                &production_maximum_threads, &production_active_blocks));
    const cudaError_t candidate_status = static_cast<cudaError_t>(
        q3x::kernels::
            query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_resources_test_cuda(
                shape.rows, shape.columns, &candidate_registers,
                &candidate_shared, &candidate_local,
                &candidate_maximum_threads, &candidate_active_blocks));
    const bool shape_gate =
        production_status == cudaSuccess && candidate_status == cudaSuccess &&
        production_registers <= 51 &&
        production_shared == kExpectedProductionSharedBytes &&
        production_local == 0U && production_maximum_threads == 256 &&
        production_active_blocks >= 5 && candidate_registers <= 51 &&
        candidate_shared == kExpectedCandidateSharedBytes &&
        candidate_local == 0U && candidate_maximum_threads == 256 &&
        candidate_active_blocks >= 5;
    resource_gate = resource_gate && shape_gate;
    std::cout << "NVFP4_M32_TABLE_FREE_RESOURCES: shape=" << shape.rows
              << 'x' << shape.columns
              << " production_status=" << static_cast<int>(production_status)
              << " production_registers=" << production_registers
              << " production_shared=" << production_shared
              << " production_local=" << production_local
              << " production_maximum_threads="
              << production_maximum_threads
              << " production_active_blocks=" << production_active_blocks
              << " candidate_status=" << static_cast<int>(candidate_status)
              << " candidate_registers=" << candidate_registers
              << " candidate_shared=" << candidate_shared
              << " candidate_local=" << candidate_local
              << " candidate_maximum_threads=" << candidate_maximum_threads
              << " candidate_active_blocks=" << candidate_active_blocks
              << " gate=" << (shape_gate ? "PASS" : "FAIL") << '\n';
    test.expect(shape_gate, std::string(shape.label) +
                                " clears table-free resource gate");
  }

  std::array<NvFp4M32TableFreeShapeMeasurement, kShapes.size()>
      measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_nvfp4_m32_table_free_shape(
        test, stream, kShapes[shape_index]);
  }

  double weighted_production = 0.0;
  double weighted_candidate = 0.0;
  bool all_cells_pass = resource_gate;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    for (std::size_t distribution_index = 0U;
         distribution_index < kNvFp4M16K128ScaleDistributions.size();
         ++distribution_index) {
      const NvFp4M32TableFreeCellMeasurement& cell =
          measurements[shape_index].distributions[distribution_index];
      const double speedup =
          cell.production_milliseconds / cell.candidate_milliseconds;
      const bool finite =
          std::isfinite(cell.production_milliseconds) &&
          std::isfinite(cell.candidate_milliseconds) &&
          std::isfinite(speedup) && cell.production_milliseconds > 0.0 &&
          cell.candidate_milliseconds > 0.0;
      const bool cell_gate = cell.bitwise_equal && cell.output_finite &&
                             finite && speedup >= kMinimumCellSpeedup;
      all_cells_pass = all_cells_pass && cell_gate;
      const double profile_calls =
          static_cast<double>(kShapes[shape_index].profile_calls);
      weighted_production +=
          profile_calls * cell.production_milliseconds;
      weighted_candidate += profile_calls * cell.candidate_milliseconds;
      std::cout << "PERF_NVFP4_M32_TABLE_FREE_CELL: "
                << kShapes[shape_index].label << " distribution="
                << nvfp4_m1_scale_distribution_name(
                       kNvFp4M16K128ScaleDistributions[distribution_index])
                << " production_ms=" << cell.production_milliseconds
                << " candidate_ms=" << cell.candidate_milliseconds
                << " speedup=" << speedup
                << " bitwise=" << (cell.bitwise_equal ? "true" : "false")
                << " output_finite="
                << (cell.output_finite ? "true" : "false")
                << " required_speedup=" << kMinimumCellSpeedup
                << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
    }
  }

  const double weighted_speedup = weighted_production / weighted_candidate;
  const bool screen_gate =
      all_cells_pass && std::isfinite(weighted_speedup) &&
      weighted_production > 0.0 && weighted_candidate > 0.0 &&
      weighted_speedup >= kMinimumScreenWeightedSpeedup;
  const bool promotion_ready =
      screen_gate && weighted_speedup >= kPromotionWeightedSpeedup;
  std::cout << "PERF_NVFP4_M32_TABLE_FREE_AGGREGATE: "
            << "weighted_production_ms=" << weighted_production
            << " weighted_candidate_ms=" << weighted_candidate
            << " speedup=" << weighted_speedup
            << " screen_required_speedup=" << kMinimumScreenWeightedSpeedup
            << " promotion_required_speedup=" << kPromotionWeightedSpeedup
            << " all_cells=" << (all_cells_pass ? "PASS" : "FAIL")
            << " promotion_ready="
            << (promotion_ready ? "true" : "false")
            << " profile_calls=128:64"
            << " distributions=checkpoint_like:same_bank_stress"
            << " gate=" << (screen_gate ? "PASS" : "FAIL") << '\n';
  test.expect(promotion_ready,
              "NVFP4 M32 table-free E2M1 clears the 1.02x weighted "
              "production promotion gate");
  run_nvfp4_m32_table_free_pair_performance(test, stream);
}

void run_optional_nvfp4_m32_raw_weight_cp_async_performance(
    TestContext& test, cudaStream_t stream) {
  if (!nvfp4_m32_raw_weight_cp_async_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 exact-M32 raw-weight cp.async performance segment; "
           "set Q3X_RUN_SM87_NVFP4_M32_RAW_WEIGHT_CP_ASYNC_PERF=1 to "
           "enable\n";
    return;
  }

  constexpr double kMinimumCellSpeedup = 1.03;
  constexpr double kMinimumRoundSpeedup = 1.0;
  constexpr double kMinimumAggregateSpeedup = 1.03;
  constexpr NvFp4M32WmmaShape kShape{
      17'408U, 5'120U, 1U,
      "NVFP4 exact-M32 gate/up raw-weight cp.async 17408x5120"};

  int production_registers = -1;
  std::size_t production_shared = std::numeric_limits<std::size_t>::max();
  std::size_t production_local = std::numeric_limits<std::size_t>::max();
  int production_maximum_threads = -1;
  int production_active_blocks = -1;
  int candidate_registers = -1;
  std::size_t candidate_shared = std::numeric_limits<std::size_t>::max();
  std::size_t candidate_local = std::numeric_limits<std::size_t>::max();
  int candidate_maximum_threads = -1;
  int candidate_active_blocks = -1;
  const cudaError_t production_status = static_cast<cudaError_t>(
      q3x::kernels::
          query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_e2m1_resources_test_cuda(
              kShape.rows, kShape.columns, &production_registers,
              &production_shared, &production_local,
              &production_maximum_threads, &production_active_blocks));
  const cudaError_t candidate_status = static_cast<cudaError_t>(
      q3x::kernels::
          query_sm87_nvfp4_w4a16_small_m32_wmma_k64_dual_a_table_free_raw_weight_cp_async_resources_test_cuda(
              kShape.rows, kShape.columns, &candidate_registers,
              &candidate_shared, &candidate_local,
              &candidate_maximum_threads, &candidate_active_blocks));
  const bool resource_gate =
      production_status == cudaSuccess && candidate_status == cudaSuccess &&
      production_registers <= 51 && production_shared == 23'552U &&
      production_local == 0U && production_maximum_threads == 256 &&
      production_active_blocks >= 5 && candidate_registers <= 51 &&
      candidate_shared == 27'648U && candidate_local == 0U &&
      candidate_maximum_threads == 256 && candidate_active_blocks >= 5;
  std::cout << "NVFP4_M32_RAW_WEIGHT_CP_ASYNC_RESOURCES: "
            << "production_status=" << static_cast<int>(production_status)
            << " production_registers=" << production_registers
            << " production_shared=" << production_shared
            << " production_local=" << production_local
            << " production_active_blocks=" << production_active_blocks
            << " candidate_status=" << static_cast<int>(candidate_status)
            << " candidate_registers=" << candidate_registers
            << " candidate_shared=" << candidate_shared
            << " candidate_local=" << candidate_local
            << " candidate_active_blocks=" << candidate_active_blocks
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  test.expect(resource_gate,
              "NVFP4 exact-M32 raw-weight cp.async clears resource gate");
  if (!resource_gate) {
    return;
  }

  const NvFp4M32TableFreeShapeMeasurement measurement =
      benchmark_nvfp4_m32_table_free_shape(test, stream, kShape, true);
  bool all_cells_pass = true;
  double aggregate_production = 0.0;
  double aggregate_candidate = 0.0;
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M32TableFreeCellMeasurement& cell =
        measurement.distributions[distribution_index];
    const double speedup =
        cell.production_milliseconds / cell.candidate_milliseconds;
    const bool finite =
        std::isfinite(cell.production_milliseconds) &&
        std::isfinite(cell.candidate_milliseconds) &&
        std::isfinite(cell.minimum_round_speedup) &&
        std::isfinite(speedup) && cell.production_milliseconds > 0.0 &&
        cell.candidate_milliseconds > 0.0;
    const bool cell_gate =
        cell.bitwise_equal && cell.output_finite && finite &&
        speedup >= kMinimumCellSpeedup &&
        cell.minimum_round_speedup >= kMinimumRoundSpeedup;
    all_cells_pass = all_cells_pass && cell_gate;
    aggregate_production += cell.production_milliseconds;
    aggregate_candidate += cell.candidate_milliseconds;
    std::cout << "PERF_NVFP4_M32_RAW_WEIGHT_CP_ASYNC_CELL: distribution="
              << nvfp4_m1_scale_distribution_name(
                     kNvFp4M16K128ScaleDistributions[distribution_index])
              << " production_ms=" << cell.production_milliseconds
              << " candidate_ms=" << cell.candidate_milliseconds
              << " speedup=" << speedup
              << " minimum_round_speedup=" << cell.minimum_round_speedup
              << " required_speedup=" << kMinimumCellSpeedup
              << " required_minimum_round_speedup="
              << kMinimumRoundSpeedup
              << " bitwise=" << (cell.bitwise_equal ? "true" : "false")
              << " output_finite="
              << (cell.output_finite ? "true" : "false")
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
    test.expect(
        cell_gate,
        std::string("NVFP4 exact-M32 raw-weight cp.async ") +
            nvfp4_m1_scale_distribution_name(
                kNvFp4M16K128ScaleDistributions[distribution_index]) +
            " clears isolated timing gate");
  }

  const double aggregate_speedup =
      aggregate_production / aggregate_candidate;
  const bool isolated_gate =
      all_cells_pass && std::isfinite(aggregate_speedup) &&
      aggregate_production > 0.0 && aggregate_candidate > 0.0 &&
      aggregate_speedup >= kMinimumAggregateSpeedup;
  std::cout << "PERF_NVFP4_M32_RAW_WEIGHT_CP_ASYNC_AGGREGATE: "
            << "production_ms=" << aggregate_production
            << " candidate_ms=" << aggregate_candidate
            << " speedup=" << aggregate_speedup
            << " required_speedup=" << kMinimumAggregateSpeedup
            << " all_cells=" << (all_cells_pass ? "PASS" : "FAIL")
            << " distributions=checkpoint_like:same_bank_stress"
            << " gate=" << (isolated_gate ? "PASS" : "FAIL") << '\n';
  test.expect(isolated_gate,
              "NVFP4 exact-M32 raw-weight cp.async clears isolated gate");
  if (!isolated_gate) {
    std::cout << "STOP: NVFP4 exact-M32 raw-weight cp.async missed its "
                 "isolated strong gate; dual-stream pair not measured\n";
    return;
  }

  run_nvfp4_m32_table_free_pair_performance(test, stream, true);
}

struct NvFp4M18MaskedM32CellMeasurement {
  double baseline_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
  bool correctness = false;
};

struct NvFp4M18MaskedM32ShapeMeasurement {
  std::array<NvFp4M18MaskedM32CellMeasurement,
             kNvFp4M16K128ScaleDistributions.size()>
      distributions{};
};

struct NvFp4M18MaskedM32Shape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  const char* label;
};

[[nodiscard]] NvFp4M18MaskedM32ShapeMeasurement
benchmark_nvfp4_m18_masked_m32_shape(
    TestContext& test, cudaStream_t stream,
    const NvFp4M18MaskedM32Shape& shape) {
  constexpr std::size_t kValidTokens = 18U;
  constexpr std::size_t kPrefixTokens = 16U;
  constexpr std::size_t kPaddedTokens = 32U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 4;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr std::uint8_t kCandidateSentinelByte = 0xa5U;
  constexpr std::uint8_t kReplaySentinelByte = 0x5aU;
  constexpr std::uint16_t kReplaySentinel = 0x5a5aU;
  const std::size_t packed_columns = shape.columns / 2U;
  const std::size_t scale_columns = shape.columns / 16U;
  const std::size_t valid_output_elements = kValidTokens * shape.rows;
  const std::size_t padded_output_elements = kPaddedTokens * shape.rows;
  const std::string label = shape.label;

  std::vector<std::uint8_t> host_packed(shape.rows * packed_columns);
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t row = 0U; row < shape.rows; ++row) {
    for (std::size_t packed_column = 0U; packed_column < packed_columns;
         ++packed_column) {
      const std::uint8_t low = static_cast<std::uint8_t>(
          (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
      const std::uint8_t high = static_cast<std::uint8_t>(
          (packed_column * 5U + row * 7U +
           (packed_column >> 3U) * 3U + 1U) &
          0x0fU);
      host_packed[row * packed_columns + packed_column] =
          static_cast<std::uint8_t>(low | (high << 4U));
      low_nibble_covered[low] = true;
      high_nibble_covered[high] = true;
    }
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 low-nibble code");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 high-nibble code");

  std::vector<std::uint8_t> host_scales(shape.rows * scale_columns);
  std::vector<std::uint16_t> host_activations(
      kPaddedTokens * shape.columns, encode_bf16(0.0F));
  for (std::size_t token = 0U; token < kValidTokens; ++token) {
    for (std::size_t column = 0U; column < shape.columns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * shape.columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> padded_activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> public_m32_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  DeviceBuffer<std::uint16_t> replay_output;
  bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(
                       activations.allocate(kValidTokens * shape.columns),
                       label + " allocate exact M18 activations");
  ready = ready && test.cuda_ok(
                       padded_activations.allocate(host_activations.size()),
                       label + " allocate public M32 padded activations");
  ready = ready && test.cuda_ok(
                       baseline_output.allocate(valid_output_elements),
                       label + " allocate preceding M16+M2 output");
  ready = ready && test.cuda_ok(
                       public_m32_output.allocate(padded_output_elements),
                       label + " allocate public M32 output");
  ready = ready && test.cuda_ok(
                       candidate_output.allocate(valid_output_elements),
                       label + " allocate exact M18 masked-M32 output");
  ready = ready && test.cuda_ok(
                       replay_output.allocate(padded_output_elements),
                       label + " allocate masked-M32 replay and tail");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), host_packed.data(),
                                       host_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed all-nibble weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           kValidTokens * shape.columns *
                               sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize exact M18 activations");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           padded_activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize public M32 zero padding");
  if (!ready) {
    return {};
  }

  const auto launch_baseline = [&]() noexcept -> int {
    int status = q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2, activations.get(),
        shape.rows, shape.columns, baseline_output.get(),
        static_cast<void*>(stream));
    if (status != static_cast<int>(cudaSuccess)) {
      return status;
    }
    return q3x::kernels::launch_sm87_nvfp4_w4a16_small_m_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2,
        activations.get() + kPrefixTokens * shape.columns,
        kValidTokens - kPrefixTokens, shape.rows, shape.columns,
        baseline_output.get() + kPrefixTokens * shape.rows,
        static_cast<void*>(stream));
  };
  const auto launch_public_m32 = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_m32_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2, padded_activations.get(),
        shape.rows, shape.columns, public_m32_output.get(),
        static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_m18_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2, activations.get(),
        shape.rows, shape.columns, candidate_output.get(),
        static_cast<void*>(stream));
  };
  const auto launch_replay = [&]() noexcept -> int {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_m18_gemm_bf16_cuda(
        packed.get(), scales.get(), kWeightScale2, activations.get(),
        shape.rows, shape.columns, replay_output.get(),
        static_cast<void*>(stream));
  };

  std::vector<std::uint16_t> baseline(valid_output_elements);
  std::vector<std::uint16_t> public_m32(valid_output_elements);
  std::vector<std::uint16_t> candidate(valid_output_elements);
  std::vector<std::uint16_t> replay(padded_output_elements);
  NvFp4M18MaskedM32ShapeMeasurement shape_measurement{};
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M16K128ScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns, distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize scales");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             candidate_output.get(), kCandidateSentinelByte,
                             valid_output_elements * sizeof(std::uint16_t),
                             stream),
                         distribution_label + " poison candidate output");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             replay_output.get(), kReplaySentinelByte,
                             padded_output_elements * sizeof(std::uint16_t),
                             stream),
                         distribution_label + " poison replay output");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         distribution_label + " correctness preceding M16+M2");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_public_m32()),
                         distribution_label + " correctness public M32");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         distribution_label + " correctness masked M32");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_replay()),
                         distribution_label + " deterministic replay");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy preceding M16+M2");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             public_m32.data(), public_m32_output.get(),
                             public_m32.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy public M32 prefix");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy exact M18 candidate");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             replay.data(), replay_output.get(),
                             replay.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy replay and tail");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " correctness synchronize");
    if (!ready) {
      return shape_measurement;
    }

    const std::size_t prefix_output_elements = kPrefixTokens * shape.rows;
    std::size_t public_m32_mismatches = 0U;
    std::size_t prefix_mismatches = 0U;
    std::size_t replay_mismatches = 0U;
    std::size_t tail_bf16_mismatches = 0U;
    float maximum_tail_absolute_error = 0.0F;
    float maximum_tail_relative_error = 0.0F;
    bool tail_within_tolerance = true;
    bool output_finite = true;
    for (std::size_t index = 0U; index < valid_output_elements; ++index) {
      public_m32_mismatches +=
          candidate[index] != public_m32[index] ? 1U : 0U;
      replay_mismatches += candidate[index] != replay[index] ? 1U : 0U;
      output_finite = output_finite &&
                      std::isfinite(decode_bf16(baseline[index])) &&
                      std::isfinite(decode_bf16(public_m32[index])) &&
                      std::isfinite(decode_bf16(candidate[index])) &&
                      std::isfinite(decode_bf16(replay[index]));
      if (index < prefix_output_elements) {
        prefix_mismatches += candidate[index] != baseline[index] ? 1U : 0U;
        continue;
      }
      tail_bf16_mismatches += candidate[index] != baseline[index] ? 1U : 0U;
      const float baseline_value = decode_bf16(baseline[index]);
      const float candidate_value = decode_bf16(candidate[index]);
      const float absolute_error =
          std::fabs(candidate_value - baseline_value);
      const float relative_error =
          absolute_error / std::max(1.0e-6F, std::fabs(baseline_value));
      maximum_tail_absolute_error =
          std::max(maximum_tail_absolute_error, absolute_error);
      maximum_tail_relative_error =
          std::max(maximum_tail_relative_error, relative_error);
      const float tolerance =
          2.0e-4F * std::sqrt(static_cast<float>(shape.columns)) +
          1.0e-2F * std::max(1.0F, std::fabs(baseline_value));
      tail_within_tolerance =
          tail_within_tolerance && std::isfinite(candidate_value) &&
          std::isfinite(baseline_value) && absolute_error <= tolerance;
    }
    bool replay_tail_intact = true;
    for (std::size_t index = valid_output_elements;
         index < padded_output_elements; ++index) {
      replay_tail_intact =
          replay_tail_intact && replay[index] == kReplaySentinel;
    }
    const bool public_m32_bitwise = public_m32_mismatches == 0U;
    const bool prefix_bitwise = prefix_mismatches == 0U;
    const bool deterministic = replay_mismatches == 0U;
    const bool correctness =
        public_m32_bitwise && prefix_bitwise && deterministic &&
        tail_within_tolerance && output_finite && replay_tail_intact;
    shape_measurement.distributions[distribution_index].correctness =
        correctness;
    std::cout << "NVFP4_M18_MASKED_M32_DIFF: " << label
              << " distribution="
              << nvfp4_m1_scale_distribution_name(distribution)
              << " candidate_vs_public_m32_mismatches="
              << public_m32_mismatches << '/' << valid_output_elements
              << " first16_vs_preceding_m16_plus_m2_mismatches="
              << prefix_mismatches << '/' << prefix_output_elements
              << " tail2_bf16_mismatches=" << tail_bf16_mismatches << '/'
              << valid_output_elements - prefix_output_elements
              << " tail2_max_abs=" << maximum_tail_absolute_error
              << " tail2_max_rel=" << maximum_tail_relative_error
              << " replay_mismatches=" << replay_mismatches << '/'
              << valid_output_elements
              << " output_finite=" << (output_finite ? "true" : "false")
              << " candidate_capacity=exact_m18"
              << " replay_tail=" << (replay_tail_intact ? "intact" : "BAD")
              << " gate=" << (correctness ? "PASS" : "FAIL") << '\n';
    test.expect(public_m32_bitwise,
                distribution_label +
                    " masked M32 first 18 tokens match public M32 bits");
    test.expect(prefix_bitwise,
                distribution_label +
                    " masked M32 first 16 tokens match preceding M16+M2 bits");
    test.expect(tail_within_tolerance,
                distribution_label +
                    " masked M32 tail two clears the existing tolerance");
    test.expect(deterministic,
                distribution_label + " masked M32 replay is bitwise stable");
    test.expect(output_finite,
                distribution_label + " all first-18 outputs remain finite");
    test.expect(replay_tail_intact,
                distribution_label +
                    " masked M32 preserves the complete 14-token replay "
                    "output tail");

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           distribution_label + " preceding M16+M2 warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           distribution_label + " masked M32 warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " warmup synchronize");
    if (!ready) {
      return shape_measurement;
    }

    double baseline_total = 0.0;
    double candidate_total = 0.0;
    bool timings_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          distribution_label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " preceding M16+M2 pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " masked M32 pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " masked M32 pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " preceding M16+M2 pass 2");
      const bool round_finite =
          std::isfinite(baseline_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(baseline_second);
      timings_finite = timings_finite && round_finite;
      if (round_finite) {
        baseline_total += baseline_first + baseline_second;
        candidate_total += candidate_first + candidate_second;
      }
      std::cout << "PERF_NVFP4_M18_MASKED_M32_ROUND: " << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }
    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    NvFp4M18MaskedM32CellMeasurement& measurement =
        shape_measurement.distributions[distribution_index];
    if (timings_finite) {
      measurement.baseline_milliseconds = baseline_total / kTimedPasses;
      measurement.candidate_milliseconds = candidate_total / kTimedPasses;
    }
  }
  return shape_measurement;
}

void run_optional_nvfp4_m18_masked_m32_performance(TestContext& test,
                                                    cudaStream_t stream) {
  if (!nvfp4_m18_masked_m32_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M18 masked-M32 performance segment; set "
                 "Q3X_RUN_SM87_NVFP4_M18_MASKED_M32_PERF=1 to enable\n";
    return;
  }

  constexpr double kMinimumCellSpeedup = 1.05;
  constexpr double kMinimumWeightedSpeedup = 1.15;
  constexpr std::array<NvFp4M18MaskedM32Shape, 2U> kShapes{{
      {17'408U, 5'120U, 128U, "NVFP4 M18 masked-M32 gate/up 17408x5120"},
      {5'120U, 17'408U, 64U, "NVFP4 M18 masked-M32 down 5120x17408"},
  }};

  std::array<NvFp4M18MaskedM32ShapeMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    int registers_per_thread = 0;
    std::size_t static_shared_bytes = 0U;
    std::size_t local_bytes = 0U;
    int maximum_threads_per_block = 0;
    int active_blocks_per_sm = 0;
    const int resource_status = q3x::kernels::
        query_sm87_nvfp4_w4a16_small_m18_masked_m32_wmma_resources_test_cuda(
            kShapes[shape_index].rows, kShapes[shape_index].columns,
            &registers_per_thread, &static_shared_bytes, &local_bytes,
            &maximum_threads_per_block, &active_blocks_per_sm);
    const bool resource_gate =
        static_cast<cudaError_t>(resource_status) == cudaSuccess &&
        registers_per_thread <= 46 && static_shared_bytes == 24'576U &&
        local_bytes == 0U && maximum_threads_per_block == 256 &&
        active_blocks_per_sm >= 5;
    std::cout << "NVFP4_M18_MASKED_M32_RESOURCES: "
              << kShapes[shape_index].label
              << " registers_per_thread=" << registers_per_thread
              << " static_shared_bytes=" << static_shared_bytes
              << " local_bytes=" << local_bytes
              << " maximum_threads_per_block=" << maximum_threads_per_block
              << " active_blocks_per_sm=" << active_blocks_per_sm
              << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
    test.expect(resource_gate,
                std::string(kShapes[shape_index].label) +
                    " resource query remains launchable without local spills");
    measurements[shape_index] = benchmark_nvfp4_m18_masked_m32_shape(
        test, stream, kShapes[shape_index]);
  }

  bool all_cells_pass = true;
  double weighted_baseline = 0.0;
  double weighted_candidate = 0.0;
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    for (std::size_t distribution_index = 0U;
         distribution_index < kNvFp4M16K128ScaleDistributions.size();
         ++distribution_index) {
      const NvFp4M18MaskedM32CellMeasurement& measurement =
          measurements[shape_index].distributions[distribution_index];
      const double speedup =
          measurement.baseline_milliseconds / measurement.candidate_milliseconds;
      const bool finite =
          std::isfinite(measurement.baseline_milliseconds) &&
          std::isfinite(measurement.candidate_milliseconds) &&
          std::isfinite(speedup) && measurement.baseline_milliseconds > 0.0 &&
          measurement.candidate_milliseconds > 0.0;
      const bool cell_gate = measurement.correctness && finite &&
                             speedup >= kMinimumCellSpeedup;
      all_cells_pass = all_cells_pass && cell_gate;
      const double profile_calls =
          static_cast<double>(kShapes[shape_index].profile_calls);
      weighted_baseline +=
          profile_calls * measurement.baseline_milliseconds;
      weighted_candidate +=
          profile_calls * measurement.candidate_milliseconds;
      std::cout << "PERF_NVFP4_M18_MASKED_M32_CELL: "
                << kShapes[shape_index].label << " distribution="
                << nvfp4_m1_scale_distribution_name(
                       kNvFp4M16K128ScaleDistributions[distribution_index])
                << " production_m16_plus_m2_ms="
                << measurement.baseline_milliseconds
                << " masked_m32_ms=" << measurement.candidate_milliseconds
                << " speedup=" << speedup
                << " required_speedup=" << kMinimumCellSpeedup
                << " correctness="
                << (measurement.correctness ? "true" : "false")
                << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
      test.expect(
          cell_gate,
          std::string(kShapes[shape_index].label) + " " +
              nvfp4_m1_scale_distribution_name(
                  kNvFp4M16K128ScaleDistributions[distribution_index]) +
              " clears the M18 masked-M32 cell gate");
    }
  }

  const double weighted_speedup = weighted_baseline / weighted_candidate;
  const bool aggregate_gate =
      all_cells_pass && std::isfinite(weighted_baseline) &&
      std::isfinite(weighted_candidate) && std::isfinite(weighted_speedup) &&
      weighted_baseline > 0.0 && weighted_candidate > 0.0 &&
      weighted_speedup >= kMinimumWeightedSpeedup;
  std::cout << "PERF_NVFP4_M18_MASKED_M32_AGGREGATE: "
            << "weighted_production_m16_plus_m2_ms=" << weighted_baseline
            << " weighted_masked_m32_ms=" << weighted_candidate
            << " speedup=" << weighted_speedup
            << " required_speedup=" << kMinimumWeightedSpeedup
            << " profile_calls=128:64"
            << " distributions=checkpoint_like:same_bank_stress"
            << " all_cells=" << (all_cells_pass ? "PASS" : "FAIL")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "NVFP4 M18 masked-M32 clears every cell and the weighted "
              "production gate");
}

constexpr std::array<std::size_t, 14U>
    kNvFp4RuntimeMaskedM32PerformanceTokens{{
        31U, 25U, 24U, 17U, 19U, 20U, 21U,
        22U, 23U, 26U, 27U, 28U, 29U, 30U,
    }};

struct NvFp4RuntimeMaskedM32PerfCell {
  double baseline_milliseconds = std::numeric_limits<double>::quiet_NaN();
  double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
  bool correctness = false;
  bool no_round_reversal = true;
};

using NvFp4RuntimeMaskedM32PerfShapeMeasurement =
    std::array<std::array<NvFp4RuntimeMaskedM32PerfCell,
                          kNvFp4M16K128ScaleDistributions.size()>,
               kNvFp4RuntimeMaskedM32PerformanceTokens.size()>;

struct NvFp4RuntimeMaskedM32PerfShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  const char* label;
};

[[nodiscard]] NvFp4RuntimeMaskedM32PerfShapeMeasurement
benchmark_nvfp4_m17_m31_runtime_masked_m32_shape(
    TestContext& test, cudaStream_t stream,
    const NvFp4RuntimeMaskedM32PerfShape& shape) {
  constexpr std::size_t kPaddedTokens = 32U;
  constexpr std::size_t kPrefixTokens = 16U;
  constexpr std::size_t kMaximumSmallMTokens = 8U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 4;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr std::uint8_t kCandidateTailSentinelByte = 0x4eU;
  constexpr std::uint16_t kCandidateTailSentinel = 0x4e4eU;
  const std::size_t packed_columns = shape.columns / 2U;
  const std::size_t scale_columns = shape.columns / 16U;

  std::vector<std::uint8_t> host_packed(shape.rows * packed_columns);
  for (std::size_t row = 0U; row < shape.rows; ++row) {
    for (std::size_t packed_column = 0U; packed_column < packed_columns;
         ++packed_column) {
      const std::uint8_t low = static_cast<std::uint8_t>(
          (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
      const std::uint8_t high = static_cast<std::uint8_t>(
          (packed_column * 5U + row * 7U +
           (packed_column >> 3U) * 3U + 1U) &
          0x0fU);
      host_packed[row * packed_columns + packed_column] =
          static_cast<std::uint8_t>(low | (high << 4U));
    }
  }
  std::vector<std::uint8_t> host_scales(shape.rows * scale_columns);
  std::vector<std::uint16_t> host_activations(kPaddedTokens * shape.columns);
  for (std::size_t token = 0U; token < kPaddedTokens; ++token) {
    for (std::size_t column = 0U; column < shape.columns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * shape.columns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> public_m32_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  const std::size_t padded_output_elements = kPaddedTokens * shape.rows;
  bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                            std::string(shape.label) + " allocate weights");
  ready = ready && test.cuda_ok(
                       scales.allocate(host_scales.size()),
                       std::string(shape.label) + " allocate scales");
  ready = ready && test.cuda_ok(
                       activations.allocate(host_activations.size()),
                       std::string(shape.label) + " allocate activations");
  ready = ready && test.cuda_ok(
                       baseline_output.allocate(padded_output_elements),
                       std::string(shape.label) + " allocate baseline output");
  ready = ready && test.cuda_ok(
                       public_m32_output.allocate(padded_output_elements),
                       std::string(shape.label) + " allocate public M32 output");
  ready = ready && test.cuda_ok(
                       candidate_output.allocate(padded_output_elements),
                       std::string(shape.label) + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), host_packed.data(),
                                       host_packed.size(),
                                       cudaMemcpyHostToDevice, stream),
                       std::string(shape.label) + " initialize weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       std::string(shape.label) + " initialize activations");
  if (!ready) {
    return {};
  }

  NvFp4RuntimeMaskedM32PerfShapeMeasurement measurements{};
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M16K128ScaleDistributions[distribution_index];
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns, distribution);
    const std::string distribution_label =
        std::string(shape.label) + " " +
        nvfp4_m1_scale_distribution_name(distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize scales");
    if (!ready) {
      return measurements;
    }

    for (std::size_t token_index = 0U;
         token_index < kNvFp4RuntimeMaskedM32PerformanceTokens.size();
         ++token_index) {
      const std::size_t valid_tokens =
          kNvFp4RuntimeMaskedM32PerformanceTokens[token_index];
      const std::string cell_label =
          distribution_label + " M" + std::to_string(valid_tokens);
      const auto launch_baseline = [&]() noexcept -> int {
        int status =
            q3x::kernels::launch_sm87_nvfp4_w4a16_m16_gemm_bf16_cuda(
                packed.get(), scales.get(), kWeightScale2, activations.get(),
                shape.rows, shape.columns, baseline_output.get(),
                static_cast<void*>(stream));
        if (status != static_cast<int>(cudaSuccess)) {
          return status;
        }
        std::size_t token_offset = kPrefixTokens;
        while (token_offset < valid_tokens) {
          const std::size_t remaining = valid_tokens - token_offset;
          const std::size_t launch_tokens =
              std::min(remaining, kMaximumSmallMTokens);
          status =
              q3x::kernels::launch_sm87_nvfp4_w4a16_small_m_gemm_bf16_cuda(
                  packed.get(), scales.get(), kWeightScale2,
                  activations.get() + token_offset * shape.columns,
                  launch_tokens, shape.rows, shape.columns,
                  baseline_output.get() + token_offset * shape.rows,
                  static_cast<void*>(stream));
          if (status != static_cast<int>(cudaSuccess)) {
            return status;
          }
          token_offset += launch_tokens;
        }
        return static_cast<int>(cudaSuccess);
      };
      const auto launch_candidate = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_small_m17_m31_runtime_masked_m32_test_cuda(
                packed.get(), scales.get(), kWeightScale2, activations.get(),
                valid_tokens, shape.rows, shape.columns,
                candidate_output.get(), static_cast<void*>(stream));
      };
      const auto launch_public_m32 = [&]() noexcept -> int {
        return q3x::kernels::launch_sm87_nvfp4_w4a16_m32_gemm_bf16_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            shape.rows, shape.columns, public_m32_output.get(),
            static_cast<void*>(stream));
      };

      const std::size_t valid_output_elements = valid_tokens * shape.rows;
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           cell_label + " correctness production fallback");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_public_m32()),
                           cell_label + " correctness public M32");
      ready = ready && test.cuda_ok(
                           cudaMemsetAsync(
                               candidate_output.get(),
                               kCandidateTailSentinelByte,
                               padded_output_elements *
                                   sizeof(std::uint16_t),
                               stream),
                           cell_label + " poison candidate output tail");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           cell_label + " correctness runtime mask");
      std::vector<std::uint16_t> baseline(valid_output_elements);
      std::vector<std::uint16_t> public_m32(valid_output_elements);
      std::vector<std::uint16_t> candidate(padded_output_elements);
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               baseline.data(), baseline_output.get(),
                               valid_output_elements * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cell_label + " copy production fallback");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               public_m32.data(), public_m32_output.get(),
                               valid_output_elements * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cell_label + " copy public M32 prefix");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               padded_output_elements * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cell_label + " copy runtime mask and tail");
      ready = ready && test.cuda_ok(
                           cudaStreamSynchronize(stream),
                           cell_label + " correctness synchronize");
      if (!ready) {
        return measurements;
      }
      const std::size_t prefix_output_elements = kPrefixTokens * shape.rows;
      std::size_t public_m32_mismatches = 0U;
      std::size_t prefix_mismatches = 0U;
      std::size_t tail_bf16_mismatches = 0U;
      float maximum_tail_absolute_error = 0.0F;
      float maximum_tail_relative_error = 0.0F;
      bool tail_within_tolerance = true;
      bool output_finite = true;
      for (std::size_t index = 0U; index < valid_output_elements; ++index) {
        public_m32_mismatches +=
            public_m32[index] != candidate[index] ? 1U : 0U;
        output_finite =
            output_finite && std::isfinite(decode_bf16(baseline[index])) &&
            std::isfinite(decode_bf16(public_m32[index])) &&
            std::isfinite(decode_bf16(candidate[index]));
        if (index < prefix_output_elements) {
          prefix_mismatches +=
              baseline[index] != candidate[index] ? 1U : 0U;
          continue;
        }
        tail_bf16_mismatches +=
            baseline[index] != candidate[index] ? 1U : 0U;
        const float baseline_value = decode_bf16(baseline[index]);
        const float candidate_value = decode_bf16(candidate[index]);
        const float absolute_error =
            std::fabs(candidate_value - baseline_value);
        const float relative_error =
            absolute_error / std::max(1.0e-6F, std::fabs(baseline_value));
        maximum_tail_absolute_error =
            std::max(maximum_tail_absolute_error, absolute_error);
        maximum_tail_relative_error =
            std::max(maximum_tail_relative_error, relative_error);
        const float tolerance =
            2.0e-4F * std::sqrt(static_cast<float>(shape.columns)) +
            1.0e-2F * std::max(1.0F, std::fabs(baseline_value));
        tail_within_tolerance =
            tail_within_tolerance && std::isfinite(candidate_value) &&
            std::isfinite(baseline_value) && absolute_error <= tolerance;
      }
      const bool candidate_tail_intact = std::all_of(
          candidate.begin() +
              static_cast<std::ptrdiff_t>(valid_output_elements),
          candidate.end(), [](const std::uint16_t value) noexcept {
            return value == kCandidateTailSentinel;
          });
      const bool correctness = public_m32_mismatches == 0U &&
                               prefix_mismatches == 0U &&
                               tail_within_tolerance && output_finite &&
                               candidate_tail_intact;
      std::cout << "NVFP4_M17_M31_RUNTIME_MASKED_M32_PERF_DIFF: "
                << cell_label << " candidate_vs_public_m32_mismatches="
                << public_m32_mismatches << '/' << valid_output_elements
                << " first16_vs_production_fallback_mismatches="
                << prefix_mismatches << '/' << prefix_output_elements
                << " tail_bf16_mismatches=" << tail_bf16_mismatches << '/'
                << valid_output_elements - prefix_output_elements
                << " tail_max_abs=" << maximum_tail_absolute_error
                << " tail_max_rel=" << maximum_tail_relative_error
                << " output_finite=" << (output_finite ? "true" : "false")
                << " candidate_tail="
                << (candidate_tail_intact ? "intact" : "BAD")
                << " gate=" << (correctness ? "PASS" : "FAIL") << '\n';
      test.expect(correctness,
                  cell_label +
                      " runtime mask matches public M32 bits, the production "
                      "prefix, the production-tail tolerance, and its exact "
                      "write extent before timing");

      for (int iteration = 0; iteration < kWarmupIterations && ready;
           ++iteration) {
        ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                             cell_label + " production fallback warmup");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_candidate()),
                             cell_label + " runtime-mask warmup");
      }
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cell_label + " warmup synchronize");
      if (!ready) {
        return measurements;
      }

      double baseline_total = 0.0;
      double candidate_total = 0.0;
      bool timings_finite = true;
      bool no_round_reversal = true;
      for (int round = 0; round < kMeasurementRounds; ++round) {
        const std::string round_label =
            cell_label + " round=" + std::to_string(round + 1);
        const float baseline_first = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 1");
        const float candidate_first = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 1");
        const float candidate_second = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 2");
        const float baseline_second = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 2");
        const bool round_finite =
            std::isfinite(baseline_first) &&
            std::isfinite(candidate_first) &&
            std::isfinite(candidate_second) &&
            std::isfinite(baseline_second);
        const bool round_not_reversed =
            round_finite &&
            candidate_first + candidate_second <=
                baseline_first + baseline_second;
        timings_finite = timings_finite && round_finite;
        no_round_reversal = no_round_reversal && round_not_reversed;
        if (round_finite) {
          baseline_total += baseline_first + baseline_second;
          candidate_total += candidate_first + candidate_second;
        }
        std::cout << "PERF_NVFP4_M17_M31_RUNTIME_MASKED_M32_ROUND: "
                  << round_label
                  << " baseline_pass1_ms=" << baseline_first
                  << " candidate_pass1_ms=" << candidate_first
                  << " candidate_pass2_ms=" << candidate_second
                  << " baseline_pass2_ms=" << baseline_second
                  << " no_reversal="
                  << (round_not_reversed ? "true" : "false") << '\n';
      }
      NvFp4RuntimeMaskedM32PerfCell& cell =
          measurements[token_index][distribution_index];
      constexpr double kTimedPasses =
          2.0 * static_cast<double>(kMeasurementRounds);
      if (timings_finite) {
        cell.baseline_milliseconds = baseline_total / kTimedPasses;
        cell.candidate_milliseconds = candidate_total / kTimedPasses;
      }
      cell.correctness = correctness;
      cell.no_round_reversal = no_round_reversal;
    }
  }
  return measurements;
}

void run_optional_nvfp4_m17_m31_runtime_masked_m32_performance(
    TestContext& test, cudaStream_t stream) {
  if (!nvfp4_m17_m31_runtime_masked_m32_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M17-M31 runtime masked-M32 performance segment; set "
           "Q3X_RUN_SM87_NVFP4_M17_M31_RUNTIME_MASKED_M32_PERF=1 to enable\n";
    return;
  }

  constexpr double kMinimumCellSpeedup = 1.05;
  constexpr double kMinimumPerMWeightedSpeedup = 1.15;
  constexpr std::array<NvFp4RuntimeMaskedM32PerfShape, 2U> kShapes{{
      {17'408U, 5'120U, 2U, "NVFP4 runtime-mask gate/up 17408x5120"},
      {5'120U, 17'408U, 1U, "NVFP4 runtime-mask down 5120x17408"},
  }};
  std::array<NvFp4RuntimeMaskedM32PerfShapeMeasurement, kShapes.size()>
      measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] =
        benchmark_nvfp4_m17_m31_runtime_masked_m32_shape(
            test, stream, kShapes[shape_index]);
  }

  for (std::size_t token_index = 0U;
       token_index < kNvFp4RuntimeMaskedM32PerformanceTokens.size();
       ++token_index) {
    const std::size_t valid_tokens =
        kNvFp4RuntimeMaskedM32PerformanceTokens[token_index];
    bool all_m_cells_pass = true;
    double weighted_baseline = 0.0;
    double weighted_candidate = 0.0;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      for (std::size_t distribution_index = 0U;
           distribution_index < kNvFp4M16K128ScaleDistributions.size();
           ++distribution_index) {
        const NvFp4RuntimeMaskedM32PerfCell& cell =
            measurements[shape_index][token_index][distribution_index];
        const double speedup =
            cell.baseline_milliseconds / cell.candidate_milliseconds;
        const bool finite =
            std::isfinite(cell.baseline_milliseconds) &&
            std::isfinite(cell.candidate_milliseconds) &&
            std::isfinite(speedup) && cell.baseline_milliseconds > 0.0 &&
            cell.candidate_milliseconds > 0.0;
        const bool cell_gate = cell.correctness && finite &&
                               cell.no_round_reversal &&
                               speedup >= kMinimumCellSpeedup;
        all_m_cells_pass = all_m_cells_pass && cell_gate;
        const double profile_calls =
            static_cast<double>(kShapes[shape_index].profile_calls);
        weighted_baseline += profile_calls * cell.baseline_milliseconds;
        weighted_candidate += profile_calls * cell.candidate_milliseconds;
        std::cout << "PERF_NVFP4_M17_M31_RUNTIME_MASKED_M32_CELL: M="
                  << valid_tokens << " shape=" << kShapes[shape_index].label
                  << " distribution="
                  << nvfp4_m1_scale_distribution_name(
                         kNvFp4M16K128ScaleDistributions[distribution_index])
                  << " production_fallback_ms="
                  << cell.baseline_milliseconds
                  << " runtime_masked_m32_ms="
                  << cell.candidate_milliseconds
                  << " speedup=" << speedup
                  << " required_speedup=" << kMinimumCellSpeedup
                  << " correctness="
                  << (cell.correctness ? "true" : "false")
                  << " no_round_reversal="
                  << (cell.no_round_reversal ? "true" : "false")
                  << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
        test.expect(cell_gate,
                    std::string(kShapes[shape_index].label) + " M" +
                        std::to_string(valid_tokens) + " " +
                        nvfp4_m1_scale_distribution_name(
                            kNvFp4M16K128ScaleDistributions[
                                distribution_index]) +
                        " clears its runtime-mask cell gate without a round "
                        "reversal");
      }
    }
    const double weighted_speedup = weighted_baseline / weighted_candidate;
    const bool per_m_gate =
        all_m_cells_pass && std::isfinite(weighted_speedup) &&
        weighted_baseline > 0.0 && weighted_candidate > 0.0 &&
        weighted_speedup >= kMinimumPerMWeightedSpeedup;
    std::cout << "PERF_NVFP4_M17_M31_RUNTIME_MASKED_M32_PER_M: M="
              << valid_tokens
              << " weighted_production_fallback_ms=" << weighted_baseline
              << " weighted_runtime_masked_m32_ms=" << weighted_candidate
              << " weighted_speedup=" << weighted_speedup
              << " required_speedup=" << kMinimumPerMWeightedSpeedup
              << " shape_weight=2:1 distributions=checkpoint_like:same_bank_stress"
              << " all_cells=" << (all_m_cells_pass ? "PASS" : "FAIL")
              << " gate=" << (per_m_gate ? "PASS" : "FAIL") << '\n';
    test.expect(per_m_gate,
                "NVFP4 runtime masked-M32 M" +
                    std::to_string(valid_tokens) +
                    " clears its independent 2:1 weighted gate");
  }
}

void run_optional_nvfp4_m17_m31_raw_weight_cp_async_performance(
    TestContext& test, cudaStream_t stream) {
  if (!nvfp4_m17_m31_raw_weight_cp_async_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M17-M31 gate/up single-slot raw-weight cp.async "
           "screening matrix; set "
           "Q3X_RUN_SM87_NVFP4_M17_M31_RAW_WEIGHT_CP_ASYNC_PERF=1 to "
           "enable\n";
    return;
  }

  constexpr std::size_t kGuardElements = 64U;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr std::uint8_t kGuardByte = 0xb7U;
  constexpr std::uint16_t kGuardValue = 0xb7b7U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 4;
  constexpr double kMinimumCellSpeedup = 1.03;
  constexpr double kMinimumPerMSpeedup = 1.03;
  constexpr double kMinimumAggregateSpeedup = 1.03;
  constexpr std::array<std::size_t, 14U> kTokenCounts{{
      17U, 19U, 20U, 21U, 22U, 23U, 24U,
      25U, 26U, 27U, 28U, 29U, 30U, 31U,
  }};

  struct Shape {
    std::size_t rows;
    std::size_t columns;
    std::size_t profile_calls;
    const char* label;
  };
  constexpr std::array<Shape, 1U> kShapes{{
      {17'408U, 5'120U, 1U, "gate/up 17408x5120"},
  }};
  struct Cell {
    double baseline_milliseconds = std::numeric_limits<double>::quiet_NaN();
    double candidate_milliseconds = std::numeric_limits<double>::quiet_NaN();
    bool correctness = false;
    bool no_round_reversal = false;
  };
  using DistributionCells =
      std::array<Cell, kNvFp4M16K128ScaleDistributions.size()>;
  using TokenCells = std::array<DistributionCells, kTokenCounts.size()>;
  std::array<TokenCells, kShapes.size()> measurements{};

  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    const Shape& shape = kShapes[shape_index];
    const std::size_t packed_columns = shape.columns / 2U;
    const std::size_t scale_columns = shape.columns / 16U;
    std::vector<std::uint8_t> host_packed(shape.rows * packed_columns);
    for (std::size_t row = 0U; row < shape.rows; ++row) {
      for (std::size_t packed_column = 0U;
           packed_column < packed_columns; ++packed_column) {
        const std::uint8_t low = static_cast<std::uint8_t>(
            (packed_column + row * 3U + (packed_column >> 3U)) & 0x0fU);
        const std::uint8_t high = static_cast<std::uint8_t>(
            (packed_column * 5U + row * 7U +
             (packed_column >> 3U) * 3U + 1U) &
            0x0fU);
        host_packed[row * packed_columns + packed_column] =
            static_cast<std::uint8_t>(low | (high << 4U));
      }
    }
    std::vector<std::uint8_t> host_scales(shape.rows * scale_columns);
    DeviceBuffer<std::uint8_t> packed;
    DeviceBuffer<std::uint8_t> scales;
    const std::string shape_label =
        std::string("raw-weight cp.async ") + shape.label;
    bool ready = test.cuda_ok(packed.allocate(host_packed.size()),
                              shape_label + " allocate packed weights");
    ready = ready &&
            test.cuda_ok(scales.allocate(host_scales.size()),
                         shape_label + " allocate scales");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             packed.get(), host_packed.data(),
                             host_packed.size(), cudaMemcpyHostToDevice,
                             stream),
                         shape_label + " initialize packed weights");
    if (!ready) {
      return;
    }

    for (std::size_t distribution_index = 0U;
         distribution_index < kNvFp4M16K128ScaleDistributions.size();
         ++distribution_index) {
      const NvFp4M1ScaleDistribution distribution =
          kNvFp4M16K128ScaleDistributions[distribution_index];
      fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                       distribution);
      const std::string distribution_label =
          shape_label + " " + nvfp4_m1_scale_distribution_name(distribution);
      ready = test.cuda_ok(
          cudaMemcpyAsync(scales.get(), host_scales.data(),
                          host_scales.size(), cudaMemcpyHostToDevice, stream),
          distribution_label + " initialize scales");
      if (!ready) {
        return;
      }

      for (std::size_t token_index = 0U;
           token_index < kTokenCounts.size(); ++token_index) {
        const std::size_t valid_tokens = kTokenCounts[token_index];
        const std::size_t activation_elements =
            valid_tokens * shape.columns;
        const std::size_t output_elements = valid_tokens * shape.rows;
        const std::size_t guarded_output_elements =
            output_elements + 2U * kGuardElements;
        const std::string cell_label =
            distribution_label + " M" + std::to_string(valid_tokens);
        std::vector<std::uint16_t> host_activations(activation_elements);
        for (std::size_t token = 0U; token < valid_tokens; ++token) {
          for (std::size_t column = 0U; column < shape.columns; ++column) {
            const int centered = static_cast<int>(
                                     (column * 17U + token * 19U + 5U) %
                                     127U) -
                                 63;
            host_activations[token * shape.columns + column] =
                encode_bf16(static_cast<float>(centered) / 256.0F);
          }
        }

        DeviceBuffer<std::uint16_t> activations;
        DeviceBuffer<std::uint16_t> baseline_output;
        DeviceBuffer<std::uint16_t> candidate_exact_output;
        DeviceBuffer<std::uint16_t> candidate_guarded_output;
        ready = test.cuda_ok(
            activations.allocate(activation_elements),
            cell_label + " allocate exact activations");
        ready = ready &&
                test.cuda_ok(baseline_output.allocate(output_elements),
                             cell_label + " allocate exact baseline output");
        ready = ready && test.cuda_ok(
                             candidate_exact_output.allocate(output_elements),
                             cell_label + " allocate exact candidate output");
        ready = ready && test.cuda_ok(
                             candidate_guarded_output.allocate(
                                 guarded_output_elements),
                             cell_label + " allocate guarded replay output");
        ready = ready && test.cuda_ok(
                             cudaMemcpyAsync(
                                 activations.get(), host_activations.data(),
                                 activation_elements * sizeof(std::uint16_t),
                                 cudaMemcpyHostToDevice, stream),
                             cell_label + " initialize exact activations");
        ready = ready && test.cuda_ok(
                             cudaMemsetAsync(
                                 candidate_guarded_output.get(), kGuardByte,
                                 guarded_output_elements *
                                     sizeof(std::uint16_t),
                                 stream),
                             cell_label + " poison candidate guards");
        if (!ready) {
          return;
        }

        const auto launch_baseline =
            [&](std::uint16_t* const output) noexcept {
              return q3x::kernels::
                  launch_sm87_nvfp4_w4a16_small_m17_m31_runtime_masked_m32_test_cuda(
                      packed.get(), scales.get(), kWeightScale2,
                      activations.get(), valid_tokens, shape.rows,
                      shape.columns, output, static_cast<void*>(stream));
            };
        const auto launch_candidate =
            [&](std::uint16_t* const output) noexcept {
              return q3x::kernels::
                  launch_sm87_nvfp4_w4a16_small_m17_m31_runtime_masked_m32_raw_weight_cp_async_test_cuda(
                      packed.get(), scales.get(), kWeightScale2,
                      activations.get(), valid_tokens, shape.rows,
                      shape.columns, output, static_cast<void*>(stream));
            };
        std::uint16_t* const guarded_candidate =
            candidate_guarded_output.get() + kGuardElements;
        ready = test.cuda_ok(
            static_cast<cudaError_t>(
                launch_baseline(baseline_output.get())),
            cell_label + " launch current-runtime baseline correctness");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_candidate(
                                 candidate_exact_output.get())),
                             cell_label + " launch exact candidate");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(
                                 launch_candidate(guarded_candidate)),
                             cell_label + " launch guarded candidate replay");
        std::vector<std::uint16_t> baseline(output_elements);
        std::vector<std::uint16_t> candidate_exact(output_elements);
        std::vector<std::uint16_t> candidate_guarded(
            guarded_output_elements);
        ready = ready && test.cuda_ok(
                             cudaMemcpyAsync(
                                 baseline.data(), baseline_output.get(),
                                 output_elements * sizeof(std::uint16_t),
                                 cudaMemcpyDeviceToHost, stream),
                             cell_label + " copy baseline");
        ready = ready && test.cuda_ok(
                             cudaMemcpyAsync(
                                 candidate_exact.data(),
                                 candidate_exact_output.get(),
                                 output_elements * sizeof(std::uint16_t),
                                 cudaMemcpyDeviceToHost, stream),
                             cell_label + " copy exact candidate");
        ready = ready && test.cuda_ok(
                             cudaMemcpyAsync(
                                 candidate_guarded.data(),
                                 candidate_guarded_output.get(),
                                 guarded_output_elements *
                                     sizeof(std::uint16_t),
                                 cudaMemcpyDeviceToHost, stream),
                             cell_label + " copy guarded candidate replay");
        ready = ready && test.cuda_ok(
                             cudaStreamSynchronize(stream),
                             cell_label + " correctness synchronize");
        if (!ready) {
          return;
        }

        std::size_t baseline_mismatches = 0U;
        std::size_t replay_mismatches = 0U;
        bool output_finite = true;
        for (std::size_t index = 0U; index < output_elements; ++index) {
          baseline_mismatches +=
              candidate_exact[index] != baseline[index] ? 1U : 0U;
          replay_mismatches +=
              candidate_guarded[kGuardElements + index] !=
                      candidate_exact[index]
                  ? 1U
                  : 0U;
          output_finite =
              output_finite &&
              std::isfinite(decode_bf16(candidate_exact[index]));
        }
        const bool head_guard_intact = std::all_of(
            candidate_guarded.begin(),
            candidate_guarded.begin() +
                static_cast<std::ptrdiff_t>(kGuardElements),
            [](const std::uint16_t value) noexcept {
              return value == kGuardValue;
            });
        const bool tail_guard_intact = std::all_of(
            candidate_guarded.begin() + static_cast<std::ptrdiff_t>(
                                            kGuardElements +
                                            output_elements),
            candidate_guarded.end(),
            [](const std::uint16_t value) noexcept {
              return value == kGuardValue;
            });
        Cell& cell =
            measurements[shape_index][token_index][distribution_index];
        cell.correctness = baseline_mismatches == 0U &&
                           replay_mismatches == 0U && output_finite &&
                           head_guard_intact && tail_guard_intact;
        std::cout << "NVFP4_RAW_WEIGHT_CP_ASYNC_CORRECTNESS: "
                  << cell_label
                  << " candidate_vs_current_runtime_mismatches="
                  << baseline_mismatches << '/' << output_elements
                  << " replay_mismatches=" << replay_mismatches << '/'
                  << output_elements
                  << " output_finite="
                  << (output_finite ? "true" : "false")
                  << " head_guard="
                  << (head_guard_intact ? "intact" : "BAD")
                  << " tail_guard="
                  << (tail_guard_intact ? "intact" : "BAD")
                  << " gate="
                  << (cell.correctness ? "PASS" : "FAIL") << '\n';
        test.expect(
            cell.correctness,
            cell_label +
                " is bit-exact against current runtime, finite, "
                "deterministic, and preserves both canaries");
        if (!cell.correctness) {
          continue;
        }

        const auto time_baseline = [&]() noexcept {
          return launch_baseline(baseline_output.get());
        };
        const auto time_candidate = [&]() noexcept {
          return launch_candidate(candidate_exact_output.get());
        };
        for (int iteration = 0;
             iteration < kWarmupIterations && ready; ++iteration) {
          ready = test.cuda_ok(
              static_cast<cudaError_t>(time_baseline()),
              cell_label + " baseline warmup");
          ready = ready && test.cuda_ok(
                               static_cast<cudaError_t>(time_candidate()),
                               cell_label + " candidate warmup");
        }
        ready = ready && test.cuda_ok(
                             cudaStreamSynchronize(stream),
                             cell_label + " warmup synchronize");
        if (!ready) {
          return;
        }

        double baseline_total = 0.0;
        double candidate_total = 0.0;
        bool timings_finite = true;
        cell.no_round_reversal = true;
        for (int round = 0; round < kMeasurementRounds; ++round) {
          const std::string round_label =
              cell_label + " round=" + std::to_string(round + 1);
          const float baseline_first = measure_small_m_tile(
              test, stream, time_baseline, kMeasuredIterations,
              round_label + " baseline pass 1");
          const float candidate_first = measure_small_m_tile(
              test, stream, time_candidate, kMeasuredIterations,
              round_label + " candidate pass 1");
          const float candidate_second = measure_small_m_tile(
              test, stream, time_candidate, kMeasuredIterations,
              round_label + " candidate pass 2");
          const float baseline_second = measure_small_m_tile(
              test, stream, time_baseline, kMeasuredIterations,
              round_label + " baseline pass 2");
          const bool round_finite =
              std::isfinite(baseline_first) &&
              std::isfinite(candidate_first) &&
              std::isfinite(candidate_second) &&
              std::isfinite(baseline_second);
          const bool round_not_reversed =
              round_finite &&
              candidate_first + candidate_second <=
                  baseline_first + baseline_second;
          timings_finite = timings_finite && round_finite;
          cell.no_round_reversal =
              cell.no_round_reversal && round_not_reversed;
          if (round_finite) {
            baseline_total += baseline_first + baseline_second;
            candidate_total += candidate_first + candidate_second;
          }
          std::cout << "PERF_NVFP4_RAW_WEIGHT_CP_ASYNC_ROUND: "
                    << round_label
                    << " baseline_pass1_ms=" << baseline_first
                    << " candidate_pass1_ms=" << candidate_first
                    << " candidate_pass2_ms=" << candidate_second
                    << " baseline_pass2_ms=" << baseline_second
                    << " no_reversal="
                    << (round_not_reversed ? "true" : "false") << '\n';
        }
        constexpr double kTimedPasses =
            2.0 * static_cast<double>(kMeasurementRounds);
        if (timings_finite) {
          cell.baseline_milliseconds = baseline_total / kTimedPasses;
          cell.candidate_milliseconds = candidate_total / kTimedPasses;
        }
      }
    }
  }

  bool all_cells_pass = true;
  bool all_per_m_pass = true;
  double aggregate_weighted_baseline = 0.0;
  double aggregate_weighted_candidate = 0.0;
  for (std::size_t token_index = 0U;
       token_index < kTokenCounts.size(); ++token_index) {
    const std::size_t valid_tokens = kTokenCounts[token_index];
    bool all_m_cells_pass = true;
    double per_m_weighted_baseline = 0.0;
    double per_m_weighted_candidate = 0.0;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      for (std::size_t distribution_index = 0U;
           distribution_index < kNvFp4M16K128ScaleDistributions.size();
           ++distribution_index) {
        const Cell& cell =
            measurements[shape_index][token_index][distribution_index];
        const double speedup =
            cell.baseline_milliseconds / cell.candidate_milliseconds;
        const bool finite =
            std::isfinite(cell.baseline_milliseconds) &&
            std::isfinite(cell.candidate_milliseconds) &&
            std::isfinite(speedup) && cell.baseline_milliseconds > 0.0 &&
            cell.candidate_milliseconds > 0.0;
        const bool cell_gate =
            cell.correctness && finite && cell.no_round_reversal &&
            speedup >= kMinimumCellSpeedup;
        all_cells_pass = all_cells_pass && cell_gate;
        all_m_cells_pass = all_m_cells_pass && cell_gate;
        const double profile_calls =
            static_cast<double>(kShapes[shape_index].profile_calls);
        per_m_weighted_baseline +=
            profile_calls * cell.baseline_milliseconds;
        per_m_weighted_candidate +=
            profile_calls * cell.candidate_milliseconds;
        std::cout << "PERF_NVFP4_RAW_WEIGHT_CP_ASYNC_CELL: M="
                  << valid_tokens
                  << " shape=" << kShapes[shape_index].label
                  << " distribution="
                  << nvfp4_m1_scale_distribution_name(
                         kNvFp4M16K128ScaleDistributions[
                             distribution_index])
                  << " current_runtime_ms="
                  << cell.baseline_milliseconds
                  << " raw_weight_cp_async_ms="
                  << cell.candidate_milliseconds
                  << " speedup=" << speedup
                  << " required_speedup=" << kMinimumCellSpeedup
                  << " correctness="
                  << (cell.correctness ? "true" : "false")
                  << " no_round_reversal="
                  << (cell.no_round_reversal ? "true" : "false")
                  << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
        test.expect(
            cell_gate,
            std::string("raw-weight cp.async M") +
                std::to_string(valid_tokens) + " " +
                kShapes[shape_index].label + " " +
                nvfp4_m1_scale_distribution_name(
                    kNvFp4M16K128ScaleDistributions[
                        distribution_index]) +
                " clears its no-regression cell gate");
      }
    }
    const double per_m_speedup =
        per_m_weighted_baseline / per_m_weighted_candidate;
    const bool per_m_gate =
        all_m_cells_pass && std::isfinite(per_m_speedup) &&
        per_m_weighted_baseline > 0.0 &&
        per_m_weighted_candidate > 0.0 &&
        per_m_speedup >= kMinimumPerMSpeedup;
    all_per_m_pass = all_per_m_pass && per_m_gate;
    aggregate_weighted_baseline += per_m_weighted_baseline;
    aggregate_weighted_candidate += per_m_weighted_candidate;
    std::cout << "PERF_NVFP4_RAW_WEIGHT_CP_ASYNC_PER_M: M="
              << valid_tokens
              << " weighted_current_runtime_ms="
              << per_m_weighted_baseline
              << " weighted_raw_weight_cp_async_ms="
              << per_m_weighted_candidate
              << " speedup=" << per_m_speedup
              << " required_speedup=" << kMinimumPerMSpeedup
              << " shape=gate/up distributions=checkpoint_like:same_bank_stress"
              << " all_cells="
              << (all_m_cells_pass ? "PASS" : "FAIL")
              << " gate=" << (per_m_gate ? "PASS" : "FAIL") << '\n';
    test.expect(per_m_gate,
                "raw-weight cp.async M" +
                    std::to_string(valid_tokens) +
                    " clears its gate/up two-distribution gate");
  }

  const double aggregate_speedup =
      aggregate_weighted_baseline / aggregate_weighted_candidate;
  const bool aggregate_gate =
      all_cells_pass && all_per_m_pass &&
      std::isfinite(aggregate_speedup) &&
      aggregate_weighted_baseline > 0.0 &&
      aggregate_weighted_candidate > 0.0 &&
      aggregate_speedup >= kMinimumAggregateSpeedup;
  std::cout << "PERF_NVFP4_RAW_WEIGHT_CP_ASYNC_AGGREGATE: "
            << "weighted_current_runtime_ms="
            << aggregate_weighted_baseline
            << " weighted_raw_weight_cp_async_ms="
            << aggregate_weighted_candidate
            << " speedup=" << aggregate_speedup
            << " required_speedup=" << kMinimumAggregateSpeedup
            << " shape=gate/up distributions=2 M_values=17,19-31"
            << " all_cells=" << (all_cells_pass ? "PASS" : "FAIL")
            << " all_per_m=" << (all_per_m_pass ? "PASS" : "FAIL")
            << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
  test.expect(aggregate_gate,
              "raw-weight cp.async clears all 28 cells, every per-M gate, "
              "and the 1.03x aggregate gate");
}

void run_optional_nvfp4_m17_m32_dual_stream_performance(
    TestContext& test, cudaStream_t stream) {
  if (!nvfp4_m17_m32_dual_stream_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M17-M32 gate/up dual-stream segment; set "
           "Q3X_RUN_SM87_NVFP4_M17_M32_DUAL_STREAM_PERF=1 to enable the "
           "full sweep (legacy activation alias, M32-only: "
           "Q3X_RUN_SM87_NVFP4_M32_DUAL_STREAM_PERF=1)\n";
    return;
  }

  constexpr std::size_t kRows = 17'408U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kMaximumTokens = 32U;
  constexpr std::size_t kPackedColumns = kColumns / 2U;
  constexpr std::size_t kScaleColumns = kColumns / 16U;
  constexpr std::size_t kMaximumOutputElements = kMaximumTokens * kRows;
  constexpr std::size_t kGuardElements = 64U;
  constexpr std::size_t kGuardedOutputElements =
      kMaximumOutputElements + 2U * kGuardElements;
  constexpr std::uint8_t kSequentialGateSentinelByte = 0xa5U;
  constexpr std::uint8_t kSequentialUpSentinelByte = 0x5aU;
  constexpr std::uint8_t kConcurrentGateSentinelByte = 0x3cU;
  constexpr std::uint8_t kConcurrentUpSentinelByte = 0xc3U;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 4;
  constexpr double kRequiredGeneralizationSpeedup = 1.03;
  constexpr double kRequiredM32RetentionSpeedup = 1.01;
  constexpr double kMinimumRoundSpeedup = 1.0;
  constexpr std::array<std::size_t, 16U> kTokenCounts{{
      17U, 18U, 19U, 20U, 21U, 22U, 23U, 24U,
      25U, 26U, 27U, 28U, 29U, 30U, 31U, 32U,
  }};

  struct CellMeasurement {
    double sequential_milliseconds =
        std::numeric_limits<double>::quiet_NaN();
    double concurrent_milliseconds =
        std::numeric_limits<double>::quiet_NaN();
    double minimum_round_speedup =
        std::numeric_limits<double>::quiet_NaN();
    double maximum_round_speedup =
        std::numeric_limits<double>::quiet_NaN();
    std::size_t gate_mismatches = 0U;
    std::size_t up_mismatches = 0U;
    std::size_t head_canary_mismatches = 0U;
    std::size_t unused_extent_mismatches = 0U;
    std::size_t tail_canary_mismatches = 0U;
    std::size_t nonfinite_outputs = 0U;
    int winning_rounds = 0;
    bool correctness = false;
    bool timings_finite = false;
    bool promotion_gate = false;
  };
  std::array<std::array<CellMeasurement,
                        kNvFp4M16K128ScaleDistributions.size()>,
             kTokenCounts.size()>
      measurements{};

  const bool full_sweep =
      nvfp4_m17_m32_dual_stream_full_sweep_enabled();
  const std::size_t first_token_index = full_sweep ? 0U : 15U;
  if (!full_sweep) {
    std::cout << "PERF_NVFP4_M17_M32_DUAL_STREAM_MODE: "
                 "legacy_m32_only=true full_sweep=false\n";
  }

  std::vector<std::uint8_t> host_gate_packed(kRows * kPackedColumns);
  std::vector<std::uint8_t> host_up_packed(host_gate_packed.size());
  for (std::size_t index = 0U; index < host_gate_packed.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 3U + (index >> 5U) + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 5U + (index >> 7U) * 3U + 7U) & 0x0fU);
    host_gate_packed[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
    host_up_packed[index] =
        static_cast<std::uint8_t>((low ^ 0x09U) |
                                  ((high ^ 0x05U) << 4U));
  }
  std::vector<std::uint8_t> host_gate_scales(kRows * kScaleColumns);
  std::vector<std::uint8_t> host_up_scales(host_gate_scales.size());
  std::vector<std::uint16_t> host_activations(kMaximumTokens * kColumns);
  for (std::size_t token = 0U; token < kMaximumTokens; ++token) {
    for (std::size_t column = 0U; column < kColumns; ++column) {
      const int centered =
          static_cast<int>((column * 17U + token * 19U + 5U) % 127U) - 63;
      host_activations[token * kColumns + column] =
          encode_bf16(static_cast<float>(centered) / 256.0F);
    }
  }

  DeviceBuffer<std::uint8_t> gate_packed;
  DeviceBuffer<std::uint8_t> up_packed;
  DeviceBuffer<std::uint8_t> gate_scales;
  DeviceBuffer<std::uint8_t> up_scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> sequential_gate_guarded;
  DeviceBuffer<std::uint16_t> sequential_up_guarded;
  DeviceBuffer<std::uint16_t> concurrent_gate_guarded;
  DeviceBuffer<std::uint16_t> concurrent_up_guarded;
  DeviceBuffer<float> scalar_scales;
  bool ready = test.cuda_ok(gate_packed.allocate(host_gate_packed.size()),
                            "dual stream allocate gate packed weights");
  ready = ready && test.cuda_ok(
                       up_packed.allocate(host_up_packed.size()),
                       "dual stream allocate up packed weights");
  ready = ready && test.cuda_ok(
                       gate_scales.allocate(host_gate_scales.size()),
                       "dual stream allocate gate block scales");
  ready = ready && test.cuda_ok(
                       up_scales.allocate(host_up_scales.size()),
                       "dual stream allocate up block scales");
  ready = ready && test.cuda_ok(
                       activations.allocate(host_activations.size()),
                       "dual stream allocate activations");
  ready = ready && test.cuda_ok(
                       sequential_gate_guarded.allocate(
                           kGuardedOutputElements),
                       "dual stream allocate guarded sequential gate output");
  ready = ready && test.cuda_ok(
                       sequential_up_guarded.allocate(kGuardedOutputElements),
                       "dual stream allocate guarded sequential up output");
  ready = ready && test.cuda_ok(
                       concurrent_gate_guarded.allocate(
                           kGuardedOutputElements),
                       "dual stream allocate guarded concurrent gate output");
  ready = ready && test.cuda_ok(
                       concurrent_up_guarded.allocate(kGuardedOutputElements),
                       "dual stream allocate guarded concurrent up output");
  ready = ready && test.cuda_ok(
                       scalar_scales.allocate(2U),
                       "dual stream allocate scalar scales");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           gate_packed.get(), host_gate_packed.data(),
                           host_gate_packed.size(), cudaMemcpyHostToDevice,
                           stream),
                       "dual stream initialize gate packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           up_packed.get(), host_up_packed.data(),
                           host_up_packed.size(), cudaMemcpyHostToDevice,
                           stream),
                       "dual stream initialize up packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activations.data(),
                           host_activations.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       "dual stream initialize activations");
  const std::array<float, 2U> host_scalar_scales{{kWeightScale2, 1.0F}};
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           scalar_scales.get(), host_scalar_scales.data(),
                           host_scalar_scales.size() * sizeof(float),
                           cudaMemcpyHostToDevice, stream),
                       "dual stream initialize scalar scales");
  if (!ready) {
    return;
  }

  cudaStream_t auxiliary_stream = nullptr;
  cudaEvent_t inputs_ready = nullptr;
  cudaEvent_t auxiliary_done = nullptr;
  ready = test.cuda_ok(
      cudaStreamCreateWithFlags(&auxiliary_stream, cudaStreamNonBlocking),
      "dual stream create auxiliary stream");
  ready = ready && test.cuda_ok(
                       cudaEventCreateWithFlags(&inputs_ready,
                                                cudaEventDisableTiming),
                       "dual stream create input-ready event");
  ready = ready && test.cuda_ok(
                       cudaEventCreateWithFlags(&auxiliary_done,
                                                cudaEventDisableTiming),
                       "dual stream create auxiliary-done event");
  if (!ready) {
    if (inputs_ready != nullptr) {
      (void)cudaEventDestroy(inputs_ready);
    }
    if (auxiliary_done != nullptr) {
      (void)cudaEventDestroy(auxiliary_done);
    }
    if (auxiliary_stream != nullptr) {
      (void)cudaStreamDestroy(auxiliary_stream);
    }
    return;
  }

  std::uint16_t* const sequential_gate_output =
      sequential_gate_guarded.get() + kGuardElements;
  std::uint16_t* const sequential_up_output =
      sequential_up_guarded.get() + kGuardElements;
  std::uint16_t* const concurrent_gate_output =
      concurrent_gate_guarded.get() + kGuardElements;
  std::uint16_t* const concurrent_up_output =
      concurrent_up_guarded.get() + kGuardElements;
  const q3x::runtime::LinearWeight gate_weight =
      q3x::runtime::NvFp4LinearWeight{
          gate_packed.get(), gate_scales.get(), scalar_scales.get(),
          scalar_scales.get() + 1U, kWeightScale2, 1.0F, kRows, kColumns};
  const q3x::runtime::LinearWeight up_weight =
      q3x::runtime::NvFp4LinearWeight{
          up_packed.get(), up_scales.get(), scalar_scales.get(),
          scalar_scales.get() + 1U, kWeightScale2, 1.0F, kRows, kColumns};
  const auto launch_one = [&](const q3x::runtime::LinearWeight& weight,
                              const std::size_t token_count,
                              std::uint16_t* const output,
                              cudaStream_t const launch_stream) noexcept {
    return q3x::runtime::launch_projection_tile_to_bf16_cuda(
        q3x::runtime::ProjectionBackend::kSm87WeightOnly, weight,
        activations.get(), token_count, nullptr, 0U, output,
        static_cast<void*>(launch_stream));
  };
  const auto poison_output = [&](DeviceBuffer<std::uint16_t>& output,
                                 const std::uint8_t sentinel,
                                 const std::string& label) {
    return test.cuda_ok(
        cudaMemsetAsync(output.get(), sentinel,
                        kGuardedOutputElements * sizeof(std::uint16_t),
                        stream),
        label);
  };

  std::vector<std::uint16_t> sequential_gate(kGuardedOutputElements);
  std::vector<std::uint16_t> sequential_up(kGuardedOutputElements);
  std::vector<std::uint16_t> concurrent_gate(kGuardedOutputElements);
  std::vector<std::uint16_t> concurrent_up(kGuardedOutputElements);
  const auto count_extent_mismatches =
      [&](const std::vector<std::uint16_t>& output,
          const std::uint8_t sentinel_byte,
          const std::size_t valid_output_elements) {
        const std::uint16_t sentinel = static_cast<std::uint16_t>(
            sentinel_byte |
            (static_cast<std::uint16_t>(sentinel_byte) << 8U));
        std::array<std::size_t, 3U> mismatches{};
        for (std::size_t index = 0U; index < kGuardElements; ++index) {
          mismatches[0] += output[index] != sentinel ? 1U : 0U;
        }
        const std::size_t unused_begin =
            kGuardElements + valid_output_elements;
        const std::size_t unused_end =
            kGuardElements + kMaximumOutputElements;
        for (std::size_t index = unused_begin; index < unused_end; ++index) {
          mismatches[1] += output[index] != sentinel ? 1U : 0U;
        }
        for (std::size_t index = unused_end;
             index < kGuardedOutputElements; ++index) {
          mismatches[2] += output[index] != sentinel ? 1U : 0U;
        }
        return mismatches;
      };

  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M16K128ScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M16K128ScaleDistributions[distribution_index];
    const std::string distribution_name =
        nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_gate_scales, kScaleColumns,
                                     distribution);
    host_up_scales = host_gate_scales;
    ready = test.cuda_ok(
        cudaMemcpyAsync(gate_scales.get(), host_gate_scales.data(),
                        host_gate_scales.size(), cudaMemcpyHostToDevice,
                        stream),
        "dual stream " + distribution_name + " initialize gate scales");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             up_scales.get(), host_up_scales.data(),
                             host_up_scales.size(), cudaMemcpyHostToDevice,
                             stream),
                         "dual stream " + distribution_name +
                             " initialize up scales");
    if (!ready) {
      break;
    }

    for (std::size_t token_index = first_token_index;
         token_index < kTokenCounts.size(); ++token_index) {
      const std::size_t token_count = kTokenCounts[token_index];
      const std::size_t valid_output_elements = token_count * kRows;
      const std::string cell_label =
          "NVFP4 M" + std::to_string(token_count) +
          " gate/up dual stream " + distribution_name;
      const auto launch_sequential = [&]() noexcept -> int {
        int status = launch_one(gate_weight, token_count,
                                sequential_gate_output, stream);
        if (status != static_cast<int>(cudaSuccess)) {
          return status;
        }
        return launch_one(up_weight, token_count, sequential_up_output,
                          stream);
      };
      const auto launch_concurrent = [&]() noexcept -> int {
        cudaError_t status = cudaEventRecord(inputs_ready, stream);
        if (status != cudaSuccess) {
          return static_cast<int>(status);
        }
        status = cudaStreamWaitEvent(auxiliary_stream, inputs_ready, 0U);
        if (status != cudaSuccess) {
          return static_cast<int>(status);
        }
        int launch_status = launch_one(gate_weight, token_count,
                                       concurrent_gate_output, stream);
        if (launch_status != static_cast<int>(cudaSuccess)) {
          return launch_status;
        }
        launch_status = launch_one(up_weight, token_count,
                                   concurrent_up_output, auxiliary_stream);
        if (launch_status != static_cast<int>(cudaSuccess)) {
          return launch_status;
        }
        status = cudaEventRecord(auxiliary_done, auxiliary_stream);
        if (status != cudaSuccess) {
          return static_cast<int>(status);
        }
        return static_cast<int>(
            cudaStreamWaitEvent(stream, auxiliary_done, 0U));
      };

      ready = poison_output(sequential_gate_guarded,
                            kSequentialGateSentinelByte,
                            cell_label + " poison sequential gate");
      ready = ready && poison_output(sequential_up_guarded,
                                     kSequentialUpSentinelByte,
                                     cell_label + " poison sequential up");
      ready = ready && poison_output(concurrent_gate_guarded,
                                     kConcurrentGateSentinelByte,
                                     cell_label + " poison concurrent gate");
      ready = ready && poison_output(concurrent_up_guarded,
                                     kConcurrentUpSentinelByte,
                                     cell_label + " poison concurrent up");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_sequential()),
                           cell_label + " correctness sequential");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_concurrent()),
                           cell_label + " correctness concurrent");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               sequential_gate.data(),
                               sequential_gate_guarded.get(),
                               kGuardedOutputElements *
                                   sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cell_label + " copy guarded sequential gate");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               sequential_up.data(),
                               sequential_up_guarded.get(),
                               kGuardedOutputElements *
                                   sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cell_label + " copy guarded sequential up");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               concurrent_gate.data(),
                               concurrent_gate_guarded.get(),
                               kGuardedOutputElements *
                                   sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cell_label + " copy guarded concurrent gate");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               concurrent_up.data(),
                               concurrent_up_guarded.get(),
                               kGuardedOutputElements *
                                   sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cell_label + " copy guarded concurrent up");
      ready = ready && test.cuda_ok(
                           cudaStreamSynchronize(stream),
                           cell_label + " correctness synchronize");
      if (!ready) {
        break;
      }

      CellMeasurement& measurement =
          measurements[token_index][distribution_index];
      for (std::size_t index = 0U; index < valid_output_elements; ++index) {
        const std::size_t guarded_index = kGuardElements + index;
        measurement.gate_mismatches +=
            sequential_gate[guarded_index] !=
                    concurrent_gate[guarded_index]
                ? 1U
                : 0U;
        measurement.up_mismatches +=
            sequential_up[guarded_index] != concurrent_up[guarded_index]
                ? 1U
                : 0U;
        measurement.nonfinite_outputs +=
            std::isfinite(decode_bf16(sequential_gate[guarded_index]))
                ? 0U
                : 1U;
        measurement.nonfinite_outputs +=
            std::isfinite(decode_bf16(sequential_up[guarded_index])) ? 0U
                                                                    : 1U;
      }
      const std::array<std::array<std::size_t, 3U>, 4U>
          extent_mismatches{{
              count_extent_mismatches(
                  sequential_gate, kSequentialGateSentinelByte,
                  valid_output_elements),
              count_extent_mismatches(sequential_up,
                                      kSequentialUpSentinelByte,
                                      valid_output_elements),
              count_extent_mismatches(
                  concurrent_gate, kConcurrentGateSentinelByte,
                  valid_output_elements),
              count_extent_mismatches(concurrent_up,
                                      kConcurrentUpSentinelByte,
                                      valid_output_elements),
          }};
      for (const std::array<std::size_t, 3U>& mismatches :
           extent_mismatches) {
        measurement.head_canary_mismatches += mismatches[0];
        measurement.unused_extent_mismatches += mismatches[1];
        measurement.tail_canary_mismatches += mismatches[2];
      }
      measurement.correctness =
          measurement.gate_mismatches == 0U &&
          measurement.up_mismatches == 0U &&
          measurement.head_canary_mismatches == 0U &&
          measurement.unused_extent_mismatches == 0U &&
          measurement.tail_canary_mismatches == 0U &&
          measurement.nonfinite_outputs == 0U;
      std::cout << "NVFP4_M17_M32_DUAL_STREAM_DIFF: M=" << token_count
                << " distribution=" << distribution_name
                << " gate_mismatches=" << measurement.gate_mismatches << '/'
                << valid_output_elements
                << " up_mismatches=" << measurement.up_mismatches << '/'
                << valid_output_elements
                << " head_canary_mismatches="
                << measurement.head_canary_mismatches
                << " unused_extent_mismatches="
                << measurement.unused_extent_mismatches
                << " tail_canary_mismatches="
                << measurement.tail_canary_mismatches
                << " nonfinite_outputs=" << measurement.nonfinite_outputs
                << " gate="
                << (measurement.correctness ? "PASS" : "FAIL") << '\n';
      test.expect(
          measurement.correctness,
          cell_label +
              " is bit-exact, finite, and preserves its exact write extent "
              "and all output canaries");

      for (int iteration = 0; iteration < kWarmupIterations && ready;
           ++iteration) {
        ready = test.cuda_ok(static_cast<cudaError_t>(launch_sequential()),
                             cell_label + " sequential warmup");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_concurrent()),
                             cell_label + " concurrent warmup");
      }
      ready = ready && test.cuda_ok(
                           cudaStreamSynchronize(stream),
                           cell_label + " warmup synchronize");
      if (!ready) {
        break;
      }

      double sequential_total = 0.0;
      double concurrent_total = 0.0;
      double minimum_round_speedup =
          std::numeric_limits<double>::infinity();
      double maximum_round_speedup = 0.0;
      bool timings_finite = true;
      int winning_rounds = 0;
      for (int round = 0; round < kMeasurementRounds; ++round) {
        const std::string round_label =
            cell_label + " round=" + std::to_string(round + 1);
        const float sequential_first = measure_small_m_tile(
            test, stream, launch_sequential, kMeasuredIterations,
            round_label + " sequential pass 1");
        const float concurrent_first = measure_small_m_tile(
            test, stream, launch_concurrent, kMeasuredIterations,
            round_label + " concurrent pass 1");
        const float concurrent_second = measure_small_m_tile(
            test, stream, launch_concurrent, kMeasuredIterations,
            round_label + " concurrent pass 2");
        const float sequential_second = measure_small_m_tile(
            test, stream, launch_sequential, kMeasuredIterations,
            round_label + " sequential pass 2");
        const bool round_finite =
            std::isfinite(sequential_first) &&
            std::isfinite(concurrent_first) &&
            std::isfinite(concurrent_second) &&
            std::isfinite(sequential_second) &&
            sequential_first > 0.0F && concurrent_first > 0.0F &&
            concurrent_second > 0.0F && sequential_second > 0.0F;
        double round_speedup =
            std::numeric_limits<double>::quiet_NaN();
        timings_finite = timings_finite && round_finite;
        if (round_finite) {
          const double sequential_round =
              static_cast<double>(sequential_first) + sequential_second;
          const double concurrent_round =
              static_cast<double>(concurrent_first) + concurrent_second;
          round_speedup = sequential_round / concurrent_round;
          sequential_total += sequential_round;
          concurrent_total += concurrent_round;
          minimum_round_speedup =
              std::min(minimum_round_speedup, round_speedup);
          maximum_round_speedup =
              std::max(maximum_round_speedup, round_speedup);
          winning_rounds += round_speedup >= 1.0 ? 1 : 0;
        }
        std::cout << "PERF_NVFP4_M17_M32_DUAL_STREAM_ROUND: M="
                  << token_count << " distribution=" << distribution_name
                  << " round=" << round + 1
                  << " sequential_pass1_ms=" << sequential_first
                  << " concurrent_pass1_ms=" << concurrent_first
                  << " concurrent_pass2_ms=" << concurrent_second
                  << " sequential_pass2_ms=" << sequential_second
                  << " round_speedup=" << round_speedup << '\n';
      }
      constexpr double kTimedPasses =
          2.0 * static_cast<double>(kMeasurementRounds);
      if (timings_finite) {
        measurement.sequential_milliseconds =
            sequential_total / kTimedPasses;
        measurement.concurrent_milliseconds =
            concurrent_total / kTimedPasses;
        measurement.minimum_round_speedup = minimum_round_speedup;
        measurement.maximum_round_speedup = maximum_round_speedup;
      }
      measurement.timings_finite = timings_finite;
      measurement.winning_rounds = winning_rounds;
      const double speedup = measurement.sequential_milliseconds /
                             measurement.concurrent_milliseconds;
      const double required_cell_speedup =
          token_count == kMaximumTokens ? kRequiredM32RetentionSpeedup
                                        : kRequiredGeneralizationSpeedup;
      const bool cell_gate =
          measurement.correctness && measurement.timings_finite &&
          std::isfinite(speedup) && speedup >= required_cell_speedup &&
          measurement.winning_rounds == kMeasurementRounds &&
          measurement.minimum_round_speedup >= kMinimumRoundSpeedup;
      measurement.promotion_gate = cell_gate;
      std::cout << "PERF_NVFP4_M17_M32_DUAL_STREAM_CELL: M="
                << token_count << " distribution=" << distribution_name
                << " sequential_ms="
                << measurement.sequential_milliseconds
                << " concurrent_ms="
                << measurement.concurrent_milliseconds
                << " speedup=" << speedup
                << " required_cell_speedup=" << required_cell_speedup
                << " winning_rounds=" << measurement.winning_rounds << '/'
                << kMeasurementRounds
                << " required_winning_rounds=" << kMeasurementRounds
                << " minimum_round_speedup="
                << measurement.minimum_round_speedup
                << " required_minimum_round_speedup="
                << kMinimumRoundSpeedup
                << " maximum_round_speedup="
                << measurement.maximum_round_speedup
                << " promotion_gate=" << (cell_gate ? "PASS" : "FAIL")
                << '\n';
      test.expect(measurement.timings_finite,
                  cell_label + " produces finite positive ABBA timings");
      test.expect(cell_gate,
                  cell_label +
                      " clears its speedup and all-round promotion gate");
    }
    if (!ready) {
      break;
    }
  }

  double aggregate_sequential = 0.0;
  double aggregate_concurrent = 0.0;
  bool all_per_m_gates_pass = ready;
  std::size_t passed_m_count = 0U;
  for (std::size_t token_index = first_token_index;
       token_index < kTokenCounts.size(); ++token_index) {
    const std::size_t token_count = kTokenCounts[token_index];
    double per_m_sequential = 0.0;
    double per_m_concurrent = 0.0;
    double minimum_cell_speedup =
        std::numeric_limits<double>::infinity();
    bool all_cells_valid = true;
    bool all_cell_gates_pass = true;
    for (std::size_t distribution_index = 0U;
         distribution_index < kNvFp4M16K128ScaleDistributions.size();
         ++distribution_index) {
      const CellMeasurement& measurement =
          measurements[token_index][distribution_index];
      const double cell_speedup = measurement.sequential_milliseconds /
                                  measurement.concurrent_milliseconds;
      const bool cell_valid =
          measurement.correctness && measurement.timings_finite &&
          std::isfinite(cell_speedup) &&
          measurement.sequential_milliseconds > 0.0 &&
          measurement.concurrent_milliseconds > 0.0;
      all_cells_valid = all_cells_valid && cell_valid;
      all_cell_gates_pass =
          all_cell_gates_pass && measurement.promotion_gate;
      if (cell_valid) {
        per_m_sequential += measurement.sequential_milliseconds;
        per_m_concurrent += measurement.concurrent_milliseconds;
        minimum_cell_speedup =
            std::min(minimum_cell_speedup, cell_speedup);
      }
    }
    const double per_m_speedup = per_m_sequential / per_m_concurrent;
    const double required_per_m_speedup =
        token_count == kMaximumTokens ? kRequiredM32RetentionSpeedup
                                      : kRequiredGeneralizationSpeedup;
    const bool per_m_gate =
        all_cells_valid && all_cell_gates_pass &&
        std::isfinite(per_m_speedup) &&
        per_m_speedup >= required_per_m_speedup;
    all_per_m_gates_pass = all_per_m_gates_pass && per_m_gate;
    const bool included_in_aggregate =
        !full_sweep || token_count != kMaximumTokens;
    if (included_in_aggregate) {
      passed_m_count += per_m_gate ? 1U : 0U;
      aggregate_sequential += per_m_sequential;
      aggregate_concurrent += per_m_concurrent;
    }
    std::cout << "PERF_NVFP4_M17_M32_DUAL_STREAM_PER_M: M="
              << token_count << " sequential_ms=" << per_m_sequential
              << " concurrent_ms=" << per_m_concurrent
              << " speedup=" << per_m_speedup
              << " required_speedup=" << required_per_m_speedup
              << " minimum_cell_speedup=" << minimum_cell_speedup
              << " required_cell_speedup=" << required_per_m_speedup
              << " aggregate_scope="
              << (included_in_aggregate ? "included" : "m32_control")
              << " all_cell_gates="
              << (all_cell_gates_pass ? "PASS" : "FAIL")
              << " distributions=checkpoint_like:same_bank_stress"
              << " promotion_gate=" << (per_m_gate ? "PASS" : "FAIL")
              << '\n';
    test.expect(per_m_gate,
                "NVFP4 M" + std::to_string(token_count) +
                    " gate/up dual stream clears its per-M promotion gate");
  }

  const std::size_t tested_m_count =
      full_sweep ? kTokenCounts.size() - 1U : 1U;
  const double required_aggregate_speedup =
      full_sweep ? kRequiredGeneralizationSpeedup
                 : kRequiredM32RetentionSpeedup;
  const double aggregate_speedup =
      aggregate_sequential / aggregate_concurrent;
  const bool aggregate_gate =
      all_per_m_gates_pass && std::isfinite(aggregate_speedup) &&
      aggregate_speedup >= required_aggregate_speedup;
  std::cout << "PERF_NVFP4_M17_M32_DUAL_STREAM_AGGREGATE: sequential_ms="
            << aggregate_sequential
            << " concurrent_ms=" << aggregate_concurrent
            << " speedup=" << aggregate_speedup
            << " required_speedup=" << required_aggregate_speedup
            << " passed_m=" << passed_m_count << '/' << tested_m_count
            << " aggregate_scope="
            << (full_sweep ? "M17-M31_with_M32_control" : "M32_retention")
            << " distributions=checkpoint_like:same_bank_stress"
            << " promotion_gate=" << (aggregate_gate ? "PASS" : "FAIL")
            << '\n';
  test.expect(
      aggregate_gate,
      full_sweep
          ? "NVFP4 M17-M31 gate/up dual-stream candidate clears every "
            "per-M gate, the aggregate promotion gate, and the M32 control"
          : "NVFP4 M32 production dual stream clears its retention gate");

  (void)test.cuda_ok(cudaStreamSynchronize(stream),
                     "dual stream final primary synchronize");
  (void)test.cuda_ok(cudaStreamSynchronize(auxiliary_stream),
                     "dual stream final auxiliary synchronize");
  (void)test.cuda_ok(cudaEventDestroy(inputs_ready),
                     "dual stream destroy input-ready event");
  (void)test.cuda_ok(cudaEventDestroy(auxiliary_done),
                     "dual stream destroy auxiliary-done event");
  (void)test.cuda_ok(cudaStreamDestroy(auxiliary_stream),
                     "dual stream destroy auxiliary stream");
}

constexpr std::array<std::size_t, 6U> kNvFp4GridCaps{{
    96U, 192U, 384U, 768U, 1'024U, 2'048U,
}};

constexpr std::array<NvFp4M1ScaleDistribution, 2U>
    kNvFp4GridCapScaleDistributions{{
        NvFp4M1ScaleDistribution::kCheckpointLike,
        NvFp4M1ScaleDistribution::kSameBankStress,
    }};

struct NvFp4M1GridCapMeasurements {
  std::array<std::array<float, kNvFp4GridCaps.size()>,
             kNvFp4GridCapScaleDistributions.size()>
      baseline_milliseconds{};
  std::array<std::array<float, kNvFp4GridCaps.size()>,
             kNvFp4GridCapScaleDistributions.size()>
      candidate_milliseconds{};
  std::array<std::array<bool, kNvFp4GridCaps.size()>,
             kNvFp4GridCapScaleDistributions.size()>
      bitwise_equal{};
};

struct NvFp4M1GridCapShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  const char* label;
};

[[nodiscard]] NvFp4M1GridCapMeasurements benchmark_nvfp4_m1_grid_cap_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  const int warmup_iterations = rows >= 100'000U ? 4 : 10;
  const int measured_iterations = rows >= 100'000U ? 10 : 24;
  const std::size_t packed_count = rows * columns / 2U;
  const std::size_t scale_columns = columns / 16U;
  const std::size_t scale_count = rows * scale_columns;

  NvFp4M1GridCapMeasurements measurements{};
  for (auto& distribution : measurements.baseline_milliseconds) {
    distribution.fill(std::numeric_limits<float>::quiet_NaN());
  }
  for (auto& distribution : measurements.candidate_milliseconds) {
    distribution.fill(std::numeric_limits<float>::quiet_NaN());
  }

  std::vector<std::uint8_t> host_scales(scale_count);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered =
        static_cast<int>((column * 13U + 3U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(packed.allocate(packed_count),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(scale_count),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activations.allocate(host_activation.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(
                       baseline_output.allocate(rows),
                       label + " allocate baseline output");
  ready = ready && test.cuda_ok(
                       candidate_output.allocate(rows),
                       label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(packed.get(), 0x21, packed_count,
                                       stream),
                       label + " initialize packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed activations");
  if (!ready) {
    return measurements;
  }

  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4GridCapScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4GridCapScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                     distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize block scales");
    if (!ready) {
      return measurements;
    }

    const auto launch_baseline = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activations.get(),
              rows, columns, baseline_output.get(),
              static_cast<void*>(stream));
    };

    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         distribution_label +
                             " correctness uncapped baseline");
    std::vector<std::uint16_t> baseline(rows);
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy uncapped baseline");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " baseline synchronize");
    if (!ready) {
      return measurements;
    }

    for (std::size_t cap_index = 0U; cap_index < kNvFp4GridCaps.size();
         ++cap_index) {
      const std::size_t grid_cap = kNvFp4GridCaps[cap_index];
      const auto launch_candidate = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_grid_cap_test_cuda(
                packed.get(), scales.get(), kWeightScale2,
                activations.get(), rows, columns, candidate_output.get(),
                grid_cap, static_cast<void*>(stream));
      };

      ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_candidate()),
          distribution_label + " correctness capped candidate cap=" +
              std::to_string(grid_cap));
      std::vector<std::uint16_t> candidate(rows);
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               candidate.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           distribution_label + " copy candidate cap=" +
                               std::to_string(grid_cap));
      ready = ready && test.cuda_ok(
                           cudaStreamSynchronize(stream),
                           distribution_label + " correctness synchronize cap=" +
                               std::to_string(grid_cap));
      if (!ready) {
        return measurements;
      }
      std::size_t mismatches = 0U;
      for (std::size_t index = 0U; index < baseline.size(); ++index) {
        mismatches += baseline[index] != candidate[index] ? 1U : 0U;
      }
      measurements.bitwise_equal[distribution_index][cap_index] =
          mismatches == 0U;
      std::cout << "NVFP4_M1_GRID_CAP_DIFF: " << label << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " grid_cap=" << grid_cap
                << " candidate_vs_uncapped_bf16=" << mismatches << '/'
                << baseline.size() << '\n';
      test.expect(mismatches == 0U,
                  distribution_label + " cap=" + std::to_string(grid_cap) +
                      " matches every uncapped BF16 bit");

      for (int iteration = 0; iteration < warmup_iterations && ready;
           ++iteration) {
        ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                             distribution_label + " baseline warmup");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_candidate()),
                             distribution_label + " candidate warmup cap=" +
                                 std::to_string(grid_cap));
      }
      ready = ready && test.cuda_ok(
                           cudaStreamSynchronize(stream),
                           distribution_label + " warmup synchronize cap=" +
                               std::to_string(grid_cap));
      if (!ready) {
        return measurements;
      }

      double baseline_total = 0.0;
      double candidate_total = 0.0;
      bool finite = true;
      for (int round = 0; round < kMeasurementRounds; ++round) {
        const std::string suffix =
            " cap=" + std::to_string(grid_cap) +
            " round=" + std::to_string(round + 1);
        const float baseline_first = measure_small_m_tile(
            test, stream, launch_baseline, measured_iterations,
            distribution_label + " baseline pass 1" + suffix);
        const float candidate_first = measure_small_m_tile(
            test, stream, launch_candidate, measured_iterations,
            distribution_label + " candidate pass 1" + suffix);
        const float candidate_second = measure_small_m_tile(
            test, stream, launch_candidate, measured_iterations,
            distribution_label + " candidate pass 2" + suffix);
        const float baseline_second = measure_small_m_tile(
            test, stream, launch_baseline, measured_iterations,
            distribution_label + " baseline pass 2" + suffix);
        const bool round_finite =
            std::isfinite(baseline_first) &&
            std::isfinite(candidate_first) &&
            std::isfinite(candidate_second) &&
            std::isfinite(baseline_second);
        finite = finite && round_finite;
        if (round_finite) {
          baseline_total += baseline_first + baseline_second;
          candidate_total += candidate_first + candidate_second;
        }
        std::cout << "PERF_NVFP4_M1_GRID_CAP_ROUND: " << label
                  << " distribution="
                  << nvfp4_m1_scale_distribution_name(distribution)
                  << " grid_cap=" << grid_cap << " round=" << round + 1
                  << " baseline_pass1_ms=" << baseline_first
                  << " candidate_pass1_ms=" << candidate_first
                  << " candidate_pass2_ms=" << candidate_second
                  << " baseline_pass2_ms=" << baseline_second << '\n';
      }
      if (!finite) {
        return measurements;
      }
      constexpr double kTimedPasses =
          2.0 * static_cast<double>(kMeasurementRounds);
      const float baseline_average =
          static_cast<float>(baseline_total / kTimedPasses);
      const float candidate_average =
          static_cast<float>(candidate_total / kTimedPasses);
      measurements.baseline_milliseconds[distribution_index][cap_index] =
          baseline_average;
      measurements.candidate_milliseconds[distribution_index][cap_index] =
          candidate_average;
      const float speedup = baseline_average / candidate_average;
      std::cout << "PERF_NVFP4_M1_GRID_CAP: " << label << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " grid_cap=" << grid_cap
                << " baseline_average_ms=" << baseline_average
                << " candidate_average_ms=" << candidate_average
                << " speedup=" << speedup
                << " uplift_percent=" << (speedup - 1.0F) * 100.0F
                << '\n';
    }
  }
  return measurements;
}

template <std::size_t ShapeCount>
[[nodiscard]] std::size_t select_nvfp4_m1_grid_cap(
    TestContext& test,
    const std::array<NvFp4M1GridCapShape, ShapeCount>& shapes,
    const std::array<NvFp4M1GridCapMeasurements, ShapeCount>& measurements,
    const std::size_t frozen_cap_index) {
  constexpr float kMinimumWeightedSpeedup = 1.03F;
  constexpr float kMinimumPerShapeSpeedup = 0.98F;
  std::array<bool, kNvFp4GridCaps.size()> aggregate_gates{};
  std::array<double, kNvFp4GridCaps.size()> weighted_speedups{};
  std::size_t selected_cap_index = kNvFp4GridCaps.size();
  double selected_weighted_speedup = 0.0;
  for (std::size_t cap_index = 0U; cap_index < kNvFp4GridCaps.size();
       ++cap_index) {
    double weighted_baseline = 0.0;
    double weighted_candidate = 0.0;
    bool all_finite = true;
    bool all_bitwise = true;
    bool no_shape_regression = true;
    for (std::size_t shape_index = 0U; shape_index < ShapeCount;
         ++shape_index) {
      for (std::size_t distribution_index = 0U;
           distribution_index < kNvFp4GridCapScaleDistributions.size();
           ++distribution_index) {
        const float baseline = measurements[shape_index]
                                   .baseline_milliseconds[distribution_index]
                                                         [cap_index];
        const float candidate = measurements[shape_index]
                                    .candidate_milliseconds[distribution_index]
                                                          [cap_index];
        const bool finite =
            std::isfinite(baseline) && std::isfinite(candidate);
        const float speedup = baseline / candidate;
        all_finite = all_finite && finite;
        all_bitwise = all_bitwise &&
                      measurements[shape_index]
                          .bitwise_equal[distribution_index][cap_index];
        no_shape_regression = no_shape_regression && finite &&
                              speedup >= kMinimumPerShapeSpeedup;
        if (distribution_index == 0U) {
          weighted_baseline +=
              static_cast<double>(shapes[shape_index].profile_calls) *
              baseline;
          weighted_candidate +=
              static_cast<double>(shapes[shape_index].profile_calls) *
              candidate;
        }
        std::cout << "PERF_NVFP4_M1_GRID_CAP_VALIDATION: "
                  << shapes[shape_index].label
                  << " distribution="
                  << nvfp4_m1_scale_distribution_name(
                         kNvFp4GridCapScaleDistributions[distribution_index])
                  << " grid_cap=" << kNvFp4GridCaps[cap_index]
                  << " baseline_ms=" << baseline
                  << " candidate_ms=" << candidate
                  << " speedup=" << speedup
                  << " minimum_speedup=" << kMinimumPerShapeSpeedup
                  << " gate="
                  << (finite && speedup >= kMinimumPerShapeSpeedup ? "PASS"
                                                                    : "FAIL")
                  << '\n';
      }
    }
    const double weighted_speedup = weighted_baseline / weighted_candidate;
    const bool aggregate_gate =
        all_finite && all_bitwise && no_shape_regression &&
        std::isfinite(weighted_speedup) &&
        weighted_speedup >= kMinimumWeightedSpeedup;
    aggregate_gates[cap_index] = aggregate_gate;
    weighted_speedups[cap_index] = weighted_speedup;
    std::cout << "PERF_NVFP4_M1_GRID_CAP_AGGREGATE: grid_cap="
              << kNvFp4GridCaps[cap_index]
              << " checkpoint_weighted_baseline_ms=" << weighted_baseline
              << " checkpoint_weighted_candidate_ms=" << weighted_candidate
              << " speedup=" << weighted_speedup
              << " required_speedup=" << kMinimumWeightedSpeedup
              << " all_bitwise=" << (all_bitwise ? "true" : "false")
              << " no_shape_regression="
              << (no_shape_regression ? "true" : "false")
              << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
    if (aggregate_gate && weighted_speedup > selected_weighted_speedup) {
      selected_cap_index = cap_index;
      selected_weighted_speedup = weighted_speedup;
    }
  }
  if (frozen_cap_index < kNvFp4GridCaps.size()) {
    const bool frozen_gate = aggregate_gates[frozen_cap_index];
    selected_cap_index =
        frozen_gate ? frozen_cap_index : kNvFp4GridCaps.size();
    selected_weighted_speedup = weighted_speedups[frozen_cap_index];
    test.expect(frozen_gate,
                "NVFP4 M1 frozen grid cap=" +
                    std::to_string(kNvFp4GridCaps[frozen_cap_index]) +
                    " passes every production gate");
    std::cout << "PERF_NVFP4_M1_GRID_CAP_SELECTED: grid_cap="
              << kNvFp4GridCaps[frozen_cap_index]
              << " weighted_speedup=" << selected_weighted_speedup
              << " gate=" << (frozen_gate ? "PASS" : "FAIL") << '\n';
    return selected_cap_index;
  }
  return kNvFp4GridCaps.size();
}

void run_nvfp4_m1_large_row_grid_stride_coverage(
    TestContext& test, cudaStream_t stream, const std::size_t grid_cap) {
  constexpr std::size_t kRows = 65'537U;
  constexpr std::size_t kColumns = 256U;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  const std::string label = "NVFP4 M1 grid-cap >65535-row coverage";
  constexpr std::size_t kPackedColumns = kColumns / 2U;
  constexpr std::size_t kScaleColumns = kColumns / 16U;
  std::vector<std::uint8_t> host_scales(kRows * kScaleColumns);
  fill_nvfp4_m1_scale_distribution(
      host_scales, kScaleColumns,
      NvFp4M1ScaleDistribution::kCheckpointLike);
  std::vector<std::uint16_t> host_activation(
      kColumns, encode_bf16(1.0F / 256.0F));

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activations;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(packed.allocate(kRows * kPackedColumns),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activations.allocate(host_activation.size()),
                                label + " allocate activations");
  ready = ready && test.cuda_ok(
                       baseline_output.allocate(kRows),
                       label + " allocate baseline output");
  ready = ready && test.cuda_ok(
                       candidate_output.allocate(kRows),
                       label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(packed.get(), 0x21,
                                       kRows * kPackedColumns, stream),
                       label + " initialize packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(scales.get(), host_scales.data(),
                                       host_scales.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " initialize block scales");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activations.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activations");
  if (!ready) {
    return;
  }

  const auto launch_baseline = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            kRows, kColumns, baseline_output.get(),
            static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_grid_cap_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activations.get(),
            kRows, kColumns, candidate_output.get(), grid_cap,
            static_cast<void*>(stream));
  };
  ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                       label + " launch uncapped baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " launch capped candidate");
  std::vector<std::uint16_t> baseline(kRows);
  std::vector<std::uint16_t> candidate(kRows);
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_output.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy baseline output");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_output.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy candidate output");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " synchronize");
  if (!ready) {
    return;
  }
  std::size_t mismatches = 0U;
  for (std::size_t index = 0U; index < baseline.size(); ++index) {
    mismatches += baseline[index] != candidate[index] ? 1U : 0U;
  }
  std::cout << "NVFP4_M1_GRID_CAP_LARGE_ROWS_DIFF: grid_cap=" << grid_cap
            << " candidate_vs_uncapped_bf16=" << mismatches << '/'
            << baseline.size() << '\n';
  test.expect(mismatches == 0U,
              label + " covers every row with identical BF16 output");
}

void run_optional_nvfp4_m1_grid_cap_performance(TestContext& test,
                                                 cudaStream_t stream) {
  if (!nvfp4_m1_grid_cap_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M1 persistent-row grid-cap segment; set "
                 "Q3X_RUN_SM87_NVFP4_M1_GRID_CAP_PERF=1 to enable\n";
    return;
  }
  constexpr std::array<NvFp4M1GridCapShape, 3U> kShapes{{
      {17'408U, 5'120U, 256U, "NVFP4 M1 MLP gate/up 17408x5120"},
      {5'120U, 17'408U, 128U, "NVFP4 M1 MLP down 5120x17408"},
      {248'320U, 5'120U, 2U, "NVFP4 M1 lm_head 248320x5120"},
  }};
  std::array<NvFp4M1GridCapMeasurements, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_nvfp4_m1_grid_cap_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }
  const std::size_t production_cap =
      q3x::kernels::sm87_nvfp4_m1_persistent_maximum_blocks_test();
  std::size_t production_cap_index = kNvFp4GridCaps.size();
  for (std::size_t cap_index = 0U; cap_index < kNvFp4GridCaps.size();
       ++cap_index) {
    if (kNvFp4GridCaps[cap_index] == production_cap) {
      production_cap_index = cap_index;
      break;
    }
  }
  const bool production_cap_is_measured =
      production_cap_index < kNvFp4GridCaps.size();
  test.expect(production_cap_is_measured,
              "NVFP4 M1 production grid cap is present in the sweep");
  if (!production_cap_is_measured) {
    return;
  }
  const std::size_t selected_cap_index =
      select_nvfp4_m1_grid_cap(test, kShapes, measurements,
                              production_cap_index);
  if (selected_cap_index < kNvFp4GridCaps.size()) {
    run_nvfp4_m1_large_row_grid_stride_coverage(
        test, stream, kNvFp4GridCaps[selected_cap_index]);
  }
}

constexpr std::array<std::size_t, 3U> kNvFp4M1RowPairGridCaps{{
    64U,
    80U,
    96U,
}};

constexpr std::array<NvFp4M1ScaleDistribution, 2U>
    kNvFp4M1RowPairScaleDistributions{{
        NvFp4M1ScaleDistribution::kCheckpointLike,
        NvFp4M1ScaleDistribution::kSameBankStress,
    }};

struct NvFp4M1RowPairDistributionMeasurement {
  std::array<float, kNvFp4M1RowPairGridCaps.size()>
      baseline_milliseconds{};
  std::array<float, kNvFp4M1RowPairGridCaps.size()>
      candidate_milliseconds{};
  std::array<bool, kNvFp4M1RowPairGridCaps.size()> bitwise_equal{};
};

struct NvFp4M1RowPairMeasurement {
  std::array<NvFp4M1RowPairDistributionMeasurement,
             kNvFp4M1RowPairScaleDistributions.size()>
      distributions{};
};

struct NvFp4M1RowPairShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  const char* label;
};

[[nodiscard]] NvFp4M1RowPairMeasurement
benchmark_nvfp4_m1_row_pair_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kProductionGridCap = 96U;
  constexpr int kWarmupIterations = 10;
  constexpr int kDefaultMeasuredIterations = 40;
  constexpr int kLmHeadMeasuredIterations = 10;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  const int measured_iterations =
      rows >= 100'000U ? kLmHeadMeasuredIterations
                       : kDefaultMeasuredIterations;
  const std::size_t packed_count = rows * columns / 2U;
  const std::size_t scale_columns = columns / 16U;
  std::vector<std::uint8_t> host_scales(rows * scale_columns);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered =
        static_cast<int>((column * 17U + 5U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  NvFp4M1RowPairMeasurement measurement;
  for (NvFp4M1RowPairDistributionMeasurement& distribution :
       measurement.distributions) {
    distribution.baseline_milliseconds.fill(
        std::numeric_limits<float>::quiet_NaN());
    distribution.candidate_milliseconds.fill(
        std::numeric_limits<float>::quiet_NaN());
  }

  test.expect(
      q3x::kernels::sm87_nvfp4_m1_persistent_maximum_blocks_test() ==
          kProductionGridCap,
      label + " performance baseline is the frozen production cap96");

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(packed.allocate(packed_count),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(rows),
                                label + " allocate candidate output");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(packed.get(), 0x21, packed_count,
                                       stream),
                       label + " initialize packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed activation");
  if (!ready) {
    return measurement;
  }

  std::vector<std::uint16_t> baseline(rows);
  std::vector<std::uint16_t> candidate(rows);
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M1RowPairScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M1RowPairScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                     distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize block scales");
    if (!ready) {
      return measurement;
    }

    for (std::size_t cap_index = 0U;
         cap_index < kNvFp4M1RowPairGridCaps.size(); ++cap_index) {
      const std::size_t candidate_grid_cap =
          kNvFp4M1RowPairGridCaps[cap_index];
      const std::string cap_label =
          distribution_label + " candidate_cap=" +
          std::to_string(candidate_grid_cap);
      const auto launch_baseline = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_grid_cap_test_cuda(
                packed.get(), scales.get(), kWeightScale2, activation.get(),
                rows, columns, baseline_output.get(), kProductionGridCap,
                static_cast<void*>(stream));
      };
      const auto launch_candidate = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_row_pair_grid_cap_test_cuda(
                packed.get(), scales.get(), kWeightScale2, activation.get(),
                rows, columns, candidate_output.get(), candidate_grid_cap,
                static_cast<void*>(stream));
      };
      const auto launch_public = [&]() noexcept -> int {
        return q3x::kernels::launch_sm87_nvfp4_w4a16_gemv_bf16_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
            columns, baseline_output.get(), static_cast<void*>(stream));
      };

      ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_baseline()),
          cap_label + " correctness preserved production cap96 baseline");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           cap_label + " correctness direct row-pair");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               baseline.data(), baseline_output.get(),
                               baseline.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy baseline output");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               candidate.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy candidate output");
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " correctness synchronize");
      if (!ready) {
        return measurement;
      }

      std::size_t mismatches = 0U;
      for (std::size_t row = 0U; row < rows; ++row) {
        mismatches += baseline[row] != candidate[row] ? 1U : 0U;
      }
      NvFp4M1RowPairDistributionMeasurement& distribution_measurement =
          measurement.distributions[distribution_index];
      distribution_measurement.bitwise_equal[cap_index] = mismatches == 0U;
      std::cout << "NVFP4_M1_ROW_PAIR_PERF_DIFF: " << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " baseline_cap=" << kProductionGridCap
                << " candidate_cap=" << candidate_grid_cap
                << " mismatches=" << mismatches << '/' << rows << '\n';
      test.expect(
          distribution_measurement.bitwise_equal[cap_index],
          cap_label +
              " row-pair matches every preserved production BF16 bit");

      const std::size_t preserved_row_pair_cap =
          q3x::kernels::sm87_nvfp4_m1_row_pair_maximum_blocks_test();
      if (candidate_grid_cap == preserved_row_pair_cap) {
        ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_public()),
            cap_label + " launch public production dispatch");
        ready = ready && test.cuda_ok(
                             cudaMemcpyAsync(
                                 baseline.data(), baseline_output.get(),
                                 baseline.size() * sizeof(std::uint16_t),
                                 cudaMemcpyDeviceToHost, stream),
                             cap_label + " copy public production output");
        ready = ready && test.cuda_ok(
                             cudaStreamSynchronize(stream),
                             cap_label + " public production synchronize");
        if (!ready) {
          return measurement;
        }
        std::size_t public_mismatches = 0U;
        for (std::size_t row = 0U; row < rows; ++row) {
          public_mismatches += baseline[row] != candidate[row] ? 1U : 0U;
        }
        std::cout << "NVFP4_M1_ROW_PAIR_PUBLIC_COMPAT_DIFF: " << label
                  << " distribution="
                  << nvfp4_m1_scale_distribution_name(distribution)
                  << " public_vs_preserved_pair_cap="
                  << preserved_row_pair_cap
                  << " mismatches=" << public_mismatches << '/' << rows
                  << '\n';
        test.expect(
            public_mismatches == 0U,
            cap_label +
                " public row-quad remains bitwise-compatible with row-pair");
      }

      for (int iteration = 0; iteration < kWarmupIterations && ready;
           ++iteration) {
        ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                             cap_label + " baseline warmup");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_candidate()),
                             cap_label + " candidate warmup");
      }
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " warmup synchronize");
      if (!ready) {
        return measurement;
      }

      double baseline_total = 0.0;
      double candidate_total = 0.0;
      bool all_finite = true;
      for (int round = 0; round < kMeasurementRounds; ++round) {
        const std::string round_label =
            cap_label + " round=" + std::to_string(round + 1);
        const float baseline_first = measure_small_m_tile(
            test, stream, launch_baseline, measured_iterations,
            round_label + " baseline pass 1");
        const float candidate_first = measure_small_m_tile(
            test, stream, launch_candidate, measured_iterations,
            round_label + " candidate pass 1");
        const float candidate_second = measure_small_m_tile(
            test, stream, launch_candidate, measured_iterations,
            round_label + " candidate pass 2");
        const float baseline_second = measure_small_m_tile(
            test, stream, launch_baseline, measured_iterations,
            round_label + " baseline pass 2");
        const bool round_finite =
            std::isfinite(baseline_first) &&
            std::isfinite(candidate_first) &&
            std::isfinite(candidate_second) &&
            std::isfinite(baseline_second);
        all_finite = all_finite && round_finite;
        if (round_finite) {
          baseline_total += baseline_first + baseline_second;
          candidate_total += candidate_first + candidate_second;
        }
        std::cout << "PERF_NVFP4_M1_ROW_PAIR_ROUND: " << label
                  << " distribution="
                  << nvfp4_m1_scale_distribution_name(distribution)
                  << " baseline_cap=" << kProductionGridCap
                  << " candidate_cap=" << candidate_grid_cap
                  << " measured_iterations=" << measured_iterations
                  << " round=" << round + 1
                  << " baseline_pass1_ms=" << baseline_first
                  << " candidate_pass1_ms=" << candidate_first
                  << " candidate_pass2_ms=" << candidate_second
                  << " baseline_pass2_ms=" << baseline_second << '\n';
      }
      constexpr double kTimedPasses =
          2.0 * static_cast<double>(kMeasurementRounds);
      distribution_measurement.baseline_milliseconds[cap_index] =
          all_finite
              ? static_cast<float>(baseline_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      distribution_measurement.candidate_milliseconds[cap_index] =
          all_finite
              ? static_cast<float>(candidate_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      const float speedup =
          distribution_measurement.baseline_milliseconds[cap_index] /
          distribution_measurement.candidate_milliseconds[cap_index];
      std::cout << "PERF_NVFP4_M1_ROW_PAIR: " << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " preserved_production_cap96_ms="
                << distribution_measurement
                       .baseline_milliseconds[cap_index]
                << " candidate_cap=" << candidate_grid_cap
                << " direct_row_pair_ms="
                << distribution_measurement
                       .candidate_milliseconds[cap_index]
                << " speedup=" << speedup << " bitwise_mismatches="
                << mismatches << '/' << rows << '\n';
    }
  }
  return measurement;
}

void run_optional_nvfp4_m1_row_pair_performance(TestContext& test,
                                                 cudaStream_t stream) {
  if (!nvfp4_m1_row_pair_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M1 scale-codebook row-pair performance "
                 "segment; set Q3X_RUN_SM87_NVFP4_M1_ROW_PAIR_PERF=1 to "
                 "enable\n";
    return;
  }
  constexpr float kMinimumCheckpointShapeSpeedup = 1.02F;
  constexpr float kMinimumStressShapeSpeedup = 0.99F;
  constexpr float kMinimumCheckpointWeightedSpeedup = 1.05F;
  constexpr std::array<NvFp4M1RowPairShape, 3U> kShapes{{
      {17'408U, 5'120U, 128U, "NVFP4 M1 row-pair 17408x5120"},
      {5'120U, 17'408U, 64U, "NVFP4 M1 row-pair 5120x17408"},
      {248'320U, 5'120U, 1U, "NVFP4 M1 row-pair lm_head 248320x5120"},
  }};

  std::array<NvFp4M1RowPairMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_nvfp4_m1_row_pair_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }

  std::size_t selected_cap_index = kNvFp4M1RowPairGridCaps.size();
  double selected_weighted_speedup = 0.0;
  std::array<double, kNvFp4M1RowPairGridCaps.size()> weighted_speedups{};
  std::array<bool, kNvFp4M1RowPairGridCaps.size()> aggregate_gates{};
  for (std::size_t cap_index = 0U;
       cap_index < kNvFp4M1RowPairGridCaps.size(); ++cap_index) {
    bool all_shape_distributions_pass = true;
    double checkpoint_weighted_baseline = 0.0;
    double checkpoint_weighted_candidate = 0.0;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      for (std::size_t distribution_index = 0U;
           distribution_index < kNvFp4M1RowPairScaleDistributions.size();
           ++distribution_index) {
        const NvFp4M1RowPairDistributionMeasurement& measurement =
            measurements[shape_index].distributions[distribution_index];
        const float baseline =
            measurement.baseline_milliseconds[cap_index];
        const float candidate =
            measurement.candidate_milliseconds[cap_index];
        const float speedup = baseline / candidate;
        const bool finite = std::isfinite(baseline) &&
                            std::isfinite(candidate) &&
                            std::isfinite(speedup) && baseline > 0.0F &&
                            candidate > 0.0F;
        const bool checkpoint_distribution =
            kNvFp4M1RowPairScaleDistributions[distribution_index] ==
            NvFp4M1ScaleDistribution::kCheckpointLike;
        const float required_speedup =
            checkpoint_distribution
                ? kMinimumCheckpointShapeSpeedup
                : kMinimumStressShapeSpeedup;
        const bool gate = measurement.bitwise_equal[cap_index] && finite &&
                          speedup >= required_speedup;
        all_shape_distributions_pass =
            all_shape_distributions_pass && gate;
        std::cout << "PERF_NVFP4_M1_ROW_PAIR_VALIDATION: "
                  << kShapes[shape_index].label << " distribution="
                  << nvfp4_m1_scale_distribution_name(
                         kNvFp4M1RowPairScaleDistributions
                             [distribution_index])
                  << " baseline_cap=96 candidate_cap="
                  << kNvFp4M1RowPairGridCaps[cap_index]
                  << " baseline_ms=" << baseline
                  << " candidate_ms=" << candidate
                  << " speedup=" << speedup
                  << " required_speedup=" << required_speedup
                  << " bitwise="
                  << (measurement.bitwise_equal[cap_index] ? "true"
                                                           : "false")
                  << " gate=" << (gate ? "PASS" : "FAIL") << '\n';
      }
      const NvFp4M1RowPairDistributionMeasurement& checkpoint =
          measurements[shape_index].distributions[0U];
      checkpoint_weighted_baseline +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          checkpoint.baseline_milliseconds[cap_index];
      checkpoint_weighted_candidate +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          checkpoint.candidate_milliseconds[cap_index];
    }

    const double checkpoint_weighted_speedup =
        checkpoint_weighted_baseline / checkpoint_weighted_candidate;
    const bool aggregate_gate =
        all_shape_distributions_pass &&
        std::isfinite(checkpoint_weighted_speedup) &&
        checkpoint_weighted_baseline > 0.0 &&
        checkpoint_weighted_candidate > 0.0 &&
        checkpoint_weighted_speedup >=
            kMinimumCheckpointWeightedSpeedup;
    weighted_speedups[cap_index] = checkpoint_weighted_speedup;
    aggregate_gates[cap_index] = aggregate_gate;
    std::cout << "PERF_NVFP4_M1_ROW_PAIR_AGGREGATE: baseline_cap=96"
              << " candidate_cap="
              << kNvFp4M1RowPairGridCaps[cap_index]
              << " checkpoint_weighted_baseline_ms="
              << checkpoint_weighted_baseline
              << " checkpoint_weighted_candidate_ms="
              << checkpoint_weighted_candidate
              << " speedup=" << checkpoint_weighted_speedup
              << " required_speedup="
              << kMinimumCheckpointWeightedSpeedup
              << " profile_calls=128:64:1 all_shape_distributions="
              << (all_shape_distributions_pass ? "PASS" : "FAIL")
              << " gate=" << (aggregate_gate ? "PASS" : "FAIL") << '\n';
    if (aggregate_gate &&
        checkpoint_weighted_speedup > selected_weighted_speedup) {
      selected_cap_index = cap_index;
      selected_weighted_speedup = checkpoint_weighted_speedup;
    }
  }

  const bool selected =
      selected_cap_index < kNvFp4M1RowPairGridCaps.size();
  test.expect(selected,
              "NVFP4 M1 row-pair sweep selects a cap clearing every gate");
  if (!selected) {
    std::cout << "PERF_NVFP4_M1_ROW_PAIR_SELECTED: gate=FAIL\n";
    return;
  }
  std::cout << "PERF_NVFP4_M1_ROW_PAIR_SELECTED: candidate_cap="
            << kNvFp4M1RowPairGridCaps[selected_cap_index]
            << " checkpoint_weighted_speedup="
            << selected_weighted_speedup << " gate=PASS\n";

  const std::size_t preserved_cap =
      q3x::kernels::sm87_nvfp4_m1_row_pair_maximum_blocks_test();
  std::size_t preserved_cap_index = kNvFp4M1RowPairGridCaps.size();
  for (std::size_t cap_index = 0U;
       cap_index < kNvFp4M1RowPairGridCaps.size(); ++cap_index) {
    if (kNvFp4M1RowPairGridCaps[cap_index] == preserved_cap) {
      preserved_cap_index = cap_index;
      break;
    }
  }
  const bool preserved_cap_measured =
      preserved_cap_index < kNvFp4M1RowPairGridCaps.size();
  test.expect(preserved_cap_measured,
              "NVFP4 M1 preserved row-pair cap is present in the sweep");
  if (!preserved_cap_measured) {
    return;
  }
  const bool preserved_gate = aggregate_gates[preserved_cap_index];
  std::cout << "PERF_NVFP4_M1_ROW_PAIR_PRESERVED: candidate_cap="
            << preserved_cap << " checkpoint_weighted_speedup="
            << weighted_speedups[preserved_cap_index]
            << " gate=" << (preserved_gate ? "PASS" : "FAIL") << '\n';
  test.expect(preserved_gate,
              "NVFP4 M1 frozen row-pair A/B cap clears every gate");
}

constexpr std::array<std::size_t, 3U> kNvFp4M1RowQuadGridCaps{{
    48U,
    64U,
    80U,
}};

constexpr std::array<NvFp4M1ScaleDistribution, 2U>
    kNvFp4M1RowQuadScaleDistributions{{
        NvFp4M1ScaleDistribution::kCheckpointLike,
        NvFp4M1ScaleDistribution::kSameBankStress,
    }};

struct NvFp4M1RowQuadDistributionMeasurement {
  std::array<float, kNvFp4M1RowQuadGridCaps.size()>
      baseline_milliseconds{};
  std::array<float, kNvFp4M1RowQuadGridCaps.size()>
      candidate_milliseconds{};
  std::array<bool, kNvFp4M1RowQuadGridCaps.size()> bitwise_equal{};
};

struct NvFp4M1RowQuadMeasurement {
  std::array<NvFp4M1RowQuadDistributionMeasurement,
             kNvFp4M1RowQuadScaleDistributions.size()>
      distributions{};
};

struct NvFp4M1RowQuadShape {
  std::size_t rows;
  std::size_t columns;
  std::size_t profile_calls;
  const char* label;
};

[[nodiscard]] NvFp4M1RowQuadMeasurement
benchmark_nvfp4_m1_row_quad_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::string& label) {
  constexpr std::size_t kBaselineGridCap = 80U;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr std::size_t kPackedPatternBytes = 256U;
  const std::size_t packed_count = rows * columns / 2U;
  const std::size_t scale_columns = columns / 16U;
  std::vector<std::uint8_t> host_scales(rows * scale_columns);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered =
        static_cast<int>((column * 17U + 5U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  std::array<std::uint8_t, kPackedPatternBytes> host_packed_pattern{};
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t index = 0U; index < host_packed_pattern.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 3U + (index >> 3U) + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 5U + (index >> 4U) * 7U + 3U) & 0x0fU);
    host_packed_pattern[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
    low_nibble_covered[low] = true;
    high_nibble_covered[high] = true;
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 low-nibble code");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " covers every E2M1 high-nibble code");
  test.expect((columns / 2U) % host_packed_pattern.size() == 0U,
              label + " repeats the full-nibble pattern within every row");

  NvFp4M1RowQuadMeasurement measurement;
  for (NvFp4M1RowQuadDistributionMeasurement& distribution :
       measurement.distributions) {
    distribution.baseline_milliseconds.fill(
        std::numeric_limits<float>::quiet_NaN());
    distribution.candidate_milliseconds.fill(
        std::numeric_limits<float>::quiet_NaN());
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(packed.allocate(packed_count),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(rows),
                                label + " allocate row-pair output");
  ready = ready && test.cuda_ok(candidate_output.allocate(rows),
                                label + " allocate row-quad output");
  const std::size_t initial_packed_bytes =
      std::min(packed_count, host_packed_pattern.size());
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           packed.get(), host_packed_pattern.data(),
                           initial_packed_bytes, cudaMemcpyHostToDevice,
                           stream),
                       label + " initialize mixed all-nibble seed");
  for (std::size_t initialized = initial_packed_bytes;
       ready && initialized < packed_count;) {
    const std::size_t copy_bytes =
        std::min(initialized, packed_count - initialized);
    ready = test.cuda_ok(
        cudaMemcpyAsync(packed.get() + initialized, packed.get(), copy_bytes,
                        cudaMemcpyDeviceToDevice, stream),
        label + " expand mixed all-nibble weights");
    initialized += copy_bytes;
  }
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize mixed activation");
  if (!ready) {
    return measurement;
  }

  std::vector<std::uint16_t> baseline(rows);
  std::vector<std::uint16_t> candidate(rows);
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M1RowQuadScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M1RowQuadScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_scale_distribution(host_scales, scale_columns,
                                     distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize block scales");
    if (!ready) {
      return measurement;
    }

    for (std::size_t cap_index = 0U;
         cap_index < kNvFp4M1RowQuadGridCaps.size(); ++cap_index) {
      const std::size_t candidate_grid_cap =
          kNvFp4M1RowQuadGridCaps[cap_index];
      const std::string cap_label =
          distribution_label + " candidate_cap=" +
          std::to_string(candidate_grid_cap);
      const auto launch_baseline = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_row_pair_grid_cap_test_cuda(
                packed.get(), scales.get(), kWeightScale2, activation.get(),
                rows, columns, baseline_output.get(), kBaselineGridCap,
                static_cast<void*>(stream));
      };
      const auto launch_candidate = [&]() noexcept -> int {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_row_quad_grid_cap_test_cuda(
                packed.get(), scales.get(), kWeightScale2, activation.get(),
                rows, columns, candidate_output.get(), candidate_grid_cap,
                static_cast<void*>(stream));
      };

      ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_baseline()),
          cap_label + " correctness direct row-pair cap80 baseline");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           cap_label + " correctness direct row-quad");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               baseline.data(), baseline_output.get(),
                               baseline.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-pair output");
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               candidate.data(), candidate_output.get(),
                               candidate.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           cap_label + " copy row-quad output");
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " correctness synchronize");
      if (!ready) {
        return measurement;
      }

      std::size_t mismatches = 0U;
      for (std::size_t row = 0U; row < rows; ++row) {
        mismatches += baseline[row] != candidate[row] ? 1U : 0U;
      }
      NvFp4M1RowQuadDistributionMeasurement& distribution_measurement =
          measurement.distributions[distribution_index];
      distribution_measurement.bitwise_equal[cap_index] = mismatches == 0U;
      std::cout << "NVFP4_M1_ROW_QUAD_DIFF: " << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " baseline_pair_cap=" << kBaselineGridCap
                << " candidate_quad_cap=" << candidate_grid_cap
                << " mismatches=" << mismatches << '/' << rows << '\n';
      test.expect(distribution_measurement.bitwise_equal[cap_index],
                  cap_label +
                      " row-quad matches every row-pair BF16 bit");

      for (int iteration = 0; iteration < kWarmupIterations && ready;
           ++iteration) {
        ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                             cap_label + " row-pair warmup");
        ready = ready && test.cuda_ok(
                             static_cast<cudaError_t>(launch_candidate()),
                             cap_label + " row-quad warmup");
      }
      ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                    cap_label + " warmup synchronize");
      if (!ready) {
        return measurement;
      }

      double baseline_total = 0.0;
      double candidate_total = 0.0;
      bool all_finite = true;
      for (int round = 0; round < kMeasurementRounds; ++round) {
        const std::string round_label =
            cap_label + " round=" + std::to_string(round + 1);
        const float baseline_first = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 1");
        const float candidate_first = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 1");
        const float candidate_second = measure_small_m_tile(
            test, stream, launch_candidate, kMeasuredIterations,
            round_label + " candidate pass 2");
        const float baseline_second = measure_small_m_tile(
            test, stream, launch_baseline, kMeasuredIterations,
            round_label + " baseline pass 2");
        const bool round_finite =
            std::isfinite(baseline_first) &&
            std::isfinite(candidate_first) &&
            std::isfinite(candidate_second) &&
            std::isfinite(baseline_second);
        all_finite = all_finite && round_finite;
        if (round_finite) {
          baseline_total += baseline_first + baseline_second;
          candidate_total += candidate_first + candidate_second;
        }
        std::cout << "PERF_NVFP4_M1_ROW_QUAD_ROUND: " << label
                  << " distribution="
                  << nvfp4_m1_scale_distribution_name(distribution)
                  << " baseline_pair_cap=" << kBaselineGridCap
                  << " candidate_quad_cap=" << candidate_grid_cap
                  << " measured_iterations=" << kMeasuredIterations
                  << " round=" << round + 1
                  << " baseline_pass1_ms=" << baseline_first
                  << " candidate_pass1_ms=" << candidate_first
                  << " candidate_pass2_ms=" << candidate_second
                  << " baseline_pass2_ms=" << baseline_second << '\n';
      }
      constexpr double kTimedPasses =
          2.0 * static_cast<double>(kMeasurementRounds);
      distribution_measurement.baseline_milliseconds[cap_index] =
          all_finite
              ? static_cast<float>(baseline_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      distribution_measurement.candidate_milliseconds[cap_index] =
          all_finite
              ? static_cast<float>(candidate_total / kTimedPasses)
              : std::numeric_limits<float>::quiet_NaN();
      const float speedup =
          distribution_measurement.baseline_milliseconds[cap_index] /
          distribution_measurement.candidate_milliseconds[cap_index];
      std::cout << "PERF_NVFP4_M1_ROW_QUAD: " << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " direct_row_pair_cap80_ms="
                << distribution_measurement
                       .baseline_milliseconds[cap_index]
                << " candidate_quad_cap=" << candidate_grid_cap
                << " direct_row_quad_ms="
                << distribution_measurement
                       .candidate_milliseconds[cap_index]
                << " speedup=" << speedup << " bitwise_mismatches="
                << mismatches << '/' << rows << '\n';
    }
  }
  return measurement;
}

void run_optional_nvfp4_m1_row_quad_performance(TestContext& test,
                                                 cudaStream_t stream) {
  if (!nvfp4_m1_row_quad_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M1 scale-codebook row-quad performance "
                 "segment; set Q3X_RUN_SM87_NVFP4_M1_ROW_QUAD_PERF=1 to "
                 "enable\n";
    return;
  }
  const std::size_t kSelectedGridCap =
      q3x::kernels::sm87_nvfp4_m1_row_quad_maximum_blocks_test();
  constexpr float kMinimumSelectedSpeedup = 1.02F;
  constexpr std::array<NvFp4M1RowQuadShape, 3U> kShapes{{
      {17'408U, 5'120U, 256U, "NVFP4 M1 row-quad 17408x5120"},
      {5'120U, 17'408U, 128U, "NVFP4 M1 row-quad 5120x17408"},
      {248'320U, 5'120U, 2U,
       "NVFP4 M1 row-quad lm_head 248320x5120"},
  }};

  std::array<NvFp4M1RowQuadMeasurement, kShapes.size()> measurements{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    measurements[shape_index] = benchmark_nvfp4_m1_row_quad_shape(
        test, stream, kShapes[shape_index].rows, kShapes[shape_index].columns,
        kShapes[shape_index].label);
  }

  std::size_t selected_cap_index = kNvFp4M1RowQuadGridCaps.size();
  for (std::size_t cap_index = 0U;
       cap_index < kNvFp4M1RowQuadGridCaps.size(); ++cap_index) {
    if (kNvFp4M1RowQuadGridCaps[cap_index] == kSelectedGridCap) {
      selected_cap_index = cap_index;
      break;
    }
  }
  const bool selected_cap_present =
      selected_cap_index < kNvFp4M1RowQuadGridCaps.size();
  test.expect(selected_cap_present,
              "NVFP4 M1 row-quad diagnostics include selected cap64");
  if (!selected_cap_present) {
    std::cout << "PERF_NVFP4_M1_ROW_QUAD_SELECTED: "
                 "scope=all_production_shapes "
                 "candidate_quad_cap=64 gate=FAIL reason=cap_not_measured\n";
    return;
  }

  for (std::size_t cap_index = 0U;
       cap_index < kNvFp4M1RowQuadGridCaps.size(); ++cap_index) {
    double checkpoint_weighted_baseline = 0.0;
    double checkpoint_weighted_candidate = 0.0;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      for (std::size_t distribution_index = 0U;
           distribution_index < kNvFp4M1RowQuadScaleDistributions.size();
           ++distribution_index) {
        const NvFp4M1RowQuadDistributionMeasurement& measurement =
            measurements[shape_index].distributions[distribution_index];
        const float baseline =
            measurement.baseline_milliseconds[cap_index];
        const float candidate =
            measurement.candidate_milliseconds[cap_index];
        const float speedup = baseline / candidate;
        const bool finite = std::isfinite(baseline) &&
                            std::isfinite(candidate) &&
                            std::isfinite(speedup) && baseline > 0.0F &&
                            candidate > 0.0F;
        const bool selected_cell = cap_index == selected_cap_index;
        const bool selected_cell_gate =
            measurement.bitwise_equal[cap_index] && finite &&
            speedup >= kMinimumSelectedSpeedup;
        std::cout << "PERF_NVFP4_M1_ROW_QUAD_DIAGNOSTIC: "
                  << kShapes[shape_index].label << " distribution="
                  << nvfp4_m1_scale_distribution_name(
                         kNvFp4M1RowQuadScaleDistributions
                             [distribution_index])
                  << " baseline_pair_cap=80 candidate_quad_cap="
                  << kNvFp4M1RowQuadGridCaps[cap_index]
                  << " baseline_ms=" << baseline
                  << " candidate_ms=" << candidate
                  << " speedup=" << speedup
                  << " bitwise="
                  << (measurement.bitwise_equal[cap_index] ? "true"
                                                           : "false")
                  << " scope="
                  << (selected_cell ? "selected_all_shapes" : "diagnostic")
                  << " performance_gate="
                  << (selected_cell
                          ? (selected_cell_gate ? "PASS" : "FAIL")
                          : "N/A")
                  << '\n';
      }

      const NvFp4M1RowQuadDistributionMeasurement& checkpoint =
          measurements[shape_index].distributions[0U];
      const float checkpoint_baseline =
          checkpoint.baseline_milliseconds[cap_index];
      const float checkpoint_candidate =
          checkpoint.candidate_milliseconds[cap_index];
      checkpoint_weighted_baseline +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          checkpoint_baseline;
      checkpoint_weighted_candidate +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          checkpoint_candidate;
    }

    const double checkpoint_weighted_speedup =
        checkpoint_weighted_baseline / checkpoint_weighted_candidate;
    std::cout
        << "PERF_NVFP4_M1_ROW_QUAD_WEIGHTED_DIAGNOSTIC: baseline_pair_cap=80"
              << " candidate_quad_cap="
              << kNvFp4M1RowQuadGridCaps[cap_index]
              << " checkpoint_weighted_baseline_ms="
              << checkpoint_weighted_baseline
              << " checkpoint_weighted_candidate_ms="
              << checkpoint_weighted_candidate
              << " speedup=" << checkpoint_weighted_speedup
              << " profile_calls=256:128:2 scope=diagnostic\n";
  }

  bool selected_gate = true;
  bool selected_all_bitwise = true;
  float selected_minimum_speedup = std::numeric_limits<float>::infinity();
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    for (std::size_t distribution_index = 0U;
         distribution_index < kNvFp4M1RowQuadScaleDistributions.size();
         ++distribution_index) {
      const NvFp4M1RowQuadDistributionMeasurement& measurement =
          measurements[shape_index].distributions[distribution_index];
      const float baseline =
          measurement.baseline_milliseconds[selected_cap_index];
      const float candidate =
          measurement.candidate_milliseconds[selected_cap_index];
      const float speedup = baseline / candidate;
      const bool bitwise = measurement.bitwise_equal[selected_cap_index];
      const bool cell_gate =
          bitwise && std::isfinite(baseline) && std::isfinite(candidate) &&
          std::isfinite(speedup) && baseline > 0.0F && candidate > 0.0F &&
          speedup >= kMinimumSelectedSpeedup;
      selected_all_bitwise = selected_all_bitwise && bitwise;
      selected_minimum_speedup =
          std::min(selected_minimum_speedup, speedup);
      selected_gate = selected_gate && cell_gate;
    }
  }
  test.expect(
      selected_gate,
      "NVFP4 M1 row-quad cap64 clears all production-shape distribution "
      "gates");
  std::cout
      << "PERF_NVFP4_M1_ROW_QUAD_SELECTED: scope=all_production_shapes"
      << " baseline_pair_cap=80 candidate_quad_cap=" << kSelectedGridCap
            << " minimum_cell_speedup=" << selected_minimum_speedup
            << " required_each=" << kMinimumSelectedSpeedup
            << " all_bitwise="
            << (selected_all_bitwise ? "true" : "false")
            << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
}

struct NvFp4M1ExactShapeDistributionMeasurement {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
  bool bitwise_equal = false;
  bool output_finite = false;
};

struct NvFp4M1ExactShapeMeasurement {
  std::array<NvFp4M1ExactShapeDistributionMeasurement,
             kNvFp4M1RowQuadScaleDistributions.size()>
      distributions{};
};

[[nodiscard]] NvFp4M1ExactShapeMeasurement
benchmark_nvfp4_m1_exact_shape(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const std::size_t profile_calls,
    const std::string& label) {
  constexpr std::size_t kBaselineGridCap = 64U;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr float kMinimumCellSpeedup = 1.015F;
  constexpr std::uint8_t kBaselineOutputSentinel = 0xa5U;
  constexpr std::uint8_t kCandidateOutputSentinel = 0x5aU;
  const int warmup_iterations = rows >= 100'000U ? 4 : 10;
  const std::size_t packed_count = rows * columns / 2U;
  const std::size_t packed_columns = columns / 2U;
  const std::size_t scale_columns = columns / 16U;
  std::vector<std::uint8_t> host_scales(rows * scale_columns);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered =
        static_cast<int>((column * 17U + 5U) % 127U) - 63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  std::array<std::uint8_t, kNvFp4M1ExactShapeFixturePeriod>
      host_packed_pattern{};
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t index = 0U; index < host_packed_pattern.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 3U + (index >> 3U) + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 5U + (index >> 4U) * 7U + 3U) & 0x0fU);
    host_packed_pattern[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
    low_nibble_covered[low] = true;
    high_nibble_covered[high] = true;
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " exact fixture covers every E2M1 low-nibble code");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " exact fixture covers every E2M1 high-nibble code");
  test.expect(
      (kNvFp4M1ExactShapeRowStride %
       kNvFp4M1ExactShapeFixturePeriod) != 0U,
      label + " exact scale fixture does not alias the 2048-row stride");
  test.expect(
      ((kNvFp4M1ExactShapeRowStride %
        kNvFp4M1ExactShapeFixturePeriod) *
       (packed_columns % kNvFp4M1ExactShapeFixturePeriod)) %
              kNvFp4M1ExactShapeFixturePeriod !=
          0U,
      label + " exact packed fixture does not alias the 2048-row stride");

  NvFp4M1ExactShapeMeasurement measurement{};
  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_output;
  DeviceBuffer<std::uint16_t> candidate_output;
  bool ready = test.cuda_ok(packed.allocate(packed_count),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(host_scales.size()),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activation.allocate(host_activation.size()),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(baseline_output.allocate(rows),
                                label + " allocate baseline output");
  ready = ready && test.cuda_ok(candidate_output.allocate(rows),
                                label + " allocate candidate output");
  const std::size_t initial_packed_bytes =
      std::min(packed_count, host_packed_pattern.size());
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           packed.get(), host_packed_pattern.data(),
                           initial_packed_bytes, cudaMemcpyHostToDevice,
                           stream),
                       label + " initialize mixed all-nibble packed seed");
  for (std::size_t initialized = initial_packed_bytes;
       ready && initialized < packed_count;) {
    const std::size_t copy_bytes =
        std::min(initialized, packed_count - initialized);
    ready = test.cuda_ok(
        cudaMemcpyAsync(packed.get() + initialized, packed.get(), copy_bytes,
                        cudaMemcpyDeviceToDevice, stream),
        label + " expand prime-period packed fixture");
    initialized += copy_bytes;
  }
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           host_activation.size() * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  if (!ready) {
    return measurement;
  }

  std::vector<std::uint16_t> baseline(rows);
  std::vector<std::uint16_t> candidate(rows);
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M1RowQuadScaleDistributions.size();
       ++distribution_index) {
    const NvFp4M1ScaleDistribution distribution =
        kNvFp4M1RowQuadScaleDistributions[distribution_index];
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_exact_shape_scale_distribution(
        host_scales, scale_columns, distribution);
    bool scale_rows_differ_across_stride = false;
    for (std::size_t scale_column = 0U;
         scale_column < scale_columns &&
         !scale_rows_differ_across_stride;
         ++scale_column) {
      scale_rows_differ_across_stride =
          host_scales[scale_column] !=
          host_scales[kNvFp4M1ExactShapeRowStride * scale_columns +
                      scale_column];
    }
    test.expect(scale_rows_differ_across_stride,
                distribution_label +
                    " scales differ across the 2048-row stride");
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), host_scales.size(),
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize block scales");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             baseline_output.get(), kBaselineOutputSentinel,
                             rows * sizeof(std::uint16_t), stream),
                         distribution_label +
                             " initialize baseline output sentinel");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             candidate_output.get(), kCandidateOutputSentinel,
                             rows * sizeof(std::uint16_t), stream),
                         distribution_label +
                             " initialize candidate output sentinel");
    if (!ready) {
      return measurement;
    }

    const auto launch_baseline = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_row_quad_grid_cap_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(),
              rows, columns, baseline_output.get(), kBaselineGridCap,
              static_cast<void*>(stream));
    };
    const auto launch_candidate = [&]() noexcept -> int {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_row_quad_exact_shape_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(),
              rows, columns, candidate_output.get(),
              static_cast<void*>(stream));
    };

    ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                         distribution_label + " correctness baseline cap64");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         distribution_label + " correctness exact shape");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_output.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy baseline output");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_output.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy candidate output");
    ready = ready && test.cuda_ok(
                         cudaStreamSynchronize(stream),
                         distribution_label + " correctness synchronize");
    if (!ready) {
      return measurement;
    }

    std::size_t mismatches = 0U;
    bool output_finite = true;
    for (std::size_t row = 0U; row < rows; ++row) {
      mismatches += baseline[row] != candidate[row] ? 1U : 0U;
      output_finite = output_finite &&
                      std::isfinite(decode_bf16(baseline[row])) &&
                      std::isfinite(decode_bf16(candidate[row]));
    }
    NvFp4M1ExactShapeDistributionMeasurement& cell =
        measurement.distributions[distribution_index];
    cell.bitwise_equal = mismatches == 0U;
    cell.output_finite = output_finite;

    for (int iteration = 0; iteration < warmup_iterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           distribution_label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           distribution_label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " warmup synchronize");
    if (!ready) {
      return measurement;
    }

    double baseline_total = 0.0;
    double candidate_total = 0.0;
    bool timings_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          distribution_label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 2");
      const bool round_finite =
          std::isfinite(baseline_first) && std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) && std::isfinite(baseline_second);
      timings_finite = timings_finite && round_finite;
      if (round_finite) {
        baseline_total += baseline_first + baseline_second;
        candidate_total += candidate_first + candidate_second;
      }
      std::cout << "PERF_NVFP4_M1_EXACT_SHAPE_ROUND: " << label
                << " distribution="
                << nvfp4_m1_scale_distribution_name(distribution)
                << " profile_calls=" << profile_calls
                << " measured_iterations=" << kMeasuredIterations
                << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }
    constexpr double kTimedPasses =
        2.0 * static_cast<double>(kMeasurementRounds);
    if (timings_finite) {
      cell.baseline_milliseconds =
          static_cast<float>(baseline_total / kTimedPasses);
      cell.candidate_milliseconds =
          static_cast<float>(candidate_total / kTimedPasses);
    }
    const float speedup =
        cell.baseline_milliseconds / cell.candidate_milliseconds;
    const bool finite = timings_finite && output_finite &&
                        std::isfinite(speedup) &&
                        cell.baseline_milliseconds > 0.0F &&
                        cell.candidate_milliseconds > 0.0F;
    const bool cell_gate = cell.bitwise_equal && finite &&
                           speedup >= kMinimumCellSpeedup;
    test.expect(cell_gate,
                distribution_label +
                    " exact-shape correctness, finite, and speedup gate");
    std::cout << "PERF_NVFP4_M1_EXACT_SHAPE: " << label
              << " distribution="
              << nvfp4_m1_scale_distribution_name(distribution)
              << " profile_calls=" << profile_calls
              << " baseline_row_quad_cap64_ms="
              << cell.baseline_milliseconds
              << " candidate_exact_shape_ms="
              << cell.candidate_milliseconds << " speedup=" << speedup
              << " required_speedup=" << kMinimumCellSpeedup
              << " bitwise_mismatches=" << mismatches << '/' << rows
              << " output_finite=" << (output_finite ? "true" : "false")
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  return measurement;
}

void run_optional_nvfp4_m1_exact_shape_performance(TestContext& test,
                                                    cudaStream_t stream) {
  if (!nvfp4_m1_exact_shape_performance_enabled()) {
    std::cout << "SKIP: NVFP4 M1 exact-shape performance segment; set "
                 "Q3X_RUN_SM87_NVFP4_M1_EXACT_SHAPE_PERF=1 to enable\n";
    return;
  }
  constexpr std::array<NvFp4M1RowQuadShape, 3U> kShapes{{
      {17'408U, 5'120U, 128U, "NVFP4 M1 exact gate/up 17408x5120"},
      {5'120U, 17'408U, 64U, "NVFP4 M1 exact down 5120x17408"},
      {248'320U, 5'120U, 1U, "NVFP4 M1 exact lm_head 248320x5120"},
  }};
  constexpr std::array<double, 2U> kMinimumWeightedSpeedups{{
      1.025,
      1.020,
  }};
  std::array<NvFp4M1ExactShapeMeasurement, kShapes.size()> measurements{};
  std::array<double, kNvFp4M1RowQuadScaleDistributions.size()>
      weighted_speedups{};
  for (std::size_t shape_index = 0U; shape_index < kShapes.size();
       ++shape_index) {
    const NvFp4M1RowQuadShape& shape = kShapes[shape_index];
    measurements[shape_index] = benchmark_nvfp4_m1_exact_shape(
        test, stream, shape.rows, shape.columns, shape.profile_calls,
        shape.label);
  }

  bool all_gates = true;
  for (std::size_t distribution_index = 0U;
       distribution_index < kNvFp4M1RowQuadScaleDistributions.size();
       ++distribution_index) {
    double weighted_baseline = 0.0;
    double weighted_candidate = 0.0;
    bool distribution_gate = true;
    for (std::size_t shape_index = 0U; shape_index < kShapes.size();
         ++shape_index) {
      const NvFp4M1ExactShapeDistributionMeasurement& cell =
          measurements[shape_index].distributions[distribution_index];
      const bool finite = std::isfinite(cell.baseline_milliseconds) &&
                          std::isfinite(cell.candidate_milliseconds) &&
                          cell.baseline_milliseconds > 0.0F &&
                          cell.candidate_milliseconds > 0.0F;
      const double cell_speedup =
          static_cast<double>(cell.baseline_milliseconds) /
          static_cast<double>(cell.candidate_milliseconds);
      distribution_gate = distribution_gate && cell.bitwise_equal &&
                          cell.output_finite && finite &&
                          std::isfinite(cell_speedup) &&
                          cell_speedup >= 1.015;
      weighted_baseline +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          cell.baseline_milliseconds;
      weighted_candidate +=
          static_cast<double>(kShapes[shape_index].profile_calls) *
          cell.candidate_milliseconds;
    }
    const double weighted_speedup = weighted_baseline / weighted_candidate;
    weighted_speedups[distribution_index] = weighted_speedup;
    const double required_speedup =
        kMinimumWeightedSpeedups[distribution_index];
    distribution_gate = distribution_gate &&
                        std::isfinite(weighted_speedup) &&
                        weighted_baseline > 0.0 && weighted_candidate > 0.0 &&
                        weighted_speedup >= required_speedup;
    all_gates = all_gates && distribution_gate;
    std::cout << "PERF_NVFP4_M1_EXACT_SHAPE_WEIGHTED: distribution="
              << nvfp4_m1_scale_distribution_name(
                     kNvFp4M1RowQuadScaleDistributions[distribution_index])
              << " baseline_row_quad_cap64_ms=" << weighted_baseline
              << " candidate_exact_shape_ms=" << weighted_candidate
              << " speedup=" << weighted_speedup
              << " required_speedup=" << required_speedup
              << " profile_calls=128:64:1"
              << " gate=" << (distribution_gate ? "PASS" : "FAIL")
              << '\n';
  }
  test.expect(all_gates,
              "NVFP4 M1 exact-shape clears correctness and performance "
              "gates");
  std::cout << "PERF_NVFP4_M1_EXACT_SHAPE_SELECTED: baseline="
               "current_row_quad_cap64 candidate=exact_shape"
            << " distributions=checkpoint_like:same_bank_stress"
            << " profile_calls=128:64:1 checkpoint_weighted_speedup="
            << weighted_speedups[0U] << " stress_weighted_speedup="
            << weighted_speedups[1U]
            << " gate=" << (all_gates ? "PASS" : "FAIL") << '\n';
}

struct NvFp4M1DownDualKernelResources {
  int registers_per_thread = 0;
  std::size_t static_shared_bytes = 0U;
  std::size_t local_bytes = 0U;
  int maximum_threads_per_block = 0;
  int active_blocks_per_sm = 0;
};

void run_nvfp4_m1_down_xor_dual_fixture(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const bool run_performance,
    const std::string& label) {
  constexpr std::size_t kGuardElements = 16U;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr std::uint16_t kBaselineGuard = 0xa5a5U;
  constexpr std::uint16_t kCandidateGuard = 0x5a5aU;
  constexpr std::uint16_t kProductionGuard = 0x3c3cU;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  constexpr float kMinimumSpeedup = 1.002F;
  constexpr std::array<NvFp4M1ScaleDistribution, 2U> kDistributions{{
      NvFp4M1ScaleDistribution::kCheckpointLike,
      NvFp4M1ScaleDistribution::kSameBankStress,
  }};

  const std::size_t packed_columns = columns / 2U;
  const std::size_t scale_columns = columns / 16U;
  const std::size_t packed_count = rows * packed_columns;
  const std::size_t scale_count = rows * scale_columns;
  std::vector<std::uint8_t> host_scales(scale_count);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered =
        static_cast<int>((column * 19U + (column >> 3U) * 7U + 11U) %
                         127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  std::array<std::uint8_t, kNvFp4M1DownDualFixturePeriod>
      host_packed_pattern{};
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t index = 0U; index < host_packed_pattern.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 5U + (index >> 2U) * 3U + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 7U + (index >> 3U) * 5U + 9U) & 0x0fU);
    host_packed_pattern[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
    low_nibble_covered[low] = true;
    high_nibble_covered[high] = true;
  }
  test.expect(std::all_of(low_nibble_covered.begin(),
                          low_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " prime fixture covers every E2M1 low nibble");
  test.expect(std::all_of(high_nibble_covered.begin(),
                          high_nibble_covered.end(),
                          [](const bool covered) { return covered; }),
              label + " prime fixture covers every E2M1 high nibble");
  test.expect(kNvFp4M1DownDualFixturePeriod !=
                  kNvFp4M1ExactShapeFixturePeriod &&
                  (kNvFp4M1ExactShapeRowStride %
                   kNvFp4M1DownDualFixturePeriod) != 0U,
              label + " uses a distinct prime grid-stride fixture");

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_storage;
  DeviceBuffer<std::uint16_t> candidate_storage;
  DeviceBuffer<std::uint16_t> production_storage;
  DeviceBuffer<std::uint8_t> unaligned_packed_storage;
  DeviceBuffer<std::uint16_t> unaligned_activation_storage;
  bool ready = test.cuda_ok(packed.allocate(packed_count),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(scale_count),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activation.allocate(columns),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(
                       baseline_storage.allocate(rows + 2U * kGuardElements),
                       label + " allocate guarded baseline output");
  ready = ready && test.cuda_ok(
                       candidate_storage.allocate(rows + 2U * kGuardElements),
                       label + " allocate guarded candidate output");
  ready = ready && test.cuda_ok(
                       production_storage.allocate(
                           rows + 2U * kGuardElements),
                       label + " allocate guarded public output");
  if (run_performance) {
    ready = ready && test.cuda_ok(
                         unaligned_packed_storage.allocate(packed_count + 1U),
                         label + " allocate packed+1 fallback fixture");
    ready = ready && test.cuda_ok(
                         unaligned_activation_storage.allocate(columns + 2U),
                         label + " allocate activation+2 fallback fixture");
  }
  const std::size_t seed_bytes =
      std::min(packed_count, host_packed_pattern.size());
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           packed.get(), host_packed_pattern.data(),
                           seed_bytes, cudaMemcpyHostToDevice, stream),
                       label + " initialize prime packed seed");
  for (std::size_t initialized = seed_bytes;
       ready && initialized < packed_count;) {
    const std::size_t copy_bytes =
        std::min(initialized, packed_count - initialized);
    ready = test.cuda_ok(
        cudaMemcpyAsync(packed.get() + initialized, packed.get(), copy_bytes,
                        cudaMemcpyDeviceToDevice, stream),
        label + " expand prime packed fixture");
    initialized += copy_bytes;
  }
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           columns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  if (run_performance) {
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             unaligned_packed_storage.get() + 1U,
                             packed.get(), packed_count,
                             cudaMemcpyDeviceToDevice, stream),
                         label + " initialize packed+1 fallback fixture");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             unaligned_activation_storage.get() + 2U,
                             activation.get(),
                             columns * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToDevice, stream),
                         label + " initialize activation+2 fallback fixture");
  }
  if (!ready) {
    return;
  }

  std::uint16_t* const baseline_output =
      baseline_storage.get() + kGuardElements;
  std::uint16_t* const candidate_output =
      candidate_storage.get() + kGuardElements;
  std::uint16_t* const production_output =
      production_storage.get() + kGuardElements;
  const auto candidate_status =
      [&](const std::uint8_t* const candidate_packed,
          const std::uint8_t* const candidate_scales,
          const std::uint16_t* const candidate_activation,
          const std::size_t candidate_rows,
          const std::size_t candidate_columns,
          std::uint16_t* const candidate_result) noexcept {
        return static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_down_xor_dual_test_cuda(
                candidate_packed, candidate_scales, kWeightScale2,
                candidate_activation, candidate_rows, candidate_columns,
                candidate_result, static_cast<void*>(stream)));
      };

  if (!run_performance) {
    ready = test.cuda_ok(
        cudaMemsetAsync(candidate_storage.get(), 0x5a,
                        (rows + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        label + " poison validation output");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " validation pre-synchronize");
    if (!ready) {
      return;
    }
    test.expect(candidate_status(nullptr, scales.get(), activation.get(),
                                 rows, columns, candidate_output) ==
                    cudaErrorInvalidValue,
                label + " null input fails before enqueue");
    test.expect(candidate_status(packed.get(), scales.get(), activation.get(),
                                 rows - 1U, columns, candidate_output) ==
                    cudaErrorInvalidValue,
                label + " near-miss rows fail before enqueue");
    test.expect(candidate_status(packed.get(), scales.get(), activation.get(),
                                 rows, columns - 16U, candidate_output) ==
                    cudaErrorInvalidValue,
                label + " near-miss columns fail before enqueue");
    test.expect(candidate_status(packed.get() + 1U, scales.get(),
                                 activation.get(), rows, columns,
                                 candidate_output) == cudaErrorInvalidValue,
                label + " unaligned packed input fails before enqueue");
    test.expect(candidate_status(packed.get(), scales.get(),
                                 activation.get() + 1U, rows, columns,
                                 candidate_output) == cudaErrorInvalidValue,
                label + " unaligned activation fails before enqueue");
    test.expect(
        candidate_status(
            packed.get(), scales.get(), activation.get(), rows, columns,
            reinterpret_cast<std::uint16_t*>(packed.get())) ==
            cudaErrorInvalidValue,
        label + " aliased output fails before enqueue");
    test.expect(
        candidate_status(
            packed.get(), scales.get(), activation.get(), rows, columns,
            reinterpret_cast<std::uint16_t*>(
                reinterpret_cast<std::uint8_t*>(candidate_output) + 1U)) ==
            cudaErrorInvalidValue,
        label + " unaligned output fails before enqueue");

    auto* const fake_packed =
        reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
    auto* const fake_scales =
        reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
    auto* const fake_activation =
        reinterpret_cast<const std::uint16_t*>(0x3'0000'0000ULL);
    auto* const fake_output =
        reinterpret_cast<std::uint16_t*>(0x4'0000'0000ULL);
    test.expect(candidate_status(fake_packed, fake_scales, fake_activation,
                                 17'408U, 5'120U, fake_output) ==
                    cudaErrorInvalidValue,
                label + " gate/up shape has no candidate instance");
    test.expect(candidate_status(fake_packed, fake_scales, fake_activation,
                                 248'320U, 5'120U, fake_output) ==
                    cudaErrorInvalidValue,
                label + " lm-head shape has no candidate instance");
    test.expect(cudaStreamQuery(stream) == cudaSuccess,
                label + " rejected calls leave the stream empty");
    std::vector<std::uint16_t> validation_output(
        rows + 2U * kGuardElements);
    ready = test.cuda_ok(
        cudaMemcpyAsync(validation_output.data(), candidate_storage.get(),
                        validation_output.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        label + " copy validation poison");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " validation synchronize");
    const bool validation_untouched =
        ready && std::all_of(validation_output.begin(),
                             validation_output.end(),
                             [](const std::uint16_t value) {
                               return value == kCandidateGuard;
                             });
    test.expect(validation_untouched,
                label + " rejected calls do not touch output storage");
    if (!ready) {
      return;
    }
  }

  const auto launch_baseline = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_down_dual_iteration_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
            columns, baseline_output, static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_down_xor_dual_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
            columns, candidate_output, static_cast<void*>(stream));
  };
  const auto launch_public =
      [&](const std::uint8_t* const public_packed,
          const std::uint16_t* const public_activation,
          std::uint16_t* const public_output) noexcept -> int {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_gemv_bf16_cuda(
        public_packed, scales.get(), kWeightScale2, public_activation, rows,
        columns, public_output, static_cast<void*>(stream));
  };
  const auto launch_scalar =
      [&](const std::uint8_t* const scalar_packed,
          const std::uint16_t* const scalar_activation,
          std::uint16_t* const scalar_output) noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_scalar_test_cuda(
            scalar_packed, scales.get(), kWeightScale2, scalar_activation,
            rows, columns, scalar_output, static_cast<void*>(stream));
  };

  std::vector<std::uint16_t> baseline(rows + 2U * kGuardElements);
  std::vector<std::uint16_t> candidate(rows + 2U * kGuardElements);
  std::vector<std::uint16_t> production(rows + 2U * kGuardElements);
  bool all_distribution_gates = true;
  bool all_production_dispatch_gates = true;
  for (const NvFp4M1ScaleDistribution distribution : kDistributions) {
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_down_dual_scale_distribution(
        host_scales, scale_columns, distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), scale_count,
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize block scales");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             baseline_storage.get(), 0xa5,
                             baseline.size() * sizeof(std::uint16_t), stream),
                         distribution_label + " poison baseline guards");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             candidate_storage.get(), 0x5a,
                             candidate.size() * sizeof(std::uint16_t), stream),
                         distribution_label + " poison candidate guards");
    if (run_performance) {
      ready = ready && test.cuda_ok(
                           cudaMemsetAsync(
                               production_storage.get(), 0x3c,
                               production.size() * sizeof(std::uint16_t),
                               stream),
                           distribution_label + " poison public guards");
    }
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         distribution_label + " correctness baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         distribution_label + " correctness candidate");
    if (run_performance) {
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_public(
                               packed.get(), activation.get(),
                               production_output)),
                           distribution_label + " correctness public");
    }
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_storage.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy guarded baseline");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_storage.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy guarded candidate");
    if (run_performance) {
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               production.data(), production_storage.get(),
                               production.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           distribution_label + " copy guarded public");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " synchronize");
    if (!ready) {
      return;
    }

    std::size_t mismatches = 0U;
    std::size_t public_mismatches = 0U;
    std::size_t nonfinite_outputs = 0U;
    for (std::size_t row = 0U; row < rows; ++row) {
      mismatches +=
          baseline[kGuardElements + row] !=
                  candidate[kGuardElements + row]
              ? 1U
              : 0U;
      nonfinite_outputs +=
          !is_bf16_finite(baseline[kGuardElements + row]) ? 1U : 0U;
      nonfinite_outputs +=
          !is_bf16_finite(candidate[kGuardElements + row]) ? 1U : 0U;
      if (run_performance) {
        public_mismatches +=
            production[kGuardElements + row] != candidate[kGuardElements + row]
                ? 1U
                : 0U;
        nonfinite_outputs +=
            !is_bf16_finite(production[kGuardElements + row]) ? 1U : 0U;
      }
    }
    bool guards_intact = true;
    for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
      guards_intact =
          guards_intact && baseline[guard] == kBaselineGuard &&
          baseline[kGuardElements + rows + guard] == kBaselineGuard &&
          candidate[guard] == kCandidateGuard &&
          candidate[kGuardElements + rows + guard] == kCandidateGuard;
      if (run_performance) {
        guards_intact =
            guards_intact && production[guard] == kProductionGuard &&
            production[kGuardElements + rows + guard] == kProductionGuard;
      }
    }
    const bool correctness_gate =
        mismatches == 0U && public_mismatches == 0U &&
        nonfinite_outputs == 0U && guards_intact;
    test.expect(correctness_gate,
                distribution_label +
                    " is bitwise, finite, and preserves both canaries");
    std::cout << "NVFP4_M1_DOWN_XOR_DUAL_DIFF: " << distribution_label
              << " rows=" << rows << " columns=" << columns
              << " bf16_mismatches=" << mismatches << '/' << rows
              << " public_vs_candidate_bf16_mismatches="
              << public_mismatches
              << '/' << (run_performance ? rows : 0U)
              << " output_guards=" << (guards_intact ? "intact" : "BAD")
              << " nonfinite_outputs=" << nonfinite_outputs << '\n';

    if (!run_performance) {
      all_distribution_gates = all_distribution_gates && correctness_gate;
      continue;
    }

    if (distribution == NvFp4M1ScaleDistribution::kCheckpointLike) {
      cudaGraph_t graph = nullptr;
      bool graph_ready = test.cuda_ok(
          cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
          distribution_label + " begin public graph capture");
      if (graph_ready) {
        graph_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_public(
                packed.get(), activation.get(), production_output)),
            distribution_label + " capture public launch");
        graph_ready =
            test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                         distribution_label + " end public graph capture") &&
            graph_ready;
      }
      std::size_t graph_node_count = 0U;
      if (graph_ready) {
        graph_ready = test.cuda_ok(
            cudaGraphGetNodes(graph, nullptr, &graph_node_count),
            distribution_label + " query public graph nodes");
      }
      cudaGraphNode_t public_node = nullptr;
      cudaKernelNodeParams public_kernel_params{};
      if (graph_ready && graph_node_count == 1U) {
        std::size_t node_capacity = 1U;
        graph_ready = test.cuda_ok(
            cudaGraphGetNodes(graph, &public_node, &node_capacity),
            distribution_label + " get public graph kernel node");
        graph_ready =
            graph_ready && node_capacity == 1U &&
            test.cuda_ok(
                cudaGraphKernelNodeGetParams(public_node,
                                             &public_kernel_params),
                distribution_label + " get public graph kernel params");
      }

      cudaGraph_t candidate_graph = nullptr;
      bool candidate_graph_ready = test.cuda_ok(
          cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
          distribution_label + " begin direct XOR graph capture");
      if (candidate_graph_ready) {
        candidate_graph_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_candidate()),
            distribution_label + " capture direct XOR launch");
        candidate_graph_ready =
            test.cuda_ok(cudaStreamEndCapture(stream, &candidate_graph),
                         distribution_label +
                             " end direct XOR graph capture") &&
            candidate_graph_ready;
      }
      std::size_t candidate_graph_node_count = 0U;
      if (candidate_graph_ready) {
        candidate_graph_ready = test.cuda_ok(
            cudaGraphGetNodes(candidate_graph, nullptr,
                              &candidate_graph_node_count),
            distribution_label + " query direct XOR graph nodes");
      }
      cudaKernelNodeParams candidate_kernel_params{};
      if (candidate_graph_ready && candidate_graph_node_count == 1U) {
        cudaGraphNode_t candidate_node = nullptr;
        std::size_t node_capacity = 1U;
        candidate_graph_ready = test.cuda_ok(
            cudaGraphGetNodes(candidate_graph, &candidate_node,
                              &node_capacity),
            distribution_label + " get direct XOR graph kernel node");
        candidate_graph_ready =
            candidate_graph_ready && node_capacity == 1U &&
            test.cuda_ok(
                cudaGraphKernelNodeGetParams(candidate_node,
                                             &candidate_kernel_params),
                distribution_label + " get direct XOR graph kernel params");
      }
      const bool kernels_distinct =
          graph_ready && candidate_graph_ready &&
          public_kernel_params.func != candidate_kernel_params.func;
      const bool graph_gate =
          graph_ready && graph_node_count == 1U && candidate_graph_ready &&
          candidate_graph_node_count == 1U && kernels_distinct;
      test.expect(graph_gate,
                  distribution_label +
                      " public aligned down staged kernel remains distinct "
                      "from preserved direct XOR");
      all_production_dispatch_gates =
          all_production_dispatch_gates && graph_gate;
      if (graph != nullptr) {
        (void)test.cuda_ok(cudaGraphDestroy(graph),
                           distribution_label + " destroy public graph");
      }
      if (candidate_graph != nullptr) {
        (void)test.cuda_ok(cudaGraphDestroy(candidate_graph),
                           distribution_label +
                               " destroy direct XOR graph");
      }
      std::cout << "NVFP4_M1_DOWN_XOR_DUAL_GRAPH: public_nodes="
                << graph_node_count << " required=1 direct_xor_nodes="
                << candidate_graph_node_count << " kernels_distinct="
                << (kernels_distinct ? "true" : "false") << " gate="
                << (graph_gate ? "PASS" : "FAIL") << '\n';

      const auto check_fallback =
          [&](const std::uint8_t* const fallback_packed,
              const std::uint16_t* const fallback_activation,
              const std::string& fallback_label) {
        bool fallback_ready = test.cuda_ok(
            cudaMemsetAsync(
                baseline_storage.get(), 0xa5,
                baseline.size() * sizeof(std::uint16_t), stream),
            fallback_label + " poison scalar-reference guards");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaMemsetAsync(
                production_storage.get(), 0x3c,
                production.size() * sizeof(std::uint16_t), stream),
            fallback_label + " poison public-fallback guards");
        fallback_ready = fallback_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_scalar(
                fallback_packed, fallback_activation, baseline_output)),
            fallback_label + " direct scalar reference");
        fallback_ready = fallback_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_public(
                fallback_packed, fallback_activation, production_output)),
            fallback_label + " public fallback");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaMemcpyAsync(
                baseline.data(), baseline_storage.get(),
                baseline.size() * sizeof(std::uint16_t),
                cudaMemcpyDeviceToHost, stream),
            fallback_label + " copy scalar reference");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaMemcpyAsync(
                production.data(), production_storage.get(),
                production.size() * sizeof(std::uint16_t),
                cudaMemcpyDeviceToHost, stream),
            fallback_label + " copy public fallback");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaStreamSynchronize(stream), fallback_label + " synchronize");
        if (!fallback_ready) {
          return false;
        }
        std::size_t fallback_mismatches = 0U;
        std::size_t fallback_nonfinite = 0U;
        for (std::size_t row = 0U; row < rows; ++row) {
          const std::uint16_t reference_bits =
              baseline[kGuardElements + row];
          const std::uint16_t public_bits =
              production[kGuardElements + row];
          fallback_mismatches += reference_bits != public_bits ? 1U : 0U;
          fallback_nonfinite += !is_bf16_finite(reference_bits) ? 1U : 0U;
          fallback_nonfinite += !is_bf16_finite(public_bits) ? 1U : 0U;
        }
        bool fallback_guards = true;
        for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
          fallback_guards =
              fallback_guards && baseline[guard] == kBaselineGuard &&
              baseline[kGuardElements + rows + guard] == kBaselineGuard &&
              production[guard] == kProductionGuard &&
              production[kGuardElements + rows + guard] == kProductionGuard;
        }
        const bool fallback_gate =
            fallback_mismatches == 0U && fallback_nonfinite == 0U &&
            fallback_guards;
        test.expect(fallback_gate,
                    fallback_label + " matches the direct scalar fallback");
        std::cout << "NVFP4_M1_DOWN_XOR_DUAL_FALLBACK_DIFF: "
                  << fallback_label
                  << " public_vs_scalar_bf16_mismatches="
                  << fallback_mismatches << '/' << rows
                  << " output_guards="
                  << (fallback_guards ? "intact" : "BAD")
                  << " nonfinite_outputs=" << fallback_nonfinite << '\n';
        return fallback_gate;
      };
      const bool packed_fallback = check_fallback(
          unaligned_packed_storage.get() + 1U, activation.get(),
          distribution_label + " packed+1");
      const bool activation_fallback = check_fallback(
          packed.get(), unaligned_activation_storage.get() + 2U,
          distribution_label + " activation+2");
      test.expect(packed_fallback && activation_fallback,
                  distribution_label +
                      " preserves both production unaligned fallbacks");
      all_production_dispatch_gates =
          all_production_dispatch_gates && packed_fallback &&
          activation_fallback;
    }

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           distribution_label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           distribution_label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " warmup synchronize");
    if (!ready) {
      return;
    }

    constexpr std::size_t kTimedPasses =
        2U * static_cast<std::size_t>(kMeasurementRounds);
    std::array<float, kTimedPasses> baseline_passes{};
    std::array<float, kTimedPasses> candidate_passes{};
    bool timings_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          distribution_label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 2");
      baseline_passes[2U * static_cast<std::size_t>(round)] =
          baseline_first;
      baseline_passes[2U * static_cast<std::size_t>(round) + 1U] =
          baseline_second;
      candidate_passes[2U * static_cast<std::size_t>(round)] =
          candidate_first;
      candidate_passes[2U * static_cast<std::size_t>(round) + 1U] =
          candidate_second;
      const bool round_finite =
          std::isfinite(baseline_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(baseline_second);
      timings_finite = timings_finite && round_finite;
      std::cout << "PERF_NVFP4_M1_DOWN_XOR_DUAL_ROUND: "
                << distribution_label << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }
    const float baseline_milliseconds =
        timings_finite
            ? median_fp8_kv_pair_timing(baseline_passes)
            : std::numeric_limits<float>::quiet_NaN();
    const float candidate_milliseconds =
        timings_finite
            ? median_fp8_kv_pair_timing(candidate_passes)
            : std::numeric_limits<float>::quiet_NaN();
    const float speedup = baseline_milliseconds / candidate_milliseconds;
    const bool performance_gate =
        correctness_gate && timings_finite && std::isfinite(speedup) &&
        baseline_milliseconds > 0.0F && candidate_milliseconds > 0.0F &&
        speedup >= kMinimumSpeedup;
    test.expect(performance_gate,
                distribution_label + " clears down-XOR 1.002 speedup gate");
    all_distribution_gates =
        all_distribution_gates && performance_gate;
    std::cout << "PERF_NVFP4_M1_DOWN_XOR_DUAL: " << distribution_label
              << " baseline_preserved_indexed_dual_median_ms="
              << baseline_milliseconds
              << " candidate_preserved_xor_dual_median_ms="
              << candidate_milliseconds << " speedup=" << speedup
              << " required_speedup=" << kMinimumSpeedup
              << " gate=" << (performance_gate ? "PASS" : "FAIL") << '\n';
  }

  // Isolate both E4M3FN NaN encodings in each half of the dual iteration:
  // rows 0/1 use scale column 0 and activation columns 0..15, while rows 2/3
  // use scale column 16 and activation columns 256..271. All later rows stay
  // finite and each classified result retains the production baseline class
  // and sign.
  std::fill(host_scales.begin(), host_scales.end(), std::uint8_t{0U});
  host_scales[0U] = 0x7fU;
  host_scales[scale_columns] = 0xffU;
  host_scales[2U * scale_columns + 16U] = 0x7fU;
  host_scales[3U * scale_columns + 16U] = 0xffU;
  std::fill(host_activation.begin(), host_activation.end(),
            encode_bf16(0.0F));
  std::fill_n(host_activation.begin(), 16U, encode_bf16(1.0F));
  std::fill_n(host_activation.begin() + 256U, 16U, encode_bf16(1.0F));
  ready = test.cuda_ok(cudaMemsetAsync(packed.get(), 0x11, packed_count,
                                        stream),
                       label + " initialize isolated-NaN packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(scales.get(), host_scales.data(),
                                       scale_count, cudaMemcpyHostToDevice,
                                       stream),
                       label + " initialize isolated-NaN scales");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           columns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize isolated-NaN activation");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           baseline_storage.get(), 0xa5,
                           baseline.size() * sizeof(std::uint16_t), stream),
                       label + " poison isolated-NaN baseline guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           candidate_storage.get(), 0x5a,
                           candidate.size() * sizeof(std::uint16_t), stream),
                       label + " poison isolated-NaN candidate guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           production_storage.get(), 0x3c,
                           production.size() * sizeof(std::uint16_t), stream),
                       label + " poison isolated-NaN public guards");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_baseline()),
                       label + " isolated-NaN baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " isolated-NaN candidate");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_public(
                           packed.get(), activation.get(),
                           production_output)),
                       label + " isolated-NaN public");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_storage.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy isolated-NaN baseline");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_storage.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy isolated-NaN candidate");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           production.data(), production_storage.get(),
                           production.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy isolated-NaN public");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " isolated-NaN synchronize");
  if (!ready) {
    return;
  }
  bool nan_class_and_sign = true;
  std::size_t nan_bitwise_mismatches = 0U;
  std::size_t nan_public_mismatches = 0U;
  for (std::size_t row = 0U; row < 4U; ++row) {
    const std::uint16_t baseline_bits = baseline[kGuardElements + row];
    const std::uint16_t candidate_bits = candidate[kGuardElements + row];
    const std::uint16_t production_bits =
        production[kGuardElements + row];
    nan_bitwise_mismatches += baseline_bits != candidate_bits ? 1U : 0U;
    nan_public_mismatches += production_bits != candidate_bits ? 1U : 0U;
    nan_class_and_sign =
        nan_class_and_sign && is_bf16_nan(baseline_bits) &&
        is_bf16_nan(candidate_bits) && is_bf16_nan(production_bits) &&
        ((baseline_bits ^ candidate_bits) & 0x8000U) == 0U &&
        ((baseline_bits ^ production_bits) & 0x8000U) == 0U;
  }
  std::size_t unexpected_nonfinite = 0U;
  std::size_t finite_mismatches = 0U;
  std::size_t finite_public_mismatches = 0U;
  for (std::size_t row = 4U; row < rows; ++row) {
    const std::uint16_t baseline_bits = baseline[kGuardElements + row];
    const std::uint16_t candidate_bits = candidate[kGuardElements + row];
    const std::uint16_t production_bits =
        production[kGuardElements + row];
    unexpected_nonfinite += !is_bf16_finite(baseline_bits) ? 1U : 0U;
    unexpected_nonfinite += !is_bf16_finite(candidate_bits) ? 1U : 0U;
    unexpected_nonfinite += !is_bf16_finite(production_bits) ? 1U : 0U;
    finite_mismatches += baseline_bits != candidate_bits ? 1U : 0U;
    finite_public_mismatches +=
        production_bits != candidate_bits ? 1U : 0U;
  }
  bool nan_guards_intact = true;
  for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
    nan_guards_intact =
        nan_guards_intact && baseline[guard] == kBaselineGuard &&
        baseline[kGuardElements + rows + guard] == kBaselineGuard &&
        candidate[guard] == kCandidateGuard &&
        candidate[kGuardElements + rows + guard] == kCandidateGuard &&
        production[guard] == kProductionGuard &&
        production[kGuardElements + rows + guard] == kProductionGuard;
  }
  const bool nan_gate = nan_bitwise_mismatches == 0U &&
                        nan_class_and_sign && unexpected_nonfinite == 0U &&
                        finite_mismatches == 0U &&
                        finite_public_mismatches == 0U &&
                        nan_public_mismatches == 0U && nan_guards_intact;
  test.expect(nan_gate,
              label +
                  " classifies isolated 0x7f/0xff NaNs and preserves guards");
  test.expect(all_distribution_gates,
              label + " clears both distribution correctness gates");
  std::cout << "NVFP4_M1_DOWN_XOR_DUAL_NAN: classified_outputs=4"
            << " nan_bitwise_mismatches=" << nan_bitwise_mismatches << "/4"
            << " public_vs_candidate_nan_mismatches="
            << nan_public_mismatches
            << "/4"
            << " class_and_sign="
            << (nan_class_and_sign ? "true" : "false")
            << " finite_mismatches=" << finite_mismatches << '/'
            << (rows - 4U)
            << " public_vs_candidate_finite_mismatches="
            << finite_public_mismatches << '/' << (rows - 4U)
            << " unexpected_nonfinite=" << unexpected_nonfinite
            << " output_guards="
            << (nan_guards_intact ? "intact" : "BAD")
            << " gate=" << (nan_gate ? "PASS" : "FAIL") << '\n';
  if (!run_performance) {
    test.expect(all_distribution_gates && nan_gate,
                label + " clears lightweight bitwise and NaN gates");
    return;
  }
  test.expect(all_production_dispatch_gates,
              label + " clears graph identity and unaligned production gates");
  const bool overall_gate = all_distribution_gates &&
                            all_production_dispatch_gates && nan_gate;
  std::cout << "PERF_NVFP4_M1_DOWN_XOR_DUAL_SELECTED: baseline="
               "preserved_down_indexed_dual_5120x17408"
            << " candidate=preserved_down_xor_dual"
            << " distributions=checkpoint_like:same_bank_stress"
            << " required_each=" << kMinimumSpeedup
            << " all_correct=" << (overall_gate ? "true" : "false")
            << " gate=" << (overall_gate ? "PASS" : "FAIL")
            << '\n';
}

void run_nvfp4_m1_down_xor_dual_probe(TestContext& test,
                                      cudaStream_t stream) {
  NvFp4M1DownDualKernelResources baseline_resources{};
  NvFp4M1DownDualKernelResources candidate_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_down_dual_iteration_resources_test_cuda(
              &baseline_resources.registers_per_thread,
              &baseline_resources.static_shared_bytes,
              &baseline_resources.local_bytes,
              &baseline_resources.maximum_threads_per_block,
              &baseline_resources.active_blocks_per_sm)),
      "query NVFP4 M1 preserved indexed-dual baseline resources");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           query_sm87_nvfp4_w4a16_m1_down_xor_dual_resources_test_cuda(
                               &candidate_resources.registers_per_thread,
                               &candidate_resources.static_shared_bytes,
                               &candidate_resources.local_bytes,
                               &candidate_resources.maximum_threads_per_block,
                               &candidate_resources.active_blocks_per_sm)),
                       "query NVFP4 M1 preserved down XOR resources");
  test.expect(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_down_xor_dual_resources_test_cuda(
              nullptr, &candidate_resources.static_shared_bytes,
              &candidate_resources.local_bytes,
              &candidate_resources.maximum_threads_per_block,
              &candidate_resources.active_blocks_per_sm)) ==
          cudaErrorInvalidValue,
      "NVFP4 M1 down XOR resource query rejects null destination");
  const bool resource_gate =
      ready && candidate_resources.registers_per_thread <= 64 &&
      candidate_resources.static_shared_bytes <= 1'088U &&
      candidate_resources.local_bytes == 0U &&
      candidate_resources.maximum_threads_per_block >= 256 &&
      candidate_resources.active_blocks_per_sm >= 4;
  test.expect(resource_gate,
              "NVFP4 M1 down XOR clears 64r/1088B/0local/active4 gate");
  std::cout << "PERF_NVFP4_M1_DOWN_XOR_DUAL_RESOURCES: "
            << "baseline_registers_per_thread="
            << baseline_resources.registers_per_thread
            << " candidate_registers_per_thread="
            << candidate_resources.registers_per_thread
            << " candidate_static_shared_bytes="
            << candidate_resources.static_shared_bytes
            << " candidate_local_bytes=" << candidate_resources.local_bytes
            << " candidate_maximum_threads_per_block="
            << candidate_resources.maximum_threads_per_block
            << " candidate_active_blocks_per_sm="
            << candidate_resources.active_blocks_per_sm
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!ready) {
    return;
  }

  run_nvfp4_m1_down_xor_dual_fixture(
      test, stream, 2'048U, 512U, false,
      "NVFP4 M1 down XOR lightweight 2048x512");
  if (!nvfp4_m1_down_xor_dual_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M1 down XOR-dual full segment; set "
           "Q3X_RUN_SM87_NVFP4_M1_DOWN_XOR_DUAL_PERF=1 to enable\n";
    return;
  }
  run_nvfp4_m1_down_xor_dual_fixture(
      test, stream, 5'120U, 17'408U, true,
      "NVFP4 M1 down XOR exact 5120x17408");
}

enum class NvFp4M1K5120XorDualProbe {
  kDownActivationStaged,
  kGateUp,
  kGateUpActivationStaged,
  kLmHead,
  kLmHeadActivationStaged,
  kLmHeadActivationStagedCs,
};

[[nodiscard]] bool run_nvfp4_m1_k5120_xor_dual_fixture(
    TestContext& test, cudaStream_t stream, const std::size_t rows,
    const std::size_t columns, const bool run_performance,
    const NvFp4M1K5120XorDualProbe probe,
    const std::string& label) {
  constexpr std::size_t kGuardElements = 16U;
  constexpr std::size_t kGridCap = 64U;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr std::uint16_t kBaselineGuard = 0xa5a5U;
  constexpr std::uint16_t kCandidateGuard = 0x5a5aU;
  constexpr std::uint16_t kProductionGuard = 0x3c3cU;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 24;
  constexpr int kMeasurementRounds = 3;
  const bool down_staged_probe =
      probe == NvFp4M1K5120XorDualProbe::kDownActivationStaged;
  const bool gate_up_staged_probe =
      probe == NvFp4M1K5120XorDualProbe::kGateUpActivationStaged;
  const bool lm_head_probe =
      probe == NvFp4M1K5120XorDualProbe::kLmHead ||
      probe == NvFp4M1K5120XorDualProbe::kLmHeadActivationStaged ||
      probe == NvFp4M1K5120XorDualProbe::kLmHeadActivationStagedCs;
  const bool lm_head_staged_probe =
      probe == NvFp4M1K5120XorDualProbe::kLmHeadActivationStaged;
  const bool lm_head_cs_probe =
      probe == NvFp4M1K5120XorDualProbe::kLmHeadActivationStagedCs;
  const bool staged_probe =
      down_staged_probe || gate_up_staged_probe || lm_head_staged_probe ||
      lm_head_cs_probe;
  const bool direct_lm_baseline_probe =
      probe == NvFp4M1K5120XorDualProbe::kLmHead || lm_head_cs_probe;
  const bool verify_public_dispatch =
      run_performance && !direct_lm_baseline_probe;
  const float minimum_speedup =
      down_staged_probe ? 1.005F
                        : gate_up_staged_probe ? 1.005F
                           : lm_head_cs_probe ? 1.005F
                           : lm_head_staged_probe ? 1.01F
                                                  : lm_head_probe ? 1.02F
                                                                  : 1.01F;
  const char* const metric_tag =
      down_staged_probe
          ? "NVFP4_M1_DOWN_ACTIVATION_STAGED"
          : gate_up_staged_probe
          ? "NVFP4_M1_GATE_UP_ACTIVATION_STAGED"
          : lm_head_cs_probe
          ? "NVFP4_M1_LM_HEAD_ACTIVATION_STAGED_CS"
          : lm_head_staged_probe
                ? "NVFP4_M1_LM_HEAD_ACTIVATION_STAGED"
                : lm_head_probe ? "NVFP4_M1_LM_HEAD_XOR_DUAL"
                                : "NVFP4_M1_K5120_XOR_DUAL";
  constexpr std::array<NvFp4M1ScaleDistribution, 2U> kDistributions{{
      NvFp4M1ScaleDistribution::kCheckpointLike,
      NvFp4M1ScaleDistribution::kSameBankStress,
  }};

  const std::size_t packed_columns = columns / 2U;
  const std::size_t scale_columns = columns / 16U;
  const std::size_t packed_count = rows * packed_columns;
  const std::size_t scale_count = rows * scale_columns;
  std::vector<std::uint8_t> host_scales(scale_count);
  std::vector<std::uint16_t> host_activation(columns);
  for (std::size_t column = 0U; column < columns; ++column) {
    const int centered =
        static_cast<int>((column * 19U + (column >> 3U) * 7U + 11U) %
                         127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  std::array<std::uint8_t, kNvFp4M1DownDualFixturePeriod>
      host_packed_pattern{};
  std::array<bool, 16U> low_nibble_covered{};
  std::array<bool, 16U> high_nibble_covered{};
  for (std::size_t index = 0U; index < host_packed_pattern.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 5U + (index >> 2U) * 3U + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 7U + (index >> 3U) * 5U + 9U) & 0x0fU);
    host_packed_pattern[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
    low_nibble_covered[low] = true;
    high_nibble_covered[high] = true;
  }
  const bool full_codebook =
      std::all_of(low_nibble_covered.begin(), low_nibble_covered.end(),
                  [](const bool covered) { return covered; }) &&
      std::all_of(high_nibble_covered.begin(), high_nibble_covered.end(),
                  [](const bool covered) { return covered; });
  test.expect(full_codebook,
              label + " prime fixture covers both complete E2M1 nibbles");

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_storage;
  DeviceBuffer<std::uint16_t> candidate_storage;
  DeviceBuffer<std::uint16_t> production_storage;
  DeviceBuffer<std::uint8_t> unaligned_packed_storage;
  DeviceBuffer<std::uint16_t> unaligned_activation_storage;
  bool ready = test.cuda_ok(packed.allocate(packed_count),
                            label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(scale_count),
                                label + " allocate block scales");
  ready = ready && test.cuda_ok(activation.allocate(columns),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(
                       baseline_storage.allocate(rows + 2U * kGuardElements),
                       label + " allocate guarded baseline output");
  ready = ready && test.cuda_ok(
                       candidate_storage.allocate(rows + 2U * kGuardElements),
                       label + " allocate guarded candidate output");
  if (verify_public_dispatch) {
    ready = ready && test.cuda_ok(
                         production_storage.allocate(
                             rows + 2U * kGuardElements),
                         label + " allocate guarded public output");
    ready = ready && test.cuda_ok(
                         unaligned_packed_storage.allocate(packed_count + 1U),
                         label + " allocate packed+1 fallback fixture");
    ready = ready && test.cuda_ok(
                         unaligned_activation_storage.allocate(columns + 2U),
                         label + " allocate activation+2 fallback fixture");
  }
  const std::size_t seed_bytes =
      std::min(packed_count, host_packed_pattern.size());
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           packed.get(), host_packed_pattern.data(),
                           seed_bytes, cudaMemcpyHostToDevice, stream),
                       label + " initialize prime packed seed");
  for (std::size_t initialized = seed_bytes;
       ready && initialized < packed_count;) {
    const std::size_t copy_bytes =
        std::min(initialized, packed_count - initialized);
    ready = test.cuda_ok(
        cudaMemcpyAsync(packed.get() + initialized, packed.get(), copy_bytes,
                        cudaMemcpyDeviceToDevice, stream),
        label + " expand prime packed fixture");
    initialized += copy_bytes;
  }
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           columns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize activation");
  if (verify_public_dispatch) {
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             unaligned_packed_storage.get() + 1U,
                             packed.get(), packed_count,
                             cudaMemcpyDeviceToDevice, stream),
                         label + " initialize packed+1 fallback fixture");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             unaligned_activation_storage.get() + 2U,
                             activation.get(),
                             columns * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToDevice, stream),
                         label +
                             " initialize activation+2 fallback fixture");
  }
  if (!ready) {
    return false;
  }

  std::uint16_t* const baseline_output =
      baseline_storage.get() + kGuardElements;
  std::uint16_t* const candidate_output =
      candidate_storage.get() + kGuardElements;
  std::uint16_t* const production_output =
      verify_public_dispatch
          ? production_storage.get() + kGuardElements
          : nullptr;
  const auto candidate_status =
      [&](const std::uint8_t* const candidate_packed,
          const std::uint8_t* const candidate_scales,
          const std::uint16_t* const candidate_activation,
          const std::size_t candidate_rows,
          const std::size_t candidate_columns,
          std::uint16_t* const candidate_result) noexcept {
        if (lm_head_cs_probe) {
          return static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_activation_staged_cs_test_cuda(
                  candidate_packed, candidate_scales, kWeightScale2,
                  candidate_activation, candidate_rows, candidate_columns,
                  candidate_result, static_cast<void*>(stream)));
        }
        if (down_staged_probe) {
          return static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_nvfp4_w4a16_gemv_bf16_down_activation_staged_test_cuda(
                  candidate_packed, candidate_scales, kWeightScale2,
                  candidate_activation, candidate_rows, candidate_columns,
                  candidate_result, static_cast<void*>(stream)));
        }
        if (gate_up_staged_probe) {
          return static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_nvfp4_w4a16_gemv_bf16_gate_up_activation_staged_test_cuda(
                  candidate_packed, candidate_scales, kWeightScale2,
                  candidate_activation, candidate_rows, candidate_columns,
                  candidate_result, static_cast<void*>(stream)));
        }
        if (lm_head_staged_probe) {
          return static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_activation_staged_test_cuda(
                  candidate_packed, candidate_scales, kWeightScale2,
                  candidate_activation, candidate_rows, candidate_columns,
                  candidate_result, static_cast<void*>(stream)));
        }
        if (lm_head_probe) {
          return static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_xor_dual_test_cuda(
                  candidate_packed, candidate_scales, kWeightScale2,
                  candidate_activation, candidate_rows, candidate_columns,
                  candidate_result, static_cast<void*>(stream)));
        }
        return static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_k5120_xor_dual_test_cuda(
                candidate_packed, candidate_scales, kWeightScale2,
                candidate_activation, candidate_rows, candidate_columns,
                candidate_result, static_cast<void*>(stream)));
      };

  bool validation_gate = true;
  if (!run_performance) {
    ready = test.cuda_ok(
        cudaMemsetAsync(candidate_storage.get(), 0x5a,
                        (rows + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        label + " poison validation output");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " validation pre-synchronize");
    if (!ready) {
      return false;
    }
    const auto expect_invalid = [&](const cudaError_t status,
                                    const std::string& reason) {
      const bool rejected = status == cudaErrorInvalidValue;
      validation_gate = validation_gate && rejected;
      test.expect(rejected, label + " " + reason + " fails before enqueue");
    };
    expect_invalid(candidate_status(nullptr, scales.get(), activation.get(),
                                    rows, columns, candidate_output),
                   "null packed input");
    expect_invalid(candidate_status(packed.get(), scales.get(),
                                    activation.get(), rows - 1U, columns,
                                    candidate_output),
                   "near-miss rows");
    expect_invalid(candidate_status(packed.get(), scales.get(),
                                    activation.get(), rows, columns - 16U,
                                    candidate_output),
                   "near-miss columns");
    expect_invalid(candidate_status(packed.get() + 1U, scales.get(),
                                    activation.get(), rows, columns,
                                    candidate_output),
                   "packed+1 alignment");
    expect_invalid(candidate_status(packed.get(), scales.get(),
                                    activation.get() + 1U, rows, columns,
                                    candidate_output),
                   "activation+1 alignment");
    expect_invalid(candidate_status(packed.get(), scales.get(),
                                    activation.get() + 2U, rows, columns,
                                    candidate_output),
                   "activation+2 alignment");
    expect_invalid(
        candidate_status(
            packed.get(), scales.get(), activation.get(), rows, columns,
            reinterpret_cast<std::uint16_t*>(packed.get())),
        "aliased output");
    expect_invalid(
        candidate_status(
            packed.get(), scales.get(), activation.get(), rows, columns,
            reinterpret_cast<std::uint16_t*>(
                reinterpret_cast<std::uint8_t*>(candidate_output) + 1U)),
        "unaligned output");

    auto* const fake_packed =
        reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
    auto* const fake_scales =
        reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
    auto* const fake_activation =
        reinterpret_cast<const std::uint16_t*>(0x3'0000'0000ULL);
    auto* const fake_output =
        reinterpret_cast<std::uint16_t*>(0x4'0000'0000ULL);
    if (!lm_head_probe && !down_staged_probe) {
      expect_invalid(candidate_status(fake_packed, fake_scales,
                                      fake_activation, 17'407U, 5'120U,
                                      fake_output),
                     "production gate/up near-miss rows");
      expect_invalid(candidate_status(fake_packed, fake_scales,
                                      fake_activation, 17'408U, 5'104U,
                                      fake_output),
                     "production gate/up near-miss columns");
    }
    if (!down_staged_probe) {
      expect_invalid(candidate_status(fake_packed, fake_scales,
                                      fake_activation, 5'120U, 17'408U,
                                      fake_output),
                     "down-projection shape");
    }
    if (lm_head_probe || down_staged_probe) {
      expect_invalid(candidate_status(fake_packed, fake_scales,
                                      fake_activation, 17'408U, 5'120U,
                                      fake_output),
                     "gate/up shape");
    }
    if (!lm_head_probe) {
      expect_invalid(candidate_status(fake_packed, fake_scales,
                                      fake_activation, 248'320U, 5'120U,
                                      fake_output),
                     "lm-head shape");
    }
    const bool stream_empty = cudaStreamQuery(stream) == cudaSuccess;
    validation_gate = validation_gate && stream_empty;
    test.expect(stream_empty, label + " rejected calls leave stream empty");
    std::vector<std::uint16_t> validation_output(
        rows + 2U * kGuardElements);
    ready = test.cuda_ok(
        cudaMemcpyAsync(validation_output.data(), candidate_storage.get(),
                        validation_output.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        label + " copy validation poison");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " validation synchronize");
    const bool poison_untouched =
        ready && std::all_of(validation_output.begin(),
                             validation_output.end(),
                             [](const std::uint16_t value) {
                               return value == kCandidateGuard;
                             });
    validation_gate = validation_gate && poison_untouched;
    test.expect(poison_untouched,
                label + " rejected calls preserve poisoned output");
    if (!ready) {
      return false;
    }
  }

  const auto launch_baseline = [&]() noexcept -> int {
    if (lm_head_cs_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_activation_staged_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
              columns, baseline_output, static_cast<void*>(stream));
    }
    if (down_staged_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_down_xor_dual_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(),
              rows, columns, baseline_output, static_cast<void*>(stream));
    }
    if (gate_up_staged_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_k5120_xor_dual_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
              columns, baseline_output, static_cast<void*>(stream));
    }
    if (run_performance) {
      if (lm_head_staged_probe) {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_xor_dual_test_cuda(
                packed.get(), scales.get(), kWeightScale2, activation.get(),
                rows, columns, baseline_output, static_cast<void*>(stream));
      }
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_row_quad_exact_shape_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(),
              rows, columns, baseline_output, static_cast<void*>(stream));
    }
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_scale_codebook_row_quad_grid_cap_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
            columns, baseline_output, kGridCap,
            static_cast<void*>(stream));
  };
  const auto launch_candidate = [&]() noexcept -> int {
    if (lm_head_cs_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_activation_staged_cs_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
              columns, candidate_output, static_cast<void*>(stream));
    }
    if (down_staged_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_down_activation_staged_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(),
              rows, columns, candidate_output, static_cast<void*>(stream));
    }
    if (gate_up_staged_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_gate_up_activation_staged_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
              columns, candidate_output, static_cast<void*>(stream));
    }
    if (lm_head_staged_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_activation_staged_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(),
              rows, columns, candidate_output, static_cast<void*>(stream));
    }
    if (lm_head_probe) {
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_lm_head_xor_dual_test_cuda(
              packed.get(), scales.get(), kWeightScale2, activation.get(),
              rows, columns, candidate_output, static_cast<void*>(stream));
    }
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_k5120_xor_dual_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(), rows,
            columns, candidate_output, static_cast<void*>(stream));
  };
  const auto launch_public =
      [&](const std::uint8_t* const public_packed,
          const std::uint16_t* const public_activation,
          std::uint16_t* const public_output) noexcept -> int {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_gemv_bf16_cuda(
        public_packed, scales.get(), kWeightScale2, public_activation, rows,
        columns, public_output, static_cast<void*>(stream));
  };
  const auto launch_scalar =
      [&](const std::uint8_t* const scalar_packed,
          const std::uint16_t* const scalar_activation,
          std::uint16_t* const scalar_output) noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_scalar_test_cuda(
            scalar_packed, scales.get(), kWeightScale2, scalar_activation,
            rows, columns, scalar_output, static_cast<void*>(stream));
  };

  std::vector<std::uint16_t> baseline(rows + 2U * kGuardElements);
  std::vector<std::uint16_t> candidate(rows + 2U * kGuardElements);
  std::vector<std::uint16_t> production(
      verify_public_dispatch ? rows + 2U * kGuardElements : 0U);
  bool all_distribution_gates = full_codebook;
  bool all_production_dispatch_gates = true;
  for (const NvFp4M1ScaleDistribution distribution : kDistributions) {
    const std::string distribution_label =
        label + " " + nvfp4_m1_scale_distribution_name(distribution);
    fill_nvfp4_m1_down_dual_scale_distribution(
        host_scales, scale_columns, distribution);
    ready = test.cuda_ok(
        cudaMemcpyAsync(scales.get(), host_scales.data(), scale_count,
                        cudaMemcpyHostToDevice, stream),
        distribution_label + " initialize block scales");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             baseline_storage.get(), 0xa5,
                             baseline.size() * sizeof(std::uint16_t), stream),
                         distribution_label + " poison baseline guards");
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             candidate_storage.get(), 0x5a,
                             candidate.size() * sizeof(std::uint16_t), stream),
                         distribution_label + " poison candidate guards");
    if (verify_public_dispatch) {
      ready = ready && test.cuda_ok(
                           cudaMemsetAsync(
                               production_storage.get(), 0x3c,
                               production.size() * sizeof(std::uint16_t),
                               stream),
                           distribution_label + " poison public guards");
    }
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         distribution_label + " correctness baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_candidate()),
                         distribution_label + " correctness candidate");
    if (verify_public_dispatch) {
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_public(
                               packed.get(), activation.get(),
                               production_output)),
                           distribution_label + " correctness public");
    }
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             baseline.data(), baseline_storage.get(),
                             baseline.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy guarded baseline");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             candidate.data(), candidate_storage.get(),
                             candidate.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         distribution_label + " copy guarded candidate");
    if (verify_public_dispatch) {
      ready = ready && test.cuda_ok(
                           cudaMemcpyAsync(
                               production.data(), production_storage.get(),
                               production.size() * sizeof(std::uint16_t),
                               cudaMemcpyDeviceToHost, stream),
                           distribution_label + " copy guarded public");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " synchronize");
    if (!ready) {
      return false;
    }

    std::size_t mismatches = 0U;
    std::size_t public_mismatches = 0U;
    std::size_t nonfinite_outputs = 0U;
    for (std::size_t row = 0U; row < rows; ++row) {
      const std::uint16_t baseline_bits = baseline[kGuardElements + row];
      const std::uint16_t candidate_bits = candidate[kGuardElements + row];
      mismatches += baseline_bits != candidate_bits ? 1U : 0U;
      nonfinite_outputs += !is_bf16_finite(baseline_bits) ? 1U : 0U;
      nonfinite_outputs += !is_bf16_finite(candidate_bits) ? 1U : 0U;
      if (verify_public_dispatch) {
        const std::uint16_t production_bits =
            production[kGuardElements + row];
        public_mismatches += production_bits != candidate_bits ? 1U : 0U;
        nonfinite_outputs += !is_bf16_finite(production_bits) ? 1U : 0U;
      }
    }
    bool guards_intact = true;
    for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
      guards_intact =
          guards_intact && baseline[guard] == kBaselineGuard &&
          baseline[kGuardElements + rows + guard] == kBaselineGuard &&
          candidate[guard] == kCandidateGuard &&
          candidate[kGuardElements + rows + guard] == kCandidateGuard;
      if (verify_public_dispatch) {
        guards_intact =
            guards_intact && production[guard] == kProductionGuard &&
            production[kGuardElements + rows + guard] == kProductionGuard;
      }
    }
    const bool correctness_gate =
        mismatches == 0U && public_mismatches == 0U &&
        nonfinite_outputs == 0U && guards_intact;
    test.expect(correctness_gate,
                distribution_label +
                    " is bitwise, finite, and preserves both canaries");
    std::cout << metric_tag << "_DIFF: " << distribution_label
              << " rows=" << rows << " columns=" << columns
              << " bf16_mismatches=" << mismatches << '/' << rows
              << (staged_probe
                      ? " public_vs_direct_staged_bf16_mismatches="
                      : " public_vs_candidate_bf16_mismatches=")
              << public_mismatches
              << '/' << (verify_public_dispatch ? rows : 0U)
              << " output_guards=" << (guards_intact ? "intact" : "BAD")
              << " nonfinite_outputs=" << nonfinite_outputs << '\n';
    if (!run_performance) {
      all_distribution_gates =
          all_distribution_gates && correctness_gate;
      continue;
    }

    if (verify_public_dispatch &&
        distribution == NvFp4M1ScaleDistribution::kCheckpointLike) {
      cudaGraph_t graph = nullptr;
      bool graph_ready = test.cuda_ok(
          cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
          distribution_label + " begin public graph capture");
      if (graph_ready) {
        graph_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_public(
                packed.get(), activation.get(), production_output)),
            distribution_label + " capture public launch");
        graph_ready =
            test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                         distribution_label + " end public graph capture") &&
            graph_ready;
      }
      std::size_t graph_node_count = 0U;
      if (graph_ready) {
        graph_ready = test.cuda_ok(
            cudaGraphGetNodes(graph, nullptr, &graph_node_count),
            distribution_label + " query public graph nodes");
      }
      cudaGraphNode_t public_node = nullptr;
      cudaKernelNodeParams public_kernel_params{};
      if (graph_ready && graph_node_count == 1U) {
        std::size_t node_capacity = 1U;
        graph_ready = test.cuda_ok(
            cudaGraphGetNodes(graph, &public_node, &node_capacity),
            distribution_label + " get public graph kernel node");
        graph_ready =
            graph_ready && node_capacity == 1U &&
            test.cuda_ok(
                cudaGraphKernelNodeGetParams(public_node,
                                             &public_kernel_params),
                distribution_label + " get public graph kernel params");
      }

      cudaGraph_t candidate_graph = nullptr;
      std::size_t candidate_graph_node_count = 0U;
      bool candidate_graph_ready = !staged_probe;
      cudaKernelNodeParams candidate_kernel_params{};
      if (staged_probe) {
        candidate_graph_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
            distribution_label + " begin direct staged graph capture");
        if (candidate_graph_ready) {
          candidate_graph_ready = test.cuda_ok(
              static_cast<cudaError_t>(launch_candidate()),
              distribution_label + " capture direct staged launch");
          candidate_graph_ready =
              test.cuda_ok(
                  cudaStreamEndCapture(stream, &candidate_graph),
                  distribution_label + " end direct staged graph capture") &&
              candidate_graph_ready;
        }
        if (candidate_graph_ready) {
          candidate_graph_ready = test.cuda_ok(
              cudaGraphGetNodes(candidate_graph, nullptr,
                                &candidate_graph_node_count),
              distribution_label + " query direct staged graph nodes");
        }
        if (candidate_graph_ready && candidate_graph_node_count == 1U) {
          cudaGraphNode_t candidate_node = nullptr;
          std::size_t node_capacity = 1U;
          candidate_graph_ready = test.cuda_ok(
              cudaGraphGetNodes(candidate_graph, &candidate_node,
                                &node_capacity),
              distribution_label + " get direct staged graph kernel node");
          candidate_graph_ready =
              candidate_graph_ready && node_capacity == 1U &&
              test.cuda_ok(
                  cudaGraphKernelNodeGetParams(candidate_node,
                                               &candidate_kernel_params),
                  distribution_label +
                      " get direct staged graph kernel params");
        }
      }
      const bool kernel_identity =
          !staged_probe ||
          (graph_ready && candidate_graph_ready &&
           public_kernel_params.func == candidate_kernel_params.func);
      const bool graph_gate =
          graph_ready && graph_node_count == 1U &&
          (!staged_probe ||
           (candidate_graph_ready && candidate_graph_node_count == 1U &&
            kernel_identity));
      test.expect(
          graph_gate,
          distribution_label +
              (staged_probe
                   ? down_staged_probe
                         ? " public aligned down capture selects the direct "
                           "staged kernel"
                         : gate_up_staged_probe
                               ? " public aligned gate/up capture selects the "
                                 "direct staged kernel"
                               : " public aligned lm-head capture selects the "
                                 "direct staged kernel"
                   : " public aligned gate/up capture has one kernel node"));
      all_production_dispatch_gates =
          all_production_dispatch_gates && graph_gate;
      if (graph != nullptr) {
        (void)test.cuda_ok(cudaGraphDestroy(graph),
                           distribution_label + " destroy public graph");
      }
      if (candidate_graph != nullptr) {
        (void)test.cuda_ok(
            cudaGraphDestroy(candidate_graph),
            distribution_label + " destroy direct staged graph");
      }
      std::cout << metric_tag << "_GRAPH: public_nodes="
                << graph_node_count << " required=1"
                << " direct_staged_nodes=" << candidate_graph_node_count
                << " kernel_identity="
                << (staged_probe ? (kernel_identity ? "true" : "false")
                                 : "not_checked")
                << " gate="
                << (graph_gate ? "PASS" : "FAIL") << '\n';

      const auto check_fallback =
          [&](const std::uint8_t* const fallback_packed,
              const std::uint16_t* const fallback_activation,
              const std::string& fallback_label) {
        bool fallback_ready = test.cuda_ok(
            cudaMemsetAsync(
                baseline_storage.get(), 0xa5,
                baseline.size() * sizeof(std::uint16_t), stream),
            fallback_label + " poison scalar-reference guards");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaMemsetAsync(
                production_storage.get(), 0x3c,
                production.size() * sizeof(std::uint16_t), stream),
            fallback_label + " poison public-fallback guards");
        fallback_ready = fallback_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_scalar(
                fallback_packed, fallback_activation, baseline_output)),
            fallback_label + " direct scalar reference");
        fallback_ready = fallback_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_public(
                fallback_packed, fallback_activation, production_output)),
            fallback_label + " public fallback");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaMemcpyAsync(
                baseline.data(), baseline_storage.get(),
                baseline.size() * sizeof(std::uint16_t),
                cudaMemcpyDeviceToHost, stream),
            fallback_label + " copy scalar reference");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaMemcpyAsync(
                production.data(), production_storage.get(),
                production.size() * sizeof(std::uint16_t),
                cudaMemcpyDeviceToHost, stream),
            fallback_label + " copy public fallback");
        fallback_ready = fallback_ready && test.cuda_ok(
            cudaStreamSynchronize(stream), fallback_label + " synchronize");
        if (!fallback_ready) {
          return false;
        }
        std::size_t fallback_mismatches = 0U;
        std::size_t fallback_nonfinite = 0U;
        for (std::size_t row = 0U; row < rows; ++row) {
          const std::uint16_t reference_bits =
              baseline[kGuardElements + row];
          const std::uint16_t public_bits =
              production[kGuardElements + row];
          fallback_mismatches += reference_bits != public_bits ? 1U : 0U;
          fallback_nonfinite += !is_bf16_finite(reference_bits) ? 1U : 0U;
          fallback_nonfinite += !is_bf16_finite(public_bits) ? 1U : 0U;
        }
        bool fallback_guards = true;
        for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
          fallback_guards =
              fallback_guards && baseline[guard] == kBaselineGuard &&
              baseline[kGuardElements + rows + guard] == kBaselineGuard &&
              production[guard] == kProductionGuard &&
              production[kGuardElements + rows + guard] == kProductionGuard;
        }
        const bool fallback_gate =
            fallback_mismatches == 0U && fallback_nonfinite == 0U &&
            fallback_guards;
        test.expect(fallback_gate,
                    fallback_label + " matches direct scalar bitwise");
        std::cout << metric_tag << "_FALLBACK_DIFF: "
                  << fallback_label
                  << " public_vs_scalar_bf16_mismatches="
                  << fallback_mismatches << '/' << rows
                  << " output_guards="
                  << (fallback_guards ? "intact" : "BAD")
                  << " nonfinite_outputs=" << fallback_nonfinite << '\n';
        return fallback_gate;
      };
      const bool packed_fallback = check_fallback(
          unaligned_packed_storage.get() + 1U, activation.get(),
          distribution_label + " packed+1");
      const bool activation_fallback = check_fallback(
          packed.get(), unaligned_activation_storage.get() + 2U,
          distribution_label + " activation+2");
      test.expect(packed_fallback && activation_fallback,
                  distribution_label +
                      " preserves both public scalar fallbacks");
      all_production_dispatch_gates =
          all_production_dispatch_gates && packed_fallback &&
          activation_fallback;
    }

    for (int iteration = 0; iteration < kWarmupIterations && ready;
         ++iteration) {
      ready = test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                           distribution_label + " baseline warmup");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_candidate()),
                           distribution_label + " candidate warmup");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  distribution_label + " warmup synchronize");
    if (!ready) {
      return false;
    }

    constexpr std::size_t kTimedPasses =
        2U * static_cast<std::size_t>(kMeasurementRounds);
    std::array<float, kTimedPasses> baseline_passes{};
    std::array<float, kTimedPasses> candidate_passes{};
    bool timings_finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          distribution_label + " round=" + std::to_string(round + 1);
      const float baseline_first = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 1");
      const float candidate_first = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 1");
      const float candidate_second = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " candidate pass 2");
      const float baseline_second = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " baseline pass 2");
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      baseline_passes[pass] = baseline_first;
      baseline_passes[pass + 1U] = baseline_second;
      candidate_passes[pass] = candidate_first;
      candidate_passes[pass + 1U] = candidate_second;
      const bool round_finite =
          std::isfinite(baseline_first) &&
          std::isfinite(candidate_first) &&
          std::isfinite(candidate_second) &&
          std::isfinite(baseline_second);
      timings_finite = timings_finite && round_finite;
      std::cout << "PERF_" << metric_tag << "_ROUND: "
                << distribution_label << " round=" << round + 1
                << " baseline_pass1_ms=" << baseline_first
                << " candidate_pass1_ms=" << candidate_first
                << " candidate_pass2_ms=" << candidate_second
                << " baseline_pass2_ms=" << baseline_second << '\n';
    }
    const float baseline_milliseconds =
        timings_finite
            ? median_fp8_kv_pair_timing(baseline_passes)
            : std::numeric_limits<float>::quiet_NaN();
    const float candidate_milliseconds =
        timings_finite
            ? median_fp8_kv_pair_timing(candidate_passes)
            : std::numeric_limits<float>::quiet_NaN();
    const float speedup = baseline_milliseconds / candidate_milliseconds;
    const bool performance_gate =
        correctness_gate && timings_finite && std::isfinite(speedup) &&
        baseline_milliseconds > 0.0F && candidate_milliseconds > 0.0F &&
        speedup >= minimum_speedup;
    test.expect(performance_gate,
                distribution_label + " clears " +
                    (down_staged_probe
                         ? "direct-vs-staged down 1.005"
                         : gate_up_staged_probe
                         ? "direct-vs-staged gate/up 1.005"
                         : lm_head_staged_probe
                               ? "direct-vs-staged lm-head 1.01"
                         : lm_head_probe ? "lm-head 1.02"
                                         : "gate/up 1.01") +
                    " speedup gate");
    all_distribution_gates =
        all_distribution_gates && performance_gate;
    std::cout << "PERF_" << metric_tag << ": " << distribution_label
              << (staged_probe
                      ? " baseline_direct_xor_dual_median_ms="
                      : " baseline_preserved_exact_row_quad_median_ms=")
              << baseline_milliseconds
              << (staged_probe
                      ? " candidate_cta_staged_median_ms="
                      : " candidate_single_xor_dual_median_ms=")
              << candidate_milliseconds << " speedup=" << speedup
              << " required_speedup=" << minimum_speedup
              << " gate=" << (performance_gate ? "PASS" : "FAIL") << '\n';
  }

  if (run_performance) {
    test.expect(all_distribution_gates,
                label +
                    (down_staged_probe
                         ? " clears both down direct-vs-staged distribution "
                           "gates"
                         : gate_up_staged_probe
                         ? " clears both gate/up direct-vs-staged distribution "
                           "gates"
                         : lm_head_staged_probe
                               ? " clears both lm-head direct-vs-staged "
                                 "distribution gates"
                         : lm_head_probe
                               ? " clears both full lm-head distribution gates"
                               : " clears both full gate/up distribution gates"));
  }
  if (verify_public_dispatch) {
    test.expect(all_production_dispatch_gates,
                label + " clears graph and unaligned production gates");
  }

  // Isolate both E4M3FN NaN signs in both phases: rows 0/1 consume scale
  // column 0 with activation 0..15 (phase 0), while rows 2/3 consume scale
  // column 16 with activation 256..271 (phase 1).
  std::fill(host_scales.begin(), host_scales.end(), std::uint8_t{0U});
  host_scales[0U] = 0x7fU;
  host_scales[scale_columns] = 0xffU;
  host_scales[2U * scale_columns + 16U] = 0x7fU;
  host_scales[3U * scale_columns + 16U] = 0xffU;
  std::fill(host_activation.begin(), host_activation.end(),
            encode_bf16(0.0F));
  std::fill_n(host_activation.begin(), 16U, encode_bf16(1.0F));
  std::fill_n(host_activation.begin() + 256U, 16U, encode_bf16(1.0F));
  ready = test.cuda_ok(cudaMemsetAsync(packed.get(), 0x11, packed_count,
                                        stream),
                       label + " initialize isolated-NaN packed weights");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(scales.get(), host_scales.data(),
                                       scale_count, cudaMemcpyHostToDevice,
                                       stream),
                       label + " initialize isolated-NaN scales");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           activation.get(), host_activation.data(),
                           columns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " initialize isolated-NaN activation");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           baseline_storage.get(), 0xa5,
                           baseline.size() * sizeof(std::uint16_t), stream),
                       label + " poison isolated-NaN baseline guards");
  ready = ready && test.cuda_ok(
                       cudaMemsetAsync(
                           candidate_storage.get(), 0x5a,
                           candidate.size() * sizeof(std::uint16_t), stream),
                       label + " poison isolated-NaN candidate guards");
  if (verify_public_dispatch) {
    ready = ready && test.cuda_ok(
                         cudaMemsetAsync(
                             production_storage.get(), 0x3c,
                             production.size() * sizeof(std::uint16_t),
                             stream),
                         label + " poison isolated-NaN public guards");
  }
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_baseline()),
                       label + " isolated-NaN baseline");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_candidate()),
                       label + " isolated-NaN candidate");
  if (verify_public_dispatch) {
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_public(
                             packed.get(), activation.get(),
                             production_output)),
                         label + " isolated-NaN public");
  }
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           baseline.data(), baseline_storage.get(),
                           baseline.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy isolated-NaN baseline");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(
                           candidate.data(), candidate_storage.get(),
                           candidate.size() * sizeof(std::uint16_t),
                           cudaMemcpyDeviceToHost, stream),
                       label + " copy isolated-NaN candidate");
  if (verify_public_dispatch) {
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(
                             production.data(), production_storage.get(),
                             production.size() * sizeof(std::uint16_t),
                             cudaMemcpyDeviceToHost, stream),
                         label + " copy isolated-NaN public");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " isolated-NaN synchronize");
  if (!ready) {
    return false;
  }
  bool nan_class_and_sign = true;
  std::size_t nan_bitwise_mismatches = 0U;
  std::size_t nan_public_mismatches = 0U;
  for (std::size_t row = 0U; row < 4U; ++row) {
    const std::uint16_t baseline_bits = baseline[kGuardElements + row];
    const std::uint16_t candidate_bits = candidate[kGuardElements + row];
    nan_bitwise_mismatches += baseline_bits != candidate_bits ? 1U : 0U;
    nan_class_and_sign =
        nan_class_and_sign && is_bf16_nan(baseline_bits) &&
        is_bf16_nan(candidate_bits) &&
        ((baseline_bits ^ candidate_bits) & 0x8000U) == 0U;
    if (verify_public_dispatch) {
      const std::uint16_t production_bits =
          production[kGuardElements + row];
      nan_public_mismatches += production_bits != candidate_bits ? 1U : 0U;
      nan_class_and_sign =
          nan_class_and_sign && is_bf16_nan(production_bits) &&
          ((baseline_bits ^ production_bits) & 0x8000U) == 0U;
    }
  }
  std::size_t finite_mismatches = 0U;
  std::size_t finite_public_mismatches = 0U;
  std::size_t unexpected_nonfinite = 0U;
  for (std::size_t row = 4U; row < rows; ++row) {
    const std::uint16_t baseline_bits = baseline[kGuardElements + row];
    const std::uint16_t candidate_bits = candidate[kGuardElements + row];
    finite_mismatches += baseline_bits != candidate_bits ? 1U : 0U;
    unexpected_nonfinite += !is_bf16_finite(baseline_bits) ? 1U : 0U;
    unexpected_nonfinite += !is_bf16_finite(candidate_bits) ? 1U : 0U;
    if (verify_public_dispatch) {
      const std::uint16_t production_bits =
          production[kGuardElements + row];
      finite_public_mismatches +=
          production_bits != candidate_bits ? 1U : 0U;
      unexpected_nonfinite += !is_bf16_finite(production_bits) ? 1U : 0U;
    }
  }
  bool nan_guards_intact = true;
  for (std::size_t guard = 0U; guard < kGuardElements; ++guard) {
    nan_guards_intact =
        nan_guards_intact && baseline[guard] == kBaselineGuard &&
        baseline[kGuardElements + rows + guard] == kBaselineGuard &&
        candidate[guard] == kCandidateGuard &&
        candidate[kGuardElements + rows + guard] == kCandidateGuard;
    if (verify_public_dispatch) {
      nan_guards_intact =
          nan_guards_intact && production[guard] == kProductionGuard &&
          production[kGuardElements + rows + guard] == kProductionGuard;
    }
  }
  const bool nan_gate = nan_bitwise_mismatches == 0U &&
                        nan_class_and_sign && finite_mismatches == 0U &&
                        finite_public_mismatches == 0U &&
                        nan_public_mismatches == 0U &&
                        unexpected_nonfinite == 0U && nan_guards_intact;
  test.expect(nan_gate,
              label + " preserves both-phase signed NaNs and canaries");
  const bool overall_gate = validation_gate && all_distribution_gates &&
                            nan_gate &&
                            (!verify_public_dispatch ||
                             all_production_dispatch_gates);
  test.expect(overall_gate,
              label + (verify_public_dispatch
                           ? " clears complete production gate"
                           : run_performance ? " clears complete full gate"
                                             : " clears complete lightweight gate"));
  std::cout << metric_tag << "_NAN: classified_outputs=4"
            << " nan_bitwise_mismatches=" << nan_bitwise_mismatches << "/4"
            << (staged_probe ? " public_vs_direct_staged_nan_mismatches="
                             : " public_vs_candidate_nan_mismatches=")
            << nan_public_mismatches
            << '/' << (verify_public_dispatch ? 4U : 0U)
            << " class_and_sign="
            << (nan_class_and_sign ? "true" : "false")
            << " finite_mismatches=" << finite_mismatches << '/'
            << (rows - 4U)
            << (staged_probe ? " public_vs_direct_staged_finite_mismatches="
                             : " public_vs_candidate_finite_mismatches=")
            << finite_public_mismatches << '/'
            << (verify_public_dispatch ? rows - 4U : 0U)
            << " unexpected_nonfinite=" << unexpected_nonfinite
            << " output_guards="
            << (nan_guards_intact ? "intact" : "BAD")
            << " gate=" << (overall_gate ? "PASS" : "FAIL") << '\n';
  if (run_performance) {
    std::cout << "PERF_" << metric_tag << "_SELECTED: baseline="
              << (down_staged_probe
                      ? "preserved_down_xor_dual_direct_activation"
                      : gate_up_staged_probe
                      ? "preserved_gate_up_xor_dual_direct_activation"
                      : lm_head_staged_probe
                            ? "preserved_lm_head_xor_dual_direct_activation"
                      : lm_head_probe
                            ? "preserved_exact_row_quad_248320x5120"
                            : "preserved_exact_row_quad_17408x5120")
              << " candidate="
              << (down_staged_probe
                      ? "production_down_activation_staged"
                      : gate_up_staged_probe
                      ? "production_gate_up_activation_staged"
                      : lm_head_staged_probe
                            ? "production_lm_head_activation_staged"
                      : lm_head_probe ? "preserved_lm_head_xor_dual_baseline"
                                      : "preserved_gate_up_xor_dual_baseline")
              << " distributions=checkpoint_like:same_bank_stress"
              << " required_each=" << minimum_speedup
              << " all_correct=" << (overall_gate ? "true" : "false")
              << " gate=" << (overall_gate ? "PASS" : "FAIL") << '\n';
  }
  return overall_gate;
}

void run_nvfp4_m1_k5120_xor_dual_probe(TestContext& test,
                                        cudaStream_t stream) {
  NvFp4M1DownDualKernelResources resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_k5120_xor_dual_resources_test_cuda(
              &resources.registers_per_thread,
              &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)),
      "query NVFP4 M1 K5120 XOR-dual resources");
  const bool null_rejected =
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_k5120_xor_dual_resources_test_cuda(
              nullptr, &resources.static_shared_bytes,
              &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)) == cudaErrorInvalidValue;
  test.expect(null_rejected,
              "NVFP4 M1 K5120 XOR-dual resource query rejects null");
  const bool resource_gate =
      ready && resources.registers_per_thread <= 64 &&
      resources.static_shared_bytes <= 1'088U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block >= 256 &&
      resources.active_blocks_per_sm >= 4;
  test.expect(resource_gate,
              "NVFP4 M1 K5120 XOR-dual clears 64r/1088B/0local/active4 gate");
  std::cout << "PERF_NVFP4_M1_K5120_XOR_DUAL_RESOURCES: "
            << "registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " maximum_threads_per_block="
            << resources.maximum_threads_per_block
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!ready) {
    return;
  }

  const bool lightweight_gate = run_nvfp4_m1_k5120_xor_dual_fixture(
      test, stream, 2'048U, 512U, false,
      NvFp4M1K5120XorDualProbe::kGateUp,
      "NVFP4 M1 K5120 XOR-dual lightweight 2048x512");
  if (!nvfp4_m1_k5120_xor_dual_gate_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M1 K5120 XOR-dual gate/up full segment; set "
           "Q3X_RUN_SM87_NVFP4_M1_K5120_XOR_DUAL_GATE_PERF=1 to enable\n";
    return;
  }
  if (!resource_gate || !lightweight_gate) {
    test.expect(false,
                "NVFP4 M1 K5120 XOR-dual full run requires resource and "
                "lightweight gates");
    return;
  }
  (void)run_nvfp4_m1_k5120_xor_dual_fixture(
      test, stream, 17'408U, 5'120U, true,
      NvFp4M1K5120XorDualProbe::kGateUp,
      "NVFP4 M1 K5120 XOR-dual gate/up exact 17408x5120");
}

void run_nvfp4_m1_down_activation_staged_probe(TestContext& test,
                                                cudaStream_t stream) {
  NvFp4M1DownDualKernelResources baseline_resources{};
  NvFp4M1DownDualKernelResources candidate_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_down_xor_dual_resources_test_cuda(
              &baseline_resources.registers_per_thread,
              &baseline_resources.static_shared_bytes,
              &baseline_resources.local_bytes,
              &baseline_resources.maximum_threads_per_block,
              &baseline_resources.active_blocks_per_sm)),
      "query NVFP4 M1 down preserved XOR baseline resources");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           query_sm87_nvfp4_w4a16_m1_down_activation_staged_resources_test_cuda(
                               &candidate_resources.registers_per_thread,
                               &candidate_resources.static_shared_bytes,
                               &candidate_resources.local_bytes,
                               &candidate_resources.maximum_threads_per_block,
                               &candidate_resources.active_blocks_per_sm)),
                       "query NVFP4 M1 down activation-staged resources");
  const bool null_rejected =
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_down_activation_staged_resources_test_cuda(
              nullptr, &candidate_resources.static_shared_bytes,
              &candidate_resources.local_bytes,
              &candidate_resources.maximum_threads_per_block,
              &candidate_resources.active_blocks_per_sm)) ==
      cudaErrorInvalidValue;
  test.expect(null_rejected,
              "NVFP4 M1 down activation-staged resource query rejects null");
  constexpr std::size_t kExpectedMaximumSharedBytes =
      17'408U * sizeof(std::uint16_t) + 1'088U;
  const bool resource_gate =
      ready && baseline_resources.registers_per_thread <= 64 &&
      baseline_resources.static_shared_bytes <= 1'088U &&
      baseline_resources.local_bytes == 0U &&
      baseline_resources.maximum_threads_per_block >= 256 &&
      baseline_resources.active_blocks_per_sm >= 4 &&
      candidate_resources.registers_per_thread <= 64 &&
      candidate_resources.static_shared_bytes <= kExpectedMaximumSharedBytes &&
      candidate_resources.local_bytes == 0U &&
      candidate_resources.maximum_threads_per_block >= 256 &&
      candidate_resources.active_blocks_per_sm >= 4;
  test.expect(resource_gate,
              "NVFP4 M1 down activation-staged clears "
              "64r/35904B/0local/active4 production gate");
  std::cout << "PERF_NVFP4_M1_DOWN_ACTIVATION_STAGED_RESOURCES: "
            << "baseline_registers_per_thread="
            << baseline_resources.registers_per_thread
            << " baseline_static_shared_bytes="
            << baseline_resources.static_shared_bytes
            << " baseline_local_bytes=" << baseline_resources.local_bytes
            << " baseline_maximum_threads_per_block="
            << baseline_resources.maximum_threads_per_block
            << " baseline_active_blocks_per_sm="
            << baseline_resources.active_blocks_per_sm
            << " candidate_registers_per_thread="
            << candidate_resources.registers_per_thread
            << " candidate_static_shared_bytes="
            << candidate_resources.static_shared_bytes
            << " candidate_local_bytes=" << candidate_resources.local_bytes
            << " candidate_maximum_threads_per_block="
            << candidate_resources.maximum_threads_per_block
            << " candidate_active_blocks_per_sm="
            << candidate_resources.active_blocks_per_sm
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!ready) {
    return;
  }

  // Guard the promotion boundary: the public exact down shape must capture
  // the staged kernel, while the former production XOR kernel stays directly
  // callable as the same-binary timing baseline.
  const auto* const fake_packed =
      reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
  const auto* const fake_scales =
      reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
  const auto* const fake_activation =
      reinterpret_cast<const std::uint16_t*>(0x3'0000'0000ULL);
  auto* const fake_output =
      reinterpret_cast<std::uint16_t*>(0x4'0000'0000ULL);
  const auto capture_single_kernel =
      [&](const auto& launch, const std::string& label,
          cudaKernelNodeParams* const captured_params) {
        cudaGraph_t graph = nullptr;
        bool capture_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
            label + " begin capture");
        if (capture_ready) {
          capture_ready =
              test.cuda_ok(static_cast<cudaError_t>(launch()),
                           label + " capture launch") &&
              capture_ready;
          capture_ready =
              test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           label + " end capture") &&
              capture_ready;
        }
        std::size_t node_count = 0U;
        if (capture_ready) {
          capture_ready = test.cuda_ok(
              cudaGraphGetNodes(graph, nullptr, &node_count),
              label + " query node count");
        }
        if (capture_ready && node_count == 1U) {
          cudaGraphNode_t node = nullptr;
          std::size_t node_capacity = 1U;
          capture_ready = test.cuda_ok(
              cudaGraphGetNodes(graph, &node, &node_capacity),
              label + " get kernel node");
          capture_ready =
              capture_ready && node_capacity == 1U &&
              test.cuda_ok(cudaGraphKernelNodeGetParams(node,
                                                       captured_params),
                           label + " get kernel params");
        }
        if (graph != nullptr) {
          capture_ready =
              test.cuda_ok(cudaGraphDestroy(graph), label + " destroy graph") &&
              capture_ready;
        }
        return capture_ready && node_count == 1U;
      };
  const auto same_launch_configuration =
      [](const cudaKernelNodeParams& first,
         const cudaKernelNodeParams& second) {
        return first.func == second.func &&
               first.gridDim.x == second.gridDim.x &&
               first.gridDim.y == second.gridDim.y &&
               first.gridDim.z == second.gridDim.z &&
               first.blockDim.x == second.blockDim.x &&
               first.blockDim.y == second.blockDim.y &&
               first.blockDim.z == second.blockDim.z &&
               first.sharedMemBytes == second.sharedMemBytes;
      };
  cudaKernelNodeParams public_params{};
  cudaKernelNodeParams direct_staged_params{};
  cudaKernelNodeParams direct_xor_params{};
  const bool public_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::launch_sm87_nvfp4_w4a16_gemv_bf16_cuda(
            fake_packed, fake_scales, 1.0F / 64.0F, fake_activation, 5'120U,
            17'408U, fake_output, static_cast<void*>(stream));
      },
      "NVFP4 M1 down public production staged", &public_params);
  const bool direct_staged_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_down_activation_staged_test_cuda(
                fake_packed, fake_scales, 1.0F / 64.0F, fake_activation,
                5'120U, 17'408U, fake_output, static_cast<void*>(stream));
      },
      "NVFP4 M1 down direct production staged", &direct_staged_params);
  const bool direct_xor_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_down_xor_dual_test_cuda(
                fake_packed, fake_scales, 1.0F / 64.0F, fake_activation,
                5'120U, 17'408U, fake_output, static_cast<void*>(stream));
      },
      "NVFP4 M1 down preserved direct XOR", &direct_xor_params);
  const bool staged_dispatch_gate =
      public_captured && direct_staged_captured &&
      same_launch_configuration(public_params, direct_staged_params);
  const bool direct_xor_baseline_gate =
      direct_xor_captured && direct_staged_captured &&
      direct_xor_params.func != direct_staged_params.func;

  const auto verify_scalar_fallback_capture =
      [&](const std::uint8_t* const fallback_packed,
          const std::uint16_t* const fallback_activation,
          const std::string& fallback_label) {
        cudaKernelNodeParams public_fallback_params{};
        cudaKernelNodeParams direct_scalar_params{};
        const bool public_fallback_captured = capture_single_kernel(
            [&]() noexcept {
              return q3x::kernels::launch_sm87_nvfp4_w4a16_gemv_bf16_cuda(
                  fallback_packed, fake_scales, 1.0F / 64.0F,
                  fallback_activation, 5'120U, 17'408U, fake_output,
                  static_cast<void*>(stream));
            },
            fallback_label + " public", &public_fallback_params);
        const bool direct_scalar_captured = capture_single_kernel(
            [&]() noexcept {
              return q3x::kernels::
                  launch_sm87_nvfp4_w4a16_gemv_bf16_scalar_test_cuda(
                      fallback_packed, fake_scales, 1.0F / 64.0F,
                      fallback_activation, 5'120U, 17'408U, fake_output,
                      static_cast<void*>(stream));
            },
            fallback_label + " direct scalar", &direct_scalar_params);
        return public_fallback_captured && direct_scalar_captured &&
               same_launch_configuration(public_fallback_params,
                                         direct_scalar_params);
      };
  const bool packed_fallback_gate = verify_scalar_fallback_capture(
      reinterpret_cast<const std::uint8_t*>(
          reinterpret_cast<std::uintptr_t>(fake_packed) + 1U),
      fake_activation, "NVFP4 M1 down packed+1 fallback");
  const bool activation_fallback_gate = verify_scalar_fallback_capture(
      fake_packed,
      reinterpret_cast<const std::uint16_t*>(
          reinterpret_cast<std::uintptr_t>(fake_activation) + 2U),
      "NVFP4 M1 down activation+2 fallback");
  const bool fallback_dispatch_gate =
      packed_fallback_gate && activation_fallback_gate;
  const bool production_dispatch_gate = staged_dispatch_gate &&
                                        direct_xor_baseline_gate &&
                                        fallback_dispatch_gate;
  test.expect(production_dispatch_gate,
              "NVFP4 M1 down production staged dispatch, direct XOR baseline, "
              "and scalar fallbacks remain distinct and exact");
  std::cout << "NVFP4_M1_DOWN_ACTIVATION_STAGED_DEFAULT_GRAPH: "
            << "public_nodes=1 direct_staged_nodes=1 direct_xor_nodes=1"
            << " production_staged_identity="
            << (staged_dispatch_gate ? "true" : "false")
            << " direct_xor_distinct="
            << (direct_xor_baseline_gate ? "true" : "false")
            << " packed_fallback_scalar_identity="
            << (packed_fallback_gate ? "true" : "false")
            << " activation_fallback_scalar_identity="
            << (activation_fallback_gate ? "true" : "false")
            << " gate=" << (production_dispatch_gate ? "PASS" : "FAIL")
            << '\n';

  const bool lightweight_gate = run_nvfp4_m1_k5120_xor_dual_fixture(
      test, stream, 2'048U, 512U, false,
      NvFp4M1K5120XorDualProbe::kDownActivationStaged,
      "NVFP4 M1 down direct-vs-staged lightweight 2048x512");
  if (!nvfp4_m1_down_activation_staged_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M1 down activation-staged full segment; set "
           "Q3X_RUN_SM87_NVFP4_M1_DOWN_ACTIVATION_STAGED_PERF=1 to enable\n";
    return;
  }
  if (!resource_gate || !production_dispatch_gate || !lightweight_gate) {
    test.expect(false,
                "NVFP4 M1 down activation-staged full run requires resource, "
                "production-dispatch, and lightweight gates");
    return;
  }
  (void)run_nvfp4_m1_k5120_xor_dual_fixture(
      test, stream, 5'120U, 17'408U, true,
      NvFp4M1K5120XorDualProbe::kDownActivationStaged,
      "NVFP4 M1 down direct-vs-staged exact 5120x17408");
}

void run_nvfp4_m1_down_residual_norm_production_probe(TestContext& test,
                                                       cudaStream_t stream) {
  constexpr std::size_t kRows = 5'120U;
  constexpr std::size_t kColumns = 17'408U;
  constexpr std::size_t kPackedCount = kRows * kColumns / 2U;
  constexpr std::size_t kScaleCount = kRows * kColumns / 16U;
  constexpr std::size_t kScaleColumns = kColumns / 16U;
  constexpr std::size_t kGuardElements = 16U;
  constexpr float kWeightScale2 = 1.0F / 64.0F;
  constexpr float kEpsilon = 1.0e-6F;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 40;
  constexpr int kMeasurementRounds = 5;
  const std::string label =
      "NVFP4 M1 down+residual+centered-norm exact 5120x17408";

  NvFp4M1DownDualKernelResources resources{};
  NvFp4M1DownDualKernelResources predecessor_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_down_residual_norm_resources_cuda(
              &resources.registers_per_thread,
              &resources.static_shared_bytes, &resources.local_bytes,
              &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)),
      label + " query fused resources");
  int device = 0;
  int cooperative_launch = 0;
  int multiprocessor_count = 0;
  ready = ready && test.cuda_ok(cudaGetDevice(&device),
                                label + " query current device");
  ready = ready && test.cuda_ok(
                       cudaDeviceGetAttribute(&cooperative_launch,
                                              cudaDevAttrCooperativeLaunch,
                                              device),
                       label + " query cooperative launch support");
  ready = ready && test.cuda_ok(
                       cudaDeviceGetAttribute(&multiprocessor_count,
                                              cudaDevAttrMultiProcessorCount,
                                              device),
                       label + " query multiprocessor count");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           query_sm87_nvfp4_w4a16_m1_down_residual_norm_predecessor_resources_test_cuda(
                               &predecessor_resources.registers_per_thread,
                               &predecessor_resources.static_shared_bytes,
                               &predecessor_resources.local_bytes,
                               &predecessor_resources.maximum_threads_per_block,
                               &predecessor_resources.active_blocks_per_sm)),
                       label + " query test-only 64x256 predecessor resources");
  const bool null_rejected =
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_down_residual_norm_resources_cuda(
              nullptr, &resources.static_shared_bytes,
              &resources.local_bytes, &resources.maximum_threads_per_block,
              &resources.active_blocks_per_sm)) == cudaErrorInvalidValue;
  const bool resource_gate =
      ready && resources.registers_per_thread <= 64 &&
      resources.static_shared_bytes == 35'904U &&
      resources.local_bytes == 0U &&
      resources.maximum_threads_per_block >= 512 &&
      resources.active_blocks_per_sm >= 2 && cooperative_launch != 0 &&
      multiprocessor_count > 0 &&
      multiprocessor_count * resources.active_blocks_per_sm >= 32 &&
      null_rejected;
  const bool predecessor_null_rejected =
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_down_residual_norm_predecessor_resources_test_cuda(
              nullptr, &predecessor_resources.static_shared_bytes,
              &predecessor_resources.local_bytes,
              &predecessor_resources.maximum_threads_per_block,
              &predecessor_resources.active_blocks_per_sm)) ==
      cudaErrorInvalidValue;
  const bool predecessor_resource_gate =
      ready && predecessor_resources.registers_per_thread == 64 &&
      predecessor_resources.static_shared_bytes == 35'904U &&
      predecessor_resources.local_bytes == 0U &&
      predecessor_resources.maximum_threads_per_block >= 256 &&
      predecessor_resources.active_blocks_per_sm == 4 &&
      cooperative_launch != 0 && multiprocessor_count > 0 &&
      multiprocessor_count * predecessor_resources.active_blocks_per_sm >= 64 &&
      predecessor_null_rejected;
  test.expect(resource_gate,
              label + " production 32x512 clears cooperative resource gate");
  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PRODUCTION_RESOURCES: "
            << "registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " maximum_threads_per_block="
            << resources.maximum_threads_per_block
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " cooperative_launch=" << cooperative_launch
            << " multiprocessor_count=" << multiprocessor_count
            << " resident_grid_capacity="
            << multiprocessor_count * resources.active_blocks_per_sm
            << " null_query_rejected="
            << (null_rejected ? "true" : "false")
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  test.expect(predecessor_resource_gate,
              label + " test-only 64x256 predecessor clears resource gate");
  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PREDECESSOR_RESOURCES: "
            << "registers_per_thread="
            << predecessor_resources.registers_per_thread
            << " static_shared_bytes="
            << predecessor_resources.static_shared_bytes
            << " local_bytes=" << predecessor_resources.local_bytes
            << " maximum_threads_per_block="
            << predecessor_resources.maximum_threads_per_block
            << " active_blocks_per_sm="
            << predecessor_resources.active_blocks_per_sm
            << " cooperative_launch=" << cooperative_launch
            << " multiprocessor_count=" << multiprocessor_count
            << " resident_grid_capacity="
            << multiprocessor_count *
                   predecessor_resources.active_blocks_per_sm
            << " null_query_rejected="
            << (predecessor_null_rejected ? "true" : "false")
            << " gate=" << (predecessor_resource_gate ? "PASS" : "FAIL")
            << '\n';
  if (!ready) {
    return;
  }

  // Production capture must remain a single 32x512 cooperative kernel node.
  const auto* const fake_packed =
      reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
  const auto* const fake_scales =
      reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
  const auto* const fake_activation =
      reinterpret_cast<const std::uint16_t*>(0x3'0000'0000ULL);
  const auto* const fake_left =
      reinterpret_cast<const std::uint16_t*>(0x4'0000'0000ULL);
  const auto* const fake_weight =
      reinterpret_cast<const std::uint16_t*>(0x5'0000'0000ULL);
  auto* const fake_raw =
      reinterpret_cast<std::uint16_t*>(0x6'0000'0000ULL);
  auto* const fake_residual =
      reinterpret_cast<std::uint16_t*>(0x7'0000'0000ULL);
  auto* const fake_normalized =
      reinterpret_cast<std::uint16_t*>(0x8'0000'0000ULL);
  cudaGraph_t capture_graph = nullptr;
  bool graph_ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin cooperative capture");
  if (graph_ready) {
    graph_ready = test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_nvfp4_w4a16_down_residual_norm_bf16_cuda(
                fake_packed, fake_scales, kWeightScale2, fake_activation,
                fake_left, fake_weight, kEpsilon, kRows, kColumns, fake_raw,
                fake_residual, fake_normalized, static_cast<void*>(stream))),
        label + " capture cooperative launch");
    graph_ready =
        test.cuda_ok(cudaStreamEndCapture(stream, &capture_graph),
                     label + " end cooperative capture") &&
        graph_ready;
  }
  std::size_t node_count = 0U;
  cudaKernelNodeParams kernel_params{};
  if (graph_ready) {
    graph_ready = test.cuda_ok(
        cudaGraphGetNodes(capture_graph, nullptr, &node_count),
        label + " query capture nodes");
  }
  if (graph_ready && node_count == 1U) {
    cudaGraphNode_t node = nullptr;
    std::size_t capacity = 1U;
    graph_ready = test.cuda_ok(
        cudaGraphGetNodes(capture_graph, &node, &capacity),
        label + " get capture node");
    graph_ready = graph_ready && capacity == 1U &&
                  test.cuda_ok(cudaGraphKernelNodeGetParams(
                                   node, &kernel_params),
                               label + " get capture kernel params");
  }
  const bool graph_gate =
      graph_ready && node_count == 1U && kernel_params.func != nullptr &&
      kernel_params.gridDim.x == 32U &&
      kernel_params.gridDim.y == 1U && kernel_params.gridDim.z == 1U &&
      kernel_params.blockDim.x == 512U && kernel_params.blockDim.y == 1U &&
      kernel_params.blockDim.z == 1U && kernel_params.sharedMemBytes == 0U;
  test.expect(graph_gate,
              label + " production captures one cooperative 32x512 node");
  if (capture_graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(capture_graph),
                       label + " destroy capture graph");
  }
  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PRODUCTION_GRAPH: nodes="
            << node_count << " grid_x=" << kernel_params.gridDim.x
            << " block_x=" << kernel_params.blockDim.x
            << " dynamic_shared_bytes=" << kernel_params.sharedMemBytes
            << " gate=" << (graph_gate ? "PASS" : "FAIL") << '\n';

  cudaGraph_t predecessor_capture_graph = nullptr;
  bool predecessor_graph_ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin test-only 64x256 predecessor capture");
  if (predecessor_graph_ready) {
    predecessor_graph_ready = test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_nvfp4_w4a16_down_residual_norm_predecessor_test_cuda(
                fake_packed, fake_scales, kWeightScale2, fake_activation,
                fake_left, fake_weight, kEpsilon, kRows, kColumns, fake_raw,
                fake_residual, fake_normalized,
                static_cast<void*>(stream))),
        label + " capture test-only 64x256 predecessor launch");
    predecessor_graph_ready =
        test.cuda_ok(
            cudaStreamEndCapture(stream, &predecessor_capture_graph),
            label + " end test-only 64x256 predecessor capture") &&
        predecessor_graph_ready;
  }
  std::size_t predecessor_node_count = 0U;
  cudaKernelNodeParams predecessor_kernel_params{};
  if (predecessor_graph_ready) {
    predecessor_graph_ready = test.cuda_ok(
        cudaGraphGetNodes(predecessor_capture_graph, nullptr,
                          &predecessor_node_count),
        label + " query test-only 64x256 predecessor nodes");
  }
  if (predecessor_graph_ready && predecessor_node_count == 1U) {
    cudaGraphNode_t node = nullptr;
    std::size_t capacity = 1U;
    predecessor_graph_ready = test.cuda_ok(
        cudaGraphGetNodes(predecessor_capture_graph, &node, &capacity),
        label + " get test-only 64x256 predecessor node");
    predecessor_graph_ready =
        predecessor_graph_ready && capacity == 1U &&
        test.cuda_ok(cudaGraphKernelNodeGetParams(
                         node, &predecessor_kernel_params),
                     label + " get test-only 64x256 predecessor params");
  }
  const bool predecessor_graph_gate =
      predecessor_graph_ready && predecessor_node_count == 1U &&
      predecessor_kernel_params.func != nullptr &&
      predecessor_kernel_params.func != kernel_params.func &&
      predecessor_kernel_params.gridDim.x == 64U &&
      predecessor_kernel_params.gridDim.y == 1U &&
      predecessor_kernel_params.gridDim.z == 1U &&
      predecessor_kernel_params.blockDim.x == 256U &&
      predecessor_kernel_params.blockDim.y == 1U &&
      predecessor_kernel_params.blockDim.z == 1U &&
      predecessor_kernel_params.sharedMemBytes == 0U;
  test.expect(predecessor_graph_gate,
              label + " test-only 64x256 predecessor is distinct");
  if (predecessor_capture_graph != nullptr) {
    (void)test.cuda_ok(cudaGraphDestroy(predecessor_capture_graph),
                       label + " destroy test-only predecessor graph");
  }
  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PREDECESSOR_GRAPH: "
            << "production_grid=" << kernel_params.gridDim.x
            << " production_block=" << kernel_params.blockDim.x
            << " predecessor_nodes=" << predecessor_node_count
            << " predecessor_grid=" << predecessor_kernel_params.gridDim.x
            << " predecessor_block=" << predecessor_kernel_params.blockDim.x
            << " distinct_function="
            << (predecessor_kernel_params.func != kernel_params.func ? "true"
                                                                     : "false")
            << " dynamic_shared_bytes="
            << predecessor_kernel_params.sharedMemBytes
            << " gate=" << (predecessor_graph_gate ? "PASS" : "FAIL")
            << '\n';

  const auto public_status =
      [&](const std::uint8_t* const packed,
          const std::uint8_t* const scales, const float scale,
          const std::uint16_t* const activation,
          const std::uint16_t* const left,
          const std::uint16_t* const weight, const float epsilon,
          const std::size_t rows, const std::size_t columns,
          std::uint16_t* const raw, std::uint16_t* const residual,
          std::uint16_t* const normalized) noexcept {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_down_residual_norm_bf16_cuda(
                packed, scales, scale, activation, left, weight, epsilon,
                rows, columns, raw, residual, normalized,
                static_cast<void*>(stream));
      };
  const auto predecessor_status =
      [&](const std::uint8_t* const packed,
          const std::uint8_t* const scales, const float scale,
          const std::uint16_t* const activation,
          const std::uint16_t* const left,
          const std::uint16_t* const weight, const float epsilon,
          const std::size_t rows, const std::size_t columns,
          std::uint16_t* const raw, std::uint16_t* const residual,
          std::uint16_t* const normalized) noexcept {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_down_residual_norm_predecessor_test_cuda(
                packed, scales, scale, activation, left, weight, epsilon,
                rows, columns, raw, residual, normalized,
                static_cast<void*>(stream));
      };
  std::size_t invalid_case_count = 0U;
  bool invalid_zero_node_gate = true;
  const auto expect_invalid_zero_node =
      [&](const auto& launch, const std::string& reason) {
        cudaGraph_t graph = nullptr;
        bool capture_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
            label + " begin invalid capture: " + reason);
        int status = static_cast<int>(cudaErrorUnknown);
        if (capture_ready) {
          status = launch();
          capture_ready =
              test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           label + " end invalid capture: " + reason) &&
              capture_ready;
        }
        std::size_t nodes = 0U;
        if (capture_ready && graph != nullptr) {
          capture_ready =
              test.cuda_ok(cudaGraphGetNodes(graph, nullptr, &nodes),
                           label + " query invalid nodes: " + reason) &&
              capture_ready;
        }
        const bool case_gate =
            capture_ready && status == static_cast<int>(cudaErrorInvalidValue) &&
            nodes == 0U;
        test.expect(case_gate,
                    label + " rejects before enqueue: " + reason);
        invalid_zero_node_gate = invalid_zero_node_gate && case_gate;
        ++invalid_case_count;
        if (graph != nullptr) {
          (void)test.cuda_ok(cudaGraphDestroy(graph),
                             label + " destroy invalid graph: " + reason);
        }
      };

  expect_invalid_zero_node(
      [&]() noexcept {
        return public_status(
            fake_packed, fake_scales, kWeightScale2, fake_activation,
