  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PREDECESSOR_INVALID: cases="
            << invalid_case_count << " zero_nodes="
            << (predecessor_invalid_zero_node_gate ? "true" : "false")
            << " gate="
            << (predecessor_invalid_zero_node_gate ? "PASS" : "FAIL")
            << '\n';

  const bool production_contract_gate =
      resource_gate && graph_gate && production_invalid_zero_node_gate;
  const bool predecessor_contract_gate =
      predecessor_resource_gate && predecessor_graph_gate &&
      predecessor_invalid_zero_node_gate;
  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PRODUCTION_CONTRACT: nodes="
            << node_count << " grid=" << kernel_params.gridDim.x
            << " block=" << kernel_params.blockDim.x
            << " registers_per_thread=" << resources.registers_per_thread
            << " static_shared_bytes=" << resources.static_shared_bytes
            << " local_bytes=" << resources.local_bytes
            << " active_blocks_per_sm=" << resources.active_blocks_per_sm
            << " cooperative_launch=" << cooperative_launch
            << " resident_grid_capacity="
            << multiprocessor_count * resources.active_blocks_per_sm
            << " invalid_cases=" << production_invalid_case_count
            << " invalid_zero_node_gate="
            << (production_invalid_zero_node_gate ? "PASS" : "FAIL")
            << " gate=" << (production_contract_gate ? "PASS" : "FAIL")
            << '\n';

  if (!production_contract_gate || !predecessor_contract_gate) {
    test.expect(false,
                label + " exact run requires predecessor/production contracts");
    return;
  }

  std::array<std::uint8_t, kNvFp4M1DownDualFixturePeriod> packed_pattern{};
  for (std::size_t index = 0U; index < packed_pattern.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 5U + (index >> 2U) * 3U + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 7U + (index >> 3U) * 5U + 9U) & 0x0fU);
    packed_pattern[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
  }
  std::vector<std::uint8_t> host_scales(kScaleCount);
  fill_nvfp4_m1_down_dual_scale_distribution(
      host_scales, kScaleColumns,
      NvFp4M1ScaleDistribution::kCheckpointLike);
  std::vector<std::uint16_t> host_activation(kColumns);
  std::vector<std::uint16_t> host_left(kRows);
  std::vector<std::uint16_t> host_weight(kRows);
  for (std::size_t index = 0U; index < kColumns; ++index) {
    const int centered =
        static_cast<int>((index * 19U + (index >> 3U) * 7U + 11U) %
                         127U) -
        63;
    host_activation[index] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }
  for (std::size_t index = 0U; index < kRows; ++index) {
    const int left_centered =
        static_cast<int>((index * 23U + (index >> 2U) * 5U + 3U) % 257U) -
        128;
    const int weight_centered =
        static_cast<int>((index * 17U + (index >> 4U) * 11U + 7U) % 97U) -
        48;
    host_left[index] =
        encode_bf16(static_cast<float>(left_centered) / 128.0F);
    host_weight[index] =
        encode_bf16(static_cast<float>(weight_centered) / 512.0F);
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> residual_left;
  DeviceBuffer<std::uint16_t> norm_weight;
  DeviceBuffer<std::uint16_t> baseline_raw_storage;
  DeviceBuffer<std::uint16_t> baseline_residual_storage;
  DeviceBuffer<std::uint16_t> baseline_norm_storage;
  DeviceBuffer<std::uint16_t> candidate_raw_storage;
  DeviceBuffer<std::uint16_t> candidate_residual_storage;
  DeviceBuffer<std::uint16_t> candidate_norm_storage;
  ready = test.cuda_ok(packed.allocate(kPackedCount),
                       label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(kScaleCount),
                                label + " allocate scales");
  ready = ready && test.cuda_ok(activation.allocate(kColumns),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(residual_left.allocate(kRows),
                                label + " allocate residual left");
  ready = ready && test.cuda_ok(norm_weight.allocate(kRows),
                                label + " allocate norm weight");
  const auto allocate_guarded =
      [&](DeviceBuffer<std::uint16_t>& buffer, const std::string& name) {
        return test.cuda_ok(buffer.allocate(kRows + 2U * kGuardElements),
                            label + " allocate guarded " + name);
      };
  ready = ready && allocate_guarded(baseline_raw_storage, "baseline raw");
  ready = ready &&
          allocate_guarded(baseline_residual_storage, "baseline residual");
  ready = ready && allocate_guarded(baseline_norm_storage, "baseline norm");
  ready = ready && allocate_guarded(candidate_raw_storage, "candidate raw");
  ready = ready &&
          allocate_guarded(candidate_residual_storage, "candidate residual");
  ready = ready && allocate_guarded(candidate_norm_storage, "candidate norm");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(packed.get(), packed_pattern.data(),
                                       packed_pattern.size(),
                                       cudaMemcpyHostToDevice, stream),
                       label + " seed packed weights");
  for (std::size_t initialized = packed_pattern.size();
       ready && initialized < kPackedCount;) {
    const std::size_t copy_bytes =
        std::min(initialized, kPackedCount - initialized);
    ready = test.cuda_ok(
        cudaMemcpyAsync(packed.get() + initialized, packed.get(), copy_bytes,
                        cudaMemcpyDeviceToDevice, stream),
        label + " expand packed weights");
    initialized += copy_bytes;
  }
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(scales.get(), host_scales.data(),
                                       kScaleCount, cudaMemcpyHostToDevice,
                                       stream),
                       label + " upload scales");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(activation.get(), host_activation.data(),
                                       kColumns * sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload activation");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(residual_left.get(), host_left.data(),
                                       kRows * sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload residual left");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(norm_weight.get(), host_weight.data(),
                                       kRows * sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload norm weight");
  if (!ready) {
    return;
  }

  std::uint16_t* const baseline_raw =
      baseline_raw_storage.get() + kGuardElements;
  std::uint16_t* const baseline_residual =
      baseline_residual_storage.get() + kGuardElements;
  std::uint16_t* const baseline_norm =
      baseline_norm_storage.get() + kGuardElements;
  std::uint16_t* const candidate_raw =
      candidate_raw_storage.get() + kGuardElements;
  std::uint16_t* const candidate_residual =
      candidate_residual_storage.get() + kGuardElements;
  std::uint16_t* const candidate_norm =
      candidate_norm_storage.get() + kGuardElements;
  const auto launch_baseline = [&]() noexcept -> int {
    int status = q3x::kernels::
        launch_sm87_nvfp4_w4a16_gemv_bf16_down_activation_staged_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(),
            kRows, kColumns, baseline_raw, static_cast<void*>(stream));
    if (status != static_cast<int>(cudaSuccess)) {
      return status;
    }
    return q3x::runtime::launch_residual_add_centered_rms_norm_5120_cuda(
        residual_left.get(), baseline_raw, norm_weight.get(), kEpsilon,
        baseline_residual, baseline_norm, static_cast<void*>(stream));
  };
  const auto launch_production = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_down_residual_norm_bf16_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(),
            residual_left.get(), norm_weight.get(), kEpsilon, kRows, kColumns,
            candidate_raw, candidate_residual, candidate_norm,
            static_cast<void*>(stream));
  };
  const auto launch_predecessor = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_down_residual_norm_predecessor_test_cuda(
            packed.get(), scales.get(), kWeightScale2, activation.get(),
            residual_left.get(), norm_weight.get(), kEpsilon, kRows, kColumns,
            baseline_raw, baseline_residual, baseline_norm,
            static_cast<void*>(stream));
  };
  const auto poison = [&](DeviceBuffer<std::uint16_t>& storage,
                          const int byte, const std::string& operation) {
    return test.cuda_ok(
        cudaMemsetAsync(storage.get(), byte,
                        (kRows + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        operation);
  };
  ready = poison(baseline_raw_storage, 0xa1, label + " poison baseline raw");
  ready = ready && poison(baseline_residual_storage, 0xb2,
                           label + " poison baseline residual");
  ready = ready && poison(baseline_norm_storage, 0xc3,
                           label + " poison baseline norm");
  ready = ready && poison(candidate_raw_storage, 0xd4,
                           label + " poison candidate raw");
  ready = ready && poison(candidate_residual_storage, 0xe5,
                           label + " poison candidate residual");
  ready = ready && poison(candidate_norm_storage, 0xf6,
                           label + " poison candidate norm");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                                label + " launch baseline chain");
  ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_production()),
                                label + " launch fused production 32x512");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " correctness synchronize");
  if (!ready) {
    return;
  }

  const std::size_t guarded_count = kRows + 2U * kGuardElements;
  std::vector<std::uint16_t> baseline_raw_host(guarded_count);
  std::vector<std::uint16_t> baseline_residual_host(guarded_count);
  std::vector<std::uint16_t> baseline_norm_host(guarded_count);
  std::vector<std::uint16_t> candidate_raw_host(guarded_count);
  std::vector<std::uint16_t> candidate_residual_host(guarded_count);
  std::vector<std::uint16_t> candidate_norm_host(guarded_count);
  const auto copy_output = [&](std::vector<std::uint16_t>& host,
                               const DeviceBuffer<std::uint16_t>& device,
                               const std::string& operation) {
    return test.cuda_ok(
        cudaMemcpyAsync(host.data(), device.get(),
                        guarded_count * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        operation);
  };
  ready = copy_output(baseline_raw_host, baseline_raw_storage,
                      label + " copy baseline raw");
  ready = ready && copy_output(baseline_residual_host,
                               baseline_residual_storage,
                               label + " copy baseline residual");
  ready = ready && copy_output(baseline_norm_host, baseline_norm_storage,
                               label + " copy baseline norm");
  ready = ready && copy_output(candidate_raw_host, candidate_raw_storage,
                               label + " copy candidate raw");
  ready = ready && copy_output(candidate_residual_host,
                               candidate_residual_storage,
                               label + " copy candidate residual");
  ready = ready && copy_output(candidate_norm_host, candidate_norm_storage,
                               label + " copy candidate norm");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " output copy synchronize");
  if (!ready) {
    return;
  }
  const auto mismatch_count =
      [&](const std::vector<std::uint16_t>& expected,
          const std::vector<std::uint16_t>& actual) {
        std::size_t mismatches = 0U;
        for (std::size_t index = 0U; index < kRows; ++index) {
          mismatches += expected[kGuardElements + index] !=
                                actual[kGuardElements + index]
                            ? 1U
                            : 0U;
        }
        return mismatches;
      };
  const auto guards_intact =
      [&](const std::vector<std::uint16_t>& output,
          const std::uint16_t expected) {
        for (std::size_t index = 0U; index < kGuardElements; ++index) {
          if (output[index] != expected ||
              output[kGuardElements + kRows + index] != expected) {
            return false;
          }
        }
        return true;
      };

  const std::size_t raw_mismatches =
      mismatch_count(baseline_raw_host, candidate_raw_host);
  const std::size_t residual_mismatches =
      mismatch_count(baseline_residual_host, candidate_residual_host);
  const std::size_t norm_mismatches =
      mismatch_count(baseline_norm_host, candidate_norm_host);
  const bool guard_gate =
      guards_intact(baseline_raw_host, 0xa1a1U) &&
      guards_intact(baseline_residual_host, 0xb2b2U) &&
      guards_intact(baseline_norm_host, 0xc3c3U) &&
      guards_intact(candidate_raw_host, 0xd4d4U) &&
      guards_intact(candidate_residual_host, 0xe5e5U) &&
      guards_intact(candidate_norm_host, 0xf6f6U);
  const bool correctness_gate = raw_mismatches == 0U &&
                                residual_mismatches == 0U &&
                                norm_mismatches == 0U && guard_gate;
  test.expect(correctness_gate,
              label + " preserves raw/residual/norm BF16 bitwise");
  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PRODUCTION_DIFF: "
            << "raw_bitwise_mismatches=" << raw_mismatches << '/' << kRows
            << " residual_bitwise_mismatches=" << residual_mismatches << '/'
            << kRows << " norm_bitwise_mismatches=" << norm_mismatches << '/'
            << kRows << " guards=" << (guard_gate ? "intact" : "BAD")
            << " gate=" << (correctness_gate ? "PASS" : "FAIL") << '\n';
  if (!correctness_gate) {
    return;
  }

  ready = poison(baseline_raw_storage, 0xa1,
                 label + " poison predecessor finite raw");
  ready = ready && poison(baseline_residual_storage, 0xb2,
                           label + " poison predecessor finite residual");
  ready = ready && poison(baseline_norm_storage, 0xc3,
                           label + " poison predecessor finite norm");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(launch_predecessor()),
                       label + " launch test-only predecessor 64x256 finite");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " predecessor finite synchronize");
  ready = ready && copy_output(baseline_raw_host, baseline_raw_storage,
                               label + " copy predecessor finite raw");
  ready = ready && copy_output(baseline_residual_host,
                               baseline_residual_storage,
                               label + " copy predecessor finite residual");
  ready = ready && copy_output(baseline_norm_host, baseline_norm_storage,
                               label + " copy predecessor finite norm");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " predecessor finite copy synchronize");
  if (!ready) {
    return;
  }
  const std::size_t predecessor_raw_mismatches =
      mismatch_count(candidate_raw_host, baseline_raw_host);
  const std::size_t predecessor_residual_mismatches =
      mismatch_count(candidate_residual_host, baseline_residual_host);
  const std::size_t predecessor_norm_mismatches =
      mismatch_count(candidate_norm_host, baseline_norm_host);
  const bool predecessor_guards =
      guards_intact(baseline_raw_host, 0xa1a1U) &&
      guards_intact(baseline_residual_host, 0xb2b2U) &&
      guards_intact(baseline_norm_host, 0xc3c3U);
  const std::vector<std::uint16_t> production_first_raw = candidate_raw_host;
  const std::vector<std::uint16_t> production_first_residual =
      candidate_residual_host;
  const std::vector<std::uint16_t> production_first_norm = candidate_norm_host;

  ready = test.cuda_ok(static_cast<cudaError_t>(launch_production()),
                       label + " replay production 32x512 finite");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " production replay synchronize");
  ready = ready && copy_output(candidate_raw_host, candidate_raw_storage,
                               label + " copy production replay raw");
  ready = ready && copy_output(candidate_residual_host,
                               candidate_residual_storage,
                               label + " copy production replay residual");
  ready = ready && copy_output(candidate_norm_host, candidate_norm_storage,
                               label + " copy production replay norm");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " production replay copy synchronize");
  if (!ready) {
    return;
  }
  const std::size_t production_replay_mismatches =
      mismatch_count(production_first_raw, candidate_raw_host) +
      mismatch_count(production_first_residual, candidate_residual_host) +
      mismatch_count(production_first_norm, candidate_norm_host);
  const bool production_replay_guards =
      guards_intact(candidate_raw_host, 0xd4d4U) &&
      guards_intact(candidate_residual_host, 0xe5e5U) &&
      guards_intact(candidate_norm_host, 0xf6f6U);
  const bool predecessor_production_gate =
      predecessor_raw_mismatches == 0U &&
      predecessor_residual_mismatches == 0U &&
      predecessor_norm_mismatches == 0U &&
      production_replay_mismatches == 0U && predecessor_guards &&
      production_replay_guards;
  test.expect(predecessor_production_gate,
              label + " predecessor and production preserve bits/replay");
  std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PREDECESSOR_PRODUCTION_DIFF: "
            << "raw_bitwise_mismatches=" << predecessor_raw_mismatches << '/'
            << kRows << " residual_bitwise_mismatches="
            << predecessor_residual_mismatches << '/' << kRows
            << " norm_bitwise_mismatches=" << predecessor_norm_mismatches << '/'
            << kRows << " replay_bitwise_mismatches="
            << production_replay_mismatches << '/' << (3U * kRows)
            << " guards="
            << (predecessor_guards && production_replay_guards ? "intact"
                                                               : "BAD")
            << " gate=" << (predecessor_production_gate ? "PASS" : "FAIL")
            << '\n';
  if (!predecessor_production_gate) {
    return;
  }

  const auto run_nonfinite_fixture =
      [&](const std::vector<std::uint16_t>& left_values,
          const std::vector<std::uint16_t>& weight_values,
          const std::string& fixture,
          const auto& semantic_check) {
        bool fixture_ready = test.cuda_ok(
            cudaMemcpyAsync(residual_left.get(), left_values.data(),
                            kRows * sizeof(std::uint16_t),
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture + " residual input");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaMemcpyAsync(norm_weight.get(), weight_values.data(),
                            kRows * sizeof(std::uint16_t),
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture + " norm weight");
        fixture_ready = fixture_ready &&
                        poison(baseline_raw_storage, 0xa1,
                               label + " poison " + fixture +
                                   " baseline raw");
        fixture_ready = fixture_ready &&
                        poison(baseline_residual_storage, 0xb2,
                               label + " poison " + fixture +
                                   " baseline residual");
        fixture_ready = fixture_ready &&
                        poison(baseline_norm_storage, 0xc3,
                               label + " poison " + fixture +
                                   " baseline norm");
        fixture_ready = fixture_ready &&
                        poison(candidate_raw_storage, 0xd4,
                               label + " poison " + fixture +
                                   " candidate raw");
        fixture_ready = fixture_ready &&
                        poison(candidate_residual_storage, 0xe5,
                               label + " poison " + fixture +
                                   " candidate residual");
        fixture_ready = fixture_ready &&
                        poison(candidate_norm_storage, 0xf6,
                               label + " poison " + fixture +
                                   " candidate norm");
        fixture_ready = fixture_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_predecessor()),
            label + " launch " + fixture + " predecessor 64x256");
        fixture_ready = fixture_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_production()),
            label + " launch " + fixture + " production 32x512");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            label + " synchronize " + fixture);
        if (!fixture_ready) {
          return false;
        }

        fixture_ready = copy_output(
            baseline_raw_host, baseline_raw_storage,
            label + " copy " + fixture + " baseline raw");
        fixture_ready = fixture_ready && copy_output(
            baseline_residual_host, baseline_residual_storage,
            label + " copy " + fixture + " baseline residual");
        fixture_ready = fixture_ready && copy_output(
            baseline_norm_host, baseline_norm_storage,
            label + " copy " + fixture + " baseline norm");
        fixture_ready = fixture_ready && copy_output(
            candidate_raw_host, candidate_raw_storage,
            label + " copy " + fixture + " production raw");
        fixture_ready = fixture_ready && copy_output(
            candidate_residual_host, candidate_residual_storage,
            label + " copy " + fixture + " production residual");
        fixture_ready = fixture_ready && copy_output(
            candidate_norm_host, candidate_norm_storage,
            label + " copy " + fixture + " production norm");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            label + " copy synchronize " + fixture);
        if (!fixture_ready) {
          return false;
        }

        const std::size_t fixture_raw_mismatches =
            mismatch_count(baseline_raw_host, candidate_raw_host);
        const std::size_t fixture_residual_mismatches =
            mismatch_count(baseline_residual_host, candidate_residual_host);
        const std::size_t fixture_norm_mismatches =
            mismatch_count(baseline_norm_host, candidate_norm_host);
        const bool fixture_guards =
            guards_intact(baseline_raw_host, 0xa1a1U) &&
            guards_intact(baseline_residual_host, 0xb2b2U) &&
            guards_intact(baseline_norm_host, 0xc3c3U) &&
            guards_intact(candidate_raw_host, 0xd4d4U) &&
            guards_intact(candidate_residual_host, 0xe5e5U) &&
            guards_intact(candidate_norm_host, 0xf6f6U);
        const bool semantic_gate = semantic_check(
            baseline_residual_host, baseline_norm_host,
            candidate_residual_host, candidate_norm_host);
        const bool fixture_gate =
            fixture_raw_mismatches == 0U &&
            fixture_residual_mismatches == 0U &&
            fixture_norm_mismatches == 0U && fixture_guards && semantic_gate;
        test.expect(fixture_gate,
                    label + " " + fixture +
                        " preserves bitwise/class/sign semantics");
        std::cout << "NVFP4_M1_DOWN_RESIDUAL_NORM_PREDECESSOR_PRODUCTION_NONFINITE: "
                  << "fixture=" << fixture
                  << " raw_bitwise_mismatches=" << fixture_raw_mismatches
                  << '/' << kRows
                  << " residual_bitwise_mismatches="
                  << fixture_residual_mismatches << '/' << kRows
                  << " norm_bitwise_mismatches=" << fixture_norm_mismatches
                  << '/' << kRows
                  << " class_sign=" << (semantic_gate ? "PASS" : "FAIL")
                  << " guards=" << (fixture_guards ? "intact" : "BAD")
                  << " gate=" << (fixture_gate ? "PASS" : "FAIL") << '\n';
        return fixture_gate;
      };

  std::vector<std::uint16_t> residual_nonfinite_left = host_left;
  residual_nonfinite_left[0U] = 0x7f80U;
  residual_nonfinite_left[1U] = 0xff80U;
  residual_nonfinite_left[2U] = 0x7fc1U;
  residual_nonfinite_left[3U] = 0xffc1U;
  const bool residual_nonfinite_gate = run_nonfinite_fixture(
      residual_nonfinite_left, host_weight, "residual_signed_nonfinite",
      [&](const std::vector<std::uint16_t>& baseline_residual_bits,
          const std::vector<std::uint16_t>& baseline_norm_bits,
          const std::vector<std::uint16_t>& production_residual_bits,
          const std::vector<std::uint16_t>& production_norm_bits) {
        const auto residual_at = [&](const auto& values,
                                     const std::size_t index) {
          return values[kGuardElements + index];
        };
        bool class_sign =
            residual_at(baseline_residual_bits, 0U) == 0x7f80U &&
            residual_at(production_residual_bits, 0U) == 0x7f80U &&
            residual_at(baseline_residual_bits, 1U) == 0xff80U &&
            residual_at(production_residual_bits, 1U) == 0xff80U;
        for (std::size_t index = 2U; index < 4U; ++index) {
          const std::uint16_t baseline_bits =
              residual_at(baseline_residual_bits, index);
          const std::uint16_t production_bits =
              residual_at(production_residual_bits, index);
          class_sign = class_sign && is_bf16_nan(baseline_bits) &&
                       is_bf16_nan(production_bits) &&
                       ((baseline_bits ^ production_bits) & 0x8000U) == 0U;
        }
        for (std::size_t index = 0U; index < 8U; ++index) {
          const std::uint16_t baseline_bits =
              residual_at(baseline_norm_bits, index);
          const std::uint16_t production_bits =
              residual_at(production_norm_bits, index);
          class_sign = class_sign && is_bf16_nan(baseline_bits) &&
                       is_bf16_nan(production_bits) &&
                       ((baseline_bits ^ production_bits) & 0x8000U) == 0U;
        }
        for (std::size_t index = 0U; index < 4U; ++index) {
          class_sign =
              class_sign &&
              (((residual_at(baseline_residual_bits, index) ^
                  residual_at(production_residual_bits, index)) &
                 0x8000U) == 0U);
        }
        return class_sign;
      });

  std::array<std::size_t, 4U> norm_nonfinite_indices{};
  std::size_t norm_index_count = 0U;
  for (std::size_t index = 0U;
       index < kRows && norm_index_count < norm_nonfinite_indices.size();
       ++index) {
    const std::uint16_t bits =
        candidate_residual_host[kGuardElements + index];
    if (is_bf16_finite(bits) && (bits & 0x7fffU) != 0U) {
      norm_nonfinite_indices[norm_index_count++] = index;
    }
  }
  bool norm_nonfinite_gate = norm_index_count == norm_nonfinite_indices.size();
  std::vector<std::uint16_t> nonfinite_weight = host_weight;
  if (norm_nonfinite_gate) {
    nonfinite_weight[norm_nonfinite_indices[0U]] = 0x7f80U;
    nonfinite_weight[norm_nonfinite_indices[1U]] = 0xff80U;
    nonfinite_weight[norm_nonfinite_indices[2U]] = 0x7fc1U;
    nonfinite_weight[norm_nonfinite_indices[3U]] = 0xffc1U;
    norm_nonfinite_gate = run_nonfinite_fixture(
        host_left, nonfinite_weight, "norm_weight_signed_nonfinite",
        [&](const std::vector<std::uint16_t>& baseline_residual_bits,
            const std::vector<std::uint16_t>& baseline_norm_bits,
            const std::vector<std::uint16_t>& production_residual_bits,
            const std::vector<std::uint16_t>& production_norm_bits) {
          bool class_sign = true;
          for (std::size_t special = 0U; special < 4U; ++special) {
            const std::size_t guarded =
                kGuardElements + norm_nonfinite_indices[special];
            const std::uint16_t baseline_bits = baseline_norm_bits[guarded];
            const std::uint16_t production_bits =
                production_norm_bits[guarded];
            class_sign =
                class_sign &&
                ((baseline_bits ^ production_bits) & 0x8000U) == 0U &&
                baseline_residual_bits[guarded] ==
                    production_residual_bits[guarded];
            if (special < 2U) {
              class_sign =
                  class_sign && !is_bf16_finite(production_bits) &&
                  !is_bf16_nan(production_bits);
              const bool residual_negative =
                  (production_residual_bits[guarded] & 0x8000U) != 0U;
              const bool expected_negative =
                  special == 0U ? residual_negative : !residual_negative;
              class_sign = class_sign &&
                           ((production_bits & 0x8000U) != 0U) ==
                               expected_negative;
            } else {
              class_sign = class_sign && is_bf16_nan(baseline_bits) &&
                           is_bf16_nan(production_bits);
            }
          }
          return class_sign;
        });
  }
  test.expect(norm_nonfinite_gate,
              label + " selects finite nonzero residuals for norm fixture");
  const bool nonfinite_gate =
      residual_nonfinite_gate && norm_nonfinite_gate;
  test.expect(nonfinite_gate,
              label + " clears signed nonfinite production gate");
  if (!nonfinite_gate) {
    return;
  }

  ready = test.cuda_ok(
      cudaMemcpyAsync(residual_left.get(), host_left.data(),
                      kRows * sizeof(std::uint16_t), cudaMemcpyHostToDevice,
                      stream),
      label + " restore finite residual input");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(norm_weight.get(), host_weight.data(),
                                       kRows * sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " restore finite norm weight");
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " restore finite fixture synchronize");
  if (!ready) {
    return;
  }

  if (!nvfp4_m1_down_residual_norm_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M1 down+residual+norm performance timing; set "
           "Q3X_RUN_SM87_NVFP4_M1_DOWN_RESIDUAL_NORM_PERF=1 to enable\n";
    return;
  }

  for (int iteration = 0; iteration < kWarmupIterations; ++iteration) {
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_baseline()),
                         label + " warm baseline");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_production()),
                         label + " warm production");
  }
  ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " warmup synchronize");
  if (!ready) {
    return;
  }
  double baseline_total = 0.0;
  double candidate_total = 0.0;
  bool performance_gate = true;
  for (int round = 0; round < kMeasurementRounds; ++round) {
    const float baseline_first = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " measure baseline first");
    const float candidate_first = measure_small_m_tile(
        test, stream, launch_production, kMeasuredIterations,
        label + " measure production first");
    const float candidate_second = measure_small_m_tile(
        test, stream, launch_production, kMeasuredIterations,
        label + " measure production second");
    const float baseline_second = measure_small_m_tile(
        test, stream, launch_baseline, kMeasuredIterations,
        label + " measure baseline second");
    const double baseline_ms =
        (static_cast<double>(baseline_first) + baseline_second) / 2.0;
    const double candidate_ms =
        (static_cast<double>(candidate_first) + candidate_second) / 2.0;
    const double speedup = baseline_ms / candidate_ms;
    performance_gate =
        performance_gate && std::isfinite(speedup) && baseline_ms > 0.0 &&
        candidate_ms > 0.0;
    baseline_total += baseline_ms;
    candidate_total += candidate_ms;
    std::cout << "PERF_NVFP4_M1_DOWN_RESIDUAL_NORM_ROUND: round="
              << round << " baseline_ms=" << baseline_ms
              << " candidate_ms=" << candidate_ms
              << " speedup=" << speedup << '\n';
  }
  const double baseline_ms = baseline_total / kMeasurementRounds;
  const double candidate_ms = candidate_total / kMeasurementRounds;
  const double speedup = baseline_ms / candidate_ms;
  performance_gate = performance_gate && std::isfinite(speedup) &&
                     speedup >= 1.005;
  test.expect(performance_gate, label + " clears hard 1.005x timing gate");
  std::cout << "PERF_NVFP4_M1_DOWN_RESIDUAL_NORM: "
            << "baseline=down_activation_staged_plus_residual_centered_norm"
            << " candidate=single_cooperative_down_residual_centered_norm"
            << " baseline_ms=" << baseline_ms
            << " candidate_ms=" << candidate_ms << " speedup=" << speedup
            << " minimum_recommendation_speedup=1.005"
            << " recommendation=" << (speedup >= 1.005 ? "KEEP" : "DROP")
            << " correctness=" << (correctness_gate ? "PASS" : "FAIL")
            << " gate=" << (performance_gate ? "PASS" : "FAIL") << '\n';
}

void run_optional_nvfp4_m1_down_residual_norm_cta_coarsen(
    TestContext& test, cudaStream_t stream) {
  if (!nvfp4_m1_down_residual_norm_performance_enabled()) {
    return;
  }

  constexpr std::size_t kRows = 5'120U;
  constexpr std::size_t kColumns = 17'408U;
  constexpr std::size_t kPackedCount = kRows * kColumns / 2U;
  constexpr std::size_t kScaleCount = kRows * kColumns / 16U;
  constexpr std::size_t kScaleColumns = kColumns / 16U;
  constexpr std::size_t kGuardElements = 16U;
  constexpr float kEpsilon = 1.0e-6F;
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 64;
  constexpr int kMeasurementRounds = 5;
  constexpr std::uint64_t kExpectedCheckpointBytes = 9'965'652'512ULL;
  constexpr std::uint64_t kExpectedHeaderBytes = 126'504ULL;
  constexpr std::uint64_t kExpectedDataBase = 126'512ULL;
  constexpr std::uint64_t kWeightOffset = 6'712'445'472ULL;
  constexpr std::uint64_t kScaleOffset = 3'600'468'512ULL;
  constexpr std::uint64_t kScale2Offset = 126'540ULL;
  constexpr std::uint64_t kNormWeightOffset = 2'544'010'432ULL;
  constexpr std::uint32_t kExpectedScale2Bits = 0x39b61862U;
  constexpr std::string_view kWeightSha256 =
      "bc1b428661d3cf657a4d69ff8d7e482b8125ef0f323e6df29b153a22fa2b6daf";
  constexpr std::string_view kScaleSha256 =
      "7943b475b23f75886309e93bf673aacc22c699e19ff400ef85607ab1a4006019";
  constexpr std::string_view kNormWeightSha256 =
      "89b1d66c33ed1a46813b12d4ca0757fcdd01f1e6fb90d47a569f37e0603a193d";
  const std::string label =
      "NVFP4 M1 down/residual/norm predecessor-vs-production 5120x17408";

  const char* const checkpoint_value =
      std::getenv("Q3X_NVFP4_M1_DOWN_ACTUAL_CHECKPOINT_FILE");
  const bool source_set =
      checkpoint_value != nullptr && checkpoint_value[0] != '\0';
  test.expect(source_set, label + " requires actual checkpoint shard");
  if (!source_set) {
    std::cout << "NVFP4_M1_DOWN_CTA_COARSEN_CHECKPOINT_SOURCE: source=missing "
                 "required_env=Q3X_NVFP4_M1_DOWN_ACTUAL_CHECKPOINT_FILE "
                 "gate=FAIL\n";
    return;
  }

  const std::string checkpoint_path = checkpoint_value;
  std::ifstream checkpoint(checkpoint_path, std::ios::binary);
  const bool opened = checkpoint.is_open();
  test.expect(opened, label + " opens actual checkpoint shard");
  if (!opened) {
    return;
  }
  checkpoint.seekg(0, std::ios::end);
  const std::streamoff checkpoint_size = checkpoint.tellg();
  const bool checkpoint_size_gate =
      checkpoint_size >= 0 &&
      static_cast<std::uint64_t>(checkpoint_size) ==
          kExpectedCheckpointBytes;
  test.expect(checkpoint_size_gate, label + " pins checkpoint shard size");
  if (!checkpoint_size_gate) {
    return;
  }

  const auto read_slice =
      [&](const std::uint64_t offset, void* const destination,
          const std::size_t bytes, const std::string& tensor) {
        const std::uint64_t file_bytes =
            static_cast<std::uint64_t>(checkpoint_size);
        const bool range_gate =
            offset <= file_bytes && bytes <= file_bytes - offset &&
            offset <= static_cast<std::uint64_t>(
                          std::numeric_limits<std::streamoff>::max()) &&
            bytes <= static_cast<std::size_t>(
                         std::numeric_limits<std::streamsize>::max());
        test.expect(range_gate, label + " contains " + tensor);
        if (!range_gate) {
          return false;
        }
        checkpoint.clear();
        checkpoint.seekg(static_cast<std::streamoff>(offset), std::ios::beg);
        checkpoint.read(reinterpret_cast<char*>(destination),
                        static_cast<std::streamsize>(bytes));
        const bool complete =
            checkpoint.gcount() == static_cast<std::streamsize>(bytes);
        test.expect(complete, label + " reads complete " + tensor);
        return complete;
      };

  std::array<std::uint8_t, 8U> header_length_bytes{};
  bool ready = read_slice(0U, header_length_bytes.data(),
                          header_length_bytes.size(),
                          "safetensors header length");
  std::uint64_t header_bytes = 0U;
  for (std::size_t index = 0U; index < header_length_bytes.size(); ++index) {
    header_bytes |= static_cast<std::uint64_t>(header_length_bytes[index])
                    << (8U * index);
  }
  const bool header_gate =
      ready && header_bytes == kExpectedHeaderBytes &&
      header_bytes + 8U == kExpectedDataBase;
  test.expect(header_gate, label + " pins safetensors header/data base");

  std::vector<std::uint8_t> actual_packed(kPackedCount);
  std::vector<std::uint8_t> actual_scales(kScaleCount);
  std::vector<std::uint16_t> actual_norm_weight(kRows);
  std::array<std::uint8_t, 4U> scale2_bytes{};
  ready = ready && read_slice(kWeightOffset, actual_packed.data(),
                              actual_packed.size(),
                              "layer-0 down_proj.weight");
  ready = ready && read_slice(kScaleOffset, actual_scales.data(),
                              actual_scales.size(),
                              "layer-0 down_proj.weight_scale");
  ready = ready && read_slice(kScale2Offset, scale2_bytes.data(),
                              scale2_bytes.size(),
                              "layer-0 down_proj.weight_scale_2");
  ready = ready && read_slice(kNormWeightOffset, actual_norm_weight.data(),
                              kRows * sizeof(std::uint16_t),
                              "layer-1 input_layernorm.weight");
  if (!ready) {
    return;
  }
  const std::uint32_t scale2_bits =
      static_cast<std::uint32_t>(scale2_bytes[0U]) |
      (static_cast<std::uint32_t>(scale2_bytes[1U]) << 8U) |
      (static_cast<std::uint32_t>(scale2_bytes[2U]) << 16U) |
      (static_cast<std::uint32_t>(scale2_bytes[3U]) << 24U);
  float actual_scale2 = 0.0F;
  std::memcpy(&actual_scale2, &scale2_bits, sizeof(actual_scale2));
  const auto hash_bytes = [](const void* const data, const std::size_t bytes) {
    return q3x::core::sha256(std::string_view(
                                 reinterpret_cast<const char*>(data), bytes))
        .hex();
  };
  const std::string weight_hash =
      hash_bytes(actual_packed.data(), actual_packed.size());
  const std::string scale_hash =
      hash_bytes(actual_scales.data(), actual_scales.size());
  const std::string norm_hash = hash_bytes(
      actual_norm_weight.data(), kRows * sizeof(std::uint16_t));
  const bool pinned_payload_gate =
      header_gate && weight_hash == kWeightSha256 &&
      scale_hash == kScaleSha256 && norm_hash == kNormWeightSha256 &&
      scale2_bits == kExpectedScale2Bits && std::isfinite(actual_scale2) &&
      actual_scale2 > 0.0F;
  test.expect(pinned_payload_gate,
              label + " pins actual weight/scale/scale2/norm payloads");
  std::cout << "NVFP4_M1_DOWN_CTA_COARSEN_CHECKPOINT_SOURCE: source=actual"
            << " path=" << checkpoint_path
            << " file_bytes=" << checkpoint_size
            << " header_bytes=" << header_bytes
            << " data_base=" << kExpectedDataBase
            << " weight_offset=" << kWeightOffset
            << " weight_bytes=" << actual_packed.size()
            << " weight_sha256=" << weight_hash
            << " scale_offset=" << kScaleOffset
            << " scale_bytes=" << actual_scales.size()
            << " scale_sha256=" << scale_hash
            << " scale2_offset=" << kScale2Offset
            << " scale2_bits=" << scale2_bits
            << " norm_weight_offset=" << kNormWeightOffset
            << " norm_weight_bytes="
            << kRows * sizeof(std::uint16_t)
            << " norm_weight_sha256=" << norm_hash
            << " gate=" << (pinned_payload_gate ? "PASS" : "FAIL")
            << '\n';
  if (!pinned_payload_gate) {
    return;
  }

  std::array<std::uint8_t, kNvFp4M1DownDualFixturePeriod> packed_pattern{};
  for (std::size_t index = 0U; index < packed_pattern.size(); ++index) {
    const std::uint8_t low = static_cast<std::uint8_t>(
        (index * 5U + (index >> 2U) * 3U + 1U) & 0x0fU);
    const std::uint8_t high = static_cast<std::uint8_t>(
        (index * 7U + (index >> 3U) * 5U + 9U) & 0x0fU);
    packed_pattern[index] =
        static_cast<std::uint8_t>(low | (high << 4U));
  }
  std::vector<std::uint8_t> stress_packed(kPackedCount);
  for (std::size_t index = 0U; index < stress_packed.size(); ++index) {
    stress_packed[index] = packed_pattern[index % packed_pattern.size()];
  }
  std::vector<std::uint8_t> stress_scales(kScaleCount);
  fill_nvfp4_m1_down_dual_scale_distribution(
      stress_scales, kScaleColumns,
      NvFp4M1ScaleDistribution::kSameBankStress);
  std::vector<std::uint16_t> host_activation(kColumns);
  std::vector<std::uint16_t> host_left(kRows);
  for (std::size_t index = 0U; index < kColumns; ++index) {
    const int centered =
        static_cast<int>((index * 19U + (index >> 3U) * 7U + 11U) %
                         127U) -
        63;
    host_activation[index] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }
  for (std::size_t index = 0U; index < kRows; ++index) {
    const int centered =
        static_cast<int>((index * 23U + (index >> 2U) * 5U + 3U) % 257U) -
        128;
    host_left[index] = encode_bf16(static_cast<float>(centered) / 128.0F);
  }

  DeviceBuffer<std::uint8_t> packed;
  DeviceBuffer<std::uint8_t> scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> residual_left;
  DeviceBuffer<std::uint16_t> norm_weight;
  DeviceBuffer<std::uint16_t> production_raw_storage;
  DeviceBuffer<std::uint16_t> production_residual_storage;
  DeviceBuffer<std::uint16_t> production_norm_storage;
  DeviceBuffer<std::uint16_t> coarsened_raw_storage;
  DeviceBuffer<std::uint16_t> coarsened_residual_storage;
  DeviceBuffer<std::uint16_t> coarsened_norm_storage;
  ready = test.cuda_ok(packed.allocate(kPackedCount),
                       label + " allocate packed weights");
  ready = ready && test.cuda_ok(scales.allocate(kScaleCount),
                                label + " allocate scales");
  ready = ready && test.cuda_ok(activation.allocate(kColumns),
                                label + " allocate activation");
  ready = ready && test.cuda_ok(residual_left.allocate(kRows),
                                label + " allocate residual input");
  ready = ready && test.cuda_ok(norm_weight.allocate(kRows),
                                label + " allocate norm weight");
  const auto allocate_guarded =
      [&](DeviceBuffer<std::uint16_t>& buffer, const std::string& name) {
        return test.cuda_ok(buffer.allocate(kRows + 2U * kGuardElements),
                            label + " allocate guarded " + name);
      };
  ready = ready &&
          allocate_guarded(production_raw_storage, "production raw");
  ready = ready && allocate_guarded(production_residual_storage,
                                     "production residual");
  ready = ready &&
          allocate_guarded(production_norm_storage, "production norm");
  ready = ready &&
          allocate_guarded(coarsened_raw_storage, "coarsened raw");
  ready = ready && allocate_guarded(coarsened_residual_storage,
                                     "coarsened residual");
  ready = ready &&
          allocate_guarded(coarsened_norm_storage, "coarsened norm");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(activation.get(), host_activation.data(),
                                       kColumns * sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload deterministic activation");
  ready = ready && test.cuda_ok(
                       cudaMemcpyAsync(residual_left.get(), host_left.data(),
                                       kRows * sizeof(std::uint16_t),
                                       cudaMemcpyHostToDevice, stream),
                       label + " upload deterministic residual input");
  if (!ready) {
    return;
  }

  std::uint16_t* const production_raw =
      production_raw_storage.get() + kGuardElements;
  std::uint16_t* const production_residual =
      production_residual_storage.get() + kGuardElements;
  std::uint16_t* const production_norm =
      production_norm_storage.get() + kGuardElements;
  std::uint16_t* const coarsened_raw =
      coarsened_raw_storage.get() + kGuardElements;
  std::uint16_t* const coarsened_residual =
      coarsened_residual_storage.get() + kGuardElements;
  std::uint16_t* const coarsened_norm =
      coarsened_norm_storage.get() + kGuardElements;
  // The first guarded buffer set is B (test-only 64x256 predecessor); the
  // second, historically named coarsened, is C (public 32x512 production).
  const auto launch_predecessor = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_down_residual_norm_predecessor_test_cuda(
            packed.get(), scales.get(), actual_scale2, activation.get(),
            residual_left.get(), norm_weight.get(), kEpsilon, kRows, kColumns,
            production_raw, production_residual, production_norm,
            static_cast<void*>(stream));
  };
  const auto launch_production = [&]() noexcept -> int {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_down_residual_norm_bf16_cuda(
            packed.get(), scales.get(), actual_scale2, activation.get(),
            residual_left.get(), norm_weight.get(), kEpsilon, kRows, kColumns,
            coarsened_raw, coarsened_residual, coarsened_norm,
            static_cast<void*>(stream));
  };
  const auto poison = [&](DeviceBuffer<std::uint16_t>& storage,
                          const int byte, const std::string& operation) {
    return test.cuda_ok(
        cudaMemsetAsync(storage.get(), byte,
                        (kRows + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        operation);
  };
  const auto poison_outputs = [&](const std::string& fixture) {
    bool ok = poison(production_raw_storage, 0xa1,
                     label + " poison " + fixture + " production raw");
    ok = ok && poison(production_residual_storage, 0xb2,
                      label + " poison " + fixture +
                          " production residual");
    ok = ok && poison(production_norm_storage, 0xc3,
                      label + " poison " + fixture + " production norm");
    ok = ok && poison(coarsened_raw_storage, 0xd4,
                      label + " poison " + fixture + " coarsened raw");
    ok = ok && poison(coarsened_residual_storage, 0xe5,
                      label + " poison " + fixture +
                          " coarsened residual");
    ok = ok && poison(coarsened_norm_storage, 0xf6,
                      label + " poison " + fixture + " coarsened norm");
    return ok;
  };
  const std::size_t guarded_count = kRows + 2U * kGuardElements;
  std::vector<std::uint16_t> production_raw_host(guarded_count);
  std::vector<std::uint16_t> production_residual_host(guarded_count);
  std::vector<std::uint16_t> production_norm_host(guarded_count);
  std::vector<std::uint16_t> coarsened_raw_host(guarded_count);
  std::vector<std::uint16_t> coarsened_residual_host(guarded_count);
  std::vector<std::uint16_t> coarsened_norm_host(guarded_count);
  const auto copy_output = [&](std::vector<std::uint16_t>& host,
                               const DeviceBuffer<std::uint16_t>& device,
                               const std::string& operation) {
    return test.cuda_ok(
        cudaMemcpyAsync(host.data(), device.get(),
                        guarded_count * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        operation);
  };
  const auto copy_all_outputs = [&](const std::string& fixture) {
    bool ok = copy_output(production_raw_host, production_raw_storage,
                          label + " copy " + fixture + " production raw");
    ok = ok && copy_output(
                   production_residual_host, production_residual_storage,
                   label + " copy " + fixture + " production residual");
    ok = ok && copy_output(production_norm_host, production_norm_storage,
                           label + " copy " + fixture + " production norm");
    ok = ok && copy_output(coarsened_raw_host, coarsened_raw_storage,
                           label + " copy " + fixture + " coarsened raw");
    ok = ok && copy_output(
                   coarsened_residual_host, coarsened_residual_storage,
                   label + " copy " + fixture + " coarsened residual");
    ok = ok && copy_output(coarsened_norm_host, coarsened_norm_storage,
                           label + " copy " + fixture + " coarsened norm");
    return ok;
  };
  const auto mismatch_count =
      [&](const std::vector<std::uint16_t>& expected,
          const std::vector<std::uint16_t>& actual) {
        std::size_t mismatches = 0U;
        for (std::size_t index = 0U; index < kRows; ++index) {
          mismatches += expected[kGuardElements + index] !=
                                actual[kGuardElements + index]
                            ? 1U
                            : 0U;
        }
        return mismatches;
      };
  const auto guards_intact =
      [&](const std::vector<std::uint16_t>& output,
          const std::uint16_t expected) {
        for (std::size_t index = 0U; index < kGuardElements; ++index) {
          if (output[index] != expected ||
              output[kGuardElements + kRows + index] != expected) {
            return false;
          }
        }
        return true;
      };

  std::vector<std::uint8_t> packed_after(kPackedCount);
  std::vector<std::uint8_t> scales_after(kScaleCount);
  std::vector<std::uint16_t> activation_after(kColumns);
  std::vector<std::uint16_t> residual_after(kRows);
  std::vector<std::uint16_t> norm_after(kRows);
  const auto inputs_preserved =
      [&](const std::vector<std::uint8_t>& expected_packed,
          const std::vector<std::uint8_t>& expected_scales,
          const std::vector<std::uint16_t>& expected_residual,
          const std::vector<std::uint16_t>& expected_norm,
          const std::string& fixture) {
        bool ok = test.cuda_ok(
            cudaMemcpyAsync(packed_after.data(), packed.get(), kPackedCount,
                            cudaMemcpyDeviceToHost, stream),
            label + " copy " + fixture + " preserved packed");
        ok = ok && test.cuda_ok(
                       cudaMemcpyAsync(scales_after.data(), scales.get(),
                                       kScaleCount, cudaMemcpyDeviceToHost,
                                       stream),
                       label + " copy " + fixture + " preserved scales");
        ok = ok && test.cuda_ok(
                       cudaMemcpyAsync(activation_after.data(),
                                       activation.get(),
                                       kColumns * sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " copy " + fixture +
                           " preserved activation");
        ok = ok && test.cuda_ok(
                       cudaMemcpyAsync(residual_after.data(),
                                       residual_left.get(),
                                       kRows * sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " copy " + fixture +
                           " preserved residual");
        ok = ok && test.cuda_ok(
                       cudaMemcpyAsync(norm_after.data(), norm_weight.get(),
                                       kRows * sizeof(std::uint16_t),
                                       cudaMemcpyDeviceToHost, stream),
                       label + " copy " + fixture + " preserved norm");
        ok = ok && test.cuda_ok(cudaStreamSynchronize(stream),
                                label + " " + fixture +
                                    " input preservation synchronize");
        return ok && packed_after == expected_packed &&
               scales_after == expected_scales &&
               activation_after == host_activation &&
               residual_after == expected_residual &&
               norm_after == expected_norm;
      };

  struct DownCoarsenFixture {
    const char* name;
    const std::vector<std::uint8_t>* packed_values;
    const std::vector<std::uint8_t>* scale_values;
    float required_median_speedup;
  };
  const std::array<DownCoarsenFixture, 2U> fixtures{{
      {"actual_checkpoint", &actual_packed, &actual_scales, 1.005F},
      {"same_bank_stress", &stress_packed, &stress_scales, 1.000F},
  }};
  std::array<bool, 2U> fixture_gates{};
  std::array<float, 2U> fixture_paired_medians{};

  for (std::size_t fixture_index = 0U; fixture_index < fixtures.size();
       ++fixture_index) {
    const DownCoarsenFixture& fixture = fixtures[fixture_index];
    const std::string fixture_name = fixture.name;
    ready = test.cuda_ok(
        cudaMemcpyAsync(packed.get(), fixture.packed_values->data(),
                        kPackedCount, cudaMemcpyHostToDevice, stream),
        label + " upload " + fixture_name + " packed");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(scales.get(),
                                         fixture.scale_values->data(),
                                         kScaleCount, cudaMemcpyHostToDevice,
                                         stream),
                         label + " upload " + fixture_name + " scales");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(norm_weight.get(),
                                         actual_norm_weight.data(),
                                         kRows * sizeof(std::uint16_t),
                                         cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_name + " norm");
    ready = ready && poison_outputs(fixture_name);
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_predecessor()),
                         label + " launch " + fixture_name +
                             " predecessor 64x256");
    ready = ready && test.cuda_ok(
                         static_cast<cudaError_t>(launch_production()),
                         label + " launch " + fixture_name +
                             " production 32x512");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " " + fixture_name +
                                      " correctness synchronize");
    ready = ready && copy_all_outputs(fixture_name);
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " " + fixture_name +
                                      " output copy synchronize");
    if (!ready) {
      return;
    }

    const std::size_t raw_mismatches =
        mismatch_count(production_raw_host, coarsened_raw_host);
    const std::size_t residual_mismatches =
        mismatch_count(production_residual_host, coarsened_residual_host);
    const std::size_t norm_mismatches =
        mismatch_count(production_norm_host, coarsened_norm_host);
    const bool guards_gate =
        guards_intact(production_raw_host, 0xa1a1U) &&
        guards_intact(production_residual_host, 0xb2b2U) &&
        guards_intact(production_norm_host, 0xc3c3U) &&
        guards_intact(coarsened_raw_host, 0xd4d4U) &&
        guards_intact(coarsened_residual_host, 0xe5e5U) &&
        guards_intact(coarsened_norm_host, 0xf6f6U);
    const std::vector<std::uint16_t> first_raw = coarsened_raw_host;
    const std::vector<std::uint16_t> first_residual =
        coarsened_residual_host;
    const std::vector<std::uint16_t> first_norm = coarsened_norm_host;
    ready = test.cuda_ok(static_cast<cudaError_t>(launch_production()),
                         label + " replay " + fixture_name +
                             " production 32x512");
    ready = ready && copy_output(coarsened_raw_host, coarsened_raw_storage,
                                 label + " copy " + fixture_name +
                                     " replay raw");
    ready = ready && copy_output(coarsened_residual_host,
                                 coarsened_residual_storage,
                                 label + " copy " + fixture_name +
                                     " replay residual");
    ready = ready && copy_output(coarsened_norm_host,
                                 coarsened_norm_storage,
                                 label + " copy " + fixture_name +
                                     " replay norm");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " " + fixture_name +
                                      " replay synchronize");
    if (!ready) {
      return;
    }
    const std::size_t replay_mismatches =
        mismatch_count(first_raw, coarsened_raw_host) +
        mismatch_count(first_residual, coarsened_residual_host) +
        mismatch_count(first_norm, coarsened_norm_host);
    const bool replay_guards_gate =
        guards_intact(coarsened_raw_host, 0xd4d4U) &&
        guards_intact(coarsened_residual_host, 0xe5e5U) &&
        guards_intact(coarsened_norm_host, 0xf6f6U);
    const bool input_gate = inputs_preserved(
        *fixture.packed_values, *fixture.scale_values, host_left,
        actual_norm_weight, fixture_name);
    const bool finite_gate = raw_mismatches == 0U &&
                             residual_mismatches == 0U &&
                             norm_mismatches == 0U &&
                             replay_mismatches == 0U && guards_gate &&
                             replay_guards_gate && input_gate;
    test.expect(finite_gate,
                label + " " + fixture_name +
                    " preserves production bits/replay/inputs");
    std::cout << "NVFP4_M1_DOWN_CTA_COARSEN_DIFF: fixture="
              << fixture_name
              << " baseline=predecessor_64x256 candidate=production_32x512"
              << " raw_bitwise_mismatches=" << raw_mismatches
              << '/' << kRows << " residual_bitwise_mismatches="
              << residual_mismatches << '/' << kRows
              << " norm_bitwise_mismatches=" << norm_mismatches << '/'
              << kRows << " replay_bitwise_mismatches="
              << replay_mismatches << '/' << (3U * kRows)
              << " guards="
              << (guards_gate && replay_guards_gate ? "intact" : "BAD")
              << " inputs_preserved=" << (input_gate ? "true" : "false")
              << " gate=" << (finite_gate ? "PASS" : "FAIL") << '\n';
    if (!finite_gate) {
      return;
    }

    for (int iteration = 0; iteration < kWarmupIterations; ++iteration) {
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_predecessor()),
                           label + " warm " + fixture_name + " predecessor");
      ready = ready && test.cuda_ok(
                           static_cast<cudaError_t>(launch_production()),
                           label + " warm " + fixture_name + " production");
    }
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " " + fixture_name +
                                      " warmup synchronize");
    if (!ready) {
      return;
    }
    std::array<float, 2U * kMeasurementRounds> predecessor_passes{};
    std::array<float, 2U * kMeasurementRounds> production_passes{};
    std::array<float, kMeasurementRounds> paired_speedups{};
    bool rounds_gate = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          label + " " + fixture_name + " round=" + std::to_string(round);
      const float b1 = measure_small_m_tile(
          test, stream, launch_predecessor, kMeasuredIterations,
          round_label + " B1 predecessor 64x256");
      const float c1 = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          round_label + " C1 production 32x512");
      const float c2 = measure_small_m_tile(
          test, stream, launch_production, kMeasuredIterations,
          round_label + " C2 production 32x512");
      const float b2 = measure_small_m_tile(
          test, stream, launch_predecessor, kMeasuredIterations,
          round_label + " B2 predecessor 64x256");
      const float paired = (b1 + b2) / (c1 + c2);
      predecessor_passes[2U * static_cast<std::size_t>(round)] = b1;
      predecessor_passes[2U * static_cast<std::size_t>(round) + 1U] = b2;
      production_passes[2U * static_cast<std::size_t>(round)] = c1;
      production_passes[2U * static_cast<std::size_t>(round) + 1U] = c2;
      paired_speedups[static_cast<std::size_t>(round)] = paired;
      const bool round_gate =
          std::isfinite(paired) && b1 > 0.0F && b2 > 0.0F && c1 > 0.0F &&
          c2 > 0.0F && paired >= 1.0F;
      rounds_gate = rounds_gate && round_gate;
      std::cout << "PERF_NVFP4_M1_DOWN_CTA_COARSEN_ROUND: fixture="
                << fixture_name << " round=" << round << " b1_ms=" << b1
                << " c1_ms=" << c1 << " c2_ms=" << c2
                << " b2_ms=" << b2 << " paired_speedup=" << paired
                << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
    }
    const float predecessor_median =
        median_fp8_kv_pair_timing(predecessor_passes);
    const float production_median =
        median_fp8_kv_pair_timing(production_passes);
    const float paired_median =
        median_fp8_kv_pair_timing(paired_speedups);
    fixture_paired_medians[fixture_index] = paired_median;
    const bool timing_gate =
        rounds_gate && std::isfinite(paired_median) &&
        paired_median >= fixture.required_median_speedup;
    fixture_gates[fixture_index] = finite_gate && timing_gate;
    test.expect(fixture_gates[fixture_index],
                label + " " + fixture_name + " clears frozen timing gate");
    std::cout << "PERF_NVFP4_M1_DOWN_CTA_COARSEN: fixture="
              << fixture_name
              << " predecessor_64x256_pass_median_ms=" << predecessor_median
              << " production_32x512_pass_median_ms=" << production_median
              << " paired_round_median_speedup=" << paired_median
              << " required_median_speedup="
              << fixture.required_median_speedup
              << " every_round_nonregression="
              << (rounds_gate ? "PASS" : "FAIL")
              << " correctness=" << (finite_gate ? "PASS" : "FAIL")
              << " gate="
              << (fixture_gates[fixture_index] ? "PASS" : "FAIL") << '\n';
  }

  const auto guarded_at = [&](const std::vector<std::uint16_t>& values,
                              const std::size_t index) {
    return values[kGuardElements + index];
  };
  const auto run_nonfinite_fixture =
      [&](const std::vector<std::uint16_t>& left_values,
          const std::vector<std::uint16_t>& norm_values,
          const std::string& fixture, const auto& semantic_check) {
        bool fixture_ready = test.cuda_ok(
            cudaMemcpyAsync(packed.get(), actual_packed.data(), kPackedCount,
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture + " actual packed");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaMemcpyAsync(scales.get(), actual_scales.data(), kScaleCount,
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture + " actual scales");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaMemcpyAsync(residual_left.get(), left_values.data(),
                            kRows * sizeof(std::uint16_t),
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture + " residual input");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaMemcpyAsync(norm_weight.get(), norm_values.data(),
                            kRows * sizeof(std::uint16_t),
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture + " norm weight");
        fixture_ready = fixture_ready && poison_outputs(fixture);
        fixture_ready = fixture_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_predecessor()),
            label + " launch " + fixture + " predecessor 64x256");
        fixture_ready = fixture_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_production()),
            label + " launch " + fixture + " production 32x512");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaStreamSynchronize(stream), label + " " + fixture +
                                               " synchronize");
        fixture_ready = fixture_ready && copy_all_outputs(fixture);
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaStreamSynchronize(stream), label + " " + fixture +
                                               " copy synchronize");
        if (!fixture_ready) {
          return false;
        }

        const std::size_t raw_mismatches =
            mismatch_count(production_raw_host, coarsened_raw_host);
        const std::size_t residual_mismatches = mismatch_count(
            production_residual_host, coarsened_residual_host);
        const std::size_t norm_mismatches =
            mismatch_count(production_norm_host, coarsened_norm_host);
        const bool guards =
            guards_intact(production_raw_host, 0xa1a1U) &&
            guards_intact(production_residual_host, 0xb2b2U) &&
            guards_intact(production_norm_host, 0xc3c3U) &&
            guards_intact(coarsened_raw_host, 0xd4d4U) &&
            guards_intact(coarsened_residual_host, 0xe5e5U) &&
            guards_intact(coarsened_norm_host, 0xf6f6U);
        const std::vector<std::uint16_t> first_raw = coarsened_raw_host;
        const std::vector<std::uint16_t> first_residual =
            coarsened_residual_host;
        const std::vector<std::uint16_t> first_norm = coarsened_norm_host;
        fixture_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_production()),
            label + " replay " + fixture + " production");
        fixture_ready = fixture_ready && copy_output(
            coarsened_raw_host, coarsened_raw_storage,
            label + " copy " + fixture + " replay raw");
        fixture_ready = fixture_ready && copy_output(
            coarsened_residual_host, coarsened_residual_storage,
            label + " copy " + fixture + " replay residual");
        fixture_ready = fixture_ready && copy_output(
            coarsened_norm_host, coarsened_norm_storage,
            label + " copy " + fixture + " replay norm");
        fixture_ready = fixture_ready && test.cuda_ok(
            cudaStreamSynchronize(stream), label + " " + fixture +
                                               " replay synchronize");
        if (!fixture_ready) {
          return false;
        }
        const std::size_t replay_mismatches =
            mismatch_count(first_raw, coarsened_raw_host) +
            mismatch_count(first_residual, coarsened_residual_host) +
            mismatch_count(first_norm, coarsened_norm_host);
        const bool replay_guards =
            guards_intact(coarsened_raw_host, 0xd4d4U) &&
            guards_intact(coarsened_residual_host, 0xe5e5U) &&
            guards_intact(coarsened_norm_host, 0xf6f6U);
        const bool input_gate = inputs_preserved(
            actual_packed, actual_scales, left_values, norm_values, fixture);
        const bool semantic_gate = semantic_check(
            production_residual_host, production_norm_host,
            coarsened_residual_host, coarsened_norm_host);
        const bool fixture_gate =
            raw_mismatches == 0U && residual_mismatches == 0U &&
            norm_mismatches == 0U && replay_mismatches == 0U && guards &&
            replay_guards && input_gate && semantic_gate;
        test.expect(fixture_gate, label + " " + fixture +
                                      " preserves bits/replay/class/sign");
        std::cout << "NVFP4_M1_DOWN_CTA_COARSEN_NONFINITE: fixture="
                  << fixture
                  << " baseline=predecessor_64x256"
                  << " candidate=production_32x512"
                  << " raw_bitwise_mismatches=" << raw_mismatches
                  << '/' << kRows << " residual_bitwise_mismatches="
                  << residual_mismatches << '/' << kRows
                  << " norm_bitwise_mismatches=" << norm_mismatches << '/'
                  << kRows << " replay_bitwise_mismatches="
                  << replay_mismatches << '/' << (3U * kRows)
                  << " class_sign=" << (semantic_gate ? "PASS" : "FAIL")
                  << " guards="
                  << (guards && replay_guards ? "intact" : "BAD")
                  << " inputs_preserved="
                  << (input_gate ? "true" : "false")
                  << " gate=" << (fixture_gate ? "PASS" : "FAIL")
                  << '\n';
        return fixture_gate;
      };

  std::vector<std::uint16_t> residual_nonfinite_left = host_left;
  residual_nonfinite_left[0U] = 0x7f80U;
  residual_nonfinite_left[1U] = 0xff80U;
  residual_nonfinite_left[2U] = 0x7fc1U;
  residual_nonfinite_left[3U] = 0xffc1U;
  const bool residual_nonfinite_gate = run_nonfinite_fixture(
      residual_nonfinite_left, actual_norm_weight,
      "residual_signed_nonfinite",
      [&](const std::vector<std::uint16_t>& production_residual_bits,
          const std::vector<std::uint16_t>& production_norm_bits,
          const std::vector<std::uint16_t>& candidate_residual_bits,
          const std::vector<std::uint16_t>& candidate_norm_bits) {
        bool class_sign =
            guarded_at(production_residual_bits, 0U) == 0x7f80U &&
            guarded_at(candidate_residual_bits, 0U) == 0x7f80U &&
            guarded_at(production_residual_bits, 1U) == 0xff80U &&
            guarded_at(candidate_residual_bits, 1U) == 0xff80U;
        for (std::size_t index = 2U; index < 4U; ++index) {
          const std::uint16_t production_bits =
              guarded_at(production_residual_bits, index);
          const std::uint16_t candidate_bits =
              guarded_at(candidate_residual_bits, index);
          class_sign = class_sign && is_bf16_nan(production_bits) &&
                       is_bf16_nan(candidate_bits) &&
                       ((production_bits ^ candidate_bits) & 0x8000U) == 0U;
        }
        for (std::size_t index = 0U; index < kRows; ++index) {
          const std::uint16_t production_bits =
              guarded_at(production_norm_bits, index);
          const std::uint16_t candidate_bits =
              guarded_at(candidate_norm_bits, index);
          class_sign = class_sign && is_bf16_nan(production_bits) &&
                       is_bf16_nan(candidate_bits) &&
                       ((production_bits ^ candidate_bits) & 0x8000U) == 0U;
        }
        return class_sign;
      });

  std::array<std::size_t, 4U> norm_nonfinite_indices{};
  std::size_t norm_nonfinite_count = 0U;
  for (std::size_t index = 0U;
       index < kRows && norm_nonfinite_count < norm_nonfinite_indices.size();
       ++index) {
    const std::uint16_t bits = guarded_at(production_residual_host, index);
    if (is_bf16_finite(bits) && (bits & 0x7fffU) != 0U) {
      norm_nonfinite_indices[norm_nonfinite_count++] = index;
    }
  }
  bool norm_nonfinite_gate =
      norm_nonfinite_count == norm_nonfinite_indices.size();
  std::vector<std::uint16_t> norm_nonfinite_weight = actual_norm_weight;
  if (norm_nonfinite_gate) {
    norm_nonfinite_weight[norm_nonfinite_indices[0U]] = 0x7f80U;
    norm_nonfinite_weight[norm_nonfinite_indices[1U]] = 0xff80U;
    norm_nonfinite_weight[norm_nonfinite_indices[2U]] = 0x7fc1U;
    norm_nonfinite_weight[norm_nonfinite_indices[3U]] = 0xffc1U;
    norm_nonfinite_gate = run_nonfinite_fixture(
        host_left, norm_nonfinite_weight, "norm_weight_signed_nonfinite",
        [&](const std::vector<std::uint16_t>& production_residual_bits,
            const std::vector<std::uint16_t>& production_norm_bits,
            const std::vector<std::uint16_t>& candidate_residual_bits,
            const std::vector<std::uint16_t>& candidate_norm_bits) {
          bool class_sign = true;
          for (std::size_t special = 0U; special < 4U; ++special) {
            const std::size_t index = norm_nonfinite_indices[special];
            const std::uint16_t production_residual_bits_at_index =
                guarded_at(production_residual_bits, index);
            const std::uint16_t candidate_residual_bits_at_index =
                guarded_at(candidate_residual_bits, index);
            const std::uint16_t production_bits =
                guarded_at(production_norm_bits, index);
            const std::uint16_t candidate_bits =
                guarded_at(candidate_norm_bits, index);
            class_sign =
                class_sign &&
                production_residual_bits_at_index ==
                    candidate_residual_bits_at_index &&
                ((production_bits ^ candidate_bits) & 0x8000U) == 0U;
            if (special < 2U) {
              class_sign = class_sign && !is_bf16_finite(production_bits) &&
                           !is_bf16_nan(production_bits) &&
                           !is_bf16_finite(candidate_bits) &&
                           !is_bf16_nan(candidate_bits);
              const bool residual_negative =
                  (production_residual_bits_at_index & 0x8000U) != 0U;
              const bool expected_negative =
                  special == 0U ? residual_negative : !residual_negative;
              class_sign = class_sign &&
                           (((production_bits & 0x8000U) != 0U) ==
                            expected_negative) &&
                           (((candidate_bits & 0x8000U) != 0U) ==
                            expected_negative);
            } else {
              class_sign = class_sign && is_bf16_nan(production_bits) &&
                           is_bf16_nan(candidate_bits);
            }
          }
          return class_sign;
        });
  }
  test.expect(norm_nonfinite_count == norm_nonfinite_indices.size(),
              label +
                  " selects finite nonzero residuals for norm-only fixture");
  const bool nonfinite_gate =
      residual_nonfinite_gate && norm_nonfinite_gate;
  test.expect(nonfinite_gate,
              label + " clears split signed nonfinite production gate");

  const bool selection_gate =
      fixture_gates[0U] && fixture_gates[1U] && nonfinite_gate;
  const bool promotion_advisory = fixture_paired_medians[0U] >= 1.01F;
  std::cout << "PERF_NVFP4_M1_DOWN_CTA_COARSEN_SELECTED: "
            << "baseline=test_only_predecessor_64x256"
            << " candidate=production_32x512"
            << " actual_paired_median_speedup="
            << fixture_paired_medians[0U]
            << " stress_paired_median_speedup="
            << fixture_paired_medians[1U]
            << " required_actual=1.005 required_stress=1"
            << " every_round_required=1"
            << " nonfinite=" << (nonfinite_gate ? "PASS" : "FAIL")
            << " promotion_advisory="
            << (promotion_advisory ? "PROCEED" : "HOLD_BELOW_1.01")
            << " gate=" << (selection_gate ? "PASS" : "FAIL") << '\n';
  test.expect(selection_gate,
              label + " clears post-promotion predecessor/production gate");
}

using NvFp4GateUpPairLauncher = int (*)(
    const std::uint8_t*, const std::uint8_t*, float,
    const std::uint8_t*, const std::uint8_t*, float,
    const std::uint16_t*, std::size_t, std::size_t, std::uint16_t*,
    std::uint16_t*, void*) noexcept;

using NvFp4GateUpPairResourceQuery = int (*)(
    int*, std::size_t*, std::size_t*, int*, int*) noexcept;

void run_nvfp4_m1_gate_up_pair_default_probe(TestContext& test,
                                              cudaStream_t stream) {
  constexpr std::size_t kRows = 2'048U;
  constexpr std::size_t kColumns = 512U;
  constexpr std::size_t kPackedCount = kRows * kColumns / 2U;
  constexpr std::size_t kScaleCount = kRows * kColumns / 16U;
  constexpr std::size_t kScaleColumns = kColumns / 16U;
  constexpr std::size_t kGuardElements = 16U;
  constexpr float kGateWeightScale2 = 1.0F / 64.0F;
  constexpr float kUpWeightScale2 = 1.0F / 80.0F;
  constexpr std::uint16_t kBaselineGateGuard = 0xa1a1U;
  constexpr std::uint16_t kBaselineUpGuard = 0xb2b2U;
  constexpr std::uint16_t kBaselineFinalGuard = 0xc3c3U;
  constexpr std::uint16_t kPairGateGuard = 0xd4d4U;
  constexpr std::uint16_t kPairUpGuard = 0xe5e5U;
  constexpr std::uint16_t kPairFinalGuard = 0xf6f6U;
  constexpr std::uint16_t kFusedGateGuard = 0x6969U;
  constexpr std::uint16_t kFusedUpGuard = 0x7878U;
  const std::string label =
      "NVFP4 M1 gate/up pair(+SiLU) bounded 2048x512";

  const NvFp4GateUpPairLauncher pair_launcher =
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_gate_up_pair_activation_staged_test_cuda;
  const NvFp4GateUpPairLauncher fused_launcher =
      q3x::kernels::
          launch_sm87_nvfp4_w4a16_gemv_bf16_gate_up_silu_activation_staged_test_cuda;
  const NvFp4GateUpPairResourceQuery pair_resource_query =
      q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_gate_up_pair_activation_staged_resources_test_cuda;
  const NvFp4GateUpPairResourceQuery fused_resource_query =
      q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_gate_up_silu_activation_staged_resources_test_cuda;
  const NvFp4GateUpPairResourceQuery residual_norm_fused_resource_query =
      q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_residual_norm_gate_up_silu_resources_test_cuda;
  const NvFp4GateUpPairResourceQuery residual_norm_shared_tree_resource_query =
      q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_residual_norm_gate_up_silu_shared_tree_resources_test_cuda;
  const NvFp4GateUpPairResourceQuery residual_norm_production_resource_query =
      q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_residual_norm_gate_up_silu_coarsened_512_resources_test_cuda;

  const auto check_resources =
      [&](const NvFp4GateUpPairResourceQuery query,
          const char* const candidate, const int minimum_threads_per_block,
          const int minimum_active_blocks_per_sm) {
        NvFp4M1DownDualKernelResources resources{};
        const bool queried = test.cuda_ok(
            static_cast<cudaError_t>(query(
                &resources.registers_per_thread,
                &resources.static_shared_bytes, &resources.local_bytes,
                &resources.maximum_threads_per_block,
                &resources.active_blocks_per_sm)),
            label + " query " + candidate + " resources");
        const bool resource_gate =
            queried && resources.registers_per_thread <= 64 &&
            resources.static_shared_bytes <= 11'328U &&
            resources.local_bytes == 0U &&
            resources.maximum_threads_per_block >= minimum_threads_per_block &&
            resources.active_blocks_per_sm >= minimum_active_blocks_per_sm;
        const bool null_rejected =
            static_cast<cudaError_t>(query(
                nullptr, &resources.static_shared_bytes,
                &resources.local_bytes, &resources.maximum_threads_per_block,
                &resources.active_blocks_per_sm)) == cudaErrorInvalidValue;
        test.expect(resource_gate,
                    label + " " + candidate +
                        " clears production resource gate");
        test.expect(null_rejected,
                    label + " " + candidate +
                        " resource query rejects null");
        std::cout << "NVFP4_M1_GATE_UP_PAIR_DEFAULT_RESOURCES: candidate="
                  << candidate
                  << " registers_per_thread="
                  << resources.registers_per_thread
                  << " static_shared_bytes="
                  << resources.static_shared_bytes
                  << " local_bytes=" << resources.local_bytes
                  << " maximum_threads_per_block="
                  << resources.maximum_threads_per_block
                  << " active_blocks_per_sm="
                  << resources.active_blocks_per_sm
                  << " maximum_registers_per_thread=64"
                  << " maximum_static_shared_bytes=11328"
                  << " require_zero_local_bytes=true"
                  << " minimum_threads_per_block="
                  << minimum_threads_per_block
                  << " minimum_active_blocks_per_sm="
                  << minimum_active_blocks_per_sm
                  << " null_query_rejected="
                  << (null_rejected ? "true" : "false")
                  << " gate="
                  << (resource_gate && null_rejected ? "PASS" : "FAIL")
                  << '\n';
        return resource_gate && null_rejected;
      };
  const bool pair_resource_gate =
      check_resources(pair_resource_query, "pair_only", 256, 4);
  const bool fused_resource_gate =
      check_resources(fused_resource_query, "pair_plus_silu", 256, 4);
  const bool residual_norm_fused_resource_gate = check_resources(
      residual_norm_fused_resource_query, "residual_norm_pair_plus_silu", 256,
      4);
  const bool residual_norm_shared_tree_resource_gate = check_resources(
      residual_norm_shared_tree_resource_query,
      "residual_norm_pair_plus_silu_shared_tree_baseline", 256, 4);
  const bool residual_norm_production_resource_gate = check_resources(
      residual_norm_production_resource_query,
      "residual_norm_pair_plus_silu_production_32x512", 512, 2);

  std::vector<std::uint8_t> host_gate_packed(kPackedCount);
  std::vector<std::uint8_t> host_up_packed(kPackedCount);
  std::vector<std::uint8_t> host_gate_scales(kScaleCount);
  std::vector<std::uint8_t> host_up_scales(kScaleCount);
  std::vector<std::uint16_t> host_activation(kColumns);
  for (std::size_t index = 0U; index < kPackedCount; ++index) {
    const std::uint8_t gate_low = static_cast<std::uint8_t>(
        (index * 5U + (index >> 3U) * 3U + 1U) & 0x0fU);
    const std::uint8_t gate_high = static_cast<std::uint8_t>(
        (index * 7U + (index >> 2U) * 5U + 9U) & 0x0fU);
    const std::uint8_t up_low = static_cast<std::uint8_t>(
        (index * 11U + (index >> 4U) * 7U + 3U) & 0x0fU);
    const std::uint8_t up_high = static_cast<std::uint8_t>(
        (index * 13U + (index >> 1U) * 3U + 5U) & 0x0fU);
    host_gate_packed[index] =
        static_cast<std::uint8_t>(gate_low | (gate_high << 4U));
    host_up_packed[index] =
        static_cast<std::uint8_t>(up_low | (up_high << 4U));
  }
  fill_nvfp4_m1_scale_distribution(
      host_gate_scales, kScaleColumns,
      NvFp4M1ScaleDistribution::kCheckpointLike);
  fill_nvfp4_m1_scale_distribution(
      host_up_scales, kScaleColumns,
      NvFp4M1ScaleDistribution::kSameBankStress);
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int centered =
        static_cast<int>((column * 19U + (column >> 2U) * 7U + 11U) %
                         127U) -
        63;
    host_activation[column] =
        encode_bf16(static_cast<float>(centered) / 256.0F);
  }

  DeviceBuffer<std::uint8_t> gate_packed;
  DeviceBuffer<std::uint8_t> up_packed;
  DeviceBuffer<std::uint8_t> gate_scales;
  DeviceBuffer<std::uint8_t> up_scales;
  DeviceBuffer<std::uint16_t> activation;
  DeviceBuffer<std::uint16_t> baseline_gate_storage;
  DeviceBuffer<std::uint16_t> baseline_up_storage;
  DeviceBuffer<std::uint16_t> baseline_final_storage;
  DeviceBuffer<std::uint16_t> pair_gate_storage;
  DeviceBuffer<std::uint16_t> pair_up_storage;
  DeviceBuffer<std::uint16_t> pair_final_storage;
  DeviceBuffer<std::uint16_t> fused_gate_storage;
  DeviceBuffer<std::uint16_t> fused_up_storage;
  bool ready = test.cuda_ok(gate_packed.allocate(kPackedCount),
                            label + " allocate gate packed weights");
  ready = ready && test.cuda_ok(up_packed.allocate(kPackedCount),
                                label + " allocate up packed weights");
  ready = ready && test.cuda_ok(gate_scales.allocate(kScaleCount),
                                label + " allocate gate scales");
  ready = ready && test.cuda_ok(up_scales.allocate(kScaleCount),
                                label + " allocate up scales");
  ready = ready && test.cuda_ok(activation.allocate(kColumns),
                                label + " allocate activation");
  const auto allocate_guarded =
      [&](DeviceBuffer<std::uint16_t>& buffer, const std::string& name) {
        return test.cuda_ok(buffer.allocate(kRows + 2U * kGuardElements),
                            label + " allocate guarded " + name);
      };
  ready = ready && allocate_guarded(baseline_gate_storage, "baseline gate");
  ready = ready && allocate_guarded(baseline_up_storage, "baseline up");
  ready = ready && allocate_guarded(baseline_final_storage, "baseline final");
  ready = ready && allocate_guarded(pair_gate_storage, "pair gate");
  ready = ready && allocate_guarded(pair_up_storage, "pair up");
  ready = ready && allocate_guarded(pair_final_storage, "pair final");
  ready = ready && allocate_guarded(fused_gate_storage, "fused gate");
  ready = ready && allocate_guarded(fused_up_storage, "fused up");
  if (!ready) {
    return;
  }

  std::uint16_t* const baseline_gate =
      baseline_gate_storage.get() + kGuardElements;
  std::uint16_t* const baseline_up =
      baseline_up_storage.get() + kGuardElements;
  std::uint16_t* const baseline_final =
      baseline_final_storage.get() + kGuardElements;
  std::uint16_t* const pair_gate =
      pair_gate_storage.get() + kGuardElements;
  std::uint16_t* const pair_up = pair_up_storage.get() + kGuardElements;
  std::uint16_t* const pair_final =
      pair_final_storage.get() + kGuardElements;
  std::uint16_t* const fused_gate =
      fused_gate_storage.get() + kGuardElements;
  std::uint16_t* const fused_up =
      fused_up_storage.get() + kGuardElements;

  const auto upload_inputs = [&](const std::string& case_label) {
    bool upload_ready = test.cuda_ok(
        cudaMemcpyAsync(gate_packed.get(), host_gate_packed.data(),
                        host_gate_packed.size(), cudaMemcpyHostToDevice,
                        stream),
        case_label + " upload gate packed weights");
    upload_ready = upload_ready && test.cuda_ok(
        cudaMemcpyAsync(up_packed.get(), host_up_packed.data(),
                        host_up_packed.size(), cudaMemcpyHostToDevice, stream),
        case_label + " upload up packed weights");
    upload_ready = upload_ready && test.cuda_ok(
        cudaMemcpyAsync(gate_scales.get(), host_gate_scales.data(),
                        host_gate_scales.size(), cudaMemcpyHostToDevice,
                        stream),
        case_label + " upload gate scales");
    upload_ready = upload_ready && test.cuda_ok(
        cudaMemcpyAsync(up_scales.get(), host_up_scales.data(),
                        host_up_scales.size(), cudaMemcpyHostToDevice, stream),
        case_label + " upload up scales");
    upload_ready = upload_ready && test.cuda_ok(
        cudaMemcpyAsync(activation.get(), host_activation.data(),
                        host_activation.size() * sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        case_label + " upload activation");
    return upload_ready;
  };

  const auto launch_single =
      [&](const std::uint8_t* const packed,
          const std::uint8_t* const scales, const float scale_2,
          std::uint16_t* const output) noexcept {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_gate_up_activation_staged_test_cuda(
                packed, scales, scale_2, activation.get(), kRows, kColumns,
                output, static_cast<void*>(stream));
      };
  const auto launch_pair = [&](const NvFp4GateUpPairLauncher launcher,
                               std::uint16_t* const gate_output,
                               std::uint16_t* const up_output) noexcept {
    return launcher(
        gate_packed.get(), gate_scales.get(), kGateWeightScale2,
        up_packed.get(), up_scales.get(), kUpWeightScale2, activation.get(),
        kRows, kColumns, gate_output, up_output,
        static_cast<void*>(stream));
  };
  const auto poison = [&](DeviceBuffer<std::uint16_t>& storage,
                          const std::uint8_t byte,
                          const std::string& operation) {
    return test.cuda_ok(
        cudaMemsetAsync(storage.get(), byte,
                        (kRows + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        operation);
  };

  struct Outputs {
    std::vector<std::uint16_t> baseline_gate;
    std::vector<std::uint16_t> baseline_up;
    std::vector<std::uint16_t> baseline_final;
    std::vector<std::uint16_t> pair_gate;
    std::vector<std::uint16_t> pair_up;
    std::vector<std::uint16_t> pair_final;
    std::vector<std::uint16_t> pair_gate_replay;
    std::vector<std::uint16_t> pair_up_replay;
    std::vector<std::uint16_t> pair_final_replay;
    std::vector<std::uint16_t> fused_gate;
    std::vector<std::uint16_t> fused_up;
    std::vector<std::uint16_t> fused_gate_replay;
    std::vector<std::uint16_t> fused_up_replay;
  } outputs;
  const auto size_output_vectors = [&]() {
    const std::size_t count = kRows + 2U * kGuardElements;
    outputs.baseline_gate.resize(count);
    outputs.baseline_up.resize(count);
    outputs.baseline_final.resize(count);
    outputs.pair_gate.resize(count);
    outputs.pair_up.resize(count);
    outputs.pair_final.resize(count);
    outputs.pair_gate_replay.resize(count);
    outputs.pair_up_replay.resize(count);
    outputs.pair_final_replay.resize(count);
    outputs.fused_gate.resize(count);
    outputs.fused_up.resize(count);
    outputs.fused_gate_replay.resize(count);
    outputs.fused_up_replay.resize(count);
  };
  size_output_vectors();

  const auto copy_guarded =
      [&](std::vector<std::uint16_t>& destination,
          const DeviceBuffer<std::uint16_t>& source,
          const std::string& operation) {
        return test.cuda_ok(
            cudaMemcpyAsync(destination.data(), source.get(),
                            destination.size() * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            operation);
      };
  const auto guard_intact = [&](const std::vector<std::uint16_t>& values,
                                const std::uint16_t guard) {
    for (std::size_t index = 0U; index < kGuardElements; ++index) {
      if (values[index] != guard ||
          values[kGuardElements + kRows + index] != guard) {
        return false;
      }
    }
    return true;
  };
  const auto mismatches = [&](const std::vector<std::uint16_t>& expected,
                              const std::vector<std::uint16_t>& actual) {
    std::size_t count = 0U;
    for (std::size_t row = 0U; row < kRows; ++row) {
      count += expected[kGuardElements + row] !=
                       actual[kGuardElements + row]
                   ? 1U
                   : 0U;
    }
    return count;
  };

  const auto run_case = [&](const std::string& case_label,
                            const bool require_finite,
                            const bool require_signed_nan) {
    bool case_ready = upload_inputs(case_label);
    case_ready = case_ready && poison(baseline_gate_storage, 0xa1U,
                                      case_label + " poison baseline gate");
    case_ready = case_ready && poison(baseline_up_storage, 0xb2U,
                                      case_label + " poison baseline up");
    case_ready = case_ready && poison(baseline_final_storage, 0xc3U,
                                      case_label + " poison baseline final");
    case_ready = case_ready && poison(pair_gate_storage, 0xd4U,
                                      case_label + " poison pair gate");
    case_ready = case_ready && poison(pair_up_storage, 0xe5U,
                                      case_label + " poison pair up");
    case_ready = case_ready && poison(pair_final_storage, 0xf6U,
                                      case_label + " poison pair final");
    case_ready = case_ready && poison(fused_gate_storage, 0x69U,
                                      case_label + " poison fused gate");
    case_ready = case_ready && poison(fused_up_storage, 0x78U,
                                      case_label + " poison fused up");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_single(
            gate_packed.get(), gate_scales.get(), kGateWeightScale2,
            baseline_gate)),
        case_label + " launch staged gate baseline");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_single(
            up_packed.get(), up_scales.get(), kUpWeightScale2, baseline_up)),
        case_label + " launch staged up baseline");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(q3x::runtime::launch_silu_mul_reference_cuda(
            baseline_gate, baseline_up, kRows, baseline_final,
            static_cast<void*>(stream))),
        case_label + " launch production SiLU baseline");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_pair(pair_launcher, pair_gate,
                                             pair_up)),
        case_label + " launch pair-only candidate");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(q3x::runtime::launch_silu_mul_reference_cuda(
            pair_gate, pair_up, kRows, pair_final,
            static_cast<void*>(stream))),
        case_label + " launch pair-only production SiLU");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_pair(fused_launcher, fused_gate,
                                             fused_up)),
        case_label + " launch pair+SiLU candidate");
    case_ready = case_ready && copy_guarded(
        outputs.baseline_gate, baseline_gate_storage,
        case_label + " copy baseline gate");
    case_ready = case_ready && copy_guarded(
        outputs.baseline_up, baseline_up_storage,
        case_label + " copy baseline up");
    case_ready = case_ready && copy_guarded(
        outputs.baseline_final, baseline_final_storage,
        case_label + " copy baseline final");
    case_ready = case_ready && copy_guarded(
        outputs.pair_gate, pair_gate_storage,
        case_label + " copy pair gate");
    case_ready = case_ready && copy_guarded(
        outputs.pair_up, pair_up_storage, case_label + " copy pair up");
    case_ready = case_ready && copy_guarded(
        outputs.pair_final, pair_final_storage,
        case_label + " copy pair final");
    case_ready = case_ready && copy_guarded(
        outputs.fused_gate, fused_gate_storage,
        case_label + " copy fused gate");
    case_ready = case_ready && copy_guarded(
        outputs.fused_up, fused_up_storage, case_label + " copy fused up");
    case_ready = case_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), case_label + " first synchronize");
    if (!case_ready) {
      return false;
    }

    case_ready = poison(pair_gate_storage, 0xd4U,
                        case_label + " poison replay pair gate");
    case_ready = case_ready && poison(pair_up_storage, 0xe5U,
                                      case_label + " poison replay pair up");
    case_ready = case_ready && poison(pair_final_storage, 0xf6U,
                                      case_label + " poison replay pair final");
    case_ready = case_ready && poison(fused_gate_storage, 0x69U,
                                      case_label + " poison replay fused gate");
    case_ready = case_ready && poison(fused_up_storage, 0x78U,
                                      case_label + " poison replay fused up");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_pair(pair_launcher, pair_gate,
                                             pair_up)),
        case_label + " replay pair-only candidate");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(q3x::runtime::launch_silu_mul_reference_cuda(
            pair_gate, pair_up, kRows, pair_final,
            static_cast<void*>(stream))),
        case_label + " replay pair-only production SiLU");
    case_ready = case_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_pair(fused_launcher, fused_gate,
                                             fused_up)),
        case_label + " replay pair+SiLU candidate");
    case_ready = case_ready && copy_guarded(
        outputs.pair_gate_replay, pair_gate_storage,
        case_label + " copy replay pair gate");
    case_ready = case_ready && copy_guarded(
        outputs.pair_up_replay, pair_up_storage,
        case_label + " copy replay pair up");
    case_ready = case_ready && copy_guarded(
        outputs.pair_final_replay, pair_final_storage,
        case_label + " copy replay pair final");
    case_ready = case_ready && copy_guarded(
        outputs.fused_gate_replay, fused_gate_storage,
        case_label + " copy replay fused gate");
    case_ready = case_ready && copy_guarded(
        outputs.fused_up_replay, fused_up_storage,
        case_label + " copy replay fused up");

    std::vector<std::uint8_t> observed_gate_packed(kPackedCount);
    std::vector<std::uint8_t> observed_up_packed(kPackedCount);
    std::vector<std::uint8_t> observed_gate_scales(kScaleCount);
    std::vector<std::uint8_t> observed_up_scales(kScaleCount);
    std::vector<std::uint16_t> observed_activation(kColumns);
    case_ready = case_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_gate_packed.data(), gate_packed.get(),
                        observed_gate_packed.size(), cudaMemcpyDeviceToHost,
                        stream),
        case_label + " copy preserved gate packed weights");
    case_ready = case_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_up_packed.data(), up_packed.get(),
                        observed_up_packed.size(), cudaMemcpyDeviceToHost,
                        stream),
        case_label + " copy preserved up packed weights");
    case_ready = case_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_gate_scales.data(), gate_scales.get(),
                        observed_gate_scales.size(), cudaMemcpyDeviceToHost,
                        stream),
        case_label + " copy preserved gate scales");
    case_ready = case_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_up_scales.data(), up_scales.get(),
                        observed_up_scales.size(), cudaMemcpyDeviceToHost,
                        stream),
        case_label + " copy preserved up scales");
    case_ready = case_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_activation.data(), activation.get(),
                        observed_activation.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        case_label + " copy preserved activation");
    case_ready = case_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), case_label + " replay synchronize");
    if (!case_ready) {
      return false;
    }

    const std::size_t pair_gate_mismatches =
        mismatches(outputs.baseline_gate, outputs.pair_gate);
    const std::size_t pair_up_mismatches =
        mismatches(outputs.baseline_up, outputs.pair_up);
    const std::size_t pair_final_mismatches =
        mismatches(outputs.baseline_final, outputs.pair_final);
    const std::size_t fused_final_mismatches =
        mismatches(outputs.baseline_final, outputs.fused_gate);
    const std::size_t fused_up_mismatches =
        mismatches(outputs.baseline_up, outputs.fused_up);
    const std::size_t replay_mismatches =
        mismatches(outputs.pair_gate, outputs.pair_gate_replay) +
        mismatches(outputs.pair_up, outputs.pair_up_replay) +
        mismatches(outputs.pair_final, outputs.pair_final_replay) +
        mismatches(outputs.fused_gate, outputs.fused_gate_replay) +
        mismatches(outputs.fused_up, outputs.fused_up_replay);
    const bool guards_intact =
        guard_intact(outputs.baseline_gate, kBaselineGateGuard) &&
        guard_intact(outputs.baseline_up, kBaselineUpGuard) &&
        guard_intact(outputs.baseline_final, kBaselineFinalGuard) &&
        guard_intact(outputs.pair_gate, kPairGateGuard) &&
        guard_intact(outputs.pair_up, kPairUpGuard) &&
        guard_intact(outputs.pair_final, kPairFinalGuard) &&
        guard_intact(outputs.pair_gate_replay, kPairGateGuard) &&
        guard_intact(outputs.pair_up_replay, kPairUpGuard) &&
        guard_intact(outputs.pair_final_replay, kPairFinalGuard) &&
        guard_intact(outputs.fused_gate, kFusedGateGuard) &&
        guard_intact(outputs.fused_up, kFusedUpGuard) &&
        guard_intact(outputs.fused_gate_replay, kFusedGateGuard) &&
        guard_intact(outputs.fused_up_replay, kFusedUpGuard);
    const bool inputs_preserved =
        observed_gate_packed == host_gate_packed &&
        observed_up_packed == host_up_packed &&
        observed_gate_scales == host_gate_scales &&
        observed_up_scales == host_up_scales &&
        observed_activation == host_activation;
    std::size_t unexpected_nonfinite = 0U;
    if (require_finite) {
      for (std::size_t row = 0U; row < kRows; ++row) {
        unexpected_nonfinite +=
            !is_bf16_finite(outputs.baseline_final[kGuardElements + row])
                ? 1U
                : 0U;
        unexpected_nonfinite +=
            !is_bf16_finite(outputs.baseline_up[kGuardElements + row]) ? 1U
                                                                        : 0U;
        unexpected_nonfinite +=
            !is_bf16_finite(outputs.fused_gate[kGuardElements + row]) ? 1U
                                                                       : 0U;
        unexpected_nonfinite +=
            !is_bf16_finite(outputs.fused_up[kGuardElements + row]) ? 1U
                                                                     : 0U;
      }
    }
    bool nan_class_sign = true;
    if (require_signed_nan) {
      for (std::size_t row = 0U; row < 2U; ++row) {
        const std::uint16_t expected =
            outputs.baseline_final[kGuardElements + row];
        const std::uint16_t actual =
            outputs.fused_gate[kGuardElements + row];
        nan_class_sign =
            nan_class_sign && is_bf16_nan(expected) && is_bf16_nan(actual) &&
            ((expected ^ actual) & 0x8000U) == 0U;
      }
      for (std::size_t row = 2U; row < 4U; ++row) {
        const std::uint16_t expected =
            outputs.baseline_up[kGuardElements + row];
        const std::uint16_t actual =
            outputs.fused_up[kGuardElements + row];
        nan_class_sign =
            nan_class_sign && is_bf16_nan(expected) && is_bf16_nan(actual) &&
            ((expected ^ actual) & 0x8000U) == 0U;
      }
    }
    const bool bitwise =
        pair_gate_mismatches == 0U && pair_up_mismatches == 0U &&
        pair_final_mismatches == 0U && fused_final_mismatches == 0U &&
        fused_up_mismatches == 0U && replay_mismatches == 0U;
    const bool case_gate =
        bitwise && guards_intact && inputs_preserved &&
        unexpected_nonfinite == 0U && nan_class_sign;
    test.expect(bitwise,
                case_label + " preserves raw/final BF16 bits and replay");
    test.expect(guards_intact,
                case_label + " preserves every output guard");
    test.expect(inputs_preserved,
                case_label + " preserves both matrices and activation");
    if (require_finite) {
      test.expect(unexpected_nonfinite == 0U,
                  case_label + " keeps every finite fixture output finite");
    }
    if (require_signed_nan) {
      test.expect(nan_class_sign,
                  case_label + " preserves signed NaN class/sign");
    }
    std::cout << "NVFP4_M1_GATE_UP_PAIR_DEFAULT_DIFF: fixture="
              << case_label
              << " pair_gate_mismatches=" << pair_gate_mismatches << '/'
              << kRows << " pair_up_mismatches=" << pair_up_mismatches << '/'
              << kRows
              << " pair_plus_production_silu_mismatches="
              << pair_final_mismatches << '/' << kRows
              << " fused_final_mismatches=" << fused_final_mismatches << '/'
              << kRows << " fused_up_mismatches=" << fused_up_mismatches
              << '/' << kRows << " replay_mismatches=" << replay_mismatches
              << '/' << (5U * kRows)
              << " guards=" << (guards_intact ? "intact" : "BAD")
              << " inputs_preserved="
              << (inputs_preserved ? "true" : "false")
              << " unexpected_nonfinite=" << unexpected_nonfinite
              << " signed_nan_class_sign="
              << (nan_class_sign ? "true" : "false")
              << " gate=" << (case_gate ? "PASS" : "FAIL") << '\n';
    return case_gate;
  };

  const bool finite_gate =
      run_case(label + " finite", true, false);

  const auto expect_invalid_before_enqueue =
      [&](const auto& invalid_launch, const std::string& operation) {
        cudaGraph_t graph = nullptr;
        bool capture_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
            label + " " + operation + " begin capture");
        cudaError_t launch_status = cudaErrorUnknown;
        if (capture_ready) {
          launch_status = static_cast<cudaError_t>(invalid_launch());
          capture_ready =
              test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           label + " " + operation + " end capture") &&
              capture_ready;
        }
        std::size_t node_count = std::numeric_limits<std::size_t>::max();
        if (capture_ready) {
          capture_ready = test.cuda_ok(
              cudaGraphGetNodes(graph, nullptr, &node_count),
              label + " " + operation + " query captured nodes");
        }
        const bool rejected_before_enqueue =
            capture_ready && launch_status == cudaErrorInvalidValue &&
            node_count == 0U;
        test.expect(rejected_before_enqueue,
                    label + " " + operation + " fails before enqueue");
        if (graph != nullptr) {
          (void)test.cuda_ok(cudaGraphDestroy(graph),
                             label + " " + operation + " destroy graph");
        }
        return rejected_before_enqueue;
      };
  bool invalid_contract_gate = true;
  const auto check_launcher_contract =
      [&](const NvFp4GateUpPairLauncher launcher,
          const std::string& candidate) {
        const auto status =
            [&](const std::uint8_t* const gate_packed_pointer,
                const std::uint8_t* const gate_scale_pointer,
                const std::uint8_t* const up_packed_pointer,
                const std::uint8_t* const up_scale_pointer,
                const std::uint16_t* const activation_pointer,
                const std::size_t rows, const std::size_t columns,
                std::uint16_t* const gate_output_pointer,
                std::uint16_t* const up_output_pointer) noexcept {
              return launcher(
                  gate_packed_pointer, gate_scale_pointer,
                  kGateWeightScale2, up_packed_pointer, up_scale_pointer,
                  kUpWeightScale2, activation_pointer, rows, columns,
                  gate_output_pointer, up_output_pointer,
                  static_cast<void*>(stream));
            };
        const auto expect_invalid = [&](const auto& launch,
                                        const std::string& reason) {
          const bool rejected = expect_invalid_before_enqueue(
              launch, candidate + " " + reason);
          invalid_contract_gate = invalid_contract_gate && rejected;
        };
        expect_invalid(
            [&]() noexcept {
              return status(nullptr, gate_scales.get(), up_packed.get(),
                            up_scales.get(), activation.get(), kRows,
                            kColumns, pair_gate, pair_up);
            },
            "null gate weights");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), nullptr, up_packed.get(),
                            up_scales.get(), activation.get(), kRows,
                            kColumns, pair_gate, pair_up);
            },
            "null gate scales");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), gate_scales.get(), nullptr,
                            up_scales.get(), activation.get(), kRows,
                            kColumns, pair_gate, pair_up);
            },
            "null up weights");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), gate_scales.get(),
                            up_packed.get(), nullptr, activation.get(), kRows,
                            kColumns, pair_gate, pair_up);
            },
            "null up scales");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), gate_scales.get(),
                            up_packed.get(), up_scales.get(), nullptr, kRows,
                            kColumns, pair_gate, pair_up);
            },
            "null activation");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), gate_scales.get(),
                            up_packed.get(), up_scales.get(), activation.get(),
                            kRows, kColumns, nullptr, pair_up);
            },
            "null gate output");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), gate_scales.get(),
                            up_packed.get(), up_scales.get(), activation.get(),
                            kRows, kColumns, pair_gate, nullptr);
            },
            "null up output");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), gate_scales.get(),
                            up_packed.get(), up_scales.get(), activation.get(),
                            kRows - 4U, kColumns, pair_gate, pair_up);
            },
            "near-miss rows");
        expect_invalid(
            [&]() noexcept {
              return status(gate_packed.get(), gate_scales.get(),
                            up_packed.get(), up_scales.get(), activation.get(),
                            kRows, kColumns + 16U, pair_gate, pair_up);
            },
            "near-miss columns");
        expect_invalid(
            [&]() noexcept {
              return launcher(
                  gate_packed.get(), gate_scales.get(), -1.0F,
                  up_packed.get(), up_scales.get(), kUpWeightScale2,
                  activation.get(), kRows, kColumns, pair_gate, pair_up,
                  static_cast<void*>(stream));
            },
            "negative gate scale2");
        expect_invalid(
            [&]() noexcept {
              return launcher(
                  gate_packed.get(), gate_scales.get(),
                  std::numeric_limits<float>::quiet_NaN(), up_packed.get(),
                  up_scales.get(), kUpWeightScale2, activation.get(), kRows,
                  kColumns, pair_gate, pair_up, static_cast<void*>(stream));
            },
            "NaN gate scale2");
        expect_invalid(
            [&]() noexcept {
              return launcher(
                  gate_packed.get(), gate_scales.get(), kGateWeightScale2,
                  up_packed.get(), up_scales.get(), -1.0F, activation.get(),
                  kRows, kColumns, pair_gate, pair_up,
                  static_cast<void*>(stream));
            },
            "negative up scale2");
        expect_invalid(
            [&]() noexcept {
              return launcher(
                  gate_packed.get(), gate_scales.get(), kGateWeightScale2,
                  up_packed.get(), up_scales.get(),
                  std::numeric_limits<float>::infinity(), activation.get(),
                  kRows, kColumns, pair_gate, pair_up,
                  static_cast<void*>(stream));
