        arguments.residual_left = reinterpret_cast<const std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(arguments.residual_left) + 1U);
      }),
      residual_norm_dead_up_alignment_cases, "unaligned residual left");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.residual_right = reinterpret_cast<const std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(arguments.residual_right) + 1U);
      }),
      residual_norm_dead_up_alignment_cases, "unaligned residual right");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.norm_weight = reinterpret_cast<const std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(arguments.norm_weight) + 1U);
      }),
      residual_norm_dead_up_alignment_cases, "unaligned norm weight");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.residual_output = reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(arguments.residual_output) +
            1U);
      }),
      residual_norm_dead_up_alignment_cases, "unaligned residual output");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.gate_output = reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(arguments.gate_output) + 1U);
      }),
      residual_norm_dead_up_alignment_cases, "unaligned gate output");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.up_workspace = reinterpret_cast<std::uint16_t*>(
            reinterpret_cast<std::uintptr_t>(arguments.up_workspace) + 1U);
      }),
      residual_norm_dead_up_alignment_cases, "unaligned up workspace");

  struct ReadOnlyAliasTarget final {
    const void* pointer;
    const char* name;
  };
  const std::array<ReadOnlyAliasTarget, 7U> read_only_alias_targets{{
      {fake_gate_packed, "gate weights"},
      {fake_gate_scales, "gate scales"},
      {fake_up_packed, "up weights"},
      {fake_up_scales, "up scales"},
      {fake_residual_left, "residual left"},
      {fake_residual_right, "residual right"},
      {fake_norm_weight, "norm weight"},
  }};
  const std::array<const char*, 3U> writable_output_names{{
      "residual output", "gate output", "up workspace"}};
  for (const ReadOnlyAliasTarget& target : read_only_alias_targets) {
    for (std::size_t output_index = 0U;
         output_index < writable_output_names.size(); ++output_index) {
      ResidualNormDeadUpArguments arguments = valid_dead_up_arguments;
      auto* const alias = reinterpret_cast<std::uint16_t*>(
          const_cast<void*>(target.pointer));
      if (output_index == 0U) {
        arguments.residual_output = alias;
      } else if (output_index == 1U) {
        arguments.gate_output = alias;
      } else {
        arguments.up_workspace = alias;
      }
      expect_residual_norm_dead_up_invalid(
          arguments, residual_norm_dead_up_alias_cases,
          std::string(writable_output_names[output_index]) + " aliases " +
              target.name);
    }
  }
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.gate_output = arguments.residual_output;
      }),
      residual_norm_dead_up_alias_cases,
      "gate output aliases residual output");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.up_workspace = arguments.residual_output;
      }),
      residual_norm_dead_up_alias_cases,
      "up workspace aliases residual output");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.up_workspace = arguments.gate_output;
      }),
      residual_norm_dead_up_alias_cases,
      "up workspace aliases gate output");

  constexpr std::uintptr_t kMaximumAddress =
      std::numeric_limits<std::uintptr_t>::max();
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.gate_packed_weights =
            reinterpret_cast<const std::uint8_t*>(kMaximumAddress - 3U);
      }),
      residual_norm_dead_up_overflow_cases, "gate packed range overflow");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.residual_left =
            reinterpret_cast<const std::uint16_t*>(kMaximumAddress - 1U);
      }),
      residual_norm_dead_up_overflow_cases, "residual input range overflow");
  expect_residual_norm_dead_up_invalid(
      mutate_dead_up_arguments([](auto& arguments) {
        arguments.residual_output =
            reinterpret_cast<std::uint16_t*>(kMaximumAddress - 1U);
      }),
      residual_norm_dead_up_overflow_cases,
      "residual output range overflow");

  constexpr std::size_t kExpectedDeadUpNullCases = 10U;
  constexpr std::size_t kExpectedDeadUpScalarCases = 6U;
  constexpr std::size_t kExpectedDeadUpShapeCases = 3U;
  constexpr std::size_t kExpectedDeadUpAlignmentCases = 8U;
  constexpr std::size_t kExpectedDeadUpAliasCases = 24U;
  constexpr std::size_t kExpectedDeadUpOverflowCases = 3U;
  constexpr std::size_t kExpectedDeadUpInvalidCases =
      kExpectedDeadUpNullCases + kExpectedDeadUpScalarCases +
      kExpectedDeadUpShapeCases + kExpectedDeadUpAlignmentCases +
      kExpectedDeadUpAliasCases + kExpectedDeadUpOverflowCases;
  static_assert(kExpectedDeadUpInvalidCases == 54U);
  residual_norm_dead_up_invalid_gate =
      residual_norm_dead_up_invalid_gate &&
      residual_norm_dead_up_null_cases == kExpectedDeadUpNullCases &&
      residual_norm_dead_up_scalar_cases == kExpectedDeadUpScalarCases &&
      residual_norm_dead_up_shape_cases == kExpectedDeadUpShapeCases &&
      residual_norm_dead_up_alignment_cases ==
          kExpectedDeadUpAlignmentCases &&
      residual_norm_dead_up_alias_cases == kExpectedDeadUpAliasCases &&
      residual_norm_dead_up_overflow_cases == kExpectedDeadUpOverflowCases &&
      residual_norm_dead_up_invalid_cases == kExpectedDeadUpInvalidCases;
  test.expect(residual_norm_dead_up_invalid_gate,
              label + " dead-up complete invalid matrix captures zero nodes");
  std::cout << "NVFP4_M1_RESIDUAL_NORM_GATE_UP_DEAD_UP_INVALID: "
            << "cases=" << residual_norm_dead_up_invalid_cases
            << " null=" << residual_norm_dead_up_null_cases
            << " scalar=" << residual_norm_dead_up_scalar_cases
            << " shape=" << residual_norm_dead_up_shape_cases
            << " alignment=" << residual_norm_dead_up_alignment_cases
            << " alias=" << residual_norm_dead_up_alias_cases
            << " overflow=" << residual_norm_dead_up_overflow_cases
            << " required_nodes_each=0 gate="
            << (residual_norm_dead_up_invalid_gate ? "PASS" : "FAIL")
            << '\n';
  const bool residual_norm_public_contract_gate =
      residual_norm_identity_gate && residual_norm_invalid_gate &&
      residual_norm_reduction_ab_topology_gate &&
      residual_norm_coarsened_topology_gate &&
      residual_norm_coarsened_invalid_gate;
  test.expect(residual_norm_public_contract_gate,
              label + " residual/norm public contract passes");
  std::cout << "NVFP4_M1_RESIDUAL_NORM_GATE_UP_SILU_PUBLIC_CONTRACT: "
            << "public_nodes=1 replay_nodes=1 same_func_grid_block_shared="
            << (residual_norm_identity_gate ? "true" : "false")
            << " predecessor_nodes=1 distinct_64x256="
            << (residual_norm_coarsened_topology_gate ? "true" : "false")
            << " invalid_zero_node_gate="
            << (residual_norm_invalid_gate ? "PASS" : "FAIL")
            << " shared_tree_ab_distinct_same_topology="
            << (residual_norm_reduction_ab_topology_gate ? "true" : "false")
            << " gate="
            << (residual_norm_public_contract_gate ? "PASS" : "FAIL")
            << '\n';

  std::vector<std::uint16_t> host_residual_left(kColumns);
  std::vector<std::uint16_t> host_residual_right(kColumns);
  std::vector<std::uint16_t> host_norm_weight(kColumns);
  for (std::size_t column = 0U; column < kColumns; ++column) {
    const int left_centered =
        static_cast<int>((column * 23U + (column >> 2U) * 5U + 3U) %
                         113U) -
        56;
    const int right_centered =
        static_cast<int>((column * 17U + (column >> 1U) * 11U + 7U) %
                         109U) -
        54;
    const int weight_centered =
        static_cast<int>((column * 13U + (column >> 3U) * 7U + 19U) %
                         67U) -
        33;
    host_residual_left[column] =
        encode_bf16(static_cast<float>(left_centered) / 192.0F);
    host_residual_right[column] =
        encode_bf16(static_cast<float>(right_centered) / 224.0F);
    host_norm_weight[column] =
        encode_bf16(static_cast<float>(weight_centered) / 384.0F);
  }
  DeviceBuffer<std::uint16_t> residual_left;
  DeviceBuffer<std::uint16_t> residual_right;
  DeviceBuffer<std::uint16_t> norm_weight;
  DeviceBuffer<std::uint16_t> normalized_activation;
  DeviceBuffer<std::uint16_t> baseline_residual_storage;
  DeviceBuffer<std::uint16_t> candidate_residual_storage;
  bool residual_ready = test.cuda_ok(
      residual_left.allocate(kColumns), label + " allocate residual left");
  residual_ready = residual_ready && test.cuda_ok(
      residual_right.allocate(kColumns), label + " allocate residual right");
  residual_ready = residual_ready && test.cuda_ok(
      norm_weight.allocate(kColumns), label + " allocate norm weight");
  residual_ready = residual_ready && test.cuda_ok(
      normalized_activation.allocate(kColumns),
      label + " allocate normalized activation");
  residual_ready = residual_ready && test.cuda_ok(
      baseline_residual_storage.allocate(kColumns + 2U * kGuardElements),
      label + " allocate guarded baseline residual");
  residual_ready = residual_ready && test.cuda_ok(
      candidate_residual_storage.allocate(kColumns + 2U * kGuardElements),
      label + " allocate guarded candidate residual");
  bool residual_norm_gate = false;
  bool residual_norm_reduction_ab_gate = false;
  if (residual_ready) {
    constexpr float kNormEpsilon = 1.0e-6F;
    std::uint16_t* const baseline_residual =
        baseline_residual_storage.get() + kGuardElements;
    std::uint16_t* const candidate_residual =
        candidate_residual_storage.get() + kGuardElements;
    residual_ready = upload_inputs(label + " residual/norm finite");
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemcpyAsync(residual_left.get(), host_residual_left.data(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        label + " upload residual left");
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemcpyAsync(residual_right.get(), host_residual_right.data(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        label + " upload residual right");
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemcpyAsync(norm_weight.get(), host_norm_weight.data(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        label + " upload norm weight");
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemsetAsync(baseline_residual_storage.get(), 0xa7U,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        label + " poison baseline residual");
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_residual_storage.get(), 0xb8U,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        label + " poison candidate residual");
    residual_ready = residual_ready && poison(
        baseline_final_storage, 0xc9U,
        label + " poison residual baseline final");
    residual_ready = residual_ready && poison(
        baseline_up_storage, 0xdaU,
        label + " poison residual baseline up");
    residual_ready = residual_ready && poison(
        fused_gate_storage, 0xebU,
        label + " poison residual candidate final");
    residual_ready = residual_ready && poison(
        fused_up_storage, 0xfcU,
        label + " poison residual candidate up");
    residual_ready = residual_ready && test.cuda_ok(
        launch_residual_norm_test_baseline<kColumns>(
            residual_left.get(), residual_right.get(), norm_weight.get(),
            kNormEpsilon, baseline_residual, normalized_activation.get(),
            stream),
        label + " launch bounded residual/norm baseline");
    residual_ready = residual_ready && test.cuda_ok(
        static_cast<cudaError_t>(fused_launcher(
            gate_packed.get(), gate_scales.get(), kGateWeightScale2,
            up_packed.get(), up_scales.get(), kUpWeightScale2,
            normalized_activation.get(), kRows, kColumns, baseline_final,
            baseline_up, static_cast<void*>(stream))),
        label + " launch bounded normalized gate/up baseline");
    residual_ready = residual_ready && test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_test_cuda(
                gate_packed.get(), gate_scales.get(), kGateWeightScale2,
                up_packed.get(), up_scales.get(), kUpWeightScale2,
                residual_left.get(), residual_right.get(), norm_weight.get(),
                kNormEpsilon, kRows, kColumns, candidate_residual, fused_gate,
                fused_up, static_cast<void*>(stream))),
        label + " launch bounded residual/norm fused candidate");

    std::vector<std::uint16_t> observed_baseline_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_baseline_final(
        kRows + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_baseline_up(
        kRows + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_final(
        kRows + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_up(
        kRows + 2U * kGuardElements);
    const auto copy_residual =
        [&](std::vector<std::uint16_t>& destination,
            const DeviceBuffer<std::uint16_t>& source,
            const std::string& operation) {
          return test.cuda_ok(
              cudaMemcpyAsync(destination.data(), source.get(),
                              destination.size() * sizeof(std::uint16_t),
                              cudaMemcpyDeviceToHost, stream),
              operation);
        };
    residual_ready = residual_ready && copy_residual(
        observed_baseline_residual, baseline_residual_storage,
        label + " copy baseline residual");
    residual_ready = residual_ready && copy_residual(
        observed_candidate_residual, candidate_residual_storage,
        label + " copy candidate residual");
    residual_ready = residual_ready && copy_residual(
        observed_baseline_final, baseline_final_storage,
        label + " copy residual baseline final");
    residual_ready = residual_ready && copy_residual(
        observed_baseline_up, baseline_up_storage,
        label + " copy residual baseline up");
    residual_ready = residual_ready && copy_residual(
        observed_candidate_final, fused_gate_storage,
        label + " copy residual candidate final");
    residual_ready = residual_ready && copy_residual(
        observed_candidate_up, fused_up_storage,
        label + " copy residual candidate up");
    std::vector<std::uint16_t> observed_left(kColumns);
    std::vector<std::uint16_t> observed_right(kColumns);
    std::vector<std::uint16_t> observed_norm(kColumns);
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_left.data(), residual_left.get(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        label + " copy preserved residual left");
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_right.data(), residual_right.get(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        label + " copy preserved residual right");
    residual_ready = residual_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_norm.data(), norm_weight.get(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        label + " copy preserved norm weight");
    residual_ready = residual_ready && test.cuda_ok(
        cudaStreamSynchronize(stream),
        label + " bounded residual/norm synchronize");
    if (residual_ready) {
      std::size_t residual_mismatches = 0U;
      std::size_t final_mismatches = 0U;
      std::size_t up_mismatches = 0U;
      for (std::size_t index = 0U; index < kColumns; ++index) {
        const std::size_t guarded = kGuardElements + index;
        residual_mismatches +=
            observed_baseline_residual[guarded] !=
            observed_candidate_residual[guarded];
      }
      for (std::size_t row = 0U; row < kRows; ++row) {
        const std::size_t guarded = kGuardElements + row;
        final_mismatches += observed_baseline_final[guarded] !=
                            observed_candidate_final[guarded];
        up_mismatches += observed_baseline_up[guarded] !=
                         observed_candidate_up[guarded];
      }
      bool guards = true;
      for (std::size_t index = 0U; index < kGuardElements; ++index) {
        guards = guards && observed_baseline_residual[index] == 0xa7a7U &&
                 observed_candidate_residual[index] == 0xb8b8U &&
                 observed_baseline_residual[kGuardElements + kColumns +
                                            index] == 0xa7a7U &&
                 observed_candidate_residual[kGuardElements + kColumns +
                                             index] == 0xb8b8U &&
                 observed_baseline_final[index] == 0xc9c9U &&
                 observed_baseline_up[index] == 0xdadaU &&
                 observed_candidate_final[index] == 0xebebU &&
                 observed_candidate_up[index] == 0xfcfcU &&
                 observed_baseline_final[kGuardElements + kRows + index] ==
                     0xc9c9U &&
                 observed_baseline_up[kGuardElements + kRows + index] ==
                     0xdadaU &&
                 observed_candidate_final[kGuardElements + kRows + index] ==
                     0xebebU &&
                 observed_candidate_up[kGuardElements + kRows + index] ==
                     0xfcfcU;
      }
      const bool inputs_preserved =
          observed_left == host_residual_left &&
          observed_right == host_residual_right &&
          observed_norm == host_norm_weight;
      residual_norm_gate = residual_mismatches == 0U &&
                           final_mismatches == 0U && up_mismatches == 0U &&
                           guards && inputs_preserved;
      test.expect(residual_norm_gate,
                  label + " bounded residual/norm fusion is bitwise");
      std::cout << "NVFP4_M1_RESIDUAL_NORM_GATE_UP_SILU_DEFAULT_DIFF: "
                << "residual_mismatches=" << residual_mismatches << '/'
                << kColumns << " final_gate_mismatches=" << final_mismatches
                << '/' << kRows << " up_mismatches=" << up_mismatches << '/'
                << kRows << " guards=" << (guards ? "intact" : "BAD")
                << " inputs_preserved="
                << (inputs_preserved ? "true" : "false")
                << " gate=" << (residual_norm_gate ? "PASS" : "FAIL")
                << '\n';

      bool reduction_ab_ready = test.cuda_ok(
          cudaMemsetAsync(baseline_residual_storage.get(), 0xa7U,
                          (kColumns + 2U * kGuardElements) *
                              sizeof(std::uint16_t),
                          stream),
          label + " poison shared-tree A/B residual");
      reduction_ab_ready = reduction_ab_ready && poison(
          baseline_final_storage, 0xc9U,
          label + " poison shared-tree A/B final");
      reduction_ab_ready = reduction_ab_ready && poison(
          baseline_up_storage, 0xdaU,
          label + " poison shared-tree A/B up");
      reduction_ab_ready = reduction_ab_ready && test.cuda_ok(
          static_cast<cudaError_t>(q3x::kernels::
              launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_shared_tree_test_cuda(
                  gate_packed.get(), gate_scales.get(), kGateWeightScale2,
                  up_packed.get(), up_scales.get(), kUpWeightScale2,
                  residual_left.get(), residual_right.get(),
                  norm_weight.get(), kNormEpsilon, kRows, kColumns,
                  baseline_residual, baseline_final, baseline_up,
                  static_cast<void*>(stream))),
          label + " launch shared-tree fused A/B baseline");
      reduction_ab_ready = reduction_ab_ready && copy_residual(
          observed_baseline_residual, baseline_residual_storage,
          label + " copy shared-tree A/B residual");
      reduction_ab_ready = reduction_ab_ready && copy_residual(
          observed_baseline_final, baseline_final_storage,
          label + " copy shared-tree A/B final");
      reduction_ab_ready = reduction_ab_ready && copy_residual(
          observed_baseline_up, baseline_up_storage,
          label + " copy shared-tree A/B up");
      reduction_ab_ready = reduction_ab_ready && test.cuda_ok(
          cudaStreamSynchronize(stream),
          label + " shared-tree/warp-tail A/B synchronize");
      std::size_t ab_residual_mismatches = 0U;
      std::size_t ab_final_mismatches = 0U;
      std::size_t ab_up_mismatches = 0U;
      bool ab_guards = reduction_ab_ready;
      if (reduction_ab_ready) {
        for (std::size_t index = 0U; index < kColumns; ++index) {
          const std::size_t guarded = kGuardElements + index;
          ab_residual_mismatches +=
              observed_baseline_residual[guarded] !=
              observed_candidate_residual[guarded];
        }
        for (std::size_t row = 0U; row < kRows; ++row) {
          const std::size_t guarded = kGuardElements + row;
          ab_final_mismatches += observed_baseline_final[guarded] !=
                                 observed_candidate_final[guarded];
          ab_up_mismatches += observed_baseline_up[guarded] !=
                              observed_candidate_up[guarded];
        }
        for (std::size_t index = 0U; index < kGuardElements; ++index) {
          ab_guards =
              ab_guards && observed_baseline_residual[index] == 0xa7a7U &&
              observed_baseline_residual[kGuardElements + kColumns + index] ==
                  0xa7a7U &&
              observed_baseline_final[index] == 0xc9c9U &&
              observed_baseline_up[index] == 0xdadaU &&
              observed_baseline_final[kGuardElements + kRows + index] ==
                  0xc9c9U &&
              observed_baseline_up[kGuardElements + kRows + index] ==
                  0xdadaU;
        }
      }
      residual_norm_reduction_ab_gate =
          reduction_ab_ready && ab_residual_mismatches == 0U &&
          ab_final_mismatches == 0U && ab_up_mismatches == 0U && ab_guards;
      test.expect(residual_norm_reduction_ab_gate,
                  label + " shared-tree/warp-tail fused A/B is bitwise");
      std::cout << "NVFP4_M1_RESIDUAL_NORM_REDUCTION_AB_DIFF: "
                << "shared_tree_vs_warp_tail_residual_mismatches="
                << ab_residual_mismatches << '/' << kColumns
                << " final_gate_mismatches=" << ab_final_mismatches << '/'
                << kRows << " up_mismatches=" << ab_up_mismatches << '/'
                << kRows << " guards=" << (ab_guards ? "intact" : "BAD")
                << " gate="
                << (residual_norm_reduction_ab_gate ? "PASS" : "FAIL")
                << '\n';
    }
  }

  bool residual_norm_nonfinite_gate = false;
  if (residual_ready) {
    constexpr float kNormEpsilon = 1.0e-6F;
    const std::string nonfinite_label =
        label + " residual/norm signed NaN and infinity";
    host_residual_left[0U] = 0x7f80U;
    host_residual_right[0U] = 0xff80U;
    host_residual_left[1U] = 0x7fc1U;
    host_residual_right[2U] = 0xffc1U;
    host_norm_weight[3U] = 0x7f80U;
    host_norm_weight[4U] = 0xff80U;

    std::uint16_t* const baseline_residual =
        baseline_residual_storage.get() + kGuardElements;
    std::uint16_t* const candidate_residual =
        candidate_residual_storage.get() + kGuardElements;
    bool nonfinite_ready = upload_inputs(nonfinite_label);
    const auto upload_bf16 =
        [&](DeviceBuffer<std::uint16_t>& destination,
            const std::vector<std::uint16_t>& source,
            const std::string& operation) {
          return test.cuda_ok(
              cudaMemcpyAsync(destination.get(), source.data(),
                              source.size() * sizeof(std::uint16_t),
                              cudaMemcpyHostToDevice, stream),
              operation);
        };
    nonfinite_ready = nonfinite_ready && upload_bf16(
        residual_left, host_residual_left,
        nonfinite_label + " upload residual left");
    nonfinite_ready = nonfinite_ready && upload_bf16(
        residual_right, host_residual_right,
        nonfinite_label + " upload residual right");
    nonfinite_ready = nonfinite_ready && upload_bf16(
        norm_weight, host_norm_weight,
        nonfinite_label + " upload norm weight");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        cudaMemsetAsync(baseline_residual_storage.get(), 0x13U,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        nonfinite_label + " poison baseline residual");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_residual_storage.get(), 0x24U,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        nonfinite_label + " poison candidate residual");
    nonfinite_ready = nonfinite_ready && poison(
        baseline_final_storage, 0x35U,
        nonfinite_label + " poison baseline final");
    nonfinite_ready = nonfinite_ready && poison(
        baseline_up_storage, 0x46U,
        nonfinite_label + " poison baseline up");
    nonfinite_ready = nonfinite_ready && poison(
        fused_gate_storage, 0x57U,
        nonfinite_label + " poison candidate final");
    nonfinite_ready = nonfinite_ready && poison(
        fused_up_storage, 0x68U,
        nonfinite_label + " poison candidate up");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        launch_residual_norm_test_baseline<kColumns>(
            residual_left.get(), residual_right.get(), norm_weight.get(),
            kNormEpsilon, baseline_residual, normalized_activation.get(),
            stream),
        nonfinite_label + " launch bounded baseline");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        static_cast<cudaError_t>(fused_launcher(
            gate_packed.get(), gate_scales.get(), kGateWeightScale2,
            up_packed.get(), up_scales.get(), kUpWeightScale2,
            normalized_activation.get(), kRows, kColumns, baseline_final,
            baseline_up, static_cast<void*>(stream))),
        nonfinite_label + " launch normalized gate/up baseline");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_test_cuda(
                gate_packed.get(), gate_scales.get(), kGateWeightScale2,
                up_packed.get(), up_scales.get(), kUpWeightScale2,
                residual_left.get(), residual_right.get(), norm_weight.get(),
                kNormEpsilon, kRows, kColumns, candidate_residual, fused_gate,
                fused_up, static_cast<void*>(stream))),
        nonfinite_label + " launch fused candidate");

    std::vector<std::uint16_t> observed_baseline_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_baseline_final(
        kRows + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_baseline_up(
        kRows + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_final(
        kRows + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_up(
        kRows + 2U * kGuardElements);
    const auto copy_output =
        [&](std::vector<std::uint16_t>& destination,
            const DeviceBuffer<std::uint16_t>& source,
            const std::string& operation) {
          return test.cuda_ok(
              cudaMemcpyAsync(destination.data(), source.get(),
                              destination.size() * sizeof(std::uint16_t),
                              cudaMemcpyDeviceToHost, stream),
              operation);
        };
    nonfinite_ready = nonfinite_ready && copy_output(
        observed_baseline_residual, baseline_residual_storage,
        nonfinite_label + " copy baseline residual");
    nonfinite_ready = nonfinite_ready && copy_output(
        observed_candidate_residual, candidate_residual_storage,
        nonfinite_label + " copy candidate residual");
    nonfinite_ready = nonfinite_ready && copy_output(
        observed_baseline_final, baseline_final_storage,
        nonfinite_label + " copy baseline final");
    nonfinite_ready = nonfinite_ready && copy_output(
        observed_baseline_up, baseline_up_storage,
        nonfinite_label + " copy baseline up");
    nonfinite_ready = nonfinite_ready && copy_output(
        observed_candidate_final, fused_gate_storage,
        nonfinite_label + " copy candidate final");
    nonfinite_ready = nonfinite_ready && copy_output(
        observed_candidate_up, fused_up_storage,
        nonfinite_label + " copy candidate up");
    std::vector<std::uint16_t> observed_left(kColumns);
    std::vector<std::uint16_t> observed_right(kColumns);
    std::vector<std::uint16_t> observed_norm(kColumns);
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_left.data(), residual_left.get(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        nonfinite_label + " copy residual left");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_right.data(), residual_right.get(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        nonfinite_label + " copy residual right");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_norm.data(), norm_weight.get(),
                        kColumns * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        nonfinite_label + " copy norm weight");
    nonfinite_ready = nonfinite_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), nonfinite_label + " synchronize");
    if (nonfinite_ready) {
      std::size_t residual_mismatches = 0U;
      std::size_t final_bitwise_mismatches = 0U;
      std::size_t up_bitwise_mismatches = 0U;
      std::size_t classified_nan_outputs = 0U;
      bool class_and_sign = true;
      for (std::size_t index = 0U; index < kColumns; ++index) {
        const std::size_t guarded = kGuardElements + index;
        residual_mismatches +=
            observed_baseline_residual[guarded] !=
            observed_candidate_residual[guarded];
      }
      for (std::size_t row = 0U; row < kRows; ++row) {
        const std::size_t guarded = kGuardElements + row;
        const std::uint16_t baseline_final_bits =
            observed_baseline_final[guarded];
        const std::uint16_t candidate_final_bits =
            observed_candidate_final[guarded];
        const std::uint16_t baseline_up_bits =
            observed_baseline_up[guarded];
        const std::uint16_t candidate_up_bits =
            observed_candidate_up[guarded];
        final_bitwise_mismatches +=
            baseline_final_bits != candidate_final_bits;
        up_bitwise_mismatches += baseline_up_bits != candidate_up_bits;
        const bool final_nan = is_bf16_nan(baseline_final_bits) &&
                               is_bf16_nan(candidate_final_bits);
        const bool up_nan = is_bf16_nan(baseline_up_bits) &&
                            is_bf16_nan(candidate_up_bits);
        classified_nan_outputs += final_nan ? 1U : 0U;
        classified_nan_outputs += up_nan ? 1U : 0U;
        class_and_sign =
            class_and_sign && final_nan && up_nan &&
            ((baseline_final_bits ^ candidate_final_bits) & 0x8000U) == 0U &&
            ((baseline_up_bits ^ candidate_up_bits) & 0x8000U) == 0U;
      }
      bool guards = true;
      for (std::size_t index = 0U; index < kGuardElements; ++index) {
        guards = guards && observed_baseline_residual[index] == 0x1313U &&
                 observed_candidate_residual[index] == 0x2424U &&
                 observed_baseline_residual[kGuardElements + kColumns +
                                            index] == 0x1313U &&
                 observed_candidate_residual[kGuardElements + kColumns +
                                             index] == 0x2424U &&
                 observed_baseline_final[index] == 0x3535U &&
                 observed_baseline_up[index] == 0x4646U &&
                 observed_candidate_final[index] == 0x5757U &&
                 observed_candidate_up[index] == 0x6868U &&
                 observed_baseline_final[kGuardElements + kRows + index] ==
                     0x3535U &&
                 observed_baseline_up[kGuardElements + kRows + index] ==
                     0x4646U &&
                 observed_candidate_final[kGuardElements + kRows + index] ==
                     0x5757U &&
                 observed_candidate_up[kGuardElements + kRows + index] ==
                     0x6868U;
      }
      const bool inputs_preserved =
          observed_left == host_residual_left &&
          observed_right == host_residual_right &&
          observed_norm == host_norm_weight;
      residual_norm_nonfinite_gate =
          residual_mismatches == 0U && final_bitwise_mismatches == 0U &&
          up_bitwise_mismatches == 0U && class_and_sign &&
          classified_nan_outputs == 2U * kRows && guards &&
          inputs_preserved;
      test.expect(residual_norm_nonfinite_gate,
                  nonfinite_label + " preserves class, sign, and inputs");
      std::cout
          << "NVFP4_M1_RESIDUAL_NORM_GATE_UP_SILU_DEFAULT_NONFINITE: "
          << "residual_mismatches=" << residual_mismatches << '/'
          << kColumns << " final_bitwise_mismatches="
          << final_bitwise_mismatches << '/' << kRows
          << " up_bitwise_mismatches=" << up_bitwise_mismatches << '/'
          << kRows << " classified_nan_outputs="
          << classified_nan_outputs << '/' << 2U * kRows
          << " class_and_sign=" << (class_and_sign ? "true" : "false")
          << " guards=" << (guards ? "intact" : "BAD")
          << " inputs_preserved="
          << (inputs_preserved ? "true" : "false") << " gate="
          << (residual_norm_nonfinite_gate ? "PASS" : "FAIL") << '\n';
    }
  }

  std::fill(host_gate_packed.begin(), host_gate_packed.end(), 0x11U);
  std::fill(host_up_packed.begin(), host_up_packed.end(), 0x11U);
  std::fill(host_gate_scales.begin(), host_gate_scales.end(), 0x38U);
  std::fill(host_up_scales.begin(), host_up_scales.end(), 0x38U);
  std::fill(host_activation.begin(), host_activation.end(),
            encode_bf16(0.0F));
  host_activation[0U] = encode_bf16(1.0F);
  host_gate_scales[0U * kScaleColumns] = 0x7fU;
  host_gate_scales[1U * kScaleColumns] = 0xffU;
  host_up_scales[2U * kScaleColumns] = 0x7fU;
  host_up_scales[3U * kScaleColumns] = 0xffU;
  const bool nan_gate =
      run_case(label + " isolated signed NaN", false, true);
  const bool default_gate =
      pair_resource_gate && fused_resource_gate &&
      residual_norm_fused_resource_gate &&
      residual_norm_shared_tree_resource_gate &&
      residual_norm_production_resource_gate && residual_norm_gate &&
      residual_norm_reduction_ab_gate && residual_norm_nonfinite_gate &&
      finite_gate && invalid_contract_gate && public_contract_gate &&
      residual_norm_public_contract_gate && nan_gate;
  test.expect(default_gate,
              label + " clears resource/contract/correctness default gate");
  std::cout << "NVFP4_M1_GATE_UP_PAIR_DEFAULT_SELECTED: pair_resource_gate="
            << (pair_resource_gate ? "PASS" : "FAIL")
            << " fused_resource_gate="
            << (fused_resource_gate ? "PASS" : "FAIL")
            << " residual_norm_fused_resource_gate="
            << (residual_norm_fused_resource_gate ? "PASS" : "FAIL")
            << " residual_norm_shared_tree_resource_gate="
            << (residual_norm_shared_tree_resource_gate ? "PASS" : "FAIL")
            << " residual_norm_production_resource_gate="
            << (residual_norm_production_resource_gate ? "PASS" : "FAIL")
            << " residual_norm_bitwise_gate="
            << (residual_norm_gate ? "PASS" : "FAIL")
            << " residual_norm_reduction_ab_gate="
            << (residual_norm_reduction_ab_gate ? "PASS" : "FAIL")
            << " residual_norm_nonfinite_gate="
            << (residual_norm_nonfinite_gate ? "PASS" : "FAIL")
            << " finite_gate=" << (finite_gate ? "PASS" : "FAIL")
            << " invalid_contract_gate="
            << (invalid_contract_gate ? "PASS" : "FAIL")
            << " public_contract_gate="
            << (public_contract_gate ? "PASS" : "FAIL")
            << " residual_norm_public_contract_gate="
            << (residual_norm_public_contract_gate ? "PASS" : "FAIL")
            << " nan_gate=" << (nan_gate ? "PASS" : "FAIL")
            << " gate=" << (default_gate ? "PASS" : "FAIL") << '\n';
}

struct NvFp4GateUpSiluFusionTiming {
  float baseline_milliseconds = std::numeric_limits<float>::quiet_NaN();
  float candidate_milliseconds = std::numeric_limits<float>::quiet_NaN();
};

struct NvFp4GateUpCtaCoarsenTiming {
  float predecessor_pass_median_milliseconds =
      std::numeric_limits<float>::quiet_NaN();
  float production_pass_median_milliseconds =
      std::numeric_limits<float>::quiet_NaN();
  float paired_round_median_speedup =
      std::numeric_limits<float>::quiet_NaN();
  std::array<float, 5U> paired_round_speedups{};
};

struct NvFp4GateUpDeadUpTiming {
  float production_pass_median_milliseconds =
      std::numeric_limits<float>::quiet_NaN();
  float candidate_pass_median_milliseconds =
      std::numeric_limits<float>::quiet_NaN();
  float paired_round_median_speedup =
      std::numeric_limits<float>::quiet_NaN();
  std::array<float, 5U> paired_round_speedups{};
  std::array<float, 5U> paired_round_deltas_milliseconds{};
};

void run_optional_nvfp4_m1_gate_up_silu_fusion_performance(
    TestContext& test, cudaStream_t stream) {
  if (!nvfp4_m1_gate_up_silu_fusion_performance_enabled() &&
      !decode_residual_chain_performance_enabled() &&
      !decode_gate_up_cg_performance_enabled() &&
      !decode_gate_up_cs_performance_enabled() &&
      !decode_gate_up_scale_aosoa4_performance_enabled() &&
      !decode_gate_up_silu_table_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M1 gate/up+SiLU fusion gate; set "
           "Q3X_RUN_SM87_NVFP4_M1_GATE_UP_SILU_FUSION_PERF=1 together "
           "with Q3X_NVFP4_GATE_UP_ACTUAL_CHECKPOINT_FILE to enable\n";
    return;
  }

  constexpr std::size_t kRows = 17'408U;
  constexpr std::size_t kColumns = 5'120U;
  constexpr std::size_t kPackedCount = kRows * kColumns / 2U;
  constexpr std::size_t kScaleCount = kRows * kColumns / 16U;
  constexpr std::size_t kScaleColumns = kColumns / 16U;
  constexpr std::size_t kGuardElements = 16U;
  constexpr std::uint64_t kExpectedCheckpointBytes = 9'965'652'512ULL;
  constexpr std::uint64_t kExpectedHeaderBytes = 126'504ULL;
  constexpr std::uint64_t kExpectedDataBase = 126'512ULL;
  constexpr std::uint64_t kGateWeightOffset = 6'757'009'952ULL;
  constexpr std::uint64_t kUpWeightOffset = 6'801'574'432ULL;
  constexpr std::uint64_t kGateScaleOffset = 3'606'039'072ULL;
  constexpr std::uint64_t kUpScaleOffset = 3'611'609'632ULL;
  constexpr std::uint64_t kGateScale2Offset = 126'548ULL;
  constexpr std::uint64_t kUpScale2Offset = 126'556ULL;
  constexpr std::uint32_t kExpectedScale2Bits = 0x391e79e8U;
  constexpr std::string_view kGateWeightSha256 =
      "e9e2d70cef19e52d65a0f7917ea6d936c172809ed247b350443b4344297159d8";
  constexpr std::string_view kUpWeightSha256 =
      "e604b0b18206afe695a191ecf77a6aaf4dfbc0f7e93f1f9789d9b579aed6215f";
  constexpr std::string_view kGateScaleSha256 =
      "6eeaaa3bf8605b1d85252e13e6c495f6cf1b06e7fee8f27ea6367abbbb8fde0e";
  constexpr std::string_view kUpScaleSha256 =
      "ba393d3f9d25a1f4decba80715c6079d27d9de1d059a038a2f3f3f0932870947";
  constexpr int kWarmupIterations = 10;
  constexpr int kMeasuredIterations = 64;
  constexpr int kMeasurementRounds = 5;
  constexpr float kNormEpsilon = 1.0e-6F;
  constexpr double kRequiredActualSpeedup = 1.02;
  constexpr double kRequiredStressSpeedup = 1.00;
  constexpr double kExploratorySymmetricSpeedup = 1.01;
  constexpr double kRequiredResidualNormActualSpeedup = 1.005;
  constexpr double kRequiredResidualNormReductionDirectSpeedup = 1.005;
  constexpr double kRequiredCtaCoarsenActualSpeedup = 1.005;
  constexpr double kRequiredCtaCoarsenStressSpeedup = 1.000;
  constexpr double kRequiredCtaCoarsenRoundSpeedup = 1.000;
  constexpr double kRequiredDeadUpActualSpeedup = 1.005;
  constexpr double kRequiredDeadUpStressSpeedup = 1.000;
  constexpr double kRequiredDeadUpRoundSpeedup = 1.000;
  static_assert(kGateWeightOffset + kPackedCount == kUpWeightOffset);
  static_assert(kGateScaleOffset + kScaleCount == kUpScaleOffset);
  const std::string label =
      "NVFP4 M1 production gate/up+SiLU fusion 17408x5120";

  const q3x::core::Sha256FileResult binary_identity =
      q3x::core::sha256_file("/proc/self/exe");
  const bool binary_identity_gate = binary_identity.ok();
  test.expect(binary_identity_gate, label + " hashes the running test binary");
  std::cout << "NVFP4_M1_GATE_UP_SILU_BINARY_IDENTITY: sha256="
            << (binary_identity_gate ? binary_identity.digest->hex()
                                     : "unavailable")
            << " gate=" << (binary_identity_gate ? "PASS" : "FAIL")
            << '\n';
  if (!binary_identity_gate) {
    return;
  }

  const char* const checkpoint_value =
      std::getenv("Q3X_NVFP4_GATE_UP_ACTUAL_CHECKPOINT_FILE");
  const bool source_set =
      checkpoint_value != nullptr && checkpoint_value[0] != '\0';
  test.expect(source_set, label + " requires the actual checkpoint file");
  if (!source_set) {
    std::cout << "NVFP4_M1_GATE_UP_SILU_CHECKPOINT_SOURCE: source=missing "
                 "required_env=Q3X_NVFP4_GATE_UP_ACTUAL_CHECKPOINT_FILE "
                 "gate=FAIL\n";
    return;
  }
  const std::string checkpoint_path = checkpoint_value;
  std::ifstream checkpoint(checkpoint_path, std::ios::binary);
  const bool opened = checkpoint.is_open();
  test.expect(opened, label + " opens the actual checkpoint");
  if (!opened) {
    return;
  }
  checkpoint.seekg(0, std::ios::end);
  const std::streamoff checkpoint_size = checkpoint.tellg();
  const bool checkpoint_size_gate =
      checkpoint_size >= 0 &&
      static_cast<std::uint64_t>(checkpoint_size) ==
          kExpectedCheckpointBytes;
  test.expect(checkpoint_size_gate, label + " pins the checkpoint size");
  if (!checkpoint_size_gate) {
    return;
  }
  const auto read_slice =
      [&](const std::uint64_t offset, std::uint8_t* const destination,
          const std::size_t bytes, const std::string& tensor) {
        const std::uint64_t file_bytes =
            static_cast<std::uint64_t>(checkpoint_size);
        const bool range_valid =
            offset <= file_bytes && bytes <= file_bytes - offset &&
            offset <= static_cast<std::uint64_t>(
                          std::numeric_limits<std::streamoff>::max()) &&
            bytes <= static_cast<std::size_t>(
                         std::numeric_limits<std::streamsize>::max());
        test.expect(range_valid, label + " contains " + tensor);
        if (!range_valid) {
          return false;
        }
        checkpoint.clear();
        checkpoint.seekg(static_cast<std::streamoff>(offset),
                         std::ios::beg);
        checkpoint.read(reinterpret_cast<char*>(destination),
                        static_cast<std::streamsize>(bytes));
        const bool complete =
            checkpoint.gcount() == static_cast<std::streamsize>(bytes);
        test.expect(complete, label + " reads complete " + tensor);
        return complete;
      };

  std::array<std::uint8_t, 8U> header_length_bytes{};
  bool fixture_ready = read_slice(0U, header_length_bytes.data(),
                                  header_length_bytes.size(),
                                  "safetensors header length");
  std::uint64_t header_bytes = 0U;
  for (std::size_t index = 0U; index < header_length_bytes.size(); ++index) {
    header_bytes |= static_cast<std::uint64_t>(header_length_bytes[index])
                    << (8U * index);
  }
  const bool header_gate =
      fixture_ready && header_bytes == kExpectedHeaderBytes &&
      header_bytes + 8U == kExpectedDataBase;
  test.expect(header_gate,
              label + " pins the safetensors header/data base");

  std::vector<std::uint8_t> host_gate_packed(kPackedCount);
  std::vector<std::uint8_t> host_up_packed(kPackedCount);
  std::vector<std::uint8_t> host_gate_scales(kScaleCount);
  std::vector<std::uint8_t> host_up_scales(kScaleCount);
  std::array<std::uint8_t, 4U> gate_scale2_bytes{};
  std::array<std::uint8_t, 4U> up_scale2_bytes{};
  fixture_ready = fixture_ready && read_slice(
      kGateWeightOffset, host_gate_packed.data(), host_gate_packed.size(),
      "layer-0 gate_proj.weight");
  fixture_ready = fixture_ready && read_slice(
      kUpWeightOffset, host_up_packed.data(), host_up_packed.size(),
      "layer-0 up_proj.weight");
  fixture_ready = fixture_ready && read_slice(
      kGateScaleOffset, host_gate_scales.data(), host_gate_scales.size(),
      "layer-0 gate_proj.weight_scale");
  fixture_ready = fixture_ready && read_slice(
      kUpScaleOffset, host_up_scales.data(), host_up_scales.size(),
      "layer-0 up_proj.weight_scale");
  fixture_ready = fixture_ready && read_slice(
      kGateScale2Offset, gate_scale2_bytes.data(), gate_scale2_bytes.size(),
      "layer-0 gate_proj.weight_scale_2");
  fixture_ready = fixture_ready && read_slice(
      kUpScale2Offset, up_scale2_bytes.data(), up_scale2_bytes.size(),
      "layer-0 up_proj.weight_scale_2");
  if (!fixture_ready) {
    return;
  }
  const auto little_endian_u32 = [](const std::array<std::uint8_t, 4U>& v) {
    return static_cast<std::uint32_t>(v[0U]) |
           (static_cast<std::uint32_t>(v[1U]) << 8U) |
           (static_cast<std::uint32_t>(v[2U]) << 16U) |
           (static_cast<std::uint32_t>(v[3U]) << 24U);
  };
  const std::uint32_t gate_scale2_bits =
      little_endian_u32(gate_scale2_bytes);
  const std::uint32_t up_scale2_bits = little_endian_u32(up_scale2_bytes);
  float gate_scale2 = 0.0F;
  float up_scale2 = 0.0F;
  std::memcpy(&gate_scale2, &gate_scale2_bits, sizeof(gate_scale2));
  std::memcpy(&up_scale2, &up_scale2_bits, sizeof(up_scale2));
  const auto hash_bytes = [](const std::vector<std::uint8_t>& values) {
    return q3x::core::sha256(std::string_view(
                                reinterpret_cast<const char*>(values.data()),
                                values.size()))
        .hex();
  };
  const std::string gate_weight_hash = hash_bytes(host_gate_packed);
  const std::string up_weight_hash = hash_bytes(host_up_packed);
  const std::string gate_scale_hash = hash_bytes(host_gate_scales);
  const std::string up_scale_hash = hash_bytes(host_up_scales);
  const bool pinned_payload_gate =
      gate_weight_hash == kGateWeightSha256 &&
      up_weight_hash == kUpWeightSha256 &&
      gate_scale_hash == kGateScaleSha256 &&
      up_scale_hash == kUpScaleSha256 &&
      gate_scale2_bits == kExpectedScale2Bits &&
      up_scale2_bits == kExpectedScale2Bits && std::isfinite(gate_scale2) &&
      std::isfinite(up_scale2);
  test.expect(pinned_payload_gate,
              label + " matches all pinned payload hashes and scale2 bits");
  std::cout << "NVFP4_M1_GATE_UP_SILU_CHECKPOINT_SOURCE: source=actual"
            << " path=" << checkpoint_path
            << " data_base=" << kExpectedDataBase
            << " gate_weight_offset=" << kGateWeightOffset
            << " up_weight_offset=" << kUpWeightOffset
            << " gate_scale_offset=" << kGateScaleOffset
            << " up_scale_offset=" << kUpScaleOffset
            << " gate_scale2_offset=" << kGateScale2Offset
            << " up_scale2_offset=" << kUpScale2Offset
            << " gate_weight_sha256=" << gate_weight_hash
            << " up_weight_sha256=" << up_weight_hash
            << " gate_scale_sha256=" << gate_scale_hash
            << " up_scale_sha256=" << up_scale_hash
