                  row * kScaleColumns + scale_column;
              const std::size_t sidecar_index =
                  ((row / 4U) * kScaleColumns + scale_column) * 4U +
                  row % 4U;
              if (canonical[canonical_index] != sidecar[sidecar_index]) {
                return false;
              }
