        finite = finite && std::isfinite(
                               decode_bf16(observed_candidate_gate[guarded]));
      }
      const auto guards_intact =
          [&](const std::vector<std::uint16_t>& values,
              const std::uint16_t canary) {
            return std::all_of(
                       values.begin(), values.begin() + kGuardElements,
                       [canary](const std::uint16_t value) {
                         return value == canary;
                       }) &&
                   std::all_of(
                       values.end() - kGuardElements, values.end(),
                       [canary](const std::uint16_t value) {
                         return value == canary;
                       });
          };
      const bool guards_gate =
          guards_intact(observed_baseline_residual, 0x3131U) &&
          guards_intact(observed_candidate_residual, 0x4242U) &&
          guards_intact(observed_baseline_gate, 0x5353U) &&
          guards_intact(observed_candidate_gate, 0x6464U);
      const bool workspace_gate =
          std::all_of(observed_baseline_up.begin(),
                      observed_baseline_up.end(),
                      [](const std::uint16_t value) {
                        return value == 0x7575U;
                      }) &&
          std::all_of(observed_candidate_up.begin(),
                      observed_candidate_up.end(),
                      [](const std::uint16_t value) {
                        return value == 0x8686U;
                      });
      correctness_gates[fixture] =
          residual_mismatches == 0U && gate_mismatches == 0U && finite &&
          guards_gate && workspace_gate;
      test.expect(correctness_gates[fixture],
                  fixture_label +
                      " is bitwise, finite, guarded, and leaves up untouched");
      std::cout << "DECODE_GATE_UP_SCALE_AOSOA4_DIFF: fixture="
                << fixture_name << " residual_mismatches="
                << residual_mismatches << '/' << kColumns
                << " gate_mismatches=" << gate_mismatches << '/' << kRows
                << " finite=" << (finite ? "true" : "false")
                << " guards=" << (guards_gate ? "PASS" : "FAIL")
                << " workspaces_untouched="
                << (workspace_gate ? "PASS" : "FAIL")
                << " gate="
                << (correctness_gates[fixture] ? "PASS" : "FAIL") << '\n';
      if (!correctness_gates[fixture]) {
        return;
      }

      for (int iteration = 0;
           iteration < kSidecarWarmupIterations && sidecar_ready;
           ++iteration) {
        sidecar_ready = test.cuda_ok(
            static_cast<cudaError_t>(launch_sidecar_baseline()),
            fixture_label + " baseline warmup");
        sidecar_ready = sidecar_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_sidecar_candidate()),
            fixture_label + " candidate warmup");
      }
      sidecar_ready = sidecar_ready && test.cuda_ok(
          cudaStreamSynchronize(stream), fixture_label + " warmup sync");
      constexpr std::size_t kTimedPasses =
          2U * static_cast<std::size_t>(kSidecarMeasurementRounds);
      std::array<float, kTimedPasses> baseline_passes{};
      std::array<float, kTimedPasses> candidate_passes{};
      std::array<float, kSidecarMeasurementRounds> paired_speedups{};
      std::array<float, kSidecarMeasurementRounds> paired_deltas{};
      bool all_rounds = sidecar_ready;
      for (int round = 0;
           round < kSidecarMeasurementRounds && sidecar_ready; ++round) {
        const std::string round_label =
            fixture_label + " round=" + std::to_string(round + 1);
        const bool baseline_outer = round % 2 == 0;
        float b1 = 0.0F;
        float b2 = 0.0F;
        float c1 = 0.0F;
        float c2 = 0.0F;
        if (baseline_outer) {
          b1 = measure_small_m_tile(
              test, stream, launch_sidecar_baseline,
              kSidecarMeasuredIterations, round_label + " B1");
          c1 = measure_small_m_tile(
              test, stream, launch_sidecar_candidate,
              kSidecarMeasuredIterations, round_label + " C1");
          c2 = measure_small_m_tile(
              test, stream, launch_sidecar_candidate,
              kSidecarMeasuredIterations, round_label + " C2");
          b2 = measure_small_m_tile(
              test, stream, launch_sidecar_baseline,
              kSidecarMeasuredIterations, round_label + " B2");
        } else {
          c1 = measure_small_m_tile(
              test, stream, launch_sidecar_candidate,
              kSidecarMeasuredIterations, round_label + " C1");
          b1 = measure_small_m_tile(
              test, stream, launch_sidecar_baseline,
              kSidecarMeasuredIterations, round_label + " B1");
          b2 = measure_small_m_tile(
              test, stream, launch_sidecar_baseline,
              kSidecarMeasuredIterations, round_label + " B2");
          c2 = measure_small_m_tile(
              test, stream, launch_sidecar_candidate,
              kSidecarMeasuredIterations, round_label + " C2");
        }
        const std::size_t pass = 2U * static_cast<std::size_t>(round);
        baseline_passes[pass] = b1;
        baseline_passes[pass + 1U] = b2;
        candidate_passes[pass] = c1;
        candidate_passes[pass + 1U] = c2;
        const bool round_finite =
            std::isfinite(b1) && b1 > 0.0F && std::isfinite(c1) &&
            c1 > 0.0F && std::isfinite(c2) && c2 > 0.0F &&
            std::isfinite(b2) && b2 > 0.0F;
        const float paired_baseline = 0.5F * (b1 + b2);
        const float paired_candidate = 0.5F * (c1 + c2);
        paired_speedups[static_cast<std::size_t>(round)] =
            paired_baseline / paired_candidate;
        paired_deltas[static_cast<std::size_t>(round)] =
            paired_baseline - paired_candidate;
        const bool round_gate =
            round_finite &&
            static_cast<double>(
                paired_speedups[static_cast<std::size_t>(round)]) >
                kRequiredEachRoundSpeedup;
        all_rounds = all_rounds && round_gate;
        sidecar_ready = sidecar_ready && round_finite;
        std::cout << "PERF_DECODE_GATE_UP_SCALE_AOSOA4_ROUND: fixture="
                  << fixture_name << " round=" << round + 1 << " order="
                  << (baseline_outer ? "B-C-C-B" : "C-B-B-C")
                  << " logical_kernels_per_pass="
                  << kSidecarMeasuredIterations << " baseline1_ms=" << b1
                  << " candidate1_ms=" << c1
                  << " candidate2_ms=" << c2 << " baseline2_ms=" << b2
                  << " paired_speedup="
                  << paired_speedups[static_cast<std::size_t>(round)]
                  << " paired_delta_ms="
                  << paired_deltas[static_cast<std::size_t>(round)]
                  << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
      }
      baseline_medians[fixture] =
          sidecar_ready
              ? median_fp8_kv_pair_timing(baseline_passes)
              : std::numeric_limits<float>::quiet_NaN();
      candidate_medians[fixture] =
          sidecar_ready
              ? median_fp8_kv_pair_timing(candidate_passes)
              : std::numeric_limits<float>::quiet_NaN();
      paired_speedup_medians[fixture] =
          sidecar_ready
              ? median_fp8_kv_pair_timing(paired_speedups)
              : std::numeric_limits<float>::quiet_NaN();
      paired_delta_medians[fixture] =
          sidecar_ready
              ? median_fp8_kv_pair_timing(paired_deltas)
              : std::numeric_limits<float>::quiet_NaN();
      every_round_nonregression[fixture] = all_rounds;
    }

    std::array<bool, 2U> timing_gates{};
    for (std::size_t fixture = 0U; fixture < 2U; ++fixture) {
      const double required =
          fixture == 0U ? kRequiredActualSpeedup : kRequiredStressSpeedup;
      timing_gates[fixture] =
          correctness_gates[fixture] && every_round_nonregression[fixture] &&
          std::isfinite(paired_speedup_medians[fixture]) &&
          static_cast<double>(paired_speedup_medians[fixture]) >= required;
      std::cout << "PERF_DECODE_GATE_UP_SCALE_AOSOA4: fixture="
                << (fixture == 0U ? "actual_checkpoint"
                                  : "same_bank_stress")
                << " baseline_pass_median_ms=" << baseline_medians[fixture]
                << " candidate_pass_median_ms="
                << candidate_medians[fixture]
                << " paired_round_median_speedup="
                << paired_speedup_medians[fixture]
                << " paired_round_median_delta_ms="
                << paired_delta_medians[fixture]
                << " required_speedup=" << required
                << " every_round_nonregression="
                << (every_round_nonregression[fixture] ? "true" : "false")
                << " gate=" << (timing_gates[fixture] ? "PASS" : "FAIL")
                << '\n';
    }
    const double projected_delta_ms =
        64.0 * static_cast<double>(paired_delta_medians[0U]);
    const bool projected_delta_gate =
        std::isfinite(projected_delta_ms) &&
        projected_delta_ms >= kRequiredProjectedDeltaMilliseconds;
    const bool selected_gate =
        header_gate && pinned_payload_gate && binary_identity_gate &&
        sidecar_resource_gate && correctness_gates[0U] &&
        correctness_gates[1U] && timing_gates[0U] && timing_gates[1U] &&
        projected_delta_gate;
    test.expect(selected_gate,
                sidecar_label + " clears the isolated promotion screen");
    std::cout << "PERF_DECODE_GATE_UP_SCALE_AOSOA4_SELECTED:"
              << " layout=row_quad_scale_column_row4"
              << " canonical_bytes_per_projection=" << kScaleCount
              << " sidecar_bytes_per_projection=" << kScaleCount
              << " actual_paired_median_speedup="
              << paired_speedup_medians[0U]
              << " stress_paired_median_speedup="
              << paired_speedup_medians[1U]
              << " projected_64_layer_delta_ms=" << projected_delta_ms
              << " required_projected_64_layer_delta_ms="
              << kRequiredProjectedDeltaMilliseconds
              << " production_dispatch_unchanged=true"
              << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
    return;
  }

  if (decode_gate_up_cg_performance_enabled() ||
      decode_gate_up_cs_performance_enabled()) {
    constexpr int kCacheWarmupIterations = 10;
    constexpr int kCacheMeasuredIterations = 64;
    constexpr int kCacheMeasurementRounds = 5;
    constexpr float kRequiredDeltaMilliseconds = 0.25F / 64.0F;
    constexpr double kRequiredSpeedup = 1.005;
    const bool cache_global_policy =
        decode_gate_up_cg_performance_enabled();
    const bool streaming_policy = decode_gate_up_cs_performance_enabled();
    const bool single_policy = cache_global_policy != streaming_policy;
    test.expect(single_policy,
                "Decode gate/up cache screen selects exactly one policy");
    if (!single_policy) {
      return;
    }
    const char* const policy_name =
        streaming_policy ? "packed_and_scale_cs" : "packed_and_scale_cg";
    const std::string cache_label =
        streaming_policy
            ? "Decode gate/up packed-weight/block-scale streaming screen"
            : "Decode gate/up packed-weight/block-scale cache-global screen";

    NvFp4M1DownDualKernelResources cache_candidate_resources{};
    const int cache_resource_status =
        streaming_policy
            ? q3x::kernels::
                  query_sm87_nvfp4_w4a16_m1_residual_norm_gate_up_silu_dead_up_shared_pair_resources_test_cuda(
                      &cache_candidate_resources.registers_per_thread,
                      &cache_candidate_resources.static_shared_bytes,
                      &cache_candidate_resources.local_bytes,
                      &cache_candidate_resources.maximum_threads_per_block,
                      &cache_candidate_resources.active_blocks_per_sm)
            : q3x::kernels::
                  query_sm87_nvfp4_w4a16_m1_residual_norm_gate_up_silu_dead_up_cg_resources_test_cuda(
                      &cache_candidate_resources.registers_per_thread,
                      &cache_candidate_resources.static_shared_bytes,
                      &cache_candidate_resources.local_bytes,
                      &cache_candidate_resources.maximum_threads_per_block,
                      &cache_candidate_resources.active_blocks_per_sm);
    bool cache_ready = test.cuda_ok(
        static_cast<cudaError_t>(cache_resource_status),
        cache_label + " query candidate resources");
    const bool cache_resource_gate =
        cache_ready && dead_up_resource_gate &&
        cache_candidate_resources.registers_per_thread ==
            residual_norm_dead_up_default_resources.registers_per_thread &&
        cache_candidate_resources.registers_per_thread <= 64 &&
        cache_candidate_resources.static_shared_bytes == 13'632U &&
        cache_candidate_resources.local_bytes == 0U &&
        cache_candidate_resources.maximum_threads_per_block >= 512 &&
        cache_candidate_resources.active_blocks_per_sm >= 2;
    test.expect(cache_resource_gate,
                cache_label + " preserves the production resource envelope");
    std::cout << "PERF_DECODE_GATE_UP_CACHE_POLICY_RESOURCES:"
              << " baseline_registers="
              << residual_norm_dead_up_default_resources.registers_per_thread
              << " baseline_shared="
              << residual_norm_dead_up_default_resources.static_shared_bytes
              << " baseline_local="
              << residual_norm_dead_up_default_resources.local_bytes
              << " baseline_active="
              << residual_norm_dead_up_default_resources.active_blocks_per_sm
              << " candidate_registers="
              << cache_candidate_resources.registers_per_thread
              << " candidate_shared="
              << cache_candidate_resources.static_shared_bytes
              << " candidate_local="
              << cache_candidate_resources.local_bytes
              << " candidate_active="
              << cache_candidate_resources.active_blocks_per_sm
              << " policy=" << policy_name
              << " gate=" << (cache_resource_gate ? "PASS" : "FAIL")
              << '\n';
    if (!cache_resource_gate) {
      return;
    }

    DeviceBuffer<std::uint16_t> replay_residual_storage;
    DeviceBuffer<std::uint16_t> replay_gate_storage;
    DeviceBuffer<std::uint16_t> replay_up_storage;
    cache_ready = cache_ready && test.cuda_ok(
        replay_residual_storage.allocate(kColumns + 2U * kGuardElements),
        cache_label + " allocate replay residual");
    cache_ready = cache_ready && test.cuda_ok(
        replay_gate_storage.allocate(guarded_count),
        cache_label + " allocate replay gate");
    cache_ready = cache_ready && test.cuda_ok(
        replay_up_storage.allocate(guarded_count),
        cache_label + " allocate replay up workspace");
    cache_ready = cache_ready && upload_fixture(cache_label);
    if (!cache_ready) {
      return;
    }
    std::uint16_t* const replay_residual =
        replay_residual_storage.get() + kGuardElements;
    std::uint16_t* const replay_gate =
        replay_gate_storage.get() + kGuardElements;
    std::uint16_t* const replay_up =
        replay_up_storage.get() + kGuardElements;
    const auto launch_cache_baseline_to =
        [&](std::uint16_t* const residual, std::uint16_t* const gate,
            std::uint16_t* const up) noexcept {
          return q3x::kernels::
              launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_dead_up_default_test_cuda(
                  gate_packed.get(), gate_scales.get(), gate_scale2,
                  up_packed.get(), up_scales.get(), up_scale2,
                  residual_left.get(), residual_right.get(),
                  norm_weight.get(), kNormEpsilon, kRows, kColumns,
                  residual, gate, up, static_cast<void*>(stream));
        };
    const auto launch_cache_candidate_to =
        [&](std::uint16_t* const residual, std::uint16_t* const gate,
            std::uint16_t* const up) noexcept {
          if (streaming_policy) {
            return q3x::kernels::
                launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_dead_up_bf16_cuda(
                    gate_packed.get(), gate_scales.get(), gate_scale2,
                    up_packed.get(), up_scales.get(), up_scale2,
                    residual_left.get(), residual_right.get(),
                    norm_weight.get(), kNormEpsilon, kRows, kColumns,
                    residual, gate, up, static_cast<void*>(stream));
          }
          return q3x::kernels::
              launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_dead_up_cg_test_cuda(
                  gate_packed.get(), gate_scales.get(), gate_scale2,
                  up_packed.get(), up_scales.get(), up_scale2,
                  residual_left.get(), residual_right.get(),
                  norm_weight.get(), kNormEpsilon, kRows, kColumns,
                  residual, gate, up, static_cast<void*>(stream));
        };
    const auto launch_cache_baseline = [&]() noexcept {
      return launch_cache_baseline_to(baseline_residual, baseline_gate,
                                      baseline_up);
    };
    const auto launch_cache_candidate = [&]() noexcept {
      return launch_cache_candidate_to(candidate_residual, candidate_gate,
                                       candidate_up);
    };

    cache_ready = test.cuda_ok(
        cudaMemsetAsync(baseline_residual_storage.get(), 0x31,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        cache_label + " poison baseline residual");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_residual_storage.get(), 0x42,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        cache_label + " poison candidate residual");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(replay_residual_storage.get(), 0x53,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        cache_label + " poison replay residual");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(baseline_gate_storage.get(), 0x64,
                        guarded_count * sizeof(std::uint16_t), stream),
        cache_label + " poison baseline gate");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_gate_storage.get(), 0x75,
                        guarded_count * sizeof(std::uint16_t), stream),
        cache_label + " poison candidate gate");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(replay_gate_storage.get(), 0x86,
                        guarded_count * sizeof(std::uint16_t), stream),
        cache_label + " poison replay gate");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(baseline_up_storage.get(), 0x97,
                        guarded_count * sizeof(std::uint16_t), stream),
        cache_label + " poison baseline up workspace");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_up_storage.get(), 0xa8,
                        guarded_count * sizeof(std::uint16_t), stream),
        cache_label + " poison candidate up workspace");
    cache_ready = cache_ready && test.cuda_ok(
        cudaMemsetAsync(replay_up_storage.get(), 0xb9,
                        guarded_count * sizeof(std::uint16_t), stream),
        cache_label + " poison replay up workspace");
    cache_ready = cache_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_cache_baseline()),
        cache_label + " launch baseline correctness");
    cache_ready = cache_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_cache_candidate()),
        cache_label + " launch candidate correctness");
    cache_ready = cache_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_cache_candidate_to(
            replay_residual, replay_gate, replay_up)),
        cache_label + " launch candidate replay");

    std::vector<std::uint16_t> observed_baseline_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_replay_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_baseline_gate(guarded_count);
    std::vector<std::uint16_t> observed_candidate_gate(guarded_count);
    std::vector<std::uint16_t> observed_replay_gate(guarded_count);
    std::vector<std::uint16_t> observed_baseline_up(guarded_count);
    std::vector<std::uint16_t> observed_candidate_up(guarded_count);
    std::vector<std::uint16_t> observed_replay_up(guarded_count);
    const auto copy_cache_output =
        [&](std::vector<std::uint16_t>& destination,
            const DeviceBuffer<std::uint16_t>& source,
            const std::string& operation) {
          return test.cuda_ok(
              cudaMemcpyAsync(destination.data(), source.get(),
                              destination.size() * sizeof(std::uint16_t),
                              cudaMemcpyDeviceToHost, stream),
              operation);
        };
    cache_ready = cache_ready && copy_cache_output(
        observed_baseline_residual, baseline_residual_storage,
        cache_label + " copy baseline residual");
    cache_ready = cache_ready && copy_cache_output(
        observed_candidate_residual, candidate_residual_storage,
        cache_label + " copy candidate residual");
    cache_ready = cache_ready && copy_cache_output(
        observed_replay_residual, replay_residual_storage,
        cache_label + " copy replay residual");
    cache_ready = cache_ready && copy_cache_output(
        observed_baseline_gate, baseline_gate_storage,
        cache_label + " copy baseline gate");
    cache_ready = cache_ready && copy_cache_output(
        observed_candidate_gate, candidate_gate_storage,
        cache_label + " copy candidate gate");
    cache_ready = cache_ready && copy_cache_output(
        observed_replay_gate, replay_gate_storage,
        cache_label + " copy replay gate");
    cache_ready = cache_ready && copy_cache_output(
        observed_baseline_up, baseline_up_storage,
        cache_label + " copy baseline up workspace");
    cache_ready = cache_ready && copy_cache_output(
        observed_candidate_up, candidate_up_storage,
        cache_label + " copy candidate up workspace");
    cache_ready = cache_ready && copy_cache_output(
        observed_replay_up, replay_up_storage,
        cache_label + " copy replay up workspace");
    cache_ready = cache_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), cache_label + " correctness sync");
    if (!cache_ready) {
      return;
    }

    std::size_t residual_mismatches = 0U;
    std::size_t gate_mismatches = 0U;
    std::size_t replay_residual_mismatches = 0U;
    std::size_t replay_gate_mismatches = 0U;
    bool finite_outputs = true;
    for (std::size_t index = 0U; index < kColumns; ++index) {
      const std::size_t guarded = kGuardElements + index;
      residual_mismatches += observed_baseline_residual[guarded] !=
                             observed_candidate_residual[guarded];
      replay_residual_mismatches += observed_candidate_residual[guarded] !=
                                    observed_replay_residual[guarded];
      finite_outputs =
          finite_outputs &&
          std::isfinite(decode_bf16(observed_candidate_residual[guarded]));
    }
    for (std::size_t row = 0U; row < kRows; ++row) {
      const std::size_t guarded = kGuardElements + row;
      gate_mismatches += observed_baseline_gate[guarded] !=
                         observed_candidate_gate[guarded];
      replay_gate_mismatches += observed_candidate_gate[guarded] !=
                                observed_replay_gate[guarded];
      finite_outputs =
          finite_outputs &&
          std::isfinite(decode_bf16(observed_candidate_gate[guarded]));
    }
    const auto cache_guards_intact =
        [&](const std::vector<std::uint16_t>& values,
            const std::uint16_t canary) {
          return std::all_of(values.begin(),
                             values.begin() + kGuardElements,
                             [canary](const std::uint16_t value) {
                               return value == canary;
                             }) &&
                 std::all_of(values.end() - kGuardElements, values.end(),
                             [canary](const std::uint16_t value) {
                               return value == canary;
                             });
        };
    const bool cache_guards_gate =
        cache_guards_intact(observed_baseline_residual, 0x3131U) &&
        cache_guards_intact(observed_candidate_residual, 0x4242U) &&
        cache_guards_intact(observed_replay_residual, 0x5353U) &&
        cache_guards_intact(observed_baseline_gate, 0x6464U) &&
        cache_guards_intact(observed_candidate_gate, 0x7575U) &&
        cache_guards_intact(observed_replay_gate, 0x8686U);
    const bool cache_workspace_gate =
        std::all_of(observed_baseline_up.begin(), observed_baseline_up.end(),
                    [](const std::uint16_t value) {
                      return value == 0x9797U;
                    }) &&
        std::all_of(observed_candidate_up.begin(),
                    observed_candidate_up.end(),
                    [](const std::uint16_t value) {
                      return value == 0xa8a8U;
                    }) &&
        std::all_of(observed_replay_up.begin(), observed_replay_up.end(),
                    [](const std::uint16_t value) {
                      return value == 0xb9b9U;
                    });
    const bool cache_correctness_gate =
        residual_mismatches == 0U && gate_mismatches == 0U &&
        replay_residual_mismatches == 0U &&
        replay_gate_mismatches == 0U && finite_outputs &&
        cache_guards_gate && cache_workspace_gate;
    test.expect(cache_correctness_gate,
                cache_label + " is bitwise, finite, guarded, and replayable");
    std::cout << "DECODE_GATE_UP_CACHE_POLICY_DIFF:"
              << " policy=" << policy_name
              << " residual_mismatches=" << residual_mismatches << '/'
              << kColumns << " gate_mismatches=" << gate_mismatches << '/'
              << kRows << " replay_residual_mismatches="
              << replay_residual_mismatches << '/' << kColumns
              << " replay_gate_mismatches=" << replay_gate_mismatches << '/'
              << kRows
              << " finite_outputs="
              << (finite_outputs ? "true" : "false")
              << " guards=" << (cache_guards_gate ? "PASS" : "FAIL")
              << " workspaces_untouched="
              << (cache_workspace_gate ? "PASS" : "FAIL")
              << " gate=" << (cache_correctness_gate ? "PASS" : "FAIL")
              << '\n';
    if (!cache_correctness_gate) {
      return;
    }

    bool timing_ready = true;
    for (int iteration = 0;
         iteration < kCacheWarmupIterations && timing_ready; ++iteration) {
      timing_ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_cache_baseline()),
          cache_label + " baseline warmup");
      timing_ready = timing_ready && test.cuda_ok(
          static_cast<cudaError_t>(launch_cache_candidate()),
          cache_label + " candidate warmup");
    }
    timing_ready = timing_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), cache_label + " warmup sync");
    constexpr std::size_t kTimedPasses =
        2U * static_cast<std::size_t>(kCacheMeasurementRounds);
    std::array<float, kTimedPasses> baseline_passes{};
    std::array<float, kTimedPasses> candidate_passes{};
    std::array<float, kCacheMeasurementRounds> paired_deltas{};
    bool all_rounds_improve = timing_ready;
    for (int round = 0;
         round < kCacheMeasurementRounds && timing_ready; ++round) {
      const std::string round_label =
          cache_label + " round=" + std::to_string(round + 1);
      const float b1 = measure_small_m_tile(
          test, stream, launch_cache_baseline, kCacheMeasuredIterations,
          round_label + " B1");
      const float c1 = measure_small_m_tile(
          test, stream, launch_cache_candidate, kCacheMeasuredIterations,
          round_label + " C1");
      const float c2 = measure_small_m_tile(
          test, stream, launch_cache_candidate, kCacheMeasuredIterations,
          round_label + " C2");
      const float b2 = measure_small_m_tile(
          test, stream, launch_cache_baseline, kCacheMeasuredIterations,
          round_label + " B2");
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      baseline_passes[pass] = b1;
      baseline_passes[pass + 1U] = b2;
      candidate_passes[pass] = c1;
      candidate_passes[pass + 1U] = c2;
      const bool finite = std::isfinite(b1) && b1 > 0.0F &&
                          std::isfinite(c1) && c1 > 0.0F &&
                          std::isfinite(c2) && c2 > 0.0F &&
                          std::isfinite(b2) && b2 > 0.0F;
      const float paired_baseline = 0.5F * (b1 + b2);
      const float paired_candidate = 0.5F * (c1 + c2);
      paired_deltas[static_cast<std::size_t>(round)] =
          paired_baseline - paired_candidate;
      const bool round_improves =
          finite && c1 < b1 && c2 < b2 &&
          paired_candidate < paired_baseline;
      timing_ready = timing_ready && finite;
      all_rounds_improve = all_rounds_improve && round_improves;
      std::cout << "PERF_DECODE_GATE_UP_CACHE_POLICY_ROUND:"
                << " policy=" << policy_name
                << " fixture=actual_checkpoint"
                << " round=" << round + 1 << " order=B-C-C-B"
                << " logical_kernels_per_pass=" << kCacheMeasuredIterations
                << " baseline1_ms=" << b1 << " candidate1_ms=" << c1
                << " candidate2_ms=" << c2 << " baseline2_ms=" << b2
                << " paired_delta_ms="
                << paired_deltas[static_cast<std::size_t>(round)]
                << " gate=" << (round_improves ? "PASS" : "FAIL")
                << '\n';
    }
    const float baseline_median =
        timing_ready ? median_fp8_kv_pair_timing(baseline_passes)
                     : std::numeric_limits<float>::quiet_NaN();
    const float candidate_median =
        timing_ready ? median_fp8_kv_pair_timing(candidate_passes)
                     : std::numeric_limits<float>::quiet_NaN();
    const float delta_median =
        timing_ready ? median_fp8_kv_pair_timing(paired_deltas)
                     : std::numeric_limits<float>::quiet_NaN();
    const double speedup = static_cast<double>(baseline_median) /
                           static_cast<double>(candidate_median);
    const double projected_decode_delta =
        64.0 * static_cast<double>(delta_median);
    const bool timing_gate =
        timing_ready && all_rounds_improve &&
        delta_median >= kRequiredDeltaMilliseconds &&
        std::isfinite(speedup) && speedup >= kRequiredSpeedup;
    const bool selected_gate =
        header_gate && pinned_payload_gate && binary_identity_gate &&
        cache_resource_gate && cache_correctness_gate && timing_gate;
    test.expect(selected_gate,
                cache_label + " clears the actual-checkpoint stop-loss");
    std::cout << "PERF_DECODE_GATE_UP_CACHE_POLICY_SELECTED:"
              << " policy=" << policy_name
              << " fixture=actual_checkpoint"
              << " baseline_median_ms=" << baseline_median
              << " candidate_median_ms=" << candidate_median
              << " median_delta_ms_per_layer=" << delta_median
              << " projected_64_layer_delta_ms="
              << projected_decode_delta << " speedup=" << speedup
              << " all_rounds_improve="
              << (all_rounds_improve ? "true" : "false")
              << " required_delta_ms_per_layer="
              << kRequiredDeltaMilliseconds
              << " required_projected_64_layer_delta_ms=0.25"
              << " required_speedup=" << kRequiredSpeedup
              << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
    if (!selected_gate || !streaming_policy) {
      return;
    }
  }

  if (decode_residual_chain_performance_enabled()) {
    constexpr std::size_t kOutputRows = 5'120U;
    constexpr std::size_t kOutputColumns = 6'144U;
    constexpr std::size_t kOutputWeightBytes =
        kOutputRows * kOutputColumns;
    constexpr std::uint64_t kOutputWeightOffset = 3'569'011'232ULL;
    constexpr std::uint64_t kOutputScaleOffset = 126'532ULL;
    constexpr std::uint32_t kExpectedOutputScaleBits = 0x3b36db6eU;
    constexpr std::string_view kOutputWeightSha256 =
        "e49a9f770a84cfcf7c2eb60f041aa7f1af8b84f5ab6323d3b8a9151588ff2bb9";
    constexpr std::string_view kOutputScaleSha256 =
        "5ca44a7624bfdd927b145a51f20f36e4af5f571c8e9d3badc472103b8dbbb6cd";
    constexpr int kChainWarmupIterations = 10;
    constexpr int kChainMeasuredIterations = 64;
    constexpr int kChainMeasurementRounds = 5;
    constexpr float kRequiredDeltaMilliseconds = 0.5F / 64.0F;
    constexpr double kRequiredChainSpeedup = 1.010;
    const std::string chain_label =
        "Decode O-proj residual epilogue plus pre-rounded dead-up gate/up";

    std::vector<std::uint8_t> host_output_weights(kOutputWeightBytes);
    std::array<std::uint8_t, 4U> output_scale_bytes{};
    bool chain_ready = read_slice(
        kOutputWeightOffset, host_output_weights.data(),
        host_output_weights.size(), "layer-0 self_attn.o_proj.weight");
    chain_ready = chain_ready &&
                  read_slice(kOutputScaleOffset, output_scale_bytes.data(),
                             output_scale_bytes.size(),
                             "layer-0 self_attn.o_proj.weight_scale");
    if (!chain_ready) {
      return;
    }
    const std::uint32_t output_scale_bits =
        little_endian_u32(output_scale_bytes);
    float output_weight_scale = 0.0F;
    std::memcpy(&output_weight_scale, &output_scale_bits,
                sizeof(output_weight_scale));
    const std::string output_weight_hash = hash_bytes(host_output_weights);
    const std::string output_scale_hash =
        q3x::core::sha256(std::string_view(
                              reinterpret_cast<const char*>(
                                  output_scale_bytes.data()),
                              output_scale_bytes.size()))
            .hex();
    const bool output_payload_gate =
        output_weight_hash == kOutputWeightSha256 &&
        output_scale_hash == kOutputScaleSha256 &&
        output_scale_bits == kExpectedOutputScaleBits &&
        std::isfinite(output_weight_scale) && output_weight_scale >= 0.0F;
    test.expect(output_payload_gate,
                chain_label + " pins the actual output-projection payload");
    if (!output_payload_gate) {
      return;
    }

    std::vector<std::uint8_t> host_output_sidecar;
    const bool sidecar_gate =
        build_fp8_m1_aosoa4_preswizzled_sidecar(
            host_output_weights, kOutputRows, kOutputColumns, 0U, 0U,
            host_output_sidecar) &&
        host_output_sidecar.size() == kOutputWeightBytes;
    test.expect(sidecar_gate,
                chain_label + " builds the exact AoSoA4 sidecar");
    if (!sidecar_gate) {
      return;
    }

    std::vector<std::uint16_t> host_output_activation(kOutputColumns);
    for (std::size_t index = 0U; index < host_output_activation.size();
         ++index) {
      const int centered =
          static_cast<int>((index * 37U + (index >> 2U) * 13U + 11U) %
                           251U) -
          125;
      host_output_activation[index] =
          encode_bf16(static_cast<float>(centered) / 512.0F);
    }

    Fp8M1Aosoa4PreswizzledResources output_candidate_resources{};
    NvFp4M1DownDualKernelResources gate_candidate_resources{};
    chain_ready = test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            query_sm87_fp8_w8a16_m1_output_projection_aosoa4_residual_epilogue_resources_test_cuda(
                &output_candidate_resources.registers_per_thread,
                &output_candidate_resources.static_shared_bytes,
                &output_candidate_resources.local_bytes,
                &output_candidate_resources.maximum_threads_per_block,
                &output_candidate_resources.active_blocks_per_sm)),
        chain_label + " query output residual-epilogue resources");
    chain_ready = chain_ready && test.cuda_ok(
        static_cast<cudaError_t>(q3x::kernels::
            query_sm87_nvfp4_w4a16_m1_prerounded_residual_norm_gate_up_silu_dead_up_resources_test_cuda(
                &gate_candidate_resources.registers_per_thread,
                &gate_candidate_resources.static_shared_bytes,
                &gate_candidate_resources.local_bytes,
                &gate_candidate_resources.maximum_threads_per_block,
                &gate_candidate_resources.active_blocks_per_sm)),
        chain_label + " query pre-rounded gate/up resources");
    const bool output_resource_gate =
        chain_ready &&
        output_candidate_resources.registers_per_thread > 0 &&
        output_candidate_resources.registers_per_thread <= 64 &&
        output_candidate_resources.static_shared_bytes <= 1'152U &&
        output_candidate_resources.local_bytes == 0U &&
        output_candidate_resources.maximum_threads_per_block == 256 &&
        output_candidate_resources.active_blocks_per_sm >= 4;
    const bool gate_resource_gate =
        chain_ready && gate_candidate_resources.registers_per_thread > 0 &&
        gate_candidate_resources.registers_per_thread <= 64 &&
        gate_candidate_resources.static_shared_bytes == 13'632U &&
        gate_candidate_resources.local_bytes == 0U &&
        gate_candidate_resources.maximum_threads_per_block >= 512 &&
        gate_candidate_resources.active_blocks_per_sm >= 2;
    const bool resource_gate =
        output_resource_gate && gate_resource_gate;
    test.expect(resource_gate, chain_label + " clears both resource gates");
    std::cout << "PERF_DECODE_RESIDUAL_CHAIN_RESOURCES:"
              << " output_registers="
              << output_candidate_resources.registers_per_thread
              << " output_shared="
              << output_candidate_resources.static_shared_bytes
              << " output_local=" << output_candidate_resources.local_bytes
              << " output_active="
              << output_candidate_resources.active_blocks_per_sm
              << " gate_registers="
              << gate_candidate_resources.registers_per_thread
              << " gate_shared="
              << gate_candidate_resources.static_shared_bytes
              << " gate_local=" << gate_candidate_resources.local_bytes
              << " gate_active="
              << gate_candidate_resources.active_blocks_per_sm
              << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
    if (!resource_gate) {
      return;
    }

    DeviceBuffer<std::uint8_t> output_sidecar;
    DeviceBuffer<std::uint16_t> output_activation;
    DeviceBuffer<std::uint16_t> baseline_raw_output;
    DeviceBuffer<std::uint16_t> replay_residual_storage;
    DeviceBuffer<std::uint16_t> replay_gate_storage;
    chain_ready = test.cuda_ok(
        output_sidecar.allocate(host_output_sidecar.size()),
        chain_label + " allocate output sidecar");
    chain_ready = chain_ready && test.cuda_ok(
        output_activation.allocate(host_output_activation.size()),
        chain_label + " allocate output activation");
    chain_ready = chain_ready && test.cuda_ok(
        baseline_raw_output.allocate(kOutputRows),
        chain_label + " allocate baseline raw output");
    chain_ready = chain_ready && test.cuda_ok(
        replay_residual_storage.allocate(kColumns + 2U * kGuardElements),
        chain_label + " allocate replay residual");
    chain_ready = chain_ready && test.cuda_ok(
        replay_gate_storage.allocate(guarded_count),
        chain_label + " allocate replay gate");
    chain_ready = chain_ready && upload_fixture(chain_label);
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemcpyAsync(output_sidecar.get(), host_output_sidecar.data(),
                        host_output_sidecar.size(), cudaMemcpyHostToDevice,
                        stream),
        chain_label + " upload output sidecar");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemcpyAsync(output_activation.get(),
                        host_output_activation.data(),
                        host_output_activation.size() *
                            sizeof(std::uint16_t),
                        cudaMemcpyHostToDevice, stream),
        chain_label + " upload output activation");
    chain_ready = chain_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), chain_label + " upload synchronize");
    if (!chain_ready) {
      return;
    }

    std::uint16_t* const replay_residual =
        replay_residual_storage.get() + kGuardElements;
    std::uint16_t* const replay_gate =
        replay_gate_storage.get() + kGuardElements;
    const auto launch_chain_baseline = [&]() noexcept {
      int status = q3x::kernels::
          launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_bf16_cuda(
              output_sidecar.get(), output_weight_scale,
              output_activation.get(), kOutputRows, kOutputColumns,
              baseline_raw_output.get(), static_cast<void*>(stream));
      if (status != static_cast<int>(cudaSuccess)) {
        return status;
      }
      return q3x::kernels::
          launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_dead_up_bf16_cuda(
              gate_packed.get(), gate_scales.get(), gate_scale2,
              up_packed.get(), up_scales.get(), up_scale2,
              residual_left.get(), baseline_raw_output.get(),
              norm_weight.get(), kNormEpsilon, kRows, kColumns,
              baseline_residual, baseline_gate, baseline_up,
              static_cast<void*>(stream));
    };
    const auto launch_chain_candidate_to =
        [&](std::uint16_t* const residual_destination,
            std::uint16_t* const gate_destination) noexcept {
          int status = q3x::kernels::
              launch_sm87_fp8_w8a16_m1_output_projection_aosoa4_residual_epilogue_test_cuda(
                  output_sidecar.get(), output_weight_scale,
                  output_activation.get(), residual_left.get(), kOutputRows,
                  kOutputColumns, residual_destination,
                  static_cast<void*>(stream));
          if (status != static_cast<int>(cudaSuccess)) {
            return status;
          }
          return q3x::kernels::
              launch_sm87_nvfp4_w4a16_prerounded_residual_norm_gate_up_silu_dead_up_test_cuda(
                  gate_packed.get(), gate_scales.get(), gate_scale2,
                  up_packed.get(), up_scales.get(), up_scale2,
                  residual_destination, norm_weight.get(), kNormEpsilon,
                  kRows, kColumns, gate_destination, candidate_up,
                  static_cast<void*>(stream));
        };
    const auto launch_chain_candidate = [&]() noexcept {
      return launch_chain_candidate_to(candidate_residual, candidate_gate);
    };

    chain_ready = test.cuda_ok(
        cudaMemsetAsync(baseline_residual_storage.get(), 0x31U,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        chain_label + " poison baseline residual");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_residual_storage.get(), 0x42U,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        chain_label + " poison candidate residual");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemsetAsync(replay_residual_storage.get(), 0x53U,
                        (kColumns + 2U * kGuardElements) *
                            sizeof(std::uint16_t),
                        stream),
        chain_label + " poison replay residual");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemsetAsync(baseline_gate_storage.get(), 0x64U,
                        guarded_count * sizeof(std::uint16_t), stream),
        chain_label + " poison baseline gate");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_gate_storage.get(), 0x75U,
                        guarded_count * sizeof(std::uint16_t), stream),
        chain_label + " poison candidate gate");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemsetAsync(replay_gate_storage.get(), 0x86U,
                        guarded_count * sizeof(std::uint16_t), stream),
        chain_label + " poison replay gate");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemsetAsync(baseline_up_storage.get(), 0x97U,
                        guarded_count * sizeof(std::uint16_t), stream),
        chain_label + " poison baseline up workspace");
    chain_ready = chain_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_up_storage.get(), 0xa8U,
                        guarded_count * sizeof(std::uint16_t), stream),
        chain_label + " poison candidate up workspace");
    chain_ready = chain_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_chain_baseline()),
        chain_label + " launch baseline correctness");
    chain_ready = chain_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_chain_candidate()),
        chain_label + " launch candidate correctness");

    std::vector<std::uint16_t> observed_baseline_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_candidate_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_replay_residual(
        kColumns + 2U * kGuardElements);
    std::vector<std::uint16_t> observed_baseline_gate(guarded_count);
    std::vector<std::uint16_t> observed_candidate_gate(guarded_count);
    std::vector<std::uint16_t> observed_replay_gate(guarded_count);
    std::vector<std::uint16_t> observed_baseline_up(guarded_count);
    std::vector<std::uint16_t> observed_candidate_up(guarded_count);
    const auto copy_bf16 =
        [&](std::vector<std::uint16_t>& destination,
            const DeviceBuffer<std::uint16_t>& source,
            const std::string& operation) {
          return test.cuda_ok(
              cudaMemcpyAsync(destination.data(), source.get(),
                              destination.size() * sizeof(std::uint16_t),
                              cudaMemcpyDeviceToHost, stream),
              operation);
        };
    chain_ready = chain_ready && copy_bf16(
        observed_baseline_residual, baseline_residual_storage,
        chain_label + " copy baseline residual");
    chain_ready = chain_ready && copy_bf16(
        observed_candidate_residual, candidate_residual_storage,
        chain_label + " copy candidate residual");
    chain_ready = chain_ready && copy_bf16(
        observed_baseline_gate, baseline_gate_storage,
        chain_label + " copy baseline gate");
    chain_ready = chain_ready && copy_bf16(
        observed_candidate_gate, candidate_gate_storage,
        chain_label + " copy candidate gate");
    chain_ready = chain_ready && copy_bf16(
        observed_baseline_up, baseline_up_storage,
        chain_label + " copy baseline up workspace");
    chain_ready = chain_ready && copy_bf16(
        observed_candidate_up, candidate_up_storage,
        chain_label + " copy candidate up workspace");
    chain_ready = chain_ready && test.cuda_ok(
        static_cast<cudaError_t>(
            launch_chain_candidate_to(replay_residual, replay_gate)),
        chain_label + " launch candidate replay");
    chain_ready = chain_ready && copy_bf16(
        observed_replay_residual, replay_residual_storage,
        chain_label + " copy replay residual");
    chain_ready = chain_ready && copy_bf16(
        observed_replay_gate, replay_gate_storage,
        chain_label + " copy replay gate");
    chain_ready = chain_ready && test.cuda_ok(
        cudaStreamSynchronize(stream),
        chain_label + " correctness synchronize");
    if (!chain_ready) {
      return;
    }

    std::size_t residual_mismatches = 0U;
    std::size_t gate_mismatches = 0U;
    std::size_t replay_residual_mismatches = 0U;
    std::size_t replay_gate_mismatches = 0U;
    bool finite_outputs = true;
    for (std::size_t index = 0U; index < kColumns; ++index) {
      const std::size_t guarded = kGuardElements + index;
      residual_mismatches +=
          observed_baseline_residual[guarded] !=
          observed_candidate_residual[guarded];
      replay_residual_mismatches +=
          observed_candidate_residual[guarded] !=
          observed_replay_residual[guarded];
      finite_outputs =
          finite_outputs &&
          std::isfinite(decode_bf16(observed_candidate_residual[guarded]));
    }
    for (std::size_t row = 0U; row < kRows; ++row) {
      const std::size_t guarded = kGuardElements + row;
      gate_mismatches += observed_baseline_gate[guarded] !=
                         observed_candidate_gate[guarded];
      replay_gate_mismatches += observed_candidate_gate[guarded] !=
                                observed_replay_gate[guarded];
      finite_outputs =
          finite_outputs &&
          std::isfinite(decode_bf16(observed_candidate_gate[guarded]));
    }
    const auto guards_intact =
        [&](const std::vector<std::uint16_t>& values,
            const std::uint16_t canary) {
          return std::all_of(values.begin(),
                             values.begin() + kGuardElements,
                             [canary](const std::uint16_t value) {
                               return value == canary;
                             }) &&
                 std::all_of(values.end() - kGuardElements, values.end(),
                             [canary](const std::uint16_t value) {
                               return value == canary;
                             });
        };
    const bool guards_gate =
        guards_intact(observed_baseline_residual, 0x3131U) &&
        guards_intact(observed_candidate_residual, 0x4242U) &&
        guards_intact(observed_replay_residual, 0x5353U) &&
        guards_intact(observed_baseline_gate, 0x6464U) &&
        guards_intact(observed_candidate_gate, 0x7575U) &&
        guards_intact(observed_replay_gate, 0x8686U);
    const bool workspace_gate =
        std::all_of(observed_baseline_up.begin(),
                    observed_baseline_up.end(),
                    [](const std::uint16_t value) {
                      return value == 0x9797U;
                    }) &&
        std::all_of(observed_candidate_up.begin(),
                    observed_candidate_up.end(),
                    [](const std::uint16_t value) {
                      return value == 0xa8a8U;
                    });
    const bool correctness_gate =
        residual_mismatches == 0U && gate_mismatches == 0U &&
        replay_residual_mismatches == 0U &&
        replay_gate_mismatches == 0U && finite_outputs && guards_gate &&
        workspace_gate;
    test.expect(correctness_gate,
                chain_label + " is bitwise, finite, guarded, and replayable");
    std::cout << "DECODE_RESIDUAL_CHAIN_DIFF:"
              << " residual_mismatches=" << residual_mismatches << '/'
              << kColumns << " gate_mismatches=" << gate_mismatches << '/'
              << kRows
              << " replay_residual_mismatches="
              << replay_residual_mismatches << '/' << kColumns
              << " replay_gate_mismatches=" << replay_gate_mismatches << '/'
              << kRows
              << " finite_outputs="
              << (finite_outputs ? "true" : "false")
              << " guards=" << (guards_gate ? "PASS" : "FAIL")
              << " workspaces_untouched="
              << (workspace_gate ? "PASS" : "FAIL")
              << " gate=" << (correctness_gate ? "PASS" : "FAIL") << '\n';
    if (!correctness_gate) {
      return;
    }

    bool timing_ready = true;
    for (int iteration = 0;
         iteration < kChainWarmupIterations && timing_ready; ++iteration) {
      timing_ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_chain_baseline()),
          chain_label + " baseline warmup");
      timing_ready = timing_ready && test.cuda_ok(
          static_cast<cudaError_t>(launch_chain_candidate()),
          chain_label + " candidate warmup");
    }
    timing_ready = timing_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), chain_label + " warmup synchronize");
    constexpr std::size_t kChainTimedPasses =
        2U * static_cast<std::size_t>(kChainMeasurementRounds);
    std::array<float, kChainTimedPasses> baseline_passes{};
    std::array<float, kChainTimedPasses> candidate_passes{};
    std::array<float, kChainMeasurementRounds> paired_deltas{};
    bool all_rounds_improve = timing_ready;
    for (int round = 0;
         round < kChainMeasurementRounds && timing_ready; ++round) {
      const std::string round_label =
          chain_label + " round=" + std::to_string(round + 1);
      const float b1 = measure_small_m_tile(
          test, stream, launch_chain_baseline, kChainMeasuredIterations,
          round_label + " B1");
      const float c1 = measure_small_m_tile(
          test, stream, launch_chain_candidate, kChainMeasuredIterations,
          round_label + " C1");
      const float c2 = measure_small_m_tile(
          test, stream, launch_chain_candidate, kChainMeasuredIterations,
          round_label + " C2");
      const float b2 = measure_small_m_tile(
          test, stream, launch_chain_baseline, kChainMeasuredIterations,
          round_label + " B2");
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      baseline_passes[pass] = b1;
      baseline_passes[pass + 1U] = b2;
      candidate_passes[pass] = c1;
      candidate_passes[pass + 1U] = c2;
      const bool finite = std::isfinite(b1) && b1 > 0.0F &&
                          std::isfinite(c1) && c1 > 0.0F &&
                          std::isfinite(c2) && c2 > 0.0F &&
                          std::isfinite(b2) && b2 > 0.0F;
      const float paired_baseline = 0.5F * (b1 + b2);
      const float paired_candidate = 0.5F * (c1 + c2);
      paired_deltas[static_cast<std::size_t>(round)] =
          paired_baseline - paired_candidate;
      const bool round_improves =
          finite && c1 < b1 && c2 < b2 &&
          paired_candidate < paired_baseline;
      timing_ready = timing_ready && finite;
      all_rounds_improve = all_rounds_improve && round_improves;
      std::cout << "PERF_DECODE_RESIDUAL_CHAIN_ROUND:"
                << " fixture=actual_checkpoint"
                << " round=" << round + 1 << " order=B-C-C-B"
                << " logical_chains_per_pass="
                << kChainMeasuredIterations
                << " baseline1_ms=" << b1 << " candidate1_ms=" << c1
                << " candidate2_ms=" << c2 << " baseline2_ms=" << b2
                << " paired_delta_ms="
                << paired_deltas[static_cast<std::size_t>(round)]
                << " gate=" << (round_improves ? "PASS" : "FAIL")
                << '\n';
    }
    const float baseline_median =
        timing_ready ? median_fp8_kv_pair_timing(baseline_passes)
                     : std::numeric_limits<float>::quiet_NaN();
    const float candidate_median =
        timing_ready ? median_fp8_kv_pair_timing(candidate_passes)
                     : std::numeric_limits<float>::quiet_NaN();
    const float delta_median =
        timing_ready ? median_fp8_kv_pair_timing(paired_deltas)
                     : std::numeric_limits<float>::quiet_NaN();
    const double speedup =
        static_cast<double>(baseline_median) /
        static_cast<double>(candidate_median);
    const double projected_decode_delta =
        64.0 * static_cast<double>(delta_median);
    const bool timing_gate =
        timing_ready && all_rounds_improve &&
        delta_median >= kRequiredDeltaMilliseconds &&
        std::isfinite(speedup) && speedup >= kRequiredChainSpeedup;
    const bool selected_gate =
        header_gate && pinned_payload_gate && output_payload_gate &&
        resource_gate && correctness_gate && timing_gate;
    test.expect(selected_gate,
                chain_label + " clears the actual-checkpoint stop-loss");
    std::cout << "PERF_DECODE_RESIDUAL_CHAIN_SELECTED:"
              << " fixture=actual_checkpoint"
              << " output_scale_bits=" << output_scale_bits
              << " output_scale=" << output_weight_scale
              << " output_weight_sha256=" << output_weight_hash
              << " output_scale_sha256=" << output_scale_hash
              << " baseline_two_kernel_median_ms=" << baseline_median
              << " candidate_two_kernel_median_ms=" << candidate_median
              << " median_delta_ms_per_layer=" << delta_median
              << " projected_64_layer_delta_ms="
              << projected_decode_delta
              << " speedup=" << speedup
              << " all_rounds_improve="
              << (all_rounds_improve ? "true" : "false")
              << " required_delta_ms_per_layer="
              << kRequiredDeltaMilliseconds
              << " required_projected_64_layer_delta_ms=0.5"
              << " required_speedup=" << kRequiredChainSpeedup
              << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
    return;
  }

  const auto check_correctness = [&](const std::string& fixture_label) {
    constexpr std::array<std::uint8_t, 7U> kGuardBytes{{
        0xa1U, 0xb2U, 0xc3U, 0xd4U, 0xe5U, 0x69U, 0x78U,
    }};
    std::array<DeviceBuffer<std::uint16_t>*, 7U> storages{{
        &baseline_gate_storage, &baseline_up_storage, &baseline_final_storage,
        &pair_gate_storage, &pair_up_storage, &candidate_gate_storage,
        &candidate_up_storage,
    }};
    bool correct_ready = true;
    for (std::size_t index = 0U; index < storages.size(); ++index) {
      correct_ready = correct_ready && test.cuda_ok(
          cudaMemsetAsync(storages[index]->get(), kGuardBytes[index],
                          guarded_count * sizeof(std::uint16_t), stream),
          fixture_label + " poison guarded output");
    }
    correct_ready = correct_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_baseline_correctness()),
        fixture_label + " launch two-single+SiLU baseline");
    correct_ready = correct_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_pair()),
        fixture_label + " launch pair-only diagnostic");
    correct_ready = correct_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_candidate()),
        fixture_label + " launch public fused candidate");
    std::array<std::vector<std::uint16_t>, 7U> observed;
    for (std::size_t index = 0U; index < observed.size(); ++index) {
      observed[index].resize(guarded_count);
      correct_ready = correct_ready && test.cuda_ok(
          cudaMemcpyAsync(observed[index].data(), storages[index]->get(),
                          guarded_count * sizeof(std::uint16_t),
                          cudaMemcpyDeviceToHost, stream),
          fixture_label + " copy guarded output");
    }
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_gate_storage.get(), kGuardBytes[5U],
                        guarded_count * sizeof(std::uint16_t), stream),
        fixture_label + " poison candidate replay gate");
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemsetAsync(candidate_up_storage.get(), kGuardBytes[6U],
                        guarded_count * sizeof(std::uint16_t), stream),
        fixture_label + " poison candidate replay up");
    correct_ready = correct_ready && test.cuda_ok(
        static_cast<cudaError_t>(launch_candidate()),
        fixture_label + " replay public fused candidate");
    std::vector<std::uint16_t> replay_gate(guarded_count);
    std::vector<std::uint16_t> replay_up(guarded_count);
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemcpyAsync(replay_gate.data(), candidate_gate_storage.get(),
                        guarded_count * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy replay gate");
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemcpyAsync(replay_up.data(), candidate_up_storage.get(),
                        guarded_count * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy replay up");
    std::vector<std::uint8_t> observed_gate_packed(kPackedCount);
    std::vector<std::uint8_t> observed_up_packed(kPackedCount);
    std::vector<std::uint8_t> observed_gate_scales(kScaleCount);
    std::vector<std::uint8_t> observed_up_scales(kScaleCount);
    std::vector<std::uint16_t> observed_activation(kColumns);
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_gate_packed.data(), gate_packed.get(),
                        observed_gate_packed.size(), cudaMemcpyDeviceToHost,
                        stream),
        fixture_label + " copy preserved gate weights");
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_up_packed.data(), up_packed.get(),
                        observed_up_packed.size(), cudaMemcpyDeviceToHost,
                        stream),
        fixture_label + " copy preserved up weights");
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_gate_scales.data(), gate_scales.get(),
                        observed_gate_scales.size(), cudaMemcpyDeviceToHost,
                        stream),
        fixture_label + " copy preserved gate scales");
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_up_scales.data(), up_scales.get(),
                        observed_up_scales.size(), cudaMemcpyDeviceToHost,
                        stream),
        fixture_label + " copy preserved up scales");
    correct_ready = correct_ready && test.cuda_ok(
        cudaMemcpyAsync(observed_activation.data(), activation.get(),
                        observed_activation.size() * sizeof(std::uint16_t),
                        cudaMemcpyDeviceToHost, stream),
        fixture_label + " copy preserved activation");
    correct_ready = correct_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), fixture_label + " synchronize");
    if (!correct_ready) {
      return false;
    }
    std::size_t pair_gate_mismatches = 0U;
    std::size_t pair_up_mismatches = 0U;
    std::size_t fused_gate_mismatches = 0U;
    std::size_t fused_up_mismatches = 0U;
    std::size_t replay_mismatches = 0U;
    std::size_t nonfinite = 0U;
    for (std::size_t row = 0U; row < kRows; ++row) {
      const std::size_t index = kGuardElements + row;
      pair_gate_mismatches += observed[0U][index] != observed[3U][index];
      pair_up_mismatches += observed[1U][index] != observed[4U][index];
      fused_gate_mismatches += observed[2U][index] != observed[5U][index];
      fused_up_mismatches += observed[1U][index] != observed[6U][index];
      replay_mismatches += observed[5U][index] != replay_gate[index];
      replay_mismatches += observed[6U][index] != replay_up[index];
      nonfinite += !is_bf16_finite(observed[0U][index]);
      nonfinite += !is_bf16_finite(observed[1U][index]);
      nonfinite += !is_bf16_finite(observed[2U][index]);
      nonfinite += !is_bf16_finite(observed[5U][index]);
      nonfinite += !is_bf16_finite(observed[6U][index]);
    }
    bool guards = true;
    for (std::size_t output = 0U; output < observed.size(); ++output) {
      const std::uint16_t guard = static_cast<std::uint16_t>(
          kGuardBytes[output] * 0x0101U);
      for (std::size_t index = 0U; index < kGuardElements; ++index) {
        guards = guards && observed[output][index] == guard &&
                 observed[output][kGuardElements + kRows + index] == guard;
      }
    }
    for (std::size_t index = 0U; index < kGuardElements; ++index) {
      guards = guards && replay_gate[index] == 0x6969U &&
               replay_up[index] == 0x7878U &&
               replay_gate[kGuardElements + kRows + index] == 0x6969U &&
               replay_up[kGuardElements + kRows + index] == 0x7878U;
    }
    const bool bitwise = pair_gate_mismatches == 0U &&
                         pair_up_mismatches == 0U &&
                         fused_gate_mismatches == 0U &&
                         fused_up_mismatches == 0U &&
                         replay_mismatches == 0U;
    const bool inputs_preserved =
        observed_gate_packed == host_gate_packed &&
        observed_up_packed == host_up_packed &&
        observed_gate_scales == host_gate_scales &&
        observed_up_scales == host_up_scales &&
        observed_activation == host_activation;
    const bool correctness_gate =
        bitwise && guards && nonfinite == 0U && inputs_preserved;
    test.expect(correctness_gate,
                fixture_label + " is bitwise, finite, guarded, replayable");
    std::cout << "NVFP4_M1_GATE_UP_SILU_EXACT_DIFF: fixture="
              << fixture_label
              << " pair_gate_mismatches=" << pair_gate_mismatches << '/'
              << kRows << " pair_up_mismatches=" << pair_up_mismatches << '/'
              << kRows
              << " fused_final_mismatches=" << fused_gate_mismatches << '/'
              << kRows << " fused_up_mismatches=" << fused_up_mismatches
              << '/' << kRows << " replay_mismatches=" << replay_mismatches
              << '/' << (2U * kRows)
              << " nonfinite=" << nonfinite
              << " guards=" << (guards ? "intact" : "BAD")
              << " inputs_preserved="
              << (inputs_preserved ? "true" : "false")
              << " public_abi=true"
              << " gate=" << (correctness_gate ? "PASS" : "FAIL") << '\n';
    return correctness_gate;
  };

  const auto benchmark = [&](const std::string& fixture_label) {
    NvFp4GateUpSiluFusionTiming timing{};
    bool timing_ready = true;
    for (int iteration = 0;
         iteration < kWarmupIterations && timing_ready; ++iteration) {
      timing_ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_baseline()),
          fixture_label + " baseline warmup");
      timing_ready = timing_ready && test.cuda_ok(
          static_cast<cudaError_t>(launch_candidate()),
          fixture_label + " candidate warmup");
    }
    timing_ready = timing_ready && test.cuda_ok(
        cudaStreamSynchronize(stream), fixture_label + " warmup synchronize");
    if (!timing_ready) {
      return timing;
    }
    constexpr std::size_t kPasses =
        2U * static_cast<std::size_t>(kMeasurementRounds);
    std::array<float, kPasses> baseline_passes{};
    std::array<float, kPasses> candidate_passes{};
    bool finite = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const std::string round_label =
          fixture_label + " round=" + std::to_string(round + 1);
      const float b1 = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " B1");
      const float c1 = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " C1");
      const float c2 = measure_small_m_tile(
          test, stream, launch_candidate, kMeasuredIterations,
          round_label + " C2");
      const float b2 = measure_small_m_tile(
          test, stream, launch_baseline, kMeasuredIterations,
          round_label + " B2");
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      baseline_passes[pass] = b1;
      baseline_passes[pass + 1U] = b2;
      candidate_passes[pass] = c1;
      candidate_passes[pass + 1U] = c2;
      finite = finite && std::isfinite(b1) && std::isfinite(c1) &&
               std::isfinite(c2) && std::isfinite(b2);
      std::cout << "PERF_NVFP4_M1_GATE_UP_SILU_ROUND: fixture="
                << fixture_label << " round=" << round + 1
                << " order=B-C-C-B iterations=64"
                << " baseline1_ms=" << b1 << " candidate1_ms=" << c1
                << " candidate2_ms=" << c2 << " baseline2_ms=" << b2
                << '\n';
    }
    if (!finite) {
      return timing;
    }
    timing.baseline_milliseconds =
        median_fp8_kv_pair_timing(baseline_passes);
    timing.candidate_milliseconds =
        median_fp8_kv_pair_timing(candidate_passes);
    return timing;
  };

  const auto check_residual_norm_correctness =
