        correct_ready = correct_ready && test.cuda_ok(
            cudaMemcpyAsync(observed_norm_weight.data(), norm_weight.get(),
                            kColumns * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            fixture_label + " copy preserved norm weight");
        correct_ready = correct_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            fixture_label + " residual correctness synchronize");
        if (replay_graph_exec != nullptr) {
          correct_ready =
              test.cuda_ok(cudaGraphExecDestroy(replay_graph_exec),
                           fixture_label + " destroy dead-up graph exec") &&
              correct_ready;
        }
        if (replay_graph != nullptr) {
          correct_ready =
              test.cuda_ok(cudaGraphDestroy(replay_graph),
                           fixture_label + " destroy dead-up graph") &&
              correct_ready;
        }
        if (!correct_ready) {
          return false;
        }

        std::size_t residual_mismatches = 0U;
        std::size_t gate_mismatches = 0U;
        std::size_t up_mismatches = 0U;
        std::size_t replay_mismatches = 0U;
        std::size_t nonfinite = 0U;
        bool candidate_up_untouched = true;
        for (std::size_t index = 0U; index < kColumns; ++index) {
          const std::size_t guarded = kGuardElements + index;
          residual_mismatches +=
              observed_baseline_residual[guarded] !=
              observed_candidate_residual[guarded];
          replay_mismatches += observed_candidate_residual[guarded] !=
                               replay_candidate_residual[guarded];
          nonfinite += !is_bf16_finite(observed_candidate_residual[guarded]);
        }
        for (std::size_t row = 0U; row < kRows; ++row) {
          const std::size_t guarded = kGuardElements + row;
          gate_mismatches += observed_baseline_gate[guarded] !=
                             observed_candidate_gate[guarded];
          if (candidate_publishes_up) {
            up_mismatches += observed_baseline_up[guarded] !=
                             observed_candidate_up[guarded];
          } else {
            candidate_up_untouched =
                candidate_up_untouched &&
                observed_candidate_up[guarded] == 0xf6f6U &&
                replay_candidate_up[guarded] == 0x8c8cU;
          }
          replay_mismatches += observed_candidate_gate[guarded] !=
                               replay_candidate_gate[guarded];
          if (candidate_publishes_up) {
            replay_mismatches += observed_candidate_up[guarded] !=
                                 replay_candidate_up[guarded];
          }
          nonfinite += !is_bf16_finite(observed_candidate_gate[guarded]);
          if (candidate_publishes_up) {
            nonfinite += !is_bf16_finite(observed_candidate_up[guarded]);
          }
        }
        bool guards = true;
        for (std::size_t index = 0U; index < kGuardElements; ++index) {
          guards = guards && observed_baseline_residual[index] == 0xa1a1U &&
                   observed_candidate_residual[index] == 0xb2b2U &&
                   observed_baseline_residual[kGuardElements + kColumns +
                                              index] == 0xa1a1U &&
                   observed_candidate_residual[kGuardElements + kColumns +
                                               index] == 0xb2b2U &&
                   observed_baseline_gate[index] == 0xc3c3U &&
                   observed_baseline_up[index] == 0xd4d4U &&
                   observed_candidate_gate[index] == 0xe5e5U &&
                   observed_candidate_up[index] == 0xf6f6U &&
                   observed_baseline_gate[kGuardElements + kRows + index] ==
                       0xc3c3U &&
                   observed_baseline_up[kGuardElements + kRows + index] ==
                       0xd4d4U &&
                   observed_candidate_gate[kGuardElements + kRows + index] ==
                       0xe5e5U &&
                   observed_candidate_up[kGuardElements + kRows + index] ==
                       0xf6f6U &&
                   replay_candidate_residual[index] == 0xb2b2U &&
                   replay_candidate_residual[kGuardElements + kColumns +
                                             index] == 0xb2b2U &&
                   replay_candidate_gate[index] == 0xe5e5U &&
                   replay_candidate_up[index] == 0x8c8cU &&
                   replay_candidate_gate[kGuardElements + kRows + index] ==
                       0xe5e5U &&
                   replay_candidate_up[kGuardElements + kRows + index] ==
                       0x8c8cU;
        }
        const bool inputs_preserved =
            observed_gate_packed == host_gate_packed &&
            observed_up_packed == host_up_packed &&
            observed_gate_scales == host_gate_scales &&
            observed_up_scales == host_up_scales &&
            observed_left == host_residual_left &&
            observed_right == host_residual_right &&
            observed_norm_weight == host_norm_weight;
        const bool correctness_gate =
            residual_mismatches == 0U && gate_mismatches == 0U &&
            (!candidate_publishes_up || up_mismatches == 0U) &&
            candidate_up_untouched && replay_mismatches == 0U &&
            nonfinite == 0U && guards && inputs_preserved;
        test.expect(correctness_gate,
                    fixture_label +
                        " residual/norm fusion is bitwise and guarded");
        std::cout << "NVFP4_M1_RESIDUAL_NORM_GATE_UP_SILU_EXACT_DIFF: fixture="
                  << fixture_label
                  << " candidate=" << candidate_name
                  << " residual_mismatches=" << residual_mismatches << '/'
                  << kColumns << " final_gate_mismatches=" << gate_mismatches
                  << '/' << kRows << " up_mismatches=" << up_mismatches << '/'
                  << kRows << " replay_mismatches=" << replay_mismatches << '/'
                  << (kColumns +
                      (candidate_publishes_up ? 2U * kRows : kRows))
                  << " nonfinite=" << nonfinite
                  << " up_publication="
                  << (candidate_publishes_up ? "required" : "elided")
                  << " dead_up_buffer_untouched="
                  << (candidate_up_untouched ? "true" : "false")
                  << " distinct_replay_up_poison=true"
                  << " replay_mode="
                  << (replay_uses_cuda_graph ? "cuda_graph" : "direct")
                  << " guards=" << (guards ? "intact" : "BAD")
                  << " inputs_preserved="
                  << (inputs_preserved ? "true" : "false")
                  << " gate=" << (correctness_gate ? "PASS" : "FAIL")
                  << '\n';
        return correctness_gate;
      };

  const auto check_residual_norm_reduction_direct_correctness =
      [&](const std::string& fixture_label, const bool require_all_nan,
          const auto& launch_direct_candidate,
          const std::string_view candidate_name,
          const bool candidate_publishes_up = true) {
        constexpr std::size_t kResidualGuardedCount =
            kColumns + 2U * kGuardElements;
        bool correct_ready = test.cuda_ok(
            cudaMemsetAsync(baseline_residual_storage.get(), 0x19U,
                            kResidualGuardedCount * sizeof(std::uint16_t),
                            stream),
            fixture_label + " poison direct shared-tree residual");
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemsetAsync(candidate_residual_storage.get(), 0x2aU,
                            kResidualGuardedCount * sizeof(std::uint16_t),
                            stream),
            fixture_label + " poison direct warp-tail residual");
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemsetAsync(baseline_gate_storage.get(), 0x3bU,
                            guarded_count * sizeof(std::uint16_t), stream),
            fixture_label + " poison direct shared-tree final");
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemsetAsync(baseline_up_storage.get(), 0x4cU,
                            guarded_count * sizeof(std::uint16_t), stream),
            fixture_label + " poison direct shared-tree up");
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemsetAsync(candidate_gate_storage.get(), 0x5dU,
                            guarded_count * sizeof(std::uint16_t), stream),
            fixture_label + " poison direct warp-tail final");
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemsetAsync(candidate_up_storage.get(), 0x6eU,
                            guarded_count * sizeof(std::uint16_t), stream),
            fixture_label + " poison direct warp-tail up");
        correct_ready = correct_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_residual_norm_shared_tree()),
            fixture_label + " launch direct shared-tree baseline");
        correct_ready = correct_ready && test.cuda_ok(
            static_cast<cudaError_t>(launch_direct_candidate()),
            fixture_label + " launch direct " + std::string(candidate_name));

        std::vector<std::uint16_t> observed_shared_residual(
            kResidualGuardedCount);
        std::vector<std::uint16_t> observed_warp_residual(
            kResidualGuardedCount);
        std::vector<std::uint16_t> observed_shared_final(guarded_count);
        std::vector<std::uint16_t> observed_shared_up(guarded_count);
        std::vector<std::uint16_t> observed_warp_final(guarded_count);
        std::vector<std::uint16_t> observed_warp_up(guarded_count);
        const auto copy_output =
            [&](std::vector<std::uint16_t>& destination,
                const DeviceBuffer<std::uint16_t>& source,
                const std::string& operation) {
              return test.cuda_ok(
                  cudaMemcpyAsync(destination.data(), source.get(),
                                  destination.size() * sizeof(std::uint16_t),
                                  cudaMemcpyDeviceToHost, stream),
                  operation);
            };
        correct_ready = correct_ready && copy_output(
            observed_shared_residual, baseline_residual_storage,
            fixture_label + " copy direct shared-tree residual");
        correct_ready = correct_ready && copy_output(
            observed_warp_residual, candidate_residual_storage,
            fixture_label + " copy direct warp-tail residual");
        correct_ready = correct_ready && copy_output(
            observed_shared_final, baseline_gate_storage,
            fixture_label + " copy direct shared-tree final");
        correct_ready = correct_ready && copy_output(
            observed_shared_up, baseline_up_storage,
            fixture_label + " copy direct shared-tree up");
        correct_ready = correct_ready && copy_output(
            observed_warp_final, candidate_gate_storage,
            fixture_label + " copy direct warp-tail final");
        correct_ready = correct_ready && copy_output(
            observed_warp_up, candidate_up_storage,
            fixture_label + " copy direct warp-tail up");
        std::vector<std::uint16_t> observed_left(kColumns);
        std::vector<std::uint16_t> observed_right(kColumns);
        std::vector<std::uint16_t> observed_weight(kColumns);
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemcpyAsync(observed_left.data(), residual_left.get(),
                            kColumns * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            fixture_label + " copy direct residual left input");
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemcpyAsync(observed_right.data(), residual_right.get(),
                            kColumns * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            fixture_label + " copy direct residual right input");
        correct_ready = correct_ready && test.cuda_ok(
            cudaMemcpyAsync(observed_weight.data(), norm_weight.get(),
                            kColumns * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
            fixture_label + " copy direct norm weight input");
        correct_ready = correct_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            fixture_label + " direct correctness synchronize");
        if (!correct_ready) {
          return false;
        }

        std::size_t residual_mismatches = 0U;
        std::size_t final_mismatches = 0U;
        std::size_t up_mismatches = 0U;
        std::size_t unexpected_nonfinite = 0U;
        std::size_t classified_nan_outputs = 0U;
        bool class_and_sign = true;
        bool candidate_up_untouched = true;
        for (std::size_t column = 0U; column < kColumns; ++column) {
          const std::size_t guarded = kGuardElements + column;
          const std::uint16_t shared_bits =
              observed_shared_residual[guarded];
          const std::uint16_t warp_bits = observed_warp_residual[guarded];
          residual_mismatches += shared_bits != warp_bits;
          if (!require_all_nan) {
            unexpected_nonfinite += !is_bf16_finite(shared_bits) ? 1U : 0U;
            unexpected_nonfinite += !is_bf16_finite(warp_bits) ? 1U : 0U;
          }
        }
        for (std::size_t row = 0U; row < kRows; ++row) {
          const std::size_t guarded = kGuardElements + row;
          const std::uint16_t shared_final =
              observed_shared_final[guarded];
          const std::uint16_t warp_final = observed_warp_final[guarded];
          const std::uint16_t shared_up = observed_shared_up[guarded];
          const std::uint16_t warp_up = observed_warp_up[guarded];
          final_mismatches += shared_final != warp_final;
          if (candidate_publishes_up) {
            up_mismatches += shared_up != warp_up;
          } else {
            candidate_up_untouched =
                candidate_up_untouched && warp_up == 0x6e6eU;
          }
          if (require_all_nan) {
            const bool final_nan =
                is_bf16_nan(shared_final) && is_bf16_nan(warp_final);
            classified_nan_outputs += final_nan ? 1U : 0U;
            class_and_sign = class_and_sign && final_nan &&
                             ((shared_final ^ warp_final) & 0x8000U) == 0U;
            if (candidate_publishes_up) {
              const bool up_nan =
                  is_bf16_nan(shared_up) && is_bf16_nan(warp_up);
              classified_nan_outputs += up_nan ? 1U : 0U;
              class_and_sign =
                  class_and_sign && up_nan &&
                  ((shared_up ^ warp_up) & 0x8000U) == 0U;
            }
          } else {
            unexpected_nonfinite +=
                !is_bf16_finite(shared_final) ? 1U : 0U;
            unexpected_nonfinite +=
                !is_bf16_finite(warp_final) ? 1U : 0U;
            if (candidate_publishes_up) {
              unexpected_nonfinite += !is_bf16_finite(shared_up) ? 1U : 0U;
              unexpected_nonfinite += !is_bf16_finite(warp_up) ? 1U : 0U;
            }
          }
        }
        bool guards = true;
        for (std::size_t index = 0U; index < kGuardElements; ++index) {
          guards =
              guards && observed_shared_residual[index] == 0x1919U &&
              observed_warp_residual[index] == 0x2a2aU &&
              observed_shared_residual[kGuardElements + kColumns + index] ==
                  0x1919U &&
              observed_warp_residual[kGuardElements + kColumns + index] ==
                  0x2a2aU &&
              observed_shared_final[index] == 0x3b3bU &&
              observed_shared_up[index] == 0x4c4cU &&
              observed_warp_final[index] == 0x5d5dU &&
              observed_warp_up[index] == 0x6e6eU &&
              observed_shared_final[kGuardElements + kRows + index] ==
                  0x3b3bU &&
              observed_shared_up[kGuardElements + kRows + index] == 0x4c4cU &&
              observed_warp_final[kGuardElements + kRows + index] ==
                  0x5d5dU &&
              observed_warp_up[kGuardElements + kRows + index] == 0x6e6eU;
        }
        const bool inputs_preserved =
            observed_left == host_residual_left &&
            observed_right == host_residual_right &&
            observed_weight == host_norm_weight;
        const bool classification_gate =
            require_all_nan
                ? class_and_sign &&
                      classified_nan_outputs ==
                          (candidate_publishes_up ? 2U * kRows : kRows)
                : unexpected_nonfinite == 0U;
        const bool correctness_gate =
            residual_mismatches == 0U && final_mismatches == 0U &&
            (!candidate_publishes_up || up_mismatches == 0U) &&
            candidate_up_untouched && classification_gate && guards &&
            inputs_preserved;
        test.expect(correctness_gate,
                    fixture_label +
                        " direct shared-tree/warp-tail full-shape bitwise");
        std::cout
            << "NVFP4_M1_RESIDUAL_NORM_REDUCTION_DIRECT_EXACT_DIFF: fixture="
            << fixture_label << " candidate=" << candidate_name
            << " residual_mismatches="
            << residual_mismatches << '/' << kColumns
            << " final_gate_mismatches=" << final_mismatches << '/' << kRows
            << " up_mismatches=" << up_mismatches << '/' << kRows
            << " unexpected_nonfinite=" << unexpected_nonfinite
            << " classified_nan_outputs=" << classified_nan_outputs << '/'
            << (candidate_publishes_up ? 2U * kRows : kRows)
            << " class_and_sign=" << (class_and_sign ? "true" : "false")
            << " up_publication="
            << (candidate_publishes_up ? "required" : "elided")
            << " dead_up_buffer_untouched="
            << (candidate_up_untouched ? "true" : "false")
            << " guards=" << (guards ? "intact" : "BAD")
            << " inputs_preserved="
            << (inputs_preserved ? "true" : "false")
            << " gate=" << (correctness_gate ? "PASS" : "FAIL") << '\n';
        return correctness_gate;
      };

  const auto benchmark_residual_norm =
      [&](const std::string& fixture_label) {
        NvFp4GateUpSiluFusionTiming timing{};
        bool timing_ready = true;
        for (int iteration = 0;
             iteration < kWarmupIterations && timing_ready; ++iteration) {
          timing_ready = test.cuda_ok(
              static_cast<cudaError_t>(launch_residual_norm_baseline()),
              fixture_label + " residual baseline warmup");
          timing_ready = timing_ready && test.cuda_ok(
              static_cast<cudaError_t>(launch_residual_norm_candidate()),
              fixture_label + " residual candidate warmup");
        }
        timing_ready = timing_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            fixture_label + " residual warmup synchronize");
        if (!timing_ready) {
          return timing;
        }
        constexpr std::size_t kPasses =
            2U * static_cast<std::size_t>(kMeasurementRounds);
        std::array<float, kPasses> baseline_passes{};
        std::array<float, kPasses> candidate_passes{};
        bool finite = true;
        for (int round = 0; round < kMeasurementRounds; ++round) {
          const std::string round_label =
              fixture_label + " residual round=" +
              std::to_string(round + 1);
          const float b1 = measure_small_m_tile(
              test, stream, launch_residual_norm_baseline,
              kMeasuredIterations, round_label + " B1");
          const float c1 = measure_small_m_tile(
              test, stream, launch_residual_norm_candidate,
              kMeasuredIterations, round_label + " C1");
          const float c2 = measure_small_m_tile(
              test, stream, launch_residual_norm_candidate,
              kMeasuredIterations, round_label + " C2");
          const float b2 = measure_small_m_tile(
              test, stream, launch_residual_norm_baseline,
              kMeasuredIterations, round_label + " B2");
          const std::size_t pass = 2U * static_cast<std::size_t>(round);
          baseline_passes[pass] = b1;
          baseline_passes[pass + 1U] = b2;
          candidate_passes[pass] = c1;
          candidate_passes[pass + 1U] = c2;
          finite = finite && std::isfinite(b1) && std::isfinite(c1) &&
                   std::isfinite(c2) && std::isfinite(b2);
          std::cout << "PERF_NVFP4_M1_RESIDUAL_NORM_GATE_UP_SILU_ROUND: "
                    << "fixture=" << fixture_label << " round=" << round + 1
                    << " order=B-C-C-B iterations=64"
                    << " baseline1_ms=" << b1 << " candidate1_ms=" << c1
                    << " candidate2_ms=" << c2 << " baseline2_ms=" << b2
                    << '\n';
        }
        if (!finite) {
          return timing;
        }
        timing.baseline_milliseconds =
            median_fp8_kv_pair_timing(baseline_passes);
        timing.candidate_milliseconds =
            median_fp8_kv_pair_timing(candidate_passes);
        return timing;
      };

  // Isolate the reduction change inside the otherwise-identical single
  // kernel. B is the preserved all-shared tree and C is the retained 64x256
  // shared-prefix/warp-tail predecessor; symmetric order limits drift bias.
  const auto benchmark_residual_norm_reduction_direct =
      [&](const std::string& fixture_label) {
        NvFp4GateUpSiluFusionTiming timing{};
        bool timing_ready = true;
        for (int iteration = 0;
             iteration < kWarmupIterations && timing_ready; ++iteration) {
          timing_ready = test.cuda_ok(
              static_cast<cudaError_t>(launch_residual_norm_shared_tree()),
              fixture_label + " direct shared-tree warmup");
          timing_ready = timing_ready && test.cuda_ok(
              static_cast<cudaError_t>(launch_residual_norm_predecessor()),
              fixture_label + " direct warp-tail warmup");
        }
        timing_ready = timing_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            fixture_label + " direct reduction warmup synchronize");
        if (!timing_ready) {
          return timing;
        }
        constexpr std::size_t kPasses =
            2U * static_cast<std::size_t>(kMeasurementRounds);
        std::array<float, kPasses> shared_tree_passes{};
        std::array<float, kPasses> warp_tail_passes{};
        bool finite = true;
        for (int round = 0; round < kMeasurementRounds; ++round) {
          const std::string round_label =
              fixture_label + " direct reduction round=" +
              std::to_string(round + 1);
          const float b1 = measure_small_m_tile(
              test, stream, launch_residual_norm_shared_tree,
              kMeasuredIterations, round_label + " B1 shared-tree");
          const float c1 = measure_small_m_tile(
              test, stream, launch_residual_norm_predecessor,
              kMeasuredIterations, round_label + " C1 warp-tail");
          const float c2 = measure_small_m_tile(
              test, stream, launch_residual_norm_predecessor,
              kMeasuredIterations, round_label + " C2 warp-tail");
          const float b2 = measure_small_m_tile(
              test, stream, launch_residual_norm_shared_tree,
              kMeasuredIterations, round_label + " B2 shared-tree");
          const std::size_t pass = 2U * static_cast<std::size_t>(round);
          shared_tree_passes[pass] = b1;
          shared_tree_passes[pass + 1U] = b2;
          warp_tail_passes[pass] = c1;
          warp_tail_passes[pass + 1U] = c2;
          finite = finite && std::isfinite(b1) && std::isfinite(c1) &&
                   std::isfinite(c2) && std::isfinite(b2);
          std::cout
              << "PERF_NVFP4_M1_RESIDUAL_NORM_REDUCTION_DIRECT_ROUND: "
              << "fixture=" << fixture_label << " round=" << round + 1
              << " order=B-C-C-B iterations=64"
              << " shared_tree1_ms=" << b1 << " warp_tail1_ms=" << c1
              << " warp_tail2_ms=" << c2 << " shared_tree2_ms=" << b2
              << '\n';
        }
        if (!finite) {
          return timing;
        }
        timing.baseline_milliseconds =
            median_fp8_kv_pair_timing(shared_tree_passes);
        timing.candidate_milliseconds =
            median_fp8_kv_pair_timing(warp_tail_passes);
        return timing;
      };

  // Compare the retained 64x256 predecessor directly with the public 32x512
  // production kernel. Both retain 512 total projection warps and 32 resident
  // warps/SM; only the repeated CTA setup count changes.
  const auto benchmark_residual_norm_cta_coarsen =
      [&](const std::string& fixture_label) {
        NvFp4GateUpCtaCoarsenTiming timing{};
        bool timing_ready = true;
        for (int iteration = 0;
             iteration < kWarmupIterations && timing_ready; ++iteration) {
          timing_ready = test.cuda_ok(
              static_cast<cudaError_t>(launch_residual_norm_predecessor()),
              fixture_label + " CTA coarsen predecessor warmup");
          timing_ready = timing_ready && test.cuda_ok(
              static_cast<cudaError_t>(launch_residual_norm_candidate()),
              fixture_label + " CTA coarsen production warmup");
        }
        timing_ready = timing_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            fixture_label + " CTA coarsen warmup synchronize");
        if (!timing_ready) {
          return timing;
        }
        constexpr std::size_t kPasses =
            2U * static_cast<std::size_t>(kMeasurementRounds);
        std::array<float, kPasses> predecessor_passes{};
        std::array<float, kPasses> production_passes{};
        bool finite = true;
        for (int round = 0; round < kMeasurementRounds; ++round) {
          const std::string round_label =
              fixture_label + " CTA coarsen round=" +
              std::to_string(round + 1);
          const float b1 = measure_small_m_tile(
              test, stream, launch_residual_norm_predecessor,
              kMeasuredIterations, round_label + " B1 predecessor");
          const float c1 = measure_small_m_tile(
              test, stream, launch_residual_norm_candidate,
              kMeasuredIterations, round_label + " C1 production 32x512");
          const float c2 = measure_small_m_tile(
              test, stream, launch_residual_norm_candidate,
              kMeasuredIterations, round_label + " C2 production 32x512");
          const float b2 = measure_small_m_tile(
              test, stream, launch_residual_norm_predecessor,
              kMeasuredIterations, round_label + " B2 predecessor");
          const std::size_t pass = 2U * static_cast<std::size_t>(round);
          predecessor_passes[pass] = b1;
          predecessor_passes[pass + 1U] = b2;
          production_passes[pass] = c1;
          production_passes[pass + 1U] = c2;
          const float paired_speedup = (b1 + b2) / (c1 + c2);
          timing.paired_round_speedups[static_cast<std::size_t>(round)] =
              paired_speedup;
          finite = finite && std::isfinite(b1) && std::isfinite(c1) &&
                   std::isfinite(c2) && std::isfinite(b2) &&
                   std::isfinite(paired_speedup);
          std::cout << "PERF_NVFP4_M1_GATE_UP_CTA_COARSEN_ROUND: fixture="
                    << fixture_label << " round=" << round + 1
                    << " order=B-C-C-B iterations=64"
                    << " predecessor1_ms=" << b1
                    << " production1_ms=" << c1
                    << " production2_ms=" << c2
                    << " predecessor2_ms=" << b2
                    << " paired_speedup=" << paired_speedup << '\n';
        }
        if (!finite) {
          return timing;
        }
        timing.predecessor_pass_median_milliseconds =
            median_fp8_kv_pair_timing(predecessor_passes);
        timing.production_pass_median_milliseconds =
            median_fp8_kv_pair_timing(production_passes);
        timing.paired_round_median_speedup =
            median_fp8_kv_pair_timing(timing.paired_round_speedups);
        return timing;
      };

  // Isolate the runner-only dead-up contract against the public production
  // 32x512 kernel. Both retain the same projection and balanced CTA epilogue;
  // C keeps the rounded gate/up pair in shared memory and leaves up_output
  // untouched because the Decode runner overwrites that buffer next.
  const auto benchmark_residual_norm_dead_up =
      [&](const std::string& fixture_label) {
        NvFp4GateUpDeadUpTiming timing{};
        bool timing_ready = true;
        for (int iteration = 0;
             iteration < kWarmupIterations && timing_ready; ++iteration) {
          timing_ready = test.cuda_ok(
              static_cast<cudaError_t>(launch_residual_norm_candidate()),
              fixture_label + " dead-up production warmup");
          timing_ready = timing_ready && test.cuda_ok(
              static_cast<cudaError_t>(
                  launch_residual_norm_dead_up_candidate()),
              fixture_label + " dead-up candidate warmup");
        }
        timing_ready = timing_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            fixture_label + " dead-up warmup synchronize");
        if (!timing_ready) {
          return timing;
        }
        constexpr std::size_t kPasses =
            2U * static_cast<std::size_t>(kMeasurementRounds);
        std::array<float, kPasses> production_passes{};
        std::array<float, kPasses> candidate_passes{};
        bool finite = true;
        for (int round = 0; round < kMeasurementRounds; ++round) {
          const std::string round_label =
              fixture_label + " dead-up round=" +
              std::to_string(round + 1);
          const float b1 = measure_small_m_tile(
              test, stream, launch_residual_norm_candidate,
              kMeasuredIterations, round_label + " B1 production");
          const float c1 = measure_small_m_tile(
              test, stream, launch_residual_norm_dead_up_candidate,
              kMeasuredIterations, round_label + " C1 dead-up");
          const float c2 = measure_small_m_tile(
              test, stream, launch_residual_norm_dead_up_candidate,
              kMeasuredIterations, round_label + " C2 dead-up");
          const float b2 = measure_small_m_tile(
              test, stream, launch_residual_norm_candidate,
              kMeasuredIterations, round_label + " B2 production");
          const std::size_t pass = 2U * static_cast<std::size_t>(round);
          production_passes[pass] = b1;
          production_passes[pass + 1U] = b2;
          candidate_passes[pass] = c1;
          candidate_passes[pass + 1U] = c2;
          const float paired_speedup = (b1 + b2) / (c1 + c2);
          timing.paired_round_speedups[static_cast<std::size_t>(round)] =
              paired_speedup;
          finite = finite && std::isfinite(b1) && std::isfinite(c1) &&
                   std::isfinite(c2) && std::isfinite(b2) &&
                   std::isfinite(paired_speedup);
          std::cout << "PERF_NVFP4_M1_GATE_UP_DEAD_UP_ROUND: fixture="
                    << fixture_label << " round=" << round + 1
                    << " order=B-C-C-B iterations=64"
                    << " production1_ms=" << b1
                    << " dead_up1_ms=" << c1
                    << " dead_up2_ms=" << c2
                    << " production2_ms=" << b2
                    << " paired_speedup=" << paired_speedup << '\n';
        }
        if (!finite) {
          return timing;
        }
        timing.production_pass_median_milliseconds =
            median_fp8_kv_pair_timing(production_passes);
        timing.candidate_pass_median_milliseconds =
            median_fp8_kv_pair_timing(candidate_passes);
        timing.paired_round_median_speedup =
            median_fp8_kv_pair_timing(timing.paired_round_speedups);
        return timing;
      };

  const auto benchmark_residual_norm_dead_up_cs =
      [&](const std::string& fixture_label) {
        NvFp4GateUpDeadUpTiming timing{};
        bool timing_ready = true;
        for (int iteration = 0;
             iteration < kWarmupIterations && timing_ready; ++iteration) {
          timing_ready = test.cuda_ok(
              static_cast<cudaError_t>(
                  launch_residual_norm_dead_up_default_rollback()),
              fixture_label + " default rollback baseline warmup");
          timing_ready = timing_ready && test.cuda_ok(
              static_cast<cudaError_t>(
                  launch_residual_norm_dead_up_candidate()),
              fixture_label + " public selected candidate warmup");
        }
        timing_ready = timing_ready && test.cuda_ok(
            cudaStreamSynchronize(stream),
            fixture_label + " cache-policy warmup synchronize");
        if (!timing_ready) {
          return timing;
        }
        const float prime_b1 = measure_small_m_tile(
            test, stream, launch_residual_norm_dead_up_default_rollback,
            kMeasuredIterations, fixture_label + " default prime B1");
        const float prime_c1 = measure_small_m_tile(
            test, stream, launch_residual_norm_dead_up_candidate,
            kMeasuredIterations, fixture_label + " public prime C1");
        const float prime_c2 = measure_small_m_tile(
            test, stream, launch_residual_norm_dead_up_candidate,
            kMeasuredIterations, fixture_label + " public prime C2");
        const float prime_b2 = measure_small_m_tile(
            test, stream, launch_residual_norm_dead_up_default_rollback,
            kMeasuredIterations, fixture_label + " default prime B2");
        if (!std::isfinite(prime_b1) || !std::isfinite(prime_c1) ||
            !std::isfinite(prime_c2) || !std::isfinite(prime_b2)) {
          return timing;
        }
        constexpr std::size_t kPasses =
            2U * static_cast<std::size_t>(kMeasurementRounds);
        std::array<float, kPasses> production_passes{};
        std::array<float, kPasses> candidate_passes{};
        bool finite = true;
        for (int round = 0; round < kMeasurementRounds; ++round) {
          const std::string round_label =
              fixture_label + " streaming round=" +
              std::to_string(round + 1);
          const bool baseline_outer = round % 2 == 0;
          float b1 = 0.0F;
          float b2 = 0.0F;
          float c1 = 0.0F;
          float c2 = 0.0F;
          if (baseline_outer) {
            b1 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_default_rollback,
                kMeasuredIterations, round_label + " B1 default");
            c1 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_candidate,
                kMeasuredIterations, round_label + " C1 public");
            c2 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_candidate,
                kMeasuredIterations, round_label + " C2 public");
            b2 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_default_rollback,
                kMeasuredIterations, round_label + " B2 default");
          } else {
            c1 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_candidate,
                kMeasuredIterations, round_label + " C1 public");
            b1 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_default_rollback,
                kMeasuredIterations, round_label + " B1 default");
            b2 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_default_rollback,
                kMeasuredIterations, round_label + " B2 default");
            c2 = measure_small_m_tile(
                test, stream, launch_residual_norm_dead_up_candidate,
                kMeasuredIterations, round_label + " C2 public");
          }
          const std::size_t pass = 2U * static_cast<std::size_t>(round);
          production_passes[pass] = b1;
          production_passes[pass + 1U] = b2;
          candidate_passes[pass] = c1;
          candidate_passes[pass + 1U] = c2;
          const float paired_speedup = (b1 + b2) / (c1 + c2);
          const float paired_delta_milliseconds =
              0.5F * ((b1 + b2) - (c1 + c2));
          timing.paired_round_speedups[static_cast<std::size_t>(round)] =
              paired_speedup;
          timing.paired_round_deltas_milliseconds
              [static_cast<std::size_t>(round)] =
                  paired_delta_milliseconds;
          finite = finite && std::isfinite(b1) && std::isfinite(c1) &&
                   std::isfinite(c2) && std::isfinite(b2) &&
                   std::isfinite(paired_speedup) &&
                   std::isfinite(paired_delta_milliseconds);
          std::cout << "PERF_DECODE_GATE_UP_CS_CLOSEOUT_ROUND: fixture="
                    << fixture_label << " round=" << round + 1
                    << " order="
                    << (baseline_outer ? "B-C-C-B" : "C-B-B-C")
                    << " iterations=64"
                    << " baseline1_ms=" << b1
                    << " candidate1_ms=" << c1
                    << " candidate2_ms=" << c2
                    << " baseline2_ms=" << b2
                    << " paired_speedup=" << paired_speedup
                    << " paired_delta_ms=" << paired_delta_milliseconds
                    << '\n';
        }
        if (!finite) {
          return timing;
        }
        timing.production_pass_median_milliseconds =
            median_fp8_kv_pair_timing(production_passes);
        timing.candidate_pass_median_milliseconds =
            median_fp8_kv_pair_timing(candidate_passes);
        timing.paired_round_median_speedup =
            median_fp8_kv_pair_timing(timing.paired_round_speedups);
        return timing;
      };

  std::array<NvFp4GateUpSiluFusionTiming, 2U> timings{};
  std::array<bool, 2U> correctness{};
  std::array<NvFp4GateUpSiluFusionTiming, 2U> residual_norm_timings{};
  std::array<NvFp4GateUpSiluFusionTiming, 2U>
      residual_norm_reduction_direct_timings{};
  std::array<bool, 2U> residual_norm_correctness{};
  std::array<bool, 2U> residual_norm_reduction_direct_correctness{};
  bool residual_norm_reduction_direct_nonfinite_correctness = false;
  std::array<NvFp4GateUpCtaCoarsenTiming, 2U>
      residual_norm_cta_coarsen_timings{};
  std::array<bool, 2U> residual_norm_cta_coarsen_correctness{};
  bool residual_norm_cta_coarsen_nonfinite_correctness = false;
  std::array<NvFp4GateUpDeadUpTiming, 2U> residual_norm_dead_up_timings{};
  std::array<bool, 2U> residual_norm_dead_up_correctness{};
  bool residual_norm_dead_up_nonfinite_correctness = false;
  std::array<NvFp4GateUpDeadUpTiming, 2U>
      residual_norm_dead_up_cs_timings{};
  std::array<bool, 2U> residual_norm_dead_up_default_correctness{};
  bool residual_norm_dead_up_default_nonfinite_correctness = false;
  for (std::size_t fixture = 0U; fixture < 2U; ++fixture) {
    const bool actual = fixture == 0U;
    if (!actual) {
      for (std::size_t index = 0U; index < kPackedCount; ++index) {
        const std::uint8_t gate_low = static_cast<std::uint8_t>(
            (index * 5U + (index >> 3U) * 3U + 1U) & 0x0fU);
        const std::uint8_t gate_high = static_cast<std::uint8_t>(
            (index * 7U + (index >> 2U) * 5U + 9U) & 0x0fU);
        const std::uint8_t up_low = static_cast<std::uint8_t>(
            (index * 11U + (index >> 4U) * 7U + 3U) & 0x0fU);
        const std::uint8_t up_high = static_cast<std::uint8_t>(
            (index * 13U + (index >> 1U) * 3U + 5U) & 0x0fU);
        host_gate_packed[index] =
            static_cast<std::uint8_t>(gate_low | (gate_high << 4U));
        host_up_packed[index] =
            static_cast<std::uint8_t>(up_low | (up_high << 4U));
      }
      fill_nvfp4_m1_exact_shape_scale_distribution(
          host_gate_scales, kScaleColumns,
          NvFp4M1ScaleDistribution::kSameBankStress);
      fill_nvfp4_m1_exact_shape_scale_distribution(
          host_up_scales, kScaleColumns,
          NvFp4M1ScaleDistribution::kSameBankStress);
      std::rotate(host_up_scales.begin(), host_up_scales.begin() + 1U,
                  host_up_scales.end());
    }
    const std::string fixture_name =
        actual ? "actual_checkpoint" : "same_bank_stress";
    const std::string fixture_label = label + " " + fixture_name;
    std::cout << "NVFP4_M1_GATE_UP_SILU_FIXTURE: fixture=" << fixture_name
              << " gate_weight_sha256=" << hash_bytes(host_gate_packed)
              << " up_weight_sha256=" << hash_bytes(host_up_packed)
              << " gate_scale_sha256=" << hash_bytes(host_gate_scales)
              << " up_scale_sha256=" << hash_bytes(host_up_scales)
              << " activation_sha256=" << activation_hash << '\n';
    if (!upload_fixture(fixture_label)) {
      return;
    }
    correctness[fixture] = check_correctness(fixture_label);
    timings[fixture] = benchmark(fixture_label);
    residual_norm_correctness[fixture] =
        check_residual_norm_correctness(
            fixture_label, launch_residual_norm_candidate,
            "production_32x512");
    residual_norm_cta_coarsen_correctness[fixture] =
        check_residual_norm_correctness(
            fixture_label, launch_residual_norm_predecessor,
            "predecessor_64x256") &&
        residual_norm_correctness[fixture];
    residual_norm_dead_up_correctness[fixture] =
        check_residual_norm_correctness(
            fixture_label, launch_residual_norm_dead_up_candidate,
            "production_runner_dead_up_shared_pair", false);
    if (decode_gate_up_cs_performance_enabled()) {
      residual_norm_dead_up_default_correctness[fixture] =
          check_residual_norm_correctness(
              fixture_label, launch_residual_norm_dead_up_default_rollback,
              "default_rollback_runner_dead_up", false);
    }
    residual_norm_reduction_direct_correctness[fixture] =
        check_residual_norm_reduction_direct_correctness(
            fixture_label + " finite", false,
            launch_residual_norm_predecessor, "predecessor_64x256");
    residual_norm_timings[fixture] =
        benchmark_residual_norm(fixture_label);
    residual_norm_reduction_direct_timings[fixture] =
        benchmark_residual_norm_reduction_direct(fixture_label);
    residual_norm_cta_coarsen_timings[fixture] =
        benchmark_residual_norm_cta_coarsen(fixture_label);
    residual_norm_dead_up_timings[fixture] =
        benchmark_residual_norm_dead_up(fixture_label);
    if (decode_gate_up_cs_performance_enabled()) {
      residual_norm_dead_up_cs_timings[fixture] =
          benchmark_residual_norm_dead_up_cs(fixture_label);
    }
    if (actual) {
      const std::vector<std::uint16_t> finite_residual_left =
          host_residual_left;
      const std::vector<std::uint16_t> finite_residual_right =
          host_residual_right;
      const std::vector<std::uint16_t> finite_norm_weight = host_norm_weight;
      host_residual_left[0U] = 0x7f80U;
      host_residual_right[0U] = 0xff80U;
      host_residual_left[1U] = 0x7fc1U;
      host_residual_right[2U] = 0xffc1U;
      host_norm_weight[3U] = 0x7f80U;
      host_norm_weight[4U] = 0xff80U;
      const std::string nonfinite_label =
          fixture_label + " signed_inf_nan";
      residual_norm_reduction_direct_nonfinite_correctness =
          upload_residual_fixture(nonfinite_label) &&
          check_residual_norm_reduction_direct_correctness(
              nonfinite_label, true, launch_residual_norm_predecessor,
              "predecessor_64x256");
      residual_norm_cta_coarsen_nonfinite_correctness =
          upload_residual_fixture(nonfinite_label) &&
          check_residual_norm_reduction_direct_correctness(
              nonfinite_label, true, launch_residual_norm_candidate,
              "production_32x512");
      residual_norm_dead_up_nonfinite_correctness =
          upload_residual_fixture(nonfinite_label) &&
          check_residual_norm_reduction_direct_correctness(
              nonfinite_label, true,
              launch_residual_norm_dead_up_candidate,
              "production_runner_dead_up_shared_pair", false);
      if (decode_gate_up_cs_performance_enabled()) {
        residual_norm_dead_up_default_nonfinite_correctness =
            upload_residual_fixture(nonfinite_label) &&
            check_residual_norm_reduction_direct_correctness(
                nonfinite_label, true,
                launch_residual_norm_dead_up_default_rollback,
                "default_rollback_runner_dead_up", false);
      }
      host_residual_left = finite_residual_left;
      host_residual_right = finite_residual_right;
      host_norm_weight = finite_norm_weight;
    }
  }

  std::array<double, 2U> speedups{};
  bool timing_gate = true;
  bool exploratory_gate = true;
  for (std::size_t fixture = 0U; fixture < speedups.size(); ++fixture) {
    speedups[fixture] =
        static_cast<double>(timings[fixture].baseline_milliseconds) /
        static_cast<double>(timings[fixture].candidate_milliseconds);
    const double required =
        fixture == 0U ? kRequiredActualSpeedup : kRequiredStressSpeedup;
    const bool cell_gate = correctness[fixture] &&
                           std::isfinite(speedups[fixture]) &&
                           timings[fixture].baseline_milliseconds > 0.0F &&
                           timings[fixture].candidate_milliseconds > 0.0F &&
                           speedups[fixture] >= required;
    timing_gate = timing_gate && cell_gate;
    exploratory_gate = exploratory_gate && correctness[fixture] &&
                       std::isfinite(speedups[fixture]) &&
                       speedups[fixture] >= kExploratorySymmetricSpeedup;
    std::cout << "PERF_NVFP4_M1_GATE_UP_SILU: fixture="
              << (fixture == 0U ? "actual_checkpoint" : "same_bank_stress")
              << " baseline_two_single_plus_silu_median_ms="
              << timings[fixture].baseline_milliseconds
              << " public_fused_median_ms="
              << timings[fixture].candidate_milliseconds
              << " speedup=" << speedups[fixture]
              << " required_speedup=" << required
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  std::array<double, 2U> residual_norm_speedups{};
  bool residual_norm_timing_gate = true;
  for (std::size_t fixture = 0U; fixture < residual_norm_speedups.size();
       ++fixture) {
    residual_norm_speedups[fixture] =
        static_cast<double>(
            residual_norm_timings[fixture].baseline_milliseconds) /
        static_cast<double>(
            residual_norm_timings[fixture].candidate_milliseconds);
    const double required = fixture == 0U
                                ? kRequiredResidualNormActualSpeedup
                                : kRequiredStressSpeedup;
    const bool cell_gate =
        residual_norm_correctness[fixture] &&
        std::isfinite(residual_norm_speedups[fixture]) &&
        residual_norm_timings[fixture].baseline_milliseconds > 0.0F &&
        residual_norm_timings[fixture].candidate_milliseconds > 0.0F &&
        residual_norm_speedups[fixture] >= required;
    residual_norm_timing_gate = residual_norm_timing_gate && cell_gate;
    std::cout << "PERF_NVFP4_M1_RESIDUAL_NORM_GATE_UP_SILU: fixture="
              << (fixture == 0U ? "actual_checkpoint" : "same_bank_stress")
              << " baseline_public_two_kernel_median_ms="
              << residual_norm_timings[fixture].baseline_milliseconds
              << " candidate_single_kernel_median_ms="
              << residual_norm_timings[fixture].candidate_milliseconds
              << " speedup=" << residual_norm_speedups[fixture]
              << " required_speedup=" << required
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  std::array<double, 2U> residual_norm_reduction_direct_speedups{};
  bool residual_norm_reduction_direct_timing_gate = true;
  for (std::size_t fixture = 0U;
       fixture < residual_norm_reduction_direct_speedups.size(); ++fixture) {
    residual_norm_reduction_direct_speedups[fixture] =
        static_cast<double>(residual_norm_reduction_direct_timings[fixture]
                                .baseline_milliseconds) /
        static_cast<double>(residual_norm_reduction_direct_timings[fixture]
                                .candidate_milliseconds);
    const bool cell_gate =
        residual_norm_correctness[fixture] &&
        residual_norm_reduction_direct_correctness[fixture] &&
        std::isfinite(residual_norm_reduction_direct_speedups[fixture]) &&
        residual_norm_reduction_direct_timings[fixture]
                .baseline_milliseconds >
            0.0F &&
        residual_norm_reduction_direct_timings[fixture]
                .candidate_milliseconds >
            0.0F &&
        residual_norm_reduction_direct_speedups[fixture] >=
            kRequiredResidualNormReductionDirectSpeedup;
    residual_norm_reduction_direct_timing_gate =
        residual_norm_reduction_direct_timing_gate && cell_gate;
    std::cout << "PERF_NVFP4_M1_RESIDUAL_NORM_REDUCTION_DIRECT: fixture="
              << (fixture == 0U ? "actual_checkpoint" : "same_bank_stress")
              << " shared_tree_single_kernel_median_ms="
              << residual_norm_reduction_direct_timings[fixture]
                     .baseline_milliseconds
              << " warp_tail_single_kernel_median_ms="
              << residual_norm_reduction_direct_timings[fixture]
                     .candidate_milliseconds
              << " direct_speedup="
              << residual_norm_reduction_direct_speedups[fixture]
              << " required_speedup="
              << kRequiredResidualNormReductionDirectSpeedup
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  std::array<bool, 2U> residual_norm_cta_coarsen_cell_gates{};
  for (std::size_t fixture = 0U;
       fixture < residual_norm_cta_coarsen_timings.size(); ++fixture) {
    const NvFp4GateUpCtaCoarsenTiming& timing =
        residual_norm_cta_coarsen_timings[fixture];
    const double required_median =
        fixture == 0U ? kRequiredCtaCoarsenActualSpeedup
                      : kRequiredCtaCoarsenStressSpeedup;
    bool every_round_nonregression = true;
    for (const float round_speedup : timing.paired_round_speedups) {
      every_round_nonregression =
          every_round_nonregression && std::isfinite(round_speedup) &&
          static_cast<double>(round_speedup) >=
              kRequiredCtaCoarsenRoundSpeedup;
    }
    const bool cell_gate =
        residual_norm_cta_coarsen_correctness[fixture] &&
        std::isfinite(timing.predecessor_pass_median_milliseconds) &&
        std::isfinite(timing.production_pass_median_milliseconds) &&
        std::isfinite(timing.paired_round_median_speedup) &&
        timing.predecessor_pass_median_milliseconds > 0.0F &&
        timing.production_pass_median_milliseconds > 0.0F &&
        static_cast<double>(timing.paired_round_median_speedup) >=
            required_median &&
        every_round_nonregression;
    residual_norm_cta_coarsen_cell_gates[fixture] = cell_gate;
    std::cout << "PERF_NVFP4_M1_GATE_UP_CTA_COARSEN: fixture="
              << (fixture == 0U ? "actual_checkpoint" : "same_bank_stress")
              << " predecessor_64x256_pass_median_ms="
              << timing.predecessor_pass_median_milliseconds
              << " production_32x512_pass_median_ms="
              << timing.production_pass_median_milliseconds
              << " paired_round_median_speedup="
              << timing.paired_round_median_speedup
              << " required_median_speedup=" << required_median
              << " required_each_round_speedup="
              << kRequiredCtaCoarsenRoundSpeedup
              << " every_round_nonregression="
              << (every_round_nonregression ? "true" : "false")
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  const bool residual_norm_cta_coarsen_selected_gate =
      header_gate && pinned_payload_gate && coarsened_resource_gate &&
      residual_norm_cta_coarsen_cell_gates[0U] &&
      residual_norm_cta_coarsen_cell_gates[1U] &&
      residual_norm_cta_coarsen_nonfinite_correctness;
  std::cout << "PERF_NVFP4_M1_GATE_UP_CTA_COARSEN_SELECTED: "
            << "production=grid32_block512"
            << " predecessor=grid64_block256"
            << " shape=17408x5120 checkpoint_source=actual"
            << " actual_paired_median_speedup="
            << residual_norm_cta_coarsen_timings[0U]
                   .paired_round_median_speedup
            << " stress_paired_median_speedup="
            << residual_norm_cta_coarsen_timings[1U]
                   .paired_round_median_speedup
            << " required_actual_speedup="
            << kRequiredCtaCoarsenActualSpeedup
            << " required_stress_speedup="
            << kRequiredCtaCoarsenStressSpeedup
            << " required_each_round_speedup="
            << kRequiredCtaCoarsenRoundSpeedup
            << " resource_gate="
            << (coarsened_resource_gate ? "PASS" : "FAIL")
            << " finite_bitwise_replay_gate="
            << (residual_norm_cta_coarsen_correctness[0U] &&
                        residual_norm_cta_coarsen_correctness[1U]
                    ? "PASS"
                    : "FAIL")
            << " nonfinite_bitwise_gate="
            << (residual_norm_cta_coarsen_nonfinite_correctness ? "PASS"
                                                               : "FAIL")
            << " gate="
            << (residual_norm_cta_coarsen_selected_gate ? "PASS" : "FAIL")
            << '\n';
  test.expect(residual_norm_cta_coarsen_selected_gate,
              label + " 32x512 CTA coarsen clears frozen promotion gates");
  std::array<bool, 2U> residual_norm_dead_up_cell_gates{};
  for (std::size_t fixture = 0U;
       fixture < residual_norm_dead_up_timings.size(); ++fixture) {
    const NvFp4GateUpDeadUpTiming& timing =
        residual_norm_dead_up_timings[fixture];
    const double required_median =
        fixture == 0U ? kRequiredDeadUpActualSpeedup
                      : kRequiredDeadUpStressSpeedup;
    bool every_round_nonregression = true;
    for (const float round_speedup : timing.paired_round_speedups) {
      every_round_nonregression =
          every_round_nonregression && std::isfinite(round_speedup) &&
          static_cast<double>(round_speedup) >=
              kRequiredDeadUpRoundSpeedup;
    }
    const bool cell_gate =
        residual_norm_dead_up_correctness[fixture] &&
        std::isfinite(timing.production_pass_median_milliseconds) &&
        std::isfinite(timing.candidate_pass_median_milliseconds) &&
        std::isfinite(timing.paired_round_median_speedup) &&
        timing.production_pass_median_milliseconds > 0.0F &&
        timing.candidate_pass_median_milliseconds > 0.0F &&
        static_cast<double>(timing.paired_round_median_speedup) >=
            required_median &&
        every_round_nonregression;
    residual_norm_dead_up_cell_gates[fixture] = cell_gate;
    std::cout << "PERF_NVFP4_M1_GATE_UP_DEAD_UP: fixture="
              << (fixture == 0U ? "actual_checkpoint" : "same_bank_stress")
              << " production_32x512_pass_median_ms="
              << timing.production_pass_median_milliseconds
              << " dead_up_shared_pair_pass_median_ms="
              << timing.candidate_pass_median_milliseconds
              << " paired_round_median_speedup="
              << timing.paired_round_median_speedup
              << " required_median_speedup=" << required_median
              << " required_each_round_speedup="
              << kRequiredDeadUpRoundSpeedup
              << " every_round_nonregression="
              << (every_round_nonregression ? "true" : "false")
              << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
  }
  const bool residual_norm_dead_up_selected_gate =
      header_gate && pinned_payload_gate && dead_up_resource_gate &&
      residual_norm_dead_up_cell_gates[0U] &&
      residual_norm_dead_up_cell_gates[1U] &&
      residual_norm_dead_up_nonfinite_correctness;
  std::cout << "PERF_NVFP4_M1_GATE_UP_DEAD_UP_SELECTED: "
            << "candidate=production_runner_cta_local_gate_up_bf16"
            << " production=grid32_block512"
            << " candidate_grid=32 candidate_block=512"
            << " global_intermediate_gate_up_publications=0"
            << " dead_up_output_untouched=true"
            << " required_actual_speedup=" << kRequiredDeadUpActualSpeedup
            << " required_stress_speedup=" << kRequiredDeadUpStressSpeedup
            << " required_each_round_speedup="
            << kRequiredDeadUpRoundSpeedup
            << " resource_gate="
            << (dead_up_resource_gate ? "PASS" : "FAIL")
            << " finite_bitwise_replay_gate="
            << (residual_norm_dead_up_correctness[0U] &&
                        residual_norm_dead_up_correctness[1U]
                    ? "PASS"
                    : "FAIL")
            << " nonfinite_bitwise_gate="
            << (residual_norm_dead_up_nonfinite_correctness ? "PASS"
                                                            : "FAIL")
            << " gate="
            << (residual_norm_dead_up_selected_gate ? "PASS" : "FAIL")
            << '\n';
  test.expect(residual_norm_dead_up_selected_gate,
              label + " dead-up shared-pair clears frozen screen gates");
  if (decode_gate_up_cs_performance_enabled()) {
    std::array<bool, 2U> cache_policy_cell_gates{};
    for (std::size_t fixture = 0U;
         fixture < residual_norm_dead_up_cs_timings.size(); ++fixture) {
      const NvFp4GateUpDeadUpTiming& timing =
          residual_norm_dead_up_cs_timings[fixture];
      bool every_round_nonregression = true;
      for (const float round_speedup : timing.paired_round_speedups) {
        every_round_nonregression =
            every_round_nonregression && std::isfinite(round_speedup) &&
            static_cast<double>(round_speedup) >= 1.0;
      }
      const double required_median = fixture == 0U ? 1.005 : 1.0;
      const bool cell_gate =
          residual_norm_dead_up_correctness[fixture] &&
          residual_norm_dead_up_default_correctness[fixture] &&
          std::isfinite(timing.production_pass_median_milliseconds) &&
          std::isfinite(timing.candidate_pass_median_milliseconds) &&
          std::isfinite(timing.paired_round_median_speedup) &&
          timing.production_pass_median_milliseconds > 0.0F &&
          timing.candidate_pass_median_milliseconds > 0.0F &&
          static_cast<double>(timing.paired_round_median_speedup) >=
              required_median &&
          every_round_nonregression;
      cache_policy_cell_gates[fixture] = cell_gate;
      std::cout << "PERF_DECODE_GATE_UP_CS_CLOSEOUT: fixture="
                << (fixture == 0U ? "actual_checkpoint"
                                  : "same_bank_stress")
                << " baseline_pass_median_ms="
                << timing.production_pass_median_milliseconds
                << " candidate_pass_median_ms="
                << timing.candidate_pass_median_milliseconds
                << " paired_round_median_speedup="
                << timing.paired_round_median_speedup
                << " required_median_speedup=" << required_median
                << " required_each_round_speedup=1"
                << " every_round_nonregression="
                << (every_round_nonregression ? "true" : "false")
                << " gate=" << (cell_gate ? "PASS" : "FAIL") << '\n';
    }
    const double actual_delta_ms_per_layer = static_cast<double>(
        median_fp8_kv_pair_timing(
            residual_norm_dead_up_cs_timings[0U]
                .paired_round_deltas_milliseconds));
    const double projected_delta_ms_per_token =
        64.0 * actual_delta_ms_per_layer;
    const bool absolute_delta_gate =
        std::isfinite(projected_delta_ms_per_token) &&
        projected_delta_ms_per_token >= 0.25;
    const bool cache_policy_selected_gate =
        header_gate && pinned_payload_gate && dead_up_resource_gate &&
        cache_policy_cell_gates[0U] && cache_policy_cell_gates[1U] &&
        residual_norm_dead_up_nonfinite_correctness &&
        residual_norm_dead_up_default_nonfinite_correctness &&
        absolute_delta_gate;
    std::cout << "PERF_DECODE_GATE_UP_CS_CLOSEOUT_SELECTED:"
              << " policy=packed_and_scale_cs"
              << " actual_paired_median_speedup="
              << residual_norm_dead_up_cs_timings[0U]
                     .paired_round_median_speedup
              << " stress_paired_median_speedup="
              << residual_norm_dead_up_cs_timings[1U]
                     .paired_round_median_speedup
              << " actual_delta_ms_per_layer="
              << actual_delta_ms_per_layer
              << " projected_64_layer_delta_ms="
              << projected_delta_ms_per_token
              << " required_projected_64_layer_delta_ms=0.25"
              << " finite_public_default_graph_replay_gate="
              << (residual_norm_dead_up_correctness[0U] &&
                          residual_norm_dead_up_correctness[1U] &&
                          residual_norm_dead_up_default_correctness[0U] &&
                          residual_norm_dead_up_default_correctness[1U]
                      ? "PASS"
                      : "FAIL")
              << " nonfinite_public_default_bitwise_gate="
              << (residual_norm_dead_up_nonfinite_correctness &&
                          residual_norm_dead_up_default_nonfinite_correctness
                      ? "PASS"
                      : "FAIL")
              << " gate="
              << (cache_policy_selected_gate ? "PASS" : "FAIL") << '\n';
    test.expect(cache_policy_selected_gate,
                label + " packed/scale streaming policy clears closeout");
  }
  const bool selected_gate =
      header_gate && pinned_payload_gate && resource_gate && timing_gate;
  std::cout << "PERF_NVFP4_M1_GATE_UP_SILU_SELECTED: candidate="
               "public_gate_up_silu_activation_staged"
            << " shape=17408x5120 checkpoint_source=actual"
            << " actual_speedup=" << speedups[0U]
            << " stress_speedup=" << speedups[1U]
            << " required_actual_speedup=" << kRequiredActualSpeedup
            << " required_stress_speedup=" << kRequiredStressSpeedup
            << " exploratory_symmetric_1p01_gate="
            << (exploratory_gate ? "PASS" : "FAIL")
            << " resource_gate=" << (resource_gate ? "PASS" : "FAIL")
            << " bitwise_gate="
            << (correctness[0U] && correctness[1U] ? "PASS" : "FAIL")
            << " gate=" << (selected_gate ? "PASS" : "FAIL") << '\n';
  test.expect(selected_gate,
              label + " clears actual-value/stress/resource/bitwise gates");
  const bool residual_norm_selected_gate =
      header_gate && pinned_payload_gate && resource_gate &&
      residual_norm_timing_gate && residual_norm_reduction_direct_timing_gate &&
      residual_norm_reduction_direct_nonfinite_correctness;
  std::cout << "PERF_NVFP4_M1_RESIDUAL_NORM_GATE_UP_SILU_SELECTED: "
            << "candidate=per_cta_redundant_norm_plus_gate_up_silu"
            << " shape=17408x5120 checkpoint_source=actual"
            << " actual_speedup=" << residual_norm_speedups[0U]
            << " stress_speedup=" << residual_norm_speedups[1U]
            << " reduction_direct_actual_speedup="
            << residual_norm_reduction_direct_speedups[0U]
            << " reduction_direct_stress_speedup="
            << residual_norm_reduction_direct_speedups[1U]
            << " required_reduction_direct_actual_speedup="
            << kRequiredResidualNormReductionDirectSpeedup
            << " required_reduction_direct_stress_speedup="
            << kRequiredResidualNormReductionDirectSpeedup
            << " required_actual_speedup="
            << kRequiredResidualNormActualSpeedup
            << " required_stress_speedup=" << kRequiredStressSpeedup
            << " resource_gate=" << (resource_gate ? "PASS" : "FAIL")
            << " bitwise_gate="
            << (residual_norm_correctness[0U] &&
                        residual_norm_correctness[1U] &&
                        residual_norm_reduction_direct_correctness[0U] &&
                        residual_norm_reduction_direct_correctness[1U]
                    ? "PASS"
                    : "FAIL")
            << " reduction_direct_nonfinite_gate="
            << (residual_norm_reduction_direct_nonfinite_correctness ? "PASS"
                                                                     : "FAIL")
            << " gate="
            << (residual_norm_selected_gate ? "PASS" : "FAIL") << '\n';
  test.expect(residual_norm_selected_gate,
              label + " residual/norm fusion clears promotion gates");
}

void run_nvfp4_m1_gate_up_activation_staged_probe(TestContext& test,
                                                   cudaStream_t stream) {
  NvFp4M1DownDualKernelResources baseline_resources{};
  NvFp4M1DownDualKernelResources candidate_resources{};
  bool ready = test.cuda_ok(
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_k5120_xor_dual_resources_test_cuda(
              &baseline_resources.registers_per_thread,
              &baseline_resources.static_shared_bytes,
              &baseline_resources.local_bytes,
              &baseline_resources.maximum_threads_per_block,
              &baseline_resources.active_blocks_per_sm)),
      "query NVFP4 M1 gate/up direct-XOR baseline resources");
  ready = ready && test.cuda_ok(
                       static_cast<cudaError_t>(q3x::kernels::
                           query_sm87_nvfp4_w4a16_m1_gate_up_activation_staged_resources_test_cuda(
                               &candidate_resources.registers_per_thread,
                               &candidate_resources.static_shared_bytes,
                               &candidate_resources.local_bytes,
                               &candidate_resources.maximum_threads_per_block,
                               &candidate_resources.active_blocks_per_sm)),
                       "query NVFP4 M1 gate/up activation-staged resources");
  const bool null_rejected =
      static_cast<cudaError_t>(q3x::kernels::
          query_sm87_nvfp4_w4a16_m1_gate_up_activation_staged_resources_test_cuda(
              nullptr, &candidate_resources.static_shared_bytes,
              &candidate_resources.local_bytes,
              &candidate_resources.maximum_threads_per_block,
              &candidate_resources.active_blocks_per_sm)) ==
      cudaErrorInvalidValue;
  test.expect(
      null_rejected,
      "NVFP4 M1 gate/up activation-staged resource query rejects null");
  constexpr std::size_t kExpectedMaximumSharedBytes =
      5'120U * sizeof(std::uint16_t) + 1'088U;
  const bool resource_gate =
      ready && baseline_resources.registers_per_thread <= 64 &&
      baseline_resources.static_shared_bytes <= 1'088U &&
      baseline_resources.local_bytes == 0U &&
      baseline_resources.maximum_threads_per_block >= 256 &&
      baseline_resources.active_blocks_per_sm >= 4 &&
      candidate_resources.registers_per_thread <= 64 &&
      candidate_resources.static_shared_bytes <= kExpectedMaximumSharedBytes &&
      candidate_resources.local_bytes == 0U &&
      candidate_resources.maximum_threads_per_block >= 256 &&
      candidate_resources.active_blocks_per_sm >= 4;
  test.expect(resource_gate,
              "NVFP4 M1 gate/up activation-staged clears "
              "64r/11328B/0local/active4 gate");
  std::cout << "PERF_NVFP4_M1_GATE_UP_ACTIVATION_STAGED_RESOURCES: "
            << "baseline_registers_per_thread="
            << baseline_resources.registers_per_thread
            << " baseline_static_shared_bytes="
            << baseline_resources.static_shared_bytes
            << " baseline_local_bytes=" << baseline_resources.local_bytes
            << " baseline_maximum_threads_per_block="
            << baseline_resources.maximum_threads_per_block
            << " baseline_active_blocks_per_sm="
            << baseline_resources.active_blocks_per_sm
            << " candidate_registers_per_thread="
            << candidate_resources.registers_per_thread
            << " candidate_static_shared_bytes="
            << candidate_resources.static_shared_bytes
            << " candidate_local_bytes=" << candidate_resources.local_bytes
            << " candidate_maximum_threads_per_block="
            << candidate_resources.maximum_threads_per_block
            << " candidate_active_blocks_per_sm="
            << candidate_resources.active_blocks_per_sm
            << " gate=" << (resource_gate ? "PASS" : "FAIL") << '\n';
  if (!ready) {
    return;
  }

  // Capture-only probes exercise the production-sized selector on every
  // default test run without allocating or executing the 45-MiB weight
  // fixture. Kernel arguments are opaque during capture, so aligned,
  // non-overlapping sentinel addresses are sufficient for these captures.
  const auto* const fake_packed =
      reinterpret_cast<const std::uint8_t*>(0x1'0000'0000ULL);
  const auto* const fake_scales =
      reinterpret_cast<const std::uint8_t*>(0x2'0000'0000ULL);
  const auto* const fake_activation =
      reinterpret_cast<const std::uint16_t*>(0x3'0000'0000ULL);
  auto* const fake_output =
      reinterpret_cast<std::uint16_t*>(0x4'0000'0000ULL);
  const auto capture_single_kernel =
      [&](const auto& launch, const std::string& capture_label,
          cudaKernelNodeParams* const captured_params) {
        cudaGraph_t graph = nullptr;
        bool capture_ready = test.cuda_ok(
            cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
            capture_label + " begin capture");
        if (capture_ready) {
          capture_ready =
              test.cuda_ok(static_cast<cudaError_t>(launch()),
                           capture_label + " capture launch") &&
              capture_ready;
          capture_ready =
              test.cuda_ok(cudaStreamEndCapture(stream, &graph),
                           capture_label + " end capture") &&
              capture_ready;
        }
        std::size_t node_count = 0U;
        if (capture_ready) {
          capture_ready = test.cuda_ok(
              cudaGraphGetNodes(graph, nullptr, &node_count),
              capture_label + " query node count");
        }
        if (capture_ready && node_count == 1U) {
          cudaGraphNode_t node = nullptr;
          std::size_t node_capacity = 1U;
          capture_ready = test.cuda_ok(
              cudaGraphGetNodes(graph, &node, &node_capacity),
              capture_label + " get kernel node");
          capture_ready =
              capture_ready && node_capacity == 1U &&
              test.cuda_ok(cudaGraphKernelNodeGetParams(node, captured_params),
                           capture_label + " get kernel params");
        }
        if (graph != nullptr) {
          capture_ready =
              test.cuda_ok(cudaGraphDestroy(graph),
                           capture_label + " destroy graph") &&
              capture_ready;
        }
        return capture_ready && node_count == 1U;
      };
  const auto same_launch_configuration =
      [](const cudaKernelNodeParams& first,
         const cudaKernelNodeParams& second) {
        return first.func == second.func &&
               first.gridDim.x == second.gridDim.x &&
               first.gridDim.y == second.gridDim.y &&
               first.gridDim.z == second.gridDim.z &&
               first.blockDim.x == second.blockDim.x &&
               first.blockDim.y == second.blockDim.y &&
               first.blockDim.z == second.blockDim.z &&
               first.sharedMemBytes == second.sharedMemBytes;
      };
  cudaKernelNodeParams public_exact_params{};
  cudaKernelNodeParams direct_exact_params{};
  const bool public_exact_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::launch_sm87_nvfp4_w4a16_gemv_bf16_cuda(
            fake_packed, fake_scales, 1.0F / 64.0F, fake_activation,
            17'408U, 5'120U, fake_output, static_cast<void*>(stream));
      },
      "NVFP4 M1 gate/up public exact staged", &public_exact_params);
  const bool direct_exact_captured = capture_single_kernel(
      [&]() noexcept {
        return q3x::kernels::
            launch_sm87_nvfp4_w4a16_gemv_bf16_gate_up_activation_staged_test_cuda(
                fake_packed, fake_scales, 1.0F / 64.0F, fake_activation,
                17'408U, 5'120U, fake_output, static_cast<void*>(stream));
      },
      "NVFP4 M1 gate/up direct exact staged", &direct_exact_params);
  const bool exact_dispatch_gate =
      public_exact_captured && direct_exact_captured &&
      same_launch_configuration(public_exact_params, direct_exact_params);
  test.expect(exact_dispatch_gate,
              "NVFP4 M1 gate/up exact public dispatch matches direct staged "
              "kernel and launch configuration");

  const auto verify_scalar_fallback_capture =
      [&](const std::uint8_t* const fallback_packed,
          const std::uint16_t* const fallback_activation,
          const std::string& fallback_label) {
        cudaKernelNodeParams public_fallback_params{};
        cudaKernelNodeParams direct_scalar_params{};
        const bool public_captured = capture_single_kernel(
            [&]() noexcept {
              return q3x::kernels::launch_sm87_nvfp4_w4a16_gemv_bf16_cuda(
                  fallback_packed, fake_scales, 1.0F / 64.0F,
                  fallback_activation, 17'408U, 5'120U, fake_output,
                  static_cast<void*>(stream));
            },
            fallback_label + " public", &public_fallback_params);
        const bool scalar_captured = capture_single_kernel(
            [&]() noexcept {
              return q3x::kernels::
                  launch_sm87_nvfp4_w4a16_gemv_bf16_scalar_test_cuda(
                      fallback_packed, fake_scales, 1.0F / 64.0F,
                      fallback_activation, 17'408U, 5'120U, fake_output,
                      static_cast<void*>(stream));
            },
            fallback_label + " direct scalar", &direct_scalar_params);
        return public_captured && scalar_captured &&
               same_launch_configuration(public_fallback_params,
                                         direct_scalar_params);
      };
  const bool packed_fallback_dispatch_gate = verify_scalar_fallback_capture(
      reinterpret_cast<const std::uint8_t*>(
          reinterpret_cast<std::uintptr_t>(fake_packed) + 1U),
      fake_activation,
      "NVFP4 M1 gate/up packed+1 fallback");
  const bool activation_fallback_dispatch_gate =
      verify_scalar_fallback_capture(
          fake_packed, reinterpret_cast<const std::uint16_t*>(
                           reinterpret_cast<std::uintptr_t>(fake_activation) +
                           2U),
          "NVFP4 M1 gate/up activation+2 fallback");
  const bool fallback_dispatch_gate = packed_fallback_dispatch_gate &&
                                      activation_fallback_dispatch_gate;
  test.expect(fallback_dispatch_gate,
              "NVFP4 M1 gate/up unaligned public dispatch selects the direct "
              "scalar launch configuration");
  std::cout << "NVFP4_M1_GATE_UP_ACTIVATION_STAGED_DEFAULT_GRAPH: "
            << "public_exact_nodes=1 direct_staged_nodes=1"
            << " exact_kernel_and_launch_identity="
            << (exact_dispatch_gate ? "true" : "false")
            << " packed_fallback_scalar_identity="
            << (packed_fallback_dispatch_gate ? "true" : "false")
            << " activation_fallback_scalar_identity="
            << (activation_fallback_dispatch_gate ? "true" : "false")
            << " gate="
            << (exact_dispatch_gate && fallback_dispatch_gate ? "PASS"
                                                               : "FAIL")
            << '\n';

  const bool lightweight_gate = run_nvfp4_m1_k5120_xor_dual_fixture(
      test, stream, 2'048U, 512U, false,
      NvFp4M1K5120XorDualProbe::kGateUpActivationStaged,
      "NVFP4 M1 gate/up direct-vs-staged lightweight 2048x512");
  if (!nvfp4_m1_gate_up_activation_staged_performance_enabled()) {
    std::cout
        << "SKIP: NVFP4 M1 gate/up activation-staged full segment; set "
           "Q3X_RUN_SM87_NVFP4_M1_GATE_UP_ACTIVATION_STAGED_PERF=1 to "
           "enable\n";
    return;
  }
  if (!resource_gate || !exact_dispatch_gate || !fallback_dispatch_gate ||
      !lightweight_gate) {
    test.expect(false,
                "NVFP4 M1 gate/up activation-staged full run requires "
                "resource, exact dispatch, fallback, and lightweight gates");
    return;
  }
  (void)run_nvfp4_m1_k5120_xor_dual_fixture(
      test, stream, 17'408U, 5'120U, true,
      NvFp4M1K5120XorDualProbe::kGateUpActivationStaged,
      "NVFP4 M1 gate/up direct-vs-staged exact 17408x5120");
}

