                                         cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_name + " residual");
    ready = ready && test.cuda_ok(
                         cudaMemcpyAsync(norm_weight.get(),
                                         actual_norm_weight.data(),
                                         kRows * sizeof(std::uint16_t),
                                         cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_name + " norm");
    ready = ready && poison_outputs(fixture_name);
    ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_baseline()),
                                  label + " launch " + fixture_name +
                                      " default rollback baseline");
    ready = ready && test.cuda_ok(static_cast<cudaError_t>(launch_candidate()),
                                  label + " launch " + fixture_name +
                                      " public selected candidate");
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " " + fixture_name +
                                      " correctness synchronize");
    ready = ready && copy_all_outputs(fixture_name);
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " " + fixture_name +
                                      " output-copy synchronize");
    if (!ready) {
      return;
    }
    const std::size_t raw_mismatches =
        mismatch_count(baseline_raw_host, candidate_raw_host);
    const std::size_t residual_mismatches =
        mismatch_count(baseline_residual_host, candidate_residual_host);
    const std::size_t norm_mismatches =
        mismatch_count(baseline_norm_host, candidate_norm_host);
    const bool baseline_guards =
        guards_intact(baseline_raw_host, 0xa1a1U) &&
        guards_intact(baseline_residual_host, 0xb2b2U) &&
        guards_intact(baseline_norm_host, 0xc3c3U);
    const bool candidate_guards =
        guards_intact(candidate_raw_host, 0xd4d4U) &&
        guards_intact(candidate_residual_host, 0xe5e5U) &&
        guards_intact(candidate_norm_host, 0xf6f6U);
    bool finite_outputs = true;
    for (std::size_t index = 0U; index < kRows; ++index) {
      const std::size_t guarded = kGuardElements + index;
      finite_outputs =
          finite_outputs &&
          (dead_raw_candidate || is_bf16_finite(candidate_raw_host[guarded])) &&
          is_bf16_finite(candidate_residual_host[guarded]) &&
          is_bf16_finite(candidate_norm_host[guarded]);
    }
    const std::vector<std::uint16_t> first_candidate_raw =
        candidate_raw_host;
    const std::vector<std::uint16_t> first_candidate_residual =
        candidate_residual_host;
    const std::vector<std::uint16_t> first_candidate_norm =
        candidate_norm_host;
    ready = launch_candidate_graph_replay(fixture_name);
    ready = ready && copy_candidate_outputs(fixture_name);
    ready = ready && test.cuda_ok(cudaStreamSynchronize(stream),
                                  label + " " + fixture_name +
                                      " replay synchronize");
    if (!ready) {
      return;
    }
    const std::size_t replay_mismatches =
        mismatch_count(first_candidate_raw, candidate_raw_host) +
        mismatch_count(first_candidate_residual, candidate_residual_host) +
        mismatch_count(first_candidate_norm, candidate_norm_host);
    const bool replay_guards =
        guards_intact(candidate_raw_host, 0xd4d4U) &&
        guards_intact(candidate_residual_host, 0xe5e5U) &&
        guards_intact(candidate_norm_host, 0xf6f6U);
    const bool input_gate = inputs_unchanged(
        *fixture.packed_values, *fixture.scale_values, host_activation,
        host_left,
        actual_norm_weight, fixture_name);
    const bool raw_contract_gate =
        dead_raw_candidate ? all_equal(first_candidate_raw, 0xd4d4U) &&
                                 all_equal(candidate_raw_host, 0xd4d4U)
                           : raw_mismatches == 0U;
    const bool correctness_gate =
        raw_contract_gate && residual_mismatches == 0U &&
        norm_mismatches == 0U && replay_mismatches == 0U &&
        baseline_guards && candidate_guards && replay_guards && input_gate &&
        finite_outputs;
    test.expect(correctness_gate,
                label + " " + fixture_name +
                    " preserves bits/replay/guards/inputs");
    std::cout << (dead_raw_candidate ? "DECODE_DOWN_DEAD_RAW_DIFF: fixture="
                                     : "DECODE_DOWN_CS_DIFF: fixture=")
              << fixture_name
              << " baseline="
              << (dead_raw_candidate ? "production_32x512"
                                     : "default_rollback_32x512")
              << " candidate="
              << (dead_raw_candidate ? "dead_raw_inline_residual_32x512"
                                     : "public_selected_cs_32x512")
              << " raw_mismatches=" << raw_mismatches << '/' << kRows
              << " candidate_raw_untouched="
              << (raw_contract_gate ? "true" : "false")
              << " residual_mismatches=" << residual_mismatches << '/'
              << kRows << " norm_mismatches=" << norm_mismatches << '/'
              << kRows << " replay_mismatches=" << replay_mismatches << '/'
              << 3U * kRows
              << " finite_outputs=" << (finite_outputs ? "true" : "false")
              << " guards="
              << (baseline_guards && candidate_guards && replay_guards
                      ? "intact"
                      : "BAD")
              << " inputs_preserved=" << (input_gate ? "true" : "false")
              << " gate=" << (correctness_gate ? "PASS" : "FAIL")
              << '\n';
    if (!correctness_gate) {
      return;
    }
    if (fixture_index == 0U) {
      finite_actual_baseline_residual = baseline_residual_host;
    }

    bool timing_ready = true;
    for (int iteration = 0;
         iteration < kWarmupIterations && timing_ready; ++iteration) {
      timing_ready = test.cuda_ok(
          static_cast<cudaError_t>(launch_timing_baseline()),
          label + " " + fixture_name + " default rollback warmup");
      timing_ready = timing_ready && test.cuda_ok(
                                         static_cast<cudaError_t>(
                                             launch_candidate()),
                                         label + " " + fixture_name +
                                             " public selected warmup");
    }
    timing_ready = timing_ready && test.cuda_ok(
                                         cudaStreamSynchronize(stream),
                                         label + " " + fixture_name +
                                             " warmup synchronize");
    if (!timing_ready) {
      return;
    }
    const float prime_b1 = measure_small_m_tile(
        test, stream, launch_timing_baseline, kMeasuredIterations,
        label + " " + fixture_name + " full prime B1");
    const float prime_c1 = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " " + fixture_name + " full prime C1");
    const float prime_c2 = measure_small_m_tile(
        test, stream, launch_candidate, kMeasuredIterations,
        label + " " + fixture_name + " full prime C2");
    const float prime_b2 = measure_small_m_tile(
        test, stream, launch_timing_baseline, kMeasuredIterations,
        label + " " + fixture_name + " full prime B2");
    const bool prime_gate =
        std::isfinite(prime_b1) && prime_b1 > 0.0F &&
        std::isfinite(prime_c1) && prime_c1 > 0.0F &&
        std::isfinite(prime_c2) && prime_c2 > 0.0F &&
        std::isfinite(prime_b2) && prime_b2 > 0.0F;
    test.expect(prime_gate,
                label + " " + fixture_name + " completes full prime");
    if (!prime_gate) {
      return;
    }
    std::array<float, 2U * kMeasurementRounds> baseline_passes{};
    std::array<float, 2U * kMeasurementRounds> candidate_passes{};
    std::array<float, kMeasurementRounds> paired_speedups{};
    std::array<float, kMeasurementRounds> paired_deltas{};
    bool every_round_nonregression = true;
    for (int round = 0; round < kMeasurementRounds; ++round) {
      const bool baseline_outer = (round % 2) == 0;
      const std::string round_label =
          label + " " + fixture_name + " round=" +
          std::to_string(round + 1);
      float b1 = 0.0F;
      float b2 = 0.0F;
      float c1 = 0.0F;
      float c2 = 0.0F;
      if (baseline_outer) {
        b1 = measure_small_m_tile(test, stream, launch_timing_baseline,
                                  kMeasuredIterations, round_label + " B1");
        c1 = measure_small_m_tile(test, stream, launch_candidate,
                                  kMeasuredIterations, round_label + " C1");
        c2 = measure_small_m_tile(test, stream, launch_candidate,
                                  kMeasuredIterations, round_label + " C2");
        b2 = measure_small_m_tile(test, stream, launch_timing_baseline,
                                  kMeasuredIterations, round_label + " B2");
      } else {
        c1 = measure_small_m_tile(test, stream, launch_candidate,
                                  kMeasuredIterations, round_label + " C1");
        b1 = measure_small_m_tile(test, stream, launch_timing_baseline,
                                  kMeasuredIterations, round_label + " B1");
        b2 = measure_small_m_tile(test, stream, launch_timing_baseline,
                                  kMeasuredIterations, round_label + " B2");
        c2 = measure_small_m_tile(test, stream, launch_candidate,
                                  kMeasuredIterations, round_label + " C2");
      }
      const float paired_speedup = (b1 + b2) / (c1 + c2);
      const float paired_delta = 0.5F * ((b1 + b2) - (c1 + c2));
      const bool finite =
          std::isfinite(b1) && b1 > 0.0F && std::isfinite(b2) && b2 > 0.0F &&
          std::isfinite(c1) && c1 > 0.0F && std::isfinite(c2) && c2 > 0.0F &&
          std::isfinite(paired_speedup) && std::isfinite(paired_delta);
      const bool round_gate =
          finite &&
          (dead_raw_candidate ? paired_speedup > 1.0F
                              : paired_speedup >= 1.0F);
      every_round_nonregression = every_round_nonregression && round_gate;
      const std::size_t pass = 2U * static_cast<std::size_t>(round);
      baseline_passes[pass] = b1;
      baseline_passes[pass + 1U] = b2;
      candidate_passes[pass] = c1;
      candidate_passes[pass + 1U] = c2;
      paired_speedups[static_cast<std::size_t>(round)] = paired_speedup;
      paired_deltas[static_cast<std::size_t>(round)] = paired_delta;
      std::cout << (dead_raw_candidate
                        ? "PERF_DECODE_DOWN_DEAD_RAW_ROUND: fixture="
                        : "PERF_DECODE_DOWN_CS_ROUND: fixture=")
                << fixture_name
                << " round=" << round + 1
                << " order="
                << (baseline_outer ? "B-C-C-B" : "C-B-B-C")
                << " iterations=" << kMeasuredIterations << " b1_ms=" << b1
                << " c1_ms=" << c1 << " c2_ms=" << c2
                << " b2_ms=" << b2
                << " paired_speedup=" << paired_speedup
                << " paired_delta_ms=" << paired_delta
                << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
    }
    const float baseline_median =
        median_fp8_kv_pair_timing(baseline_passes);
    const float candidate_median =
        median_fp8_kv_pair_timing(candidate_passes);
    const float paired_median = median_fp8_kv_pair_timing(paired_speedups);
    fixture_paired_medians[fixture_index] = paired_median;
    if (fixture_index == 0U) {
      actual_paired_deltas = paired_deltas;
    }
    const bool timing_gate =
        every_round_nonregression && std::isfinite(baseline_median) &&
        baseline_median > 0.0F && std::isfinite(candidate_median) &&
        candidate_median > 0.0F && std::isfinite(paired_median) &&
        paired_median >= fixture.required_median_speedup;
    fixture_gates[fixture_index] = correctness_gate && timing_gate;
    test.expect(fixture_gates[fixture_index],
                label + " " + fixture_name + " clears cache-policy gate");
    std::cout << (dead_raw_candidate
                      ? "PERF_DECODE_DOWN_DEAD_RAW: fixture="
                      : "PERF_DECODE_DOWN_CS: fixture=")
              << fixture_name
              << " baseline_pass_median_ms=" << baseline_median
              << " candidate_pass_median_ms=" << candidate_median
              << " paired_round_median_speedup=" << paired_median
              << " required_median_speedup="
              << fixture.required_median_speedup
              << " every_round_nonregression="
              << (every_round_nonregression ? "true" : "false")
              << " timing_outputs=shared_candidate_buffers"
              << " correctness=" << (correctness_gate ? "PASS" : "FAIL")
              << " gate="
              << (fixture_gates[fixture_index] ? "PASS" : "FAIL") << '\n';
    if (dead_raw_candidate && fixture_index == 0U) {
      dead_actual_projected_delta =
          64.0F * median_fp8_kv_pair_timing(actual_paired_deltas);
      dead_actual_absolute_gate =
          std::isfinite(dead_actual_projected_delta) &&
          dead_actual_projected_delta >= kRequiredProjectedDeltaMilliseconds;
      test.expect(dead_actual_absolute_gate,
                  label + " clears actual projected absolute delta gate");
      std::cout << "PERF_DECODE_DOWN_DEAD_RAW_ABSOLUTE_DELTA:"
                << " projected_64_layer_delta_ms="
                << dead_actual_projected_delta
                << " required_projected_64_layer_delta_ms="
                << kRequiredProjectedDeltaMilliseconds
                << " gate="
                << (dead_actual_absolute_gate ? "PASS" : "FAIL") << '\n';
      if (!fixture_gates[fixture_index] || !dead_actual_absolute_gate) {
        std::cout << "PERF_DECODE_DOWN_DEAD_RAW_STOP:"
                     " stage=process1_actual"
                     " reason=actual_relative_or_absolute_gate_failed"
                     " stress=SKIP nonfinite=SKIP gate=FAIL\n";
        return;
      }
    }
  }

  const float actual_delta_milliseconds_per_layer =
      median_fp8_kv_pair_timing(actual_paired_deltas);
  const float projected_delta_milliseconds_per_token =
      64.0F * actual_delta_milliseconds_per_layer;
  const bool absolute_delta_gate =
      std::isfinite(projected_delta_milliseconds_per_token) &&
      projected_delta_milliseconds_per_token >=
          kRequiredProjectedDeltaMilliseconds;
  if (!dead_raw_candidate) {
    test.expect(absolute_delta_gate,
                label + " clears projected 64-layer absolute delta gate");
    std::cout << "PERF_DECODE_DOWN_CS_ABSOLUTE_DELTA:"
              << " actual_delta_ms_per_layer="
              << actual_delta_milliseconds_per_layer
              << " projected_64_layer_delta_ms="
              << projected_delta_milliseconds_per_token
              << " required_projected_64_layer_delta_ms="
              << kRequiredProjectedDeltaMilliseconds
              << " gate=" << (absolute_delta_gate ? "PASS" : "FAIL")
              << '\n';
  }

  const auto guarded_at = [&](const std::vector<std::uint16_t>& values,
                              const std::size_t index) {
    return values[kGuardElements + index];
  };
  const auto run_nonfinite_fixture =
      [&](const std::vector<std::uint16_t>& activation_values,
          const std::vector<std::uint16_t>& left_values,
          const std::vector<std::uint16_t>& norm_values,
          const std::string& fixture, const auto& semantic_check) {
        bool fixture_ready = test.cuda_ok(
            cudaMemcpyAsync(packed.get(), actual_packed.data(), kPackedCount,
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture + " actual packed");
        fixture_ready = fixture_ready && test.cuda_ok(
                                             cudaMemcpyAsync(
                                                 activation.get(),
                                                 activation_values.data(),
                                                 kColumns * sizeof(std::uint16_t),
                                                 cudaMemcpyHostToDevice,
                                                 stream),
                                             label + " upload " + fixture +
                                                 " activation input");
        fixture_ready = fixture_ready && test.cuda_ok(
                                             cudaMemcpyAsync(
                                                 scales.get(),
                                                 actual_scales.data(),
                                                 kScaleCount,
                                                 cudaMemcpyHostToDevice,
                                                 stream),
                                             label + " upload " + fixture +
                                                 " actual scales");
        fixture_ready = fixture_ready && test.cuda_ok(
                                             cudaMemcpyAsync(
                                                 residual_left.get(),
                                                 left_values.data(),
                                                 kRows * sizeof(std::uint16_t),
                                                 cudaMemcpyHostToDevice,
                                                 stream),
                                             label + " upload " + fixture +
                                                 " residual input");
        fixture_ready = fixture_ready && test.cuda_ok(
                                             cudaMemcpyAsync(
                                                 norm_weight.get(),
                                                 norm_values.data(),
                                                 kRows * sizeof(std::uint16_t),
                                                 cudaMemcpyHostToDevice,
                                                 stream),
                                             label + " upload " + fixture +
                                                 " norm weight");
        fixture_ready = fixture_ready && poison_outputs(fixture);
        fixture_ready = fixture_ready && test.cuda_ok(
                                             static_cast<cudaError_t>(
                                                 launch_baseline()),
                                             label + " launch " + fixture +
                                                 " default rollback baseline");
        fixture_ready = fixture_ready && test.cuda_ok(
                                             static_cast<cudaError_t>(
                                                 launch_candidate()),
                                             label + " launch " + fixture +
                                                 " public selected candidate");
        fixture_ready = fixture_ready && test.cuda_ok(
                                             cudaStreamSynchronize(stream),
                                             label + " " + fixture +
                                                 " synchronize");
        fixture_ready = fixture_ready && copy_all_outputs(fixture);
        fixture_ready = fixture_ready && test.cuda_ok(
                                             cudaStreamSynchronize(stream),
                                             label + " " + fixture +
                                                 " output-copy synchronize");
        if (!fixture_ready) {
          return false;
        }
        const std::size_t raw_mismatches =
            mismatch_count(baseline_raw_host, candidate_raw_host);
        const std::size_t residual_mismatches =
            mismatch_count(baseline_residual_host, candidate_residual_host);
        const std::size_t norm_mismatches =
            mismatch_count(baseline_norm_host, candidate_norm_host);
        const bool guards =
            guards_intact(baseline_raw_host, 0xa1a1U) &&
            guards_intact(baseline_residual_host, 0xb2b2U) &&
            guards_intact(baseline_norm_host, 0xc3c3U) &&
            guards_intact(candidate_raw_host, 0xd4d4U) &&
            guards_intact(candidate_residual_host, 0xe5e5U) &&
            guards_intact(candidate_norm_host, 0xf6f6U);
        const std::vector<std::uint16_t> first_candidate_raw =
            candidate_raw_host;
        const std::vector<std::uint16_t> first_candidate_residual =
            candidate_residual_host;
        const std::vector<std::uint16_t> first_candidate_norm =
            candidate_norm_host;
        fixture_ready = launch_candidate_graph_replay(fixture);
        fixture_ready = fixture_ready && copy_candidate_outputs(fixture);
        fixture_ready = fixture_ready && test.cuda_ok(
                                             cudaStreamSynchronize(stream),
                                             label + " " + fixture +
                                                 " replay-copy synchronize");
        if (!fixture_ready) {
          return false;
        }
        const std::size_t replay_mismatches =
            mismatch_count(first_candidate_raw, candidate_raw_host) +
            mismatch_count(first_candidate_residual, candidate_residual_host) +
            mismatch_count(first_candidate_norm, candidate_norm_host);
        const bool replay_guards =
            guards_intact(candidate_raw_host, 0xd4d4U) &&
            guards_intact(candidate_residual_host, 0xe5e5U) &&
            guards_intact(candidate_norm_host, 0xf6f6U);
        const bool input_gate = inputs_unchanged(
            actual_packed, actual_scales, activation_values, left_values,
            norm_values, fixture);
        const bool semantic_gate = semantic_check(
            baseline_residual_host, baseline_norm_host,
            candidate_residual_host, candidate_norm_host);
        const bool raw_contract_gate =
            dead_raw_candidate
                ? all_equal(first_candidate_raw, 0xd4d4U) &&
                      all_equal(candidate_raw_host, 0xd4d4U)
                : raw_mismatches == 0U;
        const bool fixture_gate =
            raw_contract_gate && residual_mismatches == 0U &&
            norm_mismatches == 0U && replay_mismatches == 0U && guards &&
            replay_guards && input_gate && semantic_gate;
        test.expect(fixture_gate,
                    label + " " + fixture +
                        " preserves bits/Graph replay/class/sign");
        std::cout << (dead_raw_candidate
                          ? "DECODE_DOWN_DEAD_RAW_NONFINITE: fixture="
                          : "DECODE_DOWN_CS_NONFINITE: fixture=")
                  << fixture
                  << " raw_mismatches=" << raw_mismatches << '/' << kRows
                  << " candidate_raw_untouched="
                  << (raw_contract_gate ? "true" : "false")
                  << " residual_mismatches=" << residual_mismatches << '/'
                  << kRows << " norm_mismatches=" << norm_mismatches << '/'
                  << kRows << " graph_replay_mismatches="
                  << replay_mismatches << '/' << 3U * kRows
                  << " class_sign=" << (semantic_gate ? "PASS" : "FAIL")
                  << " guards="
                  << (guards && replay_guards ? "intact" : "BAD")
                  << " inputs_preserved="
                  << (input_gate ? "true" : "false")
                  << " gate=" << (fixture_gate ? "PASS" : "FAIL")
                  << '\n';
        return fixture_gate;
      };

  std::vector<std::uint16_t> residual_nonfinite_left = host_left;
  residual_nonfinite_left[0U] = 0x7f80U;
  residual_nonfinite_left[1U] = 0xff80U;
  residual_nonfinite_left[2U] = 0x7fc1U;
  residual_nonfinite_left[3U] = 0xffc1U;
  const bool residual_nonfinite_gate = run_nonfinite_fixture(
      host_activation, residual_nonfinite_left, actual_norm_weight,
      "residual_signed_nonfinite",
      [&](const std::vector<std::uint16_t>& baseline_residual_bits,
          const std::vector<std::uint16_t>& baseline_norm_bits,
          const std::vector<std::uint16_t>& candidate_residual_bits,
          const std::vector<std::uint16_t>& candidate_norm_bits) {
        bool class_sign =
            guarded_at(baseline_residual_bits, 0U) == 0x7f80U &&
            guarded_at(candidate_residual_bits, 0U) == 0x7f80U &&
            guarded_at(baseline_residual_bits, 1U) == 0xff80U &&
            guarded_at(candidate_residual_bits, 1U) == 0xff80U;
        for (std::size_t index = 2U; index < 4U; ++index) {
          const std::uint16_t baseline_bits =
              guarded_at(baseline_residual_bits, index);
          const std::uint16_t candidate_bits =
              guarded_at(candidate_residual_bits, index);
          class_sign = class_sign && is_bf16_nan(baseline_bits) &&
                       is_bf16_nan(candidate_bits) &&
                       ((baseline_bits ^ candidate_bits) & 0x8000U) == 0U;
        }
        for (std::size_t index = 0U; index < kRows; ++index) {
          const std::uint16_t baseline_bits =
              guarded_at(baseline_norm_bits, index);
          const std::uint16_t candidate_bits =
              guarded_at(candidate_norm_bits, index);
          class_sign = class_sign && is_bf16_nan(baseline_bits) &&
                       is_bf16_nan(candidate_bits) &&
                       ((baseline_bits ^ candidate_bits) & 0x8000U) == 0U;
        }
        return class_sign;
      });

  std::array<std::size_t, 4U> norm_nonfinite_indices{};
  std::size_t norm_nonfinite_count = 0U;
  for (std::size_t index = 0U;
       index < kRows && norm_nonfinite_count < norm_nonfinite_indices.size();
       ++index) {
    const std::uint16_t bits =
        guarded_at(finite_actual_baseline_residual, index);
    if (is_bf16_finite(bits) && (bits & 0x7fffU) != 0U) {
      norm_nonfinite_indices[norm_nonfinite_count++] = index;
    }
  }
  bool norm_nonfinite_gate =
      norm_nonfinite_count == norm_nonfinite_indices.size();
  std::vector<std::uint16_t> norm_nonfinite_weight = actual_norm_weight;
  if (norm_nonfinite_gate) {
    norm_nonfinite_weight[norm_nonfinite_indices[0U]] = 0x7f80U;
    norm_nonfinite_weight[norm_nonfinite_indices[1U]] = 0xff80U;
    norm_nonfinite_weight[norm_nonfinite_indices[2U]] = 0x7fc1U;
    norm_nonfinite_weight[norm_nonfinite_indices[3U]] = 0xffc1U;
    norm_nonfinite_gate = run_nonfinite_fixture(
        host_activation, host_left, norm_nonfinite_weight,
        "norm_weight_signed_nonfinite",
        [&](const std::vector<std::uint16_t>& baseline_residual_bits,
            const std::vector<std::uint16_t>& baseline_norm_bits,
            const std::vector<std::uint16_t>& candidate_residual_bits,
            const std::vector<std::uint16_t>& candidate_norm_bits) {
          bool class_sign = true;
          for (std::size_t special = 0U; special < 4U; ++special) {
            const std::size_t index = norm_nonfinite_indices[special];
            const std::uint16_t baseline_residual_at_index =
                guarded_at(baseline_residual_bits, index);
            const std::uint16_t candidate_residual_at_index =
                guarded_at(candidate_residual_bits, index);
            const std::uint16_t baseline_bits =
                guarded_at(baseline_norm_bits, index);
            const std::uint16_t candidate_bits =
                guarded_at(candidate_norm_bits, index);
            class_sign =
                class_sign &&
                baseline_residual_at_index == candidate_residual_at_index &&
                ((baseline_bits ^ candidate_bits) & 0x8000U) == 0U;
            if (special < 2U) {
              class_sign = class_sign && !is_bf16_finite(baseline_bits) &&
                           !is_bf16_nan(baseline_bits) &&
                           !is_bf16_finite(candidate_bits) &&
                           !is_bf16_nan(candidate_bits);
              const bool residual_negative =
                  (baseline_residual_at_index & 0x8000U) != 0U;
              const bool expected_negative =
                  special == 0U ? residual_negative : !residual_negative;
              class_sign =
                  class_sign &&
                  (((baseline_bits & 0x8000U) != 0U) == expected_negative) &&
                  (((candidate_bits & 0x8000U) != 0U) == expected_negative);
            } else {
              class_sign = class_sign && is_bf16_nan(baseline_bits) &&
                           is_bf16_nan(candidate_bits);
            }
          }
          return class_sign;
        });
  }
  test.expect(norm_nonfinite_count == norm_nonfinite_indices.size(),
              label +
                  " selects finite nonzero residuals for norm-only fixture");
  bool dual_nan_bitwise_gate = true;
  if (dead_raw_candidate) {
    std::vector<std::uint16_t> dual_nan_activation = host_activation;
    std::vector<std::uint16_t> dual_nan_left = host_left;
    // Force the computed down value and residual_left to be distinct NaNs.
    // This is a dynamic bitwise diagnostic for the source/SASS operand-order
    // audit; the dynamic result alone does not prove instruction order.
    dual_nan_activation[0U] = 0x7fc5U;
    dual_nan_left[0U] = 0xffc1U;
    dual_nan_left[1U] = 0x7fc3U;
    dual_nan_left[2U] = 0xffc7U;
    dual_nan_left[3U] = 0x7fcbU;
    dual_nan_bitwise_gate = run_nonfinite_fixture(
        dual_nan_activation, dual_nan_left, actual_norm_weight,
        "dual_nan_raw_residual_bitwise_diagnostic",
        [&](const std::vector<std::uint16_t>& baseline_residual_bits,
            const std::vector<std::uint16_t>& baseline_norm_bits,
            const std::vector<std::uint16_t>& candidate_residual_bits,
            const std::vector<std::uint16_t>& candidate_norm_bits) {
          bool bitwise_parity = true;
          for (std::size_t index = 0U; index < 4U; ++index) {
            const std::uint16_t raw_bits =
                guarded_at(baseline_raw_host, index);
            const std::uint16_t baseline_bits =
                guarded_at(baseline_residual_bits, index);
            const std::uint16_t candidate_bits =
                guarded_at(candidate_residual_bits, index);
            bitwise_parity =
                bitwise_parity && is_bf16_nan(raw_bits) &&
                is_bf16_nan(dual_nan_left[index]) &&
                raw_bits != dual_nan_left[index] &&
                is_bf16_nan(baseline_bits) &&
                baseline_bits == candidate_bits;
          }
          for (std::size_t index = 0U; index < kRows; ++index) {
            bitwise_parity =
                bitwise_parity &&
                guarded_at(baseline_norm_bits, index) ==
                    guarded_at(candidate_norm_bits, index) &&
                is_bf16_nan(guarded_at(candidate_norm_bits, index));
          }
          return bitwise_parity;
        });
  }
  const bool nonfinite_gate =
      residual_nonfinite_gate && norm_nonfinite_gate &&
      dual_nan_bitwise_gate;
  test.expect(nonfinite_gate,
              label + " clears split signed Inf/NaN gate");

  const bool selection_gate =
      resource_gate && graph_gate && pinned_payload_gate &&
      fixture_gates[0U] && fixture_gates[1U] && absolute_delta_gate &&
      nonfinite_gate && invalid_gate;
  std::cout << (dead_raw_candidate
                    ? "PERF_DECODE_DOWN_DEAD_RAW_SELECTED:"
                    : "PERF_DECODE_DOWN_CS_SELECTED:")
            << " baseline="
            << (dead_raw_candidate ? "production_32x512"
                                   : "default_rollback_32x512")
            << " candidate="
            << (dead_raw_candidate ? "dead_raw_inline_residual_32x512"
                                   : "public_selected_cs_32x512")
            << " actual_paired_median_speedup="
            << fixture_paired_medians[0U]
            << " stress_paired_median_speedup="
            << fixture_paired_medians[1U]
            << " projected_64_layer_delta_ms="
            << projected_delta_milliseconds_per_token
            << " required_actual=1.005 required_stress=1"
            << " required_each_round="
            << (dead_raw_candidate ? ">1" : ">=1")
            << " required_projected_64_layer_delta_ms="
            << kRequiredProjectedDeltaMilliseconds
            << " graph_replay=PASS"
            << " nonfinite=" << (nonfinite_gate ? "PASS" : "FAIL")
            << " gate=" << (selection_gate ? "PASS" : "FAIL") << '\n';
  test.expect(selection_gate,
              label +
                  (dead_raw_candidate
                       ? " clears independent dead-raw inline-residual gate"
                       : " clears independent down .cs closeout gate"));
}

struct NvFp4Scale6HostSidecar {
  std::vector<std::uint8_t> bytes;
  unsigned int base = 0U;
  std::uint8_t minimum = 0U;
  std::uint8_t maximum = 0U;
};

[[nodiscard]] bool pack_nvfp4_scale6_sidecar(
    const std::vector<std::uint8_t>& canonical_scales,
    const std::size_t rows, const std::size_t columns,
    NvFp4Scale6HostSidecar& packed) {
  constexpr std::size_t kColumnsPerTile = 512U;
  constexpr std::size_t kBytesPerTile = 96U;
  if (rows == 0U || columns == 0U || (rows % 4U) != 0U ||
      (columns % kColumnsPerTile) != 0U ||
      rows > std::numeric_limits<std::size_t>::max() / (columns / 16U) ||
      canonical_scales.size() != rows * (columns / 16U)) {
    return false;
  }
  const auto extrema =
      std::minmax_element(canonical_scales.begin(), canonical_scales.end());
  packed.minimum = *extrema.first;
  packed.maximum = *extrema.second;
  packed.base = std::min<unsigned int>(packed.minimum, 192U);
  if (static_cast<unsigned int>(packed.maximum) - packed.base > 63U) {
    return false;
  }
  const std::size_t row_quads = rows / 4U;
  const std::size_t tiles_per_row_quad = columns / kColumnsPerTile;
  if (row_quads > std::numeric_limits<std::size_t>::max() /
                      tiles_per_row_quad ||
      row_quads * tiles_per_row_quad >
          std::numeric_limits<std::size_t>::max() / kBytesPerTile) {
    return false;
  }
  packed.bytes.assign(row_quads * tiles_per_row_quad * kBytesPerTile, 0U);
  const std::size_t scale_columns = columns / 16U;
  for (std::size_t q = 0U; q < row_quads; ++q) {
    for (std::size_t tile = 0U; tile < tiles_per_row_quad; ++tile) {
      const std::size_t tile_byte =
          (q * tiles_per_row_quad + tile) * kBytesPerTile;
      for (std::size_t lane_pair = 0U; lane_pair < 16U; ++lane_pair) {
        for (std::size_t phase = 0U; phase < 2U; ++phase) {
          for (std::size_t row = 0U; row < 4U; ++row) {
            const std::size_t code = 8U * lane_pair + 4U * phase + row;
            const std::size_t canonical_column =
                32U * tile + lane_pair + 16U * phase;
            const std::uint8_t scale =
                canonical_scales[(4U * q + row) * scale_columns +
                                 canonical_column];
            const unsigned int delta =
                static_cast<unsigned int>(scale) - packed.base;
            const std::size_t first_bit = code * 6U;
            const std::size_t byte = tile_byte + first_bit / 8U;
            const unsigned int shift =
                static_cast<unsigned int>(first_bit % 8U);
            const unsigned int payload = delta << shift;
            packed.bytes[byte] |= static_cast<std::uint8_t>(payload);
            if (shift > 2U) {
              packed.bytes[byte + 1U] |=
                  static_cast<std::uint8_t>(payload >> 8U);
            }
          }
        }
      }
    }
  }
  return true;
}

[[nodiscard]] bool unpack_nvfp4_scale6_sidecar(
    const NvFp4Scale6HostSidecar& packed, const std::size_t rows,
    const std::size_t columns, std::vector<std::uint8_t>& canonical_scales) {
  constexpr std::size_t kColumnsPerTile = 512U;
  constexpr std::size_t kBytesPerTile = 96U;
  if (rows == 0U || columns == 0U || (rows % 4U) != 0U ||
      (columns % kColumnsPerTile) != 0U || packed.base > 192U) {
    return false;
  }
  const std::size_t row_quads = rows / 4U;
  const std::size_t tiles_per_row_quad = columns / kColumnsPerTile;
  if (packed.bytes.size() !=
      row_quads * tiles_per_row_quad * kBytesPerTile) {
    return false;
  }
  const std::size_t scale_columns = columns / 16U;
  canonical_scales.assign(rows * scale_columns, 0U);
  for (std::size_t q = 0U; q < row_quads; ++q) {
    for (std::size_t tile = 0U; tile < tiles_per_row_quad; ++tile) {
      const std::size_t tile_byte =
          (q * tiles_per_row_quad + tile) * kBytesPerTile;
      for (std::size_t lane_pair = 0U; lane_pair < 16U; ++lane_pair) {
        for (std::size_t phase = 0U; phase < 2U; ++phase) {
          for (std::size_t row = 0U; row < 4U; ++row) {
            const std::size_t code = 8U * lane_pair + 4U * phase + row;
            const std::size_t first_bit = code * 6U;
            const std::size_t byte = tile_byte + first_bit / 8U;
            const unsigned int shift =
                static_cast<unsigned int>(first_bit % 8U);
            unsigned int window = packed.bytes[byte];
            if (shift > 2U) {
              window |= static_cast<unsigned int>(packed.bytes[byte + 1U])
                        << 8U;
            }
            const unsigned int scale = packed.base + ((window >> shift) & 63U);
            if (scale > 255U) {
              return false;
            }
            const std::size_t canonical_column =
                32U * tile + lane_pair + 16U * phase;
            canonical_scales[(4U * q + row) * scale_columns +
                             canonical_column] =
                static_cast<std::uint8_t>(scale);
          }
        }
      }
    }
  }
  return true;
}

[[nodiscard]] std::string sha256_bytes(const void* const data,
                                       const std::size_t bytes) {
  return q3x::core::sha256(std::string_view(
                               reinterpret_cast<const char*>(data), bytes))
      .hex();
}

struct NvFp4Scale6CapturedGraph {
  cudaGraph_t graph = nullptr;
  cudaGraphExec_t executable = nullptr;
  std::size_t nodes = 0U;
  cudaKernelNodeParams parameters{};

  NvFp4Scale6CapturedGraph() = default;
  NvFp4Scale6CapturedGraph(const NvFp4Scale6CapturedGraph&) = delete;
  NvFp4Scale6CapturedGraph& operator=(const NvFp4Scale6CapturedGraph&) =
      delete;
  ~NvFp4Scale6CapturedGraph() {
    if (executable != nullptr) {
      (void)cudaGraphExecDestroy(executable);
    }
    if (graph != nullptr) {
      (void)cudaGraphDestroy(graph);
    }
  }
};

template <typename Launch>
[[nodiscard]] bool capture_nvfp4_scale6_graph(
    TestContext& test, cudaStream_t stream, const Launch& launch,
    const bool instantiate, const std::string& label,
    NvFp4Scale6CapturedGraph& captured) {
  bool ready = test.cuda_ok(
      cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal),
      label + " begin capture");
  if (ready) {
    ready = test.cuda_ok(static_cast<cudaError_t>(launch()),
                         label + " enqueue kernel") &&
            ready;
    ready = test.cuda_ok(cudaStreamEndCapture(stream, &captured.graph),
                         label + " end capture") &&
            ready;
  }
  ready = ready && captured.graph != nullptr &&
          test.cuda_ok(cudaGraphGetNodes(captured.graph, nullptr,
                                        &captured.nodes),
                       label + " count nodes");
  cudaGraphNode_t node = nullptr;
  std::size_t capacity = 1U;
  if (ready && captured.nodes == 1U) {
    ready = test.cuda_ok(cudaGraphGetNodes(captured.graph, &node, &capacity),
                         label + " get node") &&
            capacity == 1U;
  }
  cudaGraphNodeType type = cudaGraphNodeTypeEmpty;
  if (ready) {
    ready = test.cuda_ok(cudaGraphNodeGetType(node, &type),
                         label + " get node type") &&
            type == cudaGraphNodeTypeKernel &&
            test.cuda_ok(cudaGraphKernelNodeGetParams(
                             node, &captured.parameters),
                         label + " get kernel parameters");
  }
  if (ready && instantiate) {
    ready = test.cuda_ok(cudaGraphInstantiate(&captured.executable,
                                             captured.graph, nullptr,
                                             nullptr, 0U),
                         label + " instantiate");
  }
  return ready && captured.nodes == 1U &&
         (!instantiate || captured.executable != nullptr);
}

void run_optional_nvfp4_m1_scale6_sidecar_closeout(
    TestContext& test, cudaStream_t stream,
    DecodeProjectionPaletteV2ComponentResult* const joint_result = nullptr) {
  const bool joint_mode = joint_result != nullptr;
  if (!joint_mode && !decode_nvfp4_scale6_sidecar_performance_enabled()) {
    return;
  }
  constexpr std::size_t kGateRows = 17'408U;
  constexpr std::size_t kGateColumns = 5'120U;
  constexpr std::size_t kDownRows = 5'120U;
  constexpr std::size_t kDownColumns = 17'408U;
  constexpr std::size_t kPackedCount = kGateRows * kGateColumns / 2U;
  constexpr std::size_t kScaleCount = kGateRows * kGateColumns / 16U;
  constexpr std::size_t kSidecarBytes = 4'177'920U;
  constexpr std::size_t kSidecarGuardBytes = 32U;
  constexpr std::size_t kOutputGuardElements = 16U;
  constexpr int kWarmups = 10;
  constexpr int kIterations = 64;
  constexpr int kRounds = 5;
  constexpr float kEpsilon = 1.0e-6F;
  constexpr float kOriginalCombinedRequiredSavingMs = 0.5F;
  constexpr float kRequiredDownProjectedSavingMs = 0.25F;
  constexpr std::size_t kEligibleGateUpLayers = 64U;
  constexpr std::size_t kEligibleDownLayers = 53U;
  constexpr std::size_t kEligibleProjectionCount =
      2U * kEligibleGateUpLayers + kEligibleDownLayers;
  static_assert(kEligibleProjectionCount == 181U);
  constexpr std::uint64_t kCheckpointBytes = 9'965'652'512ULL;
  constexpr std::uint64_t kHeaderBytes = 126'504ULL;
  constexpr std::uint64_t kGateWeightOffset = 6'757'009'952ULL;
  constexpr std::uint64_t kUpWeightOffset = 6'801'574'432ULL;
  constexpr std::uint64_t kDownWeightOffset = 6'712'445'472ULL;
  constexpr std::uint64_t kGateScaleOffset = 3'606'039'072ULL;
  constexpr std::uint64_t kUpScaleOffset = 3'611'609'632ULL;
  constexpr std::uint64_t kDownScaleOffset = 3'600'468'512ULL;
  constexpr std::uint64_t kGateScale2Offset = 126'548ULL;
  constexpr std::uint64_t kUpScale2Offset = 126'556ULL;
  constexpr std::uint64_t kDownScale2Offset = 126'540ULL;
  // Layer-0 down is fused with the next layer's input RMSNorm weight.
  constexpr std::uint64_t kNextLayerInputNormOffset = 2'544'010'432ULL;
  constexpr std::string_view kGateWeightSha =
      "e9e2d70cef19e52d65a0f7917ea6d936c172809ed247b350443b4344297159d8";
  constexpr std::string_view kUpWeightSha =
      "e604b0b18206afe695a191ecf77a6aaf4dfbc0f7e93f1f9789d9b579aed6215f";
  constexpr std::string_view kDownWeightSha =
      "bc1b428661d3cf657a4d69ff8d7e482b8125ef0f323e6df29b153a22fa2b6daf";
  constexpr std::string_view kGateScaleSha =
      "6eeaaa3bf8605b1d85252e13e6c495f6cf1b06e7fee8f27ea6367abbbb8fde0e";
  constexpr std::string_view kUpScaleSha =
      "ba393d3f9d25a1f4decba80715c6079d27d9de1d059a038a2f3f3f0932870947";
  constexpr std::string_view kDownScaleSha =
      "7943b475b23f75886309e93bf673aacc22c699e19ff400ef85607ab1a4006019";
  constexpr std::string_view kNextLayerInputNormSha =
      "89b1d66c33ed1a46813b12d4ca0757fcdd01f1e6fb90d47a569f37e0603a193d";
  constexpr std::array<std::string_view, 3U> kActualSidecarSha{{
      "54905b291bdfb5e618a67db095f111e12dd0af382bfd39c68e1691a75de597af",
      "74a49f8da5f4b4bf2e5b98c9567777ea93ebaf1bcab3fa05afd4000a58d393e2",
      "250e205c06ad6bc4849e3a6ecafeee403bf5fb2bec116ebb301e0ae022144a45",
  }};
  constexpr std::string_view kStressSidecarSha =
      "8de5829214f72a3f8d9572f5b51e61cd2cfefc0a061b83ab511d3fbfbc4b51a9";
  const std::string label = "Decode NVFP4 six-bit block-scale sidecar";

  std::vector<std::uint8_t> micro_scales(4U * (512U / 16U));
  for (std::size_t pair = 0U; pair < 16U; ++pair) {
    for (std::size_t phase = 0U; phase < 2U; ++phase) {
      for (std::size_t row = 0U; row < 4U; ++row) {
        const std::size_t code = 8U * pair + 4U * phase + row;
        micro_scales[row * 32U + pair + 16U * phase] =
            static_cast<std::uint8_t>(64U + (code & 63U));
      }
    }
  }
  NvFp4Scale6HostSidecar micro_sidecar;
  std::vector<std::uint8_t> micro_unpacked;
  NvFp4Scale6HostSidecar micro_repacked;
  std::vector<std::uint8_t> invalid_span = micro_scales;
  invalid_span[0U] = 32U;
  invalid_span[1U] = 96U;
  NvFp4Scale6HostSidecar rejected_sidecar;
  const bool micro_gate =
      pack_nvfp4_scale6_sidecar(micro_scales, 4U, 512U, micro_sidecar) &&
      micro_sidecar.base == 64U && micro_sidecar.bytes.size() == 96U &&
      sha256_bytes(micro_sidecar.bytes.data(), micro_sidecar.bytes.size()) ==
          "042fcd619223958a55d9b166e293ee991b073364f282010888fc15ed30faa880" &&
      unpack_nvfp4_scale6_sidecar(micro_sidecar, 4U, 512U,
                                  micro_unpacked) &&
      micro_unpacked == micro_scales &&
      pack_nvfp4_scale6_sidecar(micro_unpacked, 4U, 512U,
                                micro_repacked) &&
      micro_repacked.base == micro_sidecar.base &&
      micro_repacked.bytes == micro_sidecar.bytes &&
      !pack_nvfp4_scale6_sidecar(invalid_span, 4U, 512U,
                                 rejected_sidecar);
  test.expect(micro_gate,
              label + " host pack/unpack covers all 64 deltas exactly");
  if (!micro_gate) {
    return;
  }

  const char* const checkpoint_value =
      std::getenv("Q3X_NVFP4_6BIT_ACTUAL_CHECKPOINT_FILE");
  if (checkpoint_value == nullptr || checkpoint_value[0] == '\0') {
    test.expect(false, label + " requires actual checkpoint shard");
    std::cout << "DECODE_SCALE6_CHECKPOINT: source=missing"
                 " required_env=Q3X_NVFP4_6BIT_ACTUAL_CHECKPOINT_FILE"
                 " gate=FAIL\n";
    return;
  }
  std::ifstream checkpoint(checkpoint_value, std::ios::binary);
  checkpoint.seekg(0, std::ios::end);
  const std::streamoff checkpoint_size = checkpoint.tellg();
  bool ready = checkpoint.is_open() && checkpoint_size >= 0 &&
               static_cast<std::uint64_t>(checkpoint_size) == kCheckpointBytes;
  test.expect(ready, label + " opens and pins checkpoint shard size");
  const auto read_slice = [&](const std::uint64_t offset, void* destination,
                              const std::size_t bytes,
                              const std::string& name) {
    const bool range = ready && offset <= kCheckpointBytes &&
                       bytes <= kCheckpointBytes - offset;
    test.expect(range, label + " contains " + name);
    if (!range) {
      return false;
    }
    checkpoint.clear();
    checkpoint.seekg(static_cast<std::streamoff>(offset), std::ios::beg);
    checkpoint.read(reinterpret_cast<char*>(destination),
                    static_cast<std::streamsize>(bytes));
    const bool complete =
        checkpoint.gcount() == static_cast<std::streamsize>(bytes);
    test.expect(complete, label + " reads " + name);
    return complete;
  };
  std::array<std::uint8_t, 8U> header{};
  std::array<std::vector<std::uint8_t>, 3U> actual_packed{{
      std::vector<std::uint8_t>(kPackedCount),
      std::vector<std::uint8_t>(kPackedCount),
      std::vector<std::uint8_t>(kPackedCount),
  }};
  std::array<std::vector<std::uint8_t>, 3U> actual_scales{{
      std::vector<std::uint8_t>(kScaleCount),
      std::vector<std::uint8_t>(kScaleCount),
      std::vector<std::uint8_t>(kScaleCount),
  }};
  std::vector<std::uint16_t> down_norm(kDownRows);
  std::array<std::array<std::uint8_t, 4U>, 3U> scale2_bytes{};
  ready = read_slice(0U, header.data(), header.size(), "header length") &&
          read_slice(kGateWeightOffset, actual_packed[0U].data(), kPackedCount,
                     "gate weight") &&
          read_slice(kUpWeightOffset, actual_packed[1U].data(), kPackedCount,
                     "up weight") &&
          read_slice(kDownWeightOffset, actual_packed[2U].data(), kPackedCount,
                     "down weight") &&
          read_slice(kGateScaleOffset, actual_scales[0U].data(), kScaleCount,
                     "gate scales") &&
          read_slice(kUpScaleOffset, actual_scales[1U].data(), kScaleCount,
                     "up scales") &&
          read_slice(kDownScaleOffset, actual_scales[2U].data(), kScaleCount,
                     "down scales") &&
          read_slice(kGateScale2Offset, scale2_bytes[0U].data(), 4U,
                     "gate scale2") &&
          read_slice(kUpScale2Offset, scale2_bytes[1U].data(), 4U,
                     "up scale2") &&
          read_slice(kDownScale2Offset, scale2_bytes[2U].data(), 4U,
                     "down scale2") &&
          read_slice(kNextLayerInputNormOffset, down_norm.data(),
                     down_norm.size() * sizeof(std::uint16_t), "down norm");
  std::uint64_t decoded_header = 0U;
  for (std::size_t i = 0U; i < header.size(); ++i) {
    decoded_header |= static_cast<std::uint64_t>(header[i]) << (8U * i);
  }
  std::array<float, 3U> scale2{};
  std::array<std::uint32_t, 3U> scale2_bits{};
  for (std::size_t i = 0U; i < scale2.size(); ++i) {
    scale2_bits[i] = static_cast<std::uint32_t>(scale2_bytes[i][0U]) |
                     (static_cast<std::uint32_t>(scale2_bytes[i][1U]) << 8U) |
                     (static_cast<std::uint32_t>(scale2_bytes[i][2U]) << 16U) |
                     (static_cast<std::uint32_t>(scale2_bytes[i][3U]) << 24U);
    std::memcpy(&scale2[i], &scale2_bits[i], sizeof(float));
  }
  const bool payload_gate =
      ready && decoded_header == kHeaderBytes &&
      sha256_bytes(actual_packed[0U].data(), kPackedCount) == kGateWeightSha &&
      sha256_bytes(actual_packed[1U].data(), kPackedCount) == kUpWeightSha &&
      sha256_bytes(actual_packed[2U].data(), kPackedCount) == kDownWeightSha &&
      sha256_bytes(actual_scales[0U].data(), kScaleCount) == kGateScaleSha &&
      sha256_bytes(actual_scales[1U].data(), kScaleCount) == kUpScaleSha &&
      sha256_bytes(actual_scales[2U].data(), kScaleCount) == kDownScaleSha &&
