        ((i * 5U + (i >> 3U) * 3U + 1U) & 15U) |
        (((i * 7U + (i >> 2U) * 5U + 9U) & 15U) << 4U));
    stress_packed[1U][i] = static_cast<std::uint8_t>(
        ((i * 11U + (i >> 4U) * 7U + 3U) & 15U) |
