  };
  const std::array<std::size_t, kOutputCount> output_counts{{
      kGateColumns, kGateRows, kGateRows, kGateColumns, kGateRows, kGateRows,
      kDownRows, kDownRows, kDownRows, kDownRows, kDownRows, kDownRows,
  }};
  constexpr std::array<int, kOutputCount> kOutputPoison{{
      0x11, 0x22, 0x33, 0x44, 0x55, 0x66,
      0x77, 0x88, 0x99, 0xaa, 0xbb, 0xcc,
  }};
  std::array<DeviceBuffer<std::uint16_t>, kOutputCount> outputs;
  for (std::size_t i = 0U; i < outputs.size(); ++i) {
    ready = ready && test.cuda_ok(
                         outputs[i].allocate(output_counts[i] +
                                             2U * kOutputGuardElements),
                         label + " allocate guarded output " +
                             std::to_string(i));
  }
  if (!ready) {
    return;
  }
  const auto output = [&](const std::size_t index) {
    return outputs[index].get() + kOutputGuardElements;
  };
  const auto sidecar = [&](const std::size_t index) {
    return device_sidecar_storage[index].get() + kSidecarGuardBytes;
  };

  std::vector<std::uint16_t> host_gate_left(kGateColumns);
  std::vector<std::uint16_t> host_gate_right(kGateColumns);
  std::vector<std::uint16_t> host_gate_norm(kGateColumns);
  std::vector<std::uint16_t> host_down_activation(kDownColumns);
  std::vector<std::uint16_t> host_down_left(kDownRows);
  for (std::size_t i = 0U; i < kGateColumns; ++i) {
    host_gate_left[i] = encode_bf16(
        static_cast<float>(static_cast<int>((i * 31U + 3U) % 257U) - 128) /
        256.0F);
    host_gate_right[i] = encode_bf16(
        static_cast<float>(static_cast<int>((i * 17U + 19U) % 241U) - 120) /
        384.0F);
    host_gate_norm[i] = encode_bf16(
        static_cast<float>(static_cast<int>((i * 11U + 23U) % 97U) - 48) /
        512.0F);
  }
  for (std::size_t i = 0U; i < kDownColumns; ++i) {
    host_down_activation[i] = encode_bf16(
        static_cast<float>(static_cast<int>((i * 19U + 11U) % 127U) - 63) /
        256.0F);
  }
  for (std::size_t i = 0U; i < kDownRows; ++i) {
    host_down_left[i] = encode_bf16(
        static_cast<float>(static_cast<int>((i * 23U + 3U) % 257U) - 128) /
        128.0F);
  }
  ready = test.cuda_ok(cudaMemcpyAsync(
                           gate_left.get(), host_gate_left.data(),
                           kGateColumns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " upload gate left") &&
          test.cuda_ok(cudaMemcpyAsync(
                           gate_right.get(), host_gate_right.data(),
                           kGateColumns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " upload gate right") &&
          test.cuda_ok(cudaMemcpyAsync(
                           gate_norm.get(), host_gate_norm.data(),
                           kGateColumns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " upload gate norm") &&
          test.cuda_ok(cudaMemcpyAsync(
                           down_activation.get(), host_down_activation.data(),
                           kDownColumns * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " upload down activation") &&
          test.cuda_ok(cudaMemcpyAsync(
                           down_left.get(), host_down_left.data(),
                           kDownRows * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " upload down left") &&
          test.cuda_ok(cudaMemcpyAsync(
                           device_down_norm.get(), down_norm.data(),
                           kDownRows * sizeof(std::uint16_t),
                           cudaMemcpyHostToDevice, stream),
                       label + " upload down norm") &&
          test.cuda_ok(cudaStreamSynchronize(stream),
                       label + " input upload synchronize");
  if (!ready) {
    return;
  }

  const auto launch_gate_public_to = [&](const std::size_t residual,
                                         const std::size_t gate,
                                         const std::size_t workspace) noexcept {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_dead_up_bf16_cuda(
            device_packed[0U].get(), device_scales[0U].get(), scale2[0U],
            device_packed[1U].get(), device_scales[1U].get(), scale2[1U],
            gate_left.get(), gate_right.get(), gate_norm.get(), kEpsilon,
            kGateRows, kGateColumns, output(residual), output(gate),
            output(workspace), static_cast<void*>(stream));
  };
  const auto launch_gate_scale6_to = [&](const std::size_t residual,
                                         const std::size_t gate,
                                         const std::size_t workspace) noexcept {
    return q3x::kernels::
        launch_sm87_nvfp4_w4a16_residual_norm_gate_up_silu_dead_up_scale6_test_cuda(
            device_packed[0U].get(), sidecar(0U), expected_bases[0U],
            scale2[0U], device_packed[1U].get(), sidecar(1U),
            expected_bases[1U], scale2[1U], gate_left.get(), gate_right.get(),
            gate_norm.get(), kEpsilon, kGateRows, kGateColumns,
            output(residual), output(gate), output(workspace),
            static_cast<void*>(stream));
  };
  const auto launch_down_public_to = [&](const std::size_t raw,
                                         const std::size_t residual,
                                         const std::size_t norm) noexcept {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_down_residual_norm_bf16_cuda(
        device_packed[2U].get(), device_scales[2U].get(), scale2[2U],
        down_activation.get(), down_left.get(), device_down_norm.get(),
        kEpsilon, kDownRows, kDownColumns, output(raw), output(residual),
        output(norm), static_cast<void*>(stream));
  };
  const auto launch_down_scale6_to = [&](const std::size_t raw,
                                         const std::size_t residual,
                                         const std::size_t norm) noexcept {
    return q3x::kernels::launch_sm87_nvfp4_w4a16_down_residual_norm_scale6_test_cuda(
        device_packed[2U].get(), sidecar(2U), expected_bases[2U], scale2[2U],
        down_activation.get(), down_left.get(), device_down_norm.get(),
        kEpsilon, kDownRows, kDownColumns, output(raw), output(residual),
        output(norm), static_cast<void*>(stream));
  };
  const auto launch_gate_public = [&]() noexcept {
    return launch_gate_public_to(kGateScale6Residual, kGateScale6Output,
                                 kGateScale6Workspace);
  };
  const auto launch_gate_scale6 = [&]() noexcept {
    return launch_gate_scale6_to(kGateScale6Residual, kGateScale6Output,
                                 kGateScale6Workspace);
  };
  const auto launch_down_public = [&]() noexcept {
    return launch_down_public_to(kDownScale6Raw, kDownScale6Residual,
                                 kDownScale6Norm);
  };
  const auto launch_down_scale6 = [&]() noexcept {
    return launch_down_scale6_to(kDownScale6Raw, kDownScale6Residual,
                                 kDownScale6Norm);
  };
  NvFp4Scale6CapturedGraph gate_replay;
  NvFp4Scale6CapturedGraph down_replay;
  const bool replay_graph_gate =
      capture_nvfp4_scale6_graph(test, stream, launch_gate_scale6, true,
                                 label + " gate replay", gate_replay) &&
      capture_nvfp4_scale6_graph(test, stream, launch_down_scale6, true,
                                 label + " down replay", down_replay);
  test.expect(replay_graph_gate, label + " instantiates candidate Graphs");
  if (!replay_graph_gate) {
    return;
  }

  struct Fixture {
    const char* name;
    const std::array<std::vector<std::uint8_t>, 3U>* packed;
    const std::array<std::vector<std::uint8_t>, 3U>* scales;
    const std::array<NvFp4Scale6HostSidecar, 3U>* sidecars;
  };
  const std::array<Fixture, 2U> fixtures{{
      {"actual_checkpoint", &actual_packed, &actual_scales, &actual_sidecars},
      {"valid_same_bank_stress", &stress_packed, &stress_scales,
       &stress_sidecars},
  }};
  struct Timing {
    bool gate = false;
    bool every_round_strictly_improves = false;
    std::array<float, kDecodeProjectionPaletteV2Rounds> round_speedups{};
    std::array<float, kDecodeProjectionPaletteV2Rounds> round_deltas_ms{};
    float median_speedup = 0.0F;
    float median_delta_ms = 0.0F;
  };
  std::array<std::array<Timing, 2U>, 2U> timings{};
  std::array<bool, 2U> gate_exploration_correctness{};
  std::array<bool, 2U> down_correctness{};
  std::vector<std::uint16_t> finite_actual_public_down_residual;
  const auto benchmark = [&](const std::string& route, const auto& baseline,
                             const auto& candidate) {
    Timing result;
    bool ok = true;
    for (int i = 0; i < kWarmups && ok; ++i) {
      ok = test.cuda_ok(static_cast<cudaError_t>(baseline()),
                        label + " " + route + " baseline warmup") &&
           test.cuda_ok(static_cast<cudaError_t>(candidate()),
                        label + " " + route + " candidate warmup");
    }
    ok = ok && test.cuda_ok(cudaStreamSynchronize(stream),
                            label + " " + route + " warmup sync");
    const float prime_b1 = measure_small_m_tile(
        test, stream, baseline, kIterations, label + " " + route + " prime B1");
    const float prime_c1 = measure_small_m_tile(
        test, stream, candidate, kIterations, label + " " + route + " prime C1");
    const float prime_c2 = measure_small_m_tile(
        test, stream, candidate, kIterations, label + " " + route + " prime C2");
    const float prime_b2 = measure_small_m_tile(
        test, stream, baseline, kIterations, label + " " + route + " prime B2");
    ok = ok && std::isfinite(prime_b1) && std::isfinite(prime_c1) &&
         std::isfinite(prime_c2) && std::isfinite(prime_b2);
    std::array<float, kRounds> speedups{};
    std::array<float, kRounds> deltas{};
    static_assert(static_cast<std::size_t>(kRounds) ==
                  kDecodeProjectionPaletteV2Rounds);
    bool every_round = ok;
    bool every_round_strictly_improves = ok;
    for (int round = 0; round < kRounds; ++round) {
      float b1 = 0.0F, b2 = 0.0F, c1 = 0.0F, c2 = 0.0F;
      const bool baseline_outer = (round % 2) == 0;
      const auto measure = [&](const auto& launch, const std::string& pass) {
        return measure_small_m_tile(test, stream, launch, kIterations,
                                    label + " " + route + " " + pass);
      };
      if (baseline_outer) {
        b1 = measure(baseline, "B1"); c1 = measure(candidate, "C1");
        c2 = measure(candidate, "C2"); b2 = measure(baseline, "B2");
      } else {
        c1 = measure(candidate, "C1"); b1 = measure(baseline, "B1");
        b2 = measure(baseline, "B2"); c2 = measure(candidate, "C2");
      }
      speedups[round] = (b1 + b2) / (c1 + c2);
      deltas[round] = 0.5F * ((b1 + b2) - (c1 + c2));
      const bool round_gate = std::isfinite(speedups[round]) &&
                              std::isfinite(deltas[round]) &&
                              speedups[round] >= 1.0F;
      const bool round_strictly_improves =
          std::isfinite(speedups[round]) &&
          std::isfinite(deltas[round]) && speedups[round] > 1.0F;
      every_round = every_round && round_gate;
      every_round_strictly_improves =
          every_round_strictly_improves && round_strictly_improves;
      std::cout << "PERF_DECODE_SCALE6_ROUND: route=" << route
                << " round=" << round + 1 << " order="
                << (baseline_outer ? "B-C-C-B" : "C-B-B-C")
                << " b1_ms=" << b1 << " c1_ms=" << c1
                << " c2_ms=" << c2 << " b2_ms=" << b2
                << " speedup=" << speedups[round]
                << " delta_ms=" << deltas[round]
                << " gate=" << (round_gate ? "PASS" : "FAIL") << '\n';
      if (joint_mode && route.find("/down") != std::string::npos) {
        const bool actual_fixture =
            route.rfind("actual_checkpoint/", 0U) == 0U;
        std::cout
            << "PERF_DECODE_PROJECTION_PALETTE_V2_COMPONENT_ROUND:"
            << " component=down fixture="
            << (actual_fixture ? "actual" : "stress")
            << " round=" << round + 1
            << " order=" << (baseline_outer ? "B-C-C-B" : "C-B-B-C")
            << " baseline=canonical_public_cs"
            << " candidate=scale6"
            << " speedup=" << speedups[round]
            << " delta_ms_per_layer=" << deltas[round]
            << " direction="
            << (round_strictly_improves ? "IMPROVE" : "TIE_OR_REGRESS")
            << " required_speedup=strictly_gt_1"
            << " gate=" << (round_strictly_improves ? "PASS" : "FAIL")
            << '\n';
      }
    }
    result.round_speedups = speedups;
    result.round_deltas_ms = deltas;
    result.median_speedup = median_fp8_kv_pair_timing(speedups);
    result.median_delta_ms = median_fp8_kv_pair_timing(deltas);
    result.gate = every_round && result.median_speedup >= 1.0F;
    result.every_round_strictly_improves =
        every_round_strictly_improves;
    return result;
  };

  std::array<std::vector<std::uint16_t>, kOutputCount> observed_outputs;
  for (std::size_t i = 0U; i < observed_outputs.size(); ++i) {
    observed_outputs[i].resize(output_counts[i] + 2U * kOutputGuardElements);
  }
  std::vector<std::uint8_t> observed_down_packed(kPackedCount);
  std::vector<std::uint8_t> observed_down_scales(kScaleCount);
  std::vector<std::uint8_t> observed_down_sidecar(
      kSidecarBytes + 2U * kSidecarGuardBytes);
  std::vector<std::uint16_t> observed_down_activation(kDownColumns);
  std::vector<std::uint16_t> observed_down_left(kDownRows);
  std::vector<std::uint16_t> observed_down_norm(kDownRows);
  const auto copy_outputs = [&]() {
    bool ok = true;
    for (std::size_t i = 0U; i < outputs.size(); ++i) {
      ok = test.cuda_ok(cudaMemcpyAsync(
                            observed_outputs[i].data(), outputs[i].get(),
                            observed_outputs[i].size() * sizeof(std::uint16_t),
                            cudaMemcpyDeviceToHost, stream),
                        label + " copy output " + std::to_string(i)) &&
           ok;
    }
    return ok && test.cuda_ok(cudaStreamSynchronize(stream),
                              label + " output copy synchronize");
  };
  const auto poison_outputs = [&](const bool candidate_only) {
    bool ok = true;
    for (std::size_t i = 0U; i < outputs.size(); ++i) {
      const bool candidate = (i >= kGateScale6Residual &&
                              i <= kGateScale6Workspace) ||
                             i >= kDownScale6Raw;
      if (!candidate_only || candidate) {
        ok = test.cuda_ok(cudaMemsetAsync(
                              outputs[i].get(), kOutputPoison[i],
                              observed_outputs[i].size() *
                                  sizeof(std::uint16_t),
                              stream),
                          label + " poison output " + std::to_string(i)) &&
             ok;
      }
    }
    return ok;
  };
  const auto mismatch_count = [&](const std::size_t expected,
                                  const std::size_t actual) {
    std::size_t mismatches = 0U;
    for (std::size_t i = 0U; i < output_counts[expected]; ++i) {
      mismatches += observed_outputs[expected][kOutputGuardElements + i] !=
                    observed_outputs[actual][kOutputGuardElements + i];
    }
    return mismatches;
  };
  const auto guards_intact = [&](const std::size_t index) {
    const std::uint16_t canary = static_cast<std::uint16_t>(
        static_cast<unsigned int>(kOutputPoison[index]) * 0x0101U);
    for (std::size_t i = 0U; i < kOutputGuardElements; ++i) {
      if (observed_outputs[index][i] != canary ||
          observed_outputs[index][kOutputGuardElements +
                                  output_counts[index] + i] != canary) {
        return false;
      }
    }
    return true;
  };
  const auto guards_intact_in =
      [&](const std::size_t index,
          const std::array<std::vector<std::uint16_t>, kOutputCount>& values) {
        const std::uint16_t canary = static_cast<std::uint16_t>(
            static_cast<unsigned int>(kOutputPoison[index]) * 0x0101U);
        for (std::size_t i = 0U; i < kOutputGuardElements; ++i) {
          if (values[index][i] != canary ||
              values[index][kOutputGuardElements + output_counts[index] +
                            i] != canary) {
            return false;
          }
        }
        return true;
      };
  const auto down_inputs_unchanged =
      [&](const std::vector<std::uint8_t>& expected_packed,
          const std::vector<std::uint8_t>& expected_scales,
          const NvFp4Scale6HostSidecar& expected_sidecar,
          const std::vector<std::uint16_t>& expected_left,
          const std::vector<std::uint16_t>& expected_norm,
          const std::string& fixture_label) {
        bool ok = test.cuda_ok(
            cudaMemcpyAsync(observed_down_packed.data(),
                            device_packed[2U].get(), kPackedCount,
                            cudaMemcpyDeviceToHost, stream),
            label + " observe " + fixture_label + " down packed weight");
        ok = test.cuda_ok(
                 cudaMemcpyAsync(observed_down_scales.data(),
                                 device_scales[2U].get(), kScaleCount,
                                 cudaMemcpyDeviceToHost, stream),
                 label + " observe " + fixture_label +
                     " down canonical scale") &&
             ok;
        ok = test.cuda_ok(
                 cudaMemcpyAsync(observed_down_sidecar.data(),
                                 device_sidecar_storage[2U].get(),
                                 observed_down_sidecar.size(),
                                 cudaMemcpyDeviceToHost, stream),
                 label + " observe " + fixture_label +
                     " guarded down sidecar") &&
             ok;
        ok = test.cuda_ok(
                 cudaMemcpyAsync(observed_down_activation.data(),
                                 down_activation.get(),
                                 kDownColumns * sizeof(std::uint16_t),
                                 cudaMemcpyDeviceToHost, stream),
                 label + " observe " + fixture_label +
                     " down activation") &&
             ok;
        ok = test.cuda_ok(
                 cudaMemcpyAsync(observed_down_left.data(), down_left.get(),
                                 kDownRows * sizeof(std::uint16_t),
                                 cudaMemcpyDeviceToHost, stream),
                 label + " observe " + fixture_label +
                     " down residual input") &&
             ok;
        ok = test.cuda_ok(
                 cudaMemcpyAsync(observed_down_norm.data(),
                                 device_down_norm.get(),
                                 kDownRows * sizeof(std::uint16_t),
                                 cudaMemcpyDeviceToHost, stream),
                 label + " observe " + fixture_label +
                     " down norm weight") &&
             ok;
        ok = test.cuda_ok(cudaStreamSynchronize(stream),
                          label + " " + fixture_label +
                              " down input observation synchronize") &&
             ok;
        const std::uint8_t sidecar_canary = 0xd2U;
        const bool sidecar_unchanged =
            observed_down_sidecar.size() ==
                expected_sidecar.bytes.size() +
                    2U * kSidecarGuardBytes &&
            std::all_of(observed_down_sidecar.begin(),
                        observed_down_sidecar.begin() +
                            kSidecarGuardBytes,
                        [sidecar_canary](const std::uint8_t value) {
                          return value == sidecar_canary;
                        }) &&
            std::equal(expected_sidecar.bytes.begin(),
                       expected_sidecar.bytes.end(),
                       observed_down_sidecar.begin() +
                           kSidecarGuardBytes) &&
            std::all_of(observed_down_sidecar.end() -
                            kSidecarGuardBytes,
                        observed_down_sidecar.end(),
                        [sidecar_canary](const std::uint8_t value) {
                          return value == sidecar_canary;
                        });
        return ok && observed_down_packed == expected_packed &&
               observed_down_scales == expected_scales &&
               observed_down_activation == host_down_activation &&
               observed_down_left == expected_left &&
               observed_down_norm == expected_norm && sidecar_unchanged;
      };

  for (std::size_t fixture_index = 0U; fixture_index < fixtures.size();
       ++fixture_index) {
    const Fixture& fixture = fixtures[fixture_index];
    const std::string fixture_label = fixture.name;
    ready = true;
    for (std::size_t i = 0U; i < 3U; ++i) {
      ready = test.cuda_ok(cudaMemcpyAsync(
                               device_packed[i].get(),
                               (*fixture.packed)[i].data(), kPackedCount,
                               cudaMemcpyHostToDevice, stream),
                           label + " upload " + fixture_label + " packed") &&
              ready;
      ready = test.cuda_ok(cudaMemcpyAsync(
                               device_scales[i].get(),
                               (*fixture.scales)[i].data(), kScaleCount,
                               cudaMemcpyHostToDevice, stream),
                           label + " upload " + fixture_label + " scales") &&
              ready;
      ready = test.cuda_ok(cudaMemsetAsync(
                               device_sidecar_storage[i].get(), 0xd0 + i,
                               kSidecarBytes + 2U * kSidecarGuardBytes,
                               stream),
                           label + " poison " + fixture_label + " sidecar") &&
              ready;
      ready = test.cuda_ok(cudaMemcpyAsync(
                               sidecar(i),
                               (*fixture.sidecars)[i].bytes.data(),
                               kSidecarBytes, cudaMemcpyHostToDevice, stream),
                           label + " upload " + fixture_label + " sidecar") &&
              ready;
    }
    ready = ready && poison_outputs(false) &&
            test.cuda_ok(static_cast<cudaError_t>(launch_gate_public_to(
                             kGatePublicResidual, kGatePublicOutput,
                             kGatePublicWorkspace)),
                         label + " " + fixture_label + " gate public") &&
            test.cuda_ok(static_cast<cudaError_t>(launch_gate_scale6()),
                         label + " " + fixture_label + " gate scale6") &&
            test.cuda_ok(static_cast<cudaError_t>(launch_down_public_to(
                             kDownPublicRaw, kDownPublicResidual,
                             kDownPublicNorm)),
                         label + " " + fixture_label + " down public") &&
            test.cuda_ok(static_cast<cudaError_t>(launch_down_scale6()),
                         label + " " + fixture_label + " down scale6") &&
            test.cuda_ok(cudaStreamSynchronize(stream),
                         label + " " + fixture_label + " direct sync") &&
            copy_outputs();
    if (!ready) {
      return;
    }
    const std::size_t direct_gate_mismatches =
        mismatch_count(kGatePublicResidual, kGateScale6Residual) +
        mismatch_count(kGatePublicOutput, kGateScale6Output);
    const std::size_t direct_down_mismatches =
        mismatch_count(kDownPublicRaw, kDownScale6Raw) +
        mismatch_count(kDownPublicResidual, kDownScale6Residual) +
        mismatch_count(kDownPublicNorm, kDownScale6Norm);
    const auto direct_outputs = observed_outputs;
    ready = poison_outputs(true) &&
            test.cuda_ok(cudaGraphLaunch(gate_replay.executable, stream),
                         label + " " + fixture_label + " gate replay") &&
            test.cuda_ok(cudaGraphLaunch(down_replay.executable, stream),
                         label + " " + fixture_label + " down replay") &&
            copy_outputs();
    std::size_t gate_replay_mismatches = 0U;
    std::size_t down_replay_mismatches = 0U;
    bool gate_finite = true;
    bool down_finite = true;
    for (std::size_t i = 0U; i < outputs.size(); ++i) {
      const bool gate_candidate =
          i >= kGateScale6Residual && i < kDownPublicRaw &&
          i != kGateScale6Workspace;
      const bool down_candidate = i >= kDownScale6Raw;
      if (gate_candidate || down_candidate) {
        for (std::size_t j = 0U; j < output_counts[i]; ++j) {
          const std::size_t guarded = kOutputGuardElements + j;
          const bool mismatch = direct_outputs[i][guarded] !=
                                observed_outputs[i][guarded];
          if (gate_candidate) {
            gate_replay_mismatches += mismatch;
            gate_finite =
                gate_finite && is_bf16_finite(observed_outputs[i][guarded]);
          } else {
            down_replay_mismatches += mismatch;
            down_finite =
                down_finite && is_bf16_finite(observed_outputs[i][guarded]);
          }
        }
      }
    }
    bool direct_gate_guards = true;
    bool replay_gate_guards = true;
    for (std::size_t i = kGatePublicResidual; i < kDownPublicRaw; ++i) {
      direct_gate_guards = direct_gate_guards &&
                           guards_intact_in(i, direct_outputs);
      replay_gate_guards = replay_gate_guards && guards_intact(i);
    }
    bool direct_down_guards = true;
    bool replay_down_guards = true;
    for (std::size_t i = kDownPublicRaw; i < kOutputCount; ++i) {
      direct_down_guards = direct_down_guards &&
                           guards_intact_in(i, direct_outputs);
      replay_down_guards = replay_down_guards && guards_intact(i);
    }
    const auto workspace_untouched = [&](const std::size_t index,
                                         const auto& values) {
      const std::uint16_t canary = static_cast<std::uint16_t>(
          static_cast<unsigned int>(kOutputPoison[index]) * 0x0101U);
      return std::all_of(values[index].begin(), values[index].end(),
                         [canary](const std::uint16_t value) {
                           return value == canary;
                         });
    };
    const bool workspaces_untouched =
        workspace_untouched(kGatePublicWorkspace, direct_outputs) &&
        workspace_untouched(kGateScale6Workspace, direct_outputs) &&
        workspace_untouched(kGateScale6Workspace, observed_outputs);
    std::array<bool, 3U> sidecars_immutable{{ready, ready, ready}};
    for (std::size_t i = 0U; i < 3U; ++i) {
      std::vector<std::uint8_t> observed(kSidecarBytes +
                                         2U * kSidecarGuardBytes);
      sidecars_immutable[i] =
          test.cuda_ok(cudaMemcpy(observed.data(),
                                  device_sidecar_storage[i].get(),
                                  observed.size(), cudaMemcpyDeviceToHost),
                       label + " copy guarded sidecar " +
                           std::to_string(i)) &&
          sidecars_immutable[i];
      const std::uint8_t canary = static_cast<std::uint8_t>(0xd0U + i);
      sidecars_immutable[i] =
          sidecars_immutable[i] &&
          std::all_of(observed.begin(),
                      observed.begin() + kSidecarGuardBytes,
                      [canary](const std::uint8_t value) {
                        return value == canary;
                      }) &&
          std::equal((*fixture.sidecars)[i].bytes.begin(),
                     (*fixture.sidecars)[i].bytes.end(),
                     observed.begin() + kSidecarGuardBytes) &&
          std::all_of(observed.end() - kSidecarGuardBytes, observed.end(),
                      [canary](const std::uint8_t value) {
                        return value == canary;
                      });
    }
    const bool down_input_gate = down_inputs_unchanged(
        (*fixture.packed)[2U], (*fixture.scales)[2U],
        (*fixture.sidecars)[2U], host_down_left, down_norm, fixture_label);
    gate_exploration_correctness[fixture_index] =
        ready && direct_gate_mismatches == 0U &&
        gate_replay_mismatches == 0U && direct_gate_guards &&
        replay_gate_guards && gate_finite && workspaces_untouched &&
        sidecars_immutable[0U] && sidecars_immutable[1U];
    down_correctness[fixture_index] =
        ready && direct_down_mismatches == 0U &&
        down_replay_mismatches == 0U && direct_down_guards &&
        replay_down_guards && down_finite && sidecars_immutable[2U] &&
        down_input_gate;
    test.expect(down_correctness[fixture_index],
                label + " " + fixture_label +
                    " down bitwise/Graph/guards/input immutability");
    std::cout << "DECODE_SCALE6_DIFF: fixture=" << fixture_label
              << " gate_direct_mismatches=" << direct_gate_mismatches
              << " down_direct_mismatches=" << direct_down_mismatches
              << " gate_replay_mismatches=" << gate_replay_mismatches
              << " down_replay_mismatches=" << down_replay_mismatches
              << " gate_finite=" << (gate_finite ? "true" : "false")
              << " down_finite=" << (down_finite ? "true" : "false")
              << " down_guards="
              << (direct_down_guards && replay_down_guards ? "intact"
                                                           : "BAD")
              << " down_sidecar_immutable="
              << (sidecars_immutable[2U] ? "true" : "false")
              << " down_inputs_immutable="
              << (down_input_gate ? "true" : "false")
              << " dead_up_untouched="
              << (workspaces_untouched ? "true" : "false")
              << " gate_up_exploration_correctness="
              << (gate_exploration_correctness[fixture_index] ? "PASS"
                                                               : "FAIL")
              << " gate_up_disposition=REJECT"
              << " down_gate="
              << (down_correctness[fixture_index] ? "PASS" : "FAIL")
              << '\n';
    if (!down_correctness[fixture_index]) {
      return;
    }
    if (fixture_index == 0U) {
      finite_actual_public_down_residual =
          direct_outputs[kDownPublicResidual];
    }
    timings[fixture_index][0U] = benchmark(
        fixture_label + "/gate", launch_gate_public, launch_gate_scale6);
    timings[fixture_index][1U] = benchmark(
        fixture_label + "/down", launch_down_public, launch_down_scale6);
  }

  const auto guarded_down_at = [&](const std::vector<std::uint16_t>& values,
                                   const std::size_t index) {
    return values[kOutputGuardElements + index];
  };
  const auto run_down_nonfinite_fixture =
      [&](const std::vector<std::uint16_t>& left_values,
          const std::vector<std::uint16_t>& norm_values,
          const std::string& fixture_label, const auto& semantic_check) {
        bool fixture_ready = test.cuda_ok(
            cudaMemcpyAsync(device_packed[2U].get(),
                            actual_packed[2U].data(), kPackedCount,
                            cudaMemcpyHostToDevice, stream),
            label + " upload " + fixture_label + " actual down packed");
        fixture_ready =
            test.cuda_ok(cudaMemcpyAsync(
                             device_scales[2U].get(),
                             actual_scales[2U].data(), kScaleCount,
                             cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_label +
                             " actual down canonical scale") &&
            fixture_ready;
        fixture_ready =
            test.cuda_ok(cudaMemsetAsync(device_sidecar_storage[2U].get(),
                                        0xd2, observed_down_sidecar.size(),
                                        stream),
                         label + " poison " + fixture_label +
                             " guarded down sidecar") &&
            fixture_ready;
        fixture_ready =
            test.cuda_ok(cudaMemcpyAsync(sidecar(2U),
                                        actual_sidecars[2U].bytes.data(),
                                        kSidecarBytes,
                                        cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_label +
                             " actual down scale6 sidecar") &&
            fixture_ready;
        fixture_ready =
            test.cuda_ok(cudaMemcpyAsync(
                             down_activation.get(),
                             host_down_activation.data(),
                             kDownColumns * sizeof(std::uint16_t),
                             cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_label +
                             " down activation") &&
            fixture_ready;
        fixture_ready =
            test.cuda_ok(cudaMemcpyAsync(
                             down_left.get(), left_values.data(),
                             kDownRows * sizeof(std::uint16_t),
                             cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_label +
                             " down residual input") &&
            fixture_ready;
        fixture_ready =
            test.cuda_ok(cudaMemcpyAsync(
                             device_down_norm.get(), norm_values.data(),
                             kDownRows * sizeof(std::uint16_t),
                             cudaMemcpyHostToDevice, stream),
                         label + " upload " + fixture_label +
                             " down norm weight") &&
            fixture_ready;
        fixture_ready = fixture_ready && poison_outputs(false) &&
                        test.cuda_ok(
                            static_cast<cudaError_t>(launch_down_public_to(
                                kDownPublicRaw, kDownPublicResidual,
                                kDownPublicNorm)),
                            label + " launch " + fixture_label +
                                " public down") &&
                        test.cuda_ok(
                            static_cast<cudaError_t>(launch_down_scale6()),
                            label + " launch " + fixture_label +
                                " scale6 down") &&
                        copy_outputs();
        if (!fixture_ready) {
          return false;
        }
        const std::size_t raw_mismatches =
            mismatch_count(kDownPublicRaw, kDownScale6Raw);
        const std::size_t residual_mismatches =
            mismatch_count(kDownPublicResidual, kDownScale6Residual);
        const std::size_t norm_mismatches =
            mismatch_count(kDownPublicNorm, kDownScale6Norm);
        bool direct_guards = true;
        for (std::size_t i = kDownPublicRaw; i < kOutputCount; ++i) {
          direct_guards = direct_guards && guards_intact(i);
        }
        const auto direct_outputs = observed_outputs;
        fixture_ready = poison_outputs(true) &&
                        test.cuda_ok(cudaGraphLaunch(
                                         down_replay.executable, stream),
                                     label + " launch " + fixture_label +
                                         " scale6 down Graph replay") &&
                        copy_outputs();
        if (!fixture_ready) {
          return false;
        }
        std::size_t replay_mismatches = 0U;
        for (std::size_t i = kDownScale6Raw; i < kOutputCount; ++i) {
          for (std::size_t j = 0U; j < output_counts[i]; ++j) {
            const std::size_t guarded = kOutputGuardElements + j;
            replay_mismatches += direct_outputs[i][guarded] !=
                                 observed_outputs[i][guarded];
          }
        }
        bool replay_guards = true;
        for (std::size_t i = kDownPublicRaw; i < kOutputCount; ++i) {
          replay_guards = replay_guards && guards_intact(i);
        }
        const bool inputs_immutable = down_inputs_unchanged(
            actual_packed[2U], actual_scales[2U], actual_sidecars[2U],
            left_values, norm_values, fixture_label);
        const bool semantic_gate = semantic_check(
            direct_outputs[kDownPublicResidual],
            direct_outputs[kDownPublicNorm],
            direct_outputs[kDownScale6Residual],
            direct_outputs[kDownScale6Norm]);
        const bool fixture_gate =
            raw_mismatches == 0U && residual_mismatches == 0U &&
            norm_mismatches == 0U && replay_mismatches == 0U &&
            direct_guards && replay_guards && inputs_immutable &&
            semantic_gate;
        test.expect(fixture_gate,
                    label + " " + fixture_label +
                        " down preserves bits/Graph/class/sign/inputs");
        std::cout << "DECODE_SCALE6_DOWN_NONFINITE: fixture="
                  << fixture_label << " actual_scale_base=66"
                  << " raw_mismatches=" << raw_mismatches << '/'
                  << kDownRows << " residual_mismatches="
                  << residual_mismatches << '/' << kDownRows
                  << " norm_mismatches=" << norm_mismatches << '/'
                  << kDownRows << " graph_replay_mismatches="
                  << replay_mismatches << '/' << 3U * kDownRows
                  << " class_sign="
                  << (semantic_gate ? "PASS" : "FAIL")
                  << " guards="
                  << (direct_guards && replay_guards ? "intact" : "BAD")
                  << " inputs_immutable="
                  << (inputs_immutable ? "true" : "false")
                  << " gate=" << (fixture_gate ? "PASS" : "FAIL")
                  << '\n';
        return fixture_gate;
      };

  std::vector<std::uint16_t> residual_nonfinite_left = host_down_left;
  residual_nonfinite_left[0U] = 0x7f80U;
  residual_nonfinite_left[1U] = 0xff80U;
  residual_nonfinite_left[2U] = 0x7fc1U;
  residual_nonfinite_left[3U] = 0xffc1U;
  const bool residual_nonfinite_gate = run_down_nonfinite_fixture(
      residual_nonfinite_left, down_norm, "residual_signed_nonfinite",
      [&](const std::vector<std::uint16_t>& public_residual_bits,
          const std::vector<std::uint16_t>& public_norm_bits,
          const std::vector<std::uint16_t>& scale6_residual_bits,
          const std::vector<std::uint16_t>& scale6_norm_bits) {
        bool class_sign =
            guarded_down_at(public_residual_bits, 0U) == 0x7f80U &&
            guarded_down_at(scale6_residual_bits, 0U) == 0x7f80U &&
            guarded_down_at(public_residual_bits, 1U) == 0xff80U &&
            guarded_down_at(scale6_residual_bits, 1U) == 0xff80U;
        for (std::size_t index = 2U; index < 4U; ++index) {
          const std::uint16_t public_bits =
              guarded_down_at(public_residual_bits, index);
          const std::uint16_t scale6_bits =
              guarded_down_at(scale6_residual_bits, index);
          class_sign = class_sign && is_bf16_nan(public_bits) &&
                       is_bf16_nan(scale6_bits) &&
                       ((public_bits ^ scale6_bits) & 0x8000U) == 0U;
        }
        for (std::size_t index = 0U; index < kDownRows; ++index) {
          const std::uint16_t public_bits =
              guarded_down_at(public_norm_bits, index);
          const std::uint16_t scale6_bits =
              guarded_down_at(scale6_norm_bits, index);
          class_sign = class_sign && is_bf16_nan(public_bits) &&
                       is_bf16_nan(scale6_bits) &&
                       ((public_bits ^ scale6_bits) & 0x8000U) == 0U;
        }
        return class_sign;
      });

  std::array<std::size_t, 4U> norm_nonfinite_indices{};
  std::size_t norm_nonfinite_count = 0U;
  for (std::size_t index = 0U;
       index < kDownRows &&
       norm_nonfinite_count < norm_nonfinite_indices.size();
       ++index) {
    const std::uint16_t bits =
        guarded_down_at(finite_actual_public_down_residual, index);
    if (is_bf16_finite(bits) && (bits & 0x7fffU) != 0U) {
      norm_nonfinite_indices[norm_nonfinite_count++] = index;
    }
  }
  bool norm_nonfinite_gate =
      norm_nonfinite_count == norm_nonfinite_indices.size();
  std::vector<std::uint16_t> norm_nonfinite_weight = down_norm;
  if (norm_nonfinite_gate) {
    norm_nonfinite_weight[norm_nonfinite_indices[0U]] = 0x7f80U;
    norm_nonfinite_weight[norm_nonfinite_indices[1U]] = 0xff80U;
    norm_nonfinite_weight[norm_nonfinite_indices[2U]] = 0x7fc1U;
    norm_nonfinite_weight[norm_nonfinite_indices[3U]] = 0xffc1U;
    norm_nonfinite_gate = run_down_nonfinite_fixture(
        host_down_left, norm_nonfinite_weight,
        "norm_weight_signed_nonfinite",
        [&](const std::vector<std::uint16_t>& public_residual_bits,
            const std::vector<std::uint16_t>& public_norm_bits,
            const std::vector<std::uint16_t>& scale6_residual_bits,
            const std::vector<std::uint16_t>& scale6_norm_bits) {
          bool class_sign = true;
          for (std::size_t special = 0U; special < 4U; ++special) {
            const std::size_t index = norm_nonfinite_indices[special];
            const std::uint16_t public_residual_at_index =
                guarded_down_at(public_residual_bits, index);
            const std::uint16_t scale6_residual_at_index =
                guarded_down_at(scale6_residual_bits, index);
            const std::uint16_t public_bits =
                guarded_down_at(public_norm_bits, index);
            const std::uint16_t scale6_bits =
                guarded_down_at(scale6_norm_bits, index);
            class_sign =
                class_sign &&
                public_residual_at_index == scale6_residual_at_index &&
                ((public_bits ^ scale6_bits) & 0x8000U) == 0U;
            if (special < 2U) {
              class_sign = class_sign && !is_bf16_finite(public_bits) &&
                           !is_bf16_nan(public_bits) &&
                           !is_bf16_finite(scale6_bits) &&
                           !is_bf16_nan(scale6_bits);
              const bool residual_negative =
                  (public_residual_at_index & 0x8000U) != 0U;
              const bool expected_negative =
                  special == 0U ? residual_negative : !residual_negative;
              class_sign =
                  class_sign &&
                  (((public_bits & 0x8000U) != 0U) == expected_negative) &&
                  (((scale6_bits & 0x8000U) != 0U) == expected_negative);
            } else {
              class_sign = class_sign && is_bf16_nan(public_bits) &&
                           is_bf16_nan(scale6_bits);
            }
          }
          return class_sign;
        });
  }
  test.expect(norm_nonfinite_count == norm_nonfinite_indices.size(),
              label +
                  " selects finite nonzero actual residuals for norm fixture");
  const bool down_nonfinite_gate =
      residual_nonfinite_gate && norm_nonfinite_gate;
  test.expect(down_nonfinite_gate,
              label + " clears down scale6 signed Inf/NaN gate");

  if (joint_mode) {
    const Timing& actual_down = timings[0U][1U];
    const Timing& stress_down = timings[1U][1U];
    joint_result->completed = true;
    joint_result->correctness_gate =
        micro_gate && payload_gate && sidecar_gate && down_resource_gate &&
        graph_gate && down_invalid_gate && down_invalid_cases == 8U &&
        replay_graph_gate && down_correctness[0U] && down_correctness[1U] &&
        down_nonfinite_gate;
    joint_result->actual_every_round_strictly_improves =
        actual_down.every_round_strictly_improves;
    joint_result->stress_every_round_strictly_improves =
        stress_down.every_round_strictly_improves;
    joint_result->actual_speedups = actual_down.round_speedups;
    joint_result->actual_deltas_ms = actual_down.round_deltas_ms;
    joint_result->stress_speedups = stress_down.round_speedups;
    joint_result->stress_deltas_ms = stress_down.round_deltas_ms;
    joint_result->actual_median_speedup = actual_down.median_speedup;
    joint_result->actual_median_delta_ms = actual_down.median_delta_ms;
    joint_result->stress_median_speedup = stress_down.median_speedup;
    joint_result->stress_median_delta_ms = stress_down.median_delta_ms;
    joint_result->projected_delta_ms =
        static_cast<double>(kEligibleDownLayers) *
        static_cast<double>(actual_down.median_delta_ms);
    std::cout << "PERF_DECODE_PROJECTION_PALETTE_V2_COMPONENT:"
              << " component=down"
              << " baseline=canonical_public_cs"
              << " candidate=scale6"
              << " actual_median_speedup="
              << joint_result->actual_median_speedup
              << " stress_median_speedup="
              << joint_result->stress_median_speedup
              << " actual_delta_ms_per_layer="
              << joint_result->actual_median_delta_ms
              << " projected_53_layer_delta_ms="
              << joint_result->projected_delta_ms
              << " actual_every_round_strictly_gt_1="
              << (joint_result->actual_every_round_strictly_improves ? "true"
                                                                      : "false")
              << " stress_every_round_strictly_gt_1="
              << (joint_result->stress_every_round_strictly_improves ? "true"
                                                                      : "false")
              << " correctness="
              << (joint_result->correctness_gate ? "PASS" : "FAIL")
              << " isolated_absolute_gate=not_applied"
              << " gate=pending_joint_aggregation\n";
    return;
  }

  const float combined_projected_saving_ms =
      static_cast<float>(kEligibleGateUpLayers) *
          timings[0U][0U].median_delta_ms +
      static_cast<float>(kEligibleDownLayers) *
          timings[0U][1U].median_delta_ms;
  const bool every_route_fixture_round_nonregression =
      timings[0U][0U].gate && timings[0U][1U].gate &&
      timings[1U][0U].gate && timings[1U][1U].gate;
  const bool every_down_fixture_round_nonregression =
      timings[0U][1U].gate && timings[1U][1U].gate;
  const bool original_combined_gate =
      gate_exploration_correctness[0U] &&
      gate_exploration_correctness[1U] && down_correctness[0U] &&
      down_correctness[1U] && timings[0U][0U].gate &&
      timings[0U][1U].gate && timings[1U][0U].gate &&
      timings[1U][1U].gate && std::isfinite(combined_projected_saving_ms) &&
      combined_projected_saving_ms >= kOriginalCombinedRequiredSavingMs;
  std::cout << "PERF_DECODE_SCALE6_SELECTED: baseline=current_public_cs"
            << " candidate=test_only_scale6"
            << " actual_gate_speedup=" << timings[0U][0U].median_speedup
            << " actual_down_speedup=" << timings[0U][1U].median_speedup
            << " stress_gate_speedup=" << timings[1U][0U].median_speedup
            << " stress_down_speedup=" << timings[1U][1U].median_speedup
            << " projected_full_model_mixed_delta_ms="
            << combined_projected_saving_ms
            << " gate_up_layers=" << kEligibleGateUpLayers
            << " scale6_down_layers=" << kEligibleDownLayers
            << " canonical_down_fallback_layers="
            << 64U - kEligibleDownLayers
            << " required_projected_delta_ms="
            << kOriginalCombinedRequiredSavingMs
            << " every_route_fixture_round_nonregression="
            << (every_route_fixture_round_nonregression ? "true" : "false")
            << " timing_outputs=shared_candidate_buffers"
            << " pack_h2d_graph_setup=outside_cuda_events"
            << " measured_gate="
            << (original_combined_gate ? "PASS" : "FAIL")
            << " disposition=REJECT"
            << " gate=REJECT\n";

  const float down_projected_saving_ms =
      static_cast<float>(kEligibleDownLayers) *
      timings[0U][1U].median_delta_ms;
  const bool down_only_gate =
      down_correctness[0U] && down_correctness[1U] &&
      every_down_fixture_round_nonregression && down_nonfinite_gate &&
      std::isfinite(timings[0U][1U].median_speedup) &&
      timings[0U][1U].median_speedup >= 1.005F &&
      std::isfinite(timings[1U][1U].median_speedup) &&
      timings[1U][1U].median_speedup >= 1.0F &&
      std::isfinite(down_projected_saving_ms) &&
      down_projected_saving_ms >= kRequiredDownProjectedSavingMs;
  std::cout << "PERF_DECODE_SCALE6_DOWN_SELECTED:"
            << " baseline=current_public_cs"
            << " candidate=test_only_scale6_down"
            << " actual_median_speedup="
            << timings[0U][1U].median_speedup
            << " stress_median_speedup="
            << timings[1U][1U].median_speedup
            << " actual_delta_ms_per_layer="
            << timings[0U][1U].median_delta_ms
            << " projected_53_layer_delta_ms="
            << down_projected_saving_ms
            << " required_actual_median_speedup=1.005"
            << " required_stress_median_speedup=1"
            << " required_each_actual_stress_round=1"
            << " required_projected_53_layer_delta_ms="
            << kRequiredDownProjectedSavingMs
            << " every_down_fixture_round_nonregression="
            << (every_down_fixture_round_nonregression ? "true" : "false")
            << " signed_nonfinite="
            << (down_nonfinite_gate ? "PASS" : "FAIL")
            << " gate_up_disposition=REJECT"
            << " gate=" << (down_only_gate ? "PASS" : "FAIL") << '\n';
  test.expect(down_only_gate,
              label + " clears independent 53-layer down-only gate");
}

void finish_decode_projection_palette_v2_joint_gate(
    TestContext& test,
    const DecodeProjectionPaletteV2ComponentResult& qkv,
    const DecodeProjectionPaletteV2ComponentResult& down) {
  constexpr double kRequiredPerProcessArithmeticDeltaMs = 0.30;
  constexpr double kRequiredThreeProcessMedianArithmeticDeltaMs = 0.35;
  const bool completed_gate = qkv.completed && down.completed;
  const bool correctness_gate =
      completed_gate && qkv.correctness_gate && down.correctness_gate;
  const bool strict_round_direction_gate =
      completed_gate && qkv.actual_every_round_strictly_improves &&
      qkv.stress_every_round_strictly_improves &&
      down.actual_every_round_strictly_improves &&
      down.stress_every_round_strictly_improves;
  const double arithmetic_joint_delta_ms =
      qkv.projected_delta_ms + down.projected_delta_ms;
  const bool process_delta_gate =
      std::isfinite(qkv.projected_delta_ms) &&
      std::isfinite(down.projected_delta_ms) &&
      std::isfinite(arithmetic_joint_delta_ms) &&
      arithmetic_joint_delta_ms >= kRequiredPerProcessArithmeticDeltaMs;
  const bool joint_gate =
      correctness_gate && strict_round_direction_gate && process_delta_gate;
  test.expect(joint_gate,
              "Decode projection palette v2 clears same-process joint gate");
  std::cout << "PERF_DECODE_PROJECTION_PALETTE_V2_SELECTED:"
            << " process_scope=same_process"
            << " stream_scope=same_stream"
            << " measurement_order=qkv_then_down"
            << " qkv_projected_48_layer_delta_ms="
            << qkv.projected_delta_ms
            << " down_projected_53_layer_delta_ms="
            << down.projected_delta_ms
            << " arithmetic_joint_delta_ms=" << arithmetic_joint_delta_ms
            << " qkv_actual_rounds_strictly_gt_1="
            << (qkv.actual_every_round_strictly_improves ? "true" : "false")
            << " qkv_stress_rounds_strictly_gt_1="
            << (qkv.stress_every_round_strictly_improves ? "true" : "false")
            << " down_actual_rounds_strictly_gt_1="
            << (down.actual_every_round_strictly_improves ? "true" : "false")
            << " down_stress_rounds_strictly_gt_1="
            << (down.stress_every_round_strictly_improves ? "true" : "false")
            << " required_each_component_actual_stress_round_speedup="
               "strictly_gt_1"
            << " required_per_process_arithmetic_joint_delta_ms="
            << kRequiredPerProcessArithmeticDeltaMs
            << " required_three_process_median_arithmetic_joint_delta_ms="
            << kRequiredThreeProcessMedianArithmeticDeltaMs
            << " three_process_median_gate=pending_external_aggregation"
            << " isolated_qkv_absolute_gates=not_applied"
            << " isolated_down_absolute_gates=not_applied"
            << " component_correctness="
            << (correctness_gate ? "PASS" : "FAIL")
            << " arithmetic_projection_only=true"
            << " end_to_end_claim=none"
            << " gate=" << (joint_gate ? "PASS" : "FAIL") << '\n';
}

}  // namespace

int main() {
  TestContext test;
  test_launch_validation(test);

  int device_count = 0;
  const cudaError_t device_status = cudaGetDeviceCount(&device_count);
  if (device_status != cudaSuccess || device_count == 0) {
    std::cout << "SKIP: SM87 weight-only GEMV test (no CUDA device)\n";
    (void)cudaGetLastError();
    return test.failures() == 0 ? 77 : 1;
  }
  cudaDeviceProp properties{};
  if (!test.cuda_ok(cudaGetDeviceProperties(&properties, 0),
                    "read CUDA device properties")) {
    return 1;
  }
  if (properties.major != 8 || properties.minor != 7) {
    std::cout << "SKIP: SM87 weight-only GEMV test requires sm_87, found sm_"
              << properties.major << properties.minor << '\n';
    return test.failures() == 0 ? 77 : 1;
  }
  std::cout << "SM87 weight-only GEMV device: " << properties.name << '\n';

  cudaStream_t stream = nullptr;
  if (!test.cuda_ok(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking),
                    "create non-blocking stream")) {
    return 1;
  }
  if (decode_projection_palette_v2_performance_enabled()) {
    DecodeProjectionPaletteV2ComponentResult qkv_result;
    DecodeProjectionPaletteV2ComponentResult down_result;
    run_fp8_m1_qkv_z_bf16_ab_tail_composite_screen(test, stream, &qkv_result);
    run_optional_nvfp4_m1_scale6_sidecar_closeout(test, stream, &down_result);
    finish_decode_projection_palette_v2_joint_gate(test, qkv_result,
                                                    down_result);
    (void)test.cuda_ok(cudaStreamDestroy(stream),
                       "destroy Decode projection palette v2 joint stream");
    if (test.failures() != 0) {
      std::cerr << test.failures()
                << " Decode projection palette v2 joint assertion(s) failed\n";
      return 1;
    }
    std::cout << "Decode projection palette v2 joint screen passed\n";
    return 0;
  }
